/*
 * =====================================================================
 *  P020 HashMap: Complement Lookup   Canonical LC 1 | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 1, Two Sum)
 *   Return the indices of the two numbers in nums that add up to target. Exactly one
 *   answer exists and the same element may not be used twice. nums is NOT sorted.
 *
 * EXAMPLE
 *   [2, 7, 11, 15], target 9  ->  [0, 1]
 *   [3, 2, 4],      target 6  ->  [1, 2]
 *   [3, 3],         target 6  ->  [0, 1]     the trap: equal values, different indices
 *
 * RECOGNIZE WHEN
 *   - "find a pair (i, j) with a[i] + a[j] == t" (or difference, or product, or
 *     (a[i] + a[j]) % k == 0) on UNSORTED input, often returning indices.
 *   - "is there a duplicate within distance k".
 *   - Split a 4-way condition into two halves: pair sums of A and B vs pair sums of C and D.
 *   Not this if: the input is sorted and O(1) space matters -> P011_OppositeEndsSorted; you
 *   need a contiguous range with sum k -> P002_PrefixSumHashMap.
 *
 * TEMPLATE
 *   seen = {}                                 // value (or key derived from it) -> index / count
 *   for i, x in a:
 *       if need(x) in seen: found a pair (seen[need(x)], i)
 *       seen[x] = i                           // insert AFTER the lookup: no self-pairing
 *
 * APPROACH
 *   1. Walk once. For x, the partner it needs is target - x.
 *   2. If that partner was already seen, return both indices.
 *   3. Otherwise remember x -> its index.
 *
 * KEY INSIGHT
 *   Turn "search for a partner" (O(n) each) into "look up a partner" (O(1)) by storing what
 *   you have already passed. Looking up before inserting means an element can never pair
 *   with itself, yet [3, 3] still works because the first 3 is stored before the second.
 *
 * COMPLEXITY
 *   Time O(n), space O(n). LC 454: O(n^2) time and space instead of O(n^4).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 219  Contains Duplicate II    store last index; pair if i - last <= k
 *   [coded] LC 1010 Pairs Divisible by 60    key = x % 60; partner key = (60 - r) % 60;
 *                                            count pairs instead of returning one
 *   [coded] LC 454  4Sum II                  map of a + b sums; look up -(c + d)
 *           LC 1679 Max K-Sum Pairs          counts; consume one partner per match
 *           LC 532  K-diff Pairs             distinct pairs: count map, check x + k
 *           LC 2342 Max Pair Equal Digit Sum key = digit sum, keep the best value per key
 *           LC 1512 Number of Good Pairs     count[x] pairs added per new x
 *           LC 170  Two Sum III Design       add() stores counts; find() scans the keys
 *
 * PITFALLS
 *   - Insert after the lookup, or x pairs with itself when target == 2x.
 *   - Counting pairs: add the current count of the partner key, THEN increment your own.
 *   - LC 1010: remainder 0 pairs with remainder 0, not with 60.
 *
 * DEEP DIVE
 *   A02_TwoSum, C10_PairsOfSongsDivBy60 (05-Hashing-Prefix-Sum)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

class ComplementLookup {

    // Canonical LC 1.
    static int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            Integer j = seen.get(target - nums[i]);
            if (j != null) {
                return new int[]{j, i};
            }
            seen.put(nums[i], i);
        }
        return new int[0];
    }

    // LC 219: same value at two indices at most k apart.
    static boolean containsNearbyDuplicate(int[] nums, int k) {
        Map<Integer, Integer> last = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            Integer j = last.put(nums[i], i);     // put returns the previous index
            if (j != null && i - j <= k) {
                return true;
            }
        }
        return false;
    }

    // LC 1010: count pairs whose total duration is divisible by 60.
    static int numPairsDivisibleBy60(int[] time) {
        int[] count = new int[60];
        int pairs = 0;
        for (int t : time) {
            int r = t % 60;
            pairs += count[(60 - r) % 60];
            count[r]++;
        }
        return pairs;
    }

    // LC 454: count (i, j, k, l) with a[i] + b[j] + c[k] + d[l] == 0.
    static int fourSumCount(int[] a, int[] b, int[] c, int[] d) {
        Map<Integer, Integer> sums = new HashMap<>();
        for (int x : a) {
            for (int y : b) {
                sums.merge(x + y, 1, Integer::sum);
            }
        }
        int count = 0;
        for (int x : c) {
            for (int y : d) {
                count += sums.getOrDefault(-(x + y), 0);
            }
        }
        return count;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 1 [2,7,11,15] t=9",
                Arrays.toString(twoSum(new int[]{2, 7, 11, 15}, 9)), "[0, 1]");
        check("LC 1 [3,2,4] t=6", Arrays.toString(twoSum(new int[]{3, 2, 4}, 6)), "[1, 2]");
        check("LC 1 [3,3] t=6", Arrays.toString(twoSum(new int[]{3, 3}, 6)), "[0, 1]");

        check("LC 219 [1,2,3,1] k=3", containsNearbyDuplicate(new int[]{1, 2, 3, 1}, 3), true);
        check("LC 219 [1,0,1,1] k=1", containsNearbyDuplicate(new int[]{1, 0, 1, 1}, 1), true);
        check("LC 219 [1,2,3,1,2,3] k=2",
                containsNearbyDuplicate(new int[]{1, 2, 3, 1, 2, 3}, 2), false);

        check("LC 1010 [30,20,150,100,40]",
                numPairsDivisibleBy60(new int[]{30, 20, 150, 100, 40}), 3);
        check("LC 1010 [60,60,60]", numPairsDivisibleBy60(new int[]{60, 60, 60}), 3);

        check("LC 454 two ways",
                fourSumCount(new int[]{1, 2}, new int[]{-2, -1}, new int[]{-1, 2}, new int[]{0, 2}),
                2);
        check("LC 454 all zeros",
                fourSumCount(new int[]{0}, new int[]{0}, new int[]{0}, new int[]{0}), 1);
    }
}

/*
 * =====================================================================
 *  P021 HashMap: Frequency Count + Canonical Key   Canonical LC 49 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 49, Group Anagrams)
 *   Group the strings that are anagrams of each other. Any order of groups and of the
 *   strings inside a group is accepted.
 *
 * EXAMPLE
 *   ["eat","tea","tan","ate","nat","bat"]  ->  [[ate,eat,tea],[bat],[nat,tan]]
 *   [""]                                   ->  [[]]
 *
 * RECOGNIZE WHEN
 *   - "anagram", "same letters", "can be built from", "same pattern", "same shape".
 *   - Group items that are "equal up to" reordering, renaming or shifting.
 *   - You need counts of each value to compare two collections.
 *   Not this if: the comparison is over a sliding window of a longer string ->
 *   P016_FixedWindowFrequencyMatch; you need a pair, not a group -> P020_ComplementLookup.
 *
 * TEMPLATE
 *   groups = {}
 *   for item in items:
 *       key = canonical(item)        // sorted letters, 26 counts, shift diffs, first-seen ids
 *       groups[key].append(item)
 *   compare two collections: count[x]++ for one, count[x]-- for the other, all must be 0
 *
 * APPROACH
 *   1. Two words are anagrams iff their letter counts match.
 *   2. Build a key from the 26 counts (or the sorted letters) and group by it.
 *
 * KEY INSIGHT
 *   Define a function that maps every member of an equivalence class to the SAME value and
 *   different classes to different values; then a HashMap does the grouping. Pick the key
 *   for the relation: counts for anagrams, letter-to-letter differences for shifts, and
 *   "index of first occurrence" for one-to-one renaming (isomorphism).
 *
 * COMPLEXITY
 *   Time O(n * L) with a count key (O(n * L log L) with sorting), space O(n * L).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 242  Valid Anagram            +1 for s, -1 for t, all counts must be 0
 *   [coded] LC 383  Ransom Note              counts of magazine must cover the note
 *   [coded] LC 205  Isomorphic Strings       key = first-occurrence index of each char;
 *                                            "egg" and "add" both become 0,1,1
 *   [coded] LC 290  Word Pattern             the same key over letters vs over words
 *   [coded] LC 249  Group Shifted Strings    key = (c[i] - c[0] + 26) % 26 for every i
 *           LC 890  Find and Replace Pattern LC 205 key against each word
 *           LC 1657 Close Strings            same set of letters AND same sorted counts
 *           LC 387  First Unique Character   count first, then scan for count == 1
 *           LC 1207 Unique Occurrences       set of the counts has the same size as counts
 *           LC 451  Sort Characters by Frequency  counts + buckets -> P043_TopK
 *
 * PITFALLS
 *   - Isomorphism is a BIJECTION: one map a -> b is not enough ("badc" vs "baba").
 *   - A key built by joining counts needs a separator ("1#12" vs "11#2").
 *   - Shift keys wrap around: use (diff + 26) % 26.
 *
 * DEEP DIVE
 *   C05_GroupAnagrams, C06_GroupShiftedStrings, C07_FindAndReplacePattern, A03_RansomNote
 *   (05-Hashing-Prefix-Sum)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class FrequencyCanonicalKey {

    // Canonical LC 49. Key = the 26 letter counts.
    static List<List<String>> groupAnagrams(String[] strs) {
        Map<String, List<String>> groups = new HashMap<>();
        for (String s : strs) {
            int[] count = new int[26];
            for (char c : s.toCharArray()) {
                count[c - 'a']++;
            }
            groups.computeIfAbsent(Arrays.toString(count), k -> new ArrayList<>()).add(s);
        }
        return sorted(groups.values());
    }

    // LC 242.
    static boolean isAnagram(String s, String t) {
        if (s.length() != t.length()) {
            return false;
        }
        int[] count = new int[26];
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'a']++;
            count[t.charAt(i) - 'a']--;
        }
        for (int c : count) {
            if (c != 0) {
                return false;
            }
        }
        return true;
    }

    // LC 383: every letter of the note must be available in the magazine.
    static boolean canConstruct(String ransomNote, String magazine) {
        int[] count = new int[26];
        for (char c : magazine.toCharArray()) {
            count[c - 'a']++;
        }
        for (char c : ransomNote.toCharArray()) {
            if (--count[c - 'a'] < 0) {
                return false;
            }
        }
        return true;
    }

    // Canonical key for renaming: position i -> index where that symbol first appeared.
    static List<Integer> firstSeenKey(List<String> symbols) {
        Map<String, Integer> first = new HashMap<>();
        List<Integer> key = new ArrayList<>();
        for (String sym : symbols) {
            first.putIfAbsent(sym, first.size());
            key.add(first.get(sym));
        }
        return key;
    }

    // LC 205.
    static boolean isIsomorphic(String s, String t) {
        List<Integer> keyS = firstSeenKey(Arrays.asList(s.split("")));
        return keyS.equals(firstSeenKey(Arrays.asList(t.split(""))));
    }

    // LC 290: letters of the pattern vs words of s.
    static boolean wordPattern(String pattern, String s) {
        List<String> words = Arrays.asList(s.split(" "));
        List<String> letters = Arrays.asList(pattern.split(""));
        return letters.size() == words.size() && firstSeenKey(letters).equals(firstSeenKey(words));
    }

    // LC 249: key = differences to the first letter, mod 26.
    static List<List<String>> groupStrings(String[] strings) {
        Map<String, List<String>> groups = new HashMap<>();
        for (String s : strings) {
            StringBuilder key = new StringBuilder();
            for (int i = 1; i < s.length(); i++) {
                key.append((s.charAt(i) - s.charAt(0) + 26) % 26).append(',');
            }
            groups.computeIfAbsent(key.toString(), k -> new ArrayList<>()).add(s);
        }
        return sorted(groups.values());
    }

    // Groups in any order are accepted; sort for a stable printout.
    static List<List<String>> sorted(Iterable<List<String>> groups) {
        List<List<String>> out = new ArrayList<>();
        for (List<String> g : groups) {
            List<String> copy = new ArrayList<>(g);
            Collections.sort(copy);
            out.add(copy);
        }
        out.sort((a, b) -> a.toString().compareTo(b.toString()));
        return out;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 49 six words",
                groupAnagrams(new String[]{"eat", "tea", "tan", "ate", "nat", "bat"}),
                "[[ate, eat, tea], [bat], [nat, tan]]");
        check("LC 49 empty string", groupAnagrams(new String[]{""}), "[[]]");
        check("LC 49 single", groupAnagrams(new String[]{"a"}), "[[a]]");

        check("LC 242 anagram/nagaram", isAnagram("anagram", "nagaram"), true);
        check("LC 242 rat/car", isAnagram("rat", "car"), false);

        check("LC 383 a from b", canConstruct("a", "b"), false);
        check("LC 383 aa from ab", canConstruct("aa", "ab"), false);
        check("LC 383 aa from aab", canConstruct("aa", "aab"), true);

        check("LC 205 egg/add", isIsomorphic("egg", "add"), true);
        check("LC 205 foo/bar", isIsomorphic("foo", "bar"), false);
        check("LC 205 paper/title", isIsomorphic("paper", "title"), true);
        check("LC 205 badc/baba bijection trap", isIsomorphic("badc", "baba"), false);

        check("LC 290 abba / dog cat cat dog", wordPattern("abba", "dog cat cat dog"), true);
        check("LC 290 abba / dog cat cat fish", wordPattern("abba", "dog cat cat fish"), false);
        check("LC 290 abba / dog dog dog dog", wordPattern("abba", "dog dog dog dog"), false);
        check("LC 290 aaa / three words, different", wordPattern("aaa", "dog cat dog"), false);

        check("LC 249 eight strings",
                groupStrings(new String[]{"abc", "bcd", "acef", "xyz", "az", "ba", "a", "z"}),
                "[[a, z], [abc, bcd, xyz], [acef], [az, ba]]");
    }
}

/*
 * =====================================================================
 *  P022 HashSet: Existence and Run Detection   Canonical LC 128 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 128, Longest Consecutive Sequence)
 *   nums is unsorted. Return the length of the longest run of consecutive integers that
 *   all appear in nums (order in the array does not matter). Must run in O(n).
 *
 * EXAMPLE
 *   [100, 4, 200, 1, 3, 2]          ->  4     1, 2, 3, 4
 *   [0, 3, 7, 2, 5, 8, 4, 6, 0, 1]  ->  9     0..8
 *   []                              ->  0
 *
 * RECOGNIZE WHEN
 *   - O(1) "have I seen x?" checks: duplicates, membership, set difference.
 *   - "consecutive values" (not consecutive positions) with an O(n) requirement, so
 *     sorting (O(n log n)) is ruled out.
 *   - Chains where each element points to the next value (x -> x + 1, x -> x * x).
 *   Not this if: you need counts, not presence -> P021_FrequencyCanonicalKey; consecutive
 *   POSITIONS in the array -> a sliding window (P017_VariableWindowLongest).
 *
 * TEMPLATE
 *   set = all values
 *   for x in set:
 *       if prev(x) not in set:              // x starts a chain; only starts walk forward
 *           length = 1
 *           while next(x) in set: x = next(x); length++
 *           best = max(best, length)
 *
 * APPROACH
 *   1. Put every value in a HashSet (duplicates vanish).
 *   2. Only a value whose predecessor is missing starts a run; walk forward from it.
 *
 * KEY INSIGHT
 *   Starting the walk only at run starts means each value is visited at most twice (once
 *   in the outer loop, once inside one run), so the nested loop is still O(n) total.
 *   Without the "predecessor missing" check it degrades to O(n^2).
 *
 * COMPLEXITY
 *   Time O(n) expected, space O(n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 217  Contains Duplicate       set.add returns false on a repeat
 *   [coded] LC 2501 Longest Square Streak    next(x) = x * x; start where sqrt(x) is absent
 *           LC 1365 Smaller Than Current     counts per value + prefix over the value range
 *           LC 349  Intersection of Arrays   set of one, filter the other
 *           LC 2215 Difference of Two Arrays two sets, removeAll each way
 *           LC 41   First Missing Positive   O(1) space -> P005_CyclicSortIndexAsHash
 *
 * PITFALLS
 *   - Iterate over the SET, not the array: duplicates in the array would repeat walks.
 *   - LC 2501: x * x overflows int for large x; use long.
 *   - LC 2501: a streak needs at least 2 numbers; return -1 otherwise.
 *
 * DEEP DIVE
 *   D01_LongestConsecutiveSequence, A01_ContainsDuplicate (05-Hashing-Prefix-Sum)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.HashSet;
import java.util.Set;

class HashSetRunDetection {

    // Canonical LC 128.
    static int longestConsecutive(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int x : nums) {
            set.add(x);
        }
        int best = 0;
        for (int x : set) {
            if (!set.contains(x - 1)) {
                int length = 1;
                while (set.contains(x + length)) {
                    length++;
                }
                best = Math.max(best, length);
            }
        }
        return best;
    }

    // LC 217.
    static boolean containsDuplicate(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int x : nums) {
            if (!seen.add(x)) {
                return true;
            }
        }
        return false;
    }

    // LC 2501: longest chain x, x^2, x^4, ... (any order in the array); -1 if under 2.
    static int longestSquareStreak(int[] nums) {
        Set<Long> set = new HashSet<>();
        for (int x : nums) {
            set.add((long) x);
        }
        int best = 0;
        for (long x : set) {
            long root = (long) Math.sqrt(x);
            if (root * root == x && set.contains(root)) {
                continue;                          // not a chain start
            }
            int length = 1;
            long cur = x;
            while (cur <= 100_000 && set.contains(cur * cur)) {
                cur *= cur;
                length++;
            }
            best = Math.max(best, length);
        }
        return best >= 2 ? best : -1;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 128 [100,4,200,1,3,2]", longestConsecutive(new int[]{100, 4, 200, 1, 3, 2}), 4);
        check("LC 128 [0,3,7,2,5,8,4,6,0,1]",
                longestConsecutive(new int[]{0, 3, 7, 2, 5, 8, 4, 6, 0, 1}), 9);
        check("LC 128 empty", longestConsecutive(new int[]{}), 0);
        check("LC 128 duplicates [1,2,0,1]", longestConsecutive(new int[]{1, 2, 0, 1}), 3);

        check("LC 217 [1,2,3,1]", containsDuplicate(new int[]{1, 2, 3, 1}), true);
        check("LC 217 [1,2,3,4]", containsDuplicate(new int[]{1, 2, 3, 4}), false);

        check("LC 2501 [4,3,6,16,8,2]", longestSquareStreak(new int[]{4, 3, 6, 16, 8, 2}), 3);
        check("LC 2501 [2,3,5,6,7]", longestSquareStreak(new int[]{2, 3, 5, 6, 7}), -1);
        check("LC 2501 [2,4,16,256,65536]",
                longestSquareStreak(new int[]{2, 4, 16, 256, 65536}), 5);
    }
}

