/*
 * =====================================================================
 *  P031 Fast and Slow Pointers (Floyd)   Canonical LC 141 | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 141, Linked List Cycle)
 *   Return true if following next pointers from head ever revisits a node. O(1) memory.
 *
 * EXAMPLE
 *   3 -> 2 -> 0 -> -4 -> (back to 2)   ->  true
 *   1 -> 2 -> (back to 1)              ->  true
 *   1                                  ->  false
 *
 * RECOGNIZE WHEN
 *   - A linked list (or any "next" function: x -> f(x)) and the question is about a cycle,
 *     its start, or its length.
 *   - "middle of the list", "second half", "k-th from the middle" in one pass.
 *   - "find the duplicate in 1..n without modifying the array, O(1) space" (index -> value
 *     is a next pointer).
 *   Not this if: extra memory is fine -> a HashSet of visited nodes is simpler; you need the
 *   k-th node from the END -> P034_GapPointers.
 *
 * TEMPLATE
 *   slow = fast = head
 *   while fast and fast.next:
 *       slow = slow.next; fast = fast.next.next
 *       if slow == fast: cycle found                 // LC 141
 *   // cycle start (LC 142): reset one pointer to head; step both by 1; they meet at start
 *   // middle (LC 876): when fast stops, slow is the middle (second middle if even)
 *
 * APPROACH
 *   1. Move slow by one and fast by two.
 *   2. Without a cycle, fast falls off the end. With one, fast gains one step per round on
 *      slow inside the loop, so it must land on slow.
 *
 * KEY INSIGHT
 *   Relative speed 1 means the gap inside the cycle shrinks by exactly 1 each round, so
 *   the pointers cannot jump past each other. For the start: if the tail has length a, the
 *   meeting point is a steps (mod cycle length) before the start, which is why walking a
 *   steps from head and from the meeting point lands both on the start.
 *
 * COMPLEXITY
 *   Time O(n), space O(1).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 142  Cycle Start              after meeting, restart one pointer at head
 *   [coded] LC 876  Middle of the List       stop when fast can no longer jump twice
 *   [coded] LC 202  Happy Number             next(x) = sum of squared digits; cycle at 1?
 *   [coded] LC 287  Find the Duplicate       next(i) = nums[i]; the cycle start is the dup
 *           Cycle length                     after meeting, walk one pointer round once
 *           LC 2095 Delete the Middle Node   stop slow one node earlier (start fast ahead)
 *           LC 457  Circular Array Loop      Floyd per start, with direction checks
 *           LC 234 / LC 143                  middle + reverse -> P032_InPlaceReversal
 *
 * PITFALLS
 *   - Check fast != null AND fast.next != null before fast.next.next.
 *   - For the FIRST middle of an even list, start fast at head.next.
 *   - LC 287: start both at index 0 (value 0 never appears, so 0 is outside the cycle).
 *
 * DEEP DIVE
 *   C07_LinkedListLoopDetection, C08_LinkedListLoopLength, A03_FindMiddleOfLinkedList
 *   (06-Linked-List), B16_HappyNumber (17-Math-Bit-Manipulation),
 *   C15_FindDuplicate (01-Arrays)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
class FastSlowPointers {

    static class ListNode {
        int val;
        ListNode next;

        ListNode(int val) {
            this.val = val;
        }

        // Builds a list; if pos >= 0 the tail links back to the node at index pos.
        static ListNode withCycle(int pos, int... vals) {
            ListNode dummy = new ListNode(0);
            ListNode cur = dummy;
            ListNode loopTo = null;
            for (int i = 0; i < vals.length; i++) {
                cur.next = new ListNode(vals[i]);
                cur = cur.next;
                if (i == pos) {
                    loopTo = cur;
                }
            }
            cur.next = loopTo;
            return dummy.next;
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder("[");
            for (ListNode n = this; n != null; n = n.next) {
                sb.append(n.val).append(n.next == null ? "" : ", ");
            }
            return sb.append("]").toString();
        }
    }

    // Canonical LC 141.
    static boolean hasCycle(ListNode head) {
        ListNode slow = head;
        ListNode fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {
                return true;
            }
        }
        return false;
    }

    // LC 142: the node where the cycle begins, or null.
    static ListNode detectCycle(ListNode head) {
        ListNode slow = head;
        ListNode fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {
                ListNode p = head;
                while (p != slow) {
                    p = p.next;
                    slow = slow.next;
                }
                return p;
            }
        }
        return null;
    }

    // LC 876: second middle for even lengths.
    static ListNode middleNode(ListNode head) {
        ListNode slow = head;
        ListNode fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }

    // LC 202: the digit-square sequence either reaches 1 or cycles.
    static boolean isHappy(int n) {
        int slow = n;
        int fast = next(n);
        while (fast != 1 && slow != fast) {
            slow = next(slow);
            fast = next(next(fast));
        }
        return fast == 1;
    }

    private static int next(int n) {
        int sum = 0;
        while (n > 0) {
            int d = n % 10;
            sum += d * d;
            n /= 10;
        }
        return sum;
    }

    // LC 287: values in 1..n, n + 1 slots; i -> nums[i] is a list whose cycle starts at
    // the duplicated value.
    static int findDuplicate(int[] nums) {
        int slow = nums[0];
        int fast = nums[nums[0]];
        while (slow != fast) {
            slow = nums[slow];
            fast = nums[nums[fast]];
        }
        int p = 0;
        while (p != slow) {
            p = nums[p];
            slow = nums[slow];
        }
        return p;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 141 [3,2,0,-4] pos=1", hasCycle(ListNode.withCycle(1, 3, 2, 0, -4)), true);
        check("LC 141 [1,2] pos=0", hasCycle(ListNode.withCycle(0, 1, 2)), true);
        check("LC 141 [1] no cycle", hasCycle(ListNode.withCycle(-1, 1)), false);
        check("LC 141 empty list", hasCycle(null), false);

        check("LC 142 start value", detectCycle(ListNode.withCycle(1, 3, 2, 0, -4)).val, 2);
        check("LC 142 cycle at head", detectCycle(ListNode.withCycle(0, 1, 2)).val, 1);
        check("LC 142 no cycle", detectCycle(ListNode.withCycle(-1, 1)), null);

        check("LC 876 odd length", middleNode(ListNode.withCycle(-1, 1, 2, 3, 4, 5)), "[3, 4, 5]");
        check("LC 876 even length",
                middleNode(ListNode.withCycle(-1, 1, 2, 3, 4, 5, 6)), "[4, 5, 6]");

        check("LC 202 n=19", isHappy(19), true);
        check("LC 202 n=2", isHappy(2), false);
        check("LC 202 n=1", isHappy(1), true);

        check("LC 287 [1,3,4,2,2]", findDuplicate(new int[]{1, 3, 4, 2, 2}), 2);
        check("LC 287 [3,1,3,4,2]", findDuplicate(new int[]{3, 1, 3, 4, 2}), 3);
        check("LC 287 [3,3,3,3,3]", findDuplicate(new int[]{3, 3, 3, 3, 3}), 3);
    }
}

/*
 * =====================================================================
 *  P032 Linked List In-Place Reversal   Canonical LC 206 | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 206, Reverse Linked List)
 *   Reverse a singly linked list and return the new head. Do it iteratively and
 *   recursively.
 *
 * EXAMPLE
 *   [1, 2, 3, 4, 5]  ->  [5, 4, 3, 2, 1]
 *   [1, 2]           ->  [2, 1]
 *   []               ->  []
 *
 * RECOGNIZE WHEN
 *   - "reverse" a whole list, a sublist [left, right], or every group of k nodes.
 *   - Compare a list with itself backwards (palindrome) or interleave the front with the
 *     back (reorder) in O(1) extra space.
 *   Not this if: the reversal is of an array or string -> P009_ReverseTricks; you only need
 *   to read backwards and O(n) space is fine -> push onto a stack.
 *
 * TEMPLATE
 *   prev = null, cur = head
 *   while cur:
 *       next = cur.next       // 1. save the rest
 *       cur.next = prev       // 2. flip one pointer
 *       prev = cur            // 3. advance prev
 *       cur = next            // 4. advance cur
 *   return prev
 *   sublist: walk to the node BEFORE left (use a dummy), reverse right - left + 1 nodes,
 *            reconnect both ends
 *
 * APPROACH
 *   1. Keep prev (already reversed part) and cur (rest of the list).
 *   2. Save cur.next, point cur back at prev, move both one step.
 *
 * KEY INSIGHT
 *   Reversal is just "flip one arrow at a time" while holding the three nodes around it
 *   (prev, cur, next). Every harder reversal problem is this loop plus careful bookkeeping
 *   of the node before the section and the node after it.
 *
 * COMPLEXITY
 *   Iterative O(n) time, O(1) space; recursive O(n) time, O(n) stack.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 92   Reverse Linked List II   dummy, walk to left - 1, reverse the section by
 *                                            moving each next node to the section's front
 *   [coded] LC 25   Reverse Nodes in k-Group check k nodes exist, reverse them, recurse on
 *                                            the rest; leave a short tail as it is
 *   [coded] LC 234  Palindrome Linked List   middle (P031_FastSlowPointers), reverse the
 *                                            second half, compare, (restore)
 *           LC 24   Swap Nodes in Pairs      LC 25 with k = 2
 *           LC 143  Reorder List             middle, reverse the second half, merge
 *                                            alternately
 *           LC 2130 Max Twin Sum             reverse the second half, add pairs
 *
 * PITFALLS
 *   - Save next BEFORE changing cur.next, or the rest of the list is lost.
 *   - Sublists: a dummy head avoids the "left == 1" special case.
 *   - LC 25: never reverse a final group shorter than k.
 *
 * DEEP DIVE
 *   A02_ReverseLinkedList, D01_ReverseListInKGroups, B03_PalindromeLinkedList,
 *   C10_ReorderList (06-Linked-List)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
class InPlaceReversal {

    static class ListNode {
        int val;
        ListNode next;

        ListNode(int val) {
            this.val = val;
        }

        static ListNode of(int... vals) {
            ListNode dummy = new ListNode(0);
            ListNode cur = dummy;
            for (int v : vals) {
                cur.next = new ListNode(v);
                cur = cur.next;
            }
            return dummy.next;
        }
    }

    static String show(ListNode head) {
        StringBuilder sb = new StringBuilder("[");
        for (ListNode n = head; n != null; n = n.next) {
            sb.append(n.val).append(n.next == null ? "" : ", ");
        }
        return sb.append("]").toString();
    }

    // Canonical LC 206, iterative.
    static ListNode reverseList(ListNode head) {
        ListNode prev = null;
        ListNode cur = head;
        while (cur != null) {
            ListNode next = cur.next;
            cur.next = prev;
            prev = cur;
            cur = next;
        }
        return prev;
    }

    // Canonical LC 206, recursive: reverse the rest, then hang head after its old next.
    static ListNode reverseRecursive(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }
        ListNode newHead = reverseRecursive(head.next);
        head.next.next = head;
        head.next = null;
        return newHead;
    }

    // LC 92: reverse positions left..right (1-based).
    static ListNode reverseBetween(ListNode head, int left, int right) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode before = dummy;
        for (int i = 1; i < left; i++) {
            before = before.next;
        }
        ListNode tail = before.next;               // becomes the section's last node
        for (int i = 0; i < right - left; i++) {
            ListNode moved = tail.next;            // move the next node to the front
            tail.next = moved.next;
            moved.next = before.next;
            before.next = moved;
        }
        return dummy.next;
    }

    // LC 25.
    static ListNode reverseKGroup(ListNode head, int k) {
        ListNode probe = head;
        for (int i = 0; i < k; i++) {
            if (probe == null) {
                return head;                       // fewer than k left: keep as is
            }
            probe = probe.next;
        }
        ListNode prev = reverseKGroup(probe, k);   // the already-processed rest
        ListNode cur = head;
        for (int i = 0; i < k; i++) {
            ListNode next = cur.next;
            cur.next = prev;
            prev = cur;
            cur = next;
        }
        return prev;
    }

    // LC 234.
    static boolean isPalindrome(ListNode head) {
        ListNode slow = head;
        ListNode fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode second = reverseList(slow);
        ListNode a = head;
        ListNode b = second;
        boolean same = true;
        while (b != null) {
            if (a.val != b.val) {
                same = false;
                break;
            }
            a = a.next;
            b = b.next;
        }
        reverseList(second);                       // put the list back as it was
        return same;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 206 iterative", show(reverseList(ListNode.of(1, 2, 3, 4, 5))), "[5, 4, 3, 2, 1]");
        check("LC 206 iterative [1,2]", show(reverseList(ListNode.of(1, 2))), "[2, 1]");
        check("LC 206 iterative empty", show(reverseList(null)), "[]");
        check("LC 206 recursive",
                show(reverseRecursive(ListNode.of(1, 2, 3, 4, 5))), "[5, 4, 3, 2, 1]");

        check("LC 92 left=2 right=4",
                show(reverseBetween(ListNode.of(1, 2, 3, 4, 5), 2, 4)), "[1, 4, 3, 2, 5]");
        check("LC 92 single node", show(reverseBetween(ListNode.of(5), 1, 1)), "[5]");
        check("LC 92 whole list", show(reverseBetween(ListNode.of(3, 5), 1, 2)), "[5, 3]");

        check("LC 25 k=2", show(reverseKGroup(ListNode.of(1, 2, 3, 4, 5), 2)), "[2, 1, 4, 3, 5]");
        check("LC 25 k=3", show(reverseKGroup(ListNode.of(1, 2, 3, 4, 5), 3)), "[3, 2, 1, 4, 5]");
        check("LC 25 k=1 unchanged", show(reverseKGroup(ListNode.of(1, 2, 3), 1)), "[1, 2, 3]");

        check("LC 234 [1,2,2,1]", isPalindrome(ListNode.of(1, 2, 2, 1)), true);
        check("LC 234 [1,2]", isPalindrome(ListNode.of(1, 2)), false);
        check("LC 234 [1,2,3,2,1] odd", isPalindrome(ListNode.of(1, 2, 3, 2, 1)), true);
        ListNode kept = ListNode.of(1, 2, 2, 1);
        isPalindrome(kept);
        check("LC 234 list restored afterwards", show(kept), "[1, 2, 2, 1]");
    }
}

/*
 * =====================================================================
 *  P033 Linked List: Dummy Head, Merge and Build   Canonical LC 21 | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 21, Merge Two Sorted Lists)
 *   Merge two sorted linked lists into one sorted list by splicing their nodes together,
 *   and return its head.
 *
 * EXAMPLE
 *   [1, 2, 4] + [1, 3, 4]  ->  [1, 1, 2, 3, 4, 4]
 *   []        + []         ->  []
 *   []        + [0]        ->  [0]
 *
 * RECOGNIZE WHEN
 *   - You BUILD an output list node by node (merge, add numbers, partition, filter).
 *   - The head itself might change or be deleted (removing nodes, duplicates at the front).
 *   - Splitting one list into several (by value, by parity) and joining them back.
 *   Not this if: you reverse links -> P032_InPlaceReversal; you need the n-th from the end
 *   -> P034_GapPointers; more than two sorted lists -> P044_KWayMerge.
 *
 * TEMPLATE
 *   dummy = new Node(0); tail = dummy          // dummy.next will be the real head
 *   while inputs remain:
 *       pick / create the next node
 *       tail.next = node; tail = node
 *   tail.next = rest (or null)                  // terminate, or a cycle survives
 *   return dummy.next
 *
 * APPROACH
 *   1. tail starts at a dummy node, so the first real node needs no special case.
 *   2. Attach the smaller head of the two lists, advance that list and tail.
 *   3. When one list ends, attach the rest of the other one.
 *
 * KEY INSIGHT
 *   A dummy (sentinel) node turns "the list might be empty" and "the head might change"
 *   into the general case: there is always a node before the one you are working on.
 *   Most linked-list bugs are head special cases, and the dummy deletes them.
 *
 * COMPLEXITY
 *   Time O(m + n), space O(1) (the nodes are reused; LC 2 creates max(m, n) + 1 nodes).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 2    Add Two Numbers          one new node per digit; loop while either list
 *                                            OR the carry remains
 *   [coded] LC 86   Partition List           two dummies (less, rest), join, end with null
 *   [coded] LC 82   Remove Duplicates II     prev starts at dummy; skip every run of equal
 *                                            values entirely
 *           LC 83   Remove Duplicates        keep one of each: compare with next, unlink
 *           LC 203  Remove Linked List Elements  dummy, unlink matching nodes
 *           LC 328  Odd Even Linked List     two tails (odd, even), join at the end
 *           LC 148  Sort List                merge sort: P031_FastSlowPointers middle + merge
 *           LC 23   Merge k Sorted Lists     -> P044_KWayMerge
 *
 * PITFALLS
 *   - Finish with tail.next = null when you reuse nodes (LC 86), or the old links form a
 *     cycle.
 *   - LC 2: do not forget the final carry ([5] + [5] = [0, 1]).
 *   - Return dummy.next, never dummy.
 *
 * DEEP DIVE
 *   A04_MergeTwoSortedLists, C01_AddTwoNumbers, C03_PartitionList,
 *   B01_RemoveDuplicatesInList (06-Linked-List)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
class DummyHeadMerge {

    static class ListNode {
        int val;
        ListNode next;

        ListNode(int val) {
            this.val = val;
        }

        static ListNode of(int... vals) {
            ListNode dummy = new ListNode(0);
            ListNode cur = dummy;
            for (int v : vals) {
                cur.next = new ListNode(v);
                cur = cur.next;
            }
            return dummy.next;
        }
    }

    static String show(ListNode head) {
        StringBuilder sb = new StringBuilder("[");
        for (ListNode n = head; n != null; n = n.next) {
            sb.append(n.val).append(n.next == null ? "" : ", ");
        }
        return sb.append("]").toString();
    }

    // Canonical LC 21.
    static ListNode mergeTwoLists(ListNode a, ListNode b) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        while (a != null && b != null) {
            if (a.val <= b.val) {
                tail.next = a;
                a = a.next;
            } else {
                tail.next = b;
                b = b.next;
            }
            tail = tail.next;
        }
        tail.next = a != null ? a : b;
        return dummy.next;
    }

    // LC 2: digits stored in reverse order.
    static ListNode addTwoNumbers(ListNode a, ListNode b) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        int carry = 0;
        while (a != null || b != null || carry != 0) {
            int sum = carry;
            if (a != null) {
                sum += a.val;
                a = a.next;
            }
            if (b != null) {
                sum += b.val;
                b = b.next;
            }
            tail.next = new ListNode(sum % 10);
            tail = tail.next;
            carry = sum / 10;
        }
        return dummy.next;
    }

    // LC 86: nodes < x first, keeping the original order inside each part.
    static ListNode partition(ListNode head, int x) {
        ListNode lessDummy = new ListNode(0);
        ListNode restDummy = new ListNode(0);
        ListNode less = lessDummy;
        ListNode rest = restDummy;
        for (ListNode n = head; n != null; n = n.next) {
            if (n.val < x) {
                less.next = n;
                less = n;
            } else {
                rest.next = n;
                rest = n;
            }
        }
        rest.next = null;                          // the old link might point backwards
        less.next = restDummy.next;
        return lessDummy.next;
    }

    // LC 82: delete every value that appears more than once (sorted list).
    static ListNode deleteDuplicates(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy;
        ListNode cur = head;
        while (cur != null) {
            if (cur.next != null && cur.next.val == cur.val) {
                int dup = cur.val;
                while (cur != null && cur.val == dup) {
                    cur = cur.next;
                }
                prev.next = cur;                   // drop the whole run
            } else {
                prev = cur;
                cur = cur.next;
            }
        }
        return dummy.next;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 21 two lists", show(mergeTwoLists(ListNode.of(1, 2, 4), ListNode.of(1, 3, 4))),
                "[1, 1, 2, 3, 4, 4]");
        check("LC 21 both empty", show(mergeTwoLists(null, null)), "[]");
        check("LC 21 one empty", show(mergeTwoLists(null, ListNode.of(0))), "[0]");

        check("LC 2 342 + 465",
                show(addTwoNumbers(ListNode.of(2, 4, 3), ListNode.of(5, 6, 4))), "[7, 0, 8]");
        check("LC 2 0 + 0", show(addTwoNumbers(ListNode.of(0), ListNode.of(0))), "[0]");
        check("LC 2 final carry",
                show(addTwoNumbers(ListNode.of(9, 9, 9, 9, 9, 9, 9), ListNode.of(9, 9, 9, 9))),
                "[8, 9, 9, 9, 0, 0, 0, 1]");

        check("LC 86 x=3", show(partition(ListNode.of(1, 4, 3, 2, 5, 2), 3)), "[1, 2, 2, 4, 3, 5]");
        check("LC 86 x=2", show(partition(ListNode.of(2, 1), 2)), "[1, 2]");

        check("LC 82 [1,2,3,3,4,4,5]",
                show(deleteDuplicates(ListNode.of(1, 2, 3, 3, 4, 4, 5))), "[1, 2, 5]");
        check("LC 82 duplicates at the head",
                show(deleteDuplicates(ListNode.of(1, 1, 1, 2, 3))), "[2, 3]");
        check("LC 82 all duplicates", show(deleteDuplicates(ListNode.of(1, 1))), "[]");
    }
}

/*
 * =====================================================================
 *  P034 Linked List: Gap Pointers (n-th from End)   Canonical LC 19 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 19, Remove Nth Node From End of List)
 *   Remove the n-th node from the end of the list (1 = last) in one pass and return the
 *   head. n is always valid.
 *
 * EXAMPLE
 *   [1, 2, 3, 4, 5], n = 2  ->  [1, 2, 3, 5]
 *   [1],             n = 1  ->  []
 *   [1, 2],          n = 2  ->  [2]        the trap: the head itself is removed
 *
 * RECOGNIZE WHEN
 *   - "k-th / n-th from the END", "last k nodes", "rotate right by k" on a singly linked
 *     list, ideally in one pass.
 *   - Two lists of different lengths must be walked "aligned at the end" (intersection).
 *   Not this if: you need the middle or a cycle -> P031_FastSlowPointers.
 *
 * TEMPLATE
 *   dummy.next = head; lead = trail = dummy
 *   move lead n steps ahead                    // the gap is now n
 *   while lead.next: lead = lead.next; trail = trail.next
 *   trail.next is the n-th from the end         // trail is the node BEFORE it
 *
 * APPROACH
 *   1. Put lead n nodes ahead of trail, both starting at a dummy.
 *   2. Move both until lead is on the last node; trail now sits just before the target.
 *   3. Unlink trail.next.
 *
 * KEY INSIGHT
 *   You cannot count from the end of a singly linked list, but a fixed GAP between two
 *   pointers carries the count for you: when the leader hits the end, the follower is
 *   exactly n behind. Starting at a dummy lets the follower stop BEFORE the target, even
 *   when the target is the head.
 *
 * COMPLEXITY
 *   Time O(L), one pass; space O(1).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 61   Rotate List              k %= length; the new tail is (length - k)
 *                                            from the start; close into a ring, cut it
 *   [coded] LC 160  Intersection of Lists    walk a then b, and b then a: both travel
 *                                            m + n and meet at the junction (or null)
 *           LC 1721 Swapping Nodes           k-th from start and k-th from end via the gap
 *           LC 2095 Delete Middle Node       -> P031_FastSlowPointers
 *           Kth to last (CTCI 2.2)           the same gap walk
 *
 * PITFALLS
 *   - Without the dummy, removing the head needs a special case.
 *   - LC 61: k can exceed the length; and k % length == 0 means "unchanged".
 *   - LC 160: compare NODES (references), not values.
 *
 * DEEP DIVE
 *   C02_DeleteNthNodefromEnd, C06_RotateRightList, B02_IntersectionOfTwoLinkedLists
 *   (06-Linked-List)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
class GapPointers {

    static class ListNode {
        int val;
        ListNode next;

        ListNode(int val) {
            this.val = val;
        }

        static ListNode of(int... vals) {
            ListNode dummy = new ListNode(0);
            ListNode cur = dummy;
            for (int v : vals) {
                cur.next = new ListNode(v);
                cur = cur.next;
            }
            return dummy.next;
        }
    }

    static String show(ListNode head) {
        StringBuilder sb = new StringBuilder("[");
        for (ListNode n = head; n != null; n = n.next) {
            sb.append(n.val).append(n.next == null ? "" : ", ");
        }
        return sb.append("]").toString();
    }

    // Canonical LC 19.
    static ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode lead = dummy;
        ListNode trail = dummy;
        for (int i = 0; i < n; i++) {
            lead = lead.next;
        }
        while (lead.next != null) {
            lead = lead.next;
            trail = trail.next;
        }
        trail.next = trail.next.next;
        return dummy.next;
    }

    // LC 61: rotate right by k.
    static ListNode rotateRight(ListNode head, int k) {
        if (head == null || head.next == null) {
            return head;
        }
        int length = 1;
        ListNode tail = head;
        while (tail.next != null) {
            tail = tail.next;
            length++;
        }
        k %= length;
        if (k == 0) {
            return head;
        }
        ListNode newTail = head;
        for (int i = 1; i < length - k; i++) {
            newTail = newTail.next;
        }
        ListNode newHead = newTail.next;
        newTail.next = null;
        tail.next = head;
        return newHead;
    }

    // LC 160: both pointers walk m + n nodes, so they line up at the junction.
    static ListNode getIntersectionNode(ListNode a, ListNode b) {
        ListNode p = a;
        ListNode q = b;
        while (p != q) {
            p = p == null ? b : p.next;
            q = q == null ? a : q.next;
        }
        return p;                                  // the junction, or null
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 19 n=2", show(removeNthFromEnd(ListNode.of(1, 2, 3, 4, 5), 2)), "[1, 2, 3, 5]");
        check("LC 19 only node", show(removeNthFromEnd(ListNode.of(1), 1)), "[]");
        check("LC 19 remove the head", show(removeNthFromEnd(ListNode.of(1, 2), 2)), "[2]");
        check("LC 19 remove the tail", show(removeNthFromEnd(ListNode.of(1, 2), 1)), "[1]");

        check("LC 61 k=2", show(rotateRight(ListNode.of(1, 2, 3, 4, 5), 2)), "[4, 5, 1, 2, 3]");
        check("LC 61 k=4 > length", show(rotateRight(ListNode.of(0, 1, 2), 4)), "[2, 0, 1]");
        check("LC 61 k=length unchanged", show(rotateRight(ListNode.of(1, 2, 3), 3)), "[1, 2, 3]");

        ListNode shared = ListNode.of(8, 4, 5);
        ListNode a = ListNode.of(4, 1);
        a.next.next = shared;
        ListNode b = ListNode.of(5, 6, 1);
        b.next.next.next = shared;
        check("LC 160 meet at 8", getIntersectionNode(a, b).val, 8);
        check("LC 160 no junction",
                getIntersectionNode(ListNode.of(2, 6, 4), ListNode.of(1, 5)), null);
    }
}

/*
 * =====================================================================
 *  P035 Deep Copy with an Old -> New Map   Canonical LC 138 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 138, Copy List with Random Pointer)
 *   Each node has next and random (random may point anywhere in the list, or null).
 *   Return a deep copy: brand-new nodes whose next and random mirror the original's.
 *
 * EXAMPLE
 *   [[7,null],[13,0],[11,4],[10,2],[1,0]]  ->  the same shape, all nodes new
 *   (each pair is [value, index that random points to])
 *
 * RECOGNIZE WHEN
 *   - "deep copy", "clone", "duplicate the structure" where pointers can go anywhere
 *     (random pointers, graph edges, cycles).
 *   - You meet a node through one pointer before you have created its copy.
 *   Not this if: the structure is a plain list or tree with no extra pointers -> a simple
 *   recursive copy (no map) is enough.
 *
 * TEMPLATE
 *   copyOf = {}                                       // original node -> its clone
 *   clone(node):
 *       if node is null: return null
 *       if node in copyOf: return copyOf[node]        // already made (also stops cycles)
 *       c = new Node(node.val); copyOf[node] = c      // register BEFORE recursing
 *       wire c's pointers with clone(...) of the original's pointers
 *       return c
 *
 * APPROACH
 *   1. First pass: create a copy of every node, map original -> copy.
 *   2. Second pass: copy.next = map[orig.next], copy.random = map[orig.random].
 *
 * KEY INSIGHT
 *   A pointer can name a node whose copy does not exist yet. The map answers "what is the
 *   copy of X?" whenever it is needed, and storing the copy BEFORE following any pointer
 *   is what makes cycles safe. The O(1)-space trick stores the same mapping inside the
 *   list itself: put each copy right after its original.
 *
 * COMPLEXITY
 *   Time O(n), space O(n) for the map (O(1) extra with interleaving). Graph: O(V + E).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 138 interleaved               A -> A' -> B -> B'; A'.random = A.random.next;
 *                                            then unzip the two lists
 *   [coded] LC 133  Clone Graph              DFS with the map; neighbours instead of next
 *           LC 1485 Clone Tree w/ Random     the same map over a binary tree
 *           LC 1490 Clone N-ary Tree         no sharing, so no map needed
 *
 * PITFALLS
 *   - Registering the copy AFTER recursing loops forever on a cycle.
 *   - Interleaving: restore the original list's next pointers while unzipping.
 *   - Copy random == null as null, not as "copy of null".
 *
 * DEEP DIVE
 *   C12_CopyRandomList (06-Linked-List)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayList;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;

class CloneWithMap {

    static class Node {
        int val;
        Node next;
        Node random;

        Node(int val) {
            this.val = val;
        }

        // pairs[i] = {value, randomIndex or -1}
        static Node build(int[][] pairs) {
            List<Node> nodes = new ArrayList<>();
            for (int[] p : pairs) {
                nodes.add(new Node(p[0]));
            }
            for (int i = 0; i < nodes.size(); i++) {
                nodes.get(i).next = i + 1 < nodes.size() ? nodes.get(i + 1) : null;
                nodes.get(i).random = pairs[i][1] < 0 ? null : nodes.get(pairs[i][1]);
            }
            return nodes.isEmpty() ? null : nodes.get(0);
        }
    }

    static class GraphNode {
        int val;
        List<GraphNode> neighbors = new ArrayList<>();

        GraphNode(int val) {
            this.val = val;
        }
    }

    // Prints [[val, randomIndex], ...] so a copy can be compared with the original.
    static String show(Node head) {
        Map<Node, Integer> index = new IdentityHashMap<>();
        int i = 0;
        for (Node n = head; n != null; n = n.next) {
            index.put(n, i++);
        }
        StringBuilder sb = new StringBuilder("[");
        for (Node n = head; n != null; n = n.next) {
            sb.append("[").append(n.val).append(",")
                    .append(n.random == null ? "null" : index.get(n.random)).append("]");
            if (n.next != null) {
                sb.append(",");
            }
        }
        return sb.append("]").toString();
    }

    // True when no node of the copy is a node of the original.
    static boolean shareNothing(Node a, Node b) {
        Map<Node, Boolean> seen = new IdentityHashMap<>();
        for (Node n = a; n != null; n = n.next) {
            seen.put(n, true);
        }
        for (Node n = b; n != null; n = n.next) {
            if (seen.containsKey(n)) {
                return false;
            }
        }
        return true;
    }

    // Canonical LC 138 with a map.
    static Node copyRandomList(Node head) {
        Map<Node, Node> copyOf = new HashMap<>();
        for (Node n = head; n != null; n = n.next) {
            copyOf.put(n, new Node(n.val));
        }
        for (Node n = head; n != null; n = n.next) {
            copyOf.get(n).next = copyOf.get(n.next);
            copyOf.get(n).random = copyOf.get(n.random);
        }
        return copyOf.get(head);
    }

    // LC 138 in O(1) extra space: interleave, set randoms, unzip.
    static Node copyRandomListInterleaved(Node head) {
        for (Node n = head; n != null; n = n.next.next) {
            Node c = new Node(n.val);
            c.next = n.next;
            n.next = c;
        }
        for (Node n = head; n != null; n = n.next.next) {
            n.next.random = n.random == null ? null : n.random.next;
        }
        Node dummy = new Node(0);
        Node tail = dummy;
        for (Node n = head; n != null; n = n.next) {
            Node c = n.next;
            n.next = c.next;                       // restore the original
            tail.next = c;
            tail = c;
        }
        return dummy.next;
    }

    // LC 133: register the clone before visiting neighbours (graphs have cycles).
    static GraphNode cloneGraph(GraphNode node) {
        return clone(node, new HashMap<>());
    }

    private static GraphNode clone(GraphNode node, Map<GraphNode, GraphNode> copyOf) {
        if (node == null) {
            return null;
        }
        GraphNode done = copyOf.get(node);
        if (done != null) {
            return done;
        }
        GraphNode c = new GraphNode(node.val);
        copyOf.put(node, c);
        for (GraphNode nb : node.neighbors) {
            c.neighbors.add(clone(nb, copyOf));
        }
        return c;
    }

    // Adjacency list by value (1-based, as LeetCode prints it); also checks node identity.
    static String showGraph(GraphNode start, GraphNode original) {
        Map<Integer, GraphNode> byVal = new HashMap<>();
        collect(start, byVal);
        Map<Integer, GraphNode> origByVal = new HashMap<>();
        collect(original, origByVal);
        StringBuilder sb = new StringBuilder("[");
        for (int v = 1; v <= byVal.size(); v++) {
            List<Integer> nbs = new ArrayList<>();
            for (GraphNode nb : byVal.get(v).neighbors) {
                nbs.add(nb.val);
            }
            sb.append(nbs.toString().replace(" ", "")).append(v < byVal.size() ? "," : "");
            if (byVal.get(v) == origByVal.get(v)) {
                return "shared node " + v;
            }
        }
        return sb.append("]").toString();
    }

    private static void collect(GraphNode n, Map<Integer, GraphNode> byVal) {
        if (n == null || byVal.containsKey(n.val)) {
            return;
        }
        byVal.put(n.val, n);
        for (GraphNode nb : n.neighbors) {
            collect(nb, byVal);
        }
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        int[][] shape = {{7, -1}, {13, 0}, {11, 4}, {10, 2}, {1, 0}};
        Node original = Node.build(shape);
        Node copy = copyRandomList(original);
        check("LC 138 map, same shape", show(copy), "[[7,null],[13,0],[11,4],[10,2],[1,0]]");
        check("LC 138 map, all nodes new", shareNothing(original, copy), true);

        Node original2 = Node.build(shape);
        Node copy2 = copyRandomListInterleaved(original2);
        check("LC 138 interleaved, same shape",
                show(copy2), "[[7,null],[13,0],[11,4],[10,2],[1,0]]");
        check("LC 138 interleaved, original restored", show(original2),
                "[[7,null],[13,0],[11,4],[10,2],[1,0]]");
        check("LC 138 interleaved, all nodes new", shareNothing(original2, copy2), true);
        check("LC 138 empty list", copyRandomList(null), null);

        GraphNode[] g = new GraphNode[5];
        for (int i = 1; i <= 4; i++) {
            g[i] = new GraphNode(i);
        }
        int[][] adj = {{}, {2, 4}, {1, 3}, {2, 4}, {1, 3}};
        for (int i = 1; i <= 4; i++) {
            for (int nb : adj[i]) {
                g[i].neighbors.add(g[nb]);
            }
        }
        check("LC 133 square graph",
                showGraph(cloneGraph(g[1]), g[1]), "[[2,4],[1,3],[2,4],[1,3]]");
        GraphNode lone = new GraphNode(1);
        check("LC 133 single node", showGraph(cloneGraph(lone), lone), "[[]]");
    }
}

