/*
 * =====================================================================
 *  P036 Stack: Matching and Balancing   Canonical LC 20 | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 20, Valid Parentheses)
 *   s holds only ()[]{}. It is valid if every opener is closed by the same type, in the
 *   right order. Return whether s is valid.
 *
 * EXAMPLE
 *   "()[]{}"  ->  true
 *   "([)]"    ->  false     wrong nesting order
 *   "{[]}"    ->  true
 *   "("       ->  false     left open at the end
 *
 * RECOGNIZE WHEN
 *   - Brackets, tags, nested blocks: the MOST RECENT unmatched opener must close first.
 *   - "remove adjacent pairs", "cancel", "backspace": the newest item reacts with the next.
 *   - Minimum insertions / deletions to balance.
 *   Not this if: you need the next greater / smaller element -> P037_NextGreaterElement;
 *   you evaluate an expression -> P040_ExpressionEvaluation.
 *
 * TEMPLATE
 *   stack = []
 *   for ch in s:
 *       if opener(ch): push(ch)                     // or push its INDEX if you need lengths
 *       else:
 *           if stack empty or top does not match ch: invalid (or count / mark it)
 *           else pop()
 *   valid iff stack is empty at the end
 *   only one bracket type: a counter replaces the stack
 *
 * APPROACH
 *   1. Push every opener.
 *   2. A closer must match the top; pop it. A mismatch or an empty stack is invalid.
 *   3. Anything left on the stack was never closed.
 *
 * KEY INSIGHT
 *   Nesting is last-in-first-out, which is exactly a stack. Pushing INDICES instead of
 *   characters upgrades "is it valid?" into "which characters are unmatched?" and "how
 *   long is each valid stretch?".
 *
 * COMPLEXITY
 *   Time O(n), space O(n) (O(1) with a counter for one bracket type).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 1249 Min Remove to Make Valid push indices of '('; unmatched ')' and the
 *                                            leftover '(' indices are the ones to delete
 *   [coded] LC 921  Min Add to Make Valid    one type -> counters: open, and needed ')'
 *   [coded] LC 32   Longest Valid Parentheses  stack of indices seeded with -1 (the last
 *                                            unmatched position); length = i - top
 *           LC 1047 Remove Adjacent Dups     push char, pop when equal to top
 *           LC 1209 Remove Adjacent Dups II  stack of (char, run count); pop at k
 *           LC 2390 Removing Stars           '*' pops the top
 *           LC 678  Valid Parenthesis String '*' wildcards: track min and max open counts
 *           LC 856  Score of Parentheses     depth counter: "()" at depth d adds 2^d
 *
 * PITFALLS
 *   - Check the stack is non-empty before peeking on a closer.
 *   - Return stack.isEmpty(), not true, at the end ("((" must fail).
 *   - Use ArrayDeque, not the legacy synchronized Stack class.
 *
 * DEEP DIVE
 *   A02_ValidParentheses, C02_MinimumAddToMakeParenthesesValid,
 *   D01_LongestValidParentheses, B01_RemoveAdjacentDuplicates (07-Stack-Queue-Monotonic)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.Deque;

class MatchingStack {

    // Openers and closers at matching positions.
    static final String OPEN = "([{";
    static final String CLOSE = ")]}";

    // Canonical LC 20.
    static boolean isValid(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (OPEN.indexOf(c) >= 0) {
                stack.push(c);
            } else {
                if (stack.isEmpty() || OPEN.indexOf(stack.pop()) != CLOSE.indexOf(c)) {
                    return false;
                }
            }
        }
        return stack.isEmpty();
    }

    // LC 1249: delete the fewest parentheses to make s valid (letters stay).
    static String minRemoveToMakeValid(String s) {
        char[] c = s.toCharArray();
        Deque<Integer> open = new ArrayDeque<>();
        for (int i = 0; i < c.length; i++) {
            if (c[i] == '(') {
                open.push(i);
            } else if (c[i] == ')') {
                if (open.isEmpty()) {
                    c[i] = '*';                    // unmatched closer
                } else {
                    open.pop();
                }
            }
        }
        while (!open.isEmpty()) {
            c[open.pop()] = '*';                   // unmatched openers
        }
        StringBuilder sb = new StringBuilder();
        for (char ch : c) {
            if (ch != '*') {
                sb.append(ch);
            }
        }
        return sb.toString();
    }

    // LC 921: one bracket type, so counts are enough.
    static int minAddToMakeValid(String s) {
        int open = 0;
        int added = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                open++;
            } else if (open > 0) {
                open--;
            } else {
                added++;                           // a ')' with nothing to close
            }
        }
        return added + open;
    }

    // LC 32: the stack bottom is the index of the last unmatched ')' (or -1).
    static int longestValidParentheses(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(-1);
        int best = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                stack.push(i);
            } else {
                stack.pop();
                if (stack.isEmpty()) {
                    stack.push(i);                 // new barrier
                } else {
                    best = Math.max(best, i - stack.peek());
                }
            }
        }
        return best;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 20 ()[]{}", isValid("()[]{}"), true);
        check("LC 20 (]", isValid("(]"), false);
        check("LC 20 ([)] wrong order", isValid("([)]"), false);
        check("LC 20 {[]}", isValid("{[]}"), true);
        check("LC 20 ] closer first", isValid("]"), false);
        check("LC 20 ( never closed", isValid("("), false);

        check("LC 1249 lee(t(c)o)de)", minRemoveToMakeValid("lee(t(c)o)de)"), "lee(t(c)o)de");
        check("LC 1249 a)b(c)d", minRemoveToMakeValid("a)b(c)d"), "ab(c)d");
        check("LC 1249 ))(( all go", "[" + minRemoveToMakeValid("))((") + "]", "[]");

        check("LC 921 ())", minAddToMakeValid("())"), 1);
        check("LC 921 (((", minAddToMakeValid("((("), 3);
        check("LC 921 ()))((", minAddToMakeValid("()))(("), 4);

        check("LC 32 (()", longestValidParentheses("(()"), 2);
        check("LC 32 )()())", longestValidParentheses(")()())"), 4);
        check("LC 32 empty", longestValidParentheses(""), 0);
        check("LC 32 ()(()) joined", longestValidParentheses("()(())"), 6);
    }
}

/*
 * =====================================================================
 *  P037 Monotonic Stack: Next Greater / Smaller   Canonical LC 739 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 739, Daily Temperatures)
 *   For each day, return how many days you must wait for a warmer temperature, or 0 if
 *   none comes.
 *
 * EXAMPLE
 *   [73, 74, 75, 71, 69, 72, 76, 73]  ->  [1, 1, 4, 2, 1, 1, 0, 0]
 *   [30, 40, 50, 60]                  ->  [1, 1, 1, 0]
 *   [30, 60, 90]                      ->  [1, 1, 0]
 *
 * RECOGNIZE WHEN
 *   - For EACH element: the nearest element to the right (or left) that is greater
 *     (or smaller). "next warmer day", "next bigger price", "previous higher building".
 *   - "span" / "how many consecutive days before today were <= today".
 *   - O(n^2) brute force is "scan right from every i until something is bigger".
 *   Not this if: you need the max of every fixed window -> P042_MonotonicDeque; you need
 *   the area / sum over ranges bounded by smaller elements -> P038_StackBoundariesContribution.
 *
 * TEMPLATE
 *   stack = []                                  // indices whose answer is still unknown;
 *                                               // their values are decreasing bottom->top
 *   for i in 0..n-1:
 *       while stack and a[stack.top] < a[i]:    // a[i] is the answer for everything smaller
 *           j = stack.pop(); answer[j] = i
 *       stack.push(i)
 *   // previous greater: same loop; after popping, stack.top (if any) is i's answer
 *   // next smaller: flip the comparison
 *
 * APPROACH
 *   1. Keep the days still waiting for a warmer day on a stack.
 *   2. Today pops every waiting day that is colder; their wait is today - thatDay.
 *   3. Push today; it waits too.
 *
 * KEY INSIGHT
 *   An element that is blocked by a later, bigger element can never be anyone's "next
 *   greater" for the elements further left, so it can be discarded the moment the bigger
 *   one arrives. What is left on the stack is always decreasing, and each index is pushed
 *   and popped once: O(n).
 *
 * COMPLEXITY
 *   Time O(n) (each index pushed and popped at most once), space O(n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 496  Next Greater Element I   run the template on nums2, store value -> next
 *                                            greater in a map, look up nums1
 *   [coded] LC 503  Next Greater Element II  circular: loop i over 0..2n-1, use i % n, push
 *                                            only in the first pass
 *   [coded] LC 901  Online Stock Span        PREVIOUS greater, online: stack of
 *                                            (price, span); pop and add spans while <= price
 *           LC 1475 Final Prices w/ Discount next SMALLER-OR-EQUAL element
 *           LC 2454 Next Greater Element IV  second greater: two stacks
 *           LC 1019 Next Greater Node in List copy the list to an array first
 *           LC 456  132 Pattern              scan right to left; stack + "best third" value
 *           LC 1944 Visible People in Queue  count pops, plus one if the stack is not empty
 *
 * PITFALLS
 *   - Push INDICES, not values, when you need distances.
 *   - "<" vs "<=" decides how equal values behave; read the problem twice.
 *   - Unresolved indices keep the default answer (0 or -1); set it up front.
 *
 * DEEP DIVE
 *   C06_DailyTemperatures, A03_NextGreaterElements, C10_Find132pattern,
 *   D03_VisiblePeopleInQueue (07-Stack-Queue-Monotonic)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;

class NextGreaterElement {

    // Canonical LC 739.
    static int[] dailyTemperatures(int[] t) {
        int[] answer = new int[t.length];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < t.length; i++) {
            while (!stack.isEmpty() && t[stack.peek()] < t[i]) {
                int j = stack.pop();
                answer[j] = i - j;
            }
            stack.push(i);
        }
        return answer;
    }

    // LC 496: nums1 is a subset of nums2; all values distinct.
    static int[] nextGreaterElement(int[] nums1, int[] nums2) {
        Map<Integer, Integer> next = new HashMap<>();
        Deque<Integer> stack = new ArrayDeque<>();
        for (int x : nums2) {
            while (!stack.isEmpty() && stack.peek() < x) {
                next.put(stack.pop(), x);
            }
            stack.push(x);
        }
        int[] answer = new int[nums1.length];
        for (int i = 0; i < nums1.length; i++) {
            answer[i] = next.getOrDefault(nums1[i], -1);
        }
        return answer;
    }

    // LC 503: circular array; walk it twice.
    static int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        Arrays.fill(answer, -1);
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < 2 * n; i++) {
            int x = nums[i % n];
            while (!stack.isEmpty() && nums[stack.peek()] < x) {
                answer[stack.pop()] = x;
            }
            if (i < n) {
                stack.push(i);
            }
        }
        return answer;
    }

    // LC 901: span = consecutive days up to today with price <= today's price.
    static class StockSpanner {
        private final Deque<int[]> stack = new ArrayDeque<>();   // {price, span}

        int next(int price) {
            int span = 1;
            while (!stack.isEmpty() && stack.peek()[0] <= price) {
                span += stack.pop()[1];           // absorb the days that one covered
            }
            stack.push(new int[]{price, span});
            return span;
        }
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 739 eight days",
                Arrays.toString(dailyTemperatures(new int[]{73, 74, 75, 71, 69, 72, 76, 73})),
                "[1, 1, 4, 2, 1, 1, 0, 0]");
        check("LC 739 rising",
                Arrays.toString(dailyTemperatures(new int[]{30, 40, 50, 60})), "[1, 1, 1, 0]");
        check("LC 739 equal temperatures wait",
                Arrays.toString(dailyTemperatures(new int[]{50, 50, 60})),
                "[2, 1, 0]");

        check("LC 496 [4,1,2] in [1,3,4,2]",
                Arrays.toString(nextGreaterElement(new int[]{4, 1, 2}, new int[]{1, 3, 4, 2})),
                "[-1, 3, -1]");
        check("LC 496 [2,4] in [1,2,3,4]",
                Arrays.toString(nextGreaterElement(new int[]{2, 4}, new int[]{1, 2, 3, 4})),
                "[3, -1]");

        check("LC 503 [1,2,1]",
                Arrays.toString(nextGreaterElements(new int[]{1, 2, 1})), "[2, -1, 2]");
        check("LC 503 [1,2,3,4,3]", Arrays.toString(nextGreaterElements(new int[]{1, 2, 3, 4, 3})),
                "[2, 3, 4, -1, 4]");

        StockSpanner spanner = new StockSpanner();
        int[] prices = {100, 80, 60, 70, 60, 75, 85};
        int[] spans = new int[prices.length];
        for (int i = 0; i < prices.length; i++) {
            spans[i] = spanner.next(prices[i]);
        }
        check("LC 901 seven prices", Arrays.toString(spans), "[1, 1, 1, 2, 1, 4, 6]");
    }
}

/*
 * =====================================================================
 *  P038 Monotonic Stack: Boundaries and Contribution   Canonical LC 84 | Hard   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 84, Largest Rectangle in Histogram)
 *   heights[i] is the height of a bar of width 1. Return the area of the largest
 *   rectangle that fits inside the histogram.
 *
 * EXAMPLE
 *   [2, 1, 5, 6, 2, 3]  ->  10     bars 5 and 6, height 5, width 2
 *   [2, 4]              ->  4
 *   [2, 2, 2]           ->  6      equal heights: the trap for strict comparisons
 *
 * RECOGNIZE WHEN
 *   - Each element "owns" the widest range where it is the minimum (or maximum), and the
 *     answer combines value x range: rectangles, "sum of subarray minimums", "count of
 *     subarrays where a[i] is the max".
 *   - Brute force is "for each i, expand left and right while neighbours are >= a[i]".
 *   Not this if: you only need the next greater / smaller index -> P037_NextGreaterElement.
 *
 * TEMPLATE
 *   stack = []                                       // indices with increasing heights
 *   for i in 0..n:                                   // i == n is a height-0 sentinel
 *       h = (i == n) ? 0 : a[i]
 *       while stack and a[stack.top] >= h:
 *           mid = stack.pop()
 *           left = stack.empty ? -1 : stack.top      // previous smaller (exclusive)
 *           // a[mid] is the minimum of every range (left, i) that contains mid
 *           use a[mid], left, i                      // area = a[mid] * (i - left - 1)
 *       stack.push(i)
 *
 * APPROACH
 *   1. Keep bar indices with increasing heights.
 *   2. A shorter bar ends the rectangle of every taller bar on the stack: pop it; its
 *      left limit is the new top, its right limit is i.
 *   3. A sentinel of height 0 at the end flushes the stack.
 *
 * KEY INSIGHT
 *   When a bar is popped, BOTH of its limits are known at once: the bar below it on the
 *   stack is the previous smaller, and the bar that popped it is the next smaller. So
 *   each element's "range where I am the minimum" costs O(1) amortised.
 *
 * COMPLEXITY
 *   Time O(n), space O(n). LC 85: O(rows * cols).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 907  Sum of Subarray Minimums contribution a[mid] * (mid - left) * (i - mid);
 *                                            pop on >= so equal values are counted once
 *   [coded] LC 85   Maximal Rectangle        each row builds a histogram of 1-heights;
 *                                            run LC 84 per row
 *   [coded] LC 42   Trapping Rain Water      pop a bottom; water = (min(left, right) -
 *                                            bottom) * width, layer by layer
 *           LC 2104 Sum of Subarray Ranges   sum of maxima minus sum of minima (twice)
 *           LC 1856 Max Min-Product          prefix sums + the same boundaries
 *           LC 1793 Max Score Good Subarray  LC 84 constrained to contain index k
 *
 * PITFALLS
 *   - Forgetting the sentinel leaves an increasing run on the stack, never measured.
 *   - Duplicates in LC 907: one side strict (<), the other non-strict (<=), or equal
 *     minimums are double counted.
 *   - LC 907 needs a modulo and long arithmetic.
 *
 * DEEP DIVE
 *   D02_LargestRectangleArea, C09_SumOfSubarrayMinimums (07-Stack-Queue-Monotonic),
 *   D01_TrappingRainWater (02-Two-Pointers-Sliding-Window)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.Deque;

class StackBoundariesContribution {

    // Canonical LC 84.
    static int largestRectangleArea(int[] a) {
        Deque<Integer> stack = new ArrayDeque<>();
        int best = 0;
        for (int i = 0; i <= a.length; i++) {
            int h = i == a.length ? 0 : a[i];
            while (!stack.isEmpty() && a[stack.peek()] >= h) {
                int mid = stack.pop();
                int left = stack.isEmpty() ? -1 : stack.peek();
                best = Math.max(best, a[mid] * (i - left - 1));
            }
            stack.push(i);
        }
        return best;
    }

    // LC 907.
    static int sumSubarrayMins(int[] a) {
        final long mod = 1_000_000_007L;
        Deque<Integer> stack = new ArrayDeque<>();
        long total = 0;
        for (int i = 0; i <= a.length; i++) {
            int h = i == a.length ? Integer.MIN_VALUE : a[i];
            while (!stack.isEmpty() && a[stack.peek()] >= h) {
                int mid = stack.pop();
                int left = stack.isEmpty() ? -1 : stack.peek();
                total = (total + (long) a[mid] * (mid - left) * (i - mid)) % mod;
            }
            stack.push(i);
        }
        return (int) total;
    }

    // LC 85: heights[c] = consecutive '1's ending at this row in column c.
    static int maximalRectangle(char[][] matrix) {
        if (matrix.length == 0) {
            return 0;
        }
        int[] heights = new int[matrix[0].length];
        int best = 0;
        for (char[] row : matrix) {
            for (int c = 0; c < row.length; c++) {
                heights[c] = row[c] == '1' ? heights[c] + 1 : 0;
            }
            best = Math.max(best, largestRectangleArea(heights));
        }
        return best;
    }

    // LC 42 with a stack: fill water layer by layer above each popped bottom.
    static int trap(int[] h) {
        Deque<Integer> stack = new ArrayDeque<>();
        int water = 0;
        for (int i = 0; i < h.length; i++) {
            while (!stack.isEmpty() && h[stack.peek()] < h[i]) {
                int bottom = stack.pop();
                if (stack.isEmpty()) {
                    break;                         // no left wall
                }
                int left = stack.peek();
                int depth = Math.min(h[left], h[i]) - h[bottom];
                water += depth * (i - left - 1);
            }
            stack.push(i);
        }
        return water;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 84 [2,1,5,6,2,3]", largestRectangleArea(new int[]{2, 1, 5, 6, 2, 3}), 10);
        check("LC 84 [2,4]", largestRectangleArea(new int[]{2, 4}), 4);
        check("LC 84 [2,2,2] equal", largestRectangleArea(new int[]{2, 2, 2}), 6);
        check("LC 84 [1]", largestRectangleArea(new int[]{1}), 1);

        check("LC 907 [3,1,2,4]", sumSubarrayMins(new int[]{3, 1, 2, 4}), 17);
        check("LC 907 [11,81,94,43,3]", sumSubarrayMins(new int[]{11, 81, 94, 43, 3}), 444);
        check("LC 907 [2,2] duplicates", sumSubarrayMins(new int[]{2, 2}), 6);

        char[][] grid = {
                "10100".toCharArray(), "10111".toCharArray(),
                "11111".toCharArray(), "10010".toCharArray()};
        check("LC 85 4x5", maximalRectangle(grid), 6);
        check("LC 85 [[0]]", maximalRectangle(new char[][]{{'0'}}), 0);
        check("LC 85 [[1]]", maximalRectangle(new char[][]{{'1'}}), 1);

        check("LC 42 stack", trap(new int[]{0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1}), 6);
        check("LC 42 stack [4,2,0,3,2,5]", trap(new int[]{4, 2, 0, 3, 2, 5}), 9);
    }
}

/*
 * =====================================================================
 *  P039 Monotonic Stack: Greedy Removal (Smallest Result)   Canonical LC 402 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 402, Remove K Digits)
 *   num is a non-negative integer as a string. Remove exactly k digits so the remaining
 *   number is as small as possible. Return it without leading zeros ("0" if empty).
 *
 * EXAMPLE
 *   "1432219", k = 3  ->  "1219"
 *   "10200",   k = 1  ->  "200"     leading zero dropped
 *   "10",      k = 2  ->  "0"       everything removed
 *
 * RECOGNIZE WHEN
 *   - Choose a SUBSEQUENCE (keep order) of a given length that is lexicographically
 *     smallest or largest: "remove k digits", "most competitive", "smallest subsequence of
 *     distinct characters".
 *   - A digit earlier in the result matters more than everything after it.
 *   Not this if: the order may change -> sort; you want max sum, not lexicographic order ->
 *   P043_TopK.
 *
 * TEMPLATE
 *   stack = []
 *   for x in seq:
 *       while stack and budget > 0 and stack.top > x:   // a smaller x should come earlier
 *           stack.pop(); budget--
 *       stack.push(x)
 *   drop extra items from the END if budget remains; strip leading zeros if numeric
 *
 * APPROACH
 *   1. Walk the digits. While the previous kept digit is bigger than the current one and
 *      removals remain, remove the previous digit.
 *   2. If removals remain at the end, the kept digits are non-decreasing: cut from the end.
 *
 * KEY INSIGHT
 *   The leftmost position where the result can get smaller dominates everything after it,
 *   so greedily make each position as small as possible. A bigger digit followed by a
 *   smaller one is a "peak", and deleting the first peak is always optimal.
 *
 * COMPLEXITY
 *   Time O(n), space O(n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 316  Remove Duplicate Letters pop only if the top appears AGAIN later
 *                                            (last index > i); skip letters already kept
 *   [coded] LC 1673 Most Competitive Subseq  keep exactly k: pop while
 *                                            (kept - 1) + (n - i) >= k
 *           LC 1081 Smallest Subsequence     identical to LC 316
 *           LC 321  Create Maximum Number    LC 1673 (max version) on both arrays + merge
 *           Largest number after k removals  flip the comparison (pop smaller tops)
 *
 * PITFALLS
 *   - Leading zeros: strip them at the end, and return "0" for an empty result.
 *   - LC 316: a letter already in the stack must be skipped, not pushed again.
 *   - Remaining budget after the loop: remove from the END, not the front.
 *
 * DEEP DIVE
 *   C07_RemoveKdigits (07-Stack-Queue-Monotonic)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

class GreedyRemovalStack {

    // Canonical LC 402.
    static String removeKdigits(String num, int k) {
        StringBuilder stack = new StringBuilder();       // used as a stack of chars
        for (char c : num.toCharArray()) {
            while (k > 0 && stack.length() > 0 && stack.charAt(stack.length() - 1) > c) {
                stack.deleteCharAt(stack.length() - 1);
                k--;
            }
            stack.append(c);
        }
        stack.setLength(stack.length() - k);             // leftover removals from the end
        int start = 0;
        while (start < stack.length() - 1 && stack.charAt(start) == '0') {
            start++;
        }
        String result = stack.substring(start);
        return result.isEmpty() ? "0" : result;
    }

    // LC 316: smallest result that contains every distinct letter exactly once.
    static String removeDuplicateLetters(String s) {
        int[] last = new int[26];
        for (int i = 0; i < s.length(); i++) {
            last[s.charAt(i) - 'a'] = i;
        }
        boolean[] kept = new boolean[26];
        Deque<Character> stack = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (kept[c - 'a']) {
                continue;
            }
            while (!stack.isEmpty() && stack.peek() > c && last[stack.peek() - 'a'] > i) {
                kept[stack.pop() - 'a'] = false;        // it can be taken again later
            }
            stack.push(c);
            kept[c - 'a'] = true;
        }
        StringBuilder sb = new StringBuilder();
        for (char c : stack) {
            sb.append(c);
        }
        return sb.reverse().toString();
    }

    // LC 1673: lexicographically smallest subsequence of length k.
    static int[] mostCompetitive(int[] nums, int k) {
        int[] stack = new int[k];
        int size = 0;
        for (int i = 0; i < nums.length; i++) {
            while (size > 0 && stack[size - 1] > nums[i] && size - 1 + (nums.length - i) >= k) {
                size--;
            }
            if (size < k) {
                stack[size++] = nums[i];
            }
        }
        return stack;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 402 1432219 k=3", removeKdigits("1432219", 3), "1219");
        check("LC 402 10200 k=1", removeKdigits("10200", 1), "200");
        check("LC 402 10 k=2", removeKdigits("10", 2), "0");
        check("LC 402 112 k=1 non-decreasing", removeKdigits("112", 1), "11");

        check("LC 316 bcabc", removeDuplicateLetters("bcabc"), "abc");
        check("LC 316 cbacdcbc", removeDuplicateLetters("cbacdcbc"), "acdb");

        check("LC 1673 [3,5,2,6] k=2",
                Arrays.toString(mostCompetitive(new int[]{3, 5, 2, 6}, 2)), "[2, 6]");
        check("LC 1673 [2,4,3,3,5,4,9,6] k=4",
                Arrays.toString(mostCompetitive(new int[]{2, 4, 3, 3, 5, 4, 9, 6}, 4)),
                "[2, 3, 3, 4]");
    }
}

/*
 * =====================================================================
 *  P040 Stack: Expression Evaluation and Nested Decoding   Canonical LC 150 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 150, Evaluate Reverse Polish Notation)
 *   tokens is an expression in postfix order with +, -, *, / (integer division truncating
 *   toward zero). Return its value.
 *
 * EXAMPLE
 *   ["2","1","+","3","*"]    ->  9      (2 + 1) * 3
 *   ["4","13","5","/","+"]   ->  6      4 + 13 / 5
 *
 * RECOGNIZE WHEN
 *   - Evaluate a string expression: postfix, infix with precedence, parentheses, unary
 *     minus.
 *   - Nested structures: "k[...]" repeats, nested lists, chemical formulas: work on the
 *     innermost level first and fold back out.
 *   Not this if: you only check that brackets match -> P036_MatchingStack.
 *
 * TEMPLATE
 *   postfix: number -> push; operator -> b = pop, a = pop, push(a op b)
 *   infix with + - * / (no parens): keep `last sign` and the current number; on the next
 *       operator, push +num / -num, or fold * and / into the top of the stack; sum at end
 *   parentheses: on '(' push (result so far, sign) and reset; on ')' pop and combine
 *   nested decode: on '[' push (string so far, count) and reset; on ']' pop and repeat
 *
 * APPROACH
 *   1. Numbers go on the stack.
 *   2. An operator takes the top two (the SECOND pop is the left operand) and pushes the
 *      result.
 *
 * KEY INSIGHT
 *   A stack holds "work suspended until something later arrives": operands waiting for an
 *   operator, a partial sum waiting for a ')', a prefix waiting for a ']'. Higher-precedence
 *   operators are applied immediately to the top; lower ones are deferred by pushing.
 *
 * COMPLEXITY
 *   Time O(n), space O(n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 227  Basic Calculator II      + - push signed numbers; * / combine with the
 *                                            top; answer = sum of the stack
 *   [coded] LC 224  Basic Calculator         + - and parentheses: stack of (result, sign)
 *   [coded] LC 394  Decode String            stacks of counts and string prefixes
 *           LC 772  Basic Calculator III     all of it: recursion on '(' with LC 227 inside
 *           LC 726  Number of Atoms          stack of count maps; multiply on ')'
 *           LC 1106 Parse Boolean Expression stack of chars; evaluate on ')'
 *           Infix to postfix (shunting-yard) operator stack ordered by precedence
 *
 * PITFALLS
 *   - Operand order for - and /: a = second pop, b = first pop, result a - b.
 *   - Java's / already truncates toward zero, as RPN requires.
 *   - Multi-digit numbers: build num = num * 10 + digit; spaces are skipped.
 *   - LC 227: process the LAST number too (treat the end of the string as an operator).
 *
 * DEEP DIVE
 *   C03_EvaluateReversePolishNotation, D05_BasicCalculator, C13_DecodeString,
 *   C15_InfixToPrefix (07-Stack-Queue-Monotonic)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.Deque;

class ExpressionEvaluation {

    // Canonical LC 150.
    static int evalRPN(String[] tokens) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (String t : tokens) {
            switch (t) {
                case "+" -> stack.push(stack.pop() + stack.pop());
                case "*" -> stack.push(stack.pop() * stack.pop());
                case "-" -> {
                    int b = stack.pop();
                    stack.push(stack.pop() - b);
                }
                case "/" -> {
                    int b = stack.pop();
                    stack.push(stack.pop() / b);
                }
                default -> stack.push(Integer.parseInt(t));
            }
        }
        return stack.pop();
    }

    // LC 227: + - * / and spaces, no parentheses.
    static int calculateII(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        int num = 0;
        char op = '+';                             // the operator BEFORE num
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                num = num * 10 + (c - '0');
            }
            if ((!Character.isDigit(c) && c != ' ') || i == s.length() - 1) {
                switch (op) {
                    case '+' -> stack.push(num);
                    case '-' -> stack.push(-num);
                    case '*' -> stack.push(stack.pop() * num);
                    default -> stack.push(stack.pop() / num);
                }
                op = c;
                num = 0;
            }
        }
        int sum = 0;
        for (int x : stack) {
            sum += x;
        }
        return sum;
    }

    // LC 224: + - and parentheses, unary minus allowed.
    static int calculate(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        int result = 0;
        int sign = 1;
        int num = 0;
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                num = num * 10 + (c - '0');
            } else if (c == '+' || c == '-') {
                result += sign * num;
                num = 0;
                sign = c == '+' ? 1 : -1;
            } else if (c == '(') {
                stack.push(result);                // suspend the outer sum
                stack.push(sign);                  // and the sign in front of '('
                result = 0;
                sign = 1;
            } else if (c == ')') {
                result += sign * num;
                num = 0;
                result = stack.pop() * result + stack.pop();
            }
        }
        return result + sign * num;
    }

    // LC 394.
    static String decodeString(String s) {
        Deque<Integer> counts = new ArrayDeque<>();
        Deque<StringBuilder> prefixes = new ArrayDeque<>();
        StringBuilder cur = new StringBuilder();
        int k = 0;
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                k = k * 10 + (c - '0');
            } else if (c == '[') {
                counts.push(k);
                prefixes.push(cur);
                cur = new StringBuilder();
                k = 0;
            } else if (c == ']') {
                String inner = cur.toString();
                cur = prefixes.pop();
                cur.append(inner.repeat(counts.pop()));
            } else {
                cur.append(c);
            }
        }
        return cur.toString();
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 150 (2+1)*3", evalRPN(new String[]{"2", "1", "+", "3", "*"}), 9);
        check("LC 150 4+13/5", evalRPN(new String[]{"4", "13", "5", "/", "+"}), 6);
        check("LC 150 thirteen tokens",
                evalRPN(new String[]{"10", "6", "9", "3", "+", "-11", "*", "/", "*",
                "17", "+", "5", "+"}), 22);

        check("LC 227 3+2*2", calculateII("3+2*2"), 7);
        check("LC 227 3/2 with spaces", calculateII(" 3/2 "), 1);
        check("LC 227 3+5 / 2", calculateII(" 3+5 / 2 "), 5);
        check("LC 227 14-3/2", calculateII("14-3/2"), 13);

        check("LC 224 1 + 1", calculate("1 + 1"), 2);
        check("LC 224 2-1 + 2", calculate(" 2-1 + 2 "), 3);
        check("LC 224 nested parentheses", calculate("(1+(4+5+2)-3)+(6+8)"), 23);
        check("LC 224 unary minus", calculate("-(2+3)"), -5);

        check("LC 394 3[a]2[bc]", decodeString("3[a]2[bc]"), "aaabcbc");
        check("LC 394 3[a2[c]] nested", decodeString("3[a2[c]]"), "accaccacc");
        check("LC 394 2[abc]3[cd]ef", decodeString("2[abc]3[cd]ef"), "abcabccdcdcdef");
        check("LC 394 10[a] two-digit count", decodeString("10[a]"), "aaaaaaaaaa");
    }
}

/*
 * =====================================================================
 *  P041 Stack Simulation: Collisions, Paths, Call Stacks   Canonical LC 735 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 735, Asteroid Collision)
 *   Each asteroid's absolute value is its size and its sign its direction (+ right,
 *   - left), all at the same speed. When two meet, the smaller explodes; equal sizes both
 *   explode. Return the asteroids left after all collisions.
 *
 * EXAMPLE
 *   [5, 10, -5]      ->  [5, 10]
 *   [8, -8]          ->  []
 *   [10, 2, -5]      ->  [10]           -5 destroys 2, then loses to 10
 *   [-2, -1, 1, 2]   ->  [-2, -1, 1, 2] moving apart: no collisions
 *
 * RECOGNIZE WHEN
 *   - A new item interacts with the MOST RECENT surviving item(s) and may cancel several
 *     of them: collisions, "..", undo, nested function calls with start/end timestamps.
 *   - Simulating the process step by step is the intended solution.
 *   Not this if: the interaction is only "next greater" -> P037_NextGreaterElement.
 *
 * TEMPLATE
 *   stack = []
 *   for item in items:
 *       while stack and item interacts with stack.top:
 *           resolve: pop the top, and/or destroy the item (then stop)
 *       if item survived: push(item)
 *   the stack (bottom -> top) is the final state
 *
 * APPROACH
 *   1. Only a left-mover arriving after a right-mover on the stack can collide.
 *   2. While that holds, compare sizes: pop smaller tops; on a tie pop and destroy; if
 *      the top is bigger, the new asteroid is destroyed.
 *
 * KEY INSIGHT
 *   Survivors to the left can only be hit by something arriving from the right, in
 *   reverse order of arrival: last in, first hit. That is a stack, and each asteroid is
 *   pushed and popped at most once.
 *
 * COMPLEXITY
 *   Time O(n), space O(n). LC 853: O(n log n) for the sort.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 71   Simplify Path            split on '/'; ".." pops, "." and "" skip
 *   [coded] LC 853  Car Fleet                sort by position descending; a car that
 *                                            arrives no later than the fleet ahead joins it
 *   [coded] LC 636  Exclusive Time           stack of running function ids; pause the top
 *                                            on start, credit time on end (end is inclusive)
 *           LC 2751 Robot Collisions         LC 735 with health that drops by 1 on a win
 *           LC 1598 Crawler Log Folder       a depth counter is enough
 *           LC 946  Validate Stack Sequences push in order, pop while top == next popped
 *
 * PITFALLS
 *   - LC 735: two left-movers or a left then right pair never collide.
 *   - LC 636: an end timestamp covers its whole unit: duration = end - start + 1.
 *   - LC 853: compare arrival TIMES as doubles (or cross-multiply), not distances.
 *
 * DEEP DIVE
 *   C11_AsteroidCollision, C12_SimplifyPath, C08_CarFleet, C14_ExclusiveTimeOfFunctions,
 *   D06_RobotCollisions (07-Stack-Queue-Monotonic)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;

class StackSimulation {

    // Canonical LC 735.
    static int[] asteroidCollision(int[] asteroids) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (int a : asteroids) {
            boolean alive = true;
            while (alive && a < 0 && !stack.isEmpty() && stack.peek() > 0) {
                int top = stack.peek();
                if (top < -a) {
                    stack.pop();                   // the right-mover explodes; keep checking
                } else {
                    if (top == -a) {
                        stack.pop();               // both explode
                    }
                    alive = false;
                }
            }
            if (alive) {
                stack.push(a);
            }
        }
        int[] out = new int[stack.size()];
        Iterator<Integer> it = stack.descendingIterator();   // bottom -> top
        for (int i = 0; i < out.length; i++) {
            out[i] = it.next();
        }
        return out;
    }

    // LC 71.
    static String simplifyPath(String path) {
        Deque<String> stack = new ArrayDeque<>();
        for (String part : path.split("/")) {
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.pop();
                }
            } else if (!part.isEmpty() && !part.equals(".")) {
                stack.push(part);
            }
        }
        StringBuilder sb = new StringBuilder();
        Iterator<String> it = stack.descendingIterator();
        while (it.hasNext()) {
            sb.append('/').append(it.next());
        }
        return sb.length() == 0 ? "/" : sb.toString();
    }

    // LC 853.
    static int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            order[i] = i;
        }
        Arrays.sort(order, (x, y) -> position[y] - position[x]);    // closest to target first
        int fleets = 0;
        double slowestAhead = 0;                   // arrival time of the fleet in front
        for (int i : order) {
            double time = (double) (target - position[i]) / speed[i];
            if (time > slowestAhead) {
                fleets++;                          // cannot catch up: a new fleet
                slowestAhead = time;
            }
        }
        return fleets;
    }

    // LC 636: logs "id:start|end:timestamp".
    static int[] exclusiveTime(int n, List<String> logs) {
        int[] total = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        int prev = 0;                              // start of the current unpaid stretch
        for (String log : logs) {
            String[] p = log.split(":");
            int id = Integer.parseInt(p[0]);
            int time = Integer.parseInt(p[2]);
            if (p[1].equals("start")) {
                if (!stack.isEmpty()) {
                    total[stack.peek()] += time - prev;
                }
                stack.push(id);
                prev = time;
            } else {
                total[stack.pop()] += time - prev + 1;
                prev = time + 1;
            }
        }
        return total;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 735 [5,10,-5]",
                Arrays.toString(asteroidCollision(new int[]{5, 10, -5})), "[5, 10]");
        check("LC 735 [8,-8]", Arrays.toString(asteroidCollision(new int[]{8, -8})), "[]");
        check("LC 735 [10,2,-5]", Arrays.toString(asteroidCollision(new int[]{10, 2, -5})), "[10]");
        check("LC 735 moving apart", Arrays.toString(asteroidCollision(new int[]{-2, -1, 1, 2})),
                "[-2, -1, 1, 2]");

        check("LC 71 /home/", simplifyPath("/home/"), "/home");
        check("LC 71 double slash", simplifyPath("/home//foo/"), "/home/foo");
        check("LC 71 dot-dot",
                simplifyPath("/home/user/Documents/../Pictures"), "/home/user/Pictures");
        check("LC 71 above root", simplifyPath("/../"), "/");
        check("LC 71 three dots is a name", simplifyPath("/.../a/../b/c/../d/./"), "/.../b/d");

        check("LC 853 five cars",
                carFleet(12, new int[]{10, 8, 0, 5, 3}, new int[]{2, 4, 1, 1, 3}), 3);
        check("LC 853 one car", carFleet(10, new int[]{3}, new int[]{3}), 1);
        check("LC 853 all merge", carFleet(100, new int[]{0, 2, 4}, new int[]{4, 2, 1}), 1);

        check("LC 636 two functions", Arrays.toString(exclusiveTime(2,
                List.of("0:start:0", "1:start:2", "1:end:5", "0:end:6"))), "[3, 4]");
        List<String> recursive = List.of("0:start:0", "0:start:2", "0:end:5",
                "0:start:6", "0:end:6", "0:end:7");
        check("LC 636 recursion", Arrays.toString(exclusiveTime(1, recursive)), "[8]");
    }
}

/*
 * =====================================================================
 *  P042 Monotonic Deque: Window Max / Min   Canonical LC 239 | Hard   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 239, Sliding Window Maximum)
 *   Return the maximum of every window of size k as it slides from left to right.
 *
 * EXAMPLE
 *   [1, 3, -1, -3, 5, 3, 6, 7], k = 3  ->  [3, 3, 5, 5, 6, 7]
 *   [1],                        k = 1  ->  [1]
 *
 * RECOGNIZE WHEN
 *   - A sliding window (fixed OR variable) needs its max or min at every step; a running
 *     sum would work for sums, but max/min cannot be "subtracted" when an element leaves.
 *   - DP where dp[i] = best of dp[j] over a sliding range of j (+ a[i]).
 *   - "shortest subarray with sum >= K" when values can be NEGATIVE.
 *   Not this if: the window aggregate is a sum or a count -> P015_FixedWindowAggregate; you
 *   need the median of the window -> P045_TwoHeaps.
 *
 * TEMPLATE
 *   dq = deque of indices, values decreasing from front to back (for max)
 *   for i in 0..n-1:
 *       while dq and a[dq.back] <= a[i]: dq.popBack()      // they can never be the max
 *       dq.pushBack(i)
 *       if dq.front <= i - k: dq.popFront()                 // fell out of the window
 *       if i >= k - 1: output a[dq.front]
 *
 * APPROACH
 *   1. Keep indices whose values are decreasing; the front is the window max.
 *   2. A new value removes every smaller value from the back: they are older AND smaller,
 *      so they can never be a maximum again.
 *   3. Drop the front when its index leaves the window.
 *
 * KEY INSIGHT
 *   An element that has a newer, bigger element behind it is useless for every future
 *   window. Removing such elements leaves a decreasing deque whose front is the answer,
 *   and each index enters and leaves once: O(n) total.
 *
 * COMPLEXITY
 *   Time O(n), space O(k).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 1438 Longest Abs Diff <= Limit variable window + TWO deques (max and min);
 *                                            shrink while max - min > limit
 *   [coded] LC 862  Shortest Sum >= K        deque of prefix-sum indices, increasing; pop
 *                                            the front while it gives a valid sum
 *   [coded] LC 1696 Jump Game VI             dp[i] = a[i] + max(dp[i-k..i-1]); deque of dp
 *           LC 1499 Max Value of Equation    max of (y - x) over a window of x
 *           LC 1425 Constrained Subseq Sum   LC 1696 where you may also start fresh
 *           LC 2398 Max Robots Within Budget variable window + max deque + running sum
 *
 * PITFALLS
 *   - Store INDICES, so you can tell when the front has left the window.
 *   - Pop the back with <= (for max) to keep the deque short; either works for
 *     correctness, but be consistent.
 *   - LC 862: sliding window fails with negatives; the deque of prefix sums is the fix.
 *
 * DEEP DIVE
 *   D04_SlidingWindowMaximum (07-Stack-Queue-Monotonic)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

class MonotonicDeque {

    // Canonical LC 239.
    static int[] maxSlidingWindow(int[] a, int k) {
        int[] out = new int[a.length - k + 1];
        Deque<Integer> dq = new ArrayDeque<>();
        for (int i = 0; i < a.length; i++) {
            while (!dq.isEmpty() && a[dq.peekLast()] <= a[i]) {
                dq.pollLast();
            }
            dq.offerLast(i);
            if (dq.peekFirst() <= i - k) {
                dq.pollFirst();
            }
            if (i >= k - 1) {
                out[i - k + 1] = a[dq.peekFirst()];
            }
        }
        return out;
    }

    // LC 1438.
    static int longestSubarray(int[] a, int limit) {
        Deque<Integer> maxQ = new ArrayDeque<>();
        Deque<Integer> minQ = new ArrayDeque<>();
        int left = 0;
        int best = 0;
        for (int right = 0; right < a.length; right++) {
            while (!maxQ.isEmpty() && a[maxQ.peekLast()] <= a[right]) {
                maxQ.pollLast();
            }
            maxQ.offerLast(right);
            while (!minQ.isEmpty() && a[minQ.peekLast()] >= a[right]) {
                minQ.pollLast();
            }
            minQ.offerLast(right);
            while (a[maxQ.peekFirst()] - a[minQ.peekFirst()] > limit) {
                left++;
                if (maxQ.peekFirst() < left) {
                    maxQ.pollFirst();
                }
                if (minQ.peekFirst() < left) {
                    minQ.pollFirst();
                }
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }

    // LC 862: values may be negative.
    static int shortestSubarray(int[] a, int k) {
        int n = a.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + a[i];
        }
        Deque<Integer> dq = new ArrayDeque<>();          // prefix indices, prefix increasing
        int best = Integer.MAX_VALUE;
        for (int j = 0; j <= n; j++) {
            while (!dq.isEmpty() && prefix[j] - prefix[dq.peekFirst()] >= k) {
                best = Math.min(best, j - dq.pollFirst());   // shortest for that start
            }
            while (!dq.isEmpty() && prefix[dq.peekLast()] >= prefix[j]) {
                dq.pollLast();                     // a later, smaller prefix is a better start
            }
            dq.offerLast(j);
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }

    // LC 1696: from index i you may jump 1..k forward; maximise the sum of visited values.
    static int maxResult(int[] a, int k) {
        int n = a.length;
        int[] dp = new int[n];
        dp[0] = a[0];
        Deque<Integer> dq = new ArrayDeque<>();
        dq.offerLast(0);
        for (int i = 1; i < n; i++) {
            if (dq.peekFirst() < i - k) {
                dq.pollFirst();
            }
            dp[i] = a[i] + dp[dq.peekFirst()];
            while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[i]) {
                dq.pollLast();
            }
            dq.offerLast(i);
        }
        return dp[n - 1];
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 239 k=3",
                Arrays.toString(maxSlidingWindow(new int[]{1, 3, -1, -3, 5, 3, 6, 7}, 3)),
                "[3, 3, 5, 5, 6, 7]");
        check("LC 239 k=1", Arrays.toString(maxSlidingWindow(new int[]{1}, 1)), "[1]");
        check("LC 239 decreasing",
                Arrays.toString(maxSlidingWindow(new int[]{9, 8, 7, 6}, 2)), "[9, 8, 7]");

        check("LC 1438 [8,2,4,7] limit=4", longestSubarray(new int[]{8, 2, 4, 7}, 4), 2);
        check("LC 1438 [10,1,2,4,7,2] limit=5",
                longestSubarray(new int[]{10, 1, 2, 4, 7, 2}, 5), 4);
        check("LC 1438 limit=0", longestSubarray(new int[]{4, 2, 2, 2, 4, 4, 2, 2}, 0), 3);

        check("LC 862 [1] k=1", shortestSubarray(new int[]{1}, 1), 1);
        check("LC 862 [1,2] k=4", shortestSubarray(new int[]{1, 2}, 4), -1);
        check("LC 862 [2,-1,2] k=3 negatives", shortestSubarray(new int[]{2, -1, 2}, 3), 3);
        check("LC 862 [84,-37,32,40,95] k=167",
                shortestSubarray(new int[]{84, -37, 32, 40, 95}, 167), 3);

        check("LC 1696 k=2", maxResult(new int[]{1, -1, -2, 4, -7, 3}, 2), 7);
        check("LC 1696 k=3", maxResult(new int[]{10, -5, -2, 4, 0, 3}, 3), 17);
        check("LC 1696 k=2 must cross negatives",
                maxResult(new int[]{1, -5, -20, 4, -1, 3, -6, -3}, 2), 0);
    }
}

