/*
 * =====================================================================
 *  P043 Top-K: Heap, Quickselect, Buckets   Canonical LC 215 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 215, Kth Largest Element in an Array)
 *   Return the k-th largest element of nums (k-th in sorted order, duplicates count).
 *   Can you do better than sorting?
 *
 * EXAMPLE
 *   [3, 2, 1, 5, 6, 4],          k = 2  ->  5
 *   [3, 2, 3, 1, 2, 4, 5, 5, 6], k = 4  ->  4
 *
 * RECOGNIZE WHEN
 *   - "k largest / smallest / most frequent / closest", "k-th largest".
 *   - k is much smaller than n, or the data arrives as a stream.
 *   Not this if: you need the median or both halves -> P045_TwoHeaps; you merge k SORTED
 *   lists -> P044_KWayMerge; the window slides -> P042_MonotonicDeque.
 *
 * TEMPLATE
 *   heap of size k ordered so that the WORST kept item is on top
 *       (k largest -> MIN-heap; k smallest / closest -> MAX-heap)
 *   for x in items:
 *       heap.offer(x)
 *       if heap.size() > k: heap.poll()        // evict the worst
 *   heap holds the answer; heap.peek() is the k-th
 *   alternatives: quickselect O(n) average; bucket sort when keys are small ints (counts)
 *
 * APPROACH
 *   1. Keep a min-heap of the k largest values seen so far.
 *   2. Every new value goes in; if the heap grows past k, the smallest leaves.
 *   3. The top of the heap is the k-th largest.
 *
 * KEY INSIGHT
 *   You never need the whole order, only a boundary. A size-k heap whose TOP is the
 *   current weakest member is that boundary: anything worse than the top is rejected in
 *   O(log k). Quickselect finds the boundary in place in O(n) average; buckets do it in
 *   O(n) when the key is a small count.
 *
 * COMPLEXITY
 *   Heap O(n log k) time, O(k) space. Quickselect O(n) average, O(n^2) worst, O(1) space.
 *   Buckets O(n) time and space.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 215 quickselect               partition until the pivot lands at n - k
 *   [coded] LC 347  Top K Frequent Elements  count, then bucket[count] = values; read the
 *                                            buckets from high to low
 *   [coded] LC 973  K Closest Points         max-heap by distance, size k
 *   [coded] LC 703  Kth Largest in a Stream  the heap lives in the object; add() is O(log k)
 *           LC 692  Top K Frequent Words     comparator: count desc, then word asc
 *           LC 658  K Closest Elements       sorted input: binary search the window start
 *           LC 451  Sort Characters by Freq  the bucket idea over characters
 *           LC 1985 Kth Largest String Num   comparator by length, then lexicographic
 *
 * PITFALLS
 *   - Java's PriorityQueue is a MIN-heap; use (a, b) -> b - a, or Collections.reverseOrder(),
 *     for a max-heap.
 *   - Comparators with a - b overflow for big ints; use Integer.compare.
 *   - Quickselect needs a random pivot to avoid O(n^2) on sorted input.
 *
 * DEEP DIVE
 *   A01_KthLargestElementInAStream, C01_topKFrequent, C02_KClosestPointsToOrigin
 *   (08-Heap-Priority-Queue), C01_QuickSelect (18-Sorting-Searching-Algorithms)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Random;

class TopK {

    // Canonical LC 215 with a size-k min-heap.
    static int findKthLargest(int[] nums, int k) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int x : nums) {
            heap.offer(x);
            if (heap.size() > k) {
                heap.poll();
            }
        }
        return heap.peek();
    }

    // LC 215 with quickselect: the answer is the value at sorted index n - k.
    static int findKthLargestQuickselect(int[] nums, int k) {
        int[] a = nums.clone();
        int target = a.length - k;
        int lo = 0;
        int hi = a.length - 1;
        Random rnd = new Random(1);
        while (true) {
            int p = partition(a, lo, hi, lo + rnd.nextInt(hi - lo + 1));
            if (p == target) {
                return a[p];
            } else if (p < target) {
                lo = p + 1;
            } else {
                hi = p - 1;
            }
        }
    }

    // Lomuto partition: returns the pivot's final index.
    private static int partition(int[] a, int lo, int hi, int pivotIndex) {
        swap(a, pivotIndex, hi);
        int store = lo;
        for (int i = lo; i < hi; i++) {
            if (a[i] < a[hi]) {
                swap(a, store++, i);
            }
        }
        swap(a, store, hi);
        return store;
    }

    private static void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }

    // LC 347 with bucket sort: bucket[c] holds the values that occur c times.
    static List<Integer> topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int x : nums) {
            count.merge(x, 1, Integer::sum);
        }
        List<List<Integer>> bucket = new ArrayList<>();
        for (int i = 0; i <= nums.length; i++) {
            bucket.add(new ArrayList<>());
        }
        count.forEach((value, c) -> bucket.get(c).add(value));
        List<Integer> out = new ArrayList<>();
        for (int c = nums.length; c >= 1 && out.size() < k; c--) {
            out.addAll(bucket.get(c));
        }
        List<Integer> top = new ArrayList<>(out.subList(0, k));
        Collections.sort(top);                     // any order is accepted; sorted to print
        return top;
    }

    // LC 973: max-heap by squared distance keeps the k closest.
    static int[][] kClosest(int[][] points, int k) {
        PriorityQueue<int[]> heap =
                new PriorityQueue<>((p, q) -> Integer.compare(dist(q), dist(p)));
        for (int[] p : points) {
            heap.offer(p);
            if (heap.size() > k) {
                heap.poll();
            }
        }
        int[][] out = heap.toArray(new int[0][]);
        Arrays.sort(out, (p, q) -> Integer.compare(dist(p), dist(q)));
        return out;
    }

    private static int dist(int[] p) {
        return p[0] * p[0] + p[1] * p[1];
    }

    // LC 703.
    static class KthLargest {
        private final PriorityQueue<Integer> heap = new PriorityQueue<>();
        private final int k;

        KthLargest(int k, int[] nums) {
            this.k = k;
            for (int x : nums) {
                add(x);
            }
        }

        int add(int val) {
            heap.offer(val);
            if (heap.size() > k) {
                heap.poll();
            }
            return heap.peek();
        }
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 215 heap k=2", findKthLargest(new int[]{3, 2, 1, 5, 6, 4}, 2), 5);
        check("LC 215 heap k=4 duplicates",
                findKthLargest(new int[]{3, 2, 3, 1, 2, 4, 5, 5, 6}, 4), 4);
        check("LC 215 quickselect k=2",
                findKthLargestQuickselect(new int[]{3, 2, 1, 5, 6, 4}, 2), 5);
        check("LC 215 quickselect k=4",
                findKthLargestQuickselect(new int[]{3, 2, 3, 1, 2, 4, 5, 5, 6}, 4), 4);
        check("LC 215 quickselect all equal", findKthLargestQuickselect(new int[]{7, 7, 7}, 2), 7);

        check("LC 347 k=2", topKFrequent(new int[]{1, 1, 1, 2, 2, 3}, 2), "[1, 2]");
        check("LC 347 k=1", topKFrequent(new int[]{1}, 1), "[1]");

        check("LC 973 k=1",
                Arrays.deepToString(kClosest(new int[][]{{1, 3}, {-2, 2}}, 1)), "[[-2, 2]]");
        check("LC 973 k=2", Arrays.deepToString(kClosest(new int[][]{{3, 3}, {5, -1}, {-2, 4}}, 2)),
                "[[3, 3], [-2, 4]]");

        KthLargest stream = new KthLargest(3, new int[]{4, 5, 8, 2});
        int[] adds = {3, 5, 10, 9, 4};
        int[] got = new int[adds.length];
        for (int i = 0; i < adds.length; i++) {
            got[i] = stream.add(adds[i]);
        }
        check("LC 703 k=3 stream", Arrays.toString(got), "[4, 5, 5, 8, 8]");
    }
}

/*
 * =====================================================================
 *  P044 Heap: K-Way Merge   Canonical LC 23 | Hard   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 23, Merge k Sorted Lists)
 *   Merge k sorted linked lists into one sorted list.
 *
 * EXAMPLE
 *   [[1,4,5],[1,3,4],[2,6]]  ->  [1,1,2,3,4,4,5,6]
 *   []                       ->  []
 *   [[]]                     ->  []
 *
 * RECOGNIZE WHEN
 *   - Several SORTED sequences (lists, rows of a matrix, "pairs from two sorted arrays")
 *     and you need the global order, the k-th smallest, or a range touching all of them.
 *   - The next candidate always comes from the "frontier": the current head of each
 *     sequence.
 *   Not this if: only two sequences -> P014_WalkTwoSequences or P033_DummyHeadMerge;
 *   unsorted input with "k largest" -> P043_TopK.
 *
 * TEMPLATE
 *   heap = min-heap of (value, which sequence, position in it)
 *   push the first element of every sequence
 *   while heap not empty (and you still need output):
 *       (v, s, i) = heap.poll(); emit v
 *       if sequence s has an element after i: push (next value, s, i + 1)
 *
 * APPROACH
 *   1. Put the head of every non-empty list in a min-heap.
 *   2. Repeatedly take the smallest head, append it, and push that list's next node.
 *
 * KEY INSIGHT
 *   The overall smallest remaining element is always one of the k current heads, so the
 *   heap only ever needs k entries. Each element passes through the heap once:
 *   O(N log k) instead of O(N log N) for "concatenate and sort".
 *
 * COMPLEXITY
 *   Time O(N log k) for N total elements, space O(k).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 378  Kth Smallest in Matrix   each row is a list; pop k times
 *   [coded] LC 373  K Pairs Smallest Sums    sequence i = pairs (a[i], b[0..]); push
 *                                            (i, 0) for every i, advance j on pop
 *   [coded] LC 632  Smallest Range k Lists   heap of current heads + the current max;
 *                                            the range is [heap.min, max]; stop when a
 *                                            list runs out
 *           LC 786  Kth Smallest Fraction    sequences a[i] / a[j] for each i
 *           LC 1439 Kth Smallest Sum of Rows merge rows two at a time, keep k smallest
 *           External sort                    the same merge over sorted files on disk
 *
 * PITFALLS
 *   - Skip empty lists when seeding the heap.
 *   - Store the sequence id and index with the value, or you cannot advance.
 *   - LC 373: seeding all (i, 0) pairs is O(k log k) if you seed only min(k, n) of them.
 *
 * DEEP DIVE
 *   D02_MergeKLists (06-Linked-List)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.PriorityQueue;

class KWayMerge {

    static class ListNode {
        int val;
        ListNode next;

        ListNode(int val) {
            this.val = val;
        }

        static ListNode of(int... vals) {
            ListNode dummy = new ListNode(0);
            ListNode cur = dummy;
            for (int v : vals) {
                cur.next = new ListNode(v);
                cur = cur.next;
            }
            return dummy.next;
        }
    }

    static String show(ListNode head) {
        StringBuilder sb = new StringBuilder("[");
        for (ListNode n = head; n != null; n = n.next) {
            sb.append(n.val).append(n.next == null ? "" : ",");
        }
        return sb.append("]").toString();
    }

    // Canonical LC 23.
    static ListNode mergeKLists(ListNode[] lists) {
        PriorityQueue<ListNode> heap = new PriorityQueue<>((a, b) -> Integer.compare(a.val, b.val));
        for (ListNode head : lists) {
            if (head != null) {
                heap.offer(head);
            }
        }
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        while (!heap.isEmpty()) {
            ListNode smallest = heap.poll();
            tail.next = smallest;
            tail = smallest;
            if (smallest.next != null) {
                heap.offer(smallest.next);
            }
        }
        return dummy.next;
    }

    // LC 378: heap entries are {value, row, col}.
    static int kthSmallest(int[][] m, int k) {
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        for (int r = 0; r < m.length; r++) {
            heap.offer(new int[]{m[r][0], r, 0});
        }
        for (int i = 1; i < k; i++) {
            int[] e = heap.poll();
            if (e[2] + 1 < m[e[1]].length) {
                heap.offer(new int[]{m[e[1]][e[2] + 1], e[1], e[2] + 1});
            }
        }
        return heap.peek()[0];
    }

    // LC 373: heap entries are {sum, i, j}.
    static List<List<Integer>> kSmallestPairs(int[] a, int[] b, int k) {
        PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        for (int i = 0; i < Math.min(a.length, k); i++) {
            heap.offer(new int[]{a[i] + b[0], i, 0});
        }
        List<List<Integer>> out = new ArrayList<>();
        while (!heap.isEmpty() && out.size() < k) {
            int[] e = heap.poll();
            out.add(Arrays.asList(a[e[1]], b[e[2]]));
            if (e[2] + 1 < b.length) {
                heap.offer(new int[]{a[e[1]] + b[e[2] + 1], e[1], e[2] + 1});
            }
        }
        return out;
    }

    // LC 632: smallest [lo, hi] that contains at least one number from every list.
    static int[] smallestRange(List<List<Integer>> nums) {
        PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        int max = Integer.MIN_VALUE;
        for (int i = 0; i < nums.size(); i++) {
            int v = nums.get(i).get(0);
            heap.offer(new int[]{v, i, 0});
            max = Math.max(max, v);
        }
        int[] best = {heap.peek()[0], max};
        while (true) {
            int[] e = heap.poll();                 // the current minimum
            if (max - e[0] < best[1] - best[0]) {
                best = new int[]{e[0], max};
            }
            List<Integer> list = nums.get(e[1]);
            if (e[2] + 1 == list.size()) {
                return best;                       // this list is used up
            }
            int next = list.get(e[2] + 1);
            max = Math.max(max, next);
            heap.offer(new int[]{next, e[1], e[2] + 1});
        }
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        ListNode[] three = {ListNode.of(1, 4, 5), ListNode.of(1, 3, 4), ListNode.of(2, 6)};
        check("LC 23 three lists", show(mergeKLists(three)), "[1,1,2,3,4,4,5,6]");
        check("LC 23 no lists", show(mergeKLists(new ListNode[]{})), "[]");
        check("LC 23 one empty list", show(mergeKLists(new ListNode[]{null})), "[]");

        check("LC 378 k=8", kthSmallest(new int[][]{{1, 5, 9}, {10, 11, 13}, {12, 13, 15}}, 8), 13);
        check("LC 378 k=1", kthSmallest(new int[][]{{-5}}, 1), -5);

        check("LC 373 k=3", kSmallestPairs(new int[]{1, 7, 11}, new int[]{2, 4, 6}, 3),
                "[[1, 2], [1, 4], [1, 6]]");
        check("LC 373 k=2 duplicates", kSmallestPairs(new int[]{1, 1, 2}, new int[]{1, 2, 3}, 2),
                "[[1, 1], [1, 1]]");

        List<List<Integer>> lists = List.of(List.of(4, 10, 15, 24, 26), List.of(0, 9, 12, 20),
                List.of(5, 18, 22, 30));
        check("LC 632 three lists", Arrays.toString(smallestRange(lists)), "[20, 24]");
        List<List<Integer>> same = List.of(List.of(1, 2, 3), List.of(1, 2, 3), List.of(1, 2, 3));
        check("LC 632 identical lists", Arrays.toString(smallestRange(same)), "[1, 1]");
    }
}

/*
 * =====================================================================
 *  P045 Two Heaps: Running Median and Split Choices   Canonical LC 295 | Hard   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 295, Find Median from Data Stream)
 *   Support addNum(x) and findMedian() over a stream of integers. The median of an even
 *   count is the mean of the two middle values.
 *
 * EXAMPLE
 *   addNum(1), addNum(2), findMedian() -> 1.5, addNum(3), findMedian() -> 2.0
 *
 * RECOGNIZE WHEN
 *   - Median (or any "middle" order statistic) of a stream or of a sliding window.
 *   - The data splits into a "lower half" and an "upper half" and you need the border.
 *   - Two pools where you move items from one to the other as a budget grows (IPO:
 *     "locked" projects become "affordable" ones).
 *   Not this if: you need the k largest only -> P043_TopK (one heap).
 *
 * TEMPLATE
 *   low = max-heap (smaller half), high = min-heap (larger half)
 *   add(x): push x into low; move low.top to high; if high.size > low.size: move back
 *   invariant: low.size == high.size or low.size == high.size + 1, and low.top <= high.top
 *   median = low.size > high.size ? low.top : (low.top + high.top) / 2.0
 *
 * APPROACH
 *   1. Every new number goes through low and then high, so the order invariant holds.
 *   2. Rebalance sizes so low has the extra element when the count is odd.
 *   3. The median is read from the two tops in O(1).
 *
 * KEY INSIGHT
 *   The median only depends on the BORDER between the halves. Two heaps facing each other
 *   expose exactly that border at their tops, with O(log n) insertion and O(1) reads,
 *   instead of re-sorting.
 *
 * COMPLEXITY
 *   addNum O(log n), findMedian O(1), space O(n). Sliding window: O(n log k).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 480  Sliding Window Median    two ordered sets of INDICES (so a specific
 *                                            element can be removed when it leaves)
 *   [coded] LC 502  IPO                      min-heap by capital (locked), max-heap by
 *                                            profit (affordable); unlock, take the best
 *           LC 1825 Finding MK Average       three ordered multisets: low, middle, high
 *           LC 857  Min Cost to Hire Workers sort by wage/quality, max-heap of qualities
 *           LC 2102 Location Ranking Tracker the same two-heap border, moved one per query
 *
 * PITFALLS
 *   - (a + b) / 2 overflows for big ints; use (a + (double) b) / 2.
 *   - PriorityQueue.remove(Object) is O(k); for windows use TreeSet / TreeMap or lazy
 *     deletion.
 *   - TreeSet of values loses duplicates; store indices with a (value, index) comparator.
 *
 * DEEP DIVE
 *   D01_MedianOfStream, D02_SlidingWindowMedian (08-Heap-Priority-Queue)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.TreeSet;

class TwoHeaps {

    // Canonical LC 295.
    static class MedianFinder {
        private final PriorityQueue<Integer> low = new PriorityQueue<>(Collections.reverseOrder());
        private final PriorityQueue<Integer> high = new PriorityQueue<>();

        void addNum(int x) {
            low.offer(x);
            high.offer(low.poll());
            if (high.size() > low.size()) {
                low.offer(high.poll());
            }
        }

        double findMedian() {
            return low.size() > high.size() ? low.peek() : (low.peek() + (double) high.peek()) / 2;
        }
    }

    // LC 480: ordered sets of indices, ordered by (value, index) so duplicates survive.
    static double[] medianSlidingWindow(int[] nums, int k) {
        Comparator<Integer> byValue = (i, j) -> nums[i] != nums[j]
                ? Integer.compare(nums[i], nums[j]) : Integer.compare(i, j);
        TreeSet<Integer> low = new TreeSet<>(byValue);
        TreeSet<Integer> high = new TreeSet<>(byValue);
        double[] out = new double[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            if (i >= k && !low.remove(i - k)) {
                high.remove(i - k);                // the leaving index is in one of them
            }
            low.add(i);
            high.add(low.pollLast());
            while (high.size() > low.size()) {
                low.add(high.pollFirst());
            }
            if (i >= k - 1) {
                out[i - k + 1] = k % 2 == 1 ? nums[low.last()]
                        : (nums[low.last()] + (double) nums[high.first()]) / 2;
            }
        }
        return out;
    }

    // LC 502: start with capital w, finish at most k projects, maximise final capital.
    static int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        PriorityQueue<Integer> locked =
                new PriorityQueue<>((i, j) -> Integer.compare(capital[i], capital[j]));
        PriorityQueue<Integer> affordable =
                new PriorityQueue<>((i, j) -> Integer.compare(profits[j], profits[i]));
        for (int i = 0; i < profits.length; i++) {
            locked.offer(i);
        }
        for (int done = 0; done < k; done++) {
            while (!locked.isEmpty() && capital[locked.peek()] <= w) {
                affordable.offer(locked.poll());
            }
            if (affordable.isEmpty()) {
                break;
            }
            w += profits[affordable.poll()];
        }
        return w;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        MedianFinder mf = new MedianFinder();
        mf.addNum(1);
        mf.addNum(2);
        check("LC 295 after 1,2", mf.findMedian(), 1.5);
        mf.addNum(3);
        check("LC 295 after 1,2,3", mf.findMedian(), 2.0);
        MedianFinder big = new MedianFinder();
        big.addNum(Integer.MAX_VALUE);
        big.addNum(Integer.MAX_VALUE);
        check("LC 295 overflow trap", big.findMedian(), 2.147483647E9);

        check("LC 480 k=3",
                Arrays.toString(medianSlidingWindow(new int[]{1, 3, -1, -3, 5, 3, 6, 7}, 3)),
                "[1.0, -1.0, -1.0, 3.0, 5.0, 6.0]");
        check("LC 480 k=3 duplicates",
                Arrays.toString(medianSlidingWindow(new int[]{1, 2, 3, 4, 2, 3, 1, 4, 2}, 3)),
                "[2.0, 3.0, 3.0, 3.0, 2.0, 3.0, 2.0]");
        check("LC 480 k=2 even", Arrays.toString(medianSlidingWindow(new int[]{1, 4, 2, 3}, 2)),
                "[2.5, 3.0, 2.5]");

        check("LC 502 k=2 w=0",
                findMaximizedCapital(2, 0, new int[]{1, 2, 3}, new int[]{0, 1, 1}), 4);
        check("LC 502 k=3 w=0",
                findMaximizedCapital(3, 0, new int[]{1, 2, 3}, new int[]{0, 1, 2}), 6);
        check("LC 502 nothing affordable",
                findMaximizedCapital(1, 0, new int[]{5}, new int[]{1}), 0);
    }
}

/*
 * =====================================================================
 *  P046 Heap-Driven Greedy Scheduling   Canonical LC 621 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 621, Task Scheduler)
 *   Tasks are letters; each takes one unit of time. Two runs of the same letter must be at
 *   least n units apart (idle units allowed). Return the minimum total time.
 *
 * EXAMPLE
 *   [A,A,A,B,B,B], n = 2                    ->  8     A B idle A B idle A B
 *   [A,A,A,B,B,B], n = 0                    ->  6
 *   [A,A,A,A,A,A,B,C,D,E,F,G], n = 2        ->  16
 *
 * RECOGNIZE WHEN
 *   - At every step you must pick "the best available option right now" (most frequent,
 *     biggest gain, earliest deadline), and options keep changing as time passes.
 *   - Deferred decisions: "use the ladder on the biggest climbs", "refuel at the best
 *     station you already passed" -- choose in hindsight from a heap of passed options.
 *   Not this if: one sort decides everything up front -> P096_SortAndPair or
 *   P049_SortByEndGreedy.
 *
 * TEMPLATE
 *   heap of available options, ordered by the greedy key
 *   for each step / event in time order:
 *       add newly available options to the heap
 *       take the best one (or the best k), apply it, re-insert what is left of it
 *   hindsight version: push every passed option; when you are stuck, pop the best one
 *   you could have used
 *
 * APPROACH
 *   1. Count tasks; a max-heap holds the remaining counts.
 *   2. Each cycle of n + 1 slots runs up to n + 1 DIFFERENT tasks, most frequent first.
 *   3. Put back the reduced counts. A cycle is n + 1 long unless the heap is empty after it.
 *
 * KEY INSIGHT
 *   Always run the task with the most copies left, because it is the one most likely to
 *   force idle time later. The heap answers "which is most urgent now?" in O(log k). The
 *   closed form (maxCount - 1) * (n + 1) + (number of tasks with maxCount), floored at the
 *   task count, is the same greedy counted directly.
 *
 * COMPLEXITY
 *   Time O(T log 26) = O(T) for T tasks, space O(26).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 621 formula                   (maxCount - 1) * (n + 1) + numberWithMax
 *   [coded] LC 767  Reorganize String        pop the two most frequent letters per step
 *   [coded] LC 1642 Furthest Building        min-heap of climbs on ladders; when it holds
 *                                            more than `ladders`, pay its smallest in bricks
 *   [coded] LC 871  Min Refueling Stops      max-heap of fuel at passed stations; refuel
 *                                            from the best one only when you run dry
 *           LC 1353 Max Events Attended      by day: add starting events, attend the one
 *                                            ending soonest (min-heap of end days)
 *           LC 630  Course Schedule III      sort by deadline; max-heap of durations; drop
 *                                            the longest course when over time
 *           LC 1834 Single-Threaded CPU      events by enqueue time; heap by (time, index)
 *           LC 2402 Meeting Rooms III        heap of free rooms + heap of busy rooms
 *
 * PITFALLS
 *   - LC 621: the answer is at least tasks.length (no idling needed when many letters).
 *   - LC 767: impossible when the top count > (n + 1) / 2; return "".
 *   - "Hindsight" greedy: pop from the heap only when forced, not at every step.
 *
 * DEEP DIVE
 *   C04_ReorganizeString, C07_FurthestBuildingYouCanReach, D03_MinimumRefuelingStops,
 *   C06_MaximumNumberofEventsThatCanBeAttended (08-Heap-Priority-Queue)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;

class HeapSchedulingGreedy {

    // Canonical LC 621, simulated with a max-heap of remaining counts.
    static int leastInterval(char[] tasks, int n) {
        int[] count = new int[26];
        for (char t : tasks) {
            count[t - 'A']++;
        }
        PriorityQueue<Integer> heap = new PriorityQueue<>((a, b) -> b - a);
        for (int c : count) {
            if (c > 0) {
                heap.offer(c);
            }
        }
        int time = 0;
        while (!heap.isEmpty()) {
            List<Integer> leftover = new ArrayList<>();
            int slots = 0;
            while (slots < n + 1 && !heap.isEmpty()) {
                int c = heap.poll();
                if (c > 1) {
                    leftover.add(c - 1);
                }
                slots++;
            }
            heap.addAll(leftover);
            time += heap.isEmpty() ? slots : n + 1;   // the last cycle needs no idle tail
        }
        return time;
    }

    // LC 621 closed form.
    static int leastIntervalFormula(char[] tasks, int n) {
        int[] count = new int[26];
        int max = 0;
        for (char t : tasks) {
            max = Math.max(max, ++count[t - 'A']);
        }
        int withMax = 0;
        for (int c : count) {
            if (c == max) {
                withMax++;
            }
        }
        return Math.max(tasks.length, (max - 1) * (n + 1) + withMax);
    }

    // LC 767: no two equal neighbours; "" if impossible.
    static String reorganizeString(String s) {
        int[] count = new int[26];
        for (char c : s.toCharArray()) {
            count[c - 'a']++;
        }
        PriorityQueue<Integer> heap = new PriorityQueue<>(
                (a, b) -> count[a] != count[b] ? count[b] - count[a] : a - b);
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                heap.offer(i);
            }
        }
        StringBuilder sb = new StringBuilder();
        while (heap.size() >= 2) {
            int a = heap.poll();
            int b = heap.poll();
            sb.append((char) ('a' + a)).append((char) ('a' + b));
            if (--count[a] > 0) {
                heap.offer(a);
            }
            if (--count[b] > 0) {
                heap.offer(b);
            }
        }
        if (!heap.isEmpty()) {
            int last = heap.poll();
            if (count[last] > 1) {
                return "";
            }
            sb.append((char) ('a' + last));
        }
        return sb.toString();
    }

    // LC 1642: ladders go to the largest climbs seen so far, bricks pay for the rest.
    static int furthestBuilding(int[] heights, int bricks, int ladders) {
        PriorityQueue<Integer> climbsOnLadders = new PriorityQueue<>();
        for (int i = 0; i + 1 < heights.length; i++) {
            int climb = heights[i + 1] - heights[i];
            if (climb <= 0) {
                continue;
            }
            climbsOnLadders.offer(climb);
            if (climbsOnLadders.size() > ladders) {
                bricks -= climbsOnLadders.poll();     // the smallest climb gets bricks
                if (bricks < 0) {
                    return i;
                }
            }
        }
        return heights.length - 1;
    }

    // LC 871: stations[i] = {position, fuel}.
    static int minRefuelStops(int target, int startFuel, int[][] stations) {
        PriorityQueue<Integer> passed = new PriorityQueue<>((a, b) -> b - a);
        long reach = startFuel;
        int stops = 0;
        int i = 0;
        while (reach < target) {
            while (i < stations.length && stations[i][0] <= reach) {
                passed.offer(stations[i++][1]);
            }
            if (passed.isEmpty()) {
                return -1;
            }
            reach += passed.poll();                   // refuel in hindsight at the best one
            stops++;
        }
        return stops;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        char[] six = "AAABBB".toCharArray();
        check("LC 621 heap n=2", leastInterval(six, 2), 8);
        check("LC 621 heap n=0", leastInterval(six, 0), 6);
        check("LC 621 heap n=2 many letters", leastInterval("AAAAAABCDEFG".toCharArray(), 2), 16);
        check("LC 621 formula n=2", leastIntervalFormula(six, 2), 8);
        check("LC 621 formula no idling", leastIntervalFormula("ACABDB".toCharArray(), 1), 6);

        check("LC 767 aab", reorganizeString("aab"), "aba");
        check("LC 767 aaab impossible", "[" + reorganizeString("aaab") + "]", "[]");
        check("LC 767 vvvlo", reorganizeString("vvvlo"), "vlvov");

        check("LC 1642 b=5 l=1", furthestBuilding(new int[]{4, 2, 7, 6, 9, 14, 12}, 5, 1), 4);
        check("LC 1642 b=10 l=2",
                furthestBuilding(new int[]{4, 12, 2, 7, 3, 18, 20, 3, 19}, 10, 2), 7);
        check("LC 1642 b=17 l=0", furthestBuilding(new int[]{14, 3, 19, 3}, 17, 0), 3);

        check("LC 871 already there", minRefuelStops(1, 1, new int[][]{}), 0);
        check("LC 871 cannot reach", minRefuelStops(100, 1, new int[][]{{10, 100}}), -1);
        check("LC 871 two stops",
                minRefuelStops(100, 10, new int[][]{{10, 60}, {20, 30}, {30, 30}, {60, 40}}), 2);
    }
}

/*
 * =====================================================================
 *  P047 Ordered Map: TreeMap floor / ceiling   Canonical LC 729 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 729, My Calendar I)
 *   book(start, end) adds the half-open event [start, end) if it does not overlap any
 *   booked event, and returns whether it was added.
 *
 * EXAMPLE
 *   book(10, 20) -> true, book(15, 25) -> false, book(20, 30) -> true
 *
 * RECOGNIZE WHEN
 *   - You keep inserting / deleting AND need "the nearest key below / above x" (floor,
 *     ceiling, lower, higher) or the smallest / largest key, all in O(log n).
 *   - Interval bookings, "is there a value within t of x among the last k", grouping
 *     consecutive values, counts that must be consumed smallest first.
 *   Not this if: you only need the min or max, never "nearest to x" -> a heap is lighter
 *   (P043_TopK); the keys are static and sorted -> binary search (P023_BoundarySearch).
 *
 * TEMPLATE
 *   TreeMap<Integer, V> map / TreeSet<Integer> set
 *   below = map.floorKey(x)     (<= x)     lower = map.lowerKey(x)    (< x)
 *   above = map.ceilingKey(x)   (>= x)     higher = map.higherKey(x)  (> x)
 *   map.firstKey(), map.lastKey(), map.headMap(x), map.tailMap(x)
 *   diff-map sweep: map.merge(start, +1), map.merge(end, -1), walk values in key order
 *
 * APPROACH
 *   1. Store booked events as start -> end in a TreeMap.
 *   2. The only events that can clash with [s, e) are the one starting just before s
 *      (floor) and the one starting at or after s (ceiling).
 *   3. Book if prev.end <= s and next.start >= e.
 *
 * KEY INSIGHT
 *   A balanced BST keeps keys sorted under updates, so "neighbours of x" are O(log n)
 *   questions. Many problems reduce to checking just the two neighbours of a new key
 *   instead of every existing key.
 *
 * COMPLEXITY
 *   O(log n) per operation for floor / ceiling / put / remove. LC 731 diff sweep: O(n) per
 *   booking.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 220  Contains Duplicate III   TreeSet of the last k values; ceiling(x - t)
 *                                            must be <= x + t
 *   [coded] LC 846  Hand of Straights        TreeMap of counts; always start a group at
 *                                            firstKey() and consume k consecutive keys
 *   [coded] LC 731  My Calendar II           diff map (+1 at start, -1 at end); reject if
 *                                            the running sum ever reaches 3
 *           LC 732  My Calendar III          the same sweep; answer = max running sum
 *           LC 352  Data Stream Intervals    floor / ceiling neighbours merge on insert
 *           LC 218  The Skyline Problem      events + TreeMap of active heights (counts)
 *           LC 2034 Stock Price Fluctuation  map time -> price + TreeMap price -> count
 *           LC 981  Time Based Key-Value     floorKey(timestamp) -> P104_VersionedTimeMap
 *
 * PITFALLS
 *   - floorKey / ceilingKey return null when nothing qualifies; check before unboxing.
 *   - TreeSet drops duplicates; keep counts in a TreeMap when values repeat.
 *   - LC 220: x - t and x + t overflow int; use long.
 *
 * DEEP DIVE
 *   C08_StockPriceFluctuation, C06_TimeBasedKeyValueStore (19-Design-Data-Structures)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;

class TreeMapFloorCeiling {

    // Canonical LC 729.
    static class MyCalendar {
        private final TreeMap<Integer, Integer> events = new TreeMap<>();   // start -> end

        boolean book(int start, int end) {
            Map.Entry<Integer, Integer> prev = events.floorEntry(start);
            Map.Entry<Integer, Integer> next = events.ceilingEntry(start);
            boolean clashBefore = prev != null && prev.getValue() > start;
            boolean clashAfter = next != null && next.getKey() < end;
            if (clashBefore || clashAfter) {
                return false;
            }
            events.put(start, end);
            return true;
        }
    }

    // LC 220: indices at most indexDiff apart, values at most valueDiff apart.
    static boolean containsNearbyAlmostDuplicate(int[] nums, int indexDiff, int valueDiff) {
        TreeSet<Long> window = new TreeSet<>();
        for (int i = 0; i < nums.length; i++) {
            Long candidate = window.ceiling((long) nums[i] - valueDiff);
            if (candidate != null && candidate <= (long) nums[i] + valueDiff) {
                return true;
            }
            window.add((long) nums[i]);
            if (i >= indexDiff) {
                window.remove((long) nums[i - indexDiff]);
            }
        }
        return false;
    }

    // LC 846: split the hand into groups of groupSize consecutive cards.
    static boolean isNStraightHand(int[] hand, int groupSize) {
        TreeMap<Integer, Integer> count = new TreeMap<>();
        for (int card : hand) {
            count.merge(card, 1, Integer::sum);
        }
        while (!count.isEmpty()) {
            int first = count.firstKey();              // the smallest card must start a group
            for (int card = first; card < first + groupSize; card++) {
                Integer c = count.get(card);
                if (c == null) {
                    return false;
                }
                if (c == 1) {
                    count.remove(card);
                } else {
                    count.put(card, c - 1);
                }
            }
        }
        return true;
    }

    // LC 731: no point may be covered three times.
    static class MyCalendarTwo {
        private final TreeMap<Integer, Integer> diff = new TreeMap<>();

        boolean book(int start, int end) {
            diff.merge(start, 1, Integer::sum);
            diff.merge(end, -1, Integer::sum);
            int active = 0;
            for (int delta : diff.values()) {
                active += delta;
                if (active >= 3) {
                    diff.merge(start, -1, Integer::sum);   // undo
                    diff.merge(end, 1, Integer::sum);
                    return false;
                }
            }
            return true;
        }
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        MyCalendar cal = new MyCalendar();
        List<Boolean> got = new ArrayList<>();
        got.add(cal.book(10, 20));
        got.add(cal.book(15, 25));
        got.add(cal.book(20, 30));
        check("LC 729 three bookings", got, "[true, false, true]");
        check("LC 729 inside a gap", cal.book(5, 10), true);
        check("LC 729 covering an event", cal.book(0, 40), false);

        check("LC 220 [1,2,3,1] k=3 t=0",
                containsNearbyAlmostDuplicate(new int[]{1, 2, 3, 1}, 3, 0), true);
        check("LC 220 [1,5,9,1,5,9] k=2 t=3",
                containsNearbyAlmostDuplicate(new int[]{1, 5, 9, 1, 5, 9}, 2, 3), false);
        int[] extremes = {Integer.MIN_VALUE, Integer.MAX_VALUE};
        check("LC 220 overflow trap", containsNearbyAlmostDuplicate(extremes, 1, 1), false);

        check("LC 846 groups of 3", isNStraightHand(new int[]{1, 2, 3, 6, 2, 3, 4, 7, 8}, 3), true);
        check("LC 846 groups of 4", isNStraightHand(new int[]{1, 2, 3, 4, 5}, 4), false);

        MyCalendarTwo two = new MyCalendarTwo();
        List<Boolean> got2 = new ArrayList<>();
        int[][] books = {{10, 20}, {50, 60}, {10, 40}, {5, 15}, {5, 10}, {25, 55}};
        for (int[] b : books) {
            got2.add(two.book(b[0], b[1]));
        }
        check("LC 731 six bookings", got2, "[true, true, true, false, true, true]");
    }
}

