/*
 * =====================================================================
 *  P048 Intervals: Sort by Start and Merge   Canonical LC 56 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 56, Merge Intervals)
 *   Merge all overlapping intervals and return the non-overlapping intervals that cover
 *   exactly the same points.
 *
 * EXAMPLE
 *   [[1,3],[2,6],[8,10],[15,18]]  ->  [[1,6],[8,10],[15,18]]
 *   [[1,4],[4,5]]                 ->  [[1,5]]        touching counts as overlapping
 *   [[1,4],[2,3]]                 ->  [[1,4]]        the trap: one inside the other
 *
 * RECOGNIZE WHEN
 *   - Ranges / meetings / bookings and the question is about their UNION: merge, insert,
 *     "do any overlap", "total covered length", "free time".
 *   - Two sorted lists of ranges to intersect.
 *   Not this if: you must keep as many as possible or remove the fewest -> sort by END
 *   (P049_SortByEndGreedy); you need how many overlap at once -> P050_SweepLineMinRooms.
 *
 * TEMPLATE
 *   sort by start
 *   merged = [first]
 *   for [s, e] in the rest:
 *       last = merged.back
 *       if s <= last.end: last.end = max(last.end, e)     // overlap: extend
 *       else:             merged.append([s, e])           // gap: new block
 *
 * APPROACH
 *   1. Sort by start, so any interval that overlaps the current block comes right after it.
 *   2. Extend the block's end with max(); otherwise start a new block.
 *
 * KEY INSIGHT
 *   After sorting by start, an interval can only overlap the LAST merged block, never an
 *   earlier one, so one linear pass finishes the job. Use max() for the end: a short
 *   interval inside a long one must not shrink it.
 *
 * COMPLEXITY
 *   Time O(n log n) for the sort, then O(n). Space O(n) for the output.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 57   Insert Interval          input already sorted: copy those ending before,
 *                                            merge the overlapping run, copy the rest; O(n)
 *   [coded] LC 252  Meeting Rooms            sort by start; any start < previous end fails
 *   [coded] LC 986  Interval Intersections   two pointers: overlap = [max starts, min ends];
 *                                            advance whichever interval ends first
 *           LC 759  Employee Free Time       merge everyone's intervals, report the gaps
 *           LC 228  Summary Ranges           merge runs of consecutive integers
 *           LC 1288 Remove Covered Intervals sort start asc, end DESC; count new max ends
 *           Total covered length             merge, then sum (end - start)
 *
 * PITFALLS
 *   - Touching intervals: does [1,4] + [4,5] merge? Here yes (s <= end); check the
 *     problem's definition of overlap.
 *   - Comparator a[0] - b[0] overflows for extreme values; use Integer.compare.
 *   - LC 986: after taking an overlap, advance the one with the smaller END.
 *
 * DEEP DIVE
 *   A02_MergeIntervals, C01_InsertInterval, A01_MeetingRooms,
 *   C02_IntervalListIntersections (15-Intervals)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class MergeIntervals {

    // Canonical LC 56.
    static int[][] merge(int[][] intervals) {
        int[][] a = intervals.clone();
        Arrays.sort(a, (x, y) -> Integer.compare(x[0], y[0]));
        List<int[]> merged = new ArrayList<>();
        for (int[] cur : a) {
            if (!merged.isEmpty() && cur[0] <= merged.get(merged.size() - 1)[1]) {
                int[] last = merged.get(merged.size() - 1);
                last[1] = Math.max(last[1], cur[1]);
            } else {
                merged.add(new int[]{cur[0], cur[1]});
            }
        }
        return merged.toArray(new int[0][]);
    }

    // LC 57: intervals are sorted and non-overlapping.
    static int[][] insert(int[][] intervals, int[] add) {
        List<int[]> out = new ArrayList<>();
        int i = 0;
        int n = intervals.length;
        while (i < n && intervals[i][1] < add[0]) {
            out.add(intervals[i++]);                 // entirely before
        }
        int start = add[0];
        int end = add[1];
        while (i < n && intervals[i][0] <= end) {
            start = Math.min(start, intervals[i][0]);   // overlapping run
            end = Math.max(end, intervals[i][1]);
            i++;
        }
        out.add(new int[]{start, end});
        while (i < n) {
            out.add(intervals[i++]);                 // entirely after
        }
        return out.toArray(new int[0][]);
    }

    // LC 252: can one person attend every meeting?
    static boolean canAttendMeetings(int[][] intervals) {
        int[][] a = intervals.clone();
        Arrays.sort(a, (x, y) -> Integer.compare(x[0], y[0]));
        for (int i = 1; i < a.length; i++) {
            if (a[i][0] < a[i - 1][1]) {
                return false;
            }
        }
        return true;
    }

    // LC 986.
    static int[][] intervalIntersection(int[][] first, int[][] second) {
        List<int[]> out = new ArrayList<>();
        int i = 0;
        int j = 0;
        while (i < first.length && j < second.length) {
            int lo = Math.max(first[i][0], second[j][0]);
            int hi = Math.min(first[i][1], second[j][1]);
            if (lo <= hi) {
                out.add(new int[]{lo, hi});
            }
            if (first[i][1] < second[j][1]) {
                i++;
            } else {
                j++;
            }
        }
        return out.toArray(new int[0][]);
    }

    static String show(int[][] a) {
        return Arrays.deepToString(a).replace(" ", "");
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 56 four intervals", show(merge(new int[][]{{1, 3}, {2, 6}, {8, 10}, {15, 18}})),
                "[[1,6],[8,10],[15,18]]");
        check("LC 56 touching", show(merge(new int[][]{{1, 4}, {4, 5}})), "[[1,5]]");
        check("LC 56 contained", show(merge(new int[][]{{1, 4}, {2, 3}})), "[[1,4]]");
        check("LC 56 unsorted input",
                show(merge(new int[][]{{8, 10}, {1, 3}, {2, 6}})), "[[1,6],[8,10]]");

        check("LC 57 [2,5]",
                show(insert(new int[][]{{1, 3}, {6, 9}}, new int[]{2, 5})), "[[1,5],[6,9]]");
        int[][] five = {{1, 2}, {3, 5}, {6, 7}, {8, 10}, {12, 16}};
        check("LC 57 [4,8] spans three",
                show(insert(five, new int[]{4, 8})), "[[1,2],[3,10],[12,16]]");
        check("LC 57 into empty", show(insert(new int[][]{}, new int[]{5, 7})), "[[5,7]]");

        check("LC 252 overlapping",
                canAttendMeetings(new int[][]{{0, 30}, {5, 10}, {15, 20}}), false);
        check("LC 252 disjoint", canAttendMeetings(new int[][]{{7, 10}, {2, 4}}), true);
        check("LC 252 back to back", canAttendMeetings(new int[][]{{1, 5}, {5, 8}}), true);

        int[][] a = {{0, 2}, {5, 10}, {13, 23}, {24, 25}};
        int[][] b = {{1, 5}, {8, 12}, {15, 24}, {25, 26}};
        check("LC 986 two lists", show(intervalIntersection(a, b)),
                "[[1,2],[5,5],[8,10],[15,23],[24,24],[25,25]]");
        check("LC 986 one empty",
                show(intervalIntersection(new int[][]{{1, 3}, {5, 9}}, new int[][]{})), "[]");
    }
}

/*
 * =====================================================================
 *  P049 Intervals: Sort by End, Keep the Most   Canonical LC 435 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 435, Non-overlapping Intervals)
 *   Return the minimum number of intervals to remove so the rest do not overlap.
 *   Intervals that only touch ([1,2] and [2,3]) do not overlap.
 *
 * EXAMPLE
 *   [[1,2],[2,3],[3,4],[1,3]]  ->  1     remove [1,3]
 *   [[1,2],[1,2],[1,2]]        ->  2
 *   [[1,2],[2,3]]              ->  0
 *
 * RECOGNIZE WHEN
 *   - "maximum number of non-overlapping intervals", "minimum to remove", "minimum points /
 *     arrows that hit every interval", "longest chain of pairs" -- classic activity
 *     selection.
 *   Not this if: you want the union of intervals -> P048_MergeIntervals (sort by START); you
 *   need how many overlap at the same time -> P050_SweepLineMinRooms; intervals carry
 *   weights / profits -> P093_WeightedJobScheduling (DP, not greedy).
 *
 * TEMPLATE
 *   sort by END
 *   lastEnd = -infinity, kept = 0
 *   for [s, e] in intervals:
 *       if s >= lastEnd:            // compatible with everything kept (use > for "touching
 *           kept++; lastEnd = e     //  overlaps", e.g. arrows)
 *   removed = n - kept
 *
 * APPROACH
 *   1. Sort by end time.
 *   2. Keep an interval whenever it starts at or after the end of the last kept one.
 *   3. Everything not kept is removed.
 *
 * KEY INSIGHT
 *   Among all intervals you could keep next, the one that ENDS first leaves the most room
 *   for the rest, so choosing it can never be worse (exchange argument). Sorting by start
 *   fails: one long early interval would block many short ones.
 *
 * COMPLEXITY
 *   Time O(n log n), space O(1) besides the sort.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 452  Min Arrows for Balloons  an arrow at the kept interval's END bursts all
 *                                            that start <= it; touching counts as hit
 *   [coded] LC 646  Max Length Pair Chain    count kept pairs; chain needs strict b < c
 *           LC 1288 Remove Covered Intervals sort start asc, end desc (a different greedy)
 *           LC 757  Set Intersection Size 2  sort by end, keep the two largest picked
 *                                            points per interval
 *           Activity selection               identical to counting kept intervals
 *
 * PITFALLS
 *   - Sorting with (a, b) -> a[1] - b[1] overflows on extreme values; use Integer.compare.
 *   - Strict vs non-strict: balloons that touch share an arrow (start <= end); LC 435
 *     intervals that touch are compatible (start >= lastEnd).
 *
 * DEEP DIVE
 *   C06_NonOverlappingIntervals, C07_MinimumArrowsToBurstBalloons (15-Intervals)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.Arrays;

class SortByEndGreedy {

    // Canonical LC 435.
    static int eraseOverlapIntervals(int[][] intervals) {
        int[][] a = intervals.clone();
        Arrays.sort(a, (x, y) -> Integer.compare(x[1], y[1]));
        long lastEnd = Long.MIN_VALUE;
        int kept = 0;
        for (int[] cur : a) {
            if (cur[0] >= lastEnd) {
                kept++;
                lastEnd = cur[1];
            }
        }
        return a.length - kept;
    }

    // LC 452.
    static int findMinArrowShots(int[][] points) {
        int[][] a = points.clone();
        Arrays.sort(a, (x, y) -> Integer.compare(x[1], y[1]));
        int arrows = 0;
        long arrowAt = Long.MIN_VALUE;
        for (int[] p : a) {
            if (p[0] > arrowAt) {                 // not hit by the last arrow
                arrows++;
                arrowAt = p[1];
            }
        }
        return arrows;
    }

    // LC 646: pair [a, b] can follow [c, d] only if d < a.
    static int findLongestChain(int[][] pairs) {
        int[][] a = pairs.clone();
        Arrays.sort(a, (x, y) -> Integer.compare(x[1], y[1]));
        int chain = 0;
        long lastEnd = Long.MIN_VALUE;
        for (int[] p : a) {
            if (p[0] > lastEnd) {
                chain++;
                lastEnd = p[1];
            }
        }
        return chain;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 435 remove one",
                eraseOverlapIntervals(new int[][]{{1, 2}, {2, 3}, {3, 4}, {1, 3}}), 1);
        check("LC 435 three copies", eraseOverlapIntervals(new int[][]{{1, 2}, {1, 2}, {1, 2}}), 2);
        check("LC 435 touching is fine", eraseOverlapIntervals(new int[][]{{1, 2}, {2, 3}}), 0);
        check("LC 435 one long blocks many",
                eraseOverlapIntervals(new int[][]{{1, 100}, {2, 3}, {4, 5}, {6, 7}}), 1);

        check("LC 452 four balloons",
                findMinArrowShots(new int[][]{{10, 16}, {2, 8}, {1, 6}, {7, 12}}), 2);
        check("LC 452 disjoint", findMinArrowShots(new int[][]{{1, 2}, {3, 4}, {5, 6}, {7, 8}}), 4);
        check("LC 452 touching shares",
                findMinArrowShots(new int[][]{{1, 2}, {2, 3}, {3, 4}, {4, 5}}), 2);
        int[][] extremes = {{-2147483646, -2147483645}, {2147483646, 2147483647}};
        check("LC 452 overflow trap", findMinArrowShots(extremes), 2);

        check("LC 646 [[1,2],[2,3],[3,4]]",
                findLongestChain(new int[][]{{1, 2}, {2, 3}, {3, 4}}), 2);
        check("LC 646 [[1,2],[7,8],[4,5]]",
                findLongestChain(new int[][]{{1, 2}, {7, 8}, {4, 5}}), 3);
    }
}

/*
 * =====================================================================
 *  P050 Sweep Line: Maximum Overlap / Minimum Rooms   Canonical LC 253 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 253, Meeting Rooms II)
 *   Given meeting intervals [start, end), return the minimum number of rooms so every
 *   meeting has a room. A meeting ending at t frees its room for one starting at t.
 *
 * EXAMPLE
 *   [[0,30],[5,10],[15,20]]  ->  2
 *   [[7,10],[2,4]]           ->  1
 *   [[1,5],[5,10]]           ->  1      end and start at the same time share a room
 *
 * RECOGNIZE WHEN
 *   - "minimum rooms / platforms / servers / groups", "maximum number of overlapping
 *     intervals", "peak load at any moment".
 *   - The answer is the maximum, over time, of how many intervals are active.
 *   Not this if: you merge the intervals -> P048_MergeIntervals; you keep the most
 *   non-overlapping ones -> P049_SortByEndGreedy; coordinates are small integers and many
 *   ranges are added -> a difference array (P003_DifferenceArray) is simpler.
 *
 * TEMPLATE
 *   events: (start, +1) and (end, -1); sort by time, and at equal times put -1 first
 *           when an end frees the slot for a start at the same time (half-open)
 *   active = 0, best = 0
 *   for (time, delta) in events: active += delta; best = max(best, active)
 *   heap version: sort by start; min-heap of end times; pop if heap.min <= start; push end;
 *                 rooms = max heap size (or the final size)
 *
 * APPROACH
 *   1. Sort starts and ends separately.
 *   2. Walk the starts; before counting a new meeting, release every meeting that ended
 *      at or before this start.
 *   3. The most meetings active at once is the number of rooms.
 *
 * KEY INSIGHT
 *   Which meeting uses which room does not matter, only how many are running at each
 *   moment. Turning intervals into +1 / -1 events and sweeping time in order counts that
 *   directly. The tie rule at equal times encodes whether touching intervals conflict.
 *
 * COMPLEXITY
 *   Time O(n log n), space O(n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 253 with a heap               min-heap of end times = rooms in use
 *   [coded] LC 2406 Min Groups               intervals are INCLUSIVE: [1,5] and [5,10]
 *                                            conflict, so release only if end < start
 *   [coded] Minimum Platforms (GfG)          the same count with inclusive times
 *           LC 2402 Meeting Rooms III        heap of free room ids + heap of (end, room)
 *           LC 732  My Calendar III          TreeMap of +1/-1 deltas, max running sum
 *           LC 218  The Skyline Problem      events + max-heap / TreeMap of live heights
 *           LC 1094 Car Pooling              -> P003_DifferenceArray
 *           LC 1851 Min Interval per Query   sort queries; heap of intervals by length
 *
 * PITFALLS
 *   - The tie rule decides correctness: [1,5] and [5,10] need 1 room in LC 253 (half-open)
 *     but 2 groups in LC 2406 (closed).
 *   - With a heap, pop while heap.min <= start (half-open) before pushing the new end.
 *   - Sorting events by time alone is not enough; add the tie-breaker.
 *
 * DEEP DIVE
 *   C03_MeetingRoomsII, C04_DivideIntervalsIntoMinGroups, A03_MinimumPlatforms,
 *   D01_MeetingRoomsIII (15-Intervals)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.Arrays;
import java.util.PriorityQueue;

class SweepLineMinRooms {

    // Canonical LC 253 with sorted starts and ends (two pointers over the two event lists).
    static int minMeetingRooms(int[][] intervals) {
        int n = intervals.length;
        int[] starts = new int[n];
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) {
            starts[i] = intervals[i][0];
            ends[i] = intervals[i][1];
        }
        Arrays.sort(starts);
        Arrays.sort(ends);
        int active = 0;
        int best = 0;
        int e = 0;
        for (int s = 0; s < n; s++) {
            while (e < n && ends[e] <= starts[s]) {
                active--;                          // released before this start
                e++;
            }
            active++;
            best = Math.max(best, active);
        }
        return best;
    }

    // LC 253 with a min-heap of end times.
    static int minMeetingRoomsHeap(int[][] intervals) {
        int[][] a = intervals.clone();
        Arrays.sort(a, (x, y) -> Integer.compare(x[0], y[0]));
        PriorityQueue<Integer> ends = new PriorityQueue<>();
        for (int[] m : a) {
            if (!ends.isEmpty() && ends.peek() <= m[0]) {
                ends.poll();                       // reuse the room that frees first
            }
            ends.offer(m[1]);
        }
        return ends.size();
    }

    // LC 2406: inclusive intervals, so a group frees only if its end < the new start.
    static int minGroups(int[][] intervals) {
        int[][] a = intervals.clone();
        Arrays.sort(a, (x, y) -> Integer.compare(x[0], y[0]));
        PriorityQueue<Integer> ends = new PriorityQueue<>();
        for (int[] iv : a) {
            if (!ends.isEmpty() && ends.peek() < iv[0]) {
                ends.poll();
            }
            ends.offer(iv[1]);
        }
        return ends.size();
    }

    // Minimum platforms: a train departing at t and one arriving at t need two platforms.
    static int minPlatforms(int[] arrive, int[] depart) {
        int[] a = arrive.clone();
        int[] d = depart.clone();
        Arrays.sort(a);
        Arrays.sort(d);
        int active = 0;
        int best = 0;
        int j = 0;
        for (int i = 0; i < a.length; i++) {
            while (j < d.length && d[j] < a[i]) {
                active--;
                j++;
            }
            active++;
            best = Math.max(best, active);
        }
        return best;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        int[][] three = {{0, 30}, {5, 10}, {15, 20}};
        check("LC 253 events", minMeetingRooms(three), 2);
        check("LC 253 heap", minMeetingRoomsHeap(three), 2);
        check("LC 253 disjoint", minMeetingRooms(new int[][]{{7, 10}, {2, 4}}), 1);
        check("LC 253 back to back events", minMeetingRooms(new int[][]{{1, 5}, {5, 10}}), 1);
        check("LC 253 back to back heap", minMeetingRoomsHeap(new int[][]{{1, 5}, {5, 10}}), 1);
        check("LC 253 all at once", minMeetingRoomsHeap(new int[][]{{1, 4}, {2, 5}, {3, 6}}), 3);

        check("LC 2406 five intervals",
                minGroups(new int[][]{{5, 10}, {6, 8}, {1, 5}, {2, 3}, {1, 10}}), 3);
        check("LC 2406 disjoint", minGroups(new int[][]{{1, 3}, {5, 6}, {8, 10}, {11, 13}}), 1);
        check("LC 2406 touching conflicts", minGroups(new int[][]{{1, 5}, {5, 10}}), 2);

        check("platforms six trains", minPlatforms(new int[]{900, 940, 950, 1100, 1500, 1800},
                new int[]{910, 1200, 1120, 1130, 1900, 2000}), 3);
        check("platforms same minute", minPlatforms(new int[]{100, 200}, new int[]{200, 300}), 2);
    }
}

