/*
 * =====================================================================
 *  P051 Tree Traversals: Recursive, Iterative, Morris   Canonical LC 94 | Easy
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 94, Binary Tree Inorder Traversal)
 *   Return the inorder (left, node, right) traversal of a binary tree, iteratively.
 *
 * EXAMPLE
 *   [1,null,2,3]                         ->  [1,3,2]
 *   [1,2,3,4,5,null,8,null,null,6,7,9]   ->  [4,2,6,5,7,1,3,9,8]
 *   []                                   ->  []
 *
 * RECOGNIZE WHEN
 *   - "inorder / preorder / postorder", "without recursion", "O(1) extra space".
 *   - BST problems that need sorted order (inorder) or must stop early (k-th smallest).
 *   - Recursion depth is a risk (a 10^5-node skewed tree overflows the call stack).
 *   Not this if: you need nodes level by level -> P052_BfsByLevel.
 *
 * TEMPLATE
 *   inorder:   cur = root; stack = []
 *              while cur or stack:
 *                  while cur: stack.push(cur); cur = cur.left   // go left as far as possible
 *                  cur = stack.pop(); visit(cur); cur = cur.right
 *   preorder:  stack = [root]; pop, visit, push right THEN left
 *   postorder: preorder with left and right swapped (node, right, left), then reverse
 *   Morris:    thread each node's inorder predecessor back to it; O(1) space
 *
 * APPROACH
 *   1. Push the whole left spine; the top is the leftmost unvisited node.
 *   2. Pop it, visit it, then repeat on its right subtree.
 *
 * KEY INSIGHT
 *   Recursion keeps "where to come back to" on the call stack; an explicit stack holds
 *   the same thing. Inorder pauses each node until its left side is done, which is
 *   exactly "push the left spine, pop, go right".
 *
 * COMPLEXITY
 *   Time O(n). Space O(h) for the stack (h = height); Morris O(1) extra.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 144  Preorder Iterative       stack; push right before left
 *   [coded] LC 145  Postorder Iterative      root-right-left with a stack, then reverse
 *   [coded] Morris Inorder                   predecessor.right = cur as a temporary thread
 *           LC 173  BST Iterator             the inorder stack, one pop per next()
 *                                            -> P105_IteratorDesign
 *           LC 230  Kth Smallest in BST      inorder, stop at the k-th pop
 *           LC 589 / 590  N-ary Pre / Post   push children in reverse order
 *
 * PITFALLS
 *   - Preorder: push RIGHT first so LEFT is popped first.
 *   - Morris: always remove the thread on the second visit, or the tree stays modified.
 *   - The inorder loop condition is "cur != null OR stack not empty".
 *
 * DEEP DIVE
 *   A01_RecursivePostorder, A06_PrePostInorderInOneTraversal (09-Trees-BST)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

class IterativeTraversals {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }
    }

    // Canonical LC 94.
    static List<Integer> inorder(TreeNode root) {
        List<Integer> out = new ArrayList<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode cur = root;
        while (cur != null || !stack.isEmpty()) {
            while (cur != null) {
                stack.push(cur);
                cur = cur.left;
            }
            cur = stack.pop();
            out.add(cur.val);
            cur = cur.right;
        }
        return out;
    }

    // LC 144.
    static List<Integer> preorder(TreeNode root) {
        List<Integer> out = new ArrayList<>();
        if (root == null) {
            return out;
        }
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            TreeNode n = stack.pop();
            out.add(n.val);
            if (n.right != null) {
                stack.push(n.right);
            }
            if (n.left != null) {
                stack.push(n.left);
            }
        }
        return out;
    }

    // LC 145: node-right-left, reversed, is left-right-node.
    static List<Integer> postorder(TreeNode root) {
        List<Integer> out = new ArrayList<>();
        if (root == null) {
            return out;
        }
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            TreeNode n = stack.pop();
            out.add(n.val);
            if (n.left != null) {
                stack.push(n.left);
            }
            if (n.right != null) {
                stack.push(n.right);
            }
        }
        Collections.reverse(out);
        return out;
    }

    // Morris inorder: O(1) extra space, restores the tree.
    static List<Integer> morrisInorder(TreeNode root) {
        List<Integer> out = new ArrayList<>();
        TreeNode cur = root;
        while (cur != null) {
            if (cur.left == null) {
                out.add(cur.val);
                cur = cur.right;
            } else {
                TreeNode pred = cur.left;
                while (pred.right != null && pred.right != cur) {
                    pred = pred.right;
                }
                if (pred.right == null) {
                    pred.right = cur;              // thread back, then go left
                    cur = cur.left;
                } else {
                    pred.right = null;             // second visit: remove the thread
                    out.add(cur.val);
                    cur = cur.right;
                }
            }
        }
        return out;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        Integer[] small = {1, null, 2, 3};
        Integer[] big = {1, 2, 3, 4, 5, null, 8, null, null, 6, 7, 9};
        check("LC 94 [1,null,2,3]", inorder(TreeNode.of(small)), "[1, 3, 2]");
        check("LC 94 twelve nodes", inorder(TreeNode.of(big)), "[4, 2, 6, 5, 7, 1, 3, 9, 8]");
        check("LC 94 empty", inorder(TreeNode.of()), "[]");

        check("LC 144 [1,null,2,3]", preorder(TreeNode.of(small)), "[1, 2, 3]");
        check("LC 144 twelve nodes", preorder(TreeNode.of(big)), "[1, 2, 4, 5, 6, 7, 3, 8, 9]");

        check("LC 145 [1,null,2,3]", postorder(TreeNode.of(small)), "[3, 2, 1]");
        check("LC 145 twelve nodes", postorder(TreeNode.of(big)), "[4, 6, 7, 5, 2, 9, 8, 3, 1]");

        TreeNode t = TreeNode.of(big);
        check("Morris twelve nodes", morrisInorder(t), "[4, 2, 6, 5, 7, 1, 3, 9, 8]");
        check("Morris leaves the tree intact", inorder(t), "[4, 2, 6, 5, 7, 1, 3, 9, 8]");
    }
}

/*
 * =====================================================================
 *  P052 Tree BFS Level by Level   Canonical LC 102 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 102, Binary Tree Level Order Traversal)
 *   Return the node values level by level, left to right.
 *
 * EXAMPLE
 *   [3,9,20,null,null,15,7]  ->  [[3],[9,20],[15,7]]
 *   [1]                      ->  [[1]]
 *   []                       ->  []
 *
 * RECOGNIZE WHEN
 *   - Anything "per level / per depth / per row": right view, zigzag, averages, widest
 *     level, connect next pointers.
 *   - "minimum depth", "nearest leaf": BFS reaches the shallowest answer first.
 *   Not this if: the answer combines children's results (height, diameter, path sums) ->
 *   P053_BottomUpDfs; you carry a path from the root -> P054_TopDownDfsPath.
 *
 * TEMPLATE
 *   queue = [root]
 *   while queue:
 *       size = queue.size()                 // freeze the size: exactly this level's nodes
 *       for i in 0..size-1:
 *           node = queue.poll()
 *           use node (i == 0 is leftmost, i == size - 1 is rightmost)
 *           queue.add(children)
 *       finish the level (store list, sum, max, ...)
 *
 * APPROACH
 *   1. The queue starts with the root.
 *   2. Each round, read the current queue size and pop exactly that many nodes: they are
 *      one level. Their children form the next level.
 *
 * KEY INSIGHT
 *   A FIFO queue visits nodes in distance order from the root. Snapshotting the queue size
 *   at the start of each round draws a clean line between levels without storing depths.
 *
 * COMPLEXITY
 *   Time O(n), space O(w) where w is the widest level (up to n / 2).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 199  Right Side View          record the LAST node of each level
 *   [coded] LC 103  Zigzag Level Order       reverse every other level (or add at the front)
 *   [coded] LC 111  Minimum Depth            return at the FIRST leaf you pop
 *   [coded] LC 637  Average of Levels        sum / size per level, in long
 *           LC 515  Largest Value per Row    max per level
 *           LC 1161 Max Level Sum            index of the level with the largest sum
 *           LC 116  Populating Next Pointers link each node to the next one in its level
 *           LC 662  Max Width                queue of (node, index); width = last - first + 1
 *           LC 513  Bottom Left Value        first node of the last level
 *
 * PITFALLS
 *   - Read queue.size() ONCE before the inner loop; the queue grows while you pop.
 *   - LC 111: a node with one child is not a leaf; DFS that takes min(left, right) gets
 *     this wrong, BFS stops at the first real leaf.
 *   - Return an empty list (not [[]]) for an empty tree.
 *
 * DEEP DIVE
 *   A03_LevelOrderTraversal, C18_RightView, C20_BinaryTreeZigzagTraversal,
 *   C17_MaxLevelSum (09-Trees-BST)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

class BfsByLevel {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }
    }

    // Canonical LC 102.
    static List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> out = new ArrayList<>();
        if (root == null) {
            return out;
        }
        Deque<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            int size = queue.size();
            List<Integer> level = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                TreeNode n = queue.poll();
                level.add(n.val);
                if (n.left != null) {
                    queue.add(n.left);
                }
                if (n.right != null) {
                    queue.add(n.right);
                }
            }
            out.add(level);
        }
        return out;
    }

    // LC 199.
    static List<Integer> rightSideView(TreeNode root) {
        List<Integer> out = new ArrayList<>();
        for (List<Integer> level : levelOrder(root)) {
            out.add(level.get(level.size() - 1));
        }
        return out;
    }

    // LC 103.
    static List<List<Integer>> zigzagLevelOrder(TreeNode root) {
        List<List<Integer>> levels = levelOrder(root);
        for (int d = 1; d < levels.size(); d += 2) {
            Collections.reverse(levels.get(d));
        }
        return levels;
    }

    // LC 111: the first leaf popped is the shallowest.
    static int minDepth(TreeNode root) {
        if (root == null) {
            return 0;
        }
        Deque<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);
        int depth = 1;
        while (true) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                TreeNode n = queue.poll();
                if (n.left == null && n.right == null) {
                    return depth;
                }
                if (n.left != null) {
                    queue.add(n.left);
                }
                if (n.right != null) {
                    queue.add(n.right);
                }
            }
            depth++;
        }
    }

    // LC 637.
    static List<Double> averageOfLevels(TreeNode root) {
        List<Double> out = new ArrayList<>();
        for (List<Integer> level : levelOrder(root)) {
            long sum = 0;
            for (int v : level) {
                sum += v;
            }
            out.add((double) sum / level.size());
        }
        return out;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        Integer[] t = {3, 9, 20, null, null, 15, 7};
        check("LC 102 three levels", levelOrder(TreeNode.of(t)), "[[3], [9, 20], [15, 7]]");
        check("LC 102 single", levelOrder(TreeNode.of(1)), "[[1]]");
        check("LC 102 empty", levelOrder(TreeNode.of()), "[]");

        check("LC 199 [1,2,3,null,5,null,4]",
                rightSideView(TreeNode.of(1, 2, 3, null, 5, null, 4)), "[1, 3, 4]");
        check("LC 199 left branch deeper",
                rightSideView(TreeNode.of(1, 2, 3, 4, null, null, null, 5)),
                "[1, 3, 4, 5]");

        check("LC 103 zigzag", zigzagLevelOrder(TreeNode.of(t)), "[[3], [20, 9], [15, 7]]");

        check("LC 111 [3,9,20,null,null,15,7]", minDepth(TreeNode.of(t)), 2);
        check("LC 111 one-sided chain",
                minDepth(TreeNode.of(2, null, 3, null, 4, null, 5, null, 6)), 5);

        check("LC 637 averages", averageOfLevels(TreeNode.of(t)), "[3.0, 14.5, 11.0]");
        check("LC 637 big values", averageOfLevels(TreeNode.of(2147483647, 2147483647, 2147483647)),
                "[2.147483647E9, 2.147483647E9]");
    }
}

/*
 * =====================================================================
 *  P053 Tree DFS Bottom-Up (Return Info from Children)   Canonical LC 543 | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 543, Diameter of Binary Tree)
 *   Return the number of EDGES on the longest path between any two nodes. The path does
 *   not have to pass through the root.
 *
 * EXAMPLE
 *   [1,2,3,4,5]  ->  3      4 -> 2 -> 1 -> 3 (or 5 -> 2 -> 1 -> 3)
 *   [1,2]        ->  1
 *
 * RECOGNIZE WHEN
 *   - The answer at a node is built from answers of its subtrees: height, size, balance,
 *     sums, "best path going down from here".
 *   - The global answer may "bend" at some node (diameter, max path sum): combine the two
 *     child results there, but return only ONE side to the parent.
 *   Not this if: information flows from the root down (path so far, max so far) ->
 *   P054_TopDownDfsPath; you need per-level answers -> P052_BfsByLevel.
 *
 * TEMPLATE
 *   best = initial
 *   dfs(node):                               // returns what the PARENT needs
 *       if node is null: return base
 *       L = dfs(node.left); R = dfs(node.right)
 *       best = combine(best, L, R, node)     // the answer that bends here
 *       return extend(max(L, R), node)       // a path to the parent can use one side only
 *
 * APPROACH
 *   1. dfs returns the height (in nodes) of the subtree.
 *   2. The longest path that bends at a node has L + R edges; keep the maximum.
 *   3. Return 1 + max(L, R) so the parent can extend the longer side.
 *
 * KEY INSIGHT
 *   Separate "what I report upward" from "what I record as a candidate answer". A parent
 *   can only continue ONE downward branch, but the best path may use both branches at the
 *   node where it bends; a shared variable collects that while the return value stays
 *   single-branch.
 *
 * COMPLEXITY
 *   Time O(n), space O(h) recursion.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 104  Maximum Depth            return 1 + max(L, R); nothing to record
 *   [coded] LC 110  Balanced Binary Tree     return -1 as a "not balanced" sentinel
 *   [coded] LC 124  Max Path Sum             return node + max(0, L, R); record
 *                                            node + max(0, L) + max(0, R)
 *           LC 687  Longest Univalue Path    extend a side only if the child has the same value
 *           LC 1372 Longest ZigZag Path      return (best going left, best going right)
 *           LC 563  Binary Tree Tilt         return subtree sum, record |L - R|
 *           LC 1120 Max Average Subtree      return (sum, count)
 *           LC 865  Subtree of Deepest Nodes return (depth, node)
 *
 * PITFALLS
 *   - Diameter is in EDGES: L + R with heights counted in nodes.
 *   - LC 124: clamp negative child gains to 0 (do not extend into a loss), but start best
 *     at the smallest value, since all nodes may be negative.
 *   - Do not call height() inside another recursion (O(n^2)); return it once.
 *
 * DEEP DIVE
 *   B09_DiameterOfBinaryTree, A02_HeightOfBinaryTree, B10_IsBalancedBinaryTree,
 *   D01_BinaryTreeMaxPathSum (09-Trees-BST)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.Deque;

class BottomUpDfs {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }
    }

    private static int bestDiameter;

    // Canonical LC 543.
    static int diameterOfBinaryTree(TreeNode root) {
        bestDiameter = 0;
        height(root);
        return bestDiameter;
    }

    private static int height(TreeNode node) {
        if (node == null) {
            return 0;
        }
        int l = height(node.left);
        int r = height(node.right);
        bestDiameter = Math.max(bestDiameter, l + r);   // the path bending here
        return 1 + Math.max(l, r);                      // one side for the parent
    }

    // LC 104.
    static int maxDepth(TreeNode node) {
        return node == null ? 0 : 1 + Math.max(maxDepth(node.left), maxDepth(node.right));
    }

    // LC 110: -1 means "some subtree is unbalanced".
    static boolean isBalanced(TreeNode root) {
        return balancedHeight(root) != -1;
    }

    private static int balancedHeight(TreeNode node) {
        if (node == null) {
            return 0;
        }
        int l = balancedHeight(node.left);
        int r = balancedHeight(node.right);
        if (l == -1 || r == -1 || Math.abs(l - r) > 1) {
            return -1;
        }
        return 1 + Math.max(l, r);
    }

    private static int bestPath;

    // LC 124.
    static int maxPathSum(TreeNode root) {
        bestPath = Integer.MIN_VALUE;
        gain(root);
        return bestPath;
    }

    private static int gain(TreeNode node) {
        if (node == null) {
            return 0;
        }
        int l = Math.max(0, gain(node.left));          // drop a branch that only loses
        int r = Math.max(0, gain(node.right));
        bestPath = Math.max(bestPath, node.val + l + r);
        return node.val + Math.max(l, r);
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 543 [1,2,3,4,5]", diameterOfBinaryTree(TreeNode.of(1, 2, 3, 4, 5)), 3);
        check("LC 543 [1,2]", diameterOfBinaryTree(TreeNode.of(1, 2)), 1);
        TreeNode bent = TreeNode.of(1, 2, null, 3, 4, 5, null, null, 6, 7, null, null, 8);
        check("LC 543 not through the root",
                diameterOfBinaryTree(bent),
                6);

        check("LC 104 three levels", maxDepth(TreeNode.of(3, 9, 20, null, null, 15, 7)), 3);
        check("LC 104 [1,null,2]", maxDepth(TreeNode.of(1, null, 2)), 2);

        check("LC 110 balanced", isBalanced(TreeNode.of(3, 9, 20, null, null, 15, 7)), true);
        check("LC 110 unbalanced", isBalanced(TreeNode.of(1, 2, 2, 3, 3, null, null, 4, 4)), false);
        check("LC 110 empty", isBalanced(TreeNode.of()), true);

        check("LC 124 [1,2,3]", maxPathSum(TreeNode.of(1, 2, 3)), 6);
        check("LC 124 [-10,9,20,null,null,15,7]",
                maxPathSum(TreeNode.of(-10, 9, 20, null, null, 15, 7)), 42);
        check("LC 124 single negative", maxPathSum(TreeNode.of(-3)), -3);
    }
}

/*
 * =====================================================================
 *  P054 Tree DFS Top-Down (Carry State to the Children)   Canonical LC 113 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 113, Path Sum II)
 *   Return every ROOT-TO-LEAF path whose node values sum to targetSum.
 *
 * EXAMPLE
 *   [5,4,8,11,null,13,4,7,2,null,null,5,1], target 22  ->  [[5,4,11,2],[5,8,4,5]]
 *   [1,2,3], target 5                                  ->  []
 *
 * RECOGNIZE WHEN
 *   - The decision at a node depends on its ANCESTORS: remaining sum, max so far, the
 *     number formed so far, the path itself.
 *   - "root-to-leaf", "path from the root", "good node (no bigger ancestor)".
 *   - Downward paths that may start anywhere: combine with a prefix-sum map.
 *   Not this if: the node needs its children's results -> P053_BottomUpDfs.
 *
 * TEMPLATE
 *   dfs(node, state):
 *       if node is null: return
 *       state' = update(state, node)              // e.g. remaining - node.val, path.add
 *       if node is a leaf: check state'
 *       dfs(node.left, state'); dfs(node.right, state')
 *       undo the update if state is a shared mutable list / map (backtrack)
 *
 * APPROACH
 *   1. Walk down with the remaining sum and the current path.
 *   2. At a leaf with remaining == 0, copy the path into the answer.
 *   3. Remove the node from the path on the way back up.
 *
 * KEY INSIGHT
 *   Pass the ancestors' information DOWN as parameters. Immutable values (ints) undo
 *   themselves when the call returns; shared mutable state (the path list, a prefix-sum
 *   map) must be undone explicitly, which is the same backtracking step as P076_Subsets.
 *
 * COMPLEXITY
 *   Time O(n) visits (O(n * h) with path copying), space O(h).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 112  Path Sum                 boolean; no path list needed
 *   [coded] LC 1448 Count Good Nodes         carry the max on the path so far
 *   [coded] LC 129  Sum Root to Leaf Numbers carry number * 10 + digit
 *   [coded] LC 437  Path Sum III             paths may start anywhere: prefix-sum map along
 *                                            the root path (P002_PrefixSumHashMap on a tree)
 *           LC 1026 Max Diff Node / Ancestor carry the min and max on the path
 *           LC 257  Binary Tree Paths        carry the path string
 *           LC 988  Smallest String from Leaf carry the reversed string, compare at leaves
 *
 * PITFALLS
 *   - "Leaf" means no children; a node with one child is not an end point.
 *   - Copy the path when you record it (new ArrayList<>(path)), or later edits change it.
 *   - LC 437: remove the current prefix from the map after both children return.
 *
 * DEEP DIVE
 *   C10_PathSumII, B05_HasPathSum, C08_CountGoodNodes,
 *   C09_MaximumDifferenceBetweenNodeAndAncestor (09-Trees-BST)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class TopDownDfsPath {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }
    }

    // Canonical LC 113.
    static List<List<Integer>> pathSum(TreeNode root, int target) {
        List<List<Integer>> out = new ArrayList<>();
        collect(root, target, new ArrayList<>(), out);
        return out;
    }

    private static void collect(TreeNode node, int remaining, List<Integer> path,
                                List<List<Integer>> out) {
        if (node == null) {
            return;
        }
        path.add(node.val);
        remaining -= node.val;
        if (node.left == null && node.right == null && remaining == 0) {
            out.add(new ArrayList<>(path));
        }
        collect(node.left, remaining, path, out);
        collect(node.right, remaining, path, out);
        path.remove(path.size() - 1);              // backtrack
    }

    // LC 112.
    static boolean hasPathSum(TreeNode node, int target) {
        if (node == null) {
            return false;
        }
        if (node.left == null && node.right == null) {
            return target == node.val;
        }
        int rest = target - node.val;
        return hasPathSum(node.left, rest) || hasPathSum(node.right, rest);
    }

    // LC 1448: a node is good if no node on its root path is bigger.
    static int goodNodes(TreeNode root) {
        return countGood(root, Integer.MIN_VALUE);
    }

    private static int countGood(TreeNode node, int maxSoFar) {
        if (node == null) {
            return 0;
        }
        int good = node.val >= maxSoFar ? 1 : 0;
        int max = Math.max(maxSoFar, node.val);
        return good + countGood(node.left, max) + countGood(node.right, max);
    }

    // LC 129.
    static int sumNumbers(TreeNode root) {
        return sumFrom(root, 0);
    }

    private static int sumFrom(TreeNode node, int number) {
        if (node == null) {
            return 0;
        }
        number = number * 10 + node.val;
        if (node.left == null && node.right == null) {
            return number;
        }
        return sumFrom(node.left, number) + sumFrom(node.right, number);
    }

    // LC 437: downward paths starting anywhere; prefix sums along the current root path.
    static int pathSumIII(TreeNode root, int target) {
        Map<Long, Integer> prefixCount = new HashMap<>();
        prefixCount.put(0L, 1);
        return countPaths(root, 0L, target, prefixCount);
    }

    private static int countPaths(TreeNode node, long sum, int target,
                                  Map<Long, Integer> prefixCount) {
        if (node == null) {
            return 0;
        }
        sum += node.val;
        int found = prefixCount.getOrDefault(sum - target, 0);
        prefixCount.merge(sum, 1, Integer::sum);
        found += countPaths(node.left, sum, target, prefixCount);
        found += countPaths(node.right, sum, target, prefixCount);
        prefixCount.merge(sum, -1, Integer::sum);  // leave this branch
        return found;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        Integer[] t = {5, 4, 8, 11, null, 13, 4, 7, 2, null, null, 5, 1};
        check("LC 113 target 22", pathSum(TreeNode.of(t), 22), "[[5, 4, 11, 2], [5, 8, 4, 5]]");
        check("LC 113 none", pathSum(TreeNode.of(1, 2, 3), 5), "[]");
        check("LC 113 not a leaf", pathSum(TreeNode.of(1, 2), 1), "[]");

        check("LC 112 target 22", hasPathSum(TreeNode.of(t), 22), true);
        check("LC 112 [1,2,3] target 5", hasPathSum(TreeNode.of(1, 2, 3), 5), false);
        check("LC 112 empty tree", hasPathSum(TreeNode.of(), 0), false);

        check("LC 1448 [3,1,4,3,null,1,5]", goodNodes(TreeNode.of(3, 1, 4, 3, null, 1, 5)), 4);
        check("LC 1448 [3,3,null,4,2]", goodNodes(TreeNode.of(3, 3, null, 4, 2)), 3);

        check("LC 129 [1,2,3]", sumNumbers(TreeNode.of(1, 2, 3)), 25);
        check("LC 129 [4,9,0,5,1]", sumNumbers(TreeNode.of(4, 9, 0, 5, 1)), 1026);

        check("LC 437 target 8",
                pathSumIII(TreeNode.of(10, 5, -3, 3, 2, null, 11, 3, -2, null, 1), 8), 3);
        check("LC 437 target 22", pathSumIII(TreeNode.of(t), 22), 3);
    }
}

/*
 * =====================================================================
 *  P055 Tree Recursion on Two Trees at Once   Canonical LC 100 | Easy
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 100, Same Tree)
 *   Return whether two binary trees have the same shape and the same values.
 *
 * EXAMPLE
 *   [1,2,3] vs [1,2,3]     ->  true
 *   [1,2]   vs [1,null,2]  ->  false     same values, different shape
 *   [1,2,1] vs [1,1,2]     ->  false
 *
 * RECOGNIZE WHEN
 *   - Compare, mirror, merge or match TWO trees (or two subtrees of one tree): same tree,
 *     symmetric, subtree, flip-equivalent, merge.
 *   - Transform a tree in place by recursing on both children (invert / mirror).
 *   Not this if: one tree and a value flowing down or up -> P054_TopDownDfsPath or
 *   P053_BottomUpDfs.
 *
 * TEMPLATE
 *   same(a, b):
 *       if a == null and b == null: return true
 *       if a == null or  b == null: return false        // shapes differ
 *       return a.val == b.val and same(a.left, b.left) and same(a.right, b.right)
 *   mirror: compare a.left with b.right and a.right with b.left
 *
 * APPROACH
 *   1. Two empty trees are equal; one empty and one not are different.
 *   2. Otherwise the roots must match and both pairs of children must match.
 *
 * KEY INSIGHT
 *   Walk both trees in lock-step with ONE recursion over pairs of nodes. Handling the two
 *   null cases first makes every later line safe to dereference, and changing which
 *   children you pair (left-left vs left-right) turns "same" into "mirror".
 *
 * COMPLEXITY
 *   Time O(min(n, m)) for same / symmetric; O(n * m) for LC 572 (O(n + m) with hashing or
 *   serialisation). Space O(h).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 101  Symmetric Tree           mirror(root.left, root.right)
 *   [coded] LC 572  Subtree of Another Tree  same(node, sub) for every node of the big tree
 *   [coded] LC 226  Invert Binary Tree       swap the children, recurse on both
 *           LC 617  Merge Two Binary Trees   new node with a.val + b.val; recurse on pairs
 *           LC 951  Flip Equivalent Trees    (same order) OR (swapped order) at each pair
 *           LC 1367 Linked List in Tree      LC 572 where the small "tree" is a list
 *
 * PITFALLS
 *   - Compare values only after both nodes are known to be non-null.
 *   - LC 572 needs the WHOLE subtree to match, down to the leaves, not just a prefix.
 *   - Invert: save one child before overwriting it (or swap with a temp).
 *
 * DEEP DIVE
 *   B02_SameTree, B03_SymmetricTree, B04_IsSubtree, B01_InvertTree (09-Trees-BST)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedList;
import java.util.List;

class TwoTreeRecursion {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }

        // Level-order list with trailing nulls trimmed, as LeetCode prints trees.
        static String levels(TreeNode root) {
            List<String> out = new ArrayList<>();
            LinkedList<TreeNode> queue = new LinkedList<>();
            queue.add(root);
            while (!queue.isEmpty()) {
                TreeNode n = queue.poll();
                out.add(n == null ? "null" : String.valueOf(n.val));
                if (n != null) {
                    queue.add(n.left);
                    queue.add(n.right);
                }
            }
            while (!out.isEmpty() && out.get(out.size() - 1).equals("null")) {
                out.remove(out.size() - 1);
            }
            return "[" + String.join(",", out) + "]";
        }
    }

    // Canonical LC 100.
    static boolean isSameTree(TreeNode a, TreeNode b) {
        if (a == null && b == null) {
            return true;
        }
        if (a == null || b == null) {
            return false;
        }
        return a.val == b.val && isSameTree(a.left, b.left) && isSameTree(a.right, b.right);
    }

    // LC 101.
    static boolean isSymmetric(TreeNode root) {
        return root == null || isMirror(root.left, root.right);
    }

    private static boolean isMirror(TreeNode a, TreeNode b) {
        if (a == null && b == null) {
            return true;
        }
        if (a == null || b == null) {
            return false;
        }
        return a.val == b.val && isMirror(a.left, b.right) && isMirror(a.right, b.left);
    }

    // LC 572.
    static boolean isSubtree(TreeNode root, TreeNode sub) {
        if (root == null) {
            return sub == null;
        }
        return isSameTree(root, sub) || isSubtree(root.left, sub) || isSubtree(root.right, sub);
    }

    // LC 226.
    static TreeNode invertTree(TreeNode node) {
        if (node == null) {
            return null;
        }
        TreeNode left = node.left;
        node.left = invertTree(node.right);
        node.right = invertTree(left);
        return node;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 100 identical", isSameTree(TreeNode.of(1, 2, 3), TreeNode.of(1, 2, 3)), true);
        check("LC 100 different shape",
                isSameTree(TreeNode.of(1, 2), TreeNode.of(1, null, 2)), false);
        check("LC 100 different values",
                isSameTree(TreeNode.of(1, 2, 1), TreeNode.of(1, 1, 2)), false);
        check("LC 100 both empty", isSameTree(TreeNode.of(), TreeNode.of()), true);

        check("LC 101 symmetric", isSymmetric(TreeNode.of(1, 2, 2, 3, 4, 4, 3)), true);
        check("LC 101 not symmetric", isSymmetric(TreeNode.of(1, 2, 2, null, 3, null, 3)), false);

        check("LC 572 match", isSubtree(TreeNode.of(3, 4, 5, 1, 2), TreeNode.of(4, 1, 2)), true);
        TreeNode deeper = TreeNode.of(3, 4, 5, 1, 2, null, null, null, null, 0);
        check("LC 572 extra node below",
                isSubtree(deeper, TreeNode.of(4, 1, 2)),
                false);

        check("LC 226 seven nodes", TreeNode.levels(invertTree(TreeNode.of(4, 2, 7, 1, 3, 6, 9))),
                "[4,7,2,9,6,3,1]");
        check("LC 226 [2,1,3]", TreeNode.levels(invertTree(TreeNode.of(2, 1, 3))), "[2,3,1]");
        check("LC 226 empty", TreeNode.levels(invertTree(TreeNode.of())), "[]");
    }
}

/*
 * =====================================================================
 *  P056 BST Property: Bounds and Sorted Inorder   Canonical LC 98 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 98, Validate Binary Search Tree)
 *   Return whether the tree is a valid BST: every node in a left subtree is strictly
