import java.util.ArrayDeque;
import java.util.Deque;

class BstProperty {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }

        // The node holding value v (BST search), for building test inputs.
        static TreeNode find(TreeNode root, int v) {
            while (root != null && root.val != v) {
                root = v < root.val ? root.left : root.right;
            }
            return root;
        }
    }

    // Canonical LC 98.
    static boolean isValidBST(TreeNode root) {
        return valid(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private static boolean valid(TreeNode node, long lo, long hi) {
        if (node == null) {
            return true;
        }
        if (node.val <= lo || node.val >= hi) {
            return false;
        }
        return valid(node.left, lo, node.val) && valid(node.right, node.val, hi);
    }

    // LC 230.
    static int kthSmallest(TreeNode root, int k) {
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode cur = root;
        while (true) {
            while (cur != null) {
                stack.push(cur);
                cur = cur.left;
            }
            cur = stack.pop();
            if (--k == 0) {
                return cur.val;
            }
            cur = cur.right;
        }
    }

    // LC 235.
    static TreeNode lowestCommonAncestorBst(TreeNode root, TreeNode p, TreeNode q) {
        TreeNode cur = root;
        while (cur != null) {
            if (p.val < cur.val && q.val < cur.val) {
                cur = cur.left;
            } else if (p.val > cur.val && q.val > cur.val) {
                cur = cur.right;
            } else {
                return cur;                        // they split here (or one IS cur)
            }
        }
        return null;
    }

    private static Integer prev;
    private static int minGap;

    // LC 530: neighbours in inorder are the only candidates for the minimum gap.
    static int getMinimumDifference(TreeNode root) {
        prev = null;
        minGap = Integer.MAX_VALUE;
        inorderGap(root);
        return minGap;
    }

    private static void inorderGap(TreeNode node) {
        if (node == null) {
            return;
        }
        inorderGap(node.left);
        if (prev != null) {
            minGap = Math.min(minGap, node.val - prev);
        }
        prev = node.val;
        inorderGap(node.right);
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 98 [2,1,3]", isValidBST(TreeNode.of(2, 1, 3)), true);
        check("LC 98 [5,1,4,null,null,3,6]",
                isValidBST(TreeNode.of(5, 1, 4, null, null, 3, 6)), false);
        check("LC 98 grandchild trap", isValidBST(TreeNode.of(5, 4, 6, null, null, 3, 7)), false);
        check("LC 98 int max value", isValidBST(TreeNode.of(2147483647)), true);
        check("LC 98 duplicate is invalid", isValidBST(TreeNode.of(2, 2, 2)), false);

        check("LC 230 k=1", kthSmallest(TreeNode.of(3, 1, 4, null, 2), 1), 1);
        check("LC 230 k=3", kthSmallest(TreeNode.of(5, 3, 6, 2, 4, null, null, 1), 3), 3);

        TreeNode bst = TreeNode.of(6, 2, 8, 0, 4, 7, 9, null, null, 3, 5);
        check("LC 235 p=2 q=8",
                lowestCommonAncestorBst(bst, TreeNode.find(bst, 2), TreeNode.find(bst, 8)).val, 6);
        check("LC 235 p=2 q=4 ancestor of itself",
                lowestCommonAncestorBst(bst, TreeNode.find(bst, 2), TreeNode.find(bst, 4)).val, 2);
        check("LC 235 p=3 q=5",
                lowestCommonAncestorBst(bst, TreeNode.find(bst, 3), TreeNode.find(bst, 5)).val, 4);

        check("LC 530 [4,2,6,1,3]", getMinimumDifference(TreeNode.of(4, 2, 6, 1, 3)), 1);
        check("LC 530 [1,0,48,null,null,12,49]",
                getMinimumDifference(TreeNode.of(1, 0, 48, null, null, 12, 49)), 1);
    }
}

/*
 * =====================================================================
 *  P057 BST: Insert, Delete, Build   Canonical LC 450 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 450, Delete Node in a BST)
 *   Delete the node with value key (if present) and return the root of the still-valid
 *   BST.
 *
 * EXAMPLE
 *   [5,3,6,2,4,null,7], key 3  ->  [5,4,6,2,null,null,7]
 *   [5,3,6,2,4,null,7], key 0  ->  [5,3,6,2,4,null,7]     not found: unchanged
 *   [],                 key 0  ->  []
 *
 * RECOGNIZE WHEN
 *   - Change a BST and keep it a BST: insert, delete, trim to a range.
 *   - Build a BST from sorted data (balanced) or from a traversal (preorder).
 *   Not this if: you only read the BST -> P056_BstProperty; the tree is a general binary
 *   tree built from two traversals -> P059_BuildSerializeTree.
 *
 * TEMPLATE
 *   modify(node, key):                           // return the NEW root of this subtree
 *       if node is null: return (insert ? new Node(key) : null)
 *       if key < node.val: node.left  = modify(node.left, key)
 *       elif key > node.val: node.right = modify(node.right, key)
 *       else: handle this node (delete: 0, 1 or 2 children)
 *       return node
 *   build balanced: root = middle of the sorted range, recurse on both halves
 *
 * APPROACH
 *   1. Recurse toward the key, re-linking each child to the result of the recursive call.
 *   2. At the key: no child -> null; one child -> that child; two children -> copy the
 *      successor's value (min of the right subtree) and delete the successor there.
 *
 * KEY INSIGHT
 *   "Return the new subtree root and assign it to the parent's pointer" removes all
 *   parent-tracking: every case, including deleting the root, is handled the same way.
 *   For two children, the inorder successor is the only value that can replace the node
 *   without breaking the order on either side.
 *
 * COMPLEXITY
 *   Time O(h) for insert / delete (O(log n) balanced, O(n) skewed); build O(n). Space O(h).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 701  Insert into a BST        walk down; create the node where you fall off
 *   [coded] LC 108  Sorted Array to BST      middle element is the root; recurse
 *   [coded] LC 1008 BST from Preorder        recurse with an upper bound; one shared index
 *           LC 109  Sorted List to BST       middle via P031_FastSlowPointers, then as LC 108
 *           LC 669  Trim a BST               out-of-range node -> return the trimmed child
 *           LC 1382 Balance a BST            inorder to a list, then LC 108
 *
 * PITFALLS
 *   - Forgetting to assign the recursive result back (node.left = ...) loses the change.
 *   - Two-child delete: delete the successor from the RIGHT subtree, by value.
 *   - LC 1008: the bound must be passed down, or a value lands in the wrong subtree.
 *
 * DEEP DIVE
 *   C05_DeleteNodeInBST, B15_SortedArrayToBST,
 *   C06_ConstructBinarySearchTreefromPreorderTraversal, A05_BinarySearchTreeOperations
 *   (09-Trees-BST)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedList;
import java.util.List;

class BstModifyBuild {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }

        // Level-order list with trailing nulls trimmed, as LeetCode prints trees.
        static String levels(TreeNode root) {
            List<String> out = new ArrayList<>();
            LinkedList<TreeNode> queue = new LinkedList<>();
            queue.add(root);
            while (!queue.isEmpty()) {
                TreeNode n = queue.poll();
                out.add(n == null ? "null" : String.valueOf(n.val));
                if (n != null) {
                    queue.add(n.left);
                    queue.add(n.right);
                }
            }
            while (!out.isEmpty() && out.get(out.size() - 1).equals("null")) {
                out.remove(out.size() - 1);
            }
            return "[" + String.join(",", out) + "]";
        }
    }

    // Canonical LC 450.
    static TreeNode deleteNode(TreeNode node, int key) {
        if (node == null) {
            return null;
        }
        if (key < node.val) {
            node.left = deleteNode(node.left, key);
        } else if (key > node.val) {
            node.right = deleteNode(node.right, key);
        } else {
            if (node.left == null) {
                return node.right;
            }
            if (node.right == null) {
                return node.left;
            }
            TreeNode successor = node.right;
            while (successor.left != null) {
                successor = successor.left;
            }
            node.val = successor.val;
            node.right = deleteNode(node.right, successor.val);
        }
        return node;
    }

    // LC 701.
    static TreeNode insertIntoBST(TreeNode node, int val) {
        if (node == null) {
            return new TreeNode(val);
        }
        if (val < node.val) {
            node.left = insertIntoBST(node.left, val);
        } else {
            node.right = insertIntoBST(node.right, val);
        }
        return node;
    }

    // LC 108: height-balanced BST from a sorted array.
    static TreeNode sortedArrayToBST(int[] nums) {
        return build(nums, 0, nums.length - 1);
    }

    private static TreeNode build(int[] nums, int lo, int hi) {
        if (lo > hi) {
            return null;
        }
        int mid = lo + (hi - lo) / 2;
        TreeNode root = new TreeNode(nums[mid]);
        root.left = build(nums, lo, mid - 1);
        root.right = build(nums, mid + 1, hi);
        return root;
    }

    private static int next;

    // LC 1008: each subtree takes values below its upper bound, in preorder.
    static TreeNode bstFromPreorder(int[] preorder) {
        next = 0;
        return fromPreorder(preorder, Integer.MAX_VALUE);
    }

    private static TreeNode fromPreorder(int[] pre, int bound) {
        if (next == pre.length || pre[next] > bound) {
            return null;
        }
        TreeNode root = new TreeNode(pre[next++]);
        root.left = fromPreorder(pre, root.val);
        root.right = fromPreorder(pre, bound);
        return root;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        Integer[] t = {5, 3, 6, 2, 4, null, 7};
        check("LC 450 delete 3 (two children)", TreeNode.levels(deleteNode(TreeNode.of(t), 3)),
                "[5,4,6,2,null,null,7]");
        check("LC 450 key missing",
                TreeNode.levels(deleteNode(TreeNode.of(t), 0)), "[5,3,6,2,4,null,7]");
        check("LC 450 empty", TreeNode.levels(deleteNode(TreeNode.of(), 0)), "[]");
        check("LC 450 delete the root",
                TreeNode.levels(deleteNode(TreeNode.of(t), 5)), "[6,3,7,2,4]");
        check("LC 450 delete a leaf",
                TreeNode.levels(deleteNode(TreeNode.of(t), 7)), "[5,3,6,2,4]");

        check("LC 701 insert 5", TreeNode.levels(insertIntoBST(TreeNode.of(4, 2, 7, 1, 3), 5)),
                "[4,2,7,1,3,5]");
        check("LC 701 into empty", TreeNode.levels(insertIntoBST(TreeNode.of(), 5)), "[5]");

        check("LC 108 [-10,-3,0,5,9]",
                TreeNode.levels(sortedArrayToBST(new int[]{-10, -3, 0, 5, 9})),
                "[0,-10,5,null,-3,null,9]");
        check("LC 108 [1,3]", TreeNode.levels(sortedArrayToBST(new int[]{1, 3})), "[1,null,3]");

        check("LC 1008 [8,5,1,7,10,12]",
                TreeNode.levels(bstFromPreorder(new int[]{8, 5, 1, 7, 10, 12})),
                "[8,5,10,1,7,null,12]");
        check("LC 1008 [1,3]", TreeNode.levels(bstFromPreorder(new int[]{1, 3})), "[1,null,3]");
    }
}

/*
 * =====================================================================
 *  P058 Lowest Common Ancestor   Canonical LC 236 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 236, Lowest Common Ancestor of a Binary Tree)
 *   Given a binary tree (not a BST) and two nodes p and q that both exist in it, return
 *   their lowest common ancestor. A node is an ancestor of itself.
 *
 * EXAMPLE
 *   [3,5,1,6,2,0,8,null,null,7,4], p = 5, q = 1  ->  3
 *   [3,5,1,6,2,0,8,null,null,7,4], p = 5, q = 4  ->  5     p is q's ancestor
 *   [1,2], p = 1, q = 2                          ->  1
 *
 * RECOGNIZE WHEN
 *   - "lowest common ancestor", "first shared manager", "smallest region containing both",
 *     "path between two nodes" (it goes up to the LCA and back down).
 *   - Distance between two nodes = depth(p) + depth(q) - 2 * depth(LCA).
 *   Not this if: the tree is a BST -> use the ordering (P056_BstProperty, LC 235).
 *
 * TEMPLATE
 *   lca(node, p, q):
 *       if node is null or node == p or node == q: return node
 *       L = lca(node.left, p, q); R = lca(node.right, p, q)
 *       if L and R: return node               // p and q are on different sides
 *       return L if L else R                  // pass up whichever side found something
 *   parent pointers: like LC 160 -- walk up from both, switching to the other start
 *
 * APPROACH
 *   1. Each call reports "the LCA if both are below me, else whichever of p / q is below me".
 *   2. The first node that hears back from BOTH sides is the LCA.
 *
 * KEY INSIGHT
 *   One post-order pass answers it: a subtree returns null (nothing found), p or q (one
 *   found), or the LCA (both found). The node where two non-null answers meet is the
 *   answer. Returning early at p is safe ONLY because q is guaranteed to exist.
 *
 * COMPLEXITY
 *   Time O(n), space O(h). Parent-pointer version O(h) time, O(1) space.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 1644 LCA II (may not exist)   do not stop at p / q; count how many were
 *                                            found and return null unless both were
 *   [coded] LC 1650 LCA III (parent links)   two pointers walking up, switching start:
 *                                            the intersection of two lists (P034_GapPointers)
 *   [coded] LC 1676 LCA IV (many nodes)      return node if it is in the target SET
 *           LC 2096 Step-By-Step Directions  LCA, then 'U' * depth(start) + path to dest
 *           LC 1123 LCA of Deepest Leaves    bottom-up (depth, lca) pairs
 *           LC 1483 Kth Ancestor of a Node   binary lifting: up[j][v] = 2^j-th ancestor
 *           LC 1257 Smallest Common Region   parent map + LC 1650
 *
 * PITFALLS
 *   - The early return at p is wrong when q might not be in the tree (LC 1644).
 *   - Compare NODES (references), not values, if values can repeat.
 *   - Recursion depth on skewed trees: mention the iterative parent-map version.
 *
 * DEEP DIVE
 *   C12_LCA, C13_LowestCommonAncestorOfABinaryTreeII, C15_LowestCommonAncestorOfaBinaryTreeIII,
 *   C14_LowestCommonAncestorIV, C16_SmallestCommonRegion (09-Trees-BST)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.Set;

class LowestCommonAncestor {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;
        TreeNode parent;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list and links parent pointers.
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    n.left.parent = n;
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    n.right.parent = n;
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }

        // The node holding value v anywhere in the tree, or null.
        static TreeNode find(TreeNode root, int v) {
            if (root == null || root.val == v) {
                return root;
            }
            TreeNode left = find(root.left, v);
            return left != null ? left : find(root.right, v);
        }
    }

    // Canonical LC 236.
    static TreeNode lowestCommonAncestor(TreeNode node, TreeNode p, TreeNode q) {
        if (node == null || node == p || node == q) {
            return node;
        }
        TreeNode left = lowestCommonAncestor(node.left, p, q);
        TreeNode right = lowestCommonAncestor(node.right, p, q);
        if (left != null && right != null) {
            return node;
        }
        return left != null ? left : right;
    }

    private static int found;

    // LC 1644: p or q may be missing; visit everything and count.
    static TreeNode lowestCommonAncestorII(TreeNode root, TreeNode p, TreeNode q) {
        found = 0;
        TreeNode answer = search(root, p, q);
        return found == 2 ? answer : null;
    }

    private static TreeNode search(TreeNode node, TreeNode p, TreeNode q) {
        if (node == null) {
            return null;
        }
        TreeNode left = search(node.left, p, q);
        TreeNode right = search(node.right, p, q);
        if (node == p || node == q) {
            found++;
            return node;                           // checked AFTER the children: no early stop
        }
        if (left != null && right != null) {
            return node;
        }
        return left != null ? left : right;
    }

    // LC 1650: nodes know their parents; walk up like two linked lists.
    static TreeNode lowestCommonAncestorIII(TreeNode p, TreeNode q) {
        TreeNode a = p;
        TreeNode b = q;
        while (a != b) {
            a = a == null ? q : a.parent;
            b = b == null ? p : b.parent;
        }
        return a;
    }

    // LC 1676: LCA of a whole set of nodes (all present).
    static TreeNode lowestCommonAncestorIV(TreeNode node, Set<TreeNode> targets) {
        if (node == null || targets.contains(node)) {
            return node;
        }
        TreeNode left = lowestCommonAncestorIV(node.left, targets);
        TreeNode right = lowestCommonAncestorIV(node.right, targets);
        if (left != null && right != null) {
            return node;
        }
        return left != null ? left : right;
    }

    static Integer val(TreeNode n) {
        return n == null ? null : n.val;
    }

    static Set<TreeNode> nodes(TreeNode root, int... values) {
        Set<TreeNode> set = new HashSet<>();
        for (int v : values) {
            set.add(TreeNode.find(root, v));
        }
        return set;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        TreeNode t = TreeNode.of(3, 5, 1, 6, 2, 0, 8, null, null, 7, 4);
        TreeNode n5 = TreeNode.find(t, 5);
        TreeNode n1 = TreeNode.find(t, 1);
        TreeNode n4 = TreeNode.find(t, 4);
        TreeNode n6 = TreeNode.find(t, 6);
        check("LC 236 p=5 q=1", val(lowestCommonAncestor(t, n5, n1)), 3);
        check("LC 236 p=5 q=4", val(lowestCommonAncestor(t, n5, n4)), 5);
        check("LC 236 p=6 q=4", val(lowestCommonAncestor(t, n6, n4)), 5);
        TreeNode small = TreeNode.of(1, 2);
        check("LC 236 [1,2]", val(lowestCommonAncestor(small, small, small.left)), 1);

        TreeNode stranger = new TreeNode(10);
        check("LC 1644 p=5 q=1", val(lowestCommonAncestorII(t, n5, n1)), 3);
        check("LC 1644 p=5 q=4", val(lowestCommonAncestorII(t, n5, n4)), 5);
        check("LC 1644 q missing", val(lowestCommonAncestorII(t, n5, stranger)), null);

        check("LC 1650 p=5 q=1", val(lowestCommonAncestorIII(n5, n1)), 3);
        check("LC 1650 p=5 q=4", val(lowestCommonAncestorIII(n5, n4)), 5);

        check("LC 1676 {4,7}", val(lowestCommonAncestorIV(t, nodes(t, 4, 7))), 2);
        check("LC 1676 {1}", val(lowestCommonAncestorIV(t, nodes(t, 1))), 1);
        check("LC 1676 {7,6,2,4}", val(lowestCommonAncestorIV(t, nodes(t, 7, 6, 2, 4))), 5);
    }
}

/*
 * =====================================================================
 *  P059 Build a Tree from Traversals / Serialize   Canonical LC 105 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 105, Construct Binary Tree from Preorder and Inorder)
 *   Values are unique. Rebuild the tree from its preorder and inorder traversals.
 *
 * EXAMPLE
 *   preorder [3,9,20,15,7], inorder [9,3,15,20,7]  ->  [3,9,20,null,null,15,7]
 *   preorder [-1],          inorder [-1]           ->  [-1]
 *
 * RECOGNIZE WHEN
 *   - Two traversals given, rebuild the tree (pre + in, post + in, pre + post for full
 *     trees).
 *   - Turn a tree into a string and back (serialize / deserialize, codec design).
 *   Not this if: the tree is a BST and you have one traversal -> P057_BstModifyBuild (LC 1008).
 *
 * TEMPLATE
 *   index = {value: position in inorder}            // O(1) split lookups
 *   build(lo, hi):                                  // inorder range [lo, hi]
 *       if lo > hi: return null
 *       root = next value from preorder (left to right) / postorder (right to left)
 *       mid = index[root]
 *       preorder:  root.left = build(lo, mid - 1); root.right = build(mid + 1, hi)
 *       postorder: build RIGHT first, then left
 *   serialize: preorder with a marker for null; deserialize by reading tokens in order
 *
 * APPROACH
 *   1. The next preorder value is the root of the current subtree.
 *   2. Its position in inorder splits the range into the left and right subtrees.
 *   3. Recurse left then right, consuming preorder values in order.
 *
 * KEY INSIGHT
 *   Preorder (or postorder) tells you WHO is the root; inorder tells you WHAT goes on each
 *   side. A hash map from value to inorder index makes each split O(1), so the whole build
 *   is O(n). Serializing with explicit null markers makes ONE traversal enough.
 *
 * COMPLEXITY
 *   Time O(n), space O(n) for the map and recursion.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 106  From Inorder + Postorder walk postorder from the END; build right first
 *   [coded] LC 297  Serialize / Deserialize  preorder with "#" for null, comma separated
 *           LC 889  From Preorder + Postorder  full binary tree: pre[1] roots the left part
 *           LC 449  Serialize a BST          no null markers needed (bounds rebuild it)
 *           LC 1028 Recover from Preorder    dashes give the depth; stack of the path
 *           LC 536  Construct from String    "4(2(3)(1))(6(5))": recursive descent
 *
 * PITFALLS
 *   - Duplicate values make pre + in ambiguous; the problem must promise uniqueness.
 *   - Postorder build must do the RIGHT subtree first, since you read roots backwards.
 *   - Serialization without null markers cannot rebuild a general tree.
 *
 * DEEP DIVE
 *   C23_ConstructBinaryTreeFromINPre, D02_SerializeAndDeserialiseBinaryTree,
 *   C24_BinaryTreeFromString (09-Trees-BST)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

class BuildSerializeTree {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }

        // Level-order list with trailing nulls trimmed, as LeetCode prints trees.
        static String levels(TreeNode root) {
            List<String> out = new ArrayList<>();
            LinkedList<TreeNode> queue = new LinkedList<>();
            queue.add(root);
            while (!queue.isEmpty()) {
                TreeNode n = queue.poll();
                out.add(n == null ? "null" : String.valueOf(n.val));
                if (n != null) {
                    queue.add(n.left);
                    queue.add(n.right);
                }
            }
            while (!out.isEmpty() && out.get(out.size() - 1).equals("null")) {
                out.remove(out.size() - 1);
            }
            return "[" + String.join(",", out) + "]";
        }
    }

    private static int cursor;

    // Canonical LC 105.
    static TreeNode buildTree(int[] preorder, int[] inorder) {
        Map<Integer, Integer> index = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            index.put(inorder[i], i);
        }
        cursor = 0;
        return fromPre(preorder, index, 0, inorder.length - 1);
    }

    private static TreeNode fromPre(int[] pre, Map<Integer, Integer> index, int lo, int hi) {
        if (lo > hi) {
            return null;
        }
        TreeNode root = new TreeNode(pre[cursor++]);
        int mid = index.get(root.val);
        root.left = fromPre(pre, index, lo, mid - 1);
        root.right = fromPre(pre, index, mid + 1, hi);
        return root;
    }

    // LC 106: postorder read backwards is root, right subtree, left subtree.
    static TreeNode buildTreeFromPost(int[] inorder, int[] postorder) {
        Map<Integer, Integer> index = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            index.put(inorder[i], i);
        }
        cursor = postorder.length - 1;
        return fromPost(postorder, index, 0, inorder.length - 1);
    }

    private static TreeNode fromPost(int[] post, Map<Integer, Integer> index, int lo, int hi) {
        if (lo > hi) {
            return null;
        }
        TreeNode root = new TreeNode(post[cursor--]);
        int mid = index.get(root.val);
        root.right = fromPost(post, index, mid + 1, hi);
        root.left = fromPost(post, index, lo, mid - 1);
        return root;
    }

    // LC 297 serialize: preorder, "#" for null.
    static String serialize(TreeNode root) {
        StringBuilder sb = new StringBuilder();
        writePre(root, sb);
        return sb.substring(0, sb.length() - 1);   // drop the trailing comma
    }

    private static void writePre(TreeNode node, StringBuilder sb) {
        if (node == null) {
            sb.append("#,");
            return;
        }
        sb.append(node.val).append(',');
        writePre(node.left, sb);
        writePre(node.right, sb);
    }

    // LC 297 deserialize: read the tokens back in the same preorder.
    static TreeNode deserialize(String data) {
        return readPre(Arrays.asList(data.split(",")).iterator());
    }

    private static TreeNode readPre(Iterator<String> tokens) {
        String t = tokens.next();
        if (t.equals("#")) {
            return null;
        }
        TreeNode node = new TreeNode(Integer.parseInt(t));
        node.left = readPre(tokens);
        node.right = readPre(tokens);
        return node;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 105 five nodes",
                TreeNode.levels(buildTree(new int[]{3, 9, 20, 15, 7}, new int[]{9, 3, 15, 20, 7})),
                "[3,9,20,null,null,15,7]");
        check("LC 105 single", TreeNode.levels(buildTree(new int[]{-1}, new int[]{-1})), "[-1]");
        check("LC 105 left chain",
                TreeNode.levels(buildTree(new int[]{1, 2, 3}, new int[]{3, 2, 1})),
                "[1,2,null,3]");

        int[] in = {9, 3, 15, 20, 7};
        int[] post = {9, 15, 7, 20, 3};
        check("LC 106 five nodes",
                TreeNode.levels(buildTreeFromPost(in, post)),
                "[3,9,20,null,null,15,7]");

        TreeNode t = TreeNode.of(1, 2, 3, null, null, 4, 5);
        String data = serialize(t);
        check("LC 297 serialized", data, "1,2,#,#,3,4,#,#,5,#,#");
        check("LC 297 round trip", TreeNode.levels(deserialize(data)), "[1,2,3,null,null,4,5]");
        check("LC 297 empty tree", serialize(null), "#");
        check("LC 297 empty round trip", TreeNode.levels(deserialize("#")), "[]");
    }
}

/*
 * =====================================================================
 *  P060 Tree Coordinates: Vertical Order and Views   Canonical LC 987 | Hard
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 987, Vertical Order Traversal of a Binary Tree)
 *   The root is at (row 0, col 0); a left child is at (row + 1, col - 1), a right child at
 *   (row + 1, col + 1). Return the columns from left to right; inside a column, order by
 *   row, and break ties at the same (row, col) by value.
 *
 * EXAMPLE
 *   [3,9,20,null,null,15,7]  ->  [[9],[3,15],[20],[7]]
 *   [1,2,3,4,6,5,7]          ->  [[4],[2],[1,5,6],[3],[7]]    5 and 6 share (2, 0): by value
 *
 * RECOGNIZE WHEN
 *   - "vertical", "column", "top view", "bottom view", "seen from above / below".
 *   - Anything that needs a horizontal distance per node: tag each node with (row, col).
 *   Not this if: left / right side views -> per-level BFS (P052_BfsByLevel, LC 199).
 *
 * TEMPLATE
 *   traverse with coordinates: visit(node, row, col)
 *       record (col, row, node.val); recurse (row + 1, col - 1) and (row + 1, col + 1)
 *   group by col (TreeMap keeps columns sorted), order inside a group as required
 *   top view:    first node seen in each column in BFS order
 *   bottom view: last node seen in each column in BFS order
 *
 * APPROACH
 *   1. DFS records (col, row, value) for every node.
 *   2. Sort by col, then row, then value.
 *   3. Cut the sorted list into groups of equal col.
 *
 * KEY INSIGHT
 *   Give every node explicit coordinates, and "vertical" questions become sorting and
 *   grouping problems. BFS already visits rows in order, so for top / bottom views you only
 *   keep the first or last node per column.
 *
 * COMPLEXITY
 *   Time O(n log n) for the sort, space O(n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] Top View (GfG)                   BFS with columns; keep the FIRST per column
 *   [coded] Bottom View (GfG)                BFS with columns; keep the LAST per column
 *           LC 314  Vertical Order (BFS)     ties in a column keep BFS order, no value sort
 *           LC 199  Right Side View          rows instead of columns -> P052_BfsByLevel
 *           Diagonal traversal               group by (col - row) or count left turns
 *
 * PITFALLS
 *   - LC 987 ties: same row AND column -> sort by value; DFS order is not enough.
 *   - Top / bottom views need BFS (row order); DFS can see a deeper node first.
 *   - Use a TreeMap (or track min and max column) to output columns in order.
 *
 * DEEP DIVE
 *   C21_BottomViewBinaryTree (09-Trees-BST)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

class VerticalOrderViews {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }
    }

    // Canonical LC 987.
    static List<List<Integer>> verticalTraversal(TreeNode root) {
        List<int[]> cells = new ArrayList<>();                  // {col, row, val}
        collect(root, 0, 0, cells);
        cells.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0])
                : a[1] != b[1] ? Integer.compare(a[1], b[1]) : Integer.compare(a[2], b[2]));
        List<List<Integer>> out = new ArrayList<>();
        Integer currentCol = null;
        for (int[] c : cells) {
            if (currentCol == null || c[0] != currentCol) {
                out.add(new ArrayList<>());
                currentCol = c[0];
            }
            out.get(out.size() - 1).add(c[2]);
        }
        return out;
    }

    private static void collect(TreeNode node, int row, int col, List<int[]> cells) {
        if (node == null) {
            return;
        }
        cells.add(new int[]{col, row, node.val});
        collect(node.left, row + 1, col - 1, cells);
        collect(node.right, row + 1, col + 1, cells);
    }

    // Top view: the first node met in each column during BFS.
    static List<Integer> topView(TreeNode root) {
        return view(root, true);
    }

    // Bottom view: the last node met in each column during BFS.
    static List<Integer> bottomView(TreeNode root) {
        return view(root, false);
    }

    private static List<Integer> view(TreeNode root, boolean firstWins) {
        Map<Integer, Integer> byColumn = new TreeMap<>();
        if (root != null) {
            Deque<Object[]> queue = new ArrayDeque<>();          // {node, col}
            queue.add(new Object[]{root, 0});
            while (!queue.isEmpty()) {
                Object[] e = queue.poll();
                TreeNode n = (TreeNode) e[0];
                int col = (int) e[1];
                if (!firstWins || !byColumn.containsKey(col)) {
                    byColumn.put(col, n.val);
                }
                if (n.left != null) {
                    queue.add(new Object[]{n.left, col - 1});
                }
                if (n.right != null) {
                    queue.add(new Object[]{n.right, col + 1});
                }
            }
        }
        return new ArrayList<>(byColumn.values());
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 987 five nodes", verticalTraversal(TreeNode.of(3, 9, 20, null, null, 15, 7)),
                "[[9], [3, 15], [20], [7]]");
        check("LC 987 tie broken by value", verticalTraversal(TreeNode.of(1, 2, 3, 4, 6, 5, 7)),
                "[[4], [2], [1, 5, 6], [3], [7]]");
        check("LC 987 single", verticalTraversal(TreeNode.of(1)), "[[1]]");

        check("top view seven nodes", topView(TreeNode.of(1, 2, 3, 4, 5, 6, 7)), "[4, 2, 1, 3, 7]");
        check("top view hidden right child",
                topView(TreeNode.of(1, 2, 3, null, 4, null, null, null, 5, null, 6)),
                "[2, 1, 3, 6]");

        check("bottom view nine nodes",
                bottomView(TreeNode.of(20, 8, 22, 5, 3, null, 25, null, null, 10, 14)),
                "[5, 10, 3, 14, 25]");
        check("bottom view single", bottomView(TreeNode.of(1)), "[1]");
    }
}

/*
 * =====================================================================
 *  P061 Tree as an Undirected Graph (Parent Map + BFS)   Canonical LC 863 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 863, All Nodes Distance K in Binary Tree)
 *   Return the values of all nodes exactly k edges away from the target node, in any
 *   order. Paths may go UP through parents as well as down.
 *
 * EXAMPLE
 *   [3,5,1,6,2,0,8,null,null,7,4], target 5, k 2  ->  [7,4,1]
 *   [1], target 1, k 3                            ->  []
 *
 * RECOGNIZE WHEN
 *   - Distances or spreading that start at an ARBITRARY node (not the root): "distance k",
 *     "infection / fire spreading", "closest leaf to a node".
 *   - A path may need to go up through a parent.
 *   Not this if: everything starts at the root -> plain BFS / DFS (P052_BfsByLevel); you need
 *   the LCA or a path between two nodes -> P058_LowestCommonAncestor.
 *
 * TEMPLATE
 *   parent = {}                                  // one DFS: child -> parent
 *   BFS from start over neighbours {left, right, parent}, with a visited set
 *   level by level until distance k (or until the queue empties for "time to spread")
 *
 * APPROACH
 *   1. Record every node's parent, turning the tree into an undirected graph.
 *   2. BFS from the target over children and parent, marking visited nodes.
 *   3. The nodes in the queue after k levels are the answer.
 *
 * KEY INSIGHT
 *   A tree is a graph whose edges you can only follow downward. Adding parent links makes
 *   every edge two-way, and then any "distance from node X" question is a standard BFS.
 *   The visited set matters now, because the parent edge leads back.
 *
 * COMPLEXITY
 *   Time O(n), space O(n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 2385 Time to Infect the Tree  BFS from start; answer = number of levels - 1
 *           LC 742  Closest Leaf to Target   BFS from the target until the first leaf
 *           LC 2096 Directions Between Nodes LCA path instead -> P058_LowestCommonAncestor
 *           Burn a tree (GfG)                identical to LC 2385
 *           One-pass alternative             DFS returning the distance to the target
 *                                            (no parent map), harder to get right
 *
 * PITFALLS
 *   - Without a visited set, BFS walks child -> parent -> child forever.
 *   - k == 0 returns the target itself.
 *   - Store the parent of the ROOT as nothing (null), not as itself.
 *
 * DEEP DIVE
 *   C01_AllNodesDistanceKInBinaryTree (11-Graphs)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

class TreeAsGraph {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }

        // The node holding value v anywhere in the tree, or null.
        static TreeNode find(TreeNode root, int v) {
            if (root == null || root.val == v) {
                return root;
            }
            TreeNode left = find(root.left, v);
            return left != null ? left : find(root.right, v);
        }
    }

    private static void mapParents(TreeNode node, TreeNode parent,
                                   Map<TreeNode, TreeNode> parents) {
        if (node == null) {
            return;
        }
        parents.put(node, parent);
        mapParents(node.left, node, parents);
        mapParents(node.right, node, parents);
    }

    // BFS over {left, right, parent}; returns the levels (lists of nodes) from start.
    private static List<List<TreeNode>> levelsFrom(TreeNode root, TreeNode start) {
        Map<TreeNode, TreeNode> parents = new HashMap<>();
        mapParents(root, null, parents);
        List<List<TreeNode>> levels = new ArrayList<>();
        Set<TreeNode> seen = new HashSet<>();
        Deque<TreeNode> queue = new ArrayDeque<>();
        queue.add(start);
        seen.add(start);
        while (!queue.isEmpty()) {
            int size = queue.size();
            List<TreeNode> level = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                TreeNode n = queue.poll();
                level.add(n);
                for (TreeNode next : new TreeNode[]{n.left, n.right, parents.get(n)}) {
                    if (next != null && seen.add(next)) {
                        queue.add(next);
                    }
                }
            }
            levels.add(level);
        }
        return levels;
    }

    // Canonical LC 863.
    static List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        List<List<TreeNode>> levels = levelsFrom(root, target);
        List<Integer> out = new ArrayList<>();
        if (k < levels.size()) {
            for (TreeNode n : levels.get(k)) {
                out.add(n.val);
            }
        }
        Collections.sort(out);                     // any order is accepted; sorted to print
        return out;
    }

    // LC 2385: minutes until the infection from `start` reaches every node.
    static int amountOfTime(TreeNode root, int start) {
        return levelsFrom(root, TreeNode.find(root, start)).size() - 1;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        TreeNode t = TreeNode.of(3, 5, 1, 6, 2, 0, 8, null, null, 7, 4);
        check("LC 863 target 5 k=2", distanceK(t, TreeNode.find(t, 5), 2), "[1, 4, 7]");
        check("LC 863 k=0 is the target", distanceK(t, TreeNode.find(t, 5), 0), "[5]");
        TreeNode one = TreeNode.of(1);
        check("LC 863 k larger than the tree", distanceK(one, one, 3), "[]");
        check("LC 863 up and back down", distanceK(t, TreeNode.find(t, 6), 3), "[1, 4, 7]");

        check("LC 2385 start 3", amountOfTime(TreeNode.of(1, 5, 3, null, 4, 10, 6, 9, 2), 3), 4);
        check("LC 2385 single node", amountOfTime(TreeNode.of(1), 1), 0);
    }
}

/*
 * =====================================================================
 *  P062 DP on Trees (State per Node)   Canonical LC 337 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 337, House Robber III)
 *   Houses form a binary tree. Robbing two directly linked houses (parent and child) sets
 *   off the alarm. Return the most money you can rob.
 *
 * EXAMPLE
 *   [3,2,3,null,3,null,1]  ->  7     3 + 3 + 1
 *   [3,4,5,1,3,null,1]     ->  9     4 + 5
 *
 * RECOGNIZE WHEN
 *   - A choice per node (take / skip, colour, place a camera) with a rule that links a node
 *     to its parent or children, and you optimise over the whole tree.
 *   - The 1D version is a known DP (house robber, max independent set) but on a tree.
 *   Not this if: there is no per-node choice, just an aggregate -> P053_BottomUpDfs.
 *
 * TEMPLATE
 *   dfs(node) returns an array: best value for each STATE of this node
 *       e.g. {best if node is taken, best if node is skipped}
 *   combine children's arrays according to the rule:
 *       taken   = node.val + left.skipped + right.skipped
 *       skipped = max(left) + max(right)
 *   answer = max over the root's states
 *
 * APPROACH
 *   1. For each node compute two numbers: rob it, or do not.
 *   2. If you rob it, its children must be skipped; if not, each child may do either.
 *   3. Post-order, so children are solved first.
 *
 * KEY INSIGHT
 *   Returning ALL states of a subtree (not just its best) lets the parent apply its rule
 *   without re-visiting anything. This is the tree version of P082_LinearTakeSkip, and it
 *   avoids the exponential "grandchildren" recursion.
 *
 * COMPLEXITY
 *   Time O(n), space O(h).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 968  Binary Tree Cameras      greedy states: 0 = needs cover, 1 = has camera,
 *                                            2 = covered; place a camera when a child needs one
 *   [coded] LC 979  Distribute Coins         return the excess (coins - 1) of each subtree;
 *                                            moves += |excess| on every edge
 *           LC 1372 Longest ZigZag Path      states: arriving from left / from right
 *           Max independent set on a tree    exactly LC 337 with weights 1
 *           LC 2246 Longest Path, Diff Chars bottom-up best two children with a condition
 *
 * PITFALLS
 *   - The naive "rob node + grandchildren vs children" recursion is exponential without
 *     memo; the two-state return is O(n).
 *   - LC 968: if the root still "needs cover" at the end, add one camera.
 *   - LC 979: count moves on edges with |excess|, not the excess itself.
 *
 * DEEP DIVE
 *   B03_HouseRobber (12-Dynamic-Programming)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.Deque;

class TreeDp {

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }
    }

    // Canonical LC 337.
    static int rob(TreeNode root) {
        int[] r = robStates(root);
        return Math.max(r[0], r[1]);
    }

    // {best if this node is robbed, best if it is not}
    private static int[] robStates(TreeNode node) {
        if (node == null) {
            return new int[]{0, 0};
        }
        int[] l = robStates(node.left);
        int[] r = robStates(node.right);
        int taken = node.val + l[1] + r[1];
        int skipped = Math.max(l[0], l[1]) + Math.max(r[0], r[1]);
        return new int[]{taken, skipped};
    }

    private static int cameras;

    // LC 968: fewest cameras so every node is watched (a camera covers parent and children).
    static int minCameraCover(TreeNode root) {
        cameras = 0;
        if (cover(root) == 0) {
            cameras++;                             // the root itself is still unwatched
        }
        return cameras;
    }

    // 0 = not covered, 1 = has a camera, 2 = covered without a camera.
    private static int cover(TreeNode node) {
        if (node == null) {
            return 2;                              // nothing to watch
        }
        int l = cover(node.left);
        int r = cover(node.right);
        if (l == 0 || r == 0) {
            cameras++;
            return 1;
        }
        return (l == 1 || r == 1) ? 2 : 0;
    }

    private static int moves;

    // LC 979: n nodes, n coins in total; one move shifts a coin along one edge.
    static int distributeCoins(TreeNode root) {
        moves = 0;
        excess(root);
        return moves;
    }

    private static int excess(TreeNode node) {
        if (node == null) {
            return 0;
        }
        int l = excess(node.left);
        int r = excess(node.right);
        moves += Math.abs(l) + Math.abs(r);        // coins crossing the two child edges
        return node.val + l + r - 1;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 337 [3,2,3,null,3,null,1]", rob(TreeNode.of(3, 2, 3, null, 3, null, 1)), 7);
        check("LC 337 [3,4,5,1,3,null,1]", rob(TreeNode.of(3, 4, 5, 1, 3, null, 1)), 9);
        check("LC 337 skip two levels", rob(TreeNode.of(4, 1, null, 2, null, 3)), 7);

        check("LC 968 [0,0,null,0,0]", minCameraCover(TreeNode.of(0, 0, null, 0, 0)), 1);
        check("LC 968 chain of five",
                minCameraCover(TreeNode.of(0, 0, null, 0, null, 0, null, null, 0)), 2);
        check("LC 968 single node", minCameraCover(TreeNode.of(0)), 1);

        check("LC 979 [3,0,0]", distributeCoins(TreeNode.of(3, 0, 0)), 2);
        check("LC 979 [0,3,0]", distributeCoins(TreeNode.of(0, 3, 0)), 3);
