/*
 * =====================================================================
 *  P095 Greedy Reachability (Jump Game)   Canonical LC 55 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 55, Jump Game)
 *   nums[i] is the MAXIMUM jump length from index i. Starting at index 0, can you reach the
 *   last index?
 *
 * EXAMPLE
 *   [2, 3, 1, 1, 4]  ->  true
 *   [3, 2, 1, 0, 4]  ->  false    every path lands on the 0 at index 3
 *   [0]              ->  true     already at the end
 *
 * RECOGNIZE WHEN
 *   - Each position lets you reach a RANGE ahead (jump up to k, a tap watering [i-r, i+r],
 *     a clip covering [s, e]); ask "can we reach / cover the end?" or "fewest steps".
 *   - A DP over positions would work, but only the farthest reach matters.
 *   Not this if: moves go both ways or land on exact cells -> BFS (P067_BfsShortestPath,
 *   LC 1306 below); jumps carry costs or scores -> DP (P042_MonotonicDeque for LC 1696).
 *
 * TEMPLATE
 *   can reach:   far = 0; for i in 0..n-1: if i > far: return false; far = max(far, i + a[i])
 *   min jumps:   jumps = 0, curEnd = 0, far = 0
 *                for i in 0..n-2: far = max(far, i + a[i])
 *                                 if i == curEnd: jumps++; curEnd = far   // must jump now
 *   cover [0, n] with fewest intervals: the same "BFS levels" loop over ranges
 *
 * APPROACH
 *   1. Walk left to right, tracking the farthest index reachable so far.
 *   2. If the walk ever reaches an index beyond that, you are stuck.
 *
 * KEY INSIGHT
 *   You never need to know HOW you reach an index, only how far any reachable index can
 *   send you. For the fewest jumps, the indices reachable in exactly j jumps form one
 *   contiguous window, so the algorithm is BFS by levels without a queue.
 *
 * COMPLEXITY
 *   Time O(n), space O(1).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 45   Jump Game II             count levels: jump when i reaches curEnd
 *   [coded] LC 1306 Jump Game III            exact jumps i +- a[i], both directions -> BFS
 *   [coded] LC 1326 Min Taps to Water Garden turn each tap into a range, store the farthest
 *                                            reach per left end, then LC 45
 *           LC 1024 Video Stitching          LC 1326 with clips
 *           LC 1345 Jump Game IV             BFS; jump to any index with the same value
 *           LC 1871 Jump Game VII            reachable count in a sliding window
 *
 * PITFALLS
 *   - LC 45: loop to n - 2; jumping "from" the last index would add one too many.
 *   - LC 1326: the answer is -1 if a gap is never covered (far does not move past curEnd).
 *   - A 0 at index 0 with n > 1 is unreachable for everything after it.
 *
 * DEEP DIVE
 *   C08_CanJump, C09_JumpGameII, D02_MinimumNumberOfTapsToOpenToWaterAGarden (13-Greedy)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.Deque;

class Reachability {

    // Canonical LC 55.
    static boolean canJump(int[] nums) {
        int far = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i > far) {
                return false;                      // index i can never be reached
            }
            far = Math.max(far, i + nums[i]);
        }
        return true;
    }

    // LC 45: the end is guaranteed reachable.
    static int jump(int[] nums) {
        int jumps = 0;
        int curEnd = 0;                            // last index reachable with `jumps` jumps
        int far = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            far = Math.max(far, i + nums[i]);
            if (i == curEnd) {
                jumps++;
                curEnd = far;
            }
        }
        return jumps;
    }

    // LC 1306: from i jump to i + a[i] or i - a[i]; can you reach any 0?
    static boolean canReach(int[] a, int start) {
        boolean[] seen = new boolean[a.length];
        Deque<Integer> queue = new ArrayDeque<>();
        queue.add(start);
        seen[start] = true;
        while (!queue.isEmpty()) {
            int i = queue.poll();
            if (a[i] == 0) {
                return true;
            }
            for (int j : new int[]{i + a[i], i - a[i]}) {
                if (j >= 0 && j < a.length && !seen[j]) {
                    seen[j] = true;
                    queue.add(j);
                }
            }
        }
        return false;
    }

    // LC 1326: tap i waters [i - ranges[i], i + ranges[i]]; cover [0, n] with fewest taps.
    static int minTaps(int n, int[] ranges) {
        int[] reach = new int[n + 1];              // reach[l] = farthest right end starting at l
        for (int i = 0; i <= n; i++) {
            int left = Math.max(0, i - ranges[i]);
            reach[left] = Math.max(reach[left], Math.min(n, i + ranges[i]));
        }
        int taps = 0;
        int curEnd = 0;
        int far = 0;
        for (int i = 0; i < n; i++) {
            far = Math.max(far, reach[i]);
            if (i == curEnd) {
                if (far <= i) {
                    return -1;                     // nothing extends past i: a dry gap
                }
                taps++;
                curEnd = far;
            }
        }
        return taps;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 55 [2,3,1,1,4]", canJump(new int[]{2, 3, 1, 1, 4}), true);
        check("LC 55 [3,2,1,0,4]", canJump(new int[]{3, 2, 1, 0, 4}), false);
        check("LC 55 [0]", canJump(new int[]{0}), true);
        check("LC 55 [0,1] stuck at start", canJump(new int[]{0, 1}), false);

        check("LC 45 [2,3,1,1,4]", jump(new int[]{2, 3, 1, 1, 4}), 2);
        check("LC 45 [2,3,0,1,4]", jump(new int[]{2, 3, 0, 1, 4}), 2);
        check("LC 45 [0]", jump(new int[]{0}), 0);

        int[] a = {4, 2, 3, 0, 3, 1, 2};
        check("LC 1306 start 5", canReach(a, 5), true);
        check("LC 1306 start 0", canReach(a, 0), true);
        check("LC 1306 no path", canReach(new int[]{3, 0, 2, 1, 2}, 2), false);

        check("LC 1326 one tap", minTaps(5, new int[]{3, 4, 1, 1, 0, 0}), 1);
        check("LC 1326 dry", minTaps(3, new int[]{0, 0, 0, 0}), -1);
        check("LC 1326 n=7 three taps", minTaps(7, new int[]{1, 2, 1, 0, 2, 1, 0, 1}), 3);
    }
}

/*
 * =====================================================================
 *  P096 Greedy: Sort, Then Pair or Order   Canonical LC 455 | Easy
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 455, Assign Cookies)
 *   Child i is content with a cookie of size >= g[i]; each child gets at most one cookie.
 *   Return the most children you can make content.
 *
 * EXAMPLE
 *   g [1,2,3], s [1,1]    ->  1
 *   g [1,2],   s [1,2,3]  ->  2
 *
 * RECOGNIZE WHEN
 *   - Match items from two groups (children and cookies, people and boats, workers and
 *     jobs) or order items so that a local comparison decides the best arrangement.
 *   - Sorting makes the right choice obvious: "smallest that still fits", "heaviest with
 *     the lightest", "by the difference of two costs", "which concatenation is bigger".
 *   Not this if: picks interact through a capacity in complex ways -> DP
 *   (P084_ZeroOneKnapsack); intervals -> P049_SortByEndGreedy.
 *
 * TEMPLATE
 *   sort one or both lists by the key that makes a local decision safe
 *   two pointers walk them: match when compatible, otherwise skip the item that can never
 *   be matched
 *   for orderings: sort with a comparator that compares two items directly (exchange)
 *
 * APPROACH
 *   1. Sort greed factors and cookie sizes.
 *   2. Give the smallest cookie that satisfies the least greedy child still waiting; a
 *      cookie too small for that child is too small for everyone after, so skip it.
 *
 * KEY INSIGHT
 *   Exchange argument: if an optimal answer uses a bigger cookie where a smaller one would
 *   do, swapping them never hurts. After sorting, "smallest that fits" is the safe local
 *   choice, and two pointers apply it in one pass.
 *
 * COMPLEXITY
 *   Time O(n log n) for sorting, then O(n). Space O(1) besides the sort.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 881  Boats to Save People     sort; heaviest boards with the lightest if they
 *                                            fit, else alone (two pointers from both ends)
 *   [coded] LC 1029 Two City Scheduling      sort by costA - costB; first half to A
 *   [coded] LC 870  Advantage Shuffle        sort both; beat each b with the smallest a
 *                                            that wins, else sacrifice the smallest a
 *   [coded] LC 179  Largest Number           comparator: x + y vs y + x as strings
 *           LC 2410 Max Matching Players     LC 455 with trainers
 *           LC 1710 Max Units on a Truck     sort boxes by units, fill greedily
 *           LC 948  Bag of Tokens            sort; play face up with the smallest, face down
 *                                            with the largest
 *
 * PITFALLS
 *   - LC 179: an all-zero input must print "0", not "000".
 *   - LC 870: remember original indices of b, or the output is in the wrong order.
 *   - Prove (or at least test) the greedy; plausible greedies are often wrong.
 *
 * DEEP DIVE
 *   B02_AssignCookies, C02_BoatsToSavePeople, C06_BiggestNumber, B03_ClassPhotos (13-Greedy)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.Arrays;

class SortAndPair {

    // Canonical LC 455.
    static int findContentChildren(int[] g, int[] s) {
        int[] greed = g.clone();
        int[] size = s.clone();
        Arrays.sort(greed);
        Arrays.sort(size);
        int child = 0;
        for (int cookie = 0; cookie < size.length && child < greed.length; cookie++) {
            if (size[cookie] >= greed[child]) {
                child++;                           // smallest cookie that fits this child
            }
        }
        return child;
    }

    // LC 881: each boat holds at most 2 people and `limit` weight.
    static int numRescueBoats(int[] people, int limit) {
        int[] p = people.clone();
        Arrays.sort(p);
        int light = 0;
        int heavy = p.length - 1;
        int boats = 0;
        while (light <= heavy) {
            if (p[light] + p[heavy] <= limit) {
                light++;                           // lightest rides along
            }
            heavy--;                               // heaviest always leaves
            boats++;
        }
        return boats;
    }

    // LC 1029: 2n people, n to each city, minimise the total cost.
    static int twoCitySchedCost(int[][] costs) {
        int[][] c = costs.clone();
        Arrays.sort(c, (x, y) -> Integer.compare(x[0] - x[1], y[0] - y[1]));
        int n = c.length / 2;
        int total = 0;
        for (int i = 0; i < c.length; i++) {
            total += i < n ? c[i][0] : c[i][1];    // most "A-favoured" people go to A
        }
        return total;
    }

    // LC 870: permute a to maximise how many a[i] > b[i].
    static int[] advantageCount(int[] a, int[] b) {
        int n = a.length;
        int[] sortedA = a.clone();
        Arrays.sort(sortedA);
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            order[i] = i;
        }
        Arrays.sort(order, (x, y) -> Integer.compare(b[x], b[y]));
        int[] out = new int[n];
        int lo = 0;
        int hi = n - 1;
        for (int k = n - 1; k >= 0; k--) {         // the strongest b first
            int idx = order[k];
            if (sortedA[hi] > b[idx]) {
                out[idx] = sortedA[hi--];          // our strongest beats it
            } else {
                out[idx] = sortedA[lo++];          // cannot win: sacrifice the weakest
            }
        }
        return out;
    }

    // LC 179.
    static String largestNumber(int[] nums) {
        String[] s = new String[nums.length];
        for (int i = 0; i < nums.length; i++) {
            s[i] = String.valueOf(nums[i]);
        }
        Arrays.sort(s, (x, y) -> (y + x).compareTo(x + y));
        if (s[0].equals("0")) {
            return "0";
        }
        return String.join("", s);
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 455 g=[1,2,3] s=[1,1]",
                findContentChildren(new int[]{1, 2, 3}, new int[]{1, 1}), 1);
        check("LC 455 g=[1,2] s=[1,2,3]",
                findContentChildren(new int[]{1, 2}, new int[]{1, 2, 3}), 2);
        check("LC 455 no cookies", findContentChildren(new int[]{1}, new int[]{}), 0);

        check("LC 881 limit 3", numRescueBoats(new int[]{3, 2, 2, 1}, 3), 3);
        check("LC 881 limit 5", numRescueBoats(new int[]{3, 5, 3, 4}, 5), 4);
        check("LC 881 pairs fit", numRescueBoats(new int[]{1, 2}, 3), 1);

        check("LC 1029 four people",
                twoCitySchedCost(new int[][]{{10, 20}, {30, 200}, {400, 50}, {30, 20}}), 110);
        check("LC 1029 six people", twoCitySchedCost(new int[][]{{259, 770}, {448, 54}, {926, 667},
                {184, 139}, {840, 118}, {577, 469}}), 1859);

        check("LC 870 [2,7,11,15] vs [1,10,4,11]",
                Arrays.toString(advantageCount(new int[]{2, 7, 11, 15}, new int[]{1, 10, 4, 11})),
                "[2, 11, 7, 15]");
        int[] ours = {12, 24, 8, 32};
        int[] theirs = {13, 25, 32, 11};
        check("LC 870 [12,24,8,32] vs [13,25,32,11]",
                Arrays.toString(advantageCount(ours, theirs)), "[24, 32, 8, 12]");

        check("LC 179 [10,2]", largestNumber(new int[]{10, 2}), "210");
        check("LC 179 [3,30,34,5,9]", largestNumber(new int[]{3, 30, 34, 5, 9}), "9534330");
        check("LC 179 all zeros", largestNumber(new int[]{0, 0}), "0");
    }
}

/*
 * =====================================================================
 *  P097 Greedy Running Balance   Canonical LC 134 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 134, Gas Station)
 *   Stations on a circle: you gain gas[i] at station i and spend cost[i] to reach the next.
 *   Starting with an empty tank, return the unique start index that completes the loop, or
 *   -1.
 *
 * EXAMPLE
 *   gas [1,2,3,4,5], cost [3,4,5,1,2]  ->  3
 *   gas [2,3,4],     cost [3,4,3]      ->  -1
 *
 * RECOGNIZE WHEN
 *   - A quantity goes up and down along a sequence (fuel, money, balance, score) and must
 *     never drop below zero, or you want the best point to start / stop.
 *   - "collect every rise", "can you always give change", "best hour to close".
 *   Not this if: the choices interact over a window or with a limit on count -> DP
 *   (P092_StockStateMachine for k trades).
 *
 * TEMPLATE
 *   total = 0, tank = 0, start = 0
 *   for i in 0..n-1:
 *       total += delta[i]; tank += delta[i]
 *       if tank < 0: start = i + 1; tank = 0     // no start in [start..i] can work
 *   answer = total >= 0 ? start : -1
 *
 * APPROACH
 *   1. If total gas < total cost, no start works.
 *   2. Otherwise run once with a tank; whenever it goes negative at i, every start from the
 *      current candidate up to i fails, so the next candidate is i + 1.
 *
 * KEY INSIGHT
 *   If starting at s you run dry at i, then starting anywhere between s and i also runs dry
 *   at i (you would arrive at each of those points with at least as much gas as from s).
 *   That lets you skip the whole stretch, making the search O(n) instead of O(n^2).
 *
 * COMPLEXITY
 *   Time O(n), space O(1).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 122  Stock II (greedy)        add every positive day-to-day rise
 *   [coded] LC 860  Lemonade Change          keep counts of 5s and 10s; pay 15 change with
 *                                            10 + 5 before 5 + 5 + 5
 *   [coded] LC 2483 Min Penalty for a Shop   running balance of N minus Y; close where it
 *                                            peaks
 *           LC 1413 Min Start Value          1 - min(prefix sum), at least 1
 *           LC 2214 Min Health to Beat Game  total damage - min(armor, max hit) + 1
 *
 * PITFALLS
 *   - Check the total first; the single pass alone may report a start when none exists.
 *   - LC 860: prefer giving a 10 in change; keeping 5s is what keeps future change possible.
 *   - LC 2483: ties go to the EARLIEST hour.
 *
 * DEEP DIVE
 *   C10_GasStation, B05_LemonadeChange, C01_BestTimeToBuyAndSellStockII,
 *   C03_MinimumHealthToBeatGame (13-Greedy)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
class RunningBalance {

    // Canonical LC 134.
    static int canCompleteCircuit(int[] gas, int[] cost) {
        int total = 0;
        int tank = 0;
        int start = 0;
        for (int i = 0; i < gas.length; i++) {
            int delta = gas[i] - cost[i];
            total += delta;
            tank += delta;
            if (tank < 0) {
                start = i + 1;                     // no start in the old stretch survives
                tank = 0;
            }
        }
        return total >= 0 ? start : -1;
    }

    // LC 122: unlimited trades = sum of every rise.
    static int maxProfit(int[] prices) {
        int profit = 0;
        for (int i = 1; i < prices.length; i++) {
            profit += Math.max(0, prices[i] - prices[i - 1]);
        }
        return profit;
    }

    // LC 860: customers pay 5, 10 or 20 for a 5 lemonade, in order.
    static boolean lemonadeChange(int[] bills) {
        int fives = 0;
        int tens = 0;
        for (int b : bills) {
            if (b == 5) {
                fives++;
            } else if (b == 10) {
                fives--;
                tens++;
            } else if (tens > 0) {
                tens--;                            // 10 + 5 keeps more 5s for later
                fives--;
            } else {
                fives -= 3;
            }
            if (fives < 0) {
                return false;
            }
        }
        return true;
    }

    // LC 2483: closing at hour j costs (N before j) + (Y at or after j); earliest best hour.
    static int bestClosingTime(String customers) {
        int balance = 0;                           // (Y seen) - (N seen) before hour j
        int best = 0;
        int bestHour = 0;
        for (int j = 0; j < customers.length(); j++) {
            balance += customers.charAt(j) == 'Y' ? 1 : -1;
            if (balance > best) {
                best = balance;
                bestHour = j + 1;
            }
        }
        return bestHour;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 134 start 3",
                canCompleteCircuit(new int[]{1, 2, 3, 4, 5}, new int[]{3, 4, 5, 1, 2}), 3);
        check("LC 134 impossible", canCompleteCircuit(new int[]{2, 3, 4}, new int[]{3, 4, 3}), -1);
        check("LC 134 single station", canCompleteCircuit(new int[]{5}, new int[]{4}), 0);

        check("LC 122 [7,1,5,3,6,4]", maxProfit(new int[]{7, 1, 5, 3, 6, 4}), 7);
        check("LC 122 falling", maxProfit(new int[]{7, 6, 4, 3, 1}), 0);

        check("LC 860 [5,5,5,10,20]", lemonadeChange(new int[]{5, 5, 5, 10, 20}), true);
        check("LC 860 [5,5,10,10,20]", lemonadeChange(new int[]{5, 5, 10, 10, 20}), false);
        check("LC 860 first bill 10", lemonadeChange(new int[]{10}), false);

        check("LC 2483 YYNY", bestClosingTime("YYNY"), 2);
        check("LC 2483 NNNNN", bestClosingTime("NNNNN"), 0);
        check("LC 2483 YYYY", bestClosingTime("YYYY"), 4);
    }
}

/*
 * =====================================================================
 *  P098 Greedy with Boundaries and Two Passes   Canonical LC 763 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 763, Partition Labels)
 *   Split s into as many parts as possible so each letter appears in at most one part.
 *   Return the part sizes in order.
 *
 * EXAMPLE
 *   "ababcbacadefegdehijhklij"  ->  [9, 7, 8]
 *   "eccbbbbdec"                ->  [10]
 *
 * RECOGNIZE WHEN
 *   - "each letter / value must stay inside one part", "largest number after one swap":
 *     precompute where each value LAST appears, then one greedy pass.
 *   - Constraints from BOTH neighbours (rating higher than the left and the right): satisfy
 *     the left side in one pass and the right side in a second pass.
 *   Not this if: you need the aggregate of everything left / right of i ->
 *   P008_PrefixSuffixTwoPasses; you must remove letters to get the smallest result ->
 *   P039_GreedyRemovalStack.
 *
 * TEMPLATE
 *   last[c] = last index of c                       // one pre-pass
 *   end = 0, start = 0
 *   for i, c in s:
 *       end = max(end, last[c])                     // this part must reach at least here
 *       if i == end: close the part [start, end]; start = i + 1
 *   two-sided: left-to-right pass for the left rule, right-to-left pass for the right rule,
 *              combine with max
 *
 * APPROACH
 *   1. Record each letter's last position.
 *   2. Walk the string; the current part must extend to the last occurrence of every letter
 *      seen in it. When i reaches that end, nothing inside appears later: cut.
 *
 * KEY INSIGHT
 *   One pre-pass turns a global constraint ("this letter appears again later") into a
 *   number you can max() as you go. With two-sided constraints, each pass satisfies one side
 *   without breaking the other, and taking the max keeps both.
 *
 * COMPLEXITY
 *   Time O(n), space O(alphabet) (O(n) for the candy array).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 670  Maximum Swap             last index of each digit; at the first digit
 *                                            with a larger digit later, swap with its last copy
 *   [coded] LC 135  Candy                    left pass: more than the left if rated higher;
 *                                            right pass: more than the right; take the max
 *           LC 2405 Optimal String Partition cut whenever a letter repeats inside the part
 *           LC 1525 Good Ways to Split       distinct counts from the left and from the right
 *           LC 2100 Good Days to Rob a Bank  non-increasing run lengths from both sides
 *
 * PITFALLS
 *   - Cut only when i == end, not when the current letter's last index is i.
 *   - LC 670: swap with the LAST occurrence of the bigger digit (9973 vs 9937).
 *   - LC 135: equal ratings impose nothing; only strictly higher neighbours do.
 *
 * DEEP DIVE
 *   C05_PartitionLabels, C04_MaximumSwap, D01_Candy (13-Greedy)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayList;
import java.util.List;

class BoundariesTwoPasses {

    // Canonical LC 763.
    static List<Integer> partitionLabels(String s) {
        int[] last = new int[26];
        for (int i = 0; i < s.length(); i++) {
            last[s.charAt(i) - 'a'] = i;
        }
        List<Integer> sizes = new ArrayList<>();
        int start = 0;
        int end = 0;
        for (int i = 0; i < s.length(); i++) {
            end = Math.max(end, last[s.charAt(i) - 'a']);
            if (i == end) {
                sizes.add(end - start + 1);
                start = i + 1;
            }
        }
        return sizes;
    }

    // LC 670: at most one swap of two digits to get the largest number.
    static int maximumSwap(int num) {
        char[] d = String.valueOf(num).toCharArray();
        int[] last = new int[10];
        for (int i = 0; i < d.length; i++) {
            last[d[i] - '0'] = i;
        }
        for (int i = 0; i < d.length; i++) {
            for (int digit = 9; digit > d[i] - '0'; digit--) {
                if (last[digit] > i) {
                    char t = d[i];
                    d[i] = d[last[digit]];
                    d[last[digit]] = t;
                    return Integer.parseInt(new String(d));
                }
            }
        }
        return num;
    }

    // LC 135: everyone gets at least 1; a higher rating than a neighbour means more candy.
    static int candy(int[] ratings) {
        int n = ratings.length;
        int[] c = new int[n];
        java.util.Arrays.fill(c, 1);
        for (int i = 1; i < n; i++) {
            if (ratings[i] > ratings[i - 1]) {
                c[i] = c[i - 1] + 1;               // left rule
            }
        }
        for (int i = n - 2; i >= 0; i--) {
            if (ratings[i] > ratings[i + 1]) {
                c[i] = Math.max(c[i], c[i + 1] + 1);   // right rule, keeping the left rule
            }
        }
        int total = 0;
        for (int x : c) {
            total += x;
        }
        return total;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 763 three parts", partitionLabels("ababcbacadefegdehijhklij"), "[9, 7, 8]");
        check("LC 763 one part", partitionLabels("eccbbbbdec"), "[10]");
        check("LC 763 all distinct", partitionLabels("abc"), "[1, 1, 1]");

        check("LC 670 2736", maximumSwap(2736), 7236);
        check("LC 670 9973 already max", maximumSwap(9973), 9973);
        check("LC 670 98368 last copy", maximumSwap(98368), 98863);
        check("LC 670 1993", maximumSwap(1993), 9913);

        check("LC 135 [1,0,2]", candy(new int[]{1, 0, 2}), 5);
        check("LC 135 [1,2,2]", candy(new int[]{1, 2, 2}), 4);
        check("LC 135 [1,3,2,2,1]", candy(new int[]{1, 3, 2, 2, 1}), 7);
    }
}

