/*
 * =====================================================================
 *  P099 XOR Tricks   Canonical LC 136 | Easy
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 136, Single Number)
 *   Every element appears twice except one. Find it in O(n) time and O(1) extra space.
 *
 * EXAMPLE
 *   [2, 2, 1]        ->  1
 *   [4, 1, 2, 1, 2]  ->  4
 *   [1]              ->  1
 *
 * RECOGNIZE WHEN
 *   - "every value appears twice (or k times) except one / two", "find the missing / extra
 *     value", with O(1) space.
 *   - Pairs should cancel out; order does not matter.
 *   Not this if: extra space is fine and clarity matters -> a HashMap count
 *   (P021_FrequencyCanonicalKey); values lie in 1..n and you may modify the array ->
 *   P005_CyclicSortIndexAsHash.
 *
 * TEMPLATE
 *   x ^ x = 0, x ^ 0 = x, XOR is commutative and associative
 *   single:   r = 0; for x in a: r ^= x                      // pairs cancel
 *   missing:  r = n; for i, x: r ^= i ^ x                    // indices vs values
 *   two singles: x = a ^ b (all XOR); bit = x & -x; split numbers by that bit
 *   k copies: count each of the 32 bits mod k
 *
 * APPROACH
 *   1. XOR all numbers together.
 *   2. Each paired value cancels itself, so only the single one remains.
 *
 * KEY INSIGHT
 *   XOR is "addition without carry, mod 2" per bit, so anything appearing an even number of
 *   times vanishes. When two values remain, any set bit of their XOR is a bit where they
 *   differ, which splits the array into two groups that each hold one of them.
 *
 * COMPLEXITY
 *   Time O(n), space O(1). LC 137: O(32 n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 268  Missing Number           XOR of 0..n with every value
 *   [coded] LC 260  Single Number III        lowest set bit of a ^ b separates a from b
 *   [coded] LC 137  Single Number II         others appear 3 times: per-bit counts mod 3
 *           LC 389  Find the Difference      XOR all characters of s and t
 *           LC 1720 Decode XORed Array       arr[i + 1] = encoded[i] ^ arr[i]
 *           LC 2433 Find Original from Prefix XOR  arr[i] = pref[i] ^ pref[i - 1]
 *           LC 1310 XOR Queries              prefix XOR -> P001_PrefixSumRangeQuery
 *
 * PITFALLS
 *   - x & -x isolates the lowest set bit; it works for negative x too (two's complement).
 *   - LC 137 with negatives: rebuild all 32 bits, including the sign bit.
 *   - Sum-based "missing number" can overflow; XOR cannot.
 *
 * DEEP DIVE
 *   A03_SingleNumber, B01_MissingNumber (17-Math-Bit-Manipulation)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.Arrays;

class XorTricks {

    // Canonical LC 136.
    static int singleNumber(int[] nums) {
        int r = 0;
        for (int x : nums) {
            r ^= x;
        }
        return r;
    }

    // LC 268: nums holds n distinct values from 0..n.
    static int missingNumber(int[] nums) {
        int r = nums.length;
        for (int i = 0; i < nums.length; i++) {
            r ^= i ^ nums[i];
        }
        return r;
    }

    // LC 260: exactly two values appear once, the rest twice.
    static int[] singleNumberIII(int[] nums) {
        int both = 0;
        for (int x : nums) {
            both ^= x;                             // = a ^ b
        }
        int bit = both & -both;                    // a bit where a and b differ
        int a = 0;
        for (int x : nums) {
            if ((x & bit) != 0) {
                a ^= x;                            // only the group with that bit
            }
        }
        int[] out = {a, both ^ a};
        Arrays.sort(out);                          // any order is accepted
        return out;
    }

    // LC 137: every value appears three times except one.
    static int singleNumberII(int[] nums) {
        int result = 0;
        for (int b = 0; b < 32; b++) {
            int count = 0;
            for (int x : nums) {
                count += (x >> b) & 1;
            }
            if (count % 3 != 0) {
                result |= 1 << b;                  // the single number owns this bit
            }
        }
        return result;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 136 [2,2,1]", singleNumber(new int[]{2, 2, 1}), 1);
        check("LC 136 [4,1,2,1,2]", singleNumber(new int[]{4, 1, 2, 1, 2}), 4);
        check("LC 136 [1]", singleNumber(new int[]{1}), 1);

        check("LC 268 [3,0,1]", missingNumber(new int[]{3, 0, 1}), 2);
        check("LC 268 [0,1] missing n", missingNumber(new int[]{0, 1}), 2);
        check("LC 268 nine values", missingNumber(new int[]{9, 6, 4, 2, 3, 5, 7, 0, 1}), 8);

        check("LC 260 [1,2,1,3,2,5]",
                Arrays.toString(singleNumberIII(new int[]{1, 2, 1, 3, 2, 5})), "[3, 5]");
        check("LC 260 [-1,0]", Arrays.toString(singleNumberIII(new int[]{-1, 0})), "[-1, 0]");

        check("LC 137 [2,2,3,2]", singleNumberII(new int[]{2, 2, 3, 2}), 3);
        check("LC 137 [0,1,0,1,0,1,99]", singleNumberII(new int[]{0, 1, 0, 1, 0, 1, 99}), 99);
        check("LC 137 negative single",
                singleNumberII(new int[]{-2, -2, 1, 1, 4, 1, 4, 4, -4, -2}), -4);
    }
}

/*
 * =====================================================================
 *  P100 Bit Masks and Bit Counting   Canonical LC 191 | Easy
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 191, Number of 1 Bits)
 *   Return the number of set bits in the binary form of n (treat it as unsigned 32 bits).
 *
 * EXAMPLE
 *   11 (1011)           ->  3
 *   128 (10000000)      ->  1
 *   -3 (0xFFFFFFFD)     ->  31     unsigned view: every bit except one
 *
 * RECOGNIZE WHEN
 *   - Questions about the binary form: count bits, test / set / clear a bit, powers of two,
 *     Hamming distance, reverse the bits.
 *   - A small set (<= 32 items) represented as one integer.
 *   - "without using + or *" style puzzles.
 *   Not this if: pairs cancel out -> P099_XorTricks; the mask is a DP state ->
 *   P094_BitmaskDp.
 *
 * TEMPLATE
 *   test bit i:   (x >> i) & 1          set: x | (1 << i)       clear: x & ~(1 << i)
 *   drop lowest set bit:  x & (x - 1)   lowest set bit: x & -x
 *   power of two:         x > 0 && (x & (x - 1)) == 0
 *   bits(i) = bits(i >> 1) + (i & 1)    // DP over numbers 0..n
 *   unsigned shift in Java: >>>
 *
 * APPROACH
 *   1. n & (n - 1) clears the lowest set bit.
 *   2. Count how many times you can do that before n becomes 0.
 *
 * KEY INSIGHT
 *   Subtracting 1 flips the lowest set bit and every 0 below it, so ANDing with the original
 *   removes exactly that one bit. The loop runs once per set bit, not once per bit position,
 *   and it treats negative numbers correctly because it never shifts.
 *
 * COMPLEXITY
 *   O(number of set bits) per number; LC 338 is O(n) for all of 0..n.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 338  Counting Bits            dp[i] = dp[i >> 1] + (i & 1)
 *   [coded] LC 231  Power of Two             n > 0 and n & (n - 1) == 0
 *   [coded] LC 461  Hamming Distance         bitCount(x ^ y)
 *   [coded] LC 190  Reverse Bits             shift out the low bit, shift it in on the left
 *           LC 371  Sum Without + or -       a ^ b is the sum without carries, (a & b) << 1
 *                                            the carries; repeat until no carry
 *           LC 2220 Min Bit Flips            bitCount(start ^ goal)
 *           LC 401  Binary Watch             enumerate times, keep bitCount(h) + bitCount(m)
 *
 * PITFALLS
 *   - Use >>> (unsigned) when shifting a value that may be negative, or the loop never ends.
 *   - 1 << 31 is negative in Java; compare with != 0, not > 0.
 *   - Integer.bitCount exists; say you know it, then write the loop if asked.
 *
 * DEEP DIVE
 *   A02_NumberOf1Bits, A01_CheckIfTheIthBitIsSetOrNot, B02_MinimumBitFlipsToConvertNumber,
 *   B03_BinaryWatch (17-Math-Bit-Manipulation)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.Arrays;

class BitMasksCounting {

    // Canonical LC 191 (Brian Kernighan's loop).
    static int hammingWeight(int n) {
        int count = 0;
        while (n != 0) {
            n &= n - 1;                            // drop the lowest set bit
            count++;
        }
        return count;
    }

    // LC 338.
    static int[] countBits(int n) {
        int[] dp = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i >> 1] + (i & 1);
        }
        return dp;
    }

    // LC 231.
    static boolean isPowerOfTwo(int n) {
        return n > 0 && (n & (n - 1)) == 0;
    }

    // LC 461.
    static int hammingDistance(int x, int y) {
        return hammingWeight(x ^ y);
    }

    // LC 190: reverse the 32 bits.
    static int reverseBits(int n) {
        int r = 0;
        for (int i = 0; i < 32; i++) {
            r = (r << 1) | (n & 1);
            n >>>= 1;
        }
        return r;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 191 n=11", hammingWeight(11), 3);
        check("LC 191 n=128", hammingWeight(128), 1);
        check("LC 191 n=-3 unsigned", hammingWeight(-3), 31);

        check("LC 338 n=2", Arrays.toString(countBits(2)), "[0, 1, 1]");
        check("LC 338 n=5", Arrays.toString(countBits(5)), "[0, 1, 1, 2, 1, 2]");

        check("LC 231 n=1", isPowerOfTwo(1), true);
        check("LC 231 n=16", isPowerOfTwo(16), true);
        check("LC 231 n=3", isPowerOfTwo(3), false);
        check("LC 231 int min is not", isPowerOfTwo(Integer.MIN_VALUE), false);

        check("LC 461 x=1 y=4", hammingDistance(1, 4), 2);
        check("LC 461 x=3 y=1", hammingDistance(3, 1), 1);

        check("LC 190 43261596", reverseBits(43261596), 964176192);
        check("LC 190 0xFFFFFFFD", reverseBits(0xFFFFFFFD), -1073741825);
    }
}

/*
 * =====================================================================
 *  P101 Number Theory Basics: Sieve, Fast Power, GCD   Canonical LC 204 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 204, Count Primes)
 *   Return how many prime numbers are strictly less than n.
 *
 * EXAMPLE
 *   n = 10   ->  4      2, 3, 5, 7
 *   n = 0    ->  0
 *   n = 100  ->  25
 *
 * RECOGNIZE WHEN
 *   - Primes up to a limit, prime factors, divisors.
 *   - x^n for big n, or "answer modulo 1e9 + 7" with exponents.
 *   - Greatest common divisor / least common multiple, fractions, "repeat a pattern".
 *   - Trailing zeros, digit sums and other counting questions with a closed form.
 *   Not this if: the problem is about bits -> P100_BitMasksCounting; counting paths or
 *   arrangements with constraints -> DP.
 *
 * TEMPLATE
 *   sieve:     prime[2..n) = true; for p while p * p < n: if prime[p]: mark p*p, p*p+p, ...
 *   fast pow:  result = 1; while e > 0: if e odd: result *= base; base *= base; e >>= 1
 *   gcd:       gcd(a, b) = b == 0 ? a : gcd(b, a % b);   lcm = a / gcd(a, b) * b
 *   modulo:    (a * b) % m with long; inverse of a mod prime m = a^(m - 2) mod m
 *
 * APPROACH
 *   1. Assume everything from 2 up is prime.
 *   2. For each prime p, cross out its multiples starting at p * p (smaller multiples were
 *      already crossed out by smaller primes).
 *   3. Count what is left.
 *
 * KEY INSIGHT
 *   Each of these tools turns a slow loop into a fast one by reusing structure: the sieve
 *   crosses out composites instead of testing each number, fast power squares the base so
 *   the exponent halves each step, and Euclid replaces the larger number by a remainder.
 *
 * COMPLEXITY
 *   Sieve O(n log log n) time, O(n) space. Fast power O(log n). GCD O(log min(a, b)).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 50   Pow(x, n)                binary exponentiation; negative n -> 1 / x^|n|,
 *                                            using long so -2^31 does not overflow
 *   [coded] GCD and LCM                      Euclid; lcm = a / gcd * b to avoid overflow
 *   [coded] LC 172  Factorial Trailing Zeros count factors of 5: n/5 + n/25 + n/125 + ...
 *           LC 1071 GCD of Strings           if s + t == t + s, the answer has gcd length
 *           LC 7    Reverse Integer          check overflow BEFORE multiplying by 10
 *           nCr mod p                        factorials + modular inverses (Fermat)
 *           LC 1922 Count Good Numbers       fast modular power
 *           LC 365  Water and Jug            target must be a multiple of gcd(x, y)
 *
 * PITFALLS
 *   - Sieve: start crossing at p * p, and loop while p * p < n (use long if n is huge).
 *   - Pow: n = Integer.MIN_VALUE cannot be negated as an int.
 *   - LCM: a * b can overflow; divide first.
 *
 * DEEP DIVE
 *   A08_SieveOfEratosthenes, A10_BinaryExponentiation, A09_LCMOfTwoNumbers, A07_PrimeFactors
 *   (17-Math-Bit-Manipulation)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
class NumberTheory {

    // Canonical LC 204.
    static int countPrimes(int n) {
        if (n < 3) {
            return 0;
        }
        boolean[] composite = new boolean[n];
        int count = 0;
        for (int p = 2; p < n; p++) {
            if (composite[p]) {
                continue;
            }
            count++;
            for (long m = (long) p * p; m < n; m += p) {
                composite[(int) m] = true;
            }
        }
        return count;
    }

    // LC 50.
    static double myPow(double x, int n) {
        long e = n;                                // long: -(-2^31) fits
        if (e < 0) {
            x = 1 / x;
            e = -e;
        }
        double result = 1;
        while (e > 0) {
            if ((e & 1) == 1) {
                result *= x;
            }
            x *= x;
            e >>= 1;
        }
        return result;
    }

    static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }

    // LC 172: zeros come from 2 * 5 pairs; fives are the scarce factor.
    static int trailingZeroes(int n) {
        int zeros = 0;
        while (n > 0) {
            n /= 5;
            zeros += n;
        }
        return zeros;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 204 n=10", countPrimes(10), 4);
        check("LC 204 n=0", countPrimes(0), 0);
        check("LC 204 n=2 (strictly less)", countPrimes(2), 0);
        check("LC 204 n=100", countPrimes(100), 25);

        check("LC 50 2^10", myPow(2.0, 10), 1024.0);
        check("LC 50 2^-2", myPow(2.0, -2), 0.25);
        check("LC 50 1^(int min)", myPow(1.0, Integer.MIN_VALUE), 1.0);
        check("LC 50 2^(int min)", myPow(2.0, Integer.MIN_VALUE), 0.0);

        check("gcd(12,18)", gcd(12, 18), 6L);
        check("gcd(0,5)", gcd(0, 5), 5L);
        check("lcm(4,6)", lcm(4, 6), 12L);
        check("lcm without overflow", lcm(2_000_000_000L, 3_000_000_000L), 6_000_000_000L);

        check("LC 172 n=3", trailingZeroes(3), 0);
        check("LC 172 n=5", trailingZeroes(5), 1);
        check("LC 172 n=100", trailingZeroes(100), 24);
    }
}

