/*
 * =====================================================================
 *  P102 Design: LRU and LFU Cache   Canonical LC 146 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 146, LRU Cache)
 *   A cache with a fixed capacity: get(key) returns the value or -1; put(key, value) inserts
 *   or updates, and when full evicts the LEAST RECENTLY USED key. Both in O(1).
 *
 * EXAMPLE
 *   capacity 2: put(1,1) put(2,2) get(1)=1 put(3,3) get(2)=-1 put(4,4) get(1)=-1
 *               get(3)=3 get(4)=4
 *
 * RECOGNIZE WHEN
 *   - "O(1) get and put" plus an ORDER to evict by (recency, frequency, insertion time).
 *   - Lookup by key AND removal from the middle of an ordering.
 *   Not this if: eviction is by smallest / largest value -> a heap or TreeMap
 *   (P047_TreeMapFloorCeiling); no eviction -> a plain HashMap.
 *
 * TEMPLATE
 *   map: key -> node; doubly linked list ordered by recency (head = newest, tail = oldest)
 *   get(k):    node = map[k]; if absent -1; move node to the front; return node.value
 *   put(k, v): if present: update + move to front
 *              else: if full: remove the tail node and its map entry; insert at the front
 *   sentinels: dummy head and tail remove every null check
 *   LFU: map key -> node, map freq -> its own recency list, and minFreq
 *
 * APPROACH
 *   1. The HashMap finds a node in O(1); the doubly linked list removes and re-inserts it
 *      in O(1) because each node knows both neighbours.
 *   2. The tail is always the least recently used: evict it when full.
 *
 * KEY INSIGHT
 *   Neither structure alone is enough: a map has no order, a list has no O(1) lookup. The
 *   map stores POINTERS into the list, so "find" and "reorder" are both O(1). In Java,
 *   LinkedHashMap(accessOrder = true) is exactly this pair, ready made.
 *
 * COMPLEXITY
 *   O(1) per get / put; space O(capacity).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LRU with LinkedHashMap           accessOrder = true + removeEldestEntry
 *   [coded] LC 460  LFU Cache                freq -> LinkedHashSet of keys; minFreq tells
 *                                            which bucket to evict from (its oldest key)
 *           LC 432  All O(1) Data Structure  buckets of keys by count in a linked list
 *           LC 1756 MRU Queue                order statistics; sqrt decomposition or BIT
 *           Time-based expiry (TTL cache)    the same list ordered by expiry time
 *
 * PITFALLS
 *   - put on an EXISTING key must also refresh its recency.
 *   - Remove the evicted key from the map too, not only from the list.
 *   - LFU: a put of a new key resets minFreq to 1; ties evict the least recent.
 *
 * DEEP DIVE
 *   C05_LRUCache, D01_LFUCache (19-Design-Data-Structures)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;

class LruLfuCache {

    // Canonical LC 146 with a hand-made doubly linked list.
    static class LRUCache {
        static class Node {
            int key;
            int value;
            Node prev;
            Node next;

            Node(int key, int value) {
                this.key = key;
                this.value = value;
            }
        }

        private final int capacity;
        private final Map<Integer, Node> map = new HashMap<>();
        private final Node head = new Node(0, 0);      // newest after head
        private final Node tail = new Node(0, 0);      // oldest before tail

        LRUCache(int capacity) {
            this.capacity = capacity;
            head.next = tail;
            tail.prev = head;
        }

        int get(int key) {
            Node n = map.get(key);
            if (n == null) {
                return -1;
            }
            unlink(n);
            addFront(n);
            return n.value;
        }

        void put(int key, int value) {
            Node n = map.get(key);
            if (n != null) {
                n.value = value;
                unlink(n);
                addFront(n);
                return;
            }
            if (map.size() == capacity) {
                Node oldest = tail.prev;
                unlink(oldest);
                map.remove(oldest.key);
            }
            n = new Node(key, value);
            map.put(key, n);
            addFront(n);
        }

        private void unlink(Node n) {
            n.prev.next = n.next;
            n.next.prev = n.prev;
        }

        private void addFront(Node n) {
            n.next = head.next;
            n.prev = head;
            head.next.prev = n;
            head.next = n;
        }
    }

    // LRU with the JDK: LinkedHashMap in access order evicts its eldest entry.
    static class LinkedLru extends LinkedHashMap<Integer, Integer> {
        private final int capacity;

        LinkedLru(int capacity) {
            super(16, 0.75f, true);                // true = order by access, not insertion
            this.capacity = capacity;
        }

        int read(int key) {
            return getOrDefault(key, -1);
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) {
            return size() > capacity;
        }
    }

    // LC 460.
    static class LFUCache {
        private final int capacity;
        private final Map<Integer, Integer> value = new HashMap<>();
        private final Map<Integer, Integer> freq = new HashMap<>();
        private final Map<Integer, LinkedHashSet<Integer>> byFreq = new HashMap<>();
        private int minFreq;

        LFUCache(int capacity) {
            this.capacity = capacity;
        }

        int get(int key) {
            if (!value.containsKey(key)) {
                return -1;
            }
            touch(key);
            return value.get(key);
        }

        void put(int key, int v) {
            if (capacity == 0) {
                return;
            }
            if (value.containsKey(key)) {
                value.put(key, v);
                touch(key);
                return;
            }
            if (value.size() == capacity) {
                Iterator<Integer> oldest = byFreq.get(minFreq).iterator();
                int evict = oldest.next();         // least frequent, then least recent
                oldest.remove();
                value.remove(evict);
                freq.remove(evict);
            }
            value.put(key, v);
            freq.put(key, 1);
            byFreq.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(key);
            minFreq = 1;
        }

        // Move key from its frequency bucket to the next one.
        private void touch(int key) {
            int f = freq.get(key);
            byFreq.get(f).remove(key);
            if (f == minFreq && byFreq.get(f).isEmpty()) {
                minFreq++;
            }
            freq.put(key, f + 1);
            byFreq.computeIfAbsent(f + 1, k -> new LinkedHashSet<>()).add(key);
        }
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        LRUCache lru = new LRUCache(2);
        List<Integer> got = new ArrayList<>();
        lru.put(1, 1);
        lru.put(2, 2);
        got.add(lru.get(1));
        lru.put(3, 3);                             // evicts 2
        got.add(lru.get(2));
        lru.put(4, 4);                             // evicts 1
        got.add(lru.get(1));
        got.add(lru.get(3));
        got.add(lru.get(4));
        check("LC 146 hand-made list", got, "[1, -1, -1, 3, 4]");

        LRUCache refresh = new LRUCache(2);
        refresh.put(1, 1);
        refresh.put(2, 2);
        refresh.put(1, 10);                        // update refreshes key 1
        refresh.put(3, 3);                         // so 2 is the one evicted
        check("LC 146 put refreshes recency", refresh.get(2) + "," + refresh.get(1), "-1,10");

        LinkedLru jdk = new LinkedLru(2);
        List<Integer> got2 = new ArrayList<>();
        jdk.put(1, 1);
        jdk.put(2, 2);
        got2.add(jdk.read(1));
        jdk.put(3, 3);
        got2.add(jdk.read(2));
        jdk.put(4, 4);
        got2.add(jdk.read(1));
        got2.add(jdk.read(3));
        got2.add(jdk.read(4));
        check("LC 146 LinkedHashMap", got2, "[1, -1, -1, 3, 4]");

        LFUCache lfu = new LFUCache(2);
        List<Integer> got3 = new ArrayList<>();
        lfu.put(1, 1);
        lfu.put(2, 2);
        got3.add(lfu.get(1));
        lfu.put(3, 3);                             // evicts 2 (used least)
        got3.add(lfu.get(2));
        got3.add(lfu.get(3));
        lfu.put(4, 4);                             // 1 and 3 tie on count; 1 is older
        got3.add(lfu.get(1));
        got3.add(lfu.get(3));
        got3.add(lfu.get(4));
        check("LC 460 six reads", got3, "[1, -1, 3, -1, 3, 4]");
    }
}

/*
 * =====================================================================
 *  P103 Design: Combine Structures for O(1) Operations   Canonical LC 380 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 380, Insert Delete GetRandom O(1))
 *   A set with insert(val), remove(val) (both return whether they changed the set) and
 *   getRandom() returning each present element with equal probability, all in average O(1).
 *
 * EXAMPLE
 *   insert(1) true, remove(2) false, insert(2) true, getRandom() 1 or 2, remove(1) true,
 *   insert(2) false, getRandom() 2
 *
 * RECOGNIZE WHEN
 *   - A list of required operations, each "in O(1)", that no single collection supports:
 *     random access + delete, min + push/pop, FIFO from stacks, uniform sampling of a stream.
 *   - The trick is to keep TWO structures in sync, or to store extra info with each item.
 *   Not this if: eviction by recency / frequency -> P102_LruLfuCache; values change over
 *   time with lookups by timestamp -> P104_VersionedTimeMap.
 *
 * TEMPLATE
 *   random + delete:  list of values + map value -> index; delete = move the LAST value into
 *                     the hole, update its index, drop the last slot
 *   min stack:        push (value, min so far) pairs
 *   queue by stacks:  in-stack for pushes; out-stack for pops, refilled only when empty
 *   reservoir:        k-th item replaces the kept one with probability 1 / k
 *
 * APPROACH
 *   1. The ArrayList gives O(1) random access; the HashMap gives O(1) "where is val?".
 *   2. Removing from the middle of a list is O(n), so swap the target with the last element
 *      and remove the last one instead.
 *
 * KEY INSIGHT
 *   When the ORDER of elements does not matter, any deletion can be turned into "delete the
 *   last element" by a swap. Pairing each structure with an index map (or storing a running
 *   aggregate next to each element) is the general recipe for O(1) designs.
 *
 * COMPLEXITY
 *   All operations O(1) average (queue: O(1) amortised); space O(n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 155  Min Stack                each entry stores the minimum below it too
 *   [coded] LC 232  Queue Using Stacks       move in -> out only when out is empty
 *   [coded] LC 382  Linked List Random Node  reservoir sampling: keep node k with prob 1/k
 *           LC 381  RandomizedCollection     duplicates: map value -> SET of indices
 *           LC 716  Max Stack                TreeMap + doubly linked list (popMax in log n)
 *           LC 225  Stack Using Queues       rotate the queue after each push
 *           LC 528  Random Pick with Weight  -> P001_PrefixSumRangeQuery
 *
 * PITFALLS
 *   - LC 380 remove: update the moved element's index BEFORE removing the last slot, and
 *     handle "removing the last element itself".
 *   - Min stack: store the min per entry, or a separate stack pushed on <= (not <).
 *   - Queue by stacks: refilling out on every pop breaks the amortised O(1).
 *
 * DEEP DIVE
 *   C03_InsertDeleteGetRandomOof1, A02_MinStack, A01_RandomPickIndex
 *   (19-Design-Data-Structures), A04_QueueUsingStacks (07-Stack-Queue-Monotonic)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

class ConstantTimeCombos {

    // Canonical LC 380.
    static class RandomizedSet {
        private final List<Integer> values = new ArrayList<>();
        private final Map<Integer, Integer> indexOf = new HashMap<>();
        private final Random random = new Random(7);

        boolean insert(int val) {
            if (indexOf.containsKey(val)) {
                return false;
            }
            indexOf.put(val, values.size());
            values.add(val);
            return true;
        }

        boolean remove(int val) {
            Integer i = indexOf.remove(val);
            if (i == null) {
                return false;
            }
            int last = values.remove(values.size() - 1);
            if (i < values.size()) {
                values.set(i, last);               // move the last value into the hole
                indexOf.put(last, i);
            }
            return true;
        }

        int getRandom() {
            return values.get(random.nextInt(values.size()));
        }
    }

    // LC 155: each entry remembers the minimum at the time it was pushed.
    static class MinStack {
        private final Deque<int[]> stack = new ArrayDeque<>();   // {value, min so far}

        void push(int val) {
            int min = stack.isEmpty() ? val : Math.min(val, stack.peek()[1]);
            stack.push(new int[]{val, min});
        }

        void pop() {
            stack.pop();
        }

        int top() {
            return stack.peek()[0];
        }

        int getMin() {
            return stack.peek()[1];
        }
    }

    // LC 232.
    static class MyQueue {
        private final Deque<Integer> in = new ArrayDeque<>();
        private final Deque<Integer> out = new ArrayDeque<>();

        void push(int x) {
            in.push(x);
        }

        int pop() {
            peek();
            return out.pop();
        }

        int peek() {
            if (out.isEmpty()) {
                while (!in.isEmpty()) {
                    out.push(in.pop());            // reverses the order once
                }
            }
            return out.peek();
        }

        boolean empty() {
            return in.isEmpty() && out.isEmpty();
        }
    }

    // LC 382: one pass over a list of unknown length, uniform choice (reservoir of size 1).
    static int reservoirPick(List<Integer> stream, Random random) {
        int chosen = 0;
        int seen = 0;
        for (int x : stream) {
            seen++;
            if (random.nextInt(seen) == 0) {
                chosen = x;                        // keep the seen-th item with prob 1 / seen
            }
        }
        return chosen;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        RandomizedSet set = new RandomizedSet();
        List<Boolean> ops = new ArrayList<>();
        ops.add(set.insert(1));
        ops.add(set.remove(2));
        ops.add(set.insert(2));
        int r = set.getRandom();
        ops.add(r == 1 || r == 2);
        ops.add(set.remove(1));
        ops.add(set.insert(2));
        check("LC 380 operations", ops, "[true, false, true, true, true, false]");
        check("LC 380 only 2 left", set.getRandom(), 2);
        set.insert(5);
        set.insert(9);
        set.remove(2);                             // removes from the middle via swap
        check("LC 380 after middle removal",
                set.remove(9) && set.remove(5) && !set.remove(2), true);

        MinStack ms = new MinStack();
        ms.push(-2);
        ms.push(0);
        ms.push(-3);
        int min1 = ms.getMin();
        ms.pop();
        check("LC 155 min, top, min", min1 + "," + ms.top() + "," + ms.getMin(), "-3,0,-2");

        MyQueue q = new MyQueue();
        q.push(1);
        q.push(2);
        int peek = q.peek();
        int pop = q.pop();
        check("LC 232 peek, pop, empty", peek + "," + pop + "," + q.empty(), "1,1,false");
        q.push(3);
        check("LC 232 order kept after refill",
                q.pop() + "," + q.pop() + "," + q.empty(), "2,3,true");

        Random random = new Random(42);
        int[] hits = new int[3];
        for (int i = 0; i < 30000; i++) {
            hits[reservoirPick(List.of(10, 20, 30), random) / 10 - 1]++;
        }
        boolean uniform = true;
        for (int h : hits) {
            uniform &= Math.abs(h - 10000) < 500;  // each about a third of the draws
        }
        check("LC 382 roughly uniform", uniform, true);
    }
}

/*
 * =====================================================================
 *  P104 Design: Versioned and Time-Windowed Data   Canonical LC 981 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 981, Time Based Key-Value Store)
 *   set(key, value, timestamp) stores a value; get(key, timestamp) returns the value set at
 *   the LARGEST timestamp <= the given one, or "" if none. Timestamps of set() only grow.
 *
 * EXAMPLE
 *   set(foo, bar, 1); get(foo, 1) = bar; get(foo, 3) = bar; set(foo, bar2, 4);
 *   get(foo, 4) = bar2; get(foo, 5) = bar2; get(foo, 0) = ""
 *
 * RECOGNIZE WHEN
 *   - "value at time t", "as of version v", "snapshot", "undo history": many versions per
 *     key, queried by the latest version <= t.
 *   - "hits / requests in the last N seconds", "allow a message once every 10 seconds":
 *     only a recent time window matters.
 *   Not this if: only the current value matters -> a plain HashMap; you need the k-th
 *   largest value in a window -> P045_TwoHeaps.
 *
 * TEMPLATE
 *   versions: key -> list of (time, value) appended in time order
 *   get(key, t): binary search the last entry with time <= t (or TreeMap.floorEntry(t))
 *   snapshot array: per index, list of (snapId, value); get = floor search on snapId
 *   sliding time window: queue of timestamps; pop the front while it is older than t - W
 *
 * APPROACH
 *   1. Because set() timestamps increase, each key's list is already sorted by time.
 *   2. get() binary searches that list for the last time <= t.
 *
 * KEY INSIGHT
 *   Never overwrite history: append versions, and let a floor search answer "as of". When
 *   writes arrive in time order, a list plus binary search beats a TreeMap; when they do
 *   not, TreeMap.floorEntry is the same idea with O(log n) inserts.
 *
 * COMPLEXITY
 *   set O(1), get O(log v) per key. Hit counter: O(1) amortised per call.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 1146 Snapshot Array           per index (snapId, value) history; floor search
 *   [coded] LC 362  Design Hit Counter       queue of hit times; drop those <= t - 300
 *   [coded] LC 359  Logger Rate Limiter      map message -> next allowed time
 *           LC 1352 Product of Last K        prefix products, reset on 0
 *           LC 2034 Stock Price Fluctuation  latest price per time + TreeMap of prices
 *           LC 635  Log Storage System       timestamps as strings, compare by granularity
 *
 * PITFALLS
 *   - "" (not null) when no version is old enough.
 *   - LC 1146: several sets between two snaps keep only the last one for that snap id.
 *   - Hit counter window: "last 300 seconds" includes t - 299 .. t, so drop t - 300 and older.
 *
 * DEEP DIVE
 *   C06_TimeBasedKeyValueStore, C07_SnapshotArray, C02_DesignHitCounter,
 *   B01_LoggerRateLimiter (19-Design-Data-Structures)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class VersionedTimeMap {

    // Canonical LC 981.
    static class TimeMap {
        private final Map<String, List<Integer>> times = new HashMap<>();
        private final Map<String, List<String>> values = new HashMap<>();

        void set(String key, String value, int timestamp) {
            times.computeIfAbsent(key, k -> new ArrayList<>()).add(timestamp);
            values.computeIfAbsent(key, k -> new ArrayList<>()).add(value);
        }

        String get(String key, int timestamp) {
            List<Integer> t = times.get(key);
            if (t == null) {
                return "";
            }
            int i = lastAtMost(t, timestamp);
            return i < 0 ? "" : values.get(key).get(i);
        }
    }

    // Index of the last element <= x in a sorted list, or -1.
    static int lastAtMost(List<Integer> sorted, int x) {
        int lo = 0;
        int hi = sorted.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (sorted.get(mid) <= x) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo - 1;
    }

    // LC 1146.
    static class SnapshotArray {
        private final List<List<int[]>> history = new ArrayList<>();   // {snapId, value}
        private int snapId;

        SnapshotArray(int length) {
            for (int i = 0; i < length; i++) {
                List<int[]> h = new ArrayList<>();
                h.add(new int[]{0, 0});
                history.add(h);
            }
        }

        void set(int index, int val) {
            List<int[]> h = history.get(index);
            if (h.get(h.size() - 1)[0] == snapId) {
                h.get(h.size() - 1)[1] = val;      // same snap: overwrite
            } else {
                h.add(new int[]{snapId, val});
            }
        }

        int snap() {
            return snapId++;
        }

        int get(int index, int snap) {
            List<int[]> h = history.get(index);
            int lo = 0;
            int hi = h.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (h.get(mid)[0] <= snap) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            return h.get(lo - 1)[1];
        }
    }

    // LC 362: hits in the past 300 seconds; timestamps never decrease.
    static class HitCounter {
        private final Deque<Integer> hits = new ArrayDeque<>();

        void hit(int timestamp) {
            hits.addLast(timestamp);
        }

        int getHits(int timestamp) {
            while (!hits.isEmpty() && hits.peekFirst() <= timestamp - 300) {
                hits.pollFirst();
            }
            return hits.size();
        }
    }

    // LC 359: each message may be printed at most once every 10 seconds.
    static class Logger {
        private final Map<String, Integer> nextAllowed = new HashMap<>();

        boolean shouldPrintMessage(int timestamp, String message) {
            if (timestamp < nextAllowed.getOrDefault(message, 0)) {
                return false;
            }
            nextAllowed.put(message, timestamp + 10);
            return true;
        }
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        TimeMap tm = new TimeMap();
        tm.set("foo", "bar", 1);
        List<String> got = new ArrayList<>();
        got.add(tm.get("foo", 1));
        got.add(tm.get("foo", 3));
        tm.set("foo", "bar2", 4);
        got.add(tm.get("foo", 4));
        got.add(tm.get("foo", 5));
        check("LC 981 four reads", got, "[bar, bar, bar2, bar2]");
        check("LC 981 before any set", "[" + tm.get("foo", 0) + "]", "[]");
        check("LC 981 unknown key", "[" + tm.get("nope", 9) + "]", "[]");

        SnapshotArray sa = new SnapshotArray(3);
        sa.set(0, 5);
        int s0 = sa.snap();
        sa.set(0, 6);
        check("LC 1146 snap 0 sees 5", sa.get(0, s0), 5);
        int s1 = sa.snap();
        check("LC 1146 snap 1 sees 6", sa.get(0, s1), 6);
        check("LC 1146 untouched index", sa.get(2, s1), 0);

        HitCounter hc = new HitCounter();
        hc.hit(1);
        hc.hit(2);
        hc.hit(3);
        int a = hc.getHits(4);
        hc.hit(300);
        int b = hc.getHits(300);
        int c = hc.getHits(301);
        check("LC 362 three reads", a + "," + b + "," + c, "3,4,3");

        Logger log = new Logger();
        List<Boolean> printed = new ArrayList<>();
        printed.add(log.shouldPrintMessage(1, "foo"));
        printed.add(log.shouldPrintMessage(2, "bar"));
        printed.add(log.shouldPrintMessage(3, "foo"));
        printed.add(log.shouldPrintMessage(8, "bar"));
        printed.add(log.shouldPrintMessage(10, "foo"));
        printed.add(log.shouldPrintMessage(11, "foo"));
        check("LC 359 six messages", printed, "[true, true, false, false, false, true]");
    }
}

/*
 * =====================================================================
 *  P105 Design: Lazy Iterators   Canonical LC 341 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 341, Flatten Nested List Iterator)
 *   Each element is an integer or a list whose elements are integers or lists. Implement
 *   next() and hasNext() that walk all integers in order. (LeetCode's element type is
 *   called NestedInteger; here it is NestedEntry.)
 *
 * EXAMPLE
 *   [[1,1],2,[1,1]]  ->  1, 1, 2, 1, 1
 *   [1,[4,[6]]]      ->  1, 4, 6
 *   [[]]             ->  (nothing)
 *
 * RECOGNIZE WHEN
 *   - "implement an iterator" over a structure: nested lists, a BST in order, a 2D vector,
 *     zigzag over several lists, run-length data.
 *   - next() / hasNext() should be cheap and memory should not hold the whole flattened
 *     result.
 *   Not this if: you are asked for the whole result at once -> a plain traversal is simpler
 *   (P051_IterativeTraversals for trees).
 *
 * TEMPLATE
 *   keep the traversal's state explicitly (a stack of positions / nodes)
 *   hasNext(): advance the state until the top is a real element (or nothing is left);
 *              do the work HERE, so hasNext() can be called any number of times
 *   next():    hasNext(); then pop / return the element at the top
 *   peeking:   cache one element ahead ("next" buffered); peek returns the cache
 *
 * APPROACH
 *   1. A stack of list iterators replaces the recursion of a depth-first walk.
 *   2. hasNext() opens lists until the next item is an integer (or every list is done).
 *   3. next() returns that integer.
 *
 * KEY INSIGHT
 *   An iterator is a recursive traversal paused between steps, so its state must live in
 *   fields: the explicit stack IS the paused call stack. Doing the "find the next element"
 *   work in hasNext() keeps empty lists and repeated hasNext() calls correct.
 *
 * COMPLEXITY
 *   O(1) amortised per next(); space O(depth) for nested lists, O(h) for a BST.
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 284  Peeking Iterator         buffer one element ahead
 *   [coded] LC 173  BST Iterator             stack of the left spine; pop, then push the
 *                                            left spine of the right child
 *           LC 251  Flatten 2D Vector        (row, col) pointers; skip empty rows in hasNext
 *           LC 281  Zigzag Iterator          queue of iterators; rotate after each next
 *           LC 900  RLE Iterator             consume counts lazily
 *           LC 1586 BST Iterator II          keep a list of visited values for prev()
 *
 * PITFALLS
 *   - [[]] and [[], [3]]: empty lists must be skipped in hasNext(), not next().
 *   - Calling hasNext() twice must not consume anything.
 *   - Do not flatten everything in the constructor unless the interviewer allows O(n) memory.
 *
 * DEEP DIVE
 *   B01_NestedListWeightSum (14-Backtracking-Recursion)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;

class IteratorDesign {

    // LeetCode's NestedInteger: either one integer or a list of entries.
    static class NestedEntry {
        Integer value;
        List<NestedEntry> list;

        // Builds from plain Java values: an Integer, or a List of such values.
        static NestedEntry of(Object o) {
            NestedEntry e = new NestedEntry();
            if (o instanceof Integer i) {
                e.value = i;
            } else {
                e.list = new ArrayList<>();
                for (Object child : (List<?>) o) {
                    e.list.add(of(child));
                }
            }
            return e;
        }

        static List<NestedEntry> listOf(List<?> items) {
            return of(items).list;
        }
    }

    // Canonical LC 341.
    static class NestedIterator implements Iterator<Integer> {
        private final Deque<Iterator<NestedEntry>> stack = new ArrayDeque<>();
        private Integer nextValue;

        NestedIterator(List<NestedEntry> nestedList) {
            stack.push(nestedList.iterator());
        }

        @Override
        public boolean hasNext() {
            while (nextValue == null && !stack.isEmpty()) {
                if (!stack.peek().hasNext()) {
                    stack.pop();                   // this list is finished
                    continue;
                }
                NestedEntry e = stack.peek().next();
                if (e.value != null) {
                    nextValue = e.value;
                } else {
                    stack.push(e.list.iterator()); // descend into the inner list
                }
            }
            return nextValue != null;
        }

        @Override
        public Integer next() {
            hasNext();
            Integer v = nextValue;
            nextValue = null;
            return v;
        }
    }

    // LC 284.
    static class PeekingIterator implements Iterator<Integer> {
        private final Iterator<Integer> it;
        private Integer buffered;

        PeekingIterator(Iterator<Integer> iterator) {
            it = iterator;
            buffered = it.hasNext() ? it.next() : null;
        }

        Integer peek() {
            return buffered;
        }

        @Override
        public Integer next() {
            Integer v = buffered;
            buffered = it.hasNext() ? it.next() : null;
            return v;
        }

        @Override
        public boolean hasNext() {
            return buffered != null;
        }
    }

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        // Builds a tree from LeetCode's level-order list (null = missing child).
        static TreeNode of(Integer... v) {
            if (v.length == 0 || v[0] == null) {
                return null;
            }
            TreeNode root = new TreeNode(v[0]);
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (i < v.length) {
                TreeNode n = queue.poll();
                if (v[i] != null) {
                    n.left = new TreeNode(v[i]);
                    queue.add(n.left);
                }
                i++;
                if (i < v.length && v[i] != null) {
                    n.right = new TreeNode(v[i]);
                    queue.add(n.right);
                }
                i++;
            }
            return root;
        }
    }

    // LC 173: in-order iterator over a BST.
    static class BSTIterator {
        private final Deque<TreeNode> stack = new ArrayDeque<>();

        BSTIterator(TreeNode root) {
            pushLeft(root);
        }

        int next() {
            TreeNode n = stack.pop();
            pushLeft(n.right);
            return n.val;
        }

        boolean hasNext() {
            return !stack.isEmpty();
        }

        private void pushLeft(TreeNode n) {
            while (n != null) {
                stack.push(n);
                n = n.left;
            }
        }
    }

    static List<Integer> drain(Iterator<Integer> it) {
        List<Integer> out = new ArrayList<>();
        while (it.hasNext()) {
            out.add(it.next());
        }
        return out;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        List<Object> a = List.of(List.of(1, 1), 2, List.of(1, 1));
        check("LC 341 [[1,1],2,[1,1]]",
                drain(new NestedIterator(NestedEntry.listOf(a))), "[1, 1, 2, 1, 1]");
        List<Object> b = List.of(1, List.of(4, List.of(6)));
        check("LC 341 [1,[4,[6]]]", drain(new NestedIterator(NestedEntry.listOf(b))), "[1, 4, 6]");
        List<Object> c = List.of(List.of(), List.of(List.of()), 3);
        check("LC 341 empty lists skipped",
                drain(new NestedIterator(NestedEntry.listOf(c))), "[3]");
        NestedIterator twice = new NestedIterator(NestedEntry.listOf(List.of(List.of(), 7)));
        check("LC 341 hasNext twice is safe",
                twice.hasNext() && twice.hasNext() && twice.next() == 7, true);

        PeekingIterator pk = new PeekingIterator(List.of(1, 2, 3).iterator());
        String trace = pk.next() + "," + pk.peek() + "," + pk.next() + ","
                + pk.next() + "," + pk.hasNext();
        check("LC 284 next peek next next hasNext", trace, "1,2,2,3,false");

        BSTIterator bst = new BSTIterator(TreeNode.of(7, 3, 15, null, null, 9, 20));
        StringBuilder sb = new StringBuilder();
        while (bst.hasNext()) {
            sb.append(bst.next()).append(' ');
        }
        check("LC 173 in order", sb.toString().trim(), "3 7 9 15 20");
        check("LC 173 empty tree", new BSTIterator(null).hasNext(), false);
    }
}

