/*
 * =====================================================================
 *  P106 KMP and the Prefix Function   Canonical LC 28 | Easy (Medium with KMP)
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 28, Find the Index of the First Occurrence in a String)
 *   Return the index of the first occurrence of needle in haystack, or -1. Do it in
 *   O(n + m), not O(n * m).
 *
 * EXAMPLE
 *   "sadbutsad", "sad"  ->  0
 *   "leetcode",  "leeto" ->  -1
 *   "aaaaab",    "aab"  ->  3      the naive scan restarts too far back here
 *
 * RECOGNIZE WHEN
 *   - Find a pattern in a text in linear time, or count occurrences.
 *   - Questions about a string's own borders: "longest prefix that is also a suffix",
 *     "is s a repetition of a smaller block", "shortest palindrome by adding in front".
 *   Not this if: many patterns at once -> P064_TrieDfsBitTrie; repeated substrings of a
 *   given length -> P107_RollingHash; library indexOf is allowed and fine for the interview.
 *
 * TEMPLATE
 *   lps[i] = length of the longest proper prefix of p[0..i] that is also its suffix
 *   build:  k = 0; for i in 1..m-1:
 *               while k > 0 and p[i] != p[k]: k = lps[k - 1]     // fall back along borders
 *               if p[i] == p[k]: k++
 *               lps[i] = k
 *   search: the same loop over the text with k = matched length; k == m -> found at i - m + 1
 *
 * APPROACH
 *   1. Precompute lps for the pattern.
 *   2. Scan the text once; on a mismatch, keep the longest border of what matched so far
 *      instead of restarting.
 *
 * KEY INSIGHT
 *   After matching k characters, the text's last k characters ARE the pattern's first k.
 *   On a mismatch, the next possible match must start at a border of that prefix, and lps
 *   tells you the longest one, so the text pointer never moves back.
 *
 * COMPLEXITY
 *   Time O(n + m), space O(m).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 459  Repeated Substring       n % (n - lps[n - 1]) == 0 and lps[n - 1] > 0
 *   [coded] LC 214  Shortest Palindrome      lps of s + "#" + reverse(s) gives the longest
 *                                            palindromic prefix; prepend the rest reversed
 *   [coded] LC 1392 Longest Happy Prefix     s.substring(0, lps[n - 1])
 *           LC 686  Repeated String Match    repeat a until long enough, then KMP for b
 *           LC 1764 Form Array by Concatenation  KMP each group in order
 *           Z-function                       z[i] = longest match of s and s[i..]; same uses
 *
 * PITFALLS
 *   - Fall back with k = lps[k - 1] in a WHILE loop, not once.
 *   - lps[0] = 0 always (a proper prefix of one character is empty).
 *   - LC 214: the separator '#' stops the border from crossing between the two halves.
 *
 * DEEP DIVE
 *   D02_SingleLoopSubstringCheckKMP (18-Sorting-Searching-Algorithms)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
class KmpPrefixFunction {

    static int[] prefixFunction(String p) {
        int[] lps = new int[p.length()];
        int k = 0;
        for (int i = 1; i < p.length(); i++) {
            while (k > 0 && p.charAt(i) != p.charAt(k)) {
                k = lps[k - 1];
            }
            if (p.charAt(i) == p.charAt(k)) {
                k++;
            }
            lps[i] = k;
        }
        return lps;
    }

    // Canonical LC 28.
    static int strStr(String text, String p) {
        if (p.isEmpty()) {
            return 0;
        }
        int[] lps = prefixFunction(p);
        int k = 0;                                 // characters of p matched so far
        for (int i = 0; i < text.length(); i++) {
            while (k > 0 && text.charAt(i) != p.charAt(k)) {
                k = lps[k - 1];
            }
            if (text.charAt(i) == p.charAt(k)) {
                k++;
            }
            if (k == p.length()) {
                return i - k + 1;
            }
        }
        return -1;
    }

    // LC 459.
    static boolean repeatedSubstringPattern(String s) {
        int n = s.length();
        int border = prefixFunction(s)[n - 1];
        return border > 0 && n % (n - border) == 0;
    }

    // LC 214: add characters in FRONT to make s a palindrome, as few as possible.
    static String shortestPalindrome(String s) {
        String rev = new StringBuilder(s).reverse().toString();
        int[] lps = prefixFunction(s + "#" + rev);
        int keep = lps[lps.length - 1];            // longest palindromic prefix of s
        return rev.substring(0, s.length() - keep) + s;
    }

    // LC 1392: longest proper prefix that is also a suffix.
    static String longestPrefix(String s) {
        return s.substring(0, prefixFunction(s)[s.length() - 1]);
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 28 sadbutsad", strStr("sadbutsad", "sad"), 0);
        check("LC 28 leetcode/leeto", strStr("leetcode", "leeto"), -1);
        check("LC 28 aaaaab/aab", strStr("aaaaab", "aab"), 3);
        check("LC 28 needle at the end", strStr("abcabd", "abd"), 3);

        check("LC 459 abab", repeatedSubstringPattern("abab"), true);
        check("LC 459 aba", repeatedSubstringPattern("aba"), false);
        check("LC 459 abcabcabcabc", repeatedSubstringPattern("abcabcabcabc"), true);
        check("LC 459 aabaaba (border but no repeat)", repeatedSubstringPattern("aabaaba"), false);

        check("LC 214 aacecaaa", shortestPalindrome("aacecaaa"), "aaacecaaa");
        check("LC 214 abcd", shortestPalindrome("abcd"), "dcbabcd");
        check("LC 214 empty", "[" + shortestPalindrome("") + "]", "[]");

        check("LC 1392 level", longestPrefix("level"), "l");
        check("LC 1392 ababab", longestPrefix("ababab"), "abab");
    }
}

/*
 * =====================================================================
 *  P107 Rolling Hash (Rabin-Karp)   Canonical LC 187 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 187, Repeated DNA Sequences)
 *   s holds only A, C, G, T. Return every 10-letter substring that occurs more than once.
 *
 * EXAMPLE
 *   "AAAAACCCCCAAAAACCCCCCAAAAAGGGTTT"  ->  [AAAAACCCCC, CCCCCAAAAA]
 *   "AAAAAAAAAAAAA"                     ->  [AAAAAAAAAA]
 *
 * RECOGNIZE WHEN
 *   - Compare MANY substrings of the same length: duplicates, "does any length-L substring
 *     appear twice", pattern search where hashing is easier than KMP.
 *   - Combined with binary search over the length ("longest duplicate substring").
 *   Not this if: one pattern in one text -> P106_KmpPrefixFunction (no collisions to
 *   handle); the window is small and the alphabet tiny -> a fixed window of counts
 *   (P016_FixedWindowFrequencyMatch).
 *
 * TEMPLATE
 *   h(window) = sum of code(c_i) * B^(L - 1 - i)  (mod M)
 *   slide:  h = (h - code(out) * B^(L - 1)) * B + code(in)   (mod M, keep it non-negative)
 *   a hash match is only a CANDIDATE: confirm with an equality check (or use two moduli)
 *   tiny alphabets: pack exactly (2 bits per DNA letter) and there are no collisions at all
 *
 * APPROACH
 *   1. Encode A, C, G, T as 0..3; a 10-letter window is a 20-bit integer.
 *   2. Slide: shift left 2 bits, add the new letter, mask to 20 bits.
 *   3. A window seen for the second time is reported once.
 *
 * KEY INSIGHT
 *   Sliding a hash costs O(1) per step because the new hash is the old one minus the
 *   leaving character plus the entering one. Comparing hashes instead of strings turns
 *   O(n * L) substring work into O(n). For DNA the "hash" is exact, so no checking is needed.
 *
 * COMPLEXITY
 *   Time O(n) per window length (O(n log n) with the binary search), space O(n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 1044 Longest Duplicate Substring  binary search the length; Rabin-Karp per
 *                                            length; confirm candidates by comparing strings
 *   [coded] LC 28 by Rabin-Karp              hash the needle, slide over the haystack
 *           LC 1316 Distinct Echo Substrings for each half length, compare hashes of halves
 *           LC 718  Longest Repeated Subarray binary search + rolling hash (or DP)
 *           LC 1923 Longest Common Subpath   binary search + hash sets per path
 *
 * PITFALLS
 *   - Negative values after subtraction: add M before taking % M.
 *   - Overflow: keep every product below 2^63 (base and modulus around 1e9 fit in long).
 *   - Collisions are rare but possible: verify, or use two independent hashes.
 *
 * DEEP DIVE
 *   C02_RabinKarpAlgorithm (18-Sorting-Searching-Algorithms),
 *   C04_RepeatedDnaSequences (05-Hashing-Prefix-Sum)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

class RollingHash {

    static final long MOD = 1_000_000_007L;
    static final long BASE = 131;

    // Canonical LC 187: exact 2-bit packing, so no collisions.
    static List<String> findRepeatedDnaSequences(String s) {
        Map<Character, Integer> code = Map.of('A', 0, 'C', 1, 'G', 2, 'T', 3);
        Set<Integer> seen = new HashSet<>();
        Set<String> repeated = new HashSet<>();
        int window = 0;
        int mask = (1 << 20) - 1;                  // 10 letters x 2 bits
        for (int i = 0; i < s.length(); i++) {
            window = ((window << 2) | code.get(s.charAt(i))) & mask;
            if (i >= 9 && !seen.add(window)) {
                repeated.add(s.substring(i - 9, i + 1));
            }
        }
        List<String> out = new ArrayList<>(repeated);
        Collections.sort(out);                     // any order is accepted
        return out;
    }

    // LC 1044: longest substring that occurs at least twice (may overlap).
    static String longestDupSubstring(String s) {
        int lo = 1;
        int hi = s.length() - 1;
        String best = "";
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            String found = duplicateOfLength(s, mid);
            if (found != null) {
                best = found;                      // length mid works; try longer
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return best;
    }

    // Some substring of length len that appears twice, or null.
    private static String duplicateOfLength(String s, int len) {
        long power = 1;
        for (int i = 1; i < len; i++) {
            power = power * BASE % MOD;
        }
        Map<Long, List<Integer>> starts = new HashMap<>();
        long h = 0;
        for (int i = 0; i < s.length(); i++) {
            if (i >= len) {
                h = (h - s.charAt(i - len) * power % MOD + MOD) % MOD;   // drop the leaving char
            }
            h = (h * BASE + s.charAt(i)) % MOD;
            if (i >= len - 1) {
                int start = i - len + 1;
                List<Integer> same = starts.computeIfAbsent(h, k -> new ArrayList<>());
                for (int other : same) {
                    if (s.regionMatches(other, s, start, len)) {
                        return s.substring(start, start + len);       // confirmed, not a collision
                    }
                }
                same.add(start);
            }
        }
        return null;
    }

    // LC 28 with Rabin-Karp.
    static int strStr(String text, String p) {
        int m = p.length();
        if (m == 0) {
            return 0;
        }
        if (m > text.length()) {
            return -1;
        }
        long power = 1;
        for (int i = 1; i < m; i++) {
            power = power * BASE % MOD;
        }
        long target = 0;
        for (int i = 0; i < m; i++) {
            target = (target * BASE + p.charAt(i)) % MOD;
        }
        long h = 0;
        for (int i = 0; i < text.length(); i++) {
            if (i >= m) {
                h = (h - text.charAt(i - m) * power % MOD + MOD) % MOD;
            }
            h = (h * BASE + text.charAt(i)) % MOD;
            if (i >= m - 1 && h == target && text.startsWith(p, i - m + 1)) {
                return i - m + 1;
            }
        }
        return -1;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 187 two repeats", findRepeatedDnaSequences("AAAAACCCCCAAAAACCCCCCAAAAAGGGTTT"),
                "[AAAAACCCCC, CCCCCAAAAA]");
        check("LC 187 overlapping repeat",
                findRepeatedDnaSequences("AAAAAAAAAAAAA"), "[AAAAAAAAAA]");
        check("LC 187 too short", findRepeatedDnaSequences("ACGT"), "[]");

        check("LC 1044 banana", longestDupSubstring("banana"), "ana");
        check("LC 1044 abcd none", "[" + longestDupSubstring("abcd") + "]", "[]");
        check("LC 1044 aaaaa overlapping", longestDupSubstring("aaaaa"), "aaaa");

        check("LC 28 Rabin-Karp sadbutsad", strStr("sadbutsad", "sad"), 0);
        check("LC 28 Rabin-Karp leeto", strStr("leetcode", "leeto"), -1);
        check("LC 28 Rabin-Karp aaaaab", strStr("aaaaab", "aab"), 3);
    }
}

/*
 * =====================================================================
 *  P108 Careful Parsing and String Simulation   Canonical LC 8 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 8, String to Integer (atoi))
 *   Skip leading spaces, read an optional sign, then digits until a non-digit. Clamp to the
 *   32-bit range. Anything malformed before the digits gives 0.
 *
 * EXAMPLE
 *   "42"              ->  42
 *   "   -042"         ->  -42
 *   "1337c0d3"        ->  1337
 *   "words and 987"   ->  0
 *   "-91283472332"    ->  -2147483648     clamped
 *
 * RECOGNIZE WHEN
 *   - The problem is a precise spec over characters: number formats, compression, layout
 *     (zigzag, justification), comments, IP addresses. No clever algorithm, many edge cases.
 *   - Interviewers grade it on edge cases: empty input, signs, overflow, leading zeros.
 *   Not this if: there is real nesting (brackets, k[...]) -> P040_ExpressionEvaluation; you
 *   search for a pattern -> P106_KmpPrefixFunction.
 *
 * TEMPLATE
 *   one index i walks the string in PHASES (spaces, sign, digits, ...)
 *   each phase: while i < n and s[i] fits the phase: consume
 *   overflow check BEFORE result = result * 10 + d:
 *       if result > (MAX - d) / 10: clamp
 *   state flags (seenDigit, seenDot, seenExp) for validators instead of regexes
 *
 * APPROACH
 *   1. Skip spaces. 2. Read one sign. 3. Read digits, checking overflow before each step.
 *   4. Stop at the first non-digit; return sign * result.
 *
 * KEY INSIGHT
 *   Write the spec as an ordered list of phases and give each phase its own small loop.
 *   Check for overflow before it happens (compare against (MAX - d) / 10), because after it
 *   happens the value is already wrong.
 *
 * COMPLEXITY
 *   Time O(n), space O(1) (O(n) for LC 443's output written in place).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 443  String Compression       read a run, write the char and its count digits
 *                                            in place; return the new length
 *   [coded] LC 65   Valid Number             flags: digit seen, dot seen, exponent seen;
 *                                            a sign only at the start or right after 'e'
 *           LC 6    Zigzag Conversion        one StringBuilder per row, bounce the row index
 *           LC 68   Text Justification       greedy line fill, then spread the spaces
 *           LC 468  Validate IP Address      split carefully (keep trailing empty parts)
 *           LC 722  Remove Comments          a block-comment flag carried across lines
 *           LC 7    Reverse Integer          the same overflow check
 *
 * PITFALLS
 *   - "+-12" is 0: only one sign is allowed.
 *   - Integer.MIN_VALUE has no positive int counterpart; clamp by sign.
 *   - LC 65: "." and "e" alone are invalid, ".1" and "1." are valid.
 *
 * DEEP DIVE
 *   C02_ATOI, C03_StringCompression, D01_ValidNumber, C05_ZigzagConversion (04-Strings)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
class CarefulParsing {

    // Canonical LC 8.
    static int myAtoi(String s) {
        int i = 0;
        int n = s.length();
        while (i < n && s.charAt(i) == ' ') {
            i++;
        }
        int sign = 1;
        if (i < n && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
            sign = s.charAt(i) == '-' ? -1 : 1;
            i++;
        }
        int result = 0;
        while (i < n && Character.isDigit(s.charAt(i))) {
            int d = s.charAt(i) - '0';
            if (result > (Integer.MAX_VALUE - d) / 10) {
                return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            }
            result = result * 10 + d;
            i++;
        }
        return sign * result;
    }

    // LC 443: compress in place; returns the new length.
    static int compress(char[] chars) {
        int write = 0;
        int read = 0;
        while (read < chars.length) {
            char c = chars[read];
            int start = read;
            while (read < chars.length && chars[read] == c) {
                read++;
            }
            chars[write++] = c;
            int run = read - start;
            if (run > 1) {
                for (char d : String.valueOf(run).toCharArray()) {
                    chars[write++] = d;
                }
            }
        }
        return write;
    }

    // LC 65.
    static boolean isNumber(String s) {
        boolean digit = false;
        boolean dot = false;
        boolean exp = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                digit = true;
            } else if (c == '+' || c == '-') {
                if (i > 0 && s.charAt(i - 1) != 'e' && s.charAt(i - 1) != 'E') {
                    return false;                  // a sign only at the start or after e
                }
            } else if (c == '.') {
                if (dot || exp) {
                    return false;                  // one dot, and never in the exponent
                }
                dot = true;
            } else if (c == 'e' || c == 'E') {
                if (exp || !digit) {
                    return false;                  // one e, with digits before it
                }
                exp = true;
                digit = false;                     // the exponent needs its own digits
            } else {
                return false;
            }
        }
        return digit;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        check("LC 8 [42]", myAtoi("42"), 42);
        check("LC 8 [   -042]", myAtoi("   -042"), -42);
        check("LC 8 [1337c0d3]", myAtoi("1337c0d3"), 1337);
        check("LC 8 [0-1]", myAtoi("0-1"), 0);
        check("LC 8 [words and 987]", myAtoi("words and 987"), 0);
        check("LC 8 [-91283472332] clamp", myAtoi("-91283472332"), Integer.MIN_VALUE);
        check("LC 8 [2147483648] clamp", myAtoi("2147483648"), Integer.MAX_VALUE);
        check("LC 8 [+-12] two signs", myAtoi("+-12"), 0);

        char[] a = "aabbccc".toCharArray();
        int len = compress(a);
        check("LC 443 aabbccc", len + " " + new String(a, 0, len), "6 a2b2c3");
        char[] b = "a".toCharArray();
        int len2 = compress(b);
        check("LC 443 single", len2 + " " + new String(b, 0, len2), "1 a");
        char[] c = "abbbbbbbbbbbb".toCharArray();
