/*
 * =====================================================================
 *  P109 Fenwick Tree and Merge-Sort Counting   Canonical LC 307 | Medium
 * =====================================================================
 *
 * PROBLEM  (canonical: LeetCode 307, Range Sum Query - Mutable)
 *   Support update(index, val) and sumRange(left, right) on an array, both in O(log n).
 *
 * EXAMPLE
 *   [1, 3, 5]: sumRange(0, 2) = 9; update(1, 2); sumRange(0, 2) = 8
 *
 * RECOGNIZE WHEN
 *   - Prefix sums, but values CHANGE between queries (a static array is
 *     P001_PrefixSumRangeQuery).
 *   - "how many earlier / later elements are smaller / larger" (count by rank as you go).
 *   - Inversion-style counts: pairs i < j with a[i] > a[j] (or > 2 * a[j]).
 *   Not this if: the array never changes -> P001_PrefixSumRangeQuery; you need min / max or
 *   range updates -> P110_SegmentTree.
 *
 * TEMPLATE
 *   Fenwick (1-indexed tree[]):
 *       add(i, delta): for (; i <= n; i += i & -i) tree[i] += delta
 *       sum(i):        for (; i > 0;  i -= i & -i) s += tree[i]       // prefix 1..i
 *       range(l, r) = sum(r) - sum(l - 1)
 *   counting smaller-after-self: compress values to ranks, scan RIGHT to LEFT,
 *       answer[i] = sum(rank[i] - 1), then add(rank[i], 1)
 *   merge-sort counting: while merging two sorted halves, count cross pairs with two pointers
 *
 * APPROACH
 *   1. tree[i] stores the sum of a block of length (i & -i) ending at i.
 *   2. A prefix sum hops down by removing the lowest set bit; an update hops up by adding it.
 *   3. update(index, val) adds (val - old) at that index.
 *
 * KEY INSIGHT
 *   The lowest set bit of i splits 1..n into O(log n) blocks, so every prefix is the sum of
 *   at most log n stored blocks and every index belongs to at most log n blocks. Counting
 *   problems become prefix sums over RANKS: "how many seen values are smaller" is sum(rank - 1).
 *
 * COMPLEXITY
 *   Fenwick O(log n) per update / query, O(n) space. Merge-sort counting O(n log n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] LC 315  Count Smaller After Self Fenwick over value ranks, scanning right to left
 *   [coded] LC 493  Reverse Pairs            merge sort; before merging, count a[i] > 2 * b[j]
 *   [coded] Count inversions (GfG)           merge sort; every time the right side wins,
 *                                            add (left elements remaining)
 *           LC 327  Count of Range Sum       merge sort over prefix sums with a window
 *           LC 1649 Sorted Array Instructions  Fenwick: min(smaller, greater) per insert
 *           LC 2179 Count Good Triplets      Fenwick from both sides
 *
 * PITFALLS
 *   - Fenwick is 1-indexed: shift array indices by one.
 *   - Compress values first when they are large or negative.
 *   - LC 493: 2 * a[j] overflows int; compare in long.
 *
 * DEEP DIVE
 *   D03_SegmentTree, A05_MergeSort (18-Sorting-Searching-Algorithms)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
import java.util.Arrays;

class FenwickAndMergeCounting {

    static class Fenwick {
        private final long[] tree;

        Fenwick(int n) {
            tree = new long[n + 1];
        }

        void add(int i, long delta) {              // i is 1-based
            for (; i < tree.length; i += i & -i) {
                tree[i] += delta;
            }
        }

        long sum(int i) {                          // prefix 1..i
            long s = 0;
            for (; i > 0; i -= i & -i) {
                s += tree[i];
            }
            return s;
        }
    }

    // Canonical LC 307.
    static class NumArray {
        private final int[] a;
        private final Fenwick bit;

        NumArray(int[] nums) {
            a = nums.clone();
            bit = new Fenwick(nums.length);
            for (int i = 0; i < nums.length; i++) {
                bit.add(i + 1, nums[i]);
            }
        }

        void update(int index, int val) {
            bit.add(index + 1, val - a[index]);
            a[index] = val;
        }

        long sumRange(int left, int right) {
            return bit.sum(right + 1) - bit.sum(left);
        }
    }

    // LC 315.
    static int[] countSmaller(int[] nums) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        Fenwick bit = new Fenwick(nums.length);
        int[] out = new int[nums.length];
        for (int i = nums.length - 1; i >= 0; i--) {
            int rank = Arrays.binarySearch(sorted, nums[i]);
            while (rank > 0 && sorted[rank - 1] == nums[i]) {
                rank--;                            // first position of this value
            }
            out[i] = (int) bit.sum(rank);          // values strictly smaller, already seen
            bit.add(rank + 1, 1);
        }
        return out;
    }

    // LC 493: pairs i < j with nums[i] > 2 * nums[j].
    static int reversePairs(int[] nums) {
        return (int) sortCount(nums.clone(), 0, nums.length - 1, true);
    }

    // Inversions: pairs i < j with a[i] > a[j].
    static long countInversions(int[] a) {
        return sortCount(a.clone(), 0, a.length - 1, false);
    }

    private static long sortCount(int[] a, int lo, int hi, boolean doubled) {
        if (lo >= hi) {
            return 0;
        }
        int mid = (lo + hi) >>> 1;
        long count = sortCount(a, lo, mid, doubled) + sortCount(a, mid + 1, hi, doubled);
        int j = mid + 1;
        for (int i = lo; i <= mid; i++) {          // both halves are sorted now
            while (j <= hi && (long) a[i] > (doubled ? 2L * a[j] : a[j])) {
                j++;
            }
            count += j - (mid + 1);
        }
        int[] merged = new int[hi - lo + 1];
        int p = lo;
        int q = mid + 1;
        int k = 0;
        while (p <= mid || q <= hi) {
            merged[k++] = (q > hi || (p <= mid && a[p] <= a[q])) ? a[p++] : a[q++];
        }
        System.arraycopy(merged, 0, a, lo, merged.length);
        return count;
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        NumArray na = new NumArray(new int[]{1, 3, 5});
        long before = na.sumRange(0, 2);
        na.update(1, 2);
        check("LC 307 sum, update, sum", before + "," + na.sumRange(0, 2), "9,8");
        check("LC 307 single cell after update", na.sumRange(1, 1), 2L);

        check("LC 315 [5,2,6,1]",
                Arrays.toString(countSmaller(new int[]{5, 2, 6, 1})), "[2, 1, 1, 0]");
        check("LC 315 [-1]", Arrays.toString(countSmaller(new int[]{-1})), "[0]");
        check("LC 315 duplicates", Arrays.toString(countSmaller(new int[]{-1, -1})), "[0, 0]");

        check("LC 493 [1,3,2,3,1]", reversePairs(new int[]{1, 3, 2, 3, 1}), 2);
        check("LC 493 [2,4,3,5,1]", reversePairs(new int[]{2, 4, 3, 5, 1}), 3);
        check("LC 493 overflow trap",
                reversePairs(new int[]{2147483647, 2147483647, 2147483647}), 0);

        check("inversions [2,4,1,3,5]", countInversions(new int[]{2, 4, 1, 3, 5}), 3L);
        check("inversions descending", countInversions(new int[]{5, 4, 3, 2, 1}), 10L);
    }
}

/*
 * =====================================================================
 *  P110 Segment Tree (with Lazy Propagation)   Canonical Range Min Query | Hard
 * =====================================================================
 *
 * PROBLEM  (canonical: Range Minimum Query with point updates; LeetCode 307 is the sum version)
 *   Support update(i, value) and min(l, r) over an array, both in O(log n).
 *
 * EXAMPLE
 *   [5, 2, 6, 3, 8, 1, 7]: min(0, 6) = 1, min(1, 3) = 2; update(5, 10); min(0, 6) = 2
 *
 * RECOGNIZE WHEN
 *   - Range queries for an operation that is NOT invertible (min, max, gcd) with updates,
 *     so prefix-sum tricks and Fenwick trees do not apply.
 *   - RANGE updates ("add 5 to every index in [l, r]") mixed with range queries: lazy
 *     propagation.
 *   - Segment tree over VALUES (coordinates) for "best answer among values < x".
 *   Not this if: only sums with point updates -> P109_FenwickAndMergeCounting (shorter);
 *   no updates -> a sparse table or prefix sums; updates first, queries after ->
 *   P003_DifferenceArray.
 *
 * TEMPLATE
 *   tree over [lo, hi], node stores combine(left child, right child); array size 4n
 *   query(node, lo, hi, l, r):
 *       if [lo, hi] outside [l, r]: return identity
 *       if [lo, hi] inside  [l, r]: return tree[node]
 *       push(node) (lazy); split at mid; combine both halves
 *   point update: descend to the leaf, set it, recombine on the way up
 *   lazy range add: tag a fully covered node (tree += add * length, lazy += add) and stop;
 *                   push the tag to the children only when you descend later
 *
 * APPROACH
 *   1. Build bottom-up: each internal node is the min of its two children.
 *   2. A query splits [l, r] into O(log n) fully covered nodes.
 *   3. An update changes one leaf and the O(log n) ancestors above it.
 *
 * KEY INSIGHT
 *   Any interval is a union of O(log n) canonical segments (the tree's nodes), so any
 *   ASSOCIATIVE operation can be answered from precomputed segments. Lazy tags postpone
 *   range updates until a query actually needs to look inside a segment.
 *
 * COMPLEXITY
 *   Build O(n); query and update O(log n); space O(4n).
 *
 * VARIATIONS  (same template; what changes)
 *   [coded] Range add + range sum (lazy)     tags carry the pending add per node
 *           LC 307  Range Sum Mutable        combine = +, identity 0
 *           LC 699  Falling Squares          range max with range ASSIGN (coordinate compress)
 *           LC 2407 Longest Increasing Subsequence II  tree over values: best dp in a range
 *           LC 715  Range Module             interval set; a dynamic segment tree or TreeMap
 *           LC 732  My Calendar III          range add + global max (or a TreeMap sweep)
 *
 * PITFALLS
 *   - Size the array 4n, not 2n, for the recursive layout.
 *   - Return the IDENTITY for out-of-range parts (+infinity for min, 0 for sum).
 *   - Lazy: push tags down before visiting children, in both update and query.
 *
 * DEEP DIVE
 *   D03_SegmentTree (18-Sorting-Searching-Algorithms)
 *
 * RUN
 *   main() prints every case as "label: actual   expected value".
 */
class SegmentTree {

    // Canonical: range minimum with point updates.
    static class MinTree {
        private final int n;
        private final int[] tree;

        MinTree(int[] a) {
            n = a.length;
            tree = new int[4 * n];
            build(a, 1, 0, n - 1);
        }

        private void build(int[] a, int node, int lo, int hi) {
            if (lo == hi) {
                tree[node] = a[lo];
                return;
            }
            int mid = (lo + hi) >>> 1;
            build(a, 2 * node, lo, mid);
            build(a, 2 * node + 1, mid + 1, hi);
            tree[node] = Math.min(tree[2 * node], tree[2 * node + 1]);
        }

        void update(int i, int value) {
            update(1, 0, n - 1, i, value);
        }

        private void update(int node, int lo, int hi, int i, int value) {
            if (lo == hi) {
                tree[node] = value;
                return;
            }
            int mid = (lo + hi) >>> 1;
            if (i <= mid) {
                update(2 * node, lo, mid, i, value);
            } else {
                update(2 * node + 1, mid + 1, hi, i, value);
            }
            tree[node] = Math.min(tree[2 * node], tree[2 * node + 1]);
        }

        int min(int l, int r) {
            return min(1, 0, n - 1, l, r);
        }

        private int min(int node, int lo, int hi, int l, int r) {
            if (r < lo || hi < l) {
                return Integer.MAX_VALUE;          // identity for min
            }
            if (l <= lo && hi <= r) {
                return tree[node];
            }
            int mid = (lo + hi) >>> 1;
            return Math.min(min(2 * node, lo, mid, l, r), min(2 * node + 1, mid + 1, hi, l, r));
        }
    }

    // Range add + range sum with lazy propagation.
    static class LazySumTree {
        private final int n;
        private final long[] sum;
        private final long[] lazy;

        LazySumTree(int[] a) {
            n = a.length;
            sum = new long[4 * n];
            lazy = new long[4 * n];
            build(a, 1, 0, n - 1);
        }

        private void build(int[] a, int node, int lo, int hi) {
            if (lo == hi) {
                sum[node] = a[lo];
                return;
            }
            int mid = (lo + hi) >>> 1;
            build(a, 2 * node, lo, mid);
            build(a, 2 * node + 1, mid + 1, hi);
            sum[node] = sum[2 * node] + sum[2 * node + 1];
        }

        // Hand a pending add down to both children.
        private void push(int node, int lo, int hi) {
            if (lazy[node] != 0) {
                int mid = (lo + hi) >>> 1;
                apply(2 * node, lo, mid, lazy[node]);
                apply(2 * node + 1, mid + 1, hi, lazy[node]);
                lazy[node] = 0;
            }
        }

        private void apply(int node, int lo, int hi, long add) {
            sum[node] += add * (hi - lo + 1);
            lazy[node] += add;
        }

        void add(int l, int r, long value) {
            add(1, 0, n - 1, l, r, value);
        }

        private void add(int node, int lo, int hi, int l, int r, long value) {
            if (r < lo || hi < l) {
                return;
            }
            if (l <= lo && hi <= r) {
                apply(node, lo, hi, value);        // fully covered: tag and stop
                return;
            }
            push(node, lo, hi);
            int mid = (lo + hi) >>> 1;
            add(2 * node, lo, mid, l, r, value);
            add(2 * node + 1, mid + 1, hi, l, r, value);
            sum[node] = sum[2 * node] + sum[2 * node + 1];
        }

        long sum(int l, int r) {
            return sum(1, 0, n - 1, l, r);
        }

        private long sum(int node, int lo, int hi, int l, int r) {
            if (r < lo || hi < l) {
                return 0;
            }
            if (l <= lo && hi <= r) {
                return sum[node];
            }
            push(node, lo, hi);
            int mid = (lo + hi) >>> 1;
            return sum(2 * node, lo, mid, l, r) + sum(2 * node + 1, mid + 1, hi, l, r);
        }
    }

    private static void check(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        MinTree mt = new MinTree(new int[]{5, 2, 6, 3, 8, 1, 7});
        check("RMQ whole array", mt.min(0, 6), 1);
        check("RMQ [1,3]", mt.min(1, 3), 2);
        mt.update(5, 10);
        check("RMQ after update", mt.min(0, 6), 2);
        check("RMQ [4,6]", mt.min(4, 6), 7);
        check("RMQ single cell", mt.min(2, 2), 6);

        LazySumTree lt = new LazySumTree(new int[]{1, 2, 3, 4, 5});
        check("lazy sum before", lt.sum(0, 4), 15L);
        lt.add(1, 3, 10);
        check("lazy sum after add 10 on [1,3]", lt.sum(0, 4), 45L);
        check("lazy single cell", lt.sum(1, 1), 12L);
        check("lazy partial overlap", lt.sum(3, 4), 19L);
        lt.add(0, 0, -1);
        check("lazy second add", lt.sum(0, 2), 25L);
    }
}

AAScratches/01-DSA/01-Arrays/A02_Monoton.text:
/*
 * =====================================================================
 *  Monotonic Array                                   LeetCode 896 | Easy
 * =====================================================================
 *
 * PROBLEM
 *   An array is monotonic if it is entirely non-increasing or entirely
 *   non-decreasing. Given an integer array, return true if it is monotonic.
 *   Equal neighbours are allowed in both directions; arrays with 0, 1 or 2
 *   elements are always monotonic.
 *
 * EXAMPLE
 *   [1, 2, 2, 3]  ->  true    non-decreasing
 *   [6, 5, 4, 4]  ->  true    non-increasing
 *   [1, 3, 2]     ->  false   goes up then down
 *   [7, 7, 7]     ->  true    flat counts as both
 *   []            ->  true [1, 2, 2, 1]  ->  false   the plateau hides a turn
 *
 * APPROACH  (two boolean flags, one pass)
 *   1. Start with increasing = true and decreasing = true (both hypotheses alive).
 *   2. For each adjacent pair, a strict rise (nums[i] > nums[i-1]) kills
 *      "decreasing"; a strict fall kills "increasing". Equal pairs kill neither.
 *   3. After the pass, the array is monotonic if either flag survived.
 *
 * KEY INSIGHT
 *   Instead of scanning once for "is it increasing?" and again for "is it
 *   decreasing?", carry both hypotheses through a single scan and let the
 *   data falsify them. Same adjacent-pair loop as A01_ArraySortedOrNot, but testing two
 *   properties at once; a rise and a fall both seen means neither survives.
 *
 * COMPLEXITY
 *   Time  O(n)  one pass over adjacent pairs
 *   Space O(1)  two booleans
 *
 * INTERVIEW FOLLOW-UPS
 *   - Strictly monotonic? Then an equal pair must kill both flags.
 *   - Early exit: return false as soon as both flags are false.
 *   - Compare with the "decide direction from the first unequal pair" version,
 *     which needs an extra scan to find that pair.
 *
 * RUN
 *   main() runs 6 cases (up, down, turn, flat, empty, plateau-then-turn) and
 *   prints actual vs expected.
 */
import java.util.Arrays;

class MonotonicArray {

    public static boolean isMonotonic(int[] nums) {
        if (nums.length <= 2) {
            return true; // 0, 1 or 2 elements can only go one way
        }

        boolean increasing = true;
        boolean decreasing = true;

        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > nums[i - 1]) {
                decreasing = false; // saw a rise, so it cannot be non-increasing
            }
            if (nums[i] < nums[i - 1]) {
                increasing = false; // saw a fall, so it cannot be non-decreasing
            }
            // equal neighbours leave both flags untouched
        }

        return increasing || decreasing;
    }

    private static void check(int[] nums, boolean expected) {
        System.out.println(Arrays.toString(nums) + " -> " + isMonotonic(nums)
                + "   expected " + expected);
    }

    public static void main(String[] args) {
        check(new int[]{1, 2, 2, 3}, true);    // non-decreasing
        check(new int[]{6, 5, 4, 4}, true);    // non-increasing
        check(new int[]{1, 3, 2}, false);      // up then down
        check(new int[]{7, 7, 7}, true);       // all equal
        check(new int[]{}, true);              // empty
        check(new int[]{1, 2, 2, 1}, false);   // plateau then a turn
    }
}

AAScratches/01-DSA/01-Arrays/A04_SecondS.text:
/*
 * =====================================================================
 *  Second Smallest Element                                 GfG | Easy
 * =====================================================================
 *
 * PROBLEM
 *   Given an integer array, return the second smallest DISTINCT value. So
 *   [1, 1, 2] gives 2, not 1: the duplicate 1 does not count twice. If the
 *   array has fewer than 2 elements or fewer than 2 distinct values, there is
 *   no answer and the method throws IllegalArgumentException.
 *
 * EXAMPLE
 *   [4, 2, 2, 1, 1]   ->  2      smallest 1, next distinct value 2
 *   [0, 1]            ->  1 [1, 1, 2]         ->  2      duplicate of the smallest is ignored
 *   [-3, -3, -1, 0]   ->  -1     negatives work the same way
 *   [5, 5, 5]         ->  throws  only one distinct value
 *   [0]               ->  throws  too short
 *
 * APPROACH  (track two extremes, one pass)
 *   1. smallest = second = +infinity (long, so any int is below it).
 *   2. For each num:
 *        if num < smallest: demote smallest to second, then smallest = num
 *        else if smallest < num < second: second = num
 *   3. If second is still +infinity, no second distinct value exists: throw.
 *
 * KEY INSIGHT
 *   Two rules make this work. Order: demote the old smallest BEFORE
 *   overwriting it, or the previous minimum is lost. Distinctness: the
 *   num > smallest guard in the else-branch stops a repeat of the minimum
 *   from being promoted to second place. Using long for the sentinels means
 *   Integer.MIN_VALUE / MAX_VALUE in the input are handled without a flag.
 *
 * COMPLEXITY
 *   Time  O(n)  single pass Space O(1)  two scalars
 *
 * INTERVIEW FOLLOW-UPS
 *   - Second largest? Mirror the comparisons with -infinity sentinels.
 *   - k-th smallest distinct? Sort-and-dedupe O(n log n), or a size-k max-heap.
 *   - Return -1 instead of throwing when there is no answer (GfG style).
 *   - Why not sort and take index 1? O(n log n) and wrong with duplicates.
 *
 * RUN
 *   main() runs 6 cases (typical with duplicates, two elements, duplicate of
 *   the minimum, negatives, all equal, single element) and prints actual vs expected.
 */
import java.util.Arrays;

class SecondSmallest {

    public static int secondSmallest(int[] nums) {
        if (nums.length < 2) {
            throw new IllegalArgumentException("Array must contain at least 2 elements");
        }

        long smallest = Long.MAX_VALUE;        // long so Integer.MAX_VALUE in input still counts
        long secondSmallest = Long.MAX_VALUE;

        for (int num : nums) {
            if (num < smallest) {
                secondSmallest = smallest;     // demote first, then take the new minimum
                smallest = num;
            } else if (num > smallest && num < secondSmallest) {
                secondSmallest = num;          // strictly > smallest keeps duplicates out
            }
        }

        if (secondSmallest == Long.MAX_VALUE) {
            throw new IllegalArgumentException("Array must contain at least 2 distinct values");
        }
        return (int) secondSmallest;
    }

    /** Runs the method and turns an exception into the word "throws" so it can be compared. */
    private static String run(int[] nums) {
        try {
            return String.valueOf(secondSmallest(nums));
        } catch (IllegalArgumentException ex) {
            return "throws";
        }
    }

    private static void check(int[] nums, String expected) {
        System.out.println(Arrays.toString(nums) + " -> " + run(nums) + "   expected " + expected);
    }

    public static void main(String[] args) {
        check(new int[]{4, 2, 2, 1, 1}, "2");        // typical, with duplicates
        check(new int[]{0, 1}, "1");                 // smallest possible valid input
        check(new int[]{1, 1, 2}, "2");              // duplicate of the minimum is ignored
        check(new int[]{-3, -3, -1, 0}, "-1");       // negatives
        check(new int[]{5, 5, 5}, "throws");         // only one distinct value
        check(new int[]{0}, "throws");               // too short
    }
}

AAScratches/01-DSA/01-Arrays/A05_ThreeLa.text:
/*
 * =====================================================================
 *  Three Largest Numbers                              AlgoExpert | Easy
 * =====================================================================
 *
 * PROBLEM
 *   Given an integer array with at least 3 elements, return its three largest
 *   values as [first, second, third] in descending order, in one pass and
 *   without sorting. Duplicates are allowed: [9, 9, 6] is a valid answer if
 *   9 appears twice in the input.
 *
 * EXAMPLE
 *   [3, 1, 4, 1, 5, 9, 2, 6, 5]  ->  [9, 6, 5]
 *   [-1, -2, -3]                 ->  [-1, -2, -3]   all negative, still fine
 *   [7, 7, 7, 7]                 ->  [7, 7, 7]      duplicates fill the slots
 *   [5, 9, 9, 6]                 ->  [9, 9, 6]      repeated maximum kept twice
 *   [1, 2]                       ->  [2, 1, MIN]    fewer than 3 elements: sentinel leaks
 *
 * APPROACH  (track three extremes, cascading)
 *   1. first = second = third = Integer.MIN_VALUE.
 *   2. For each num, find the highest slot it beats and shift everything
 *      below that slot down by one:
 *        num > first  : third = second, second = first, first = num
 *        num > second : third = second, second = num
 *        num > third  : third = num
 *   3. Return [first, second, third].
 *
 * KEY INSIGHT
 *   Insert num into a tiny sorted list of size 3, shifting the displaced
 *   values down. The cascade must run from the bottom up (third takes
 *   second's old value BEFORE second takes first's) or a value is lost.
 *   Once you can write this for k = 3 you can write it for any small fixed k;
 *   for large k switch to a size-k min-heap.
 *
 * COMPLEXITY
 *   Time  O(n)  one pass, at most 3 comparisons per element
 *   Space O(1)  three scalars plus the output array
 *
 * INTERVIEW FOLLOW-UPS
 *   - Three largest DISTINCT values? Add num != first / num != second guards.
 *   - k largest for large k? Min-heap of size k, O(n log k); or quickselect, O(n) average.
 *   - Input may contain Integer.MIN_VALUE or have fewer than 3 elements?
 *     Use long sentinels or a count of filled slots instead of MIN_VALUE.
 *   - Three smallest? Mirror with MAX_VALUE sentinels and flipped comparisons.
 *
 * RUN
 *   main() runs 5 cases (typical, all negative, all equal, repeated max, too short)
 *   and prints actual vs expected.
 */
import java.util.Arrays;

class ThreeLargestNumbers {

    public static int[] findThreeLargest(int[] nums) {
        int first = Integer.MIN_VALUE;
        int second = Integer.MIN_VALUE;
        int third = Integer.MIN_VALUE;

        for (int num : nums) {
            if (num > first) {
                // new champion: everyone below moves down one place
                third = second;
                second = first;
                first = num;
            } else if (num > second) {
                third = second;
                second = num;
            } else if (num > third) {
                third = num;
            }
        }
        return new int[]{first, second, third};
    }

    private static void check(int[] nums, int[] expected) {
        System.out.println(Arrays.toString(nums) + " -> "
                + Arrays.toString(findThreeLargest(nums))
                + "   expected " + Arrays.toString(expected));
    }

    public static void main(String[] args) {
        check(new int[]{3, 1, 4, 1, 5, 9, 2, 6, 5}, new int[]{9, 6, 5});   // typical
        check(new int[]{-1, -2, -3}, new int[]{-1, -2, -3});               // all negative
        check(new int[]{7, 7, 7, 7}, new int[]{7, 7, 7});                  // all equal
        check(new int[]{5, 9, 9, 6}, new int[]{9, 9, 6});                  // repeated maximum
        // Documented limitation: with fewer than 3 elements the MIN_VALUE sentinel shows through.
        check(new int[]{1, 2}, new int[]{2, 1, Integer.MIN_VALUE});
    }
}

