    }

    public static void main(String[] args) {
        print("case 1 typical      ", partitionDisjoint(new int[]{5, 0, 3, 8, 6}), 3);
        print("case 2 ties         ", partitionDisjoint(new int[]{1, 1, 1, 0, 6, 12}), 4);
