    public static int findPeakElement(int[] nums) {
        int left = 0, right = nums.length - 1;
        if (nums.length == 1) {
            return 0; // index, not value
        }
        if (nums.length == 2) {
            return nums[0] > nums[1] ? 0 : 1;
        }
        while (left <= right) {
                int mid = left + (right - left) / 2;
