class MinIndexInRotatedSortedArray {

    private static int getMinIndex(int[] arr) {
        int low = 0, high = arr.length - 1;
        int ans = 0;
        while (low < high) {
            if (arr[low] < arr[high]) {
                ans = low;
                break;
            }
            int mid = low + (high - low) / 2;
            if (arr[mid] < arr[high]) {
                ans = mid;      // potential minimum index
