/*
 * =====================================================================
 *  Stack Traversal Order                            Java core demo | Easy
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   java.util.Stack is a Vector underneath. A for-each loop walks the Vector from index 0
 *   upward, which is BOTTOM to TOP. pop() removes from the end of the Vector, which is TOP to
 *   BOTTOM. The two orders are opposite, and code that iterates a Stack expecting LIFO order
 *   is silently wrong. ArrayDeque used as a stack iterates TOP to BOTTOM, the opposite again.
 *
 * WHAT YOU WILL SEE
 *   push 1,2,3,4 onto a Stack
 *     for-each          -> [1, 2, 3, 4]   bottom to top (Vector index order)
 *     pop until empty   -> [4, 3, 2, 1]   top to bottom (true LIFO)
 *   push 1,2,3,4 onto an ArrayDeque
 *     for-each          -> [4, 3, 2, 1]   head first, and push() inserts at the head
 *   empty and single-element stacks give the same order both ways (nothing to reverse)
 *
 * HOW IT WORKS
 *   1. Stack extends Vector; push(x) is addElement(x) at index size(), so the top is the
 *      LAST index. Iterator goes 0..size-1, so it reaches the top last.
 *   2. pop() reads and removes index size-1, so it drains the top first.
 *   3. ArrayDeque.push(x) is addFirst(x); its iterator starts at the head, so the most
 *      recently pushed element comes out first. descendingIterator() gives bottom to top.
 *
 * KEY INSIGHT
 *   Iteration order of a stack is an implementation detail, not a LIFO guarantee.
 *   When order matters (building a string from leftover characters, printing a path),
 *   decide explicitly: pop() for top-first, for-each over Stack for bottom-first, and never
 *   assume the two agree. Prefer ArrayDeque over Stack in new code (no synchronization cost),
 *   but remember its for-each is top-first.
 *
 * GOTCHAS
 *   - Stack.get(i) and stack.elementAt(i) index from the BOTTOM (index 0 = oldest element).
 *   - Stack.search(x) returns a 1-based distance from the TOP, not an index.
 *   - Stack is synchronized (Vector), so every push/pop takes a lock you did not ask for.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why does Java recommend ArrayDeque over Stack? (Vector locking, cleaner Deque API)
 *   - How do you print a Stack top-to-bottom without destroying it? (index from size-1 down,
 *     or ArrayDeque for-each)
 *   - Which order does B01_RemoveAdjacentDuplicates rely on when it rebuilds the string?
 *
 * RUN
 *   main() runs 5 cases (Stack for-each, Stack pop, ArrayDeque for-each, empty, single) and
 *   prints actual vs expected.
 */
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Stack;

class StackTraversal {

    // for-each over java.util.Stack walks the backing Vector from index 0: bottom to top.
    static List<String> stackForEachOrder(Stack<String> stack) {
        List<String> order = new ArrayList<>();
        for (String s : stack) {
            order.add(s);
        }
        return order;
    }

    // pop() always returns the most recently pushed element: top to bottom. Empties the stack.
    static List<String> stackPopOrder(Stack<String> stack) {
        List<String> order = new ArrayList<>();
        while (!stack.isEmpty()) {
            order.add(stack.pop());
        }
        return order;
    }

    // ArrayDeque.push() inserts at the head and the iterator starts at the head: top to bottom.
    static List<String> dequeForEachOrder(Deque<String> deque) {
        List<String> order = new ArrayList<>();
        for (String s : deque) {
            order.add(s);
        }
        return order;
    }

    static Stack<String> stackOf(String... items) {
        Stack<String> stack = new Stack<>();
        for (String item : items) {
            stack.push(item);
        }
        return stack;
    }

    static Deque<String> dequeOf(String... items) {
        Deque<String> deque = new ArrayDeque<>();
        for (String item : items) {
            deque.push(item);
        }
        return deque;
    }

    static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // case 1: Stack for-each is bottom-to-top (Vector index order), NOT LIFO
        Stack<String> s1 = stackOf("1", "2", "3", "4");
        print("case 1 Stack for-each     ", stackForEachOrder(s1), "[1, 2, 3, 4]");

        // case 2: Stack pop is top-to-bottom, the true LIFO order
        print("case 2 Stack pop          ", stackPopOrder(s1), "[4, 3, 2, 1]");

        // case 3: ArrayDeque used as a stack iterates top-to-bottom (opposite of Stack)
        Deque<String> d1 = dequeOf("1", "2", "3", "4");
        print("case 3 ArrayDeque for-each", dequeForEachOrder(d1), "[4, 3, 2, 1]");

        // case 4: empty stack, both orders are empty
        print("case 4 empty for-each     ", stackForEachOrder(stackOf()), "[]");
        print("case 4 empty pop          ", stackPopOrder(stackOf()), "[]");

        // case 5: single element, both orders agree because there is nothing to reverse
        print("case 5 single for-each    ", stackForEachOrder(stackOf("x")), "[x]");
        print("case 5 single pop         ", stackPopOrder(stackOf("x")), "[x]");
    }
}

/*
 * =====================================================================
 *  Valid Parentheses                              LeetCode 20 | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Given a string containing only the characters ( ) [ ] { }, return true if every opening
 *   bracket is closed by a bracket of the same type, in the correct order. An empty string is
 *   valid. Length up to 10^4.
 *
 * EXAMPLE
 *   "()[]{}"  ->  true "([)]"    ->  false   because ']' arrives while '(' is still the innermost
 *   open bracket
 *   "(]"      ->  false   wrong type
 *   ""        ->  true    nothing to mismatch
 *   "("       ->  false   opener never closed
 *   ")("      ->  false   closer with nothing open
 *
 * APPROACH  (Stack as bracket matcher)
 *   1. Walk the string left to right.
 *   2. Opening bracket: push it. It is now the innermost unmatched opener.
 *   3. Closing bracket: the stack must be non-empty and its top must be the matching opener.
 *      Pop it. Anything else means the string is invalid, return false immediately.
 *   4. At the end the stack must be empty; leftover openers were never closed.
 *   Second method (isValidWithCounter): when only ( and ) exist, a single int balance counter
 *   replaces the stack. Go negative once -> invalid; end non-zero -> invalid.
 *
 * KEY INSIGHT
 *   A closing bracket must match the MOST RECENT unmatched opener, and "most recent" is
 *   exactly what a stack top is. The counter works for one type because there is no order to
 *   confuse; with several types "([)]" balances to zero for every type yet is invalid, and only
 *   a stack remembers which opener is innermost. Pattern: push openers, pop on matching closer.
 *
 * COMPLEXITY
 *   Time  O(n)  each character is pushed and popped at most once
 *   Space O(n)  worst case is a string of all openers; counter version is O(1)
 *
 * INTERVIEW FOLLOW-UPS
 *   - Only one bracket type: drop the stack for a counter (shown here).
 *   - Minimum insertions to make a string valid (LeetCode 921): count unmatched of each side.
 *   - Longest valid substring (LeetCode 32): store indices, use a -1 sentinel.
 *   - Streaming input with no upper bound on nesting: the stack is still the answer.
 *
 * RUN
 *   main() runs 9 cases (multi-type valid, wrong order, wrong type, empty, unclosed and
 *   closer-first through the stack; three single-type cases through the counter only), plus
 *   one extra demo line showing where the counter breaks, and prints actual vs expected.
 */
import java.util.Stack;

class ValidParentheses {

    // Parallel strings: OPEN.charAt(i) is the opener that matches CLOSE.charAt(i)
    private static final String OPEN = "([{";
    private static final String CLOSE = ")]}";

    // Approach 1: Stack. Works for any mix of (), [], {}.
    static boolean isValidWithStack(String str) {
        Stack<Character> stack = new Stack<>();
        for (char c : str.toCharArray()) {
            int closeIdx = CLOSE.indexOf(c);
            if (OPEN.indexOf(c) >= 0) {
                stack.push(c);
            } else if (closeIdx >= 0) {
                // Closing bracket: stack must be non-empty and its top must be the matching opener
                if (stack.isEmpty() || stack.pop() != OPEN.charAt(closeIdx)) {
                    return false;
                }
            }
        }
        // Leftover openers mean something was never closed
        return stack.isEmpty();
    }

    // Approach 2: Balance counter. Only valid when the string has a single bracket type.
    static boolean isValidWithCounter(String s) {
        int balance = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                balance--;
            }
            // Negative balance = a ')' arrived before its '(' -> fail fast.
            // A positive balance mid-way is fine: the matching ')' may still come.
            if (balance < 0) {
                return false;
            }
        }
        // Zero at the end = every '(' found its ')'
        return balance == 0;
    }

    static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // Stack handles every bracket type
        print("case 1 \"()[]{}\" stack  ", isValidWithStack("()[]{}"), true);
        print("case 2 \"([)]\"   stack  ", isValidWithStack("([)]"), false);
        print("case 3 \"(]\"     stack  ", isValidWithStack("(]"), false);
        print("case 4 \"\"       stack  ", isValidWithStack(""), true);
        print("case 5 \"(\"      stack  ", isValidWithStack("("), false);
        print("case 6 \")(\"     stack  ", isValidWithStack(")("), false);

        // Single bracket type: counter and stack must agree
        print("case 7 \"()()\"   counter", isValidWithCounter("()()"), true);
        print("case 8 \"(()\"    counter", isValidWithCounter("(()"), false);
        print("case 9 \"())(\"   counter", isValidWithCounter("())("), false);

        // Why the counter is NOT enough for multiple types: it wrongly accepts "([)]"
        print("counter on \"([)]\" (wrong, shows the limit)", isValidWithCounter("([)]"), true);
    }
}

/*
 * =====================================================================
 *  Next Greater Element (array)                   LeetCode 496 family | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   For every element of an int array, find the first element to its RIGHT that is strictly
 *   greater. If none exists, output -1 for that position. Return the results as an array of
 *   the same length. Values may repeat.
 *
 * EXAMPLE
 *   [4, 5, 2, 10, 8]     ->  [5, 10, 10, -1, -1]
 *   [3, 7, 1, 7, 6, 4]   ->  [7, -1, 7, -1, -1, -1]   equal 7 does not count as greater
 *   [6, 8, 0, 1, 3]      ->  [8, -1, 1, 3, -1]
 *   [5, 4, 3]            ->  [-1, -1, -1]              strictly decreasing, nothing resolves
 *   []                   ->  []                        used to throw, see Fixed below
 *
 * APPROACH  (Monotonic decreasing stack of indices)
 *   1. Keep a stack of INDICES whose next greater element is still unknown. The values at
 *      those indices are always decreasing from bottom to top.
 *   2. For each i: while the stack top's value is smaller than nums[i], that top has just
 *      found its answer, nums[i]. Record it and pop.
 *   3. Push i. It waits for something bigger to arrive.
 *   4. After the loop, everything left on the stack never saw a bigger value: set -1.
 *
 * KEY INSIGHT
 *   An element that is smaller than the newcomer can never be anyone's "next greater", so it
 *   can be resolved and discarded right now. That is why the stack stays decreasing and why
 *   every index is pushed once and popped once. Recognise the pattern whenever a question asks
 *   "for each element, the nearest larger/smaller to the left/right".
 *   Fixed: the original pushed index 0 before the loop, so an empty array threw
 *   ArrayIndexOutOfBounds. The loop now starts at 0 and handles empty input naturally.
 *
 * COMPLEXITY
 *   Time  O(n)  each index is pushed and popped at most once, so the while loop is O(n) total
 *   Space O(n)  the stack plus the output array
 *
 * INTERVIEW FOLLOW-UPS
 *   - Return the DISTANCE instead of the value: store indices (as here) and use i - top.
 *     That is C06_DailyTemperatures.
 *   - Circular array (LeetCode 503): loop i from 0 to 2n-1 and index with i % n.
 *   - Next SMALLER element: flip the comparison, the stack becomes increasing.
 *   - Previous greater element: same loop, but the answer for i is stack.peek() after popping.
 *
 * RUN
 *   main() runs 5 cases (typical, duplicates, mixed, strictly decreasing, empty) and prints
 *   actual vs expected.
 */
import java.util.Arrays;
import java.util.Stack;

class NextGreaterElements {

    static int[] getNextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        // Indices still waiting for their next greater element; values decrease bottom to top
        Stack<Integer> waiting = new Stack<>();

        for (int i = 0; i < n; i++) {
            // nums[i] is the answer for every waiting index whose value is strictly smaller
            while (!waiting.isEmpty() && nums[waiting.peek()] < nums[i]) {
                result[waiting.pop()] = nums[i];
            }
            waiting.push(i);
        }

        // Whatever is still waiting never met a bigger value
        while (!waiting.isEmpty()) {
            result[waiting.pop()] = -1;
        }
        return result;
    }

    static void print(String label, int[] input, String expected) {
        int[] actual = getNextGreaterElements(input);
        System.out.println(label + " " + Arrays.toString(input) + " -> " + Arrays.toString(actual)
                + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 typical   ", new int[]{4, 5, 2, 10, 8}, "[5, 10, 10, -1, -1]");
        print("case 2 duplicates", new int[]{3, 7, 1, 7, 6, 4}, "[7, -1, 7, -1, -1, -1]");
        print("case 3 mixed     ", new int[]{6, 8, 0, 1, 3}, "[8, -1, 1, 3, -1]");
        print("case 4 decreasing", new int[]{5, 4, 3}, "[-1, -1, -1]");
        print("case 5 empty     ", new int[]{}, "[]");
    }
}

/*
 * =====================================================================
 *  Implement Queue using Stacks                   LeetCode 232 | Easy
 * =====================================================================
 *
 * PROBLEM
 *   Build a FIFO queue (enqueue, dequeue, peek, isEmpty, size) using only stack operations
 *   (push, pop, peek, isEmpty, size). Every operation should be amortised O(1).
 *
 * EXAMPLE
 *   enqueue 1, 2, 3; dequeue -> 1; peek -> 2; size -> 2
 *   enqueue 1, 2; dequeue -> 1; enqueue 3; dequeue -> 2; dequeue -> 3; isEmpty -> true
 *   dequeue on an empty queue -> throws NoSuchElementException
 *
 * APPROACH  (Two-stack FIFO, lazy transfer)
 *   1. inbox: enqueue always pushes here. Newest element on top.
 *   2. outbox: dequeue and peek always read from here. Oldest element on top.
 *   3. When outbox is empty and a read is requested, pour ALL of inbox into outbox
 *      (pop from inbox, push to outbox). Popping reverses the order, so the element that
 *      went into inbox first ends up on top of outbox.
 *   4. Never transfer while outbox still has elements: they are older than anything in inbox,
 *      so they must come out first. This is what keeps the ordering correct after interleaving.
 *
 * KEY INSIGHT
 *   Two reversals make a forward order: a stack reverses on the way in, a second stack
 *   reverses again on the way out. The amortised argument, which you must say aloud: each
 *   element is pushed to inbox once, moved to outbox once, popped from outbox once, so a
 *   sequence of n operations does at most 3n stack pushes/pops. A single dequeue can cost
 *   O(n), but it "pays" for the elements it moved, which are then O(1) to dequeue.
 *
 * COMPLEXITY
 *   Time  enqueue O(1); dequeue and peek O(1) amortised, O(n) worst single call; isEmpty,
 *         size O(1)
 *   Space O(n)  every element lives in exactly one of the two stacks
 *
 * INTERVIEW FOLLOW-UPS
 *   - Implement a Stack using Queues (LeetCode 225): rotate the queue after each push.
 *   - Why not transfer back to inbox after every dequeue? That makes dequeue O(n) always.
 *   - Thread safety: two stacks change under one operation, so lock the whole operation.
 *   - Sliding-window maximum uses the same "two ends" thinking with a deque.
 *
 * RUN
 *   main() runs 3 cases (basic FIFO order, interleaved enqueue/dequeue, dequeue on empty)
 *   and prints actual vs expected.
 */
import java.util.NoSuchElementException;
import java.util.Stack;

class QueueUsingStacks {
    private final Stack<Integer> inbox = new Stack<>();   // enqueue pushes here
    private final Stack<Integer> outbox = new Stack<>();  // dequeue and peek read from here

    public void enqueue(int value) {
        inbox.push(value);
    }

    public int dequeue() {
        refillOutboxIfEmpty();
        return outbox.pop();
    }

    public int peek() {
        refillOutboxIfEmpty();
        return outbox.peek();
    }

    public boolean isEmpty() {
        return inbox.isEmpty() && outbox.isEmpty();
    }

    public int size() {
        return inbox.size() + outbox.size();
    }

    // Only when outbox is empty: pouring inbox reverses it, so the oldest element lands on top.
    private void refillOutboxIfEmpty() {
        if (outbox.isEmpty()) {
            while (!inbox.isEmpty()) {
                outbox.push(inbox.pop());
            }
        }
        if (outbox.isEmpty()) {
            throw new NoSuchElementException("Queue is empty");
        }
    }

    static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // case 1: basic FIFO order
        QueueUsingStacks q1 = new QueueUsingStacks();
        q1.enqueue(1);
        q1.enqueue(2);
        q1.enqueue(3);
        print("case 1 dequeue", q1.dequeue(), 1);
        print("case 1 peek   ", q1.peek(), 2);
        print("case 1 size   ", q1.size(), 2);

        // case 2: interleaved operations. 3 arrives while outbox still holds 2; 2 must come first.
        QueueUsingStacks q2 = new QueueUsingStacks();
        q2.enqueue(1);
        q2.enqueue(2);
        int first = q2.dequeue();
        q2.enqueue(3);
        int second = q2.dequeue();
        int third = q2.dequeue();
        print("case 2 order  ", first + "," + second + "," + third, "1,2,3");
        print("case 2 isEmpty", q2.isEmpty(), true);

        // case 3: dequeue on an empty queue throws
        QueueUsingStacks q3 = new QueueUsingStacks();
        String outcome;
        try {
            q3.dequeue();
            outcome = "returned";
        } catch (NoSuchElementException e) {
            outcome = "threw NoSuchElementException";
        }
        print("case 3 empty  ", outcome, "threw NoSuchElementException");
    }
}

/*
 * =====================================================================
 *  Remove All Adjacent Duplicates In String       LeetCode 1047 | Easy
 * =====================================================================
 *
 * PROBLEM
 *   Given a lowercase string, repeatedly delete any two adjacent equal characters until no
 *   such pair remains, and return the final string. Removing one pair can make a new pair
 *   adjacent, and that pair must be removed too. The answer is unique.
 *
 * EXAMPLE
 *   "abbaca"  ->  "ca"    remove "bb" -> "aaca", then "aa" -> "ca"
 *   "azxxzy"  ->  "ay"    remove "xx" -> "azzy", then "zz" -> "ay"  (cascade)
 *   "aaaa"    ->  ""      everything cancels
 *   ""        ->  "" "abc"     ->  "abc"   nothing adjacent is equal
 *
 * APPROACH  (Stack collapse on equal top)
 *   1. Walk the string once, keeping a stack of characters that have survived so far.
 *   2. If the current char equals the stack top, pop: the pair is destroyed.
 *   3. Otherwise push the current char.
 *   4. The stack, read BOTTOM to TOP, is the answer. Note: for-each over java.util.Stack
 *      iterates bottom to top, which is exactly the order we need here (see A01_StackTraversal).
 *   Second method (removeDuplicatesWithBuilder): the same loop with a StringBuilder as the
 *   stack. Its last char is the top; deleteCharAt(len-1) is pop. No boxing, and the result
 *   is already a string.
 *
 * KEY INSIGHT
 *   One pass is enough because the stack top always holds the character that is CURRENTLY
 *   adjacent to the new one, even after earlier removals. That is the whole trick: the
 *   "cascade" the problem describes happens for free, because popping exposes the previous
 *   survivor as the new top. Every "compare with top, then push or pop" simulation in this
 *   folder (asteroids, stars, backspace compare) reuses this shape.
 *
 * COMPLEXITY
 *   Time  O(n)  each character is pushed at most once and popped at most once
 *   Space O(n)  the stack holds the whole input when nothing collapses
 *
 * INTERVIEW FOLLOW-UPS
 *   - Remove duplicates of length k (LeetCode 1209): stack of (char, count) pairs.
 *   - Remove stars from a string (LeetCode 2390): '*' pops instead of an equal char.
 *   - Do it in place with a write pointer over a char array: O(1) extra space.
 *   - Backspace string compare (LeetCode 844): same collapse with '#' as the pop trigger.
 *
 * RUN
 *   main() runs 5 cases (typical, cascade, all cancel, empty, no pairs) through both
 *   methods and prints actual vs expected.
 */
import java.util.Stack;

class RemoveAdjacentDuplicates {

    // Approach 1: explicit Stack of characters
    public static String removeDuplicates(String s) {
        Stack<Character> survivors = new Stack<>();

        for (char c : s.toCharArray()) {
            if (!survivors.isEmpty() && survivors.peek() == c) {
                survivors.pop();   // c and the top form an adjacent pair: destroy both
            } else {
                survivors.push(c);
            }
        }

        // for-each over Stack is bottom-to-top, which is the original left-to-right order
        StringBuilder result = new StringBuilder();
        for (char c : survivors) {
            result.append(c);
        }
        return result.toString();
    }

    // Approach 2: StringBuilder as the stack. Last char is the top; no Character boxing.
    public static String removeDuplicatesWithBuilder(String s) {
        StringBuilder survivors = new StringBuilder();
        for (char c : s.toCharArray()) {
            int top = survivors.length() - 1;
            if (top >= 0 && survivors.charAt(top) == c) {
                survivors.deleteCharAt(top);
            } else {
                survivors.append(c);
            }
        }
        return survivors.toString();
    }

    static void print(String label, String input, String expected) {
        System.out.println(label + " \"" + input + "\": stack=\"" + removeDuplicates(input)
                + "\" builder=\"" + removeDuplicatesWithBuilder(input)
                + "\"   expected \"" + expected + "\"");
    }

    public static void main(String[] args) {
        print("case 1 typical   ", "abbaca", "ca");
        print("case 2 cascade   ", "azxxzy", "ay");
        print("case 3 all cancel", "aaaa", "");
        print("case 4 empty     ", "", "");
        print("case 5 no pairs  ", "abc", "abc");
    }
}

/*
 * =====================================================================
 *  Removing Stars From a String                    LeetCode 2390 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   s contains lowercase letters and '*'. Every '*' deletes the closest non-star
 *   character to its left and then disappears itself. The input guarantees a letter
 *   is always available to delete. Return the string that remains.
 *
 * EXAMPLE
 *   "leet**cod*e"  ->  "lecoe"   two stars erase "t","e"; the third erases "d"
 *   "erase*****"   ->  ""        every letter is erased
 *   "abc"          ->  "abc"     no stars, unchanged
 *
 * APPROACH  (in-place char array used as a stack)
 *   1. Copy s into a char[]; 'top' is the write pointer = current stack size.
 *   2. Letter: write it at chars[top] and advance top   (push).
 *   3. Star:   step top back by one                     (pop); the erased letter is
 *      simply overwritten by the next push.
 *   4. The answer is chars[0..top).
 *   A second method, removeStarsWithStringBuilder, does the same with an explicit
 *   StringBuilder as the stack (setLength(len - 1) is the pop). main() runs both.
 *
 * KEY INSIGHT
 *   "Delete the nearest thing to the left" is a stack pop. A stack is often just an
 *   index into an array you already own: push = write and advance, pop = step back.
 *   Overwriting in place is safe because the write pointer never overtakes the read
 *   pointer (top <= right at all times).
 *
 * COMPLEXITY
 *   Time  O(n)  one pass; each char is written at most once and erased at most once
 *   Space O(n)  the char[] copy that becomes the output (O(1) beyond the output)
 *
 * INTERVIEW FOLLOW-UPS
 *   - Backspace String Compare (LC 844): same idea with '#' as the star, then compare
 *   - Remove All Adjacent Duplicates (LC 1047): pop when the top equals the new char
 *   - What if a star may have no letter to its left? Guard the pop with top > 0
 *
 * RUN
 *   main() runs 3 cases (typical, all erased, no stars) and prints actual vs expected.
 */
class RemovingStarsFromAString {

    /** Author's approach: the char[] itself is the stack, 'top' is its size. */
    public static String removeStars(String s) {
        char[] chars = s.toCharArray();
        int top = 0; // next free slot == number of surviving letters
        for (int right = 0; right < chars.length; right++) {
            if (chars[right] == '*') {
                top--;                       // pop: forget the last surviving letter
            } else {
                chars[top++] = chars[right]; // push: keep this letter
            }
        }
        return new String(chars, 0, top);
    }

    /** Same algorithm with an explicit StringBuilder as the stack. */
    public static String removeStarsWithStringBuilder(String s) {
        StringBuilder stack = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '*') {
                stack.setLength(stack.length() - 1); // pop
            } else {
                stack.append(c);                     // push
            }
        }
        return stack.toString();
    }

    public static void main(String[] args) {
        String[] inputs   = {"leet**cod*e", "erase*****", "abc"};
        String[] expected = {"lecoe",       "",           "abc"};

        for (int i = 0; i < inputs.length; i++) {
            System.out.println("case " + (i + 1) + " in-place:       \"" + removeStars(inputs[i])
                    + "\"   expected \"" + expected[i] + "\"");
            System.out.println("case " + (i + 1) + " StringBuilder:  \""
                    + removeStarsWithStringBuilder(inputs[i])
                    + "\"   expected \"" + expected[i] + "\"");
        }
    }
}

/*
 * =====================================================================
 *  Minimum Add to Make Parentheses Valid            LeetCode 921 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   s contains only '(' and ')'. In one move you may insert a parenthesis anywhere.
 *   Return the minimum number of insertions that makes s valid (every opener has a
 *   closer after it, properly nested). s may be empty.
 *
 * EXAMPLE
 *   "()))(("  ->  4   two extra ')' need two '(' before them; two extra '(' need ')'
 *   "())"     ->  1   one unmatched ')'
 *   "((("     ->  3   three unmatched '('
 *   "))(("    ->  4   nothing pairs up at all
 *   ""        ->  0   already valid
 *
 * APPROACH  (two-sided balance counter)
 *   1. Scan left to right with two counters: open = unmatched '(' so far,
 *      close = ')' that arrived when no '(' was available.
 *   2. On '(' : open++.
 *   3. On ')' : if open > 0 it pairs with a pending '(' so open--; else close++.
 *   4. Answer = open + close. Each unmatched symbol needs exactly one insertion.
 *
 * KEY INSIGHT
 *   Valid Parentheses (LC 20) only needs one balance counter and a "did it ever go
 *   negative" check. Here, a ')' that would drive the balance negative is not a
 *   failure, it is a mandatory insertion, so count it separately and reset. The
 *   leftover '(' at the end are the other mandatory insertions. No stack is needed
 *   because there is only one bracket type.
 *
 * COMPLEXITY
 *   Time  O(n)  one pass Space O(1)  two ints
 *
 * INTERVIEW FOLLOW-UPS
 *   - Minimum Remove to Make Valid Parentheses (LC 1249): same counters, but you must
 *     rebuild the string, so record indices to delete
 *   - Minimum Insertions to Balance (LC 1541): each '(' needs "))", tricky odd cases
 *   - Longest Valid Parentheses (LC 32): needs positions, so a sentinel-index stack
 *
 * RUN
 *   main() runs 5 cases (typical, closer-heavy, opener-heavy, nothing pairs, empty)
 *   and prints actual vs expected. Fixed: main's last label said "()" while it was
 *   testing "))((".
 */
class MinimumAddToMakeParenthesesValid {

    public static int minAddToMakeValid(String s) {
        int unmatchedOpen = 0;  // '(' still waiting for a ')'
        int unmatchedClose = 0; // ')' that arrived with nothing to pair with

        for (char ch : s.toCharArray()) {
            if (ch == '(') {
                unmatchedOpen++;
            } else if (unmatchedOpen > 0) {
                unmatchedOpen--;        // this ')' pairs with a pending '('
            } else {
                unmatchedClose++;       // needs a '(' inserted before it
            }
        }
        return unmatchedOpen + unmatchedClose;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 \"()))((\"", minAddToMakeValid("()))(("), 4);
        print("case 2 \"())\"   ", minAddToMakeValid("())"), 1);
        print("case 3 \"(((\"   ", minAddToMakeValid("((("), 3);
        print("case 4 \"))((\"  ", minAddToMakeValid("))(("), 4);
        print("case 5 \"\" (empty)", minAddToMakeValid(""), 0);
    }
}

/*
 * =====================================================================
 *  Evaluate Reverse Polish Notation                 LeetCode 150 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   tokens is a valid postfix (RPN) expression: integers and the operators
 *   + - * /. Operands come before their operator. Division truncates toward zero
 *   and never divides by zero. Every intermediate value fits in a 32-bit int.
 *   Return the value of the expression.
 *
 * EXAMPLE
 *   ["2","1","+","3","*"]                 ->  9    (2 + 1) * 3
 *   ["4","13","5","/","+"]                ->  6    4 + (13 / 5) = 4 + 2, truncation
 *   ["10","6","9","3","+","-11","*","/","*","17","+","5","+"]  ->  22
 *   ["18"]                                ->  18   single operand, nothing to do
 *
 * APPROACH  (operand stack, arrow-form switch)
 *   1. Walk the tokens left to right with a stack of ints.
 *   2. Number: push it.
 *   3. Operator: pop the RIGHT operand first, then the LEFT, apply, push the result.
 *      For + and * the order does not matter, so pop() op pop() is fine inline.
 *      For - and / it does: b = pop(), a = pop(), push(a - b) and (a / b).
 *   4. When the tokens are exhausted, the single value left on the stack is the answer.
 *
 * KEY INSIGHT
 *   Postfix needs no precedence rules and no parentheses: the stack IS the
 *   evaluation order. The only trap is operand order for the non-commutative
 *   operators. Java's arrow-form switch (case "x" -> ...) has no fall-through and
 *   needs no break, which removes the classic bug of a missing break.
 *
 * COMPLEXITY
 *   Time  O(n)  each token is pushed once and popped at most once
 *   Space O(n)  the operand stack in the worst case (all numbers first)
 *
 * INTERVIEW FOLLOW-UPS
 *   - Basic Calculator (LC 224/227): infix input, so you must also handle precedence
 *   - Convert infix to postfix (shunting-yard) and then evaluate with this function
 *   - What breaks with Integer.parseInt for "-11"? Nothing: the minus is part of the
 *     token, so the default branch handles negative literals correctly
 *
 * RUN
 *   main() runs 4 cases (typical, truncating division, long with negatives, single
 *   operand) and prints actual vs expected.
 */
import java.util.Arrays;
import java.util.Stack;

class EvaluateReversePolishNotation {

    public static int evalRPN(String[] tokens) {
        Stack<Integer> stack = new Stack<>();

        for (String token : tokens) {
            switch (token) {
                case "+" -> stack.push(stack.pop() + stack.pop());
                case "-" -> {
                    int right = stack.pop(); // top of stack is the right operand
                    int left = stack.pop();
                    stack.push(left - right);
                }
                case "*" -> stack.push(stack.pop() * stack.pop());
                case "/" -> {
                    int divisor = stack.pop();
                    int dividend = stack.pop();
                    stack.push(dividend / divisor); // Java int division truncates toward zero
                }
                default -> stack.push(Integer.parseInt(token)); // handles "-11" too
            }
        }
        return stack.pop();
    }

    private static void print(String label, String[] tokens, int expected) {
        System.out.println(label + " " + Arrays.toString(tokens) + " -> " + evalRPN(tokens)
                + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1", new String[]{"2", "1", "+", "3", "*"}, 9);
        print("case 2", new String[]{"4", "13", "5", "/", "+"}, 6);
        String[] longWithNegative =
                {"10", "6", "9", "3", "+", "-11", "*", "/", "*", "17", "+", "5", "+"};
        print("case 3", longWithNegative, 22);
        print("case 4", new String[]{"18"}, 18);
    }
}

/*
 * =====================================================================
 *  Stack Sortable Permutation                       GeeksforGeeks | Medium
 * =====================================================================
 *
 * PROBLEM
 *   A is a permutation of 1..n. You read it left to right; each element must be
 *   pushed onto a single stack, and at any moment you may pop the top to the output.
 *   Return true if the output can be exactly 1, 2, ..., n (the sorted order).
 *
 * EXAMPLE
 *   [4, 1, 2, 3]  ->  true    push 4; push 1 pop 1; push 2 pop 2; push 3 pop 3; pop 4
 *   [4, 3, 1, 2]  ->  true    push 4,3,1; pop 1; push 2; pop 2, pop 3, pop 4
 *   [2, 3, 1]     ->  false   2 is buried under 3, but 2 is due before 3
 *   [3, 1, 4, 2]  ->  false   after popping 1, 3 is under 4 and 2 is still coming
 *   [1, 2, 3, 4]  ->  true    already sorted, pop each right after its push
 *   []            ->  true    nothing to sort
 *
 * APPROACH  (greedy stack simulation)
 *   1. expected = 1, the next value the sorted output needs.
 *   2. For each element: push it, then while the top equals expected, pop and
 *      expected++. Popping as early as possible is always safe: the top is exactly
 *      what the output needs, and holding it can only block later values.
 *   3. After the scan, sortable iff expected == n + 1 (every value was output in order).
 *
 * KEY INSIGHT
 *   The stack models a process, not a pairing of symbols. The greedy rule works
 *   because the stack is LIFO: if a smaller value ever ends up below a larger one
 *   while an even smaller value is still to come (the 2-3-1 pattern), the smaller
 *   one can never get out in time. Popping whenever the top is 'expected' is the
 *   only way to avoid burying it. Same simulation as Validate Stack Sequences.
 *
 * COMPLEXITY
 *   Time  O(n)  each value is pushed once and popped at most once
 *   Space O(n)  the stack in the worst case (a descending input)
 *
 * INTERVIEW FOLLOW-UPS
 *   - Validate Stack Sequences (LC 946): same loop, but the pop order is a given array
 *   - Characterise sortable permutations: exactly those avoiding the 2-3-1 pattern
 *   - Count them: the n-th Catalan number
 *   - What if A is not a permutation (duplicates or gaps)? The == expected test fails
 *     and the method returns false, which is the right answer for "sorted 1..n"
 *
 * RUN
 *   main() runs 6 cases (typical, hidden-true, two false shapes, sorted, empty) and
 *   prints actual vs expected. Fixed: main labelled every line "A1" and claimed
 *   [4,3,1,2] is not sortable; it is (the code was right, the comment was wrong).
 */
import java.util.Arrays;
import java.util.Stack;

class StackSortable {

    public static boolean isStackSortable(int[] A) {
        Stack<Integer> stack = new Stack<>();
        int expected = 1; // the next value the sorted output needs

        for (int value : A) {
            stack.push(value);
            // Pop greedily while the top is exactly what the output needs next
            while (!stack.isEmpty() && stack.peek() == expected) {
                stack.pop();
                expected++;
            }
        }
        // Every value 1..n was output in order iff expected advanced past n
        return expected == A.length + 1;
    }

    private static void print(String label, int[] A, boolean expected) {
        System.out.println(label + " " + Arrays.toString(A) + " -> " + isStackSortable(A)
                + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1", new int[]{4, 1, 2, 3}, true);
        print("case 2", new int[]{4, 3, 1, 2}, true);
        print("case 3", new int[]{2, 3, 1}, false);
        print("case 4", new int[]{3, 1, 4, 2}, false);
        print("case 5", new int[]{1, 2, 3, 4}, true);
        print("case 6", new int[]{}, true);
    }
}

/*
 * =====================================================================
 *  Buildings With an Ocean View                     LeetCode 1762 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   heights[i] is the height of building i in a line; the ocean is to the RIGHT.
 *   Building i has an ocean view if every building to its right is strictly
 *   shorter. Return the indices of all such buildings in increasing order.
 *
 * EXAMPLE
 *   [4, 2, 3, 1]  ->  [0, 2, 3]      1 blocks nothing; 3 blocks 2; 4 beats all
 *   [4, 3, 2, 1]  ->  [0, 1, 2, 3]   strictly decreasing, everyone sees the ocean
 *   [1, 3, 2, 4]  ->  [3]            4 blocks everything to its left
 *   [2, 2, 2]     ->  [2]            equal height blocks the view (strictly shorter)
 *   [7]           ->  [0]            the last building always sees the ocean
 *
 * APPROACH  (right-to-left running maximum)
 *   1. Walk from the last building to the first, keeping maxToRight = tallest
 *      building seen so far (i.e. everything to the right of the current one).
 *   2. If heights[i] > maxToRight the building sees the ocean: record i, update max.
 *   3. Indices were collected right to left, so reverse the list before returning.
 *
 * KEY INSIGHT
 *   "Can see past everything on one side" only depends on the maximum on that side,
 *   so scan from that side and carry one number. This is the degenerate case of a
 *   monotonic stack: a strictly decreasing stack whose only useful element is its
 *   top collapses to a single variable. If the scan must go LEFT to right instead
 *   (streaming input), you need the real stack: pop every building that is <= the
 *   new one, and what remains at the end is the answer.
 *
 * COMPLEXITY
 *   Time  O(n)  one pass plus a reverse of the result
 *   Space O(1)  extra beyond the output list
 *
 * INTERVIEW FOLLOW-UPS
 *   - Ocean on the left: scan left to right with the same running max, no reverse
 *   - Buildings arrive one at a time (left to right): monotonic decreasing stack
 *   - Count how many buildings each one can see (LC 1944): stack with pop counting
 *   - Return heights instead of indices, or use >= if equal heights do not block
 *
 * RUN
 *   main() runs 5 cases (typical, all visible, only last, all equal, single) and
 *   prints actual vs expected.
 */
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

class BuildingsWithOceanView {

    public static List<Integer> findBuildings(int[] heights) {
        List<Integer> result = new ArrayList<>();
        int maxToRight = Integer.MIN_VALUE; // nothing to the right of the last building

        for (int i = heights.length - 1; i >= 0; i--) {
            if (heights[i] > maxToRight) { // strictly taller than everything to its right
                result.add(i);
                maxToRight = heights[i];
            }
        }
        Collections.reverse(result); // collected right to left; answer wants increasing
        return result;
    }

    private static void print(String label, int[] heights, String expected) {
        System.out.println(label + " " + Arrays.toString(heights) + " -> "
                + findBuildings(heights) + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1", new int[]{4, 2, 3, 1}, "[0, 2, 3]");
        print("case 2", new int[]{4, 3, 2, 1}, "[0, 1, 2, 3]");
        print("case 3", new int[]{1, 3, 2, 4}, "[3]");
        print("case 4", new int[]{2, 2, 2}, "[2]");
        print("case 5", new int[]{7}, "[0]");
    }
}

/*
 * =====================================================================
 *  Daily Temperatures                            LeetCode 739 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Given an array of daily temperatures, return an array where answer[i] is how many days
 *   you must wait after day i for a strictly warmer temperature. If no warmer day ever comes,
 *   answer[i] = 0. Up to 1e5 days, so the O(n^2) "scan right for each day" is too slow.
 *
 * EXAMPLE
 *   [73, 74, 75, 71, 69, 72, 76, 73]  ->  [1, 1, 4, 2, 1, 1, 0, 0]
 *   [50, 50, 50]                      ->  [0, 0, 0]   equal is not warmer
 *   [90, 80, 70]                      ->  [0, 0, 0]   never gets warmer
 *   [42]                              ->  [0]
 *
 * APPROACH  (monotonic decreasing stack of indices)
 *   1. Walk left to right. The stack holds indices of days still waiting for a warmer day;
 *      their temperatures decrease from bottom to top.
 *   2. For day i, while the index on top has a colder temperature than temps[i], pop it:
 *      day i is its answer, so result[top] = i - top.
 *   3. Push i. It now waits for its own warmer day.
 *   4. Whatever is left on the stack never found a warmer day; result stays 0 for them.
 *
 * KEY INSIGHT
 *   This is Next Greater Element, but the answer is a DISTANCE, so store indices, not values.
 *   Each index is pushed once and popped at most once, which is why the nested while loop is
 *   still linear. Pattern to recognise: "for each element, the nearest larger/smaller element
 *   to the left/right" is always a monotonic stack.
 *
 * COMPLEXITY
 *   Time  O(n)  every index is pushed and popped at most once
 *   Space O(n)  the stack, worst case on strictly decreasing input
 *
 * INTERVIEW FOLLOW-UPS
 *   - O(1) extra space: walk right to left and hop through result[] (j = i + 1, then
 *     j += result[j]) until temps[j] > temps[i] or result[j] == 0.
 *   - Return the warmer day's index or temperature instead of the distance.
 *   - Circular array: Next Greater Element II, loop 2n times and index with i % n.
 *
 * RUN
 *   main() runs 4 cases (typical, all equal, never warmer, single) and prints actual vs expected.
 */

import java.util.Arrays;
import java.util.Stack;

class DailyTemperatures {

    public int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] result = new int[n];
        // Indices of days still waiting for a warmer day; temperatures decrease bottom to top.
        Stack<Integer> waiting = new Stack<>();
        for (int today = 0; today < n; today++) {
            // Today answers every waiting day that is strictly colder than today.
            while (!waiting.isEmpty() && temperatures[today] > temperatures[waiting.peek()]) {
                int colderDay = waiting.pop();
                result[colderDay] = today - colderDay;
            }
            waiting.push(today);
        }
        return result;
    }

    private static void print(String label, int[] actual, int[] expected) {
        System.out.println(label + ": " + Arrays.toString(actual)
                + "   expected " + Arrays.toString(expected));
    }

    public static void main(String[] args) {
        DailyTemperatures solution = new DailyTemperatures();

        print("case 1 typical      ",
                solution.dailyTemperatures(new int[]{73, 74, 75, 71, 69, 72, 76, 73}),
                new int[]{1, 1, 4, 2, 1, 1, 0, 0});
        print("case 2 all equal    ",
                solution.dailyTemperatures(new int[]{50, 50, 50}),
                new int[]{0, 0, 0});
        print("case 3 never warmer ",
                solution.dailyTemperatures(new int[]{90, 80, 70}),
                new int[]{0, 0, 0});
        print("case 4 single day   ",
                solution.dailyTemperatures(new int[]{42}),
                new int[]{0});
    }
}

/*
 * =====================================================================
 *  Remove K Digits                               LeetCode 402 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Given a non-negative integer as a string num and an integer k, remove exactly k digits so
 *   the remaining number is the smallest possible. Digit order must be preserved. Return the
 *   result without leading zeros; if nothing is left, return "0". k <= num.length().
 *
 * EXAMPLE
 *   num = "1432219", k = 3  ->  "1219"   remove 4, 3, 2
 *   num = "10200",   k = 1  ->  "200"    remove the 1, then strip the leading 0
 *   num = "10",      k = 2  ->  "0"      everything removed
 *   num = "1234",    k = 1  ->  "123"    already increasing, so drop from the end
 *   num = "100",     k = 1  ->  "0"      "00" collapses to a single "0"
 *
 * APPROACH  (monotonic non-decreasing stack with a removal budget)
 *   1. Scan digits left to right, keeping a stack whose digits never decrease bottom to top.
 *   2. Before pushing digit d, while the top is larger than d and k > 0, pop it and spend one
 *      removal: replacing a bigger digit with a smaller one in a higher position is the best
 *      possible move.
 *   3. Push d.
 *   4. If budget remains, the stack is non-decreasing, so pop from the top (the biggest digits).
 *   5. Rebuild the string bottom to top and strip leading zeros; return "0" if empty.
 *
 * KEY INSIGHT
 *   Greedy: the leftmost "peak" (a digit followed by a smaller one) is always the right thing
 *   to remove first, because it lowers the most significant position that can be lowered.
 *   The monotonic stack finds every such peak in one pass. Same skeleton as Remove Duplicate
 *   Letters and Create Maximum Number, only the pop condition changes.
 *
 * COMPLEXITY
 *   Time  O(n)  each digit is pushed once and popped at most once
 *   Space O(n)  the stack and the result builder
 *
 * INTERVIEW FOLLOW-UPS
 *   - Largest number instead of smallest: pop while the top is SMALLER than the new digit.
 *   - Remove Duplicate Letters (LeetCode 316): same stack, pop only if the char appears later.
 *   - Why "0" and not ""? The problem asks for a number; "00" and "" both mean zero.
 *
 * RUN
 *   main() runs 5 cases (typical, leading zero, remove all, already increasing, all zeros)
 *   and prints actual vs expected.
 */

import java.util.Stack;

class RemoveKdigits {

    public static String removeKdigits(String num, int k) {
        if (num.length() == k) {
            return "0";
        }
        // Digits kept so far; never decreasing from bottom to top.
        Stack<Character> kept = new Stack<>();

        for (int i = 0; i < num.length(); i++) {
            char digit = num.charAt(i);
            // A bigger digit on top followed by a smaller one is a peak: pop it while budget lasts.
            while (k > 0 && !kept.isEmpty() && kept.peek() > digit) {
                kept.pop();
                k--;
            }
            kept.push(digit);
        }
        // Budget left over means the digits are non-decreasing; the largest ones are on top.
        while (k > 0) {
            kept.pop();
            k--;
        }

        StringBuilder result = new StringBuilder();
        while (!kept.isEmpty()) {
            result.append(kept.pop());
        }
        result.reverse(); // popped top-down, so flip back to original order

        while (result.length() > 1 && result.charAt(0) == '0') {
            result.deleteCharAt(0);
        }
        return result.toString();
    }

    private static void print(String label, String actual, String expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 typical             ", removeKdigits("1432219", 3), "1219");
        print("case 2 leading zero        ", removeKdigits("10200", 1), "200");
        print("case 3 remove everything   ", removeKdigits("10", 2), "0");
        print("case 4 already increasing  ", removeKdigits("1234", 1), "123");
        print("case 5 collapses to zero   ", removeKdigits("100", 1), "0");
    }
}

/*
 * =====================================================================
 *  Car Fleet                                     LeetCode 853 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   n cars drive along a one-lane road toward mile target. position[i] is where car i starts
 *   and speed[i] its speed; all start positions are distinct. A car cannot overtake: when it
 *   catches a slower car it slows down and they travel together as one fleet. Catching up
 *   exactly at the target still counts as joining. Return how many fleets reach the target.
 *
 * EXAMPLE
 *   target = 12, position = [10, 8, 0, 5, 3], speed = [2, 4, 1, 1, 3]  ->  3
 *     cars at 10 and 8 meet at 12; car at 0 is alone; cars at 5 and 3 meet at 6
 *   target = 10, position = [3], speed = [3]                            ->  1   single car
 *   target = 100, position = [0, 2, 4], speed = [4, 2, 1]               ->  1   all catch up
 *   target = 10, position = [6, 8], speed = [3, 2]                      ->  2   never meet
 *
 * APPROACH  (sort by position, then compare arrival times front to back)
 *   1. For each car compute time = (target - position) / speed, as a double.
 *   2. Sort cars by start position, closest to the target first. The front car can never be
 *      caught by anything ahead of it, so it is always the head of a fleet.
 *   3. Walk the sorted list keeping lastFleetTime, the arrival time of the fleet in front.
 *      If this car's time is LARGER, it can never catch that fleet: count a new fleet and remember
 *      its time. If its time is smaller or equal, it would reach the target no later than the fleet
 *      ahead, so it catches up and merges; it inherits the slower fleet's time (no update).
 *
 * KEY INSIGHT
 *   Position order plus arrival time turns a physics question into a monotonic scan. A car
 *   behind merges when its (unblocked) arrival time <= the fleet ahead; the fleet's time is the
 *   maximum so far, so only a strictly larger time starts a new fleet. Written with an explicit
 *   stack of times, this is a monotonic increasing stack whose final size is the answer.
 *
 * COMPLEXITY
 *   Time  O(n log n)  the sort dominates; the scan is O(n)
 *   Space O(n)        the position/time pairs
 *
 * INTERVIEW FOLLOW-UPS
 *   - Car Fleet II (LeetCode 1776): return WHEN each car collides, needs a real stack.
 *   - Why doubles? Integer division would merge cars that actually arrive at different times.
 *
 * RUN
 *   main() runs 4 cases (typical, single car, all merge, none merge) and prints actual vs expected.
 */

import java.util.Arrays;

class CarFleet {

    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        // cars[i] = { start position, time to reach target driving unblocked }
        double[][] cars = new double[n][2];
        for (int i = 0; i < n; i++) {
            cars[i][0] = position[i];
            cars[i][1] = (double) (target - position[i]) / speed[i]; // double: avoid truncation
        }
        // Closest to the target first, so the fleet in front is processed before its followers.
        Arrays.sort(cars, (a, b) -> Double.compare(b[0], a[0]));

        int fleets = 0;
        double lastFleetTime = 0.0;
        for (double[] car : cars) {
            double arrivalTime = car[1];
            if (arrivalTime > lastFleetTime) {
                // Slower than the fleet ahead: it can never catch up, so it leads a new fleet.
                fleets++;
                lastFleetTime = arrivalTime;
            }
            // else: it reaches the target no later than the fleet ahead, so it merges into it.
        }
        return fleets;
    }

    private static void print(String label, int actual, int expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        CarFleet cf = new CarFleet();
        print("case 1 typical    ",
                cf.carFleet(12, new int[]{10, 8, 0, 5, 3}, new int[]{2, 4, 1, 1, 3}), 3);
        print("case 2 single car ", cf.carFleet(10, new int[]{3}, new int[]{3}), 1);
        print("case 3 all merge  ", cf.carFleet(100, new int[]{0, 2, 4}, new int[]{4, 2, 1}), 1);
        print("case 4 none merge ", cf.carFleet(10, new int[]{6, 8}, new int[]{3, 2}), 2);
    }
}

/*
 * =====================================================================
 *  Sum of Subarray Minimums                      LeetCode 907 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Given an integer array arr, return the sum of min(b) over every contiguous subarray b,
 *   modulo 1e9 + 7. Up to 3e4 elements, so enumerating all O(n^2) subarrays is too slow.
 *
 * EXAMPLE
 *   [3, 1, 2, 4]          ->  17    mins: 3,1,2,4, 1,1,2, 1,1, 1  =  17
 *   [11, 81, 94, 43, 3]   ->  444
 *   [2, 2, 2]             ->  12    6 subarrays, every min is 2 (tie-break must not double count)
 *   [5]                   ->  5
 *
 * APPROACH  (previous smaller-or-equal + next strictly smaller, count contributions)
 *   1. prev[i]: index of the nearest element to the LEFT that is smaller OR EQUAL (-1 if none).
 *      Left-to-right monotonic increasing stack, pop while arr[top] > arr[i].
 *   2. next[i]: index of the nearest element to the RIGHT that is STRICTLY smaller (n if none).
 *      Right-to-left stack, pop while arr[top] >= arr[i].
 *   3. arr[i] is the minimum of every subarray that starts in (prev[i], i] and ends in
 *      [i, next[i]). That is (i - prev[i]) * (next[i] - i) subarrays.
 *   4. Answer = sum of arr[i] * leftCount * rightCount, taking the modulus at every step.
 *
 * KEY INSIGHT
 *   Flip the question: instead of "what is the min of each subarray", ask "how many subarrays
 *   is each element the min of". That turns O(n^2) subarrays into O(n) contributions.
 *   Ties: use strict on one side and non-strict on the other. For equal values, the LEFT copy
 *   owns the subarrays spanning both; if both sides were strict, those would be counted twice,
 *   and if both non-strict, counted by nobody.
 *
 * COMPLEXITY
 *   Time  O(n)  three linear passes; each index is pushed and popped at most once
 *   Space O(n)  prev[], next[] and the stack
 *
 * INTERVIEW FOLLOW-UPS
 *   - Sum of Subarray Ranges (LeetCode 2104): run the same thing for maximums and subtract.
 *   - Single pass version: compute the contribution at pop time instead of storing prev/next.
 *   - Why long and the mod inside the product? arr[i] * left * right can exceed int and even
 *     long if the mod is only applied at the end.
 *
 * RUN
 *   main() runs 4 cases (typical, LeetCode example 2, all equal, single) and prints
 *   actual vs expected.
 */

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

class SumOfSubarrayMinimums {
    private static final int MOD = 1_000_000_007; // 10^9 + 7

    public static int sumSubarrayMins(int[] arr) {
        int n = arr.length;
        int[] prevSmallerOrEqual = previousSmallerOrEqual(arr);
        int[] nextStrictlySmaller = nextStrictlySmaller(arr);

        long total = 0;
        for (int i = 0; i < n; i++) {
            long leftChoices = i - prevSmallerOrEqual[i];      // valid start indices
            long rightChoices = nextStrictlySmaller[i] - i;   // valid end indices
            total = (total + arr[i] * leftChoices % MOD * rightChoices % MOD) % MOD;
        }
        return (int) total;
    }

    /** prev[i] = nearest index on the left with arr[j] <= arr[i], or -1. Non-strict. */
    private static int[] previousSmallerOrEqual(int[] arr) {
        int n = arr.length;
        int[] prev = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && arr[stack.peek()] > arr[i]) {
                stack.pop();
            }
            prev[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }
        return prev;
    }

    /** next[i] = nearest index on the right with arr[j] < arr[i], or n. Strict on purpose. */
    private static int[] nextStrictlySmaller(int[] arr) {
        int n = arr.length;
        int[] next = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && arr[stack.peek()] >= arr[i]) {
                stack.pop();
            }
            next[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }
        return next;
    }

    private static void print(String label, int[] input, int expected) {
        System.out.println(label + ": " + Arrays.toString(input) + " -> "
                + sumSubarrayMins(input) + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 typical   ", new int[]{3, 1, 2, 4}, 17);
        print("case 2 example 2 ", new int[]{11, 81, 94, 43, 3}, 444);
        print("case 3 all equal ", new int[]{2, 2, 2}, 12);
        print("case 4 single    ", new int[]{5}, 5);
    }
}

/*
 * =====================================================================
 *  132 Pattern                                          LeetCode 456 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Given an integer array, decide whether there exist indices i < j < k with
 *   nums[i] < nums[k] < nums[j]  (a small value, then the largest, then a
 *   middle value). Return true or false. Arrays shorter than 3 are false.
 *
 * EXAMPLE
 *   [3, 1, 6, 5, 4, 3, 2]  ->  true    1 < 5 < 6  (or 1 < 2 < 6, etc.)
 *   [-1, 3, 2, 0]          ->  true    -1 < 2 < 3
 *   [1, 2, 3, 4]           ->  false   strictly increasing, no "3 then 2"
 *   [4, 3, 2, 1]           ->  false   nothing smaller before a peak
 *   [1, 2]                 ->  false   fewer than 3 elements
 *
 * APPROACH  (right-to-left monotonic stack, track the best "2")
 *   1. Scan from the right. Keep a stack of candidates for the "3" (the peak)
 *      that is decreasing from bottom to top.
 *   2. Keep 'second' = the largest value ever popped: a value that has some
 *      bigger element to its right, i.e. the best "2" seen so far.
 *   3. If nums[i] < second, nums[i] is a valid "1": pattern found.
 *   4. Otherwise pop every stack value smaller than nums[i] into 'second'
 *      (nums[i] becomes their "3"), then push nums[i].
 *
 * KEY INSIGHT
 *   Fix the "3" as the element being scanned and ask: what is the largest "2"
 *   that already has a bigger element to its right? The largest popped value
 *   is exactly that, and a larger "2" only makes the "1 < 2" check easier.
 *   'second' never needs to decrease because pops only happen when a bigger
 *   "3" arrives, so every popped value is a legitimate "2" with a "3" after it.
 *
 * COMPLEXITY
 *   Time  O(n)  each element pushed and popped at most once
 *   Space O(n)  stack in the worst case (increasing input scanned right to left)
 *
 * INTERVIEW FOLLOW-UPS
 *   - O(n^2) baseline: for each j, track min on the left and scan k to the right.
 *   - Return the actual indices (i, j, k) rather than a boolean.
 *   - Why scan right to left? Scanning left to right you know the "1" (prefix
 *     min) but not the "3", and the stack cannot look ahead.
 *   - Count all 132 subsequences: no longer a stack problem, needs BIT/DP.
 *
 * RUN
 *   main() runs 5 cases (typical, negative, increasing, decreasing, too short)
 *   and prints actual vs expected.
 */

import java.util.Arrays;
import java.util.Stack;

class Find132pattern {

    public static boolean find132pattern(int[] nums) {
        int n = nums.length;
        if (n < 3) return false;

        Stack<Integer> peakCandidates = new Stack<>(); // candidates for the "3", decreasing upward
        int second = Integer.MIN_VALUE;                // best "2": largest value popped so far

        for (int i = n - 1; i >= 0; i--) {
            if (nums[i] < second) {
                return true; // nums[i] is the "1" for the already-found "3 ... 2"
            }
            // nums[i] is bigger than these, so it serves as their "3"; remember the largest
            while (!peakCandidates.isEmpty() && nums[i] > peakCandidates.peek()) {
                second = peakCandidates.pop();
            }
            peakCandidates.push(nums[i]);
        }
        return false;
    }

    static void print(String label, int[] nums, boolean expected) {
        System.out.println(label + " " + Arrays.toString(nums) + ": "
                + find132pattern(nums) + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 typical   ", new int[]{3, 1, 6, 5, 4, 3, 2}, true);
        print("case 2 negative  ", new int[]{-1, 3, 2, 0}, true);
        print("case 3 increasing", new int[]{1, 2, 3, 4}, false);
        print("case 4 decreasing", new int[]{4, 3, 2, 1}, false);
        print("case 5 too short ", new int[]{1, 2}, false);
    }
}

/*
 * =====================================================================
 *  Asteroid Collision                          LeetCode 735 | Medium     MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Each int is an asteroid: |value| is its size, sign is its direction (+ right, - left).
 *   All move at the same speed on one line. When two meet, the smaller explodes; equal sizes
 *   both explode. Return the asteroids left after every collision. No value is 0.
 *
 * EXAMPLE
 *   [5, 10, -5]      ->  [5, 10]          10 beats -5; 5 and 10 move the same way, never meet
 *   [8, -8]          ->  []               equal sizes, both explode
 *   [10, 2, -5]      ->  [10]             -5 kills 2, then loses to 10
 *   [-2, -1, 1, 2]   ->  [-2, -1, 1, 2]   lefts are already past, rights never turn back
 *
 * APPROACH  (stack collision simulation)
 *   1. Scan left to right; the stack holds survivors so far, top = the nearest one to the left.
 *   2. A right-mover can never hit anything already on the stack: push it.
 *   3. A left-mover fights while the top is a right-mover:
 *        top smaller  -> pop, keep fighting
 *        top equal    -> pop and mark the current one destroyed (set to 0)
 *        top larger   -> mark the current one destroyed
 *   4. Push the current asteroid only if it survived (non-zero).
 *   5. Drain the stack bottom-to-top into the answer array.
 *
 * KEY INSIGHT
 *   Only "right-mover on the stack, left-mover arriving" can collide, so one while loop with a
 *   three-way branch covers every case. Setting the current value to 0 is a cheap "destroyed"
 *   flag that also exits the loop (the condition needs current < 0). Pattern: stack simulation
 *   where each new element may cancel a run of earlier ones.
 *
 * COMPLEXITY
 *   Time  O(n)  every asteroid is pushed at most once and popped at most once
 *   Space O(n)  the stack in the worst case (all right-movers)
 *
 * INTERVIEW FOLLOW-UPS
 *   - Robot Collisions (LC 2751): same loop but with health and unsorted positions
 *   - What if speeds differ? Then it is Car Fleet (LC 853), which needs arrival times
 *   - Return the number of collisions instead of the survivors (count the pops)
 *
 * RUN
 *   main() runs 4 cases (typical, equal sizes, chain kill, no collision) and prints
 *   actual vs expected.
 */
import java.util.Arrays;
import java.util.Stack;

// https://leetcode.com/problems/asteroid-collision/description/
class ImportantAsteroidCollision {

    public static int[] asteroidCollision(int[] asteroids) {
        Stack<Integer> survivors = new Stack<>();

        for (int current : asteroids) {
            // A collision is only possible when the top moves right and current moves left.
            while (!survivors.isEmpty() && current < 0 && survivors.peek() > 0) {
                int top = survivors.peek();
                int currentSize = Math.abs(current);
                if (top < currentSize) {
                    survivors.pop();          // current wins, keep fighting the next one down
                } else if (top == currentSize) {
                    survivors.pop();
                    current = 0;              // both explode; 0 = destroyed, also exits the loop
                } else {
                    current = 0;              // top wins; current is destroyed
                }
            }
            // Input guarantees no 0, so 0 can only mean "destroyed".
            if (current != 0) survivors.push(current);
        }

        int[] result = new int[survivors.size()];
        for (int i = survivors.size() - 1; i >= 0; i--) {
            result[i] = survivors.pop();
        }
        return result;
    }

    private static void print(String label, int[] input, int[] expected) {
        System.out.println(label + ": " + Arrays.toString(asteroidCollision(input))
                + "   expected " + Arrays.toString(expected));
    }

    public static void main(String[] args) {
        print("case 1 typical      ", new int[]{5, 10, -5}, new int[]{5, 10});
        print("case 2 equal sizes  ", new int[]{8, -8}, new int[]{});
        print("case 3 chain kill   ", new int[]{10, 2, -5}, new int[]{10});
        print("case 4 no collision ", new int[]{-2, -1, 1, 2}, new int[]{-2, -1, 1, 2});
    }
}

/*
 * =====================================================================
 *  Simplify Path                                        LeetCode 71 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Given an absolute Unix path, return its canonical form: starts with "/", single slashes
 *   between names, no trailing slash, "." (current dir) removed, ".." (parent dir) resolved.
 *   ".." at the root stays at the root. Any other run of dots (e.g. "...") is a normal name.
 *
 * EXAMPLE
 *   "/home/"                          ->  "/home"
 *   "/home//foo/"                     ->  "/home/foo"           empty segment ignored
 *   "/home/user/Documents/../Pictures" ->  "/home/user/Pictures"
 *   "/../"                            ->  "/"                   cannot go above root
 *   "/.../a/../b/c/../d/./"           ->  "/.../b/d"            "..." is a real name
 *
 * APPROACH  (token stack for path resolution)
 *   1. Split on "/" to get segments. Empty strings appear for "//" and the leading "/".
 *   2. For each segment:
 *        ".."         -> pop the stack if it is non-empty (root absorbs extra "..")
 *        "." or ""    -> skip anything else -> push (it is a directory name)
 *   3. Empty stack means root: return "/".
 *   4. Otherwise join the stack bottom-to-top with "/" in front of each name.
 *
 * KEY INSIGHT
 *   Work on tokens, not characters: split first, then the stack only ever sees whole names.
 *   The problem is really an edge-case checklist (empty segments, ".", ".." at root, "..." as a
 *   name), so state the rules aloud before coding. Note that iterating java.util.Stack goes
 *   bottom-to-top, which is exactly the order a path needs here.
 *
 * COMPLEXITY
 *   Time  O(n)  one pass to split, one pass over segments, one pass to join
 *   Space O(n)  the segment array and the stack
 *
 * INTERVIEW FOLLOW-UPS
 *   - Relative paths: resolve against a given current directory
 *   - Symlinks or "~": which segments need extra state?
 *   - Do it without split(): scan with two pointers between slashes to avoid the array
 *
 * RUN
 *   main() runs 5 cases (typical, double slash, "..", ".." at root, "..." name) and prints
 *   actual vs expected.
 */
import java.util.Stack;

// https://leetcode.com/problems/simplify-path/
class SimplifyPath {

    public static String simplifyPath(String path) {
        String[] segments = path.split("/");   // "" for leading slash and for "//"
        Stack<String> dirs = new Stack<>();

        for (String segment : segments) {
            if (segment.equals("..")) {
                if (!dirs.isEmpty()) dirs.pop();     // at root ".." is a no-op
            } else if (!segment.equals(".") && !segment.isEmpty()) {
                dirs.push(segment);                  // a real directory name (includes "...")
            }
        }

        if (dirs.isEmpty()) return "/";

        StringBuilder canonical = new StringBuilder();
        for (String dir : dirs) {                    // Stack iterates bottom-to-top: root first
            canonical.append('/').append(dir);
        }
        return canonical.toString();
    }

    private static void print(String label, String path, String expected) {
        System.out.println(label + ": " + simplifyPath(path) + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 trailing slash ", "/home/", "/home");
        print("case 2 double slash   ", "/home//foo/", "/home/foo");
        print("case 3 parent dir     ", "/home/user/Documents/../Pictures", "/home/user/Pictures");
        print("case 4 above root     ", "/../", "/");
        print("case 5 dots as a name ", "/.../a/../b/c/../d/./", "/.../b/d");
    }
}

/*
 * =====================================================================
 *  Decode String                                     LeetCode 394 | Medium     MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Decode a string where k[encoded] means "repeat encoded k times". Brackets nest, k is a
 *   positive integer (may have several digits), and letters outside brackets are copied as-is.
 *   Input is guaranteed valid; length <= 30, k <= 300.
 *
 * EXAMPLE
 *   "3[a]2[bc]"       ->  "aaabcbc"
 *   "3[a2[c]]"        ->  "accaccacc"        inner 2[c] = "cc", then a+cc repeated 3 times
 *   "2[abc]3[cd]ef"   ->  "abcabccdcdcdef"
 *   "abc"             ->  "abc"              no brackets at all
 *   "10[a]"           ->  "aaaaaaaaaa"       multi-digit count
 *
 * APPROACH  (twin stacks for nested state)
 *   Keep two pieces of "current" state: count being read, and current = text built since the
 *   last '['. Two stacks save the enclosing context when a bracket opens.
 *   1. digit  -> count = count * 10 + digit  (build multi-digit numbers)
 *   2. '['    -> push count and current; reset both (start a fresh inner scope)
 *   3. ']'    -> pop times and the outer text; append current to the outer text `times` times;
 *                that outer text becomes the new current
 *   4. letter -> append to current
 *   5. At the end, current holds the fully decoded string.
 *
 * KEY INSIGHT
 *   '[' is "save and enter", ']' is "restore and merge". Whatever context the outer scope had
 *   (its partial text and its pending repeat count) goes on a stack and comes back exactly
 *   when the inner scope closes. This save/restore-on-bracket model is the same one used by
 *   Basic Calculator and by nested expression evaluators generally.
 *
 * COMPLEXITY
 *   Time  O(n + output length)  each character is read once; appends are proportional to output
 *   Space O(nesting depth + output length)  stacks hold one entry per open bracket
 *
 * INTERVIEW FOLLOW-UPS
 *   - Recursive version: parse(index) returns the decoded substring and the index after ']'
 *   - What if input can be invalid (unmatched brackets)? Where would you detect it?
 *   - Basic Calculator (LC 224) uses the same save/restore on '(' and ')'
 *
 * RUN
 *   main() runs 5 cases (simple, nested, trailing letters, no brackets, multi-digit) and
 *   prints actual vs expected.
 */
import java.util.Stack;

// https://leetcode.com/problems/decode-string/description/
class DecodeString {

    // Walking "abc3[de2[f]]": at each '[' the text so far ("abc") and the count (3) are saved.
    public static String decodeString(String s) {
        Stack<Integer> counts = new Stack<>();          // repeat count pending for each open '['
        Stack<StringBuilder> outerTexts = new Stack<>(); // text built before each open '['
        StringBuilder current = new StringBuilder();    // text built since the last '['
        int count = 0;

        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                count = count * 10 + (c - '0');         // multi-digit counts like 10[a]
            } else if (c == '[') {
                counts.push(count);
                outerTexts.push(current);
                count = 0;
                current = new StringBuilder();          // fresh scope for the bracket body
            } else if (c == ']') {
                int times = counts.pop();
                StringBuilder body = current;
                current = outerTexts.pop();             // restore the enclosing text
                for (int i = 0; i < times; i++) {
                    current.append(body);
                }
            } else {
                current.append(c);
            }
        }
        return current.toString();
    }

    private static void print(String label, String input, String expected) {
        System.out.println(label + ": " + decodeString(input) + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 simple       ", "3[a]2[bc]", "aaabcbc");
        print("case 2 nested       ", "3[a2[c]]", "accaccacc");
        print("case 3 trailing text", "2[abc]3[cd]ef", "abcabccdcdcdef");
        print("case 4 no brackets  ", "abc", "abc");
        print("case 5 multi-digit  ", "10[a]", "aaaaaaaaaa");
    }
}

/*
 * =====================================================================
 *  Exclusive Time of Functions                        LeetCode 636 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   A single-threaded CPU runs n functions (ids 0..n-1). Logs are "id:start:t" or "id:end:t",
 *   in time order. "start:t" means the function began at the START of unit t; "end:t" means it
 *   finished at the END of unit t (so a call with start:2 end:5 ran 4 units). Calls nest like a
 *   call stack and may be recursive. Return each function's exclusive time: the units it ran
 *   itself, excluding time spent in functions it called.
 *
 * EXAMPLE
 *   n=2  [0:start:0, 1:start:2, 1:end:5, 0:end:6]                       ->  [3, 4]
 *        fn 0 runs 0-1 and 6 (3 units), fn 1 runs 2-5 (4 units)
 *   n=1  [0:start:0, 0:start:2, 0:end:5, 0:start:6, 0:end:6, 0:end:7]  ->  [8]   recursion
 *   n=2  [0:start:0, 0:end:0, 1:start:1, 1:end:1]                       ->  [1, 1] 1-unit calls
 *
 * APPROACH  (call-frame stack with time deltas)
 *   Keep a stack of running function ids and prevTime = the first time unit not yet charged.
 *   1. On "start:t": the function on top of the stack ran from prevTime up to (not including) t,
 *      so charge it t - prevTime. Push the new id. prevTime = t.
 *   2. On "end:t": the top function ran from prevTime through t inclusive, so charge it
 *      t - prevTime + 1 and pop. prevTime = t + 1 (unit t is fully used up).
 *   3. The array of charges is the answer.
 *
 * KEY INSIGHT
 *   Every log line is a boundary: whatever is on top of the stack owns the time between the
 *   previous boundary and this one. The only subtlety is the inclusive/exclusive convention:
 *   start is exclusive of t (charge up to t), end is inclusive of t (charge through t, then
 *   move prevTime past it). Getting the "+1" and "prevTime = t + 1" right is the whole problem.
 *
 * COMPLEXITY
 *   Time  O(L)  one pass over L log lines; string split is constant work per line
 *   Space O(n + depth)  the result array plus the call stack at its deepest nesting
 *
 * INTERVIEW FOLLOW-UPS
 *   - Inclusive time instead (time including callees): record start time per frame
 *   - Multi-core: logs per core, or interleaved with a core id, need one stack per core
 *   - What breaks if the logs are not sorted by time? How would you validate them?
 *
 * RUN
 *   main() runs 3 cases (nested calls, recursion, back-to-back 1-unit calls) and prints
 *   actual vs expected.
 */
import java.util.Arrays;
import java.util.List;
import java.util.Stack;

// https://leetcode.com/problems/exclusive-time-of-functions/description/
class ExclusiveTimeOfFunctions {

    public static int[] exclusiveTime(int n, List<String> logs) {
        int[] exclusive = new int[n];
        Stack<Integer> callStack = new Stack<>();   // ids of functions currently running
        int prevTime = 0;                           // first time unit not yet charged to anyone

        for (String log : logs) {
            String[] parts = log.split(":");        // "{id}:{start|end}:{time}"
            int id = Integer.parseInt(parts[0]);
            boolean isStart = parts[1].equals("start");
            int time = Integer.parseInt(parts[2]);

            if (isStart) {
                // The caller (top of stack) ran from prevTime up to, but not including, time.
                if (!callStack.isEmpty()) {
                    exclusive[callStack.peek()] += time - prevTime;
                }
                callStack.push(id);
                prevTime = time;
            } else {
                // "end:t" means it finished at the END of unit t, so unit t itself counts: +1.
                exclusive[callStack.pop()] += time - prevTime + 1;
                prevTime = time + 1;                // unit t is fully consumed
            }
        }
        return exclusive;
    }

    private static void print(String label, int n, List<String> logs, int[] expected) {
        System.out.println(label + ": " + Arrays.toString(exclusiveTime(n, logs))
                + "   expected " + Arrays.toString(expected));
    }

    public static void main(String[] args) {
        print("case 1 nested calls ", 2,
                Arrays.asList("0:start:0", "1:start:2", "1:end:5", "0:end:6"),
                new int[]{3, 4});
        print("case 2 recursion    ", 1,
                Arrays.asList("0:start:0", "0:start:2", "0:end:5",
                              "0:start:6", "0:end:6", "0:end:7"),
                new int[]{8});
        print("case 3 1-unit calls ", 2,
                Arrays.asList("0:start:0", "0:end:0", "1:start:1", "1:end:1"),
                new int[]{1, 1});
    }
}

/*
 * =====================================================================
 *  Infix to Prefix Conversion                        GfG classic | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Given an infix expression with single-letter/digit operands, the operators
 *   + - * / ^ and parentheses, return the equivalent prefix (Polish) expression.
 *   + - * / are left-associative, ^ is right-associative, precedence ^ > * / > + -.
 *
 * EXAMPLE
 *   (A-B/C)*(A/K-L)  ->  *-A/BC-/AKL
 *   A-B-C            ->  --ABC      because (A-B)-C, not A-(B-C)
 *   A^B^C            ->  ^A^BC      because A^(B^C), right-associative
 *   A                ->  A          single operand, no operators
 *
 * APPROACH  (reverse + shunting-yard to postfix + reverse)
 *   1. Reverse the infix string and swap every '(' with ')'.
 *   2. Run infix-to-postfix (operator stack) on that reversed string.
 *      Because the string is reversed, associativity flips: for + - * / pop
 *      only while the stack top has STRICTLY higher precedence; for ^ pop
 *      while the top has higher OR EQUAL precedence.
 *   3. Reverse the postfix output; that is the prefix expression.
 *
 * KEY INSIGHT
 *   Prefix of E == reverse(postfix(reverse(E) with brackets swapped)).
 *   The only trap is associativity: reversing the input turns a left-assoc
 *   chain into a right-assoc one, so the "pop on equal precedence" rule that
 *   is correct for plain infix-to-postfix gives the wrong tree here.
 *   Trap: popping on equal precedence for all operators turns A-B-C into
 *   -A-BC (= A-(B-C)) instead of --ABC.
 *
 * COMPLEXITY
 *   Time  O(n)  each character is pushed and popped at most once
 *   Space O(n)  operator stack plus output builder
 *
 * INTERVIEW FOLLOW-UPS
 *   - Infix to postfix directly (same loop, pop on <= for left-assoc, < for ^).
 *   - Evaluate the prefix expression (scan right to left with an operand stack).
 *   - Multi-character operands / numbers: tokenize first, then the same algorithm.
 *   - Unary minus: needs a lookahead to distinguish from binary minus.
 *
 * RUN
 *   main() runs 5 cases (typical, left-assoc chain, right-assoc chain, single
 *   operand, mixed precedence) and prints actual vs expected.
 */

import java.util.Stack;

class InfixToPrefix {

    static int precedence(char ch) {
        switch (ch) {
            case '+':
            case '-':
                return 1;
            case '*':
            case '/':
                return 2;
            case '^':
                return 3;
        }
        return -1;
    }

    static boolean isOperator(char c) {
        return c == '+' || c == '-' || c == '*' || c == '/' || c == '^';
    }

    static String reverse(String expression) {
        return new StringBuilder(expression).reverse().toString();
    }

    /** Reverse the string and swap '(' with ')' so brackets still read left-to-right. */
    static String reverseAndSwapBrackets(String infix) {
        char[] chars = reverse(infix).toCharArray();
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == '(') {
                chars[i] = ')';
            } else if (chars[i] == ')') {
                chars[i] = '(';
            }
        }
        return new String(chars);
    }

    static String infixToPrefix(String infix) {
        String reversedInfix = reverseAndSwapBrackets(infix);
        String postfixOfReversed = reversedInfixToPostfix(reversedInfix);
        return reverse(postfixOfReversed);
    }

    /**
     * Shunting-yard on an already-reversed expression.
     * Reversal flips associativity, so the pop rule is the mirror of the usual one:
     *   + - * /  (left-assoc originally)  -> pop only while top is strictly higher
     *   ^        (right-assoc originally) -> pop while top is higher or equal
     */
    static String reversedInfixToPostfix(String reversedInfix) {
        Stack<Character> operators = new Stack<>();
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < reversedInfix.length(); i++) {
            char c = reversedInfix.charAt(i);

            if (Character.isLetterOrDigit(c)) {
                output.append(c);
            } else if (c == '(') {
                operators.push(c);
            } else if (c == ')') {
                while (!operators.isEmpty() && operators.peek() != '(') {
                    output.append(operators.pop());
                }
                operators.pop(); // discard the matching '('
            } else if (isOperator(c)) {
                while (!operators.isEmpty() && shouldPopBefore(c, operators.peek())) {
                    output.append(operators.pop());
                }
                operators.push(c);
            }
        }

        while (!operators.isEmpty()) {
            output.append(operators.pop());
        }
        return output.toString();
    }

    /** Pop rule for the reversed expression (see method comment above). */
    static boolean shouldPopBefore(char incoming, char top) {
        if (incoming == '^') {
            return precedence(incoming) <= precedence(top);
        }
        return precedence(incoming) < precedence(top);
    }

    static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 typical       ", infixToPrefix("(A-B/C)*(A/K-L)"), "*-A/BC-/AKL");
        print("case 2 left-assoc    ", infixToPrefix("A-B-C"), "--ABC");
        print("case 3 right-assoc   ", infixToPrefix("A^B^C"), "^A^BC");
        print("case 4 single operand", infixToPrefix("A"), "A");
        print("case 5 mixed prec    ", infixToPrefix("A+B*C-D"), "-+A*BCD");
    }
}

/*
 * =====================================================================
 *  Longest Valid Parentheses                    LeetCode 32 | Hard   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Given a string of only '(' and ')', return the length of the longest
 *   contiguous substring that is a well-formed parentheses sequence.
 *   The string can be empty and can start with unmatched ')' characters.
 *
 * EXAMPLE
 *   ")()())"   ->  4   substring "()()"
 *   "(()"      ->  2   substring "()"
 *   ")(()()))" ->  6   substring "(()())"
 *   ""         ->  0 "()(()"    ->  2   two separate valid pieces, neither joins the other
 *
 * APPROACH  (index stack with a -1 sentinel)
 *   1. Push -1 as the "index of the last unmatched ')'" so the first valid
 *      run has something to measure from and pop never sees an empty stack.
 *   2. On '(' push its index.
 *   3. On ')' pop. If the stack is now empty this ')' is unmatched: push its
 *      index as the new base. Otherwise the valid run ends here and started
 *      just after stack.peek(), so its length is i - stack.peek().
 *
 * APPROACH  (two-pass left/right counter, O(1) space)
 *   1. Scan left to right counting '(' and ')'. When equal, a valid run of
 *      length 2*right just ended. When right > left the run is broken: reset.
 *   2. This misses runs like "(()" where left stays ahead, so repeat right to
 *      left with the roles swapped (reset when left > right).
 *
 * KEY INSIGHT
 *   Store INDICES, not characters. The stack top after a pop is the index of
 *   the last character that is NOT part of the current valid run, so
 *   i - stack.peek() is the run length. The -1 sentinel makes the first run
 *   measure correctly. This "distance from the element below" arithmetic is
 *   the same trick Largest Rectangle in Histogram uses for width.
 *
 * COMPLEXITY
 *   Time  O(n)  each index pushed and popped at most once; the counter does two scans
 *   Space O(n)  for the stack; O(1) for the two-pass counter
 *
 * INTERVIEW FOLLOW-UPS
 *   - Do it in O(1) space (the two-pass counter shown here).
 *   - DP version: dp[i] = length of valid run ending at i; dp[i] = dp[i-2]+2 or
 *     dp[i-1] + 2 + dp[i - dp[i-1] - 2].
 *   - Return the substring itself, not just the length.
 *   - Multiple bracket types: the counter trick no longer works; use the stack.
 *
 * RUN
 *   main() runs 5 cases through both methods and prints actual vs expected.
 */

import java.util.Stack;

class ImportantLongestValidParentheses {

    /** Index stack with -1 sentinel. */
    public static int longestValidParenthesesUsingStack(String s) {
        Stack<Integer> lastUnmatched = new Stack<>();
        lastUnmatched.push(-1); // sentinel: base for the first valid run; guards pop() on ")))"
        int maxLen = 0;

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                lastUnmatched.push(i);
            } else {
                lastUnmatched.pop(); // matches a '(' or consumes the current base
                if (lastUnmatched.isEmpty()) {
                    lastUnmatched.push(i); // this ')' is unmatched: new base
                } else {
                    maxLen = Math.max(maxLen, i - lastUnmatched.peek());
                }
            }
        }
        return maxLen;
    }

    /** Two-pass counter, O(1) extra space. */
    public static int longestValidParentheses(String s) {
        int max = 0;

        // Left to right: catches runs where ')' never outruns '('.
        int left = 0, right = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') left++; else right++;
            if (left == right) {
                max = Math.max(max, 2 * right);
            } else if (right > left) {
                left = right = 0; // run broken by an unmatched ')'
            }
        }

        // Right to left: catches runs like "(()" where '(' stays ahead.
        left = right = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            if (s.charAt(i) == '(') left++; else right++;
            if (left == right) {
                max = Math.max(max, 2 * left);
            } else if (left > right) {
                left = right = 0; // run broken by an unmatched '('
            }
        }
        return max;
    }

    static void print(String label, String s, int expected) {
        System.out.println(label + " \"" + s + "\": stack=" + longestValidParenthesesUsingStack(s)
                + " counter=" + longestValidParentheses(s) + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 typical ", ")()())", 4);
        print("case 2 open end", "(()", 2);
        print("case 3 nested  ", ")(()()))", 6);
        print("case 4 empty   ", "", 0);
        print("case 5 split   ", "()(()", 2);
    }
}

/*
 * =====================================================================
 *  Number of Visible People in a Queue          LeetCode 1944 | Hard
 * =====================================================================
 *
 * PROBLEM
 *   People stand in a queue facing right; heights[i] is the height of person i and all heights
 *   are distinct. Person i can see person j (i < j) when everyone strictly between them is
 *   shorter than both of them. Return answer[i] = how many people person i can see to the right.
 *
 * EXAMPLE
 *   [10, 6, 8, 5, 11, 9]  ->  [3, 1, 2, 1, 1, 0]   person 0 sees 6, 8 and 11; 11 blocks 9
 *   [2, 3, 4, 5, 11, 12]  ->  [1, 1, 1, 1, 1, 0]   each person only sees the next (taller) one
 *   [5, 4, 3, 2, 1]       ->  [1, 1, 1, 1, 0]      each sees exactly the next (shorter) one
 *   [7]                   ->  [0]
 *
 * APPROACH  (monotonic decreasing stack, right to left, count the pops)
 *   1. Walk from the right end. The stack holds heights of people to the right of i that are
 *      still "visible from somewhere"; they decrease from bottom to top.
 *   2. While the top is shorter than heights[i], pop it and count it: person i sees them, and
 *      nobody further left will ever see them again because i is taller and stands in front.
 *   3. If the stack is not empty after popping, the top is taller than i: i can see that one
 *      person too (nothing between them is taller than i), so add 1 more. Stop there.
 *   4. Push heights[i].
 *
 * KEY INSIGHT
 *   Person i sees every shorter person up to and including the first taller one. The popped
 *   count is the "shorter" part; the +1 is the "first taller" part. The stack stays strictly
 *   decreasing, so each person is popped once, and the same stack answers everybody.
 *
 * COMPLEXITY
 *   Time  O(n)  each height is pushed once and popped at most once
 *   Space O(n)  the stack, worst case on strictly increasing input
 *
 * INTERVIEW FOLLOW-UPS
 *   - What changes if heights can repeat? Define whether equal heights block the view and
 *     switch the pop condition between < and <= accordingly.
 *   - Return WHO each person sees (store indices instead of heights and collect the pops).
 *   - Same shape as Daily Temperatures and Next Greater Element, only the bookkeeping differs.
 *
 * RUN
 *   main() runs 4 cases (typical, increasing, decreasing, single) and prints actual vs expected.
 */

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

class VisiblePeopleInQueue {

    public static int[] canSeePersonsCount(int[] heights) {
        int n = heights.length;
        int[] result = new int[n];
        // Heights to the right of i that are still visible; strictly decreasing from bottom to top.
        Deque<Integer> tallerToTheRight = new ArrayDeque<>();

        for (int i = n - 1; i >= 0; i--) {
            // Every shorter person on top is visible to i and blocked from everyone left of i.
            // Heights are distinct, so <= and < behave the same here.
            while (!tallerToTheRight.isEmpty() && tallerToTheRight.peek() <= heights[i]) {
                tallerToTheRight.pop();
                result[i]++;
            }
            // The first taller person is still visible; nobody taller than i stands in between.
            if (!tallerToTheRight.isEmpty()) {
                result[i]++;
            }
            tallerToTheRight.push(heights[i]);
        }
        return result;
    }

    private static void print(String label, int[] actual, int[] expected) {
        System.out.println(label + ": " + Arrays.toString(actual)
                + "   expected " + Arrays.toString(expected));
    }

    public static void main(String[] args) {
        print("case 1 typical    ", canSeePersonsCount(new int[]{10, 6, 8, 5, 11, 9}),
                new int[]{3, 1, 2, 1, 1, 0});
        print("case 2 increasing ", canSeePersonsCount(new int[]{2, 3, 4, 5, 11, 12}),
                new int[]{1, 1, 1, 1, 1, 0});
        print("case 3 decreasing ", canSeePersonsCount(new int[]{5, 4, 3, 2, 1}),
                new int[]{1, 1, 1, 1, 0});
        print("case 4 single     ", canSeePersonsCount(new int[]{7}),
                new int[]{0});
    }
}

/*
 * =====================================================================
 *  Sliding Window Maximum                     LeetCode 239 | Hard   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Given an integer array and a window size k, return the maximum of every
 *   contiguous window of size k as the window slides one step at a time from
 *   left to right. Output length is n - k + 1. Values may be negative.
 *
 * EXAMPLE
 *   [1, 3, -1, -3, 5, 3, 6, 7], k = 3  ->  [3, 3, 5, 5, 6, 7]
 *   [9, 8, 7, 6], k = 2                ->  [9, 8, 7]   front keeps expiring
 *   [4, 4, 4], k = 2                   ->  [4, 4]      equal values
 *   [1], k = 1                         ->  [1]
 *   [2, 5, 1], k = 3                   ->  [5]         window is the whole array
 *
 * APPROACH  (monotonic decreasing deque of indices)
 *   1. Keep a deque of INDICES whose values are decreasing from front to back.
 *      The front is always the index of the current window's maximum.
 *   2. For each i: evict the front if its index has left the window
 *      (index < i - k + 1). At most one can expire per step.
 *   3. Pop from the back every index whose value is smaller than nums[i];
 *      they can never be a maximum again while nums[i] is in the window.
 *   4. Push i at the back. Once i >= k - 1, record nums[front] as the answer.
 *
 * KEY INSIGHT
 *   A smaller element to the LEFT of a bigger one is dead: it leaves the window
 *   first and is never the max while the bigger one lives. So only a decreasing
 *   run of candidates matters. The deque is a monotonic stack (pop from back)
 *   plus one extra operation the stack lacks: expiry from the front by index.
 *   Storing indices instead of values is what makes expiry possible.
 *
 * COMPLEXITY
 *   Time  O(n)  each index enters and leaves the deque at most once
 *   Space O(k)  the deque never holds more than one window's worth of indices
 *
 * INTERVIEW FOLLOW-UPS
 *   - Sliding window minimum: same code with the comparison flipped.
 *   - Heap solution O(n log k) with lazy deletion; why the deque beats it.
 *   - Two-stack queue with a max (the A-tier QueueUsingStacks with running max).
 *   - Shortest subarray with sum at least K (LC 862): same deque on prefix sums.
 *
 * RUN
 *   main() runs 5 cases (typical, decreasing, all equal, single, k == n)
 *   and prints actual vs expected.
 */

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

class ImportantSlidingWindowMaximum {

    public static int[] maxSlidingWindow(int[] nums, int k) {
        if (nums == null || k <= 0 || k > nums.length) return new int[0];
        int n = nums.length;
        int[] result = new int[n - k + 1];
        Deque<Integer> candidates = new ArrayDeque<>(); // indices; values decreasing front to back

        for (int i = 0; i < n; i++) {
            // front has slid out of the window [i-k+1, i]
            if (!candidates.isEmpty() && candidates.peekFirst() < i - k + 1) {
                candidates.pollFirst();
            }
            // anything smaller than nums[i] to its left can never be a max again
            while (!candidates.isEmpty() && nums[candidates.peekLast()] < nums[i]) {
                candidates.pollLast();
            }
            candidates.offerLast(i);

            if (i >= k - 1) {
                result[i - k + 1] = nums[candidates.peekFirst()];
            }
        }
        return result;
    }

    static void print(String label, int[] nums, int k, int[] expected) {
        System.out.println(label + " " + Arrays.toString(nums) + " k=" + k + ": "
                + Arrays.toString(maxSlidingWindow(nums, k))
                + "   expected " + Arrays.toString(expected));
    }

    public static void main(String[] args) {
        print("case 1 typical   ", new int[]{1, 3, -1, -3, 5, 3, 6, 7}, 3,
                new int[]{3, 3, 5, 5, 6, 7});
        print("case 2 decreasing", new int[]{9, 8, 7, 6}, 2, new int[]{9, 8, 7});
        print("case 3 all equal ", new int[]{4, 4, 4}, 2, new int[]{4, 4});
        print("case 4 single    ", new int[]{1}, 1, new int[]{1});
        print("case 5 k == n    ", new int[]{2, 5, 1}, 3, new int[]{5});
    }
}

/*
 * =====================================================================
 *  Basic Calculator                                LeetCode 224 | Hard   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Evaluate a string expression made of non-negative integers, '+', '-', '(', ')' and
 *   spaces. No '*' or '/', but parentheses nest to any depth and a '-' may appear right
 *   after '(' (unary minus). Every intermediate value fits in a signed 32-bit int.
 *
 * EXAMPLE
 *   "1 + 1"                  ->  2
 *   " 2-1 + 2 "              ->  3
 *   "(1+(4+5+2)-3)+(6+8)"    ->  23
 *   "-(2+3)"                 ->  -5    unary minus in front of a group
 *   "2-(5-6)"                ->  3     the sign before '(' must flip everything inside
 *   "42"                     ->  42    single number, no operators
 *
 * APPROACH  (sign and result stack parsing)
 *   1. Walk the string once keeping three variables: num (digits being built),
 *      sign (+1/-1 that applies to num) and result (sum so far at this nesting level).
 *   2. Digit: num = num * 10 + digit.
 *   3. '+' or '-': fold the finished number into result (result += sign * num),
 *      then record the new sign and reset num.
 *   4. '(': push result and sign (the enclosing context), then start a fresh
 *      result = 0, sign = +1 for the inner expression.
 *   5. ')': fold the last number, then pop sign and result of the outer level:
 *      result = outerResult + outerSign * innerResult.
 *   6. After the loop fold the trailing number once more.
 *
 * KEY INSIGHT
 *   A '(' does not need recursion: it only needs to remember two things, the outer
 *   running total and the sign that was waiting to be applied. Push both, compute
 *   the inside as if it were a brand-new expression, then apply the saved sign to
 *   the whole inner value on ')'. This is the save/restore pattern from DecodeString
 *   with the operand handling from RPN; the sign stack replaces operator precedence
 *   because '+' and '-' have equal precedence and are left-associative.
 *
 * COMPLEXITY
 *   Time  O(n)  every character is visited once; each push has one matching pop
 *   Space O(n)  the stack grows with nesting depth, worst case all '(' characters
 *
 * INTERVIEW FOLLOW-UPS
 *   - Basic Calculator II (LC 227): add '*' and '/' without parentheses; keep a stack
 *     of signed operands and multiply/divide against the top before pushing.
 *   - Basic Calculator III (LC 772): both operators and parentheses; recurse on '('
 *     or run this stack idea on top of the LC 227 operand stack.
 *   - How would you handle unary minus after '(' ? Already works here: sign=-1 with
 *     num=0 folds to 0, then the real number picks up the -1.
 *   - Why two pushes per '(' instead of an object? Same cost; the pop order (sign
 *     first, then result) is the only thing to get right.
 *
 * RUN
 *   main() runs 6 cases (typical, spaces, nested, unary minus, sign flip,
 *   single number) and prints actual vs expected.
 */
import java.util.Stack;

class BasicCalculator {

    public static int calculate(String s) {
        Stack<Integer> stack = new Stack<>(); // saved (result, sign) pairs of enclosing levels
        int num = 0;                          // number currently being read digit by digit
        int sign = 1;                         // sign that applies to num: +1 or -1
        int result = 0;                       // running total of the current nesting level

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);

            if (Character.isDigit(ch)) {
                num = num * 10 + (ch - '0');
            } else if (ch == '+') {
                // the sign was recorded before this number was built, so apply it now
                result += sign * num;
                sign = 1;
                num = 0;
            } else if (ch == '-') {
                result += sign * num;
                sign = -1;
                num = 0;
            } else if (ch == '(') {
                // save the outer context, then evaluate the inside as a fresh expression
                stack.push(result);
                stack.push(sign);
                result = 0;
                sign = 1;
            } else if (ch == ')') {
                result += sign * num; // fold the last number of the inner expression
                num = 0;
                result *= stack.pop(); // sign that was waiting in front of the '('
                result += stack.pop(); // outer running total before the '('
            }
            // spaces are skipped
        }

        // the last number has no operator after it to trigger the fold
        result += sign * num;
        return result;
    }

    private static void print(String label, String expr, int expected) {
        System.out.println(label + ": " + calculate(expr) + "   expected " + expected
                + "   (" + expr + ")");
    }

    public static void main(String[] args) {
        print("case 1 typical      ", "1 + 1", 2);
        print("case 2 spaces       ", " 2-1 + 2 ", 3);
        print("case 3 nested       ", "(1+(4+5+2)-3)+(6+8)", 23);
        print("case 4 unary minus  ", "-(2+3)", -5);
        print("case 5 sign flip    ", "2-(5-6)", 3);
        print("case 6 single number", "42", 42);
    }
}

/*
 * =====================================================================
 *  Robot Collisions                                    LeetCode 2751 | Hard
 * =====================================================================
 *
 * PROBLEM
 *   Robot i sits at positions[i] (all distinct) with healths[i] and moves 'L' or 'R' at equal
 *   speed. When two collide, the lower-health one is removed and the survivor loses 1 health;
 *   equal health removes both. Return the healths of the survivors in ORIGINAL input order.
 *
 * EXAMPLE
 *   pos [5,4,3,2,1] hp [2,17,9,15,10] "RRRRR"  ->  [2, 17, 9, 15, 10]   same direction, no hits
 *   pos [3,5,2,6]   hp [10,10,15,12]  "RLRL"   ->  [14]  by position: 2R15 3R10 5L10 6L12
 *                                     5L ties 3R (both die); 6L (12) loses to 2R (15) -> 14
 *   pos [1,2,5,6]   hp [10,10,11,11]  "RLRL"   ->  []    two equal-health pairs, all die
 *
 * APPROACH  (collision simulation with state and reindexing)
 *   1. Wrap each robot as {originalIndex, position, health, direction}.
 *   2. Sort robots by position so "to the left" means "earlier in the loop".
 *   3. Scan left to right with a stack (ArrayList used as one):
 *        'R' robot -> push, it cannot hit anything already seen.
 *        'L' robot -> while top is 'R' and this robot is alive:
 *            equal health   -> pop top, this robot's health = 0
 *            top weaker     -> pop top, this robot loses 1
 *            top stronger   -> top loses 1, this robot's health = 0
 *          push this robot only if it is still alive.
 *   4. Sort survivors back by originalIndex and collect their healths.
 *
 * KEY INSIGHT
 *   This is Asteroid Collision with two extras: mutable state (health decrements instead of
 *   binary win/lose) and a transform step (sort by position first, restore original order at
 *   the end). Recognise "positions given out of order" as a cue to sort, then reuse the
 *   push-or-fight loop unchanged.
 *
 * COMPLEXITY
 *   Time  O(n log n)  two sorts; the collision loop itself is O(n) (each robot pushed/popped once)
 *   Space O(n)        robot objects plus the stack
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why can a right-mover never collide with something already on the stack?
 *   - How would you return the survivors' final positions instead of healths?
 *   - Asteroid Collision (LC 735) is the same loop without health or reindexing
 *
 * RUN
 *   main() runs 3 cases (no collisions, chained fights, everyone dies) and prints
 *   actual vs expected.
 */
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

// https://leetcode.com/problems/robot-collisions/description/
class RobotCollisions {

    static class Robot {
        final int index;      // original input index, used to restore output order
        final int position;
        int health;
        final char direction;

        Robot(int index, int position, int health, char direction) {
            this.index = index;
            this.position = position;
            this.health = health;
            this.direction = direction;
        }
    }

    public static List<Integer> survivedRobotsHealths(int[] positions, int[] healths,
                                                      String directions) {
        int n = positions.length;
        Robot[] robots = new Robot[n];
        for (int i = 0; i < n; i++) {
            robots[i] = new Robot(i, positions[i], healths[i], directions.charAt(i));
        }
        // Sort by position so the scan order matches the physical left-to-right order.
        Arrays.sort(robots, Comparator.comparingInt(r -> r.position));

        List<Robot> stack = new ArrayList<>();   // survivors so far; last element is the top
        for (Robot robot : robots) {
            if (robot.direction == 'R') {
                stack.add(robot);                // nothing to its left can ever catch it
                continue;
            }
            // Left-mover: fight every right-mover on top of the stack until dead or clear.
            while (!stack.isEmpty() && top(stack).direction == 'R' && robot.health > 0) {
                Robot rightRobot = top(stack);
                if (rightRobot.health == robot.health) {
                    stack.remove(stack.size() - 1);   // both die
                    robot.health = 0;
                } else if (rightRobot.health < robot.health) {
                    stack.remove(stack.size() - 1);   // right robot dies, this one pays 1 health
                    robot.health -= 1;
                } else {
                    rightRobot.health -= 1;           // right robot survives with 1 less health
                    robot.health = 0;
                }
            }
            if (robot.health > 0) {
                stack.add(robot);
            }
        }

        // Survivors are in position order; the answer wants original index order.
        stack.sort(Comparator.comparingInt(r -> r.index));
        List<Integer> result = new ArrayList<>();
        for (Robot r : stack) {
            result.add(r.health);
        }
        return result;
    }

    private static Robot top(List<Robot> stack) {
        return stack.get(stack.size() - 1);
    }

    private static void print(String label, int[] positions, int[] healths, String directions,
                              List<Integer> expected) {
        System.out.println(label + ": " + survivedRobotsHealths(positions, healths, directions)
                + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 no collisions ", new int[]{5, 4, 3, 2, 1}, new int[]{2, 17, 9, 15, 10},
                "RRRRR", Arrays.asList(2, 17, 9, 15, 10));
        print("case 2 chained fights", new int[]{3, 5, 2, 6}, new int[]{10, 10, 15, 12}, "RLRL",
                Arrays.asList(14));
        print("case 3 everyone dies ", new int[]{1, 2, 5, 6}, new int[]{10, 10, 11, 11}, "RLRL",
                Arrays.asList());
    }
}

