/*
 * =====================================================================
 *  Kth Largest Element in a Stream           LeetCode 703 | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Design a class that is constructed with an integer k and an initial array nums.
 *   Each call to add(val) appends val to the stream and returns the kth largest element
 *   seen so far (kth largest in sorted order, so duplicates count separately).
 *   1 <= k <= 10^4, up to 10^4 calls to add, and there are at least k elements whenever
 *   add() is asked for an answer.
 *
 * EXAMPLE
 *   k = 3, nums = [4, 5, 8, 2]
 *     add(3)  -> 4     stream {2,3,4,5,8}, 3rd largest is 4
 *     add(5)  -> 5     stream {2,3,4,5,5,8}
 *     add(10) -> 5 add(9)  -> 8
 *     add(4)  -> 8
 *   k = 1, nums = []  (edge: empty start)
 *     add(-3) -> -3, add(-2) -> -2, add(-4) -> -2, add(1) -> 1
 *
 * APPROACH  (bounded size-k min-heap)
 *   1. Keep a min-heap that never holds more than k elements: the k largest so far.
 *   2. On add(val): if the heap has fewer than k elements, just offer val.
 *      Otherwise, if val is bigger than the root (the smallest of the k largest),
 *      poll the root and offer val; if val is not bigger, it cannot be in the top k.
 *   3. The root of the heap is always the kth largest. Return peek().
 *
 * KEY INSIGHT
 *   "Kth largest" == "smallest of the k largest". A min-heap capped at size k makes that
 *   smallest element sit at the root for free. Every top-K / kth-largest / k-closest
 *   problem in this folder is this one idea with a different comparator.
 *
 * COMPLEXITY
 *   Time  O(log k) per add          one poll + one offer on a heap of size k
 *   Space O(k)                      the heap never grows past k
 *
 * INTERVIEW FOLLOW-UPS
 *   - Kth smallest instead: flip to a max-heap of size k.
 *   - Whole array is given up front (LC 215): quickselect gives O(n) average.
 *   - Why not a sorted list? Insert is O(n); the heap keeps only what matters.
 *   - What if k > number of elements? Problem guarantees it will not happen; heap.peek()
 *     would return the smallest seen so far, which is not a valid answer.
 *
 * RUN
 *   main() runs 3 cases (typical, empty-start with negatives, all-equal) and prints
 *   actual vs expected.
 */
import java.util.Arrays;
import java.util.PriorityQueue;

// https://leetcode.com/problems/kth-largest-element-in-a-stream/
class KthLargestElementInAStream {
    private final PriorityQueue<Integer> minHeap;   // holds the k largest seen; root = kth largest
    private final int k;

    // Fixed: this used to be a plain method named KthLargest(...) that mimicked a constructor,
    // so callers had to do "new X(); x.KthLargest(k, nums)". It is now a real constructor.
    public KthLargestElementInAStream(int k, int[] nums) {
        this.k = k;
        this.minHeap = new PriorityQueue<>(k);
        for (int num : nums) {
            add(num);
        }
    }

    public int add(int val) {
        if (minHeap.size() < k) {
            minHeap.offer(val);                 // still filling the top-k window
        } else if (val > minHeap.peek()) {
            minHeap.poll();                     // evict the smallest of the current top k
            minHeap.offer(val);                 // val takes its place
        }
        // else: val is <= the current kth largest, so it can never be in the top k
        return minHeap.peek();
    }

    // Replays a sequence of add() calls and collects each returned kth largest.
    private static int[] replay(int k, int[] initial, int[] adds) {
        KthLargestElementInAStream stream = new KthLargestElementInAStream(k, initial);
        int[] answers = new int[adds.length];
        for (int i = 0; i < adds.length; i++) {
            answers[i] = stream.add(adds[i]);
        }
        return answers;
    }

    private static void print(String label, int[] actual, int[] expected) {
        System.out.println(label + ": " + Arrays.toString(actual)
                + "   expected " + Arrays.toString(expected));
    }

    public static void main(String[] args) {
        // typical: LeetCode example 1
        print("case 1 (k=3, start [4,5,8,2], add 3,5,10,9,4)",
                replay(3, new int[]{4, 5, 8, 2}, new int[]{3, 5, 10, 9, 4}),
                new int[]{4, 5, 5, 8, 8});

        // edge: empty initial array, negatives, k = 1 (so answer is simply the max so far)
        print("case 2 (k=1, start [], add -3,-2,-4,1)",
                replay(1, new int[]{}, new int[]{-3, -2, -4, 1}),
                new int[]{-3, -2, -2, 1});

        // tricky: duplicates count separately; all-equal stream
        print("case 3 (k=2, start [7,7,7], add 7,8,8)",
                replay(2, new int[]{7, 7, 7}, new int[]{7, 8, 8}),
                new int[]{7, 7, 8});
    }
}

/*
 * =====================================================================
 *  Last Stone Weight                                  LeetCode 1046 | Easy
 * =====================================================================
 *
 * PROBLEM
 *   stones[i] is the weight of the ith stone. Each turn take the two heaviest stones
 *   x <= y and smash them: if x == y both vanish, otherwise y becomes y - x and x vanishes.
 *   Return the weight of the last stone left, or 0 if none remain.
 *   1 <= stones.length <= 30, 1 <= stones[i] <= 1000.
 *
 * EXAMPLE
 *   [2, 7, 4, 1, 8, 1] -> 1    8&7 -> 1; 4&2 -> 2; 2&1 -> 1; 1&1 -> 0; left [1]
 *   [1]                -> 1    nothing to smash
 *   [2, 2]             -> 0    equal stones destroy each other
 *   [10, 4, 4]         -> 2    10&4 -> 6; 6&4 -> 2
 *
 * APPROACH  (max-heap simulation loop)
 *   1. Put every stone into a max-heap (PriorityQueue with Collections.reverseOrder()).
 *   2. While at least two stones remain: poll the two largest.
 *      If they differ, push back the difference; if equal, push nothing.
 *   3. When the loop ends the heap holds 0 or 1 stones: return that stone or 0.
 *
 * KEY INSIGHT
 *   The rule "always act on the two largest" is exactly what a max-heap serves in O(log n).
 *   Recognise the shape "poll two, push one back" -- it recurs in Huffman coding and
 *   Reorganize String. Java has no max-heap class; reverseOrder() on a min-heap is it.
 *
 * COMPLEXITY
 *   Time  O(n log n)   each smash removes at least one stone, each heap op is O(log n)
 *   Space O(n)         the heap
 *
 * INTERVIEW FOLLOW-UPS
 *   - Weights bounded by 1000: counting-sort / bucket approach gives O(n + maxWeight).
 *   - Last Stone Weight II (LC 1049): pick ANY two stones -> becomes subset-sum DP, not greedy.
 *   - Why is the answer at most one stone? Every turn removes at least one stone.
 *
 * RUN
 *   main() runs 4 cases (typical, single stone, equal pair, empty) and prints
 *   actual vs expected.
 */
import java.util.Collections;
import java.util.PriorityQueue;

// https://leetcode.com/problems/last-stone-weight/
class LastStoneWeight {
    public static int lastStoneWeight(int[] stones) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        for (int stone : stones) {
            maxHeap.add(stone);
        }
        while (maxHeap.size() > 1) {
            int heaviest = maxHeap.poll();
            int secondHeaviest = maxHeap.poll();
            if (heaviest != secondHeaviest) {
                maxHeap.add(heaviest - secondHeaviest);   // the survivor goes back in
            }
        }
        return maxHeap.isEmpty() ? 0 : maxHeap.poll();
    }

    public static void main(String[] args) {
        System.out.println("case 1: " + lastStoneWeight(new int[]{2, 7, 4, 1, 8, 1})
                + "   expected 1");
        System.out.println("case 2: " + lastStoneWeight(new int[]{1}) + "   expected 1");
        System.out.println("case 3: " + lastStoneWeight(new int[]{2, 2}) + "   expected 0");
        System.out.println("case 4: " + lastStoneWeight(new int[]{}) + "   expected 0");
    }
}

/*
 * =====================================================================
 *  Top K Frequent Elements                        LeetCode 347 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Given an integer array nums and an integer k, return the k most frequent elements.
 *   The answer is guaranteed unique and may be returned in any order.
 *   1 <= nums.length <= 10^5, k is between 1 and the number of distinct values.
 *   Follow-up on the problem itself: must be better than O(n log n).
 *
 * EXAMPLE
 *   nums = [1, 1, 1, 2, 2, 3], k = 2   ->  [1, 2]     counts 1:3, 2:2, 3:1
 *   nums = [1], k = 1                  ->  [1]        single element
 *   nums = [4, 1, -1, 2, -1, 2, 3], k = 2  ->  [-1, 2] (any order)  both appear twice
 *
 * APPROACH  (frequency map + size-k min-heap)
 *   1. Count each value in a HashMap<value, count>.
 *   2. Walk the map entries and offer each into a min-heap ordered by count.
 *      Whenever the heap grows past k, poll: the least frequent entry so far falls out.
 *   3. What remains are the k most frequent. Poll them into the result array from the
 *      back so the array ends up most-frequent first (nice, not required).
 *
 *   Second method topKFrequentBucket (the O(n) follow-up):
 *   1. Count as before. 2. bucket[c] = list of values with count c (c <= n).
 *   3. Walk buckets from n down to 1 collecting values until k are gathered.
 *
 * KEY INSIGHT
 *   Same primitive as Kth Largest in a Stream, just keyed on a computed frequency rather
 *   than the value itself. A min-heap bounded to k gives O(n log k), which beats sorting
 *   all m distinct entries when k << m. Buckets go further: counts are bounded by n, so
 *   they can be sorted in O(n) with no comparisons at all.
 *
 * COMPLEXITY
 *   Heap    Time O(n log k)   n to count, each of m <= n entries costs O(log k)
 *           Space O(m + k)    the map plus the heap
 *   Bucket  Time O(n)         count, distribute into n+1 buckets, scan down once
 *           Space O(n)        the map plus the buckets
 *
 * INTERVIEW FOLLOW-UPS
 *   - "Better than O(n log n)?" -> bucket sort on counts, O(n).
 *   - Top k frequent words (LC 692): ties broken alphabetically, so the comparator must
 *     order by count then reversed word; a heap handles that, buckets need sorting.
 *   - Stream of values with a fixed k: keep the map and heap alive and update per element.
 *   - Quickselect on the distinct entries by count: O(m) average, in place.
 *
 * RUN
 *   main() runs 3 cases through both methods and prints actual vs expected.
 *   Results are sorted before printing because the problem allows any order.
 */
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;

// https://leetcode.com/problems/top-k-frequent-elements/
class TopKFrequent {

    // Approach 1: frequency map + min-heap bounded to size k.  O(n log k)
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> countOf = new HashMap<>();
        for (int num : nums) {
            countOf.merge(num, 1, Integer::sum);
        }

        // min-heap on count: the root is the least frequent of the k kept so far
        PriorityQueue<Map.Entry<Integer, Integer>> minHeap =
                new PriorityQueue<>((a, b) -> Integer.compare(a.getValue(), b.getValue()));

        for (Map.Entry<Integer, Integer> entry : countOf.entrySet()) {
            minHeap.offer(entry);
            if (minHeap.size() > k) {
                minHeap.poll();                 // drop the least frequent, keep exactly k
            }
        }

        int[] result = new int[k];
        for (int i = k - 1; i >= 0; i--) {      // fill from the back: most frequent ends up first
            result[i] = minHeap.poll().getKey();
        }
        return result;
    }

    // Approach 2: bucket sort on counts.  O(n) -- answers the "better than n log n" follow-up.
    public int[] topKFrequentBucket(int[] nums, int k) {
        Map<Integer, Integer> countOf = new HashMap<>();
        for (int num : nums) {
            countOf.merge(num, 1, Integer::sum);
        }

        // bucket[c] holds every value that occurs exactly c times; c can be at most nums.length
        List<List<Integer>> bucket = new ArrayList<>();
        for (int c = 0; c <= nums.length; c++) {
            bucket.add(new ArrayList<>());
        }
        for (Map.Entry<Integer, Integer> entry : countOf.entrySet()) {
            bucket.get(entry.getValue()).add(entry.getKey());
        }

        int[] result = new int[k];
        int filled = 0;
        for (int c = nums.length; c >= 1 && filled < k; c--) {   // highest count first
            for (int value : bucket.get(c)) {
                if (filled == k) break;
                result[filled++] = value;
            }
        }
        return result;
    }

    // The problem accepts any order, so sort before comparing against the expected array.
    private static int[] sorted(int[] arr) {
        int[] copy = arr.clone();
        Arrays.sort(copy);
        return copy;
    }

    private static void print(String label, int[] actual, int[] expected) {
        System.out.println(label + ": " + Arrays.toString(sorted(actual))
                + "   expected " + Arrays.toString(sorted(expected)));
    }

    public static void main(String[] args) {
        TopKFrequent sol = new TopKFrequent();

        int[][] inputs = {
                {1, 1, 1, 2, 2, 3},          // typical
                {1},                         // edge: single element, k == distinct count
                {4, 1, -1, 2, -1, 2, 3},     // tricky: negatives, tie between -1 and 2
        };
        int[] ks = {2, 1, 2};
        int[][] expected = {{1, 2}, {1}, {-1, 2}};

        for (int i = 0; i < inputs.length; i++) {
            String label = "case " + (i + 1) + " nums=" + Arrays.toString(inputs[i])
                    + " k=" + ks[i];
            print(label + " heap  ", sol.topKFrequent(inputs[i], ks[i]), expected[i]);
            print(label + " bucket", sol.topKFrequentBucket(inputs[i], ks[i]), expected[i]);
        }
    }
}

/*
 * =====================================================================
 *  K Closest Points to Origin                     LeetCode 973 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Given points[i] = [xi, yi] on the plane and an integer k, return the k points closest
 *   to the origin (0, 0) by Euclidean distance. The answer is unique and may be returned
 *   in any order. 1 <= k <= points.length <= 10^4, coordinates in [-10^4, 10^4].
 *
 * EXAMPLE
 *   points = [[1,3], [-2,2]], k = 1            ->  [[-2,2]]        dist^2 10 vs 8
 *   points = [[3,3], [5,-1], [-2,4]], k = 2    ->  [[3,3], [-2,4]] dist^2 18, 26, 20
 *   points = [[1,3], [-2,2], [5,8], [0,1]], k = 4  ->  all four   k == n, nothing evicted
 *
 * APPROACH  (size-k max-heap on a computed key)
 *   1. Compare points by squared distance x*x + y*y; the square root is monotonic so it is
 *      never needed and we stay in exact integer arithmetic.
 *   2. Keep a MAX-heap of at most k points: its root is the farthest of the k closest so far.
 *   3. Offer every point; when the size exceeds k, poll the root (the farthest one out).
 *   4. Whatever remains is the answer; drain the heap into a k x 2 array.
 *
 * KEY INSIGHT
 *   "K closest" is "k smallest by distance", so the heap direction flips: a max-heap evicts
 *   the worst survivor. The comparator is written over a derived value (distance), not the
 *   element itself -- that is the pattern to spot: decide the key, then decide which end of
 *   the heap must hold the element you are willing to throw away.
 *
 * COMPLEXITY
 *   Time  O(n log k)   each of n points costs one heap op on a heap of size <= k
 *   Space O(k)         the heap (plus the k x 2 result)
 *
 * INTERVIEW FOLLOW-UPS
 *   - O(n) average: quickselect on squared distance (partition until the pivot lands at k).
 *   - Points arrive as a stream: the heap version already works incrementally.
 *   - k close to n: sorting all points, O(n log n), is simpler and about as fast.
 *   - Why squared distance? Avoids sqrt and floating point; coordinates <= 10^4 keep the
 *     squares within int (2 * 10^8).
 *
 * RUN
 *   main() runs 3 cases (typical k=1, typical k=2, k == n) and prints actual vs expected.
 *   Output rows are sorted before printing because the problem allows any order.
 */
import java.util.Arrays;
import java.util.PriorityQueue;

// https://leetcode.com/problems/k-closest-points-to-origin/
class KClosestPointsToOrigin {

    private static int distSq(int[] p) {
        return p[0] * p[0] + p[1] * p[1];
    }

    public static int[][] kClosest(int[][] points, int k) {
        // max-heap by squared distance: root = the farthest of the k closest kept so far
        PriorityQueue<int[]> maxHeap =
                new PriorityQueue<>((a, b) -> Integer.compare(distSq(b), distSq(a)));

        for (int[] point : points) {
            maxHeap.offer(point);
            if (maxHeap.size() > k) {
                maxHeap.poll();                 // evict the farthest survivor
            }
        }

        int[][] result = new int[k][];
        for (int i = 0; i < k; i++) {
            result[i] = maxHeap.poll();
        }
        return result;
    }

    // Any order is accepted, so sort rows (by distance, then x, then y) before comparing.
    private static int[][] sortedRows(int[][] rows) {
        int[][] copy = rows.clone();
        Arrays.sort(copy, (a, b) -> {
            if (distSq(a) != distSq(b)) return Integer.compare(distSq(a), distSq(b));
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        return copy;
    }

    private static void print(String label, int[][] actual, int[][] expected) {
        System.out.println(label + ": " + Arrays.deepToString(sortedRows(actual))
                + "   expected " + Arrays.deepToString(sortedRows(expected)));
    }

    public static void main(String[] args) {
        // typical: LeetCode example 1
        print("case 1 (k=1)",
                kClosest(new int[][]{{1, 3}, {-2, 2}}, 1),
                new int[][]{{-2, 2}});

        // typical: LeetCode example 2, negatives in both axes
        print("case 2 (k=2)",
                kClosest(new int[][]{{3, 3}, {5, -1}, {-2, 4}}, 2),
                new int[][]{{3, 3}, {-2, 4}});

        // edge: k == n, nothing is ever evicted
        print("case 3 (k=n)",
                kClosest(new int[][]{{1, 3}, {-2, 2}, {5, 8}, {0, 1}}, 4),
                new int[][]{{0, 1}, {-2, 2}, {1, 3}, {5, 8}});
    }
}

/*
 * =====================================================================
 *  Huffman Coding                              Classic greedy (GfG) | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Given a set of characters and their frequencies, build a prefix-free binary code
 *   (no code is a prefix of another) that minimises the total encoded length
 *   sum(freq[c] * len(code[c])). Then encode a string with it and decode it back.
 *
 * EXAMPLE
 *   chars = a b c d e f, freq = 5 9 12 13 16 45
 *     codes: f=0 c=100 d=101 e=111 a=1100 b=1101, total = 224 bits
 *     (fixed 3-bit codes would cost 100 * 3 = 300 bits)
 *   chars = a, freq = 3                    edge: one symbol, code "1", "aaa" -> "111"
 *   chars = a b c d, freq = 1 1 1 1        tricky: all tied, every code is 2 bits, total 8
 *
 * APPROACH  (merge-two-smallest greedy tree build)
 *   1. Put every character in a min-heap of Nodes ordered by frequency.
 *   2. While more than one node remains: poll the two smallest, create a parent whose
 *      frequency is their sum (left = smaller, right = larger), push the parent back.
 *   3. The last node is the root. Walk the tree: going left appends '0', right appends '1';
 *      the path to each leaf is that character's code. A lone root leaf gets code "1".
 *   4. Encode: concatenate each character's code. Decode: walk from the root one bit at a
 *      time, emit the character at each leaf and restart at the root.
 *
 *   Fixed: decoding crashed (NullPointerException) when the alphabet has a single symbol,
 *   because the root itself is the leaf and has no children to walk into. Also removed a
 *   duplicate copy of the tree-building loop; encode and decode now share buildTree().
 *
 * KEY INSIGHT
 *   The two rarest symbols should be the deepest leaves, and merging them makes a pseudo-
 *   symbol that is treated exactly like any other -- so the greedy is just "poll two,
 *   push one" on a heap, the Last Stone Weight loop with tree nodes instead of ints.
 *   The same shape solves Minimum Cost to Connect Ropes / Merge Files (LC 1167).
 *
 * COMPLEXITY
 *   Time  O(m log m)   m symbols, m - 1 merges, each two polls and one offer
 *   Space O(m)         the heap and the tree (2m - 1 nodes); codes are O(m * depth)
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why is it optimal? Exchange argument: swapping a rare symbol deeper never hurts.
 *   - Prefix-free property: every symbol is a leaf, so no code is a prefix of another.
 *   - Ties give different trees but the same total cost; decoder must use the SAME tree.
 *   - Connect Ropes / Merge Stones with a heap: identical loop, just sum the costs.
 *
 * RUN
 *   main() runs 3 cases (classic six symbols, single symbol, all-tied frequencies)
 *   and prints codes, total bits and the encode/decode round trip vs expected.
 */
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.TreeMap;

// Node of the Huffman tree: a leaf holds a character; an internal node holds the merged frequency.
class Node {
    char ch;
    int freq;
    Node left, right;

    Node(char ch, int freq) {
        this(ch, freq, null, null);
    }

    Node(char ch, int freq, Node left, Node right) {
        this.ch = ch;
        this.freq = freq;
        this.left = left;
        this.right = right;
    }

    boolean isLeaf() {
        return left == null && right == null;
    }
}

class HuffmanCoding {

    // Greedy build: repeatedly merge the two least frequent nodes until one root remains.
    public static Node buildTree(char[] characters, int[] frequencies) {
        if (characters.length == 0) return null;
        PriorityQueue<Node> minHeap =
                new PriorityQueue<>((l, r) -> Integer.compare(l.freq, r.freq));
        for (int i = 0; i < characters.length; i++) {
            minHeap.add(new Node(characters[i], frequencies[i]));
        }
        while (minHeap.size() > 1) {
            Node left = minHeap.poll();          // smallest
            Node right = minHeap.poll();         // second smallest
            minHeap.add(new Node('\0', left.freq + right.freq, left, right));  // pseudo-symbol
        }
        return minHeap.peek();
    }

    // Root-to-leaf paths become the codes: '0' for left, '1' for right.
    private static void collectCodes(Node node, String path, Map<Character, String> codeOf) {
        if (node == null) return;
        if (node.isLeaf()) {
            codeOf.put(node.ch, path.isEmpty() ? "1" : path);   // lone root leaf still needs 1 bit
            return;
        }
        collectCodes(node.left, path + '0', codeOf);
        collectCodes(node.right, path + '1', codeOf);
    }

    public static Map<Character, String> getEncodedHuffmanMap(Node root) {
        Map<Character, String> codeOf = new HashMap<>();
        collectCodes(root, "", codeOf);
        return codeOf;
    }

    public static String encode(String text, Map<Character, String> codeOf) {
        StringBuilder bits = new StringBuilder();
        for (char ch : text.toCharArray()) {
            bits.append(codeOf.get(ch));
        }
        return bits.toString();
    }

    // Walk the tree bit by bit; every time a leaf is reached emit its character and restart.
    public static String decode(Node root, String bits) {
        StringBuilder text = new StringBuilder();
        if (root == null) return "";
        if (root.isLeaf()) {                      // single-symbol alphabet: each bit is one symbol
            for (int i = 0; i < bits.length(); i++) text.append(root.ch);
            return text.toString();
        }
        Node current = root;
        for (char bit : bits.toCharArray()) {
            current = (bit == '0') ? current.left : current.right;
            if (current.isLeaf()) {
                text.append(current.ch);
                current = root;
            }
        }
        return text.toString();
    }

    // sum(freq * codeLength): the quantity Huffman minimises.
    private static int totalBits(char[] characters, int[] frequencies,
                                 Map<Character, String> codeOf) {
        int total = 0;
        for (int i = 0; i < characters.length; i++) {
            total += frequencies[i] * codeOf.get(characters[i]).length();
        }
        return total;
    }

    private static void runCase(String label, char[] chars, int[] freqs, String text,
                                int expectedTotalBits, String expectedCodes) {
        Node root = buildTree(chars, freqs);
        Map<Character, String> codeOf = getEncodedHuffmanMap(root);
        String encoded = encode(text, codeOf);
        String decoded = decode(root, encoded);

        System.out.println(label);
        if (expectedCodes != null) {
            System.out.println("  codes      : " + new TreeMap<>(codeOf)
                    + "   expected " + expectedCodes);
        }
        System.out.println("  total bits : " + totalBits(chars, freqs, codeOf)
                + "   expected " + expectedTotalBits);
        System.out.println("  encoded    : " + encoded + " (" + encoded.length() + " bits)");
        System.out.println("  round trip : " + decoded + "   expected " + text);
    }

    public static void main(String[] args) {
        // typical: the textbook example, no ties so the codes are fully determined
        runCase("case 1 (a..f, freq 5 9 12 13 16 45)",
                new char[]{'a', 'b', 'c', 'd', 'e', 'f'}, new int[]{5, 9, 12, 13, 16, 45},
                "abcdef", 224, "{a=1100, b=1101, c=100, d=101, e=111, f=0}");

        // edge: single symbol -> root is a leaf; used to NPE in decode
        runCase("case 2 (single symbol a)",
                new char[]{'a'}, new int[]{3},
                "aaa", 3, "{a=1}");

        // tricky: all frequencies tied -> tree shape depends on heap tie-breaks, but every
        // code has length 2 and the total is fixed, so only the totals are asserted
        runCase("case 3 (a b c d all freq 1)",
                new char[]{'a', 'b', 'c', 'd'}, new int[]{1, 1, 1, 1},
                "abcdabcd", 8, null);
    }
}

/*
 * =====================================================================
 *  Reorganize String                                 LeetCode 767 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Given a string s, rearrange its characters so that no two adjacent characters
 *   are equal. Return any valid arrangement, or "" if none exists.
 *   1 <= s.length <= 500, lowercase letters only.
 *
 * EXAMPLE
 *   s = "aab"    ->  "aba" s = "aaab"   ->  ""       'a' appears 3 times; length 4 allows at most 2
 *   s = "vvvlo"  ->  "vlvov"  (any other valid order is also accepted)
 *   s = "a"      ->  "a"      a single character is trivially valid
 *
 * APPROACH  (frequency max-heap, dual poll)
 *   1. Count every character into a map.
 *   2. Push each (char, count) entry into a max-heap ordered by count.
 *   3. Feasibility check: if the top count > (n + 1) / 2, no arrangement exists.
 *   4. While the heap holds at least two entries, poll the two most frequent
 *      characters, append both, decrement their counts, and push back any entry
 *      whose count is still > 0.
 *   5. If one entry is left, step 3 guarantees its count is 1; append it.
 *
 * KEY INSIGHT
 *   Always placing the two most frequent remaining characters next to each other
 *   stops the most frequent one from ever being forced beside itself. Because a
 *   character polled this round cannot be polled again until the next round, it
 *   gets a "cooldown" of exactly one slot, which is the no-adjacent-repeat rule.
 *   Pattern: "spread out the heavy hitters" == max-heap on frequency plus a
 *   cooldown. Task Scheduler (LC 621) is the same shape.
 *
 * COMPLEXITY
 *   Time  O(n log k)  n characters, k distinct chars (k <= 26, so effectively O(n))
 *   Space O(k)        the frequency map and the heap
 *
 * INTERVIEW FOLLOW-UPS
 *   - Rearrange String k Distance Apart (LC 358): poll k entries per round instead of 2.
 *   - Task Scheduler (LC 621): same heap, but idle slots are inserted when cooldown fails.
 *   - Without a heap: fill even indices with the most frequent char, then odd indices.
 *
 * RUN
 *   main() runs 4 cases and prints the result, whether it is a valid arrangement,
 *   and the expected outcome. Ties in the heap mean the exact string may differ
 *   between runs, so validity is what is checked.
 */

import java.util.AbstractMap;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

class ReorganizeString {

    public static String reorganizeString(String s) {
        if (s == null || s.length() <= 1) {
            return s;
        }
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : s.toCharArray()) {
            freq.put(c, freq.getOrDefault(c, 0) + 1);
        }

        // max-heap: the most frequent character sits on top
        PriorityQueue<Map.Entry<Character, Integer>> maxHeap =
                new PriorityQueue<>((a, b) -> b.getValue() - a.getValue());
        maxHeap.addAll(freq.entrySet());

        // more than half the slots (rounded up) for one char -> two of them must touch
        if (maxHeap.peek().getValue() > (s.length() + 1) / 2) {
            return "";
        }

        StringBuilder result = new StringBuilder();
        while (maxHeap.size() > 1) {
            Map.Entry<Character, Integer> first = maxHeap.poll();
            Map.Entry<Character, Integer> second = maxHeap.poll();
            result.append(first.getKey()).append(second.getKey());
            offerIfRemaining(maxHeap, first);
            offerIfRemaining(maxHeap, second);
        }
        // at most one entry remains, and the feasibility check guarantees its count is 1
        if (!maxHeap.isEmpty()) {
            result.append(maxHeap.poll().getKey());
        }
        return result.toString();
    }

    /** Push the entry back with one fewer occurrence, unless it is used up. */
    private static void offerIfRemaining(PriorityQueue<Map.Entry<Character, Integer>> heap,
                                         Map.Entry<Character, Integer> used) {
        if (used.getValue() > 1) {
            heap.offer(new AbstractMap.SimpleEntry<>(used.getKey(), used.getValue() - 1));
        }
    }

    /** True when result is a permutation of original with no two equal neighbours. */
    private static boolean isValidArrangement(String original, String result) {
        if (result.length() != original.length()) {
            return false;
        }
        char[] a = original.toCharArray();
        char[] b = result.toCharArray();
        Arrays.sort(a);
        Arrays.sort(b);
        if (!Arrays.equals(a, b)) {
            return false;
        }
        for (int i = 1; i < result.length(); i++) {
            if (result.charAt(i) == result.charAt(i - 1)) {
                return false;
            }
        }
        return true;
    }

    private static void print(String label, String input, boolean expectPossible) {
        String actual = reorganizeString(input);
        String verdict;
        if (actual.isEmpty()) {
            verdict = "impossible";
        } else {
            verdict = isValidArrangement(input, actual) ? "valid" : "INVALID";
        }
        String expected = expectPossible ? "valid" : "impossible";
        System.out.println(label + ": \"" + input + "\" -> \"" + actual + "\" (" + verdict + ")"
                + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 typical", "aab", true);
        print("case 2 impossible", "aaab", false);
        print("case 3 tricky", "vvvlo", true);
        print("case 4 single char", "a", true);
    }
}

/*
 * =====================================================================
 *  Maximum Average Pass Ratio                        LeetCode 1792 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   classes[i] = [pass, total]. You have extraStudents brilliant students who will
 *   pass any class you put them in. Assign all of them so that the average of
 *   pass/total across all classes is as large as possible. Answers within 1e-5
 *   of the true value are accepted.
 *
 * EXAMPLE
 *   classes = [[1,2],[3,5],[2,2]], extra = 2  ->  0.78333
 *     both extras go to [1,2]:  (3/4 + 3/5 + 2/2) / 3
 *   classes = [[2,4],[3,9],[4,5],[2,10]], extra = 4  ->  0.53485
 *   classes = [[2,2],[1,1]], extra = 3  ->  1.00000   full classes cannot improve
 *   classes = [[1,4]], extra = 0  ->  0.25000          nothing to assign
 *
 * APPROACH  (max-heap keyed by marginal gain)
 *   1. For each class compute gain = (pass+1)/(total+1) - pass/total: how much the
 *      ratio improves if one more passing student joins.
 *   2. Put every class in a max-heap ordered by that gain.
 *   3. For each extra student: poll the class with the largest gain, add the
 *      student (pass++, total++), and re-offer it. Its gain is now smaller, so it
 *      sinks and another class may come to the top.
 *   4. Sum pass/total over all classes and divide by the number of classes.
 *
 * KEY INSIGHT
 *   For one class, each added student gives a smaller gain than the previous one
 *   (diminishing returns), so taking the single best marginal gain each time is
 *   globally optimal. The heap key CHANGES after each pick, so the item has to
 *   leave and re-enter: poll, mutate, re-offer. Never mutate an object's sort key
 *   while it is still inside a PriorityQueue; the heap will silently go stale.
 *
 * COMPLEXITY
 *   Time  O((n + extra) log n)  n initial offers, then extra poll/offer pairs
 *   Space O(n)                  one heap entry per class
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why not the class with the lowest ratio? [1,10] gains 0.082, [1,2] gains 0.167.
 *   - Store gain as a field so the comparator does not recompute two divisions per compare.
 *   - n and extra both up to 1e5: this is fine; anything O(n * extra) times out.
 *
 * RUN
 *   main() runs 4 cases and prints actual vs expected to 5 decimals.
 */

import java.util.PriorityQueue;

class MaximumAveragePassRatio {

    /** One class: how many pass, how many total, and the gain from one more passing student. */
    private static class ClassInfo {
        int pass;
        int total;

        ClassInfo(int pass, int total) {
            this.pass = pass;
            this.total = total;
        }

        // (pass+1)/(total+1) - pass/total : improvement from adding one passing student
        double gain() {
            return ((double) (pass + 1) / (total + 1)) - ((double) pass / total);
        }
    }

    public static double maxAverageRatio(int[][] classes, int extraStudents) {
        // max-heap by marginal gain
        PriorityQueue<ClassInfo> byGain = new PriorityQueue<>(
                (c1, c2) -> Double.compare(c2.gain(), c1.gain())
        );
        for (int[] cl : classes) {
            byGain.offer(new ClassInfo(cl[0], cl[1]));
        }

        // hand out students one at a time, always to the class that improves most
        for (int i = 0; i < extraStudents; i++) {
            ClassInfo best = byGain.poll();
            best.pass++;
            best.total++;
            byGain.offer(best); // its gain shrank, so it must be re-positioned
        }

        double sum = 0.0;
        for (ClassInfo ci : byGain) {
            sum += (double) ci.pass / ci.total;
        }
        return sum / classes.length;
    }

    private static void print(String label, int[][] classes, int extra, String expected) {
        double actual = maxAverageRatio(classes, extra);
        System.out.println(label + ": " + String.format("%.5f", actual)
                + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 typical", new int[][]{{1, 2}, {3, 5}, {2, 2}}, 2, "0.78333");
        print("case 2 typical", new int[][]{{2, 4}, {3, 9}, {4, 5}, {2, 10}}, 4, "0.53485");
        print("case 3 all full", new int[][]{{2, 2}, {1, 1}}, 3, "1.00000");
        print("case 4 no extras", new int[][]{{1, 4}}, 0, "0.25000");
    }
}

/*
 * =====================================================================
 *  Maximum Number of Events That Can Be Attended     LeetCode 1353 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   events[i] = [startDay, endDay], both inclusive. You can attend at most one
 *   event per day, on any day d with start <= d <= end. Return the maximum number
 *   of events you can attend. Up to 1e5 events, day values up to 1e5.
 *
 * EXAMPLE
 *   [[1,2],[2,3],[3,4]]              ->  3   day 1, day 2, day 3
 *   [[1,4],[4,4],[2,2],[3,4],[1,1]]  ->  4   d1 [1,1], d2 [2,2], d3 [1,4], d4 [4,4]
 *   [[1,1],[1,1],[1,1]]              ->  1   all three collide on the only day
 *   [[7,7]]                          ->  1   single event
 *
 * APPROACH  (sort by start, min-heap on end day)
 *   1. Sort events by start day.
 *   2. Walk a day counter. If no event is currently open, jump the counter
 *      forward to the next event's start day (never backwards).
 *   3. Push the end day of every event that has started by the current day.
 *   4. Pop end days that are already in the past (end < day): those expired.
 *   5. Attend the open event that ends soonest (heap top), count it, next day.
 *   6. Stop when every event has been pushed and the heap is empty.
 *
 * KEY INSIGHT
 *   On any given day, among the events you could still attend, the one that
 *   expires first is the one you lose if you do not take it now; every other
 *   choice can wait. This is "earliest deadline first", and a min-heap on end
 *   day answers "which expires first" in O(log n). Sort by start so that events
 *   become available in order; heap by end so you pick the most urgent one.
 *
 * COMPLEXITY
 *   Time  O(n log n)  sort, plus each event enters and leaves the heap once
 *   Space O(n)        the heap
 *
 * INTERVIEW FOLLOW-UPS
 *   - Events carry a value and you may attend k (LC 1751): greedy breaks, use DP + binary search.
 *   - Day values up to 1e9: still fine, the counter jumps over empty gaps instead of iterating.
 *   - Why not iterate days 1..maxDay? Works for 1e5 but wastes time on gaps; the jump fixes it.
 *
 * RUN
 *   main() runs 4 cases and prints actual vs expected.
 */

import java.util.Arrays;
import java.util.PriorityQueue;

class MaximumNumberofEventsThatCanBeAttended {

    public static int maxEvents(int[][] events) {
        Arrays.sort(events, (a, b) -> Integer.compare(a[0], b[0]));
        PriorityQueue<Integer> openEndDays = new PriorityQueue<>(); // min-heap on end day
        int n = events.length;
        int next = 0;      // index of the next event not yet pushed
        int day = 0;
        int attended = 0;

        while (next < n || !openEndDays.isEmpty()) {
            if (openEndDays.isEmpty()) {
                // nothing open today: skip straight to the next event's start day
                day = Math.max(day, events[next][0]);
            }
            // open every event that has started by today
            while (next < n && events[next][0] <= day) {
                openEndDays.offer(events[next][1]);
                next++;
            }
            // drop events whose last day has already passed
            while (!openEndDays.isEmpty() && openEndDays.peek() < day) {
                openEndDays.poll();
            }
            // attend the open event that ends soonest, then move to the next day
            if (!openEndDays.isEmpty()) {
                openEndDays.poll();
                attended++;
                day++;
            }
        }
        return attended;
    }

    private static void print(String label, int[][] events, int expected) {
        System.out.println(label + ": " + maxEvents(events) + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 typical", new int[][]{{1, 2}, {2, 3}, {3, 4}}, 3);
        print("case 2 tricky", new int[][]{{1, 4}, {4, 4}, {2, 2}, {3, 4}, {1, 1}}, 4);
        print("case 3 all collide", new int[][]{{1, 1}, {1, 1}, {1, 1}}, 1);
        print("case 4 single event", new int[][]{{7, 7}}, 1);
    }
}

/*
 * =====================================================================
 *  Furthest Building You Can Reach                   LeetCode 1642 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   heights[i] is the height of building i. Moving to a lower or equal building
 *   is free. Moving up by diff costs either diff bricks or exactly one ladder
 *   (a ladder covers any height). Given bricks and ladders, return the furthest
 *   0-based index you can reach.
 *
 * EXAMPLE
 *   [4,2,7,6,9,14,12], bricks 5, ladders 1     ->  4   climbs 5,3,5: ladder + 5 bricks cover
 *                                                      two of them, the third 5 is unpaid
 *   [4,12,2,7,3,18,20,3,19], bricks 10, ladders 2 ->  7
 *   [14,3,19,3], bricks 17, ladders 0           ->  3   bricks alone cover the climb of 16
 *   [1,5,1,2,3,4,10000], bricks 0, ladders 5    ->  6   five ladders for five climbs
 *   [5], bricks 0, ladders 0                    ->  0   single building, nothing to climb
 *
 * APPROACH  (regret heap of size = ladders)  -- laddersFirstMinHeap
 *   1. For each upward step diff, tentatively spend a ladder: push diff into a min-heap.
 *   2. If the heap now holds more climbs than there are ladders, the smallest held
 *      climb is the cheapest one to downgrade: pop it and pay it with bricks.
 *   3. If bricks go negative, this step is unaffordable: return the current index.
 *   4. If the loop finishes, every building was reached: return n - 1.
 *
 * ALTERNATIVE  (bricks first, max-heap)  -- bricksFirstMaxHeap
 *   Pay every climb with bricks and record it in a max-heap. When bricks run
 *   short, spend a ladder on the LARGEST brick-paid climb so far (refunding its
 *   bricks) if that climb is bigger than the current one; otherwise use the
 *   ladder on the current climb directly. Same answer, more branches.
 *
 * KEY INSIGHT
 *   You cannot know up front which climbs deserve a ladder, so make a tentative
 *   choice and take it back later ("regret" greedy). A min-heap capped at
 *   `ladders` entries always holds exactly the L largest climbs seen so far, and
 *   everything that falls out is what bricks must cover. Ladders on the biggest
 *   climbs, bricks on the smallest, is provably optimal.
 *
 * COMPLEXITY
 *   Time  O(n log L)  L = ladders; one heap operation per climb (approach 1)
 *   Space O(L)        approach 1 never holds more than L + 1 entries; approach 2 is O(n)
 *
 * INTERVIEW FOLLOW-UPS
 *   - ladders = 0: the heap immediately pops every push, degrading to plain brick accounting.
 *   - Binary search on the answer ("can I reach index m?") is the fallback if you do not see
 *     the greedy: sort the first m climbs, ladder the largest L, brick the rest. O(n log^2 n).
 *   - Minimum Number of Refueling Stops (LC 871) uses the same retroactive-greedy idea.
 *
 * RUN
 *   main() runs 5 cases through both methods and prints actual vs expected.
 */

import java.util.Collections;
import java.util.PriorityQueue;

class FurthestBuildingYouCanReach {

    /**
     * Approach 1: ladders first, min-heap.
     * Every climb is first assigned a ladder. When we hold more climbs than ladders,
     * the smallest held climb is the cheapest one to pay with bricks instead.
     */
    public static int laddersFirstMinHeap(int[] heights, int bricks, int ladders) {
        PriorityQueue<Integer> ladderedClimbs = new PriorityQueue<>(); // min-heap
        int n = heights.length;

        for (int i = 0; i < n - 1; i++) {
            int diff = heights[i + 1] - heights[i];
            if (diff <= 0) {
                continue; // downhill or flat: free
            }
            ladderedClimbs.offer(diff);
            // one ladder too many: downgrade the smallest laddered climb to bricks
            if (ladderedClimbs.size() > ladders) {
                bricks -= ladderedClimbs.poll();
            }
            if (bricks < 0) {
                return i; // cannot afford this step, stop on building i
            }
        }
        return n - 1;
    }

    /**
     * Approach 2: bricks first, max-heap.
     * Pay every climb with bricks while they last. When bricks fall short, spend a ladder,
     * but put it on the LARGEST brick-paid climb so far (refunding those bricks) if that
     * climb is bigger than the current one; otherwise use the ladder on the current climb.
     */
    public static int bricksFirstMaxHeap(int[] heights, int bricks, int ladders) {
        PriorityQueue<Integer> brickedClimbs = new PriorityQueue<>(Collections.reverseOrder());
        int n = heights.length;
        int i;
        for (i = 0; i < n - 1; i++) {
            int diff = heights[i + 1] - heights[i];
            if (diff <= 0) {
                continue; // downhill or flat: free
            }
            if (bricks >= diff) {
                bricks -= diff;
                brickedClimbs.offer(diff);
            } else if (ladders > 0) {
                if (!brickedClimbs.isEmpty() && brickedClimbs.peek() > diff) {
                    // move the ladder onto the biggest bricked climb; bricks then cover this one
                    int biggest = brickedClimbs.poll();
                    bricks += biggest - diff;
                    brickedClimbs.offer(diff);
                }
                // else: the ladder goes on the current climb
                ladders--;
            } else {
                break; // no resources left; i is the furthest building
            }
        }
        return i;
    }

    private static void print(String label, int[] heights, int bricks, int ladders, int expected) {
        System.out.println(label + " (bricks=" + bricks + ", ladders=" + ladders + ")");
        int viaLadders = laddersFirstMinHeap(heights, bricks, ladders);
        int viaBricks = bricksFirstMaxHeap(heights, bricks, ladders);
        System.out.println("  laddersFirstMinHeap: " + viaLadders + "   expected " + expected);
        System.out.println("  bricksFirstMaxHeap : " + viaBricks + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 typical", new int[]{4, 2, 7, 6, 9, 14, 12}, 5, 1, 4);
        print("case 2 typical", new int[]{4, 12, 2, 7, 3, 18, 20, 3, 19}, 10, 2, 7);
        print("case 3 no ladders", new int[]{14, 3, 19, 3}, 17, 0, 3);
        print("case 4 ladders only", new int[]{1, 5, 1, 2, 3, 4, 10000}, 0, 5, 6);
        print("case 5 single building", new int[]{5}, 0, 0, 0);
    }
}

/*
 * =====================================================================
 *  Find Median from Data Stream                 LeetCode 295 | Hard   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Design a structure that accepts integers one at a time (addNum) and can
 *   return the median of everything seen so far (findMedian) at any moment.
 *   Up to 5e4 calls, so findMedian must not re-sort the data.
 *
 * EXAMPLE
 *   add 1, add 2        ->  findMedian = 1.5
 *   add 3               ->  findMedian = 2.0
 *   add 5, 15, 1, 3     ->  median after each add: 5.0, 10.0, 5.0, 4.0
 *   add -2, -2, -2      ->  median after each add: -2.0, -2.0, -2.0
 *
 * APPROACH  (two balanced heaps)
 *   1. lower = max-heap holding the smaller half; upper = min-heap holding the larger half.
 *   2. addNum: if lower is empty or num < lower.top, it belongs in the lower half,
 *      otherwise in the upper half.
 *   3. Rebalance so that lower.size is equal to upper.size or one more:
 *      lower two bigger -> move lower.top to upper; upper bigger -> move upper.top to lower.
 *   4. findMedian: equal sizes -> average of both tops; otherwise lower.top.
 *
 * KEY INSIGHT
 *   The median only depends on the boundary between the lower and upper halves,
 *   and a heap gives O(1) access to exactly one boundary element. Two heaps
 *   facing each other (max-heap below, min-heap above) keep BOTH boundary
 *   elements on top. The invariant to recite: every element of lower <= every
 *   element of upper, and the sizes differ by at most one, with lower allowed
 *   to be the larger. Insert into the natural side, then fix sizes.
 *
 * COMPLEXITY
 *   Time  O(log n) per addNum (at most two heap operations), O(1) per findMedian
 *   Space O(n)     every element lives in one of the two heaps
 *
 * INTERVIEW FOLLOW-UPS
 *   - All numbers in [0, 100]: a counting array of 101 buckets makes addNum O(1).
 *   - 99% of numbers in [0, 100]: buckets for the middle, two heaps for the outliers.
 *   - Sliding Window Median (LC 480): same two heaps plus lazy deletion of departing values.
 *   - Why not a sorted list? Insert is O(n). A balanced BST works but is far more code.
 *
 * RUN
 *   main() runs 3 cases (LeetCode example, mixed order, all equal negatives) and
 *   prints the median after each add vs expected.
 */

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.PriorityQueue;

class ImportantMedianOfStream {
    private final PriorityQueue<Integer> lower = new PriorityQueue<>(Collections.reverseOrder());
    private final PriorityQueue<Integer> upper = new PriorityQueue<>();

    public void addNum(int num) {
        // 1. drop it on the side it naturally belongs to
        if (lower.isEmpty() || num < lower.peek()) {
            lower.offer(num);
        } else {
            upper.offer(num);
        }
        // 2. restore the size invariant: lower.size == upper.size or upper.size + 1
        if (lower.size() - upper.size() > 1) {
            upper.offer(lower.poll());
        } else if (lower.size() < upper.size()) {
            lower.offer(upper.poll());
        }
    }

    public double findMedian() {
        if (lower.size() == upper.size()) {
            return (lower.peek() + upper.peek()) / 2.0;
        }
        return lower.peek(); // lower is the larger heap when sizes differ
    }

    /** Feed the numbers in order and collect the median after each one. */
    private static List<Double> mediansAfterEachAdd(int[] nums) {
        ImportantMedianOfStream stream = new ImportantMedianOfStream();
        List<Double> medians = new ArrayList<>();
        for (int n : nums) {
            stream.addNum(n);
            medians.add(stream.findMedian());
        }
        return medians;
    }

    private static void print(String label, int[] nums, String expected) {
        System.out.println(label + ": " + mediansAfterEachAdd(nums) + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 leetcode", new int[]{1, 2, 3}, "[1.0, 1.5, 2.0]");
        print("case 2 mixed order", new int[]{5, 15, 1, 3}, "[5.0, 10.0, 5.0, 4.0]");
        print("case 3 all equal negative", new int[]{-2, -2, -2}, "[-2.0, -2.0, -2.0]");
    }
}

/*
 * =====================================================================
 *  Sliding Window Median                                LeetCode 480 | Hard
 * =====================================================================
 *
 * PROBLEM
 *   Given an int array nums and a window size k, return the median of every
 *   contiguous window of size k, left to right, as doubles. The median of an
 *   even-sized window is the mean of its two middle values. nums[i] can be any
 *   int, including Integer.MAX_VALUE, so the two-value mean must not overflow.
 *
 * EXAMPLE
 *   nums = [1, 3, -1, -3, 5, 3, 6, 7], k = 3  ->  [1, -1, -1, 3, 5, 6]
 *     windows: [1 3 -1] [3 -1 -3] [-1 -3 5] [-3 5 3] [5 3 6] [3 6 7]
 *   nums = [1, 2, 3, 4], k = 4                 ->  [2.5]     one window, even size
 *   nums = [4, 2, 5], k = 1                    ->  [4, 2, 5] every element is its own median
 *   nums = [2147483647, 2147483647], k = 2     ->  [2147483647]  overflow trap
 *
 * APPROACH  (two heaps with window removal)
 *   1. maxHeap ("low") holds the smaller half, minHeap ("high") the larger half.
 *      Invariant: low.size() == high.size() or low.size() == high.size() + 1,
 *      so the median is low.peek() (odd k) or the mean of both roots (even k).
 *   2. For each index i: add nums[i] to low if it is <= low's root, else to high,
 *      then rebalance so the invariant holds.
 *   3. Once i >= k - 1 the window is full: record the median, then remove the
 *      element leaving the window (nums[i - k + 1]) from whichever heap holds
 *      it, and rebalance again because an arbitrary removal can break step 1.
 *   4. Removal uses PriorityQueue.remove(Object), which is O(k): it scans the heap.
 *
 * KEY INSIGHT
 *   The median-of-stream two-heap trick still works with eviction, as long as
 *   every add AND every remove is followed by a rebalance. The invariant, not
 *   the heap contents, is what makes peek() the median. When k is large, swap
 *   the O(k) remove for lazy deletion (a "to delete" count map, purged when the
 *   stale element reaches a root) or two TreeMap multisets for O(log k).
 *
 * COMPLEXITY
 *   Time  O(n * k)    each slide does O(log k) heap ops plus one O(k) remove(Object)
 *   Space O(k)        the two heaps together hold exactly the window
 *
 * INTERVIEW FOLLOW-UPS
 *   - Make removal O(log k): lazy deletion with a HashMap<Integer, Integer> of pending
 *     deletes, or replace the heaps with two TreeMap<Integer, Integer> multisets.
 *   - Why not just sort each window? O(n * k log k) and no reuse between windows.
 *   - Streaming version with no window (LeetCode 295): same heaps, no remove step.
 *   - Sliding window MAX instead of median (LeetCode 239): monotonic deque, O(n).
 *
 * Fixed: (maxHeap.peek() + minHeap.peek()) / 2.0 added the two ints before
 *        widening to double, so a window like [2147483647, 2147483647] overflowed
 *        to a negative median. Now the first root is cast to double before adding.
 *
 * RUN
 *   main() runs 4 cases (typical, single window, k = 1, int overflow) and prints
 *   actual vs expected.
 */

import java.util.Arrays;
import java.util.Collections;
import java.util.PriorityQueue;

class SlidingWindowMedian {

    public static double[] medianSlidingWindow(int[] nums, int k) {
        double[] result = new double[nums.length - k + 1];

        // low: max-heap with the smaller half; high: min-heap with the larger half
        PriorityQueue<Integer> low = new PriorityQueue<>(Collections.reverseOrder());
        PriorityQueue<Integer> high = new PriorityQueue<>();

        for (int i = 0; i < nums.length; i++) {
            add(nums[i], low, high);
            rebalance(low, high);

            if (i >= k - 1) {                     // window [i-k+1 .. i] is full
                result[i - k + 1] = median(low, high);
                remove(nums[i - k + 1], low, high); // evict the element leaving the window
                rebalance(low, high);               // removal can break the size invariant
            }
        }
        return result;
    }

    // Route a new value to the half it belongs to.
    private static void add(int num, PriorityQueue<Integer> low, PriorityQueue<Integer> high) {
        if (low.isEmpty() || num <= low.peek()) {
            low.offer(num);
        } else {
            high.offer(num);
        }
    }

    // Restore: low.size() == high.size() or low.size() == high.size() + 1.
    private static void rebalance(PriorityQueue<Integer> low, PriorityQueue<Integer> high) {
        if (low.size() > high.size() + 1) {
            high.offer(low.poll());
        } else if (high.size() > low.size()) {
            low.offer(high.poll());
        }
    }

    // With the invariant in place the median is at the heap roots.
    private static double median(PriorityQueue<Integer> low, PriorityQueue<Integer> high) {
        if (low.size() > high.size()) {
            return low.peek();
        }
        // cast BEFORE adding: two ints near 2^31 overflow if summed as int
        return ((double) low.peek() + high.peek()) / 2.0;
    }

    // Remove the outgoing element from whichever half holds it. O(k) scan.
    private static void remove(int num, PriorityQueue<Integer> low, PriorityQueue<Integer> high) {
        if (num <= low.peek()) {
            low.remove(num);
        } else {
            high.remove(num);
        }
    }

    private static void print(String label, double[] actual, String expected) {
        System.out.println(label + ": " + Arrays.toString(actual) + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 typical k=3",
                medianSlidingWindow(new int[]{1, 3, -1, -3, 5, 3, 6, 7}, 3),
                "[1.0, -1.0, -1.0, 3.0, 5.0, 6.0]");

        print("case 2 k == n, even",
                medianSlidingWindow(new int[]{1, 2, 3, 4}, 4),
                "[2.5]");

        print("case 3 k == 1",
                medianSlidingWindow(new int[]{4, 2, 5}, 1),
                "[4.0, 2.0, 5.0]");

        print("case 4 int overflow",
                medianSlidingWindow(new int[]{Integer.MAX_VALUE, Integer.MAX_VALUE}, 2),
                "[2.147483647E9]");
    }
}

/*
 * =====================================================================
 *  Minimum Number of Refueling Stops                    LeetCode 871 | Hard
 * =====================================================================
 *
 * PROBLEM
 *   A car starts at position 0 with startFuel litres and must reach position
 *   target. stations[i] = [position, fuel] lists gas stations sorted by position,
 *   all strictly before target; stopping at one adds all of its fuel. One litre
 *   moves the car one mile. Return the minimum number of stops needed to reach
 *   target, or -1 if it is impossible.
 *
 * EXAMPLE
 *   target = 1000, startFuel = 200,
 *   stations = [[200,200],[400,200],[600,200],[800,200]]
 *     -> 4   every hop is exactly 200 miles, so every station must be used
 *   target = 100, startFuel = 10, stations = [[10,60],[20,30],[30,30],[60,40]]
 *     -> 2   stop at [10,60] (fuel 60) and [60,40] (fuel 50), skip the rest
 *   target = 1, startFuel = 1, stations = []            ->  0   no stops needed
 *   target = 100, startFuel = 1, stations = [[10,100]]  -> -1   cannot reach the first station
 *
 * APPROACH  (retroactive greedy with a max-heap)
 *   1. Append a sentinel station [target, 0] so the destination is just one more
 *      hop and the loop needs no special end case.
 *   2. Walk the stations in order. For each, compute dist from the previous
 *      position and check whether the tank covers it.
 *   3. If not, pop the largest fuel amount banked in the heap (a station we
 *      already drove past) and count that as a stop. Repeat until the hop is
 *      covered or the heap runs dry; an empty heap with fuel still short means -1.
 *   4. Drive the hop (fuel -= dist) and bank this station's fuel in the heap
 *      without deciding yet whether we will ever "use" it.
 *
 * KEY INSIGHT
 *   You do not have to decide at a station whether to stop there. Bank every
 *   station you pass, and only when you actually run short do you retroactively
 *   "stop" at the biggest banked one. Because fuel is additive and order of
 *   refuelling does not matter, choosing the largest banked station is always
 *   optimal. Recognise this as the "regret / deferred decision" heap pattern,
 *   the same shape as Furthest Building You Can Reach.
 *
 * COMPLEXITY
 *   Time  O(n log n)  each station is offered once and polled at most once
 *   Space O(n)        the heap plus the copied stations array with the sentinel
 *
 * INTERVIEW FOLLOW-UPS
 *   - Prove the exchange argument: why is "largest banked fuel first" never worse?
 *   - DP alternative: dp[s] = farthest reachable with s stops, O(n^2) time, O(n) space.
 *   - What breaks if stations are not sorted by position? (sort first, then same loop)
 *   - Return the actual stations used, not just the count.
 *
 * RUN
 *   main() runs 4 cases (every station needed, skip some, no stations, unreachable)
 *   and prints actual vs expected.
 */

import java.util.Arrays;
import java.util.Collections;
import java.util.PriorityQueue;

class MinimumRefuelingStops {

    public static int minRefuelStops(int target, int startFuel, int[][] stations) {
        // Fuel amounts of every station already driven past, largest on top.
        PriorityQueue<Integer> bankedFuel = new PriorityQueue<>(Collections.reverseOrder());
        int fuel = startFuel;
        int prevPosition = 0;
        int stops = 0;

        // Sentinel: treat the target as a final station with no fuel.
        int n = stations.length;
        int[][] route = Arrays.copyOf(stations, n + 1);
        route[n] = new int[]{target, 0};

        for (int[] station : route) {
            int dist = station[0] - prevPosition;

            // Short for this hop? Retroactively refuel at the best station we passed.
            while (fuel < dist && !bankedFuel.isEmpty()) {
                fuel += bankedFuel.poll();
                stops++;
            }
            if (fuel < dist) {
                return -1;                    // heap is empty and still short
            }

            fuel -= dist;
            bankedFuel.offer(station[1]);     // bank it; decide later whether it was a stop
            prevPosition = station[0];
        }
        return stops;
    }

    private static void print(String label, int actual, int expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        print("case 1 every station needed",
                minRefuelStops(1000, 200,
                        new int[][]{{200, 200}, {400, 200}, {600, 200}, {800, 200}}),
                4);

        print("case 2 skip some stations",
                minRefuelStops(100, 10, new int[][]{{10, 60}, {20, 30}, {30, 30}, {60, 40}}),
                2);

        print("case 3 no stations, enough fuel",
                minRefuelStops(1, 1, new int[][]{}),
                0);

        print("case 4 unreachable",
                minRefuelStops(100, 1, new int[][]{{10, 100}}),
                -1);
    }
}

