        //                      / \
        //                     2   3
        //                    / \   \
        //                   4   5   6
        TreeNode balanced = new TreeNode(1);
        balanced.left = new TreeNode(2);
        balanced.right = new TreeNode(3);
        balanced.left.left = new TreeNode(4);
        balanced.left.right = new TreeNode(5);
        balanced.right.right = new TreeNode(6);
