        tricky.right.right = new TreeNode(3);
        tricky.left.left.left = new TreeNode(4);
        tricky.right.right.right = new TreeNode(4);
        print("case 4 root heights equal, inner node not", solver.isBalanced(tricky), false);
    }
}

