/*
 * =====================================================================
 *  BFS and DFS traversal of a graph          GFG | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Given V vertices (0..V-1) and an adjacency list, return the order in which
 *   BFS and DFS visit the vertices starting from vertex 0. Neighbours are visited
 *   in the order they appear in the adjacency list. The graph may be disconnected;
 *   the classic GFG version only traverses the component containing 0.
 *
 * EXAMPLE
 *   edges 0-1, 0-4, 1-2, 1-3 (undirected)
 *     BFS from 0 -> [0, 1, 4, 2, 3]   level by level: 0 | 1 4 | 2 3
 *     DFS from 0 -> [0, 1, 2, 3, 4]   go deep along 0->1->2, back up, 3, back up, 4
 *   single vertex, no edges -> BFS [0], DFS [0]
 *   0-1, 2-3 (two components) -> BFS from 0 = [0, 1]; vertices 2, 3 unreachable
 *
 * APPROACH  (BFS queue and DFS recursion)
 *   BFS
 *   1. Mark the start visited and push it on a queue.
 *   2. Pop a vertex, append it to the answer, then for every unvisited neighbour
 *      mark it visited and push it. Marking at push time stops duplicates.
 *   DFS
 *   1. Mark the current vertex visited and append it to the answer.
 *   2. For every neighbour not yet visited, recurse into it.
 *
 * KEY INSIGHT
 *   The only difference between the two is the container: a FIFO queue gives
 *   level order (BFS), the call stack gives depth first (DFS). Every other file
 *   in this folder is one of these two loops with extra state bolted on
 *   (parent, colour, distance, recursion-stack flag).
 *
 * COMPLEXITY
 *   Time  O(V + E)  every vertex is enqueued/visited once, every edge scanned once
 *   Space O(V)      visited array plus queue / recursion depth
 *
 * INTERVIEW FOLLOW-UPS
 *   - How do you cover a disconnected graph? Loop over all vertices, start a
 *     traversal from each one that is still unvisited.
 *   - Iterative DFS: replace recursion with an explicit Stack (avoids stack
 *     overflow on deep graphs).
 *   - Why mark visited when enqueuing, not when dequeuing? Otherwise the same
 *     vertex can sit in the queue several times.
 *
 * RUN
 *   main() runs 3 cases (typical, single vertex, disconnected) and prints
 *   actual vs expected for both traversals.
 */
import java.util.*;

class BFSandDFS {

    /** Breadth-first: vertex 0, then its neighbours, then their neighbours, and so on. */
    public ArrayList<Integer> bfsOfGraph(int V, ArrayList<ArrayList<Integer>> adj) {
        ArrayList<Integer> order = new ArrayList<>();
        boolean[] visited = new boolean[V];
        Queue<Integer> queue = new LinkedList<>();

        queue.add(0);
        visited[0] = true;

        while (!queue.isEmpty()) {
            int u = queue.poll();
            order.add(u);
            for (int v : adj.get(u)) {
                // mark at enqueue time so a vertex never enters the queue twice
                if (!visited[v]) {
                    visited[v] = true;
                    queue.add(v);
                }
            }
        }
        return order;
    }

    /** Depth-first: dive into the first unvisited neighbour before touching the rest. */
    public ArrayList<Integer> dfsOfGraph(int V, ArrayList<ArrayList<Integer>> adj) {
        boolean[] visited = new boolean[V];
        ArrayList<Integer> order = new ArrayList<>();
        dfs(0, visited, adj, order);
        return order;
    }

    private static void dfs(int node, boolean[] visited,
                            ArrayList<ArrayList<Integer>> adj, ArrayList<Integer> order) {
        visited[node] = true;
        order.add(node);
        for (int next : adj.get(node)) {
            if (!visited[next]) {
                dfs(next, visited, adj, order);
            }
        }
    }

    // ---------- test scaffolding ----------

    private static ArrayList<ArrayList<Integer>> undirectedGraph(int V, int[][] edges) {
        ArrayList<ArrayList<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        return adj;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        BFSandDFS g = new BFSandDFS();

        // case 1: typical - 5 vertices, edges 0-1, 0-4, 1-2, 1-3
        ArrayList<ArrayList<Integer>> adj1 = undirectedGraph(5,
                new int[][]{{0, 1}, {0, 4}, {1, 2}, {1, 3}});
        print("case 1 bfs", g.bfsOfGraph(5, adj1), "[0, 1, 4, 2, 3]");
        print("case 1 dfs", g.dfsOfGraph(5, adj1), "[0, 1, 2, 3, 4]");

        // case 2: edge - single vertex, no edges
        ArrayList<ArrayList<Integer>> adj2 = undirectedGraph(1, new int[][]{});
        print("case 2 bfs", g.bfsOfGraph(1, adj2), "[0]");
        print("case 2 dfs", g.dfsOfGraph(1, adj2), "[0]");

        // case 3: tricky - disconnected graph; 2 and 3 are never reached from 0
        ArrayList<ArrayList<Integer>> adj3 = undirectedGraph(4,
                new int[][]{{0, 1}, {2, 3}});
        print("case 3 bfs", g.bfsOfGraph(4, adj3), "[0, 1]");
        print("case 3 dfs", g.dfsOfGraph(4, adj3), "[0, 1]");
    }
}

AAScratches/01-DSA/11-Graphs/A02_CheckFo.text:
/*
 * =====================================================================
 *  Detect Cycle in an Undirected Graph            GFG classic | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Given an undirected graph with V vertices (0..V-1) as an adjacency list,
 *   report whether it contains at least one cycle. The graph may be
 *   disconnected, so every component has to be checked, not just one.
 *
 * EXAMPLE
 *   V=4, edges 1-2, 2-3                 ->  false  (a plain path, no cycle)
 *   V=4, edges 1-2, 2-3, 3-1            ->  true   (triangle 1-2-3-1)
 *   V=6, edges 0-1 | 2-3, 3-4, 4-2      ->  true   (cycle is in component 2)
 *   V=1, no edges                       ->  false  (edge case: single vertex)
 *
 * APPROACH  (traversal + "where did I come from")
 *   1. In an undirected graph every edge u-v is stored twice, so from v you can
 *      always walk straight back to u. That step is NOT a cycle.
 *   2. So carry the parent along with the node. When you meet an already
 *      visited neighbour that is not the parent, you have found a second way
 *      into that vertex -> a cycle.
 *   3. DFS form: recurse with (node, parent).
 *      BFS form: the queue holds Node(vertex, parent) pairs instead of ints.
 *   4. Wrap either traversal in a loop over all vertices so disconnected
 *      components are covered. Once visited, a vertex is never re-explored,
 *      so the whole sweep is still linear.
 *
 * KEY INSIGHT
 *   Undirected cycle detection = "visited neighbour that is not my parent".
 *   Compare with a DIRECTED graph, where visited is not enough and you need a
 *   recursion-stack array (pathVis) instead - see A03_CycleCheckInDirectedGraph. Recognising which
 *   of the two rules applies is the whole question.
 *
 * COMPLEXITY
 *   Time  O(V + E)  every vertex is pushed once, every edge is scanned twice.
 *   Space O(V)      visited array plus the queue (BFS) or call stack (DFS).
 *
 * INTERVIEW FOLLOW-UPS
 *   - Print the cycle itself, not just true/false (keep a parent array and walk back).
 *   - Same question on a DIRECTED graph - why does the parent trick break?
 *   - Solve it with Union-Find: an edge whose endpoints already share a root closes a cycle.
 *   - What about self-loops (u-u) and parallel edges (u-v twice)? Both are cycles,
 *     and the plain parent check misses a duplicate u-v pair.
 *
 * RUN
 *   main() runs 4 cases (path, triangle, disconnected-with-cycle, single vertex)
 *   through BOTH the DFS and the BFS version and prints actual vs expected.
 */
import java.util.*;

class CheckForCycleInUnDirected {

    /** DFS form: recurse carrying the vertex we arrived from. */
    private boolean dfs(int node,
                        int parent,
                        boolean[] vis,
                        ArrayList<ArrayList<Integer>> adj) {
        vis[node] = true;
        for (int adjacentNode : adj.get(node)) {
            if (!vis[adjacentNode]) {
                if (dfs(adjacentNode, node, vis, adj)) return true;
            }
            // Visited AND not the vertex we came from -> a second route into it -> cycle.
            // e.g. 1-2-3-1 : from 3 we see 1, already visited, parent is 2, so cycle.
            else if (adjacentNode != parent) {
                return true;
            }
        }
        return false;
    }

    /** BFS form: the queue stores (vertex, parent) so the same rule applies. */
    private boolean bfs(ArrayList<ArrayList<Integer>> adj,
                        int src,
                        boolean[] vis) {
        Queue<Node> q = new LinkedList<>();
        q.add(new Node(src, -1));
        vis[src] = true;

        while (!q.isEmpty()) {
            Node current = q.poll();
            int u = current.u;
            int parent = current.parent;

            for (int v : adj.get(u)) {
                if (!vis[v]) {
                    vis[v] = true;          // mark at enqueue time, or a vertex can be queued twice
                    q.add(new Node(v, u));
                } else if (v != parent) {
                    return true;
                }
            }
        }
        return false;
    }

    public boolean isCycleDFS(int V, ArrayList<ArrayList<Integer>> adj) {
        boolean[] vis = new boolean[V];
        for (int node = 0; node < V; node++) {
            if (!vis[node] && dfs(node, -1, vis, adj)) return true;   // -1 = "no parent yet"
        }
        return false;
    }

    public boolean isCycleBFS(int V, ArrayList<ArrayList<Integer>> adj) {
        boolean[] vis = new boolean[V];
        for (int node = 0; node < V; node++) {
            if (!vis[node] && bfs(adj, node, vis)) return true;
        }
        return false;
    }

    // ------------------------------------------------------------------ demo

    private static ArrayList<ArrayList<Integer>> emptyGraph(int V) {
        ArrayList<ArrayList<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());
        return adj;
    }

    /** Undirected edge: store it in both directions. */
    private static void addEdge(ArrayList<ArrayList<Integer>> adj, int u, int v) {
        adj.get(u).add(v);
        adj.get(v).add(u);
    }

    public static void main(String[] args) {
        CheckForCycleInUnDirected obj = new CheckForCycleInUnDirected();

        // case 1: typical - a path 1-2-3, no cycle
        ArrayList<ArrayList<Integer>> g1 = emptyGraph(4);
        addEdge(g1, 1, 2);
        addEdge(g1, 2, 3);
        check(obj, "case 1 path 1-2-3        ", 4, g1, false);

        // case 2: typical - a triangle
        ArrayList<ArrayList<Integer>> g2 = emptyGraph(4);
        addEdge(g2, 1, 2);
        addEdge(g2, 2, 3);
        addEdge(g2, 3, 1);
        check(obj, "case 2 triangle 1-2-3-1  ", 4, g2, true);

        // case 3: tricky - cycle hides in the SECOND component, so the outer loop matters
        ArrayList<ArrayList<Integer>> g3 = emptyGraph(6);
        addEdge(g3, 0, 1);
        addEdge(g3, 2, 3);
        addEdge(g3, 3, 4);
        addEdge(g3, 4, 2);
        check(obj, "case 3 disconnected+cycle", 6, g3, true);

        // case 4: edge case - one vertex, no edges
        check(obj, "case 4 single vertex     ", 1, emptyGraph(1), false);
    }

    private static void check(CheckForCycleInUnDirected obj, String label,
                              int V, ArrayList<ArrayList<Integer>> adj, boolean expected) {
        boolean byDfs = obj.isCycleDFS(V, adj);
        boolean byBfs = obj.isCycleBFS(V, adj);
        System.out.println(label + " -> DFS " + byDfs + ", BFS " + byBfs
                + "   expected " + expected + ", " + expected);
    }
}

/** (vertex, parent) pair carried through the BFS queue. */
class Node {
    int u;
    int parent;

    public Node(int u, int parent) {
        this.u = u;
        this.parent = parent;
    }
}

