/*
 * =====================================================================
 *  Merge Intervals                              LeetCode 56 | Medium  MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Given a collection of intervals, merge every group that overlaps and return
 *   the resulting list of mutually disjoint intervals. The input is in no
 *   particular order. Intervals that merely touch (end == next start) are merged
 *   here, which is what LeetCode 56 expects.
 *
 * EXAMPLE
 *   [[1,3],[2,6],[8,10],[15,18]]  ->  [[1,6],[8,10],[15,18]]   1-3 and 2-6 overlap
 *   [[1,4],[4,5]]                 ->  [[1,5]]                  touching still merges
 *   [[5,10],[1,20],[2,3]]         ->  [[1,20]]                 one interval swallows all
 *   []                            ->  []                       nothing to merge
 *
 * APPROACH  (sort by start, fold into an accumulator)
 *   1. Sort the intervals by start value.
 *   2. Walk the sorted list keeping a result list whose last entry is the
 *      interval currently being built.
 *   3. If the current interval starts after the last result ends, it cannot touch
 *      anything already merged, so append a COPY of it and move on.
 *   4. Otherwise they overlap, so stretch the last result's end to
 *      max(last.end, current.end). The start never needs updating: sorting
 *      guarantees last.start is already the smaller one.
 *
 * KEY INSIGHT
 *   Sorting by start turns a global "which intervals overlap which" question into
 *   a local one: each interval only ever has to be compared with the single
 *   interval being accumulated. The whole pattern is three lines - sort, compare
 *   against the last kept interval, extend its end - and Insert Interval, Non
 *   Overlapping Intervals and Interval List Intersections are all variations of
 *   this same fold.
 *
 * COMPLEXITY
 *   Time  O(n log n)  the sort dominates, the merge pass is a single O(n) walk
 *   Space O(n)        output list (plus O(n) for the sort's own scratch space)
 *
 * INTERVIEW FOLLOW-UPS
 *   - The list is already sorted and you insert one new interval: LeetCode 57 (C01_InsertInterval).
 *   - Return the total covered length, or the gaps between the merged blocks.
 *   - Intervals arrive as a stream: keep a TreeMap keyed by start and merge the
 *     floor and ceiling neighbours on each insert.
 *   - Only merge intervals that overlap by at least k units.
 *
 * FIXES APPLIED
 *   Fixed: merge() appended the caller's Interval objects and then mutated their
 *          end field, silently corrupting the input list. It now appends copies.
 *   Fixed: the comparator used (i1.start - i2.start), which overflows for large
 *          or negative starts. Replaced with Integer.compare.
 *
 * RUN
 *   main() runs 4 cases (typical, touching, nested, empty), prints actual vs
 *   expected, and re-prints the input to show it was not mutated.
 */

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Interval {
    int start;
    int end;

    Interval(int start, int end) {
        this.start = start;
        this.end = end;
    }

    @Override
    public String toString() {
        return "[" + start + ", " + end + "]";
    }
}

class MergeIntervals {

    public List<Interval> merge(List<Interval> intervals) {
        // Sort by start value. Integer.compare avoids the overflow that a plain
        // subtraction comparator hits when the starts are far apart.
        Collections.sort(intervals, (i1, i2) -> Integer.compare(i1.start, i2.start));

        List<Interval> merged = new ArrayList<>();
        for (Interval interval : intervals) {
            Interval last = merged.isEmpty() ? null : merged.get(merged.size() - 1);

            // No overlap with the interval being accumulated -> start a new one.
            // A copy is added so that stretching its end later cannot write back
            // into the caller's list.
            if (last == null || last.end < interval.start) {
                merged.add(new Interval(interval.start, interval.end));
            } else {
                // Overlap: only the end can grow. Sorting already fixed the start.
                last.end = Math.max(last.end, interval.end);
            }
        }
        return merged;
    }

    private static List<Interval> intervalsOf(int[][] pairs) {
        List<Interval> list = new ArrayList<>();
        for (int[] pair : pairs) {
            list.add(new Interval(pair[0], pair[1]));
        }
        return list;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        MergeIntervals solver = new MergeIntervals();

        // typical: one overlapping pair, two isolated intervals
        List<Interval> input1 = intervalsOf(new int[][]{{1, 3}, {2, 6}, {8, 10}, {15, 18}});
        print("case 1", solver.merge(input1), "[[1, 6], [8, 10], [15, 18]]");
        // merge() sorts the list in place, but it must not change any endpoint
        print("case 1 input after merge", input1, "[[1, 3], [2, 6], [8, 10], [15, 18]]");

        // tricky: intervals that only touch still merge under LeetCode 56 rules
        print("case 2", solver.merge(intervalsOf(new int[][]{{1, 4}, {4, 5}})), "[[1, 5]]");

        // tricky: unsorted input where one interval contains the others
        print("case 3",
                solver.merge(intervalsOf(new int[][]{{5, 10}, {1, 20}, {2, 3}})), "[[1, 20]]");

        // edge: empty input
        print("case 4", solver.merge(intervalsOf(new int[][]{})), "[]");
    }
}

AAScratches/01-DSA/15-Intervals/A03_Mini.text:
/*
 * =====================================================================
 *  Minimum Number of Platforms                    GFG classic | Medium  MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Given the arrival and departure times of n trains at one station, find the
 *   smallest number of platforms needed so that no train ever waits. A platform
 *   holds one train from its arrival until its departure, and a train arriving at
 *   exactly the moment another departs still needs its own platform.
 *
 * EXAMPLE
 *   arr = [900, 945, 955, 1100, 1500, 1800]
 *   dep = [920, 1200, 1130, 1150, 1900, 2000]  ->  3   (945, 955, 1100 all overlap)
 *   arr = [900], dep = [910]                   ->  1   single train
 *   arr = [100, 200, 300], dep = [900, 900, 900] -> 3  nothing leaves before all arrive
 *
 * APPROACH  (decouple the endpoints, then sweep time forward)
 *   1. Sort the arrival array and the departure array INDEPENDENTLY. Which train
 *      owns which time stops mattering; only the chronology of events does.
 *   2. Walk both arrays with two pointers, always handling the earlier event next.
 *   3. Arrival earlier than or equal to the next departure -> a train occupies a
 *      platform, so increment the live count and record the running maximum.
 *   4. Otherwise the next event is a departure -> decrement the live count.
 *   5. Stop when the arrivals run out; the peak can only occur on an arrival.
 *
 * KEY INSIGHT
 *   The answer is the maximum number of intervals alive at the same instant, and
 *   that peak is found without ever pairing a start with its own end. Breaking
 *   intervals into a sorted stream of +1 and -1 events is the third interval
 *   primitive, and it solves Meeting Rooms II, Divide Intervals Into Minimum
 *   Groups, Car Pooling and Maximum Population Year with the same loop.
 *   Using <= rather than < on the arrival branch encodes "arrival at the exact
 *   departure minute still needs a platform"; flip it to < if the station allows
 *   an instant handover.
 *
 * COMPLEXITY
 *   Time  O(n log n)  two sorts; the sweep afterwards is a single O(n) pass
 *   Space O(1) extra  both sorts are in place, the sweep keeps two counters
 *
 * INTERVIEW FOLLOW-UPS
 *   - Same problem under the interview name Meeting Rooms II
 *     (C03_MeetingRoomsII).
 *   - Report the busiest time window, not just the count.
 *   - Each train carries a different number of coaches: weight the deltas
 *     (C05_CarPooling).
 *   - Times are unbounded or arrive as a stream: use a TreeMap difference map.
 *
 * RUN
 *   main() runs 5 cases (typical, single train, total overlap, empty, handover
 *   at the same minute) and prints actual vs expected.
 */

import java.util.Arrays;

class MinimumPlatforms {

    private static int findPlatform(int[] arr, int[] dep, int n) {
        // Sorted independently on purpose: the pairing of an arrival with its own
        // departure is irrelevant, only the order of events in time matters.
        Arrays.sort(arr);
        Arrays.sort(dep);

        int minPlatforms = 0; // the answer: peak concurrency seen so far
        int platforms = 0;    // platforms occupied right now

        int i = 0; // next arrival
        int j = 0; // next departure
        while (i < n && j < n) {
            if (arr[i] <= dep[j]) {
                // A train arrives before (or exactly as) the next one leaves.
                platforms++;
                i++;
                minPlatforms = Math.max(minPlatforms, platforms);
            } else {
                // The next event in time is a departure, freeing a platform.
                platforms--;
                j++;
            }
        }

        // No tail loop is needed: once the arrivals are exhausted the count can
        // only fall, so the maximum has already been recorded.
        return minPlatforms;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // typical: 945, 955 and 1100 are all on platforms at 1100
        int[] arr1 = {900, 945, 955, 1100, 1500, 1800};
        int[] dep1 = {920, 1200, 1130, 1150, 1900, 2000};
        print("case 1 six trains", findPlatform(arr1, dep1, arr1.length), 3);

        // edge: one train needs one platform
        int[] arr2 = {900};
        int[] dep2 = {910};
        print("case 2 single train", findPlatform(arr2, dep2, arr2.length), 1);

        // tricky: nothing departs until every train has arrived
        int[] arr3 = {100, 200, 300};
        int[] dep3 = {900, 900, 900};
        print("case 3 all overlap", findPlatform(arr3, dep3, arr3.length), 3);

        // edge: no trains at all
        print("case 4 empty", findPlatform(new int[]{}, new int[]{}, 0), 0);

        // tricky: back-to-back times still clash under the <= rule
        int[] arr5 = {900, 920};
        int[] dep5 = {920, 940};
        print("case 5 handover at 920", findPlatform(arr5, dep5, arr5.length), 2);
    }
}

