/*
 * =====================================================================
 *  Car Pooling                                       LeetCode 1094 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   A car with a fixed capacity drives one way along a number line, never
 *   turning back. trips[i] = [numPassengers, from, to] means that many people
 *   board at "from" and leave at "to". Return true if the car can complete
 *   every trip without ever carrying more than capacity passengers.
 *
 * EXAMPLE
 *   trips = [[2,1,5],[3,3,7]], capacity = 4  ->  false  (5 aboard on [3,5])
 *   trips = [[2,1,5],[3,5,7]], capacity = 5  ->  true   (2 leave exactly as 3 board)
 *   trips = [[9,0,1]],         capacity = 9  ->  true   (exactly full, allowed)
 *
 * APPROACH  (weighted event sweep / difference array on the line)
 *   1. Turn each trip into two events: (from, +numPassengers) and (to, -numPassengers).
 *   2. Sort the events by location. Where locations tie, apply the DROP-OFFS
 *      first - passengers leaving at x are already gone before anyone boards at x.
 *      That is the whole comparator: location ascending, then delta ascending.
 *   3. Sweep left to right adding each delta to a running occupancy count.
 *   4. If the running count ever exceeds capacity, return false; otherwise true.
 *
 * KEY INSIGHT
 *   This is the +1/-1 concurrency sweep from Minimum Platforms with weights
 *   attached: the "+1 per meeting" becomes "+k per trip". Peak value of the
 *   running sum is the peak occupancy. The part that actually bites in an
 *   interview is the tie-break - without ordering drop-offs before pick-ups at
 *   the same coordinate you invent passengers who overlap for zero distance.
 *
 *   Fixed: the original comparator sorted only by location, so at a shared
 *   coordinate the order depended on which trip happened to be listed first.
 *   For trips = [[3,5,7],[2,1,5]] with capacity 4 it reported false even though
 *   the 2 passengers leave at 5 exactly as the 3 board. Comparing the delta on a
 *   tie makes the result independent of input order.
 *
 * COMPLEXITY
 *   Time  O(n log n)  sorting 2n events; the sweep is O(n).
 *   Space O(n)        the event list.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Locations are bounded (0..1000 on LeetCode): drop the sort and use a
 *     difference array over the axis for O(n + range).
 *   - Return the maximum occupancy, or the location where the car is fullest.
 *   - What if the car could turn around, so trips are unordered in time?
 *   - Streaming trips that arrive one at a time: keep a TreeMap of deltas.
 *
 * RUN
 *   main() runs 4 cases (over capacity, exact handover, exactly full, and the
 *   reordered handover that used to fail) and prints actual vs expected.
 */

import java.util.ArrayList;
import java.util.List;

class CarPooling {

    public static boolean carPooling(int[][] trips, int capacity) {
        List<int[]> events = new ArrayList<>();

        for (int[] trip : trips) {
            // Naming the columns beats indexing trip[0..2] all over the method.
            int numPassengers = trip[0];
            int startLocation = trip[1];
            int endLocation = trip[2];

            events.add(new int[]{startLocation, numPassengers});  // pick-up
            events.add(new int[]{endLocation, -numPassengers});   // drop-off
        }

        // Location ascending; on a tie the negative delta (drop-off) sorts first,
        // so the seats are freed before the next group boards at that stop.
        events.sort((a, b) -> a[0] != b[0]
                ? Integer.compare(a[0], b[0])
                : Integer.compare(a[1], b[1]));

        int currentPassengers = 0;
        for (int[] event : events) {
            currentPassengers += event[1];
            if (currentPassengers > capacity) {
                return false;
            }
        }
        return true;
    }

    private static void print(String label, boolean actual, boolean expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // Case 1: typical - 2 + 3 = 5 aboard between 3 and 5, over a capacity of 4.
        print("case 1 (over capacity)", carPooling(new int[][]{{2, 1, 5}, {3, 3, 7}}, 4), false);

        // Case 2: edge - drop-off and pick-up at the same stop; peak is 3, not 5.
        print("case 2 (handover at 5)", carPooling(new int[][]{{2, 1, 5}, {3, 5, 7}}, 5), true);

        // Case 3: edge - occupancy exactly equals capacity, which is allowed.
        print("case 3 (exactly full)", carPooling(new int[][]{{9, 0, 1}}, 9), true);

        // Case 4: tricky - same handover as case 2 but the trips are listed in the
        // other order. The old location-only comparator returned false here.
        print("case 4 (reordered handover)",
                carPooling(new int[][]{{3, 5, 7}, {2, 1, 5}}, 4), true);
    }
}

AAScratches/01-DSA/15-Intervals/C06_NonO.text:
/*
 * =====================================================================
 *  Non-overlapping Intervals                         LeetCode 435 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Given a list of intervals, return the minimum number you must REMOVE so
 *   that the survivors never overlap. Intervals that merely touch, such as
 *   [1,2] and [2,3], do not count as overlapping. Removing the fewest is the
 *   same as keeping the most, so this is activity selection in disguise.
 *
 * EXAMPLE
 *   [[1,2],[2,3],[3,4],[1,3]]  ->  1   (drop [1,3]; the other three chain cleanly)
 *   [[1,2],[1,2],[1,2]]        ->  2   (keep one copy, remove the other two)
 *   [[1,2]]                    ->  0   (nothing to remove)
 *   [[1,100],[11,22],[1,11],[2,12]] -> 2  (the greedy keeps [1,11] and [11,22])
 *
 * APPROACH  (greedy: sort by END time, keep the earliest finisher)
 *   1. Sort the intervals by their end value, ascending.
 *   2. Track lastEnd, the end of the most recent interval we decided to KEEP.
 *      Start it at Integer.MIN_VALUE so the first interval is always kept.
 *   3. Scan in that order. If interval.start >= lastEnd it does not clash with
 *      anything kept so far: keep it and set lastEnd = interval.end.
 *   4. Otherwise it overlaps the kept set, so count it as a removal and move on -
 *      lastEnd is untouched, because the interval we kept ends no later.
 *   5. The removal count is the answer.
 *
 * KEY INSIGHT
 *   Sort by END, not by start. This is the folder's second axis and the classic
 *   exchange argument: among intervals that clash, the one finishing earliest
 *   leaves the most room for everything after it, so keeping it is never worse
 *   than keeping any rival. Sorting by start is the trap - with [[1,100],[2,3],
 *   [3,4]] it anchors on the 99-wide interval and gets the answer wrong.
 *   Recognise it by the shape "keep the largest non-conflicting subset".
 *
 * COMPLEXITY
 *   Time  O(n log n)  the sort dominates; the single scan is O(n).
 *   Space O(1)        in place, ignoring the sort's own overhead.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Minimum Arrows to Burst Balloons (C07_MinimumArrowsToBurstBalloons,
 *     LC 452) is the same sort-by-end greedy, EXCEPT that touching intervals
 *     are pierceable by one arrow there, so its comparison is strict
 *     (start > end) while this one is start >= lastEnd. The two counts are
 *     therefore not simple reframings of each other.
 *   - If touching intervals DID overlap, change the test to interval[0] > lastEnd.
 *   - Weighted version (each interval has a value, maximise the kept value):
 *     greedy breaks, it becomes DP with binary search - O(n log n).
 *   - Return the intervals you kept, not just how many you dropped.
 *
 * RUN
 *   main() runs 4 cases (typical, all identical, single interval, nested) and
 *   prints actual vs expected.
 */

import java.util.Arrays;
import java.util.Comparator;

class NonOverlappingIntervals {

    public int eraseOverlapIntervals(int[][] intervals) {
        // Earliest finisher first: that is what makes the greedy optimal.
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[1]));

        int count = 0;                    // intervals removed so far
        int lastEnd = Integer.MIN_VALUE;  // end of the last interval we kept

        for (int[] interval : intervals) {
            if (interval[0] >= lastEnd) {
                // Starts at or after the kept one ends, so no clash: keep it.
                lastEnd = interval[1];
            } else {
                // Clashes with what we already kept, and that one ends earlier,
                // so dropping this interval is never the worse choice.
                count++;
            }
        }
        return count;
    }

    private static void print(String label, int actual, int expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        NonOverlappingIntervals solution = new NonOverlappingIntervals();

        // Case 1: typical - one wide interval must go.
        print("case 1 (typical)",
                solution.eraseOverlapIntervals(new int[][]{{1, 2}, {2, 3}, {3, 4}, {1, 3}}), 1);

        // Case 2: edge - every interval identical, so all but one are removed.
        print("case 2 (all equal)",
                solution.eraseOverlapIntervals(new int[][]{{1, 2}, {1, 2}, {1, 2}}), 2);

        // Case 3: edge - a single interval never overlaps anything.
        print("case 3 (single)",
                solution.eraseOverlapIntervals(new int[][]{{1, 2}}), 0);

        // Case 4: tricky - a nested giant. Sorting by START would keep [1,100]
        // first and report 3; sorting by END keeps [1,11] and [11,22] and reports 2.
        print("case 4 (nested giant)",
                solution.eraseOverlapIntervals(
                        new int[][]{{1, 100}, {11, 22}, {1, 11}, {2, 12}}), 2);
    }
}

