/*
 * =====================================================================
 *  Random Pick Index                              LeetCode 398 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Two related jobs live in this file. The building block: pick one index of an
 *   array uniformly at random. The actual LeetCode 398 problem: given nums (which
 *   may contain duplicates) and a target, return a random index where that target
 *   sits, each such index equally likely.
 *
 * EXAMPLE
 *   arr = [10, 20, 30, 40, 50, 60]      ->  pickRandomIndex gives some i in [0, 6)
 *   arr = [7]                           ->  pickRandomIndex always gives 0
 *   nums = [1, 2, 3, 3, 3], target = 3  ->  one of {2, 3, 4}, each with probability 1/3
 *   nums = [1, 2, 3, 3, 3], target = 1  ->  always 0 (only one match)
 *
 * APPROACH  (bounded Random, then reservoir sampling of size 1)
 *   1. pickRandomIndex: rand.nextInt(arr.length). The bound is EXCLUSIVE, so the
 *      result is already a legal index - no -1 and no modulo bias.
 *   2. pickIndexOfTarget: walk nums once, counting matches seen so far (count).
 *      On the k-th match, replace the answer with that index with probability 1/k.
 *   3. Because the replacement probability shrinks as k grows, every match ends up
 *      equally likely, and only one int of extra memory is ever held.
 *
 * KEY INSIGHT
 *   Reservoir sampling turns "choose uniformly from a stream of unknown length"
 *   into O(1) space: keep the k-th item with probability 1/k. Recognise it whenever
 *   you may not store or re-scan the candidates (huge arrays, streams, linked lists).
 *
 * COMPLEXITY
 *   pickRandomIndex   Time O(1)  one bounded random draw
 *   pickIndexOfTarget Time O(n)  one pass over nums;  Space O(1)  one saved index
 *
 * INTERVIEW FOLLOW-UPS
 *   - Many pick calls, few updates? Pre-build Map<value, List<index>> for O(1) picks.
 *   - Pick k distinct indices instead of one -> reservoir of size k.
 *   - Weighted pick (LC 528) -> prefix sums plus binary search, not reservoir.
 *   - Why not rand.nextInt() % n? It skews toward small values when n is not a power of 2.
 *
 * NOTE
 *   Fixed: the file linked LC 398 but only had the uniform-index primitive; the real
 *   reservoir-sampling solution is added as pickIndexOfTarget and run from main().
 *
 * RUN
 *   main() runs 4 cases with a fixed seed, so the printed results are reproducible.
 */

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.TreeSet;

class RandomPickIndex {

    private final Random rand;

    public RandomPickIndex() {
        this(new Random());
    }

    /** Seeded constructor so tests and demos are reproducible. */
    public RandomPickIndex(long seed) {
        this(new Random(seed));
    }

    private RandomPickIndex(Random rand) {
        this.rand = rand;
    }

    /** Building block: a uniformly random legal index of arr. */
    public int pickRandomIndex(int[] arr) {
        if (arr == null || arr.length == 0) {
            throw new IllegalArgumentException("cannot pick an index from an empty array");
        }
        return rand.nextInt(arr.length); // bound is exclusive, so 0 .. arr.length - 1
    }

    /** LeetCode 398: a uniformly random index i with nums[i] == target. */
    public int pickIndexOfTarget(int[] nums, int target) {
        int chosen = -1;
        int matchesSeen = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != target) {
                continue;
            }
            matchesSeen++;
            // Keep the k-th match with probability 1/k; that leaves all matches equally likely.
            if (rand.nextInt(matchesSeen) == 0) {
                chosen = i;
            }
        }
        if (chosen < 0) {
            throw new IllegalArgumentException("target not present: " + target);
        }
        return chosen;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        RandomPickIndex picker = new RandomPickIndex(42L); // fixed seed -> reproducible output

        // Case 1 (typical): every draw is a legal index, and every index does get drawn.
        int[] arr = {10, 20, 30, 40, 50, 60};
        int[] hits = new int[arr.length];
        boolean allInRange = true;
        for (int draw = 0; draw < 6000; draw++) {
            int i = picker.pickRandomIndex(arr);
            if (i < 0 || i >= arr.length) {
                allInRange = false;
            } else {
                hits[i]++;
            }
        }
        int leastHit = Integer.MAX_VALUE;
        for (int h : hits) {
            leastHit = Math.min(leastHit, h);
        }
        print("case 1a: 6000 draws all in [0, 6)", allInRange, true);
        print("case 1b: rarest index hit > 800 times", leastHit > 800, true);

        // Case 2 (edge): a single-element array leaves no choice at all.
        int[] single = {7};
        print("case 2: pickRandomIndex([7])", picker.pickRandomIndex(single), 0);

        // Case 3 (typical LC 398): three copies of the target, so three reachable indices.
        int[] nums = {1, 2, 3, 3, 3};
        TreeSet<Integer> seen = new TreeSet<>();
        for (int draw = 0; draw < 3000; draw++) {
            seen.add(picker.pickIndexOfTarget(nums, 3));
        }
        List<Integer> sortedSeen = new ArrayList<>(seen);
        print("case 3: indices picked for target 3", sortedSeen, "[2, 3, 4]");

        // Case 4 (tricky): a target that occurs once must always give the same index.
        boolean alwaysZero = true;
        for (int draw = 0; draw < 100; draw++) {
            alwaysZero &= picker.pickIndexOfTarget(nums, 1) == 0;
        }
        print("case 4: single-occurrence target always index 0", alwaysZero, true);
    }
}

/*
 * =====================================================================
 *  Min Stack                           LeetCode 155 | Medium  MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Design a stack supporting push, pop, top and getMin, where getMin returns the
 *   smallest value currently on the stack. Every one of the four operations must be
 *   O(1) - so getMin is not allowed to scan the stack.
 *
 * EXAMPLE
 *   push 5, push 3, push 7, push 2  ->  top = 2,  getMin = 2
 *   pop (drops 2)                   ->  top = 7,  getMin = 3
 *   pop (drops 7)                   ->  top = 3,  getMin = 3
 *   push 3, push 3, pop             ->  getMin = 3  (duplicate mins must survive one pop)
 *
 * APPROACH  (augment each entry with a running aggregate)
 *   1. Store a Pair(val, minVal) per entry instead of a bare int.
 *   2. On push, minVal = min(value, minVal of the entry below), or value if empty.
 *   3. pop just removes the top pair - the minimum of the shorter stack is already
 *      recorded in the new top pair, so nothing has to be recomputed.
 *   4. top returns peek().val; getMin returns peek().minVal.
 *
 * KEY INSIGHT
 *   The minimum "so far" is a prefix property of the stack, and a stack only ever
 *   grows or shrinks at one end - so caching the answer per entry is enough, and
 *   popping automatically restores the previous answer. Recognise this whenever a
 *   query must become O(1) on a structure that changes at one end only: store the
 *   aggregate alongside each element rather than recomputing it.
 *
 * COMPLEXITY
 *   Time  O(1)  push, pop, top, getMin - all are single stack operations
 *   Space O(n)  one extra int per element for the running minimum
 *
 * INTERVIEW FOLLOW-UPS
 *   - Halve the memory: a second stack holding a min only when a new min is pushed.
 *   - Single-stack O(1) extra space with encoded deltas (2*val - min) - overflow risk.
 *   - Make it a Min Queue -> two stacks, or a monotonic deque (LC 239 sliding window).
 *   - getMax as well? Store both aggregates per entry; the pattern does not change.
 *
 * RUN
 *   main() runs 3 cases (typical sequence, duplicate minimums, empty stack) and
 *   prints actual vs expected on each line.
 */

import java.util.Stack;

class Pair {
    final int val;
    final int minVal; // smallest value in the stack up to and including this entry

    Pair(int val, int minVal) {
        this.val = val;
        this.minVal = minVal;
    }
}

class MinStack {
    private final Stack<Pair> st;

    public MinStack() {
        st = new Stack<>();
    }

    public void push(int value) {
        // The new minimum is the smaller of this value and the minimum below it.
        int min = st.isEmpty() ? value : Math.min(st.peek().minVal, value);
        st.push(new Pair(value, min));
    }

    /** Popping an empty stack is a no-op here, matching the LeetCode contract. */
    public void pop() {
        if (!st.isEmpty()) {
            st.pop();
        }
    }

    public int top() {
        if (st.isEmpty()) throw new RuntimeException("Stack is empty");
        return st.peek().val;
    }

    public int getMin() {
        if (st.isEmpty()) throw new RuntimeException("Stack is empty");
        return st.peek().minVal; // already computed at push time
    }

    public boolean isEmpty() {
        return st.isEmpty();
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // Case 1 (typical): the minimum moves down as the smaller values are popped off.
        MinStack stack = new MinStack();
        stack.push(5);
        stack.push(3);
        stack.push(7);
        stack.push(2);
        print("case 1a: top", stack.top(), 2);
        print("case 1b: getMin", stack.getMin(), 2);

        stack.pop(); // removes 2
        print("case 1c: top after pop", stack.top(), 7);
        print("case 1d: getMin after pop", stack.getMin(), 3);

        stack.pop(); // removes 7
        print("case 1e: top", stack.top(), 3);
        print("case 1f: getMin", stack.getMin(), 3);

        // Case 2 (tricky): duplicate minimums - popping one copy must not lose the min.
        MinStack dupes = new MinStack();
        dupes.push(3);
        dupes.push(3);
        dupes.push(9);
        dupes.pop(); // removes 9
        print("case 2a: getMin with two 3s left", dupes.getMin(), 3);
        dupes.pop(); // removes one 3
        print("case 2b: getMin with one 3 left", dupes.getMin(), 3);

        // Case 3 (edge): empty stack - pop is a no-op, getMin throws.
        MinStack empty = new MinStack();
        empty.pop(); // no-op, must not throw
        String result;
        try {
            empty.getMin();
            result = "no exception";
        } catch (RuntimeException e) {
            result = e.getMessage();
        }
        print("case 3a: pop on empty then isEmpty", empty.isEmpty(), true);
        print("case 3b: getMin on empty", result, "Stack is empty");
    }
}

/*
 * =====================================================================
 *  Logger Rate Limiter                              LeetCode 359 | Easy
 * =====================================================================
 *
 * PROBLEM
 *   Build a logger that prints a message at most once every 10 seconds. Calls arrive
 *   as shouldPrintMessage(timestamp, message) with non-decreasing timestamps (seconds).
 *   Return true if the message may be printed now, false if it is still suppressed.
 *   Each distinct message has its own independent 10-second window.
 *
 * EXAMPLE
 *   (1,  "foo")  ->  true    first time seen, next "foo" allowed at 11
 *   (2,  "bar")  ->  true    a different message has its own window
 *   (3,  "foo")  ->  false   3 < 11
 *   (10, "foo")  ->  false   10 < 11, one second short
 *   (11, "foo")  ->  true    boundary is inclusive: >= nextAllowed prints
 *
 * APPROACH  (map each key to its next-allowed timestamp)
 *   1. Keep HashMap<message, nextAllowedTimestamp>.
 *   2. On a call, read nextAllowed (default 0, so an unseen message always prints).
 *   3. If timestamp < nextAllowed, return false and change nothing - a suppressed
 *      message must NOT extend its own window, or a chatty caller is silenced forever.
 *   4. Otherwise store timestamp + 10 and return true.
 *
 * KEY INSIGHT
 *   Store the deadline, not the history. One int per message answers "may I print?"
 *   in O(1), while a list of past timestamps would cost time and memory for nothing.
 *   Recognise this whenever a window only needs its next boundary, not its contents -
 *   and note the contrast with the hit counter, which must keep events because it
 *   has to COUNT them, not just gate them.
 *
 * COMPLEXITY
 *   Time  O(1)  one hash lookup plus one hash insert per call
 *   Space O(d)  d = number of distinct messages ever seen (this map never shrinks)
 *
 * INTERVIEW FOLLOW-UPS
 *   - Unbounded memory: evict stale keys with an LRU cache or a periodic sweep.
 *   - Timestamps arriving out of order? Store max(existing, timestamp + 10).
 *   - Allow N messages per window instead of one -> token bucket or a per-key queue.
 *   - Make it thread-safe: ConcurrentHashMap plus an atomic compare-and-set on the value.
 *
 * RUN
 *   main() runs 3 cases: the LeetCode sequence, the exact boundary, and time 0.
 */

import java.util.HashMap;
import java.util.Map;

class LoggerRateLimiter {

    private static final int WINDOW_SECONDS = 10;

    /** message -> the earliest timestamp at which it may be printed again */
    private final Map<String, Integer> messageNextAllowed;

    public LoggerRateLimiter() {
        messageNextAllowed = new HashMap<>();
    }

    public boolean shouldPrintMessage(int timestamp, String message) {
        int nextAllowed = messageNextAllowed.getOrDefault(message, 0);
        if (timestamp < nextAllowed) {
            return false; // still inside the window; deliberately do not push the deadline out
        }
        messageNextAllowed.put(message, timestamp + WINDOW_SECONDS);
        return true;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // Case 1 (typical): the LeetCode example, two interleaved messages.
        LoggerRateLimiter logger = new LoggerRateLimiter();
        print("case 1a: (1, foo)", logger.shouldPrintMessage(1, "foo"), true);
        print("case 1b: (2, bar)", logger.shouldPrintMessage(2, "bar"), true);
        print("case 1c: (3, foo)", logger.shouldPrintMessage(3, "foo"), false);
        print("case 1d: (8, bar)", logger.shouldPrintMessage(8, "bar"), false);
        print("case 1e: (10, foo)", logger.shouldPrintMessage(10, "foo"), false);
        print("case 1f: (11, foo)", logger.shouldPrintMessage(11, "foo"), true);

        // Case 2 (edge): a rejected call must not restart the clock.
        LoggerRateLimiter boundary = new LoggerRateLimiter();
        print("case 2a: (100, hi)", boundary.shouldPrintMessage(100, "hi"), true);
        for (int t = 101; t < 110; t++) {
            boundary.shouldPrintMessage(t, "hi"); // nine suppressed calls in a row
        }
        print("case 2b: (110, hi) after 9 rejects", boundary.shouldPrintMessage(110, "hi"), true);

        // Case 3 (edge): timestamp 0, where the map's default of 0 has to behave.
        LoggerRateLimiter zero = new LoggerRateLimiter();
        print("case 3a: (0, start)", zero.shouldPrintMessage(0, "start"), true);
        print("case 3b: (9, start)", zero.shouldPrintMessage(9, "start"), false);
        print("case 3c: (10, start)", zero.shouldPrintMessage(10, "start"), true);
    }
}

/*
 * =====================================================================
 *  Design Authentication Manager                 LeetCode 1797 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Tokens live for timeToLive seconds. generate(tokenId, currentTime) creates a token
 *   that expires at currentTime + timeToLive. renew(tokenId, currentTime) pushes the
 *   expiry out by another timeToLive, but ONLY if the token exists and has not expired.
 *   countUnexpiredTokens(currentTime) returns how many tokens are still alive.
 *   Expiry is exclusive: a token expiring at time t is already dead at time t.
 *
 * EXAMPLE
 *   ttl = 5, generate("token1", 1)      ->  token1 expires at 6
 *   countUnexpiredTokens(2)             ->  1
 *   renew("token1", 6)                  ->  ignored: 6 >= 6, the token died exactly now
 *   countUnexpiredTokens(6)             ->  0
 *
 * APPROACH  (map tokenId -> expiry timestamp)
 *   1. generate: put(tokenId, currentTime + timeToLive), overwriting any old entry.
 *   2. renew: look up the expiry; return early if absent or if expiry <= currentTime,
 *      otherwise put the fresh expiry. The two guards are the whole problem.
 *   3. countUnexpiredTokens: scan the values and count expiry > currentTime.
 *   4. cleanup is an optional sweep that drops dead entries so the map stops growing.
 *
 * KEY INSIGHT
 *   Nothing ever has to be actively expired. Store the expiry timestamp and decide
 *   liveness lazily at read time by comparing with "now". The only detail that costs
 *   candidates the question is the boundary: expiry <= now means dead, so renewing at
 *   exactly the expiry second must fail.
 *
 * COMPLEXITY
 *   Time  O(1) generate and renew;  O(n) countUnexpiredTokens, n = tokens in the map
 *   Space O(n)  one entry per token until it is cleaned up
 *
 * INTERVIEW FOLLOW-UPS
 *   - Make count O(1): keep a LinkedHashMap in expiry order and pop the dead front,
 *     since calls arrive with non-decreasing time - amortised O(1), like LC 362.
 *   - Distributed version: Redis keys with TTL, or a lazy check plus a background sweep.
 *   - Make it thread-safe under concurrent renew: ConcurrentHashMap.computeIfPresent.
 *
 * RUN
 *   main() runs 3 cases (lifecycle, renew edge cases, expiry boundary) and prints
 *   actual vs expected on each line.
 */

import java.util.HashMap;
import java.util.Map;

class DesignAuthenticationManager {

    private final int timeToLive;

    /** tokenId -> the timestamp at which it becomes invalid (exclusive) */
    private final Map<String, Integer> tokenExpiryMap;

    public DesignAuthenticationManager(int timeToLive) {
        this.timeToLive = timeToLive;
        this.tokenExpiryMap = new HashMap<>();
    }

    public void generate(String tokenId, int currentTime) {
        tokenExpiryMap.put(tokenId, currentTime + timeToLive);
    }

    public void renew(String tokenId, int currentTime) {
        Integer expiryTime = tokenExpiryMap.get(tokenId);
        if (expiryTime == null) {
            return; // token was never generated
        }
        if (expiryTime <= currentTime) {
            return; // already expired: expiry is exclusive, so == now is too late
        }
        tokenExpiryMap.put(tokenId, currentTime + timeToLive);
    }

    public int countUnexpiredTokens(int currentTime) {
        int count = 0;
        for (int expiryTime : tokenExpiryMap.values()) {
            if (expiryTime > currentTime) {
                count++;
            }
        }
        return count;
    }

    /** Optional housekeeping: physically drop dead tokens so the map does not grow forever. */
    public void cleanup(int currentTime) {
        tokenExpiryMap.entrySet().removeIf(entry -> entry.getValue() <= currentTime);
    }

    public int size() {
        return tokenExpiryMap.size();
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // Case 1 (typical): generate, let it die, generate more, renew a live one.
        DesignAuthenticationManager manager = new DesignAuthenticationManager(5);
        manager.generate("token1", 1); // expires at 6
        print("case 1a: count at 2", manager.countUnexpiredTokens(2), 1);

        manager.renew("token1", 6); // 6 >= 6, so this renew is ignored
        print("case 1b: count at 6 after failed renew", manager.countUnexpiredTokens(6), 0);

        manager.generate("token2", 7); // expires at 12
        manager.generate("token3", 8); // expires at 13
        print("case 1c: count at 10", manager.countUnexpiredTokens(10), 2);

        manager.renew("token2", 10); // still alive (12 > 10), so expiry moves to 15
        print("case 1d: count at 13 (token3 just died)", manager.countUnexpiredTokens(13), 1);
        print("case 1e: count at 20", manager.countUnexpiredTokens(20), 0);

        // Case 2 (edge): renewing a token that was never generated is a silent no-op.
        DesignAuthenticationManager edge = new DesignAuthenticationManager(3);
        edge.renew("ghost", 1);
        print("case 2a: count at 1 after renewing a ghost", edge.countUnexpiredTokens(1), 0);
        print("case 2b: map size (ghost not inserted)", edge.size(), 0);

        // Case 3 (tricky): renew one second before expiry works, exactly at expiry does not.
        DesignAuthenticationManager boundary = new DesignAuthenticationManager(5);
        boundary.generate("a", 0); // dies at 5
        boundary.renew("a", 4);    // 5 > 4, so it now dies at 9
        print("case 3a: count at 8", boundary.countUnexpiredTokens(8), 1);
        boundary.generate("b", 0); // dies at 5
        boundary.renew("b", 5);    // 5 <= 5, ignored
        print("case 3b: count at 6", boundary.countUnexpiredTokens(6), 1);
        boundary.cleanup(6);       // drops the dead token b
        print("case 3c: map size after cleanup(6)", boundary.size(), 1);
    }
}

/*
 * =====================================================================
 *  Design Hit Counter                    LeetCode 362 | Medium MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Count the hits received in the past 5 minutes (300 seconds). hit(timestamp)
 *   records one hit; getHits(timestamp) returns how many hits landed in the window
 *   (timestamp - 300, timestamp]. Calls arrive with non-decreasing timestamps, and
 *   several hits may share the same second.
 *
 * EXAMPLE
 *   hit(1), hit(2), hit(3)  ->  getHits(4)   = 3    nothing has aged out yet
 *   hit(300)                ->  getHits(300) = 4    the hit at second 1 is still in range
 *                               getHits(301) = 3    second 1 is now exactly 300 old: dropped
 *
 * APPROACH  (sliding window over a FIFO queue of timestamps)
 *   1. hit: append the timestamp to the back of a deque. O(1), no cleanup.
 *   2. getHits: first evict from the FRONT while head <= timestamp - 300, because
 *      the oldest hits are always the first ones stored.
 *   3. The remaining size is the answer.
 *   4. Eviction is lazy - work is done on read, and each timestamp is pushed once
 *      and popped at most once, so the cost is amortised O(1) per hit.
 *
 * KEY INSIGHT
 *   A time window over non-decreasing timestamps is a queue: arrivals go in at one
 *   end, expiries leave from the other, and you never have to search the middle.
 *   Contrast with the logger rate limiter, which only needs the next deadline - here
 *   you must keep the events themselves because the question is "how many".
 *
 * COMPLEXITY
 *   Time  hit O(1);  getHits O(k) for the k expired entries, amortised O(1) per hit
 *   Space O(n)  n = hits inside one 300-second window
 *
 * INTERVIEW FOLLOW-UPS
 *   - Huge hit rate? Use 300 fixed buckets (BucketHitCounter below): O(1) hit,
 *     O(300) getHits, and memory bounded no matter the traffic.
 *   - Out-of-order or concurrent timestamps -> synchronise, or per-second atomic counters.
 *   - Window granularity in milliseconds or a 24-hour window -> buckets, not a queue.
 *   - Distributed counting -> per-node buckets summed by a coordinator, or HyperLogLog
 *     when distinct users, not raw hits, are what matters.
 *
 * RUN
 *   main() runs 3 cases against BOTH implementations: the LeetCode sequence, the
 *   exact 300-second boundary, and an empty counter.
 */

import java.util.ArrayDeque;
import java.util.Deque;

class DesignHitCounter {

    private static final int WINDOW = 300; // 300 seconds = 5 minutes

    /** Hit timestamps, oldest at the front - so expiry is always a pollFirst. */
    private final Deque<Integer> queue;

    public DesignHitCounter() {
        queue = new ArrayDeque<>();
    }

    /** Record a hit at the given timestamp (seconds). */
    public void hit(int timestamp) {
        queue.offerLast(timestamp);
    }

    /** Hits within the last 300 seconds, i.e. in (timestamp - 300, timestamp]. */
    public int getHits(int timestamp) {
        // Drop everything that is 300 seconds old or older; the front is always the oldest.
        while (!queue.isEmpty() && queue.peekFirst() <= timestamp - WINDOW) {
            queue.pollFirst();
        }
        return queue.size();
    }

    /**
     * Follow-up variant: fixed memory no matter how many hits arrive per second.
     * Slot i holds the timestamp that last wrote to it plus that second's count;
     * a slot whose timestamp is older than the window is simply ignored on read.
     */
    static class BucketHitCounter {
        private final int[] slotTime = new int[WINDOW];
        private final int[] slotHits = new int[WINDOW];

        public void hit(int timestamp) {
            int idx = timestamp % WINDOW;
            if (slotTime[idx] != timestamp) {
                slotTime[idx] = timestamp; // the slot belonged to an older second: reset it
                slotHits[idx] = 1;
            } else {
                slotHits[idx]++;
            }
        }

        public int getHits(int timestamp) {
            int total = 0;
            for (int i = 0; i < WINDOW; i++) {
                if (timestamp - slotTime[i] < WINDOW) {
                    total += slotHits[i];
                }
            }
            return total;
        }
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // Case 1 (typical) and Case 2 (boundary): same sequence through both designs.
        DesignHitCounter queueCounter = new DesignHitCounter();
        BucketHitCounter bucketCounter = new BucketHitCounter();
        for (int t : new int[]{1, 2, 3}) {
            queueCounter.hit(t);
            bucketCounter.hit(t);
        }
        print("case 1a: queue  getHits(4)", queueCounter.getHits(4), 3);
        print("case 1b: bucket getHits(4)", bucketCounter.getHits(4), 3);

        queueCounter.hit(300);
        bucketCounter.hit(300);
        print("case 2a: queue  getHits(300)", queueCounter.getHits(300), 4);
        print("case 2b: bucket getHits(300)", bucketCounter.getHits(300), 4);
        print("case 2c: queue  getHits(301) drops second 1", queueCounter.getHits(301), 3);
        print("case 2d: bucket getHits(301) drops second 1", bucketCounter.getHits(301), 3);

        // Case 3 (edge): never hit, plus many hits in one second, plus a window that
        // has fully drained.
        DesignHitCounter empty = new DesignHitCounter();
        BucketHitCounter emptyBucket = new BucketHitCounter();
        print("case 3a: queue  getHits(1) with no hits", empty.getHits(1), 0);
        print("case 3b: bucket getHits(1) with no hits", emptyBucket.getHits(1), 0);

        for (int i = 0; i < 5; i++) {
            empty.hit(10);
            emptyBucket.hit(10);
        }
        print("case 3c: queue  5 hits in second 10", empty.getHits(10), 5);
        print("case 3d: bucket 5 hits in second 10", emptyBucket.getHits(10), 5);
        print("case 3e: queue  getHits(310) all aged out", empty.getHits(310), 0);
        print("case 3f: bucket getHits(310) all aged out", emptyBucket.getHits(310), 0);
    }
}

/*
 * =====================================================================
 *  Insert Delete GetRandom O(1)           LeetCode 380 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Design a set of ints supporting insert, remove and getRandom in average O(1).
 *   insert returns false if the value is already there; remove returns false if it is
 *   absent. getRandom must return every element currently in the set with equal chance.
 *
 * EXAMPLE
 *   insert(10) -> true, insert(20) -> true, insert(10) -> false   (already present)
 *   remove(20) -> true, remove(20) -> false                       (gone already)
 *   getRandom() -> 10                                             (only member left)
 *
 * DESIGN  (array plus index map, swap-with-last deletion)
 *   List<Integer> values   the elements packed with no gaps, so a random draw is just
 *                          values.get(rand.nextInt(values.size())).
 *   Map<Integer,Integer> indexOf   value -> its position in values, so remove can find
 *                          the slot to overwrite in O(1) instead of scanning.
 *   insert     append to values, record the new index in indexOf.
 *   remove     copy the LAST element over the victim's slot, repoint that element's
 *              index, then drop the duplicated tail and delete the victim's key.
 *   getRandom  one uniform draw over [0, size).
 *
 * KEY DECISIONS
 *   - Why not delete from the middle of the list? That shifts every later element:
 *     O(n) work and every index stored in the map goes stale. Swapping with the last
 *     element touches exactly two map entries and keeps the array gap-free.
 *   - The array MUST stay gap-free: getRandom's uniformity relies on every index in
 *     [0, size) holding a live element, so tombstones are not an option.
 *   - Order inside remove matters. Do indexOf.put(lastValue, slot) BEFORE
 *     indexOf.remove(val); when the victim IS the last element the put re-adds its own
 *     key, and only the later remove clears it. Swap the two lines and a dead key stays.
 *   - values.remove(values.size() - 1) resolves to remove(int index), which is O(1).
 *     remove(Integer.valueOf(x)) would be a linear scan - a classic overload trap.
 *
 * COMPLEXITY
 *   Time  O(1) average per op   hash lookup plus an append or a tail removal
 *   Space O(n)                  each element is held once in the list, once as a key
 *
 * INTERVIEW FOLLOW-UPS
 *   - Allow duplicates (LC 381): the map value becomes a Set<Integer> of indices.
 *   - Weighted getRandom: prefix sums plus binary search, O(log n) per draw.
 *   - Thread safety: one lock is easy; concurrent readers need a stable snapshot.
 *   - Why not TreeSet / LinkedHashSet? Neither can pick a uniform element in O(1).
 *
 * RUN
 *   main() runs 3 cases: a typical insert/remove sequence, the edge case of removing
 *   the only element and re-inserting it, and a statistical check that getRandom is
 *   uniform. Every line prints actual vs expected.
 */

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

class RandomizedSet {

    /** value -> index of that value inside {@code values}. */
    private final Map<Integer, Integer> indexOf;

    /** The elements, packed with no gaps so index -> element is total. */
    private final List<Integer> values;

    private final Random rand;

    public RandomizedSet() {
        indexOf = new HashMap<>();
        values = new ArrayList<>();
        rand = new Random();
    }

    /** Inserts val. Returns false (and changes nothing) if it is already present. */
    public boolean insert(int val) {
        if (indexOf.containsKey(val)) {
            return false;
        }
        values.add(val);
        indexOf.put(val, values.size() - 1);
        return true;
    }

    /** Removes val. Returns false if it was not in the set. */
    public boolean remove(int val) {
        Integer slot = indexOf.get(val);
        if (slot == null) {
            return false;
        }
        int lastValue = values.get(values.size() - 1);

        // Move the last element into the victim's slot so the array keeps no gaps.
        values.set(slot, lastValue);
        indexOf.put(lastValue, slot);

        // Drop the now-duplicated tail by INDEX (O(1)), then forget the victim.
        // If val was itself the last element, the put above re-added its key and this
        // remove is what finally clears it - hence this exact ordering.
        values.remove(values.size() - 1);
        indexOf.remove(val);
        return true;
    }

    /** Uniformly random member. Caller must not call this on an empty set. */
    public int getRandom() {
        return values.get(rand.nextInt(values.size()));
    }

    public int size() {
        return values.size();
    }

    /** Copy of the backing array, for the demo only - insertion order is an artefact. */
    public List<Integer> contents() {
        return new ArrayList<>(values);
    }
}

class InsertDeleteGetRandomOof1 {

    public static void main(String[] args) {
        // ---- case 1: typical sequence -------------------------------------------
        RandomizedSet set = new RandomizedSet();
        print("case 1 insert(10)", set.insert(10), true);
        print("case 1 insert(20)", set.insert(20), true);
        print("case 1 insert(30)", set.insert(30), true);
        print("case 1 insert(10) again", set.insert(10), false);
        print("case 1 contents", set.contents(), "[10, 20, 30]");
        print("case 1 remove(20)", set.remove(20), true);
        // 30 was the last element, so it slid into slot 1 where 20 used to sit.
        print("case 1 contents after remove", set.contents(), "[10, 30]");
        print("case 1 remove(20) again", set.remove(20), false);
        print("case 1 size", set.size(), 2);

        // ---- case 2: edge - remove the only element, then re-insert it -----------
        // This is what breaks a naive remove(): the victim is also the last element.
        RandomizedSet single = new RandomizedSet();
        print("case 2 insert(7)", single.insert(7), true);
        print("case 2 remove(7)", single.remove(7), true);
        print("case 2 size", single.size(), 0);
        print("case 2 contents", single.contents(), "[]");
        print("case 2 insert(7) again", single.insert(7), true);
        print("case 2 getRandom", single.getRandom(), 7);

        // ---- case 3: getRandom is a member, and is uniform -----------------------
        RandomizedSet three = new RandomizedSet();
        three.insert(1);
        three.insert(2);
        three.insert(3);

        int draws = 3000;
        int[] hits = new int[4];
        boolean alwaysMember = true;
        for (int i = 0; i < draws; i++) {
            int picked = three.getRandom();
            if (picked < 1 || picked > 3) {
                alwaysMember = false;
            } else {
                hits[picked]++;
            }
        }
        print("case 3 every draw is a member", alwaysMember, true);
        // Expected 1000 each; 700..1300 is roughly 11 standard deviations wide, so this
        // is a deterministic pass for a correct uniform draw.
        boolean balanced = inRange(hits[1]) && inRange(hits[2]) && inRange(hits[3]);
        print("case 3 each of 1,2,3 drawn 700..1300 times", balanced, true);
    }

    private static boolean inRange(int count) {
        return count >= 700 && count <= 1300;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Design a Stack With Increment Operation        LeetCode 1381 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Build a stack with a fixed maxSize supporting push (ignored when full), pop
 *   (returns -1 when empty) and increment(k, val), which adds val to the bottom k
 *   elements - or to every element if the stack holds fewer than k.
 *   The goal is O(1) for all three, so increment must not touch k cells.
 *
 * EXAMPLE
 *   maxSize = 3: push 1, push 2 -> pop() = 2
 *   push 2, push 3, push 4 (ignored, stack is full: [1, 2, 3])
 *   increment(5, 100) -> all 3 get +100 ; increment(2, 100) -> bottom 2 get +100
 *   pops are then 103, 202, 201
 *
 * DESIGN  (lazy increment propagation)
 *   int[] stack   raw pushed values, never rewritten by increment.
 *   int[] inc     inc[i] is a debt owed to positions 0..i. increment(k, val) writes
 *                 ONE cell: inc[min(k, top) - 1] += val.
 *   int top       next free slot, so top is also the current size.
 *   pop           real value = stack[top-1] + inc[top-1]; before returning, push the
 *                 debt one step down (inc[top-2] += inc[top-1]) so the element that
 *                 becomes the new peek still owes what it owed, then clear the slot.
 *   The true value of position i is stack[i] + sum(inc[i..top-1]); the propagation on
 *   pop is what keeps that sum collapsed into a single cell at the top.
 *
 * KEY DECISIONS
 *   - Why not just loop over the bottom k cells? That is O(k) per increment and the
 *     whole point of the problem is to make it O(1). Deferring the work is the answer.
 *   - Why store the debt at the TOP of the affected range rather than the bottom?
 *     Because pop always removes from the top, so the top is the only place the stack
 *     is ever read - parking the debt there means exactly one element ever reads it.
 *   - Fixed arrays rather than an ArrayList: maxSize is given, and the parallel array
 *     inc has to be index-aligned with stack anyway.
 *   - Watch the final pop: it is 201, not 101. The bottom element collects the debt
 *     from BOTH increments (1 + 100 from increment(5,100) + 100 from increment(2,100)),
 *     because every increment covers position 0.
 *
 * COMPLEXITY
 *   Time  O(1) for push, pop and increment - each touches a constant number of cells
 *   Space O(maxSize) for the two parallel arrays
 *
 * INTERVIEW FOLLOW-UPS
 *   - Increment the TOP k instead of the bottom k: park the debt at inc[top - k].
 *   - Support getMin as well: keep MinStack's per-entry running minimum alongside.
 *   - Unbounded stack: same idea over ArrayLists, amortised O(1).
 *   - Where else does this trick show up? Difference arrays and lazy segment trees are
 *     the same "record the delta once, settle it on read" idea.
 *
 * RUN
 *   main() runs 3 cases: the LeetCode example, an empty-stack case (pop returns -1 and
 *   increment is a no-op), and an overflow case where push past maxSize is ignored.
 *   Every line prints actual vs expected.
 */

import java.util.ArrayList;
import java.util.List;

class DesignAStackWithIncrementOperation {

    private final int maxSize;
    private final int[] stack;

    /** inc[i] is an unpaid increment owed to every position 0..i. */
    private final int[] inc;

    /** Next free index, which is also the current size. */
    private int top;

    public DesignAStackWithIncrementOperation(int maxSize) {
        this.maxSize = maxSize;
        this.stack = new int[maxSize];
        this.inc = new int[maxSize];
        this.top = 0;
    }

    /** Pushes x; silently ignored when the stack is already at maxSize. */
    public void push(int x) {
        if (top < maxSize) {
            stack[top] = x;
            inc[top] = 0;
            top++;
        }
    }

    /** Pops and returns the top value with its debt settled, or -1 if empty. */
    public int pop() {
        if (top == 0) {
            return -1;
        }
        top--;
        int result = stack[top] + inc[top];
        if (top > 0) {
            // Hand the debt down: the new top owes whatever this element owed.
            inc[top - 1] += inc[top];
        }
        inc[top] = 0; // slot is free again
        return result;
    }

    /** Adds val to the bottom min(k, size) elements in O(1). */
    public void increment(int k, int val) {
        int highestAffected = Math.min(k, top) - 1;
        if (highestAffected >= 0) {
            inc[highestAffected] += val;
        }
    }

    /**
     * Bottom-to-top view of the real values, for the demo only.
     * Value at i is stack[i] plus every debt parked at or above i, so walk downwards
     * accumulating. Read-only: nothing here mutates inc.
     */
    public List<Integer> contents() {
        int[] real = new int[top];
        int owed = 0;
        for (int i = top - 1; i >= 0; i--) {
            owed += inc[i];
            real[i] = stack[i] + owed;
        }
        List<Integer> out = new ArrayList<>();
        for (int v : real) {
            out.add(v);
        }
        return out;
    }

    public static void main(String[] args) {
        // ---- case 1: the LeetCode example ---------------------------------------
        DesignAStackWithIncrementOperation cs = new DesignAStackWithIncrementOperation(3);
        cs.push(1);
        cs.push(2);
        print("case 1 pop", cs.pop(), 2);
        cs.push(2);
        cs.push(3);
        cs.push(4);                       // ignored, stack is full
        print("case 1 after full push", cs.contents(), "[1, 2, 3]");
        cs.increment(5, 100);             // k > size, so all 3 elements
        cs.increment(2, 100);             // bottom 2 elements
        print("case 1 after increments", cs.contents(), "[201, 202, 103]");
        print("case 1 pop", cs.pop(), 103);
        print("case 1 pop", cs.pop(), 202);
        print("case 1 pop", cs.pop(), 201);

        // ---- case 2: edge - empty stack -----------------------------------------
        DesignAStackWithIncrementOperation empty = new DesignAStackWithIncrementOperation(2);
        print("case 2 pop on empty", empty.pop(), -1);
        empty.increment(3, 50);           // no-op: nothing to owe the debt to
        empty.push(7);                    // must NOT inherit the earlier increment
        print("case 2 pop after no-op increment", empty.pop(), 7);

        // ---- case 3: tricky - debt survives an ignored push ----------------------
        DesignAStackWithIncrementOperation full = new DesignAStackWithIncrementOperation(2);
        full.push(10);
        full.push(20);
        full.push(30);                    // ignored: maxSize is 2
        full.increment(1, 5);             // bottom element only
        print("case 3 contents", full.contents(), "[15, 20]");
        print("case 3 pop", full.pop(), 20);
        print("case 3 pop", full.pop(), 15);
        print("case 3 pop on drained stack", full.pop(), -1);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  LRU Cache                              LeetCode 146 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Design a fixed-capacity key-value cache where get and put are both O(1).
 *   get(key) returns the value or -1 if absent, and counts as a use.
 *   put(key, value) inserts or updates, also counts as a use, and when the cache is
 *   over capacity it evicts the key that was used least recently.
 *
 * EXAMPLE
 *   capacity 2: put(1,1), put(2,2), get(1) -> 1   (order is now 1 newest, 2 oldest)
 *   put(3,3) evicts key 2       -> get(2) = -1
 *   put(4,4) evicts key 1       -> get(1) = -1, get(3) = 3, get(4) = 4
 *
 * DESIGN  (HashMap plus doubly linked list)
 *   Map<Integer,Node> cache   key -> its node, so lookup is O(1).
 *   Doubly linked list        usage order, head = most recently used, tail = least.
 *   Node                      key, value, prev, next. It stores the key as well as the
 *                             value so eviction can delete the map entry from the tail
 *                             node alone - without the key, eviction would be O(n).
 *   get  map lookup, then moveToHead (unlink, relink at the front).
 *   put  existing key: overwrite the value and moveToHead.
 *        new key: if full, drop the tail from both the list and the map, then addToHead.
 *   This version deliberately uses no dummy sentinel nodes, so head and tail can be null
 *   and unlinking has to branch on four cases.
 *
 * KEY DECISIONS
 *   - Why a doubly linked list? Eviction needs the element at the far end and reordering
 *     needs to unlink a node found by reference. Both are O(1) only with a prev pointer;
 *     a singly linked list would need an O(n) scan to find the predecessor.
 *   - Why not an ArrayList or a queue? Moving an element to the front of an array is
 *     O(n), and a queue cannot reorder an item already inside it.
 *   - Sentinels vs none: with a dummy head and tail, remove() is three lines and never
 *     null-checks. The no-sentinel version saves two objects and costs four branches -
 *     write the sentinel version in an interview, it is far harder to get wrong.
 *   - Fixed: addToHead left the new head's prev pointer dangling at its old predecessor,
 *     so the list was only consistent when walked forwards. Any backwards walk (or a
 *     later sentinel refactor) would have read a stale node. addToHead now clears it.
 *   - Fixed: capacity 0 made the first put dereference a null tail. put is now a no-op
 *     for a non-positive capacity.
 *
 * COMPLEXITY
 *   Time  O(1) for get and put - one hash lookup plus a constant number of relinks
 *   Space O(capacity) for the map entries and the node objects
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why not just LinkedHashMap with accessOrder=true and removeEldestEntry? You can,
 *     and should say so, but the interviewer wants the list built by hand.
 *   - Make it thread-safe: one lock around both ops, or segment the cache by key hash.
 *   - Add a TTL: store an expiry on each node and treat an expired hit as a miss.
 *   - LFU (LC 460) is the standard follow-up: evict by frequency, not recency.
 *
 * RUN
 *   main() runs 3 cases: the LeetCode walkthrough, a capacity-1 cache (every insert
 *   evicts), and an update-in-place case that must NOT evict. Each line prints actual
 *   vs expected, including forwards and backwards views of the list to prove the links
 *   agree in both directions.
 */

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class LRUCache {

    private final int capacity;
    private final Map<Integer, Node> cache;

    /** head = most recently used, tail = least recently used. No dummy nodes. */
    private Node head;
    private Node tail;

    LRUCache(int capacity) {
        this.capacity = capacity;
        this.cache = new HashMap<>(Math.max(1, capacity));
    }

    /** Returns the value and marks the key as most recently used, or -1 if absent. */
    int get(int key) {
        Node node = cache.get(key);
        if (node == null) {
            return -1;
        }
        moveToHead(node);
        return node.value;
    }

    /** Inserts or updates a key, marking it most recently used. */
    void put(int key, int value) {
        if (capacity <= 0) {
            return; // nothing can be cached, and there is no tail to evict
        }
        Node node = cache.get(key);
        if (node != null) {
            // Update in place: the size does not change, so nothing is evicted.
            node.value = value;
            moveToHead(node);
            return;
        }
        if (cache.size() >= capacity) {
            // Evict the least recently used entry. The node carries its own key, which
            // is what makes removing it from the map O(1).
            cache.remove(tail.key);
            remove(tail);
        }
        Node fresh = new Node(key, value);
        addToHead(fresh);
        cache.put(key, fresh);
    }

    private void moveToHead(Node node) {
        if (node == head) {
            return; // already newest
        }
        remove(node);
        addToHead(node);
    }

    private void addToHead(Node node) {
        node.prev = null; // the head has no predecessor - a stale prev here corrupts
        if (head == null) {
            node.next = null;
            head = tail = node; // first node in the list
        } else {
            node.next = head;
            head.prev = node;
            head = node;
        }
    }

    /** Unlinks a node from the list. Four cases because there are no sentinels. */
    private void remove(Node node) {
        if (node == head && node == tail) {
            head = tail = null;
        } else if (node == head) {
            head = head.next;
            head.prev = null;
        } else if (node == tail) {
            tail = tail.prev;
            tail.next = null;
        } else {
            node.prev.next = node.next;
            node.next.prev = node.prev;
        }
    }

    /** Keys walked from head to tail: most recently used first. Demo only. */
    List<Integer> keysNewestFirst() {
        List<Integer> keys = new ArrayList<>();
        for (Node n = head; n != null; n = n.next) {
            keys.add(n.key);
        }
        return keys;
    }

    /** Same list walked backwards via prev. Must be the exact reverse of the above. */
    List<Integer> keysOldestFirst() {
        List<Integer> keys = new ArrayList<>();
        for (Node n = tail; n != null; n = n.prev) {
            keys.add(n.key);
        }
        return keys;
    }
}

class ImportantLRUCacheMain {

    public static void main(String[] args) {
        // ---- case 1: the LeetCode walkthrough -----------------------------------
        LRUCache cache = new LRUCache(2);
        cache.put(1, 1);
        cache.put(2, 2);
        print("case 1 get(1)", cache.get(1), 1);
        print("case 1 order newest first", cache.keysNewestFirst(), "[1, 2]");
        cache.put(3, 3);                       // evicts key 2 (least recently used)
        print("case 1 get(2) after evict", cache.get(2), -1);
        cache.put(4, 4);                       // evicts key 1
        print("case 1 get(1) after evict", cache.get(1), -1);
        print("case 1 get(3)", cache.get(3), 3);
        print("case 1 get(4)", cache.get(4), 4);
        // 4 was read last, so it is newest; walking back from the tail must mirror it.
        print("case 1 order newest first", cache.keysNewestFirst(), "[4, 3]");
        print("case 1 order oldest first", cache.keysOldestFirst(), "[3, 4]");

        // ---- case 2: edge - capacity 1, every insert evicts ----------------------
        LRUCache tiny = new LRUCache(1);
        tiny.put(1, 100);
        print("case 2 get(1)", tiny.get(1), 100);
        tiny.put(2, 200);                      // evicts key 1
        print("case 2 get(1) after evict", tiny.get(1), -1);
        print("case 2 get(2)", tiny.get(2), 200);
        print("case 2 order", tiny.keysNewestFirst(), "[2]");

        // ---- case 3: tricky - updating an existing key must not evict ------------
        LRUCache upd = new LRUCache(2);
        upd.put(1, 1);
        upd.put(2, 2);
        upd.put(1, 11);                        // update, not insert: still 2 entries
        print("case 3 get(1) updated", upd.get(1), 11);
        print("case 3 get(2) survived", upd.get(2), 2);
        // get(2) just ran, so 2 is newest and 1 is the eviction candidate.
        upd.put(3, 3);
        print("case 3 get(1) after evict", upd.get(1), -1);
        print("case 3 order newest first", upd.keysNewestFirst(), "[3, 2]");
        print("case 3 order oldest first", upd.keysOldestFirst(), "[2, 3]");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

class Node {
    int key;
    int value;
    Node prev;
    Node next;

    Node(int key, int value) {
        this.key = key;
        this.value = value;
    }
}

/*
 * =====================================================================
 *  Time Based Key-Value Store             LeetCode 981 | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Design a store where set(key, value, timestamp) records a value for a key at a
 *   point in time, and get(key, timestamp) returns the value written at the LARGEST
 *   stored timestamp that is <= the queried one, or "" if there is none.
 *   Timestamps passed to set are strictly increasing per key.
 *
 * EXAMPLE
 *   set("foo", "bar", 1) get("foo", 1) -> "bar"    exact hit
 *   get("foo", 3) -> "bar"    nothing newer than 1 yet, so the value at 1 still holds
 *   set("foo", "bar2", 4) get("foo", 5) -> "bar2"   largest stamp <= 5 is 4
 *   get("foo", 0) -> ""       every stored stamp is newer than the query
 *
 * DESIGN  (TreeMap floorKey per key)
 *   Map<String, TreeMap<Integer,String>> store
 *     outer HashMap   key -> that key's own timeline, so keys never interfere.
 *     inner TreeMap   timestamp -> value, kept sorted by timestamp.
 *   set  store.computeIfAbsent(key, ...).put(timestamp, value)  - one sorted insert.
 *   get  floorKey(timestamp) is exactly "greatest key <= timestamp", returning null
 *        when the timeline starts after the query; then read that entry's value.
 *
 * KEY DECISIONS
 *   - Why a TreeMap and not a HashMap? A point-in-time read is a RANGE question, not an
 *     equality one. A HashMap can only answer "is this exact stamp present".
 *   - floorKey vs the neighbours: floor is <= (what we want), lower is strictly <,
 *     ceiling is >=, higher is strictly >. Picking the wrong one is the classic slip.
 *   - A timeline per key, not one global sorted map: a single map would force get to
 *     skip past other keys' entries, turning an O(log n) read into a scan.
 *   - Because set's timestamps increase per key, the timeline is append-only. That is
 *     what makes the array-plus-binary-search variant (see the follow-ups, and
 *     C07_SnapshotArray) equivalent and O(1) to add.
 *
 * COMPLEXITY
 *   Time  set O(log m), get O(log m), where m is the number of writes for that key
 *   Space O(total writes) - every (timestamp, value) pair is kept, nothing is merged
 *
 * INTERVIEW FOLLOW-UPS
 *   - No TreeMap allowed: keep an ArrayList per key and hand-roll the floor with binary
 *     search - the appends stay sorted for free. (SnapshotArray, LC 1146, is that form.)
 *   - Unsorted or out-of-order timestamps: TreeMap still works, the array version breaks.
 *   - Bound the memory: evict stamps older than a retention window, or snapshot-compact.
 *   - Concurrent readers and writers: ConcurrentSkipListMap gives the same floorKey.
 *
 * RUN
 *   main() runs 3 cases: the LeetCode walkthrough, edge cases (unknown key, and a query
 *   before the first write), and a tricky case with two independent keys plus an
 *   overwrite at an already-used timestamp. Each line prints actual vs expected.
 */

import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

class TimeBasedKeyValueStore {

    /** key -> (timestamp -> value), sorted by timestamp so a floor query is O(log m). */
    private final Map<String, TreeMap<Integer, String>> store;

    public TimeBasedKeyValueStore() {
        store = new HashMap<>();
    }

    /** Stores value for key at the given timestamp. */
    public void set(String key, String value, int timestamp) {
        store.computeIfAbsent(key, k -> new TreeMap<>()).put(timestamp, value);
    }

    /**
     * Returns the value written at the largest timestamp <= the given one,
     * or "" when the key is unknown or its timeline starts later.
     */
    public String get(String key, int timestamp) {
        TreeMap<Integer, String> timeline = store.get(key);
        if (timeline == null) {
            return "";
        }
        // floorKey = greatest stored stamp <= timestamp, or null if there is none.
        Integer at = timeline.floorKey(timestamp);
        return at == null ? "" : timeline.get(at);
    }

    public static void main(String[] args) {
        // ---- case 1: the LeetCode walkthrough -----------------------------------
        TimeBasedKeyValueStore timeMap = new TimeBasedKeyValueStore();
        timeMap.set("foo", "bar", 1);
        print("case 1 get(foo, 1)", timeMap.get("foo", 1), "bar");
        // Nothing newer exists yet, so the value written at stamp 1 is still current.
        print("case 1 get(foo, 3)", timeMap.get("foo", 3), "bar");
        timeMap.set("foo", "bar2", 4);
        print("case 1 get(foo, 4)", timeMap.get("foo", 4), "bar2");
        print("case 1 get(foo, 5)", timeMap.get("foo", 5), "bar2");
        // A read between the two writes must still see the older value.
        print("case 1 get(foo, 3) again", timeMap.get("foo", 3), "bar");

        // ---- case 2: edge - nothing to return -----------------------------------
        print("case 2 get(foo, 0) before first write", timeMap.get("foo", 0), "");
        print("case 2 get(missing, 10) unknown key", timeMap.get("missing", 10), "");

        // ---- case 3: tricky - two keys, and an overwrite at the same stamp -------
        TimeBasedKeyValueStore multi = new TimeBasedKeyValueStore();
        multi.set("a", "a1", 1);
        multi.set("b", "b1", 2);
        multi.set("a", "a2", 5);
        // Keys have independent timelines: b's write at 2 never shadows a's write at 1.
        print("case 3 get(a, 4)", multi.get("a", 4), "a1");
        print("case 3 get(b, 4)", multi.get("b", 4), "b1");
        print("case 3 get(b, 1) before b's first write", multi.get("b", 1), "");
        multi.set("a", "a1-fixed", 1);   // same stamp: the TreeMap entry is replaced
        print("case 3 get(a, 1) after overwrite", multi.get("a", 1), "a1-fixed");
        print("case 3 get(a, 9) still newest", multi.get("a", 9), "a2");
    }

    /** Quotes the strings so an empty result is visible rather than blank. */
    private static void print(String label, String actual, String expected) {
        System.out.println(label + ": \"" + actual + "\"   expected \"" + expected + "\"");
    }
}

/*
 * =====================================================================
 *  Snapshot Array                                 LeetCode 1146 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Implement an array of the given length, all zeros to start, supporting
 *   set(index, val), snap() which freezes the current contents and returns an
 *   increasing snapshot id, and get(index, snapId) which reads the value that
 *   index held at the time of that snapshot. Up to ~50k of each call.
 *
 * EXAMPLE
 *   new SnapshotArray(3); set(0, 5); snap() -> 0; set(0, 6)
 *   get(0, 0) -> 5    the frozen value, not the current 6
 *   index 1 was never written, so get(1, 0) -> 0
 *
 * DESIGN  (per-index version list plus binary search)
 *   List<Version>[] history   one append-only timeline per index, each Version being
 *                             (snapId, val) meaning "from this snapshot on, the value
 *                             was val". Each list is seeded with (0, 0) for the zeros.
 *   int currentSnapId         the snapshot being written into right now.
 *   set   if the newest version already belongs to the current snapshot, overwrite it
 *         in place; otherwise append a new version. So one snapshot leaves at most one
 *         version per index, no matter how many times it is written.
 *   snap  return currentSnapId, then increment. O(1) - nothing is copied.
 *   get   binary search that index's timeline for the largest snapId <= the query,
 *         which is the version in force at that snapshot.
 *
 * KEY DECISIONS
 *   - Why not copy the whole array on snap()? That is O(length) per snapshot and blows
 *     up to 50k * 50k cells. Recording only what CHANGED makes the cost proportional to
 *     the number of writes, not to snapshots times length.
 *   - Why per index rather than one global change log? A read then has to hunt for the
 *     right index; a timeline per index makes the binary search land directly.
 *   - The seed version (0, 0) is what lets get() skip a null check: the search can
 *     never fall off the left end, because snapshot 0 always has an entry.
 *   - Same "largest stamp <= query" question as TimeBasedKeyValueStore (LC 981). There
 *     it is TreeMap.floorKey; here the lists are append-only, so a plain ArrayList plus
 *     binary search is cheaper and this is the hand-rolled form of floorKey.
 *
 * COMPLEXITY
 *   Time  set O(1) amortised, snap O(1), get O(log v) with v = versions at that index
 *   Space O(length + number of set calls) - one seed version each, plus one per change
 *
 * INTERVIEW FOLLOW-UPS
 *   - Delete a snapshot / cap retention: needs a refcount per snapshot before pruning.
 *   - Range queries inside a snapshot: layer a persistent segment tree instead.
 *   - Writes far outnumber reads - would you still version? Copy-on-write per block is
 *     the usual answer, trading read cost for fewer objects.
 *   - What if snapshot ids could be requested out of order, or reused? The append-only
 *     assumption breaks and each timeline has to become a TreeMap.
 *
 * RUN
 *   main() runs 3 cases: the LeetCode example, edge cases (a never-written index and a
 *   snapshot taken with no writes at all), and a tricky case showing that repeated sets
 *   inside one snapshot collapse to a single stored version. Each line prints actual
 *   vs expected.
 */

import java.util.ArrayList;
import java.util.List;

class SnapshotArray {

    /** One entry in an index's timeline: the value in force from snapId onwards. */
    private static class Version {
        final int snapId;
        int val;

        Version(int snapId, int val) {
            this.snapId = snapId;
            this.val = val;
        }
    }

    private final List<Version>[] history;
    private int currentSnapId;

    @SuppressWarnings("unchecked") // no generic array literals in Java; the casts are safe
    public SnapshotArray(int length) {
        history = (List<Version>[]) new List[length];
        for (int i = 0; i < length; i++) {
            history[i] = new ArrayList<>();
            // Seed every index with 0 at snapshot 0 so get() always finds something.
            history[i].add(new Version(0, 0));
        }
        currentSnapId = 0;
    }

    public void set(int index, int val) {
        List<Version> timeline = history[index];
        Version newest = timeline.get(timeline.size() - 1);
        if (newest.snapId == currentSnapId) {
            // Still inside the same snapshot - no one can observe the old value.
            newest.val = val;
        } else {
            timeline.add(new Version(currentSnapId, val));
        }
    }

    /** Freezes the current state and returns its id. O(1): nothing is copied. */
    public int snap() {
        return currentSnapId++;
    }

    /** Value at index as of snapId: the newest version with version.snapId <= snapId. */
    public int get(int index, int snapId) {
        List<Version> timeline = history[index];
        int lo = 0;
        int hi = timeline.size() - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (timeline.get(mid).snapId <= snapId) {
                lo = mid + 1;  // this one qualifies; look for a later one
            } else {
                hi = mid - 1;
            }
        }
        // hi settles on the last qualifying version, and is never -1 thanks to the
        // seed version at snapshot 0.
        return timeline.get(hi).val;
    }

    /** How many versions this index has actually stored. Demo only. */
    int versionCount(int index) {
        return history[index].size();
    }

    public static void main(String[] args) {
        // ---- case 1: the LeetCode example ---------------------------------------
        SnapshotArray arr = new SnapshotArray(3);
        arr.set(0, 5);
        int snap0 = arr.snap();
        print("case 1 snap()", snap0, 0);
        arr.set(0, 6);                       // lands in snapshot 1, not 0
        print("case 1 get(0, snap0)", arr.get(0, snap0), 5);
        print("case 1 get(1, snap0) never written", arr.get(1, snap0), 0);
        int snap1 = arr.snap();
        print("case 1 snap()", snap1, 1);
        print("case 1 get(0, snap1)", arr.get(0, snap1), 6);
        print("case 1 get(0, snap0) unchanged", arr.get(0, snap0), 5);

        // ---- case 2: edge - empty snapshot and an untouched index ---------------
        SnapshotArray edge = new SnapshotArray(3);
        int e0 = edge.snap();                // snapshot of an all-zero array
        print("case 2 get(2, e0)", edge.get(2, e0), 0);
        edge.set(2, 42);
        int e1 = edge.snap();
        print("case 2 get(2, e0) still historical", edge.get(2, e0), 0);
        print("case 2 get(2, e1)", edge.get(2, e1), 42);
        int e2 = edge.snap();                // no writes between e1 and e2
        print("case 2 get(2, e2) carries forward", edge.get(2, e2), 42);
        print("case 2 versions at index 2", edge.versionCount(2), 2);

        // ---- case 3: tricky - repeated writes inside one snapshot collapse -------
        SnapshotArray collapse = new SnapshotArray(2);
        collapse.set(0, 5);
        collapse.set(0, 6);
        collapse.set(0, 7);                  // three writes, still snapshot 0
        print("case 3 versions after 3 writes", collapse.versionCount(0), 1);
        int c0 = collapse.snap();
        collapse.set(0, 8);
        collapse.set(0, 9);                  // append once, then overwrite in place
        print("case 3 versions after 2 more writes", collapse.versionCount(0), 2);
        print("case 3 get(0, c0)", collapse.get(0, c0), 7);
        int c1 = collapse.snap();
        print("case 3 get(0, c1)", collapse.get(0, c1), 9);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Stock Price Fluctuation                       LeetCode 2034 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   A stream of (timestamp, price) records arrives out of order, and a record for a
 *   timestamp already seen is a CORRECTION that overwrites the old price. Support
 *   update(ts, price), current() (price at the largest timestamp seen), maximum() and
 *   minimum() over the corrected prices.
 *
 * EXAMPLE
 *   update(1, 10), update(2, 5)  ->  current = 5, maximum = 10, minimum = 5
 *   update(1, 3)                 ->  maximum = 5   because ts 1 is now 3, not 10
 *   update(4, 2)                 ->  minimum = 2   and current = 2 (ts 4 is newest)
 *
 * DESIGN
 *   Price               immutable (timestamp, price) pair -- one recorded reading.
 *   timestampToPrice    HashMap ts -> its CURRENT Price. The single source of truth;
 *                       the heaps are only caches of it.
 *   minHeap / maxHeap   PriorityQueue<Price> by price. A correction pushes a new Price
 *                       and leaves the old one behind, because a heap cannot delete an
 *                       interior element in better than O(n).
 *   latestTimestamp     running max of all timestamps, so current() is O(1).
 *
 * KEY DECISIONS
 *   - Lazy deletion: update() only pushes. Cleanup is paid by the next query that trips
 *     over a stale top.
 *   - Validity test on peek: (ts, p) is live only if timestampToPrice.get(ts).price == p.
 *     Anything else was superseded -- poll it and look again.
 *   - A stale entry can sit right at the top: in maxHeap a superseded higher price
 *     outranks its own correction, so maximum() peeks it first. Only the map check
 *     stops it being returned. Correctness = that check plus the fact that the true
 *     extreme is always present as a live entry, with the stale ones polled off above it.
 *
 * KEY INSIGHT
 *   You cannot cheaply remove an arbitrary element from a binary heap, so do not try.
 *   Keep an authoritative map, let the heap collect garbage, and validate the peek
 *   against the map. Each entry is polled at most once, so the waste amortizes away.
 *
 * COMPLEXITY
 *   Time  update O(log n); current O(1); maximum/minimum O(log n) amortized.
 *   Space O(n) in the number of update() calls -- stale entries linger until evicted.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why not TreeMap<price, count>? True O(log n) worst case and O(distinct) space, at
 *     the cost of a decrement-and-remove on every correction.
 *   - Bound the memory when corrections are frequent (rebuild the heaps on a threshold).
 *   - What changes if timestamps can be deleted, not just corrected?
 *   - Make it thread safe for concurrent updates and queries.
 *
 * RUN
 *   main() runs 3 scenarios (typical stream, correction of an old timestamp, single
 *   record) and prints actual vs expected.
 */

import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

/** One recorded reading. Immutable, so a stale copy left in a heap is harmless. */
class Price {
    final int timestamp;
    final int price;

    Price(int timestamp, int price) {
        this.timestamp = timestamp;
        this.price = price;
    }
}

class StockPrice {

    private int latestTimestamp;

    /** Source of truth: timestamp -> its latest (corrected) price. */
    private final Map<Integer, Price> timestampToPrice = new HashMap<>();

    private final PriorityQueue<Price> minHeap =
            new PriorityQueue<>(Comparator.comparingInt(p -> p.price));

    private final PriorityQueue<Price> maxHeap =
            new PriorityQueue<>(Comparator.comparingInt((Price p) -> p.price).reversed());

    public StockPrice() {
        this.latestTimestamp = 0;
    }

    public void update(int timestamp, int price) {
        Price reading = new Price(timestamp, price);
        timestampToPrice.put(timestamp, reading);   // overwrites any earlier reading
        // The old reading stays in both heaps as garbage; a query will evict it.
        minHeap.add(reading);
        maxHeap.add(reading);
        latestTimestamp = Math.max(latestTimestamp, timestamp);
    }

    public int current() {
        return timestampToPrice.get(latestTimestamp).price;
    }

    public int maximum() {
        return peekLive(maxHeap);
    }

    public int minimum() {
        return peekLive(minHeap);
    }

    /**
     * Discards stale tops until the top entry still matches the map, then returns it.
     * Amortized O(log n): each entry can be discarded only once, ever.
     */
    private int peekLive(PriorityQueue<Price> heap) {
        while (!heap.isEmpty()) {
            Price top = heap.peek();
            if (timestampToPrice.get(top.timestamp).price == top.price) {
                return top.price;
            }
            heap.poll();    // superseded by a correction
        }
        return -1;          // only reachable if no update() has happened yet
    }
}

class StockPriceFluctuation {

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // ---- case 1: typical stream, no corrections yet -------------------
        StockPrice stock = new StockPrice();
        stock.update(1, 10);
        stock.update(2, 5);
        print("case 1 current", stock.current(), 5);
        print("case 1 maximum", stock.maximum(), 10);
        print("case 1 minimum", stock.minimum(), 5);

        // ---- case 2: correction of an OLD timestamp (the whole point) -----
        stock.update(1, 3);                     // ts 1 was 10, is now 3
        print("case 2 maximum", stock.maximum(), 5);    // the 10 is now garbage
        print("case 2 minimum", stock.minimum(), 3);
        print("case 2 current", stock.current(), 5);    // ts 2 is still the newest
        stock.update(4, 2);                     // newest timestamp, new global min
        print("case 2 minimum after ts4", stock.minimum(), 2);
        print("case 2 current after ts4", stock.current(), 2);

        // ---- case 3: edge case, a single record corrected twice -----------
        StockPrice single = new StockPrice();
        single.update(7, 100);
        print("case 3 max == min", single.maximum() + "/" + single.minimum(), "100/100");
        single.update(7, 50);
        print("case 3 after correction", single.maximum() + "/" + single.minimum(), "50/50");
        print("case 3 current", single.current(), 50);
    }
}

/*
 * =====================================================================
 *  Design a Food Rating System                   LeetCode 2353 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Parallel arrays foods, cuisines and ratings describe n dishes; each food name is
 *   unique and belongs to exactly one cuisine. Support changeRating(food, newRating) and
 *   highestRated(cuisine), which returns the best-rated food of that cuisine, breaking
 *   ties by the lexicographically smaller NAME.
 *
 * EXAMPLE
 *   foods = [kimchi, miso, sushi, ramen], cuisines = [korean, japanese x3],
 *   ratings = [9, 12, 8, 15] highestRated("japanese")          ->  ramen   (15 is the best)
 *   changeRating("ramen", 10)         ->  miso now leads with 12
 *   miso and sushi both 16            ->  miso, because "miso" < "sushi"
 *
 * DESIGN
 *   Food              immutable record (name, cuisine, rating) -- one snapshot of a dish.
 *   nameToFood        HashMap name -> its CURRENT Food. The single source of truth.
 *   cuisineToFoods    HashMap cuisine -> PriorityQueue<Food>, one heap PER CUISINE, so a
 *                     query never looks at dishes of another cuisine.
 *   Heap ordering     rating descending, then name ascending -- the tie-break is a
 *                     property of the structure, not of the query.
 *
 * KEY DECISIONS
 *   - Lazy deletion: changeRating() pushes a new snapshot and leaves the old one in the
 *     heap, since a PriorityQueue cannot remove an interior element in better than O(n).
 *   - Validity test on peek: a snapshot is live only if
 *     nameToFood.get(top.name()).rating() == top.rating(). Otherwise poll and retry.
 *   - Integer.compare / String.compareTo instead of subtraction, so the comparator stays
 *     correct for ratings near Integer.MAX_VALUE.
 *
 * KEY INSIGHT
 *   Group first, then apply lazy deletion inside each group: partitioning by cuisine
 *   turns one global "find the best" into many small ones. The two-level comparator is
 *   where candidates drop points -- state the tie-break out loud before writing the heap.
 *
 * COMPLEXITY
 *   Time  constructor O(n log n); changeRating O(log n); highestRated O(log n) amortized.
 *   Space O(n + c) for n dishes and c changeRating calls, since stale snapshots linger.
 *
 * INTERVIEW FOLLOW-UPS
 *   - TreeSet<Food> per cuisine with eager removal: true O(log n) worst case, O(n) space.
 *   - Return the top k foods of a cuisine instead of just the best.
 *   - Bound memory when ratings churn: rebuild a heap past 2x the live dish count.
 *   - Make changeRating and highestRated safe under concurrent callers.
 *
 * RUN
 *   main() runs 3 scenarios (typical, a rating tie that exercises the name tie-break,
 *   and a single-dish cuisine) and prints actual vs expected.
 */

import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

class DesignAFoodRatingSystem {

    /** One snapshot of a dish. A record is immutable, so stale copies are harmless. */
    private record Food(String name, String cuisine, int rating) {
    }

    /** cuisine -> max-heap of snapshots (rating desc, then name asc). */
    private final Map<String, PriorityQueue<Food>> cuisineToFoods = new HashMap<>();

    /** food name -> its current snapshot. This is the authority the heaps are checked against. */
    private final Map<String, Food> nameToFood = new HashMap<>();

    public DesignAFoodRatingSystem(String[] foods, String[] cuisines, int[] ratings) {
        for (int i = 0; i < foods.length; i++) {
            Food food = new Food(foods[i], cuisines[i], ratings[i]);
            nameToFood.put(food.name(), food);
            heapFor(food.cuisine()).add(food);
        }
    }

    /** Lazily creates the per-cuisine heap with the two-level ordering. */
    private PriorityQueue<Food> heapFor(String cuisine) {
        return cuisineToFoods.computeIfAbsent(cuisine, k -> new PriorityQueue<>((a, b) -> {
            int byRating = Integer.compare(b.rating(), a.rating());   // higher rating first
            if (byRating != 0) {
                return byRating;
            }
            return a.name().compareTo(b.name());                      // tie -> smaller name
        }));
    }

    /** O(log n): push a new snapshot, leave the old one behind as garbage. */
    public void changeRating(String food, int newRating) {
        String cuisine = nameToFood.get(food).cuisine();
        Food updated = new Food(food, cuisine, newRating);
        nameToFood.put(food, updated);
        heapFor(cuisine).add(updated);
    }

    /** O(log n) amortized: drop superseded snapshots, then trust the top. */
    public String highestRated(String cuisine) {
        PriorityQueue<Food> heap = cuisineToFoods.get(cuisine);
        if (heap == null) {
            return null;    // cuisine never seen
        }
        while (!heap.isEmpty()) {
            Food top = heap.peek();
            Food live = nameToFood.get(top.name());
            if (top.rating() == live.rating()) {
                return top.name();
            }
            heap.poll();    // this snapshot was superseded by a changeRating
        }
        return null;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        String[] foods = {"kimchi", "miso", "sushi", "ramen"};
        String[] cuisines = {"korean", "japanese", "japanese", "japanese"};
        int[] ratings = {9, 12, 8, 15};
        DesignAFoodRatingSystem system = new DesignAFoodRatingSystem(foods, cuisines, ratings);

        // ---- case 1: typical -- best dish, then a downgrade of the leader ----
        print("case 1 japanese", system.highestRated("japanese"), "ramen");
        system.changeRating("ramen", 10);           // 15 -> 10, ramen loses the lead
        print("case 1 after downgrade", system.highestRated("japanese"), "miso");
        system.changeRating("sushi", 16);           // 8 -> 16, the laggard takes over
        print("case 1 after upgrade", system.highestRated("japanese"), "sushi");

        // ---- case 2: tie on rating -> lexicographically smaller name wins ----
        system.changeRating("miso", 16);            // miso and sushi are both 16 now
        print("case 2 tie 16/16", system.highestRated("japanese"), "miso");

        // ---- case 3: edge case -- a cuisine with exactly one dish ----
        print("case 3 korean", system.highestRated("korean"), "kimchi");
        system.changeRating("kimchi", 1);           // still the only korean dish
        print("case 3 korean downgraded", system.highestRated("korean"), "kimchi");
        print("case 3 unknown cuisine", system.highestRated("thai"), "null");
    }
}

/*
 * =====================================================================
 *  Design Snake Game                              LeetCode 353 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   A snake starts at cell (0, 0) of a height x width grid, one cell long. Food appears
 *   one piece at a time at the positions in food[], in that exact order. Each move("U" |
 *   "D" | "L" | "R") shifts the head one cell; eating the current food grows the snake by
 *   one and scores a point. Return the score, or -1 once the snake leaves the board or
 *   bites its own body -- and -1 for every move after that.
 *
 * EXAMPLE
 *   width 3, height 2, food [[1,2],[0,1]]; moves R D R U L U -> 0, 0, 1, 1, 2, -1
 *   (the last move walks off the top edge)
 *   width 3, height 3, food [[1,0],[1,1]]; moves D R L -> 1, 2, -1
 *   (after growing to length 3 the snake reverses into its own neck)
 *
 * DESIGN
 *   Cell encoding     (row, col) is stored as the single int row * width + col, so the
 *                     body needs no Point class.
 *   snake: Deque      head at the FIRST end, tail at the LAST: addFirst() each move,
 *                     pollLast() when not growing. Only a deque makes both ends O(1).
 *   occupied: Set     the same cells, kept in sync, so the self-bite test is O(1).
 *   foodIndex         pieces eaten so far; food[foodIndex] is the only one on the board.
 *   score             doubles as the game-over sentinel -- once -1, move() short-circuits.
 *
 * KEY DECISIONS
 *   - Remove the tail BEFORE testing for a self-bite: the tail vacates its cell in the
 *     same move, so stepping onto the old tail cell is legal. Testing first would report
 *     a phantom collision on every tight turn.
 *   - Do not remove the tail when eating -- that is precisely what "grow by one" means.
 *   - Two structures for one list of cells, because neither a deque nor a set alone gives
 *     both ordered ends and O(1) membership.
 *
 * KEY INSIGHT
 *   The snake IS a queue of cells: the head is an enqueue, the tail a dequeue, and growing
 *   just means skipping the dequeue. Pair the deque with a hash set for O(1) membership
 *   and flatten each cell to row * width + col. The difficulty is the ORDER of the
 *   checks, not the data structures.
 *
 * COMPLEXITY
 *   Time  O(1) per move -- one push, at most one pop, constant-time set work.
 *   Space O(min(width * height, food.length + 1)), held twice (deque and set).
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why is stepping onto the current tail cell safe, and when is it not?
 *   - Support food appearing at random free cells instead of a fixed list.
 *   - Add the rule "the snake may not reverse straight back": track the last direction.
 *   - Wrap-around (torus) edges instead of walls: which check disappears?
 *
 * RUN
 *   main() runs 3 games (typical walkthrough, a self-bite, and a 1x1 board where the
 *   first move is fatal) and prints actual vs expected.
 */

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.Set;

class DesignSnakeGame {
    private final int width;
    private final int height;
    private final int[][] food;

    private int foodIndex = 0;
    private int score = 0;                  // -1 also means "game over"

    private final Deque<Integer> snake;     // head first, tail last
    private final Set<Integer> occupied;    // same cells, for O(1) self-bite checks

    public DesignSnakeGame(int width, int height, int[][] food) {
        this.width = width;
        this.height = height;
        this.food = food;
        this.snake = new ArrayDeque<>();
        this.occupied = new HashSet<>();
        snake.addLast(encode(0, 0));        // the snake starts at the top-left cell
        occupied.add(encode(0, 0));
    }

    /** Packs a cell into one int so the body can live in int collections. */
    private int encode(int row, int col) {
        return row * width + col;
    }

    public int move(String direction) {
        if (score == -1) {
            return -1;                      // already dead; every later move is -1 too
        }

        int head = snake.peekFirst();
        int row = head / width;
        int col = head % width;

        switch (direction) {
            case "U" -> row--;              // row 0 is the TOP row, so up decreases row
            case "D" -> row++;
            case "L" -> col--;
            case "R" -> col++;
            default -> throw new IllegalArgumentException("Invalid direction: " + direction);
        }

        if (row < 0 || row >= height || col < 0 || col >= width) {
            score = -1;                     // walked off the board
            return -1;
        }

        // Only food[foodIndex] is on the board right now.
        boolean eating = foodIndex < food.length
                && food[foodIndex][0] == row
                && food[foodIndex][1] == col;
        if (eating) {
            score++;
            foodIndex++;
        } else {
            // Not growing: the tail vacates its cell BEFORE the collision test below,
            // which is what makes a tight turn onto the old tail cell legal.
            occupied.remove(snake.pollLast());
        }

        int newHead = encode(row, col);
        if (occupied.contains(newHead)) {
            score = -1;                     // bit its own body
            return -1;
        }

        snake.addFirst(newHead);
        occupied.add(newHead);
        return score;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // ---- case 1: typical walkthrough on a 3 x 2 board -----------------
        DesignSnakeGame game = new DesignSnakeGame(3, 2, new int[][]{{1, 2}, {0, 1}});
        print("case 1 move R", game.move("R"), 0);
        print("case 1 move D", game.move("D"), 0);
        print("case 1 move R", game.move("R"), 1);   // eats food at (1,2)
        print("case 1 move U", game.move("U"), 1);
        print("case 1 move L", game.move("L"), 2);   // eats food at (0,1)
        print("case 1 move U", game.move("U"), -1);  // off the top edge
        print("case 1 move after death", game.move("D"), -1);

        // ---- case 2: tricky -- grow to length 3, then reverse into itself --
        DesignSnakeGame biter = new DesignSnakeGame(3, 3, new int[][]{{1, 0}, {1, 1}});
        print("case 2 move D", biter.move("D"), 1);  // eats (1,0), length 2
        print("case 2 move R", biter.move("R"), 2);  // eats (1,1), length 3
        print("case 2 move L", biter.move("L"), -1); // back onto its own neck

        // ---- case 3: edge case -- 1 x 1 board, nowhere legal to go --------
        DesignSnakeGame tiny = new DesignSnakeGame(1, 1, new int[][]{});
        print("case 3 move R", tiny.move("R"), -1);
    }
}

/*
 * =====================================================================
 *  Complete Binary Tree Inserter                  LeetCode 919 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Given the root of a COMPLETE binary tree (every level full except possibly the last,
 *   and the last filled left to right with no gaps), support insert(val), which adds a
 *   node so the tree stays complete and returns the value of the new node's PARENT, and
 *   get_root(), which returns the root.
 *
 * EXAMPLE
 *   start [1, 2, 3] insert(4) -> 2    4 becomes the left child of 2
 *   insert(5) -> 2    5 becomes the right child of 2
 *   insert(6) -> 3    tree is now [1, 2, 3, 4, 5, 6]
 *   edge case: start [1]; insert(2) -> 1, insert(3) -> 1, insert(4) -> 2
 *
 * DESIGN
 *   TreeNode          plain binary node (val, left, right).
 *   root              kept so get_root() is O(1).
 *   q: Queue          candidate PARENTS in level order -- nodes that may still have a
 *                     free child slot. The front is always the leftmost node on the
 *                     deepest incomplete level, which is exactly where the next node goes.
 *   Constructor       seeds the queue with the root ONLY. Children are enqueued lazily,
 *                     the moment their parent is found full, so no up-front BFS is needed
 *                     and level order is still preserved.
 *
 * KEY DECISIONS
 *   - insert() loops rather than assuming the front is free: it pops full nodes (both
 *     children present), enqueuing their children, until the front has a free slot.
 *   - After filling a node's RIGHT child the node is deliberately left in the queue. It
 *     is full now, so the next insert() pops it on its first iteration and enqueues its
 *     children then. Deferring costs nothing and keeps one exit path per branch.
 *   - Children are enqueued left then right; that is what keeps the tree complete.
 *
 * KEY INSIGHT
 *   "Complete" means the next free slot is the leftmost one on the deepest level, and a
 *   BFS queue hands you that node for free. Only nodes with a free child slot need to be
 *   retained; a full node is discarded forever once its children are enqueued, which is
 *   why every node is touched at most once.
 *
 * COMPLEXITY
 *   Time  insert O(1) amortized -- each node is enqueued once and polled once overall;
 *         get_root O(1).
 *   Space O(n) worst case, though in steady state the queue only holds the deepest level.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Do it with no queue: the path to 1-based index i is i's binary representation
 *     (0 = left, 1 = right) -- O(log n) insert, O(1) extra space.
 *   - Support deleting the last node (the array-backed heap's siftDown problem).
 *   - How does this relate to a binary heap stored in an array?
 *   - Prove the front of the queue is always the correct parent.
 *
 * RUN
 *   main() runs 3 cases (typical 3-node start, single-node start, and a 4-node start that
 *   forces the queue to skip a full node) and prints actual vs expected.
 */

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;

    TreeNode() {
    }

    TreeNode(int val) {
        this.val = val;
    }

    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class CBTInserter {

    TreeNode root;
    Queue<TreeNode> q;

    public CBTInserter(TreeNode root) {
        this.root = root;
        this.q = new LinkedList<>();
        q.add(root);    // children are enqueued lazily, only when a node turns out full
    }

    public int insert(int val) {
        TreeNode node = new TreeNode(val);
        while (!q.isEmpty()) {
            TreeNode candidate = q.peek();

            if (candidate.left == null) {
                candidate.left = node;      // still has a right slot, so keep it queued
                return candidate.val;
            }
            if (candidate.right == null) {
                candidate.right = node;     // now full; the NEXT insert will pop it
                return candidate.val;
            }
            // Full node: retire it and promote its children as future parents, in order.
            q.poll();
            q.add(candidate.left);
            q.add(candidate.right);
        }
        return -1;      // unreachable for a non-null root
    }

    public TreeNode get_root() {
        return root;
    }

    /** Level-order values, so main() can show the whole tree on one line. */
    private static List<Integer> levelOrder(TreeNode root) {
        List<Integer> values = new ArrayList<>();
        if (root == null) {
            return values;
        }
        Queue<TreeNode> queue = new LinkedList<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            values.add(node.val);
            if (node.left != null) {
                queue.add(node.left);
            }
            if (node.right != null) {
                queue.add(node.right);
            }
        }
        return values;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // ---- case 1: typical -- start from [1, 2, 3] ----------------------
        CBTInserter typical = new CBTInserter(new TreeNode(1, new TreeNode(2), new TreeNode(3)));
        print("case 1 insert 4 parent", typical.insert(4), 2);
        print("case 1 insert 5 parent", typical.insert(5), 2);
        print("case 1 insert 6 parent", typical.insert(6), 3);
        print("case 1 tree", levelOrder(typical.get_root()), "[1, 2, 3, 4, 5, 6]");

        // ---- case 2: edge case -- start from a single node ----------------
        CBTInserter single = new CBTInserter(new TreeNode(1));
        print("case 2 insert 2 parent", single.insert(2), 1);
        print("case 2 insert 3 parent", single.insert(3), 1);
        print("case 2 insert 4 parent", single.insert(4), 2);
        print("case 2 tree", levelOrder(single.get_root()), "[1, 2, 3, 4]");

        // ---- case 3: tricky -- last level partly filled, so the queue must
        //      skip node 2's left slot and land on its right slot first -----
        TreeNode root = new TreeNode(1,
                new TreeNode(2, new TreeNode(4), null),
                new TreeNode(3));
        CBTInserter partial = new CBTInserter(root);
        print("case 3 insert 5 parent", partial.insert(5), 2);   // fills 2's right
        print("case 3 insert 6 parent", partial.insert(6), 3);   // 2 is full, move to 3
        print("case 3 insert 7 parent", partial.insert(7), 3);
        print("case 3 insert 8 parent", partial.insert(8), 4);   // new level starts at 4
        print("case 3 tree", levelOrder(partial.get_root()), "[1, 2, 3, 4, 5, 6, 7, 8]");
    }
}

/*
 * =====================================================================
 *  Design File System                            LeetCode 1166 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Map unix-style paths to integer values. createPath(path, value) succeeds only if the
 *   path is well formed ("/a/b", never "/" or ""), does NOT already exist, and its PARENT
 *   path already exists; it returns whether it succeeded. get(path) returns the value at
 *   that path, or -1 if the path does not exist.
 *
 * EXAMPLE
 *   createPath("/a", 1)    -> true     get("/a")   -> 1
 *   createPath("/a/b", 2)  -> true     get("/a/b") -> 2
 *   createPath("/c/d", 3)  -> false    parent "/c" was never created
 *   createPath("/a/b", 4)  -> false    already exists; the stored 2 is untouched
 *   createPath("/", 9)     -> false    the root is not a creatable path
 *
 * DESIGN
 *   Node          a trie node: children (segment name -> Node) plus an int value. The
 *                 sentinel value -1 means "exists only as a parent", which is also what
 *                 get() must return for a missing path, so one sentinel covers both.
 *   root          an unnamed Node standing for "/"; never a result itself.
 *   Splitting     "/a/b".split("/") is ["", "a", "b"] -- index 0 is always the empty
 *                 string before the leading slash, so every walk starts at i = 1.
 *
 * KEY DECISIONS
 *   - One node per path SEGMENT, not one map entry per full path string. A flat
 *     HashMap<String, Integer> would pass these two operations, but the trie is what
 *     makes the parent-exists rule a single lookup and what ls / mkdir -p build on.
 *   - createPath walks only the PARENT segments (i = 1 .. parts.length - 2) and bails the
 *     moment one is missing; the last segment is handled apart, because it is the one
 *     that must NOT already exist.
 *   - A rejected createPath returns before touching any map, so a failed call leaves the
 *     tree unchanged -- no half-created directories.
 *
 * KEY INSIGHT
 *   A path is not a string, it is a sequence of segments, so store it the way a trie
 *   stores a word: one node per segment. "The parent must exist" then becomes "the walk
 *   must not fall off the trie before the last segment", which is the whole problem.
 *   Recognise this shape whenever the keys share long prefixes.
 *
 * COMPLEXITY
 *   For a path of m segments and total length L:
 *   Time  createPath and get are both O(m) hash lookups, O(L) counting the character
 *         work in split and hashing.
 *   Space O(number of distinct segments across all created paths).
 *
 * INTERVIEW FOLLOW-UPS
 *   - Add remove(path): delete the subtree, and decide whether removing a non-empty
 *     directory is allowed.
 *   - Add ls(path) returning children sorted -- swap HashMap for TreeMap and it is free.
 *   - Trie vs HashMap<String, Integer> on the full path: compare the parent check, a
 *     future ls, and a subtree delete.
 *   - Thread safety: which node do you lock when two creates race on the same parent?
 *
 * RUN
 *   main() runs 3 groups of cases (happy path, the two rejection rules, and malformed or
 *   missing paths) and prints actual vs expected.
 */

import java.util.HashMap;
import java.util.Map;

class DesignFileSystem {

    /** One path segment. value == -1 means "exists as a parent, holds nothing". */
    private static class Node {
        Map<String, Node> children = new HashMap<>();
        int value = -1;
    }

    private final Node root;

    public DesignFileSystem() {
        root = new Node();
    }

    public boolean createPath(String path, int value) {
        // "/" and anything without a leading slash are not creatable paths.
        if (path == null || path.equals("/") || !path.startsWith("/")) {
            return false;
        }

        String[] parts = path.split("/");   // "/a/b" -> ["", "a", "b"], so start at 1
        Node curr = root;

        // Walk the PARENT segments only; every one of them must already exist.
        for (int i = 1; i < parts.length - 1; i++) {
            curr = curr.children.get(parts[i]);
            if (curr == null) {
                return false;               // parent path does not exist
            }
        }

        String last = parts[parts.length - 1];
        if (curr.children.containsKey(last)) {
            return false;                   // path already exists; leave its value alone
        }

        Node created = new Node();
        created.value = value;
        curr.children.put(last, created);
        return true;
    }

    public int get(String path) {
        if (path == null || !path.startsWith("/")) {
            return -1;
        }

        String[] parts = path.split("/");
        Node curr = root;
        for (int i = 1; i < parts.length; i++) {
            curr = curr.children.get(parts[i]);
            if (curr == null) {
                return -1;                  // fell off the trie: path does not exist
            }
        }
        return curr.value;                  // for "/" this is the root's -1
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        DesignFileSystem fs = new DesignFileSystem();

        // ---- case 1: typical -- create a path, then a child of it ---------
        print("case 1 create /a", fs.createPath("/a", 1), true);
        print("case 1 get /a", fs.get("/a"), 1);
        print("case 1 create /a/b", fs.createPath("/a/b", 2), true);
        print("case 1 get /a/b", fs.get("/a/b"), 2);

        // ---- case 2: the two rejection rules ------------------------------
        print("case 2 missing parent /c/d", fs.createPath("/c/d", 3), false);
        print("case 2 get /c", fs.get("/c"), -1);          // nothing was half-created
        print("case 2 duplicate /a/b", fs.createPath("/a/b", 4), false);
        print("case 2 /a/b unchanged", fs.get("/a/b"), 2); // the failed create kept 2

        // ---- case 3: edge cases -- malformed and missing paths ------------
        print("case 3 create root", fs.createPath("/", 9), false);
        print("case 3 get root", fs.get("/"), -1);
        print("case 3 no leading slash", fs.createPath("leetcode", 5), false);
        print("case 3 get deeper than tree", fs.get("/a/b/c"), -1);
        print("case 3 create /a/b/c", fs.createPath("/a/b/c", 6), true);
        print("case 3 get /a/b/c", fs.get("/a/b/c"), 6);
    }
}

/*
 * =====================================================================
 *  LFU Cache                                   LeetCode 460 | Hard  MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Build a fixed-capacity cache where get(key) and put(key, value) are both O(1).
 *   When the cache is full, evict the key with the smallest use count. If several keys
 *   tie on use count, evict the least recently used among them. get returns -1 if absent.
 *   Every get and every put counts as one use of that key.
 *
 * EXAMPLE
 *   cap=2: put(1,1) put(2,2) get(1)=1 put(3,3) -> evicts key 2 (count 1 vs key 1's count 2)
 *   cap=2: put(1,1) put(2,2) get(1) get(2) put(3,3) -> both count 2, so LRU wins: evict 1
 *   cap=0: put(1,1) then get(1) = -1   (nothing can ever be stored)
 *
 * DESIGN  (frequency buckets + minFrequency pointer)
 *   DLLNode           one cache entry: key, value, its use count, and list links.
 *   DoubleLinkedList  an unsorted bucket of nodes that all share one use count.
 *                     addNode pushes at the head, so the tail is always the oldest
 *                     node in that bucket -- that is what makes the LRU tie-break free.
 *   LFUCache          cache        : key -> node            (O(1) lookup)
 *                     frequencyMap : count -> bucket        (O(1) bucket lookup)
 *                     minFrequency : the smallest count that currently has a node
 *
 * KEY DECISIONS
 *   1. A "use" never rebuilds anything: unlink the node from bucket f, bump its count,
 *      push it at the head of bucket f+1. Two pointer fixes, no scan.
 *   2. minFrequency only ever has to move by ONE step, never search. Two facts force it:
 *      - a use of the last node in the min bucket moves that node to min+1, so min+1
 *        is non-empty and is the new minimum;
 *      - inserting a new key gives it count 1, so the minimum is 1 again.
 *      Because of that, a plain int replaces what looks like it needs a sorted structure.
 *   3. Eviction is frequencyMap.get(minFrequency).tail -- least used, and oldest of those.
 *   4. capacity 0 is handled up front; without that guard put would insert then evict itself.
 *
 * COMPLEXITY
 *   Time  O(1)         every operation is a bounded number of map lookups and pointer writes
 *   Space O(capacity)  one node per key, plus one bucket per distinct count in use
 *
 * INTERVIEW FOLLOW-UPS
 *   - How does this differ from LRU (LC 146)? LRU needs one list; LFU needs a list per count.
 *   - Why is a PriorityQueue by count wrong here? Updating a count is O(n) or O(log n), not O(1).
 *   - Make it thread-safe, or shard it: what breaks first? (minFrequency is the shared hot spot.)
 *   - Add aging or a decay factor so a key that was hot an hour ago stops pinning the cache.
 *
 * RUN
 *   main() runs 3 cases (LeetCode sample, the LRU tie-break, capacity 0) and prints
 *   actual vs expected for every call.
 */

import java.util.HashMap;
import java.util.Map;

/** One cache entry. Lives in exactly one frequency bucket at a time. */
class DLLNode {
    int key;
    int val;
    int frequency;
    DLLNode prev;
    DLLNode next;

    DLLNode(int key, int val) {
        this.key = key;
        this.val = val;
        this.frequency = 1; // a node is created by a put, which already counts as one use
    }
}

/**
 * Bucket of nodes that share one use count. Order inside the bucket is recency:
 * head = most recently used, tail = least recently used. That is the LFU tie-break.
 */
class DoubleLinkedList {
    int listSize;
    DLLNode head;
    DLLNode tail;

    /** Push at the head, so this node becomes the most recently used of its bucket. */
    void addNode(DLLNode curNode) {
        curNode.prev = null;
        curNode.next = head; // null when the bucket is empty, which is exactly what we want
        if (head != null) {
            head.prev = curNode;
        } else {
            tail = curNode; // first node in the bucket is both head and tail
        }
        head = curNode;
        listSize++;
    }

    /** Unlink a node we already hold a reference to, in O(1). */
    void removeNode(DLLNode curNode) {
        if (curNode.prev != null) {
            curNode.prev.next = curNode.next;
        } else {
            head = curNode.next; // it was the head
        }
        if (curNode.next != null) {
            curNode.next.prev = curNode.prev;
        } else {
            tail = curNode.prev; // it was the tail
        }
        // Clear the links so a stale pointer can never be followed after a move.
        curNode.prev = null;
        curNode.next = null;
        listSize--;
    }
}

class LFUCache {
    private final int capacity;
    private int curSize = 0;
    private int minFrequency = 0;

    private final Map<Integer, DLLNode> cache = new HashMap<>();
    private final Map<Integer, DoubleLinkedList> frequencyMap = new HashMap<>();

    LFUCache(int capacity) {
        this.capacity = capacity;
    }

    public int get(int key) {
        DLLNode curNode = cache.get(key);
        if (curNode == null) {
            return -1;
        }
        touch(curNode);
        return curNode.val;
    }

    public void put(int key, int value) {
        if (capacity == 0) {
            return; // nothing can be stored; without this guard the code below would evict itself
        }

        DLLNode existing = cache.get(key);
        if (existing != null) {
            existing.val = value;
            touch(existing);
            return;
        }

        if (curSize == capacity) {
            evictLeastFrequent();
        }

        DLLNode newNode = new DLLNode(key, value);
        cache.put(key, newNode);
        bucketFor(1).addNode(newNode);
        minFrequency = 1; // a brand-new key has count 1, so the minimum is 1 again
        curSize++;
    }

    /** Count one more use of this node: move it from bucket f to bucket f + 1. */
    private void touch(DLLNode curNode) {
        int curFreq = curNode.frequency;
        DoubleLinkedList curList = frequencyMap.get(curFreq);
        curList.removeNode(curNode);

        // If we just emptied the minimum bucket, the node we moved is now the rarest,
        // so the new minimum is exactly curFreq + 1 -- never further away than one step.
        if (curFreq == minFrequency && curList.listSize == 0) {
            minFrequency = curFreq + 1;
        }

        curNode.frequency = curFreq + 1;
        bucketFor(curNode.frequency).addNode(curNode);
    }

    /** Drop the oldest node in the least-used bucket. */
    private void evictLeastFrequent() {
        DoubleLinkedList minFreqList = frequencyMap.get(minFrequency);
        DLLNode victim = minFreqList.tail; // least frequently used, and oldest among those
        minFreqList.removeNode(victim);
        cache.remove(victim.key);
        curSize--;
    }

    private DoubleLinkedList bucketFor(int frequency) {
        return frequencyMap.computeIfAbsent(frequency, f -> new DoubleLinkedList());
    }

    // ------------------------------------------------------------------
    // Demo
    // ------------------------------------------------------------------

    private static void check(String label, Object actual, Object expected) {
        boolean ok = String.valueOf(actual).equals(String.valueOf(expected));
        System.out.println(label + " -> actual " + actual + "   expected " + expected
                + (ok ? "   OK" : "   FAIL"));
    }

    public static void main(String[] args) {
        System.out.println("case 1: LeetCode sample, capacity 2");
        LFUCache c1 = new LFUCache(2);
        c1.put(1, 1);
        c1.put(2, 2);
        check("  get(1)", c1.get(1), 1);
        c1.put(3, 3); // key 2 has count 1, key 1 has count 2 -> evict key 2
        check("  get(2) after evict", c1.get(2), -1);
        check("  get(3)", c1.get(3), 3);
        c1.put(4, 4); // keys 1 and 3 both count 2; key 1 is older -> evict key 1
        check("  get(1) after evict", c1.get(1), -1);
        check("  get(3)", c1.get(3), 3);
        check("  get(4)", c1.get(4), 4);

        System.out.println("case 2: tie on count, least recently used loses");
        LFUCache c2 = new LFUCache(2);
        c2.put(1, 1);
        c2.put(2, 2);
        check("  get(1)", c2.get(1), 1); // key 1 count 2
        check("  get(2)", c2.get(2), 2); // key 2 count 2, and now the most recent
        c2.put(3, 3);                    // tie at count 2 -> evict the older one, key 1
        check("  get(1) evicted", c2.get(1), -1);
        check("  get(2) kept", c2.get(2), 2);
        check("  get(3)", c2.get(3), 3);

        System.out.println("case 3: edge cases, capacity 0 and capacity 1");
        LFUCache c3 = new LFUCache(0);
        c3.put(1, 1);
        check("  cap 0, get(1)", c3.get(1), -1);
        check("  cap 0, get(9)", c3.get(9), -1);

        LFUCache c4 = new LFUCache(1);
        c4.put(1, 1);
        c4.put(1, 10); // overwrite, not an insert: nothing is evicted
        check("  cap 1, get(1) overwritten", c4.get(1), 10);
        c4.put(2, 2);  // capacity 1 -> key 1 must go even though it has a high count
        check("  cap 1, get(1) evicted", c4.get(1), -1);
        check("  cap 1, get(2)", c4.get(2), 2);
    }
}

/*
 * =====================================================================
 *  All O`one Data Structure                           LeetCode 432 | Hard
 * =====================================================================
 *
 * PROBLEM
 *   Track a multiset of string keys with four operations, every one in O(1):
 *   inc(key) adds one to the key's count (creating it at 1), dec(key) subtracts one and
 *   removes the key when its count hits 0, getMaxKey() and getMinKey() return ANY key at
 *   the highest / lowest count, or "" when the structure is empty.
 *   Counts are always positive, so "empty" and "count 0" are the same thing.
 *
 * EXAMPLE
 *   inc(hello) inc(hello)         -> max=hello  min=hello        (hello=2)
 *   inc(leet)                     -> max=hello  min=leet         (hello=2, leet=1)
 *   inc(leet) inc(leet)           -> max=leet   min=hello        (hello=2, leet=3)
 *   dec every key down to 0       -> max=""     min=""           (empty again)
 *
 * DESIGN  (two approaches, same interface, both driven from main)
 *   AllOneApi   the shared contract, so one test script runs against both.
 *
 *   1. TwoMaps    keyFreqMap : key  -> count
 *                 freqKeysMap: count -> set of keys at that count (bucket)
 *                 plus tracked minFreq / maxFreq ints.
 *                 Easy to write under time pressure and correct, but NOT strictly O(1):
 *                 when the last key at minFreq is decremented away, the next non-empty
 *                 bucket can be anywhere above, so minFreq has to scan upward.
 *
 *   2. BucketList a doubly linked list of buckets kept sorted by count, with sentinel
 *                 head and tail, plus keyBucketMap : key -> its bucket node.
 *                 min = head.next, max = tail.prev, always, with no scan. True O(1).
 *
 * KEY DECISIONS
 *   1. Store keys grouped BY COUNT, not sorted by count. A hash set per count is enough
 *      because getMaxKey/getMinKey may return any key in the bucket.
 *   2. inc moves a key exactly one bucket up and dec exactly one bucket down. Neighbouring
 *      buckets differ by exactly 1, so in approach 2 the target bucket is either the
 *      adjacent node (reuse it) or a brand-new node spliced in next to the old one.
 *   3. A bucket that loses its last key is unlinked immediately. That is what keeps
 *      head.next and tail.prev meaningful without any cleanup pass.
 *   4. Approach 1's minFreq scan is the whole reason approach 2 exists -- state approach 1
 *      in an interview, name that weakness yourself, then offer the linked list.
 *
 * COMPLEXITY
 *   TwoMaps     Time O(1) for inc / getMax / getMin; dec is O(1) amortised but O(maxCount)
 *               in the worst case when the minimum bucket empties.  Space O(number of keys).
 *   BucketList  Time O(1) worst case for all four operations.
 *               Space O(number of keys + number of distinct counts).
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why not a TreeMap of counts? It gives O(log n), and the question demands O(1).
 *   - Why not a heap? Updating one key's count is O(n) to find it, and both min and max
 *     are needed, which would mean two heaps plus lazy deletion.
 *   - Return the FULL set of keys at the max count instead of any one: same buckets, but
 *     you now hand back the set, so it must not be mutated by the caller.
 *   - Make it thread-safe: the bucket splice is the critical section, not the maps.
 *
 * RUN
 *   main() runs one identical script (build up, tie, sparse counts, drain to empty)
 *   against both implementations and prints actual vs expected for every step.
 *   Ties are legitimately ambiguous, so those lines accept either valid key.
 */

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class AllOne {

    /** Common contract so one main can drive both approaches. */
    interface AllOneApi {
        void inc(String key);

        void dec(String key);

        String getMaxKey();

        String getMinKey();
    }

    // =====================================================================
    // Approach 1: two HashMaps + tracked minFreq / maxFreq
    // =====================================================================
    static class TwoMaps implements AllOneApi {
        private final Map<String, Integer> keyFreqMap = new HashMap<>();       // key  -> frequency
        private final Map<Integer, Set<String>> freqKeysMap = new HashMap<>(); // freq -> keys at it
        private int minFreq = 0; // 0 means "empty"
        private int maxFreq = 0;

        /*
         * Fixed: three bugs that the naive version of this approach always has.
         *  - inserting a new key reset BOTH minFreq and maxFreq to 1, so maxFreq was lost.
         *  - inc() did minFreq++ when the min bucket emptied, but buckets are sparse
         *    (e.g. 1 -> 3), so minFreq could point at a bucket that does not exist -> NPE.
         *  - dec() also did minFreq++ when the min bucket emptied, but a decremented key
         *    moves DOWN, so minFreq must become newFreq, not minFreq + 1.
         */

        @Override
        public void inc(String key) {
            int oldFreq = keyFreqMap.getOrDefault(key, 0);
            int newFreq = oldFreq + 1;
            keyFreqMap.put(key, newFreq);
            freqKeysMap.computeIfAbsent(newFreq, k -> new HashSet<>()).add(key);

            if (oldFreq > 0) {
                removeFromBucket(key, oldFreq);
                // Every other key had freq >= oldFreq. If oldFreq was the min and its bucket
                // is now empty, the new min is exactly newFreq (nothing can sit in between).
                if (oldFreq == minFreq && !freqKeysMap.containsKey(oldFreq)) {
                    minFreq = newFreq;
                }
            } else {
                minFreq = 1; // a brand-new key is always the minimum
            }
            maxFreq = Math.max(maxFreq, newFreq);
        }

        @Override
        public void dec(String key) {
            Integer oldFreq = keyFreqMap.get(key);
            if (oldFreq == null) {
                return; // key does not exist; LeetCode guarantees it does, this is a safety net
            }
            int newFreq = oldFreq - 1;
            removeFromBucket(key, oldFreq);

            if (newFreq == 0) {
                keyFreqMap.remove(key);
            } else {
                keyFreqMap.put(key, newFreq);
                freqKeysMap.computeIfAbsent(newFreq, k -> new HashSet<>()).add(key);
            }

            if (keyFreqMap.isEmpty()) {
                minFreq = 0;
                maxFreq = 0;
                return;
            }
            // Every other key had freq <= oldFreq. If oldFreq was the max and its bucket
            // is now empty, the new max is exactly newFreq (newFreq > 0 here, else map is empty).
            if (oldFreq == maxFreq && !freqKeysMap.containsKey(oldFreq)) {
                maxFreq = newFreq;
            }
            if (newFreq > 0) {
                minFreq = Math.min(minFreq, newFreq);
            } else if (oldFreq == minFreq && !freqKeysMap.containsKey(oldFreq)) {
                // The only min key vanished. The next min is somewhere above - this scan is
                // O(maxFreq), the one place this design is not O(1). Approach 2 fixes it.
                while (!freqKeysMap.containsKey(minFreq)) {
                    minFreq++;
                }
            }
        }

        @Override
        public String getMaxKey() {
            return maxFreq == 0 ? "" : freqKeysMap.get(maxFreq).iterator().next();
        }

        @Override
        public String getMinKey() {
            return minFreq == 0 ? "" : freqKeysMap.get(minFreq).iterator().next();
        }

        private void removeFromBucket(String key, int freq) {
            Set<String> bucket = freqKeysMap.get(freq);
            bucket.remove(key);
            if (bucket.isEmpty()) {
                freqKeysMap.remove(freq); // an empty bucket must not be visible to min/max
            }
        }
    }

    // =====================================================================
    // Approach 2: doubly linked list of count buckets + key -> bucket map
    // =====================================================================
    static class BucketList implements AllOneApi {

        /** One bucket per distinct count; holds every key currently at that count. */
        private static class Bucket {
            final int count;
            final Set<String> keys = new HashSet<>();
            Bucket prev;
            Bucket next;

            Bucket(int count) {
                this.count = count;
            }
        }

        // Sentinel (dummy) head and tail: the list is always sorted by count, ascending.
        private final Bucket head = new Bucket(Integer.MIN_VALUE);
        private final Bucket tail = new Bucket(Integer.MAX_VALUE);
        private final Map<String, Bucket> keyBucketMap = new HashMap<>(); // key -> its bucket

        BucketList() {
            head.next = tail;
            tail.prev = head;
        }

        @Override
        public void inc(String key) {
            Bucket curr = keyBucketMap.get(key);
            // A new key starts at count 1, which belongs in the bucket right after head.
            Bucket anchor = (curr == null) ? head : curr;
            int newCount = (curr == null) ? 1 : curr.count + 1;
            moveKey(key, curr, anchor, anchor.next, newCount);
        }

        @Override
        public void dec(String key) {
            Bucket curr = keyBucketMap.get(key);
            if (curr == null) {
                return; // key does not exist; safety net, same as above
            }
            if (curr.count == 1) {
                keyBucketMap.remove(key); // count would hit 0, so the key disappears entirely
                detachKey(key, curr);
            } else {
                moveKey(key, curr, curr.prev, curr, curr.count - 1);
            }
        }

        @Override
        public String getMaxKey() {
            return tail.prev == head ? "" : tail.prev.keys.iterator().next();
        }

        @Override
        public String getMinKey() {
            return head.next == tail ? "" : head.next.keys.iterator().next();
        }

        /**
         * Put {@code key} into the bucket with {@code newCount}, which must sit between
         * {@code left} and {@code right}. Reuse that bucket if it already exists there,
         * otherwise splice in a new one. Then drop the key from its old bucket (if any).
         */
        private void moveKey(String key, Bucket old, Bucket left, Bucket right, int newCount) {
            Bucket target;
            if (right != tail && right.count == newCount) {
                target = right;                 // bucket already exists (inc case)
            } else if (left != head && left.count == newCount) {
                target = left;                  // bucket already exists (dec case)
            } else {
                target = new Bucket(newCount);  // create it between left and right
                insertAfter(left, target);
            }
            target.keys.add(key);
            keyBucketMap.put(key, target);
            if (old != null) {
                detachKey(key, old);
            }
        }

        private void detachKey(String key, Bucket bucket) {
            bucket.keys.remove(key);
            if (bucket.keys.isEmpty()) {
                removeBucket(bucket); // keeps head.next / tail.prev meaningful with no cleanup pass
            }
        }

        private void insertAfter(Bucket node, Bucket toInsert) {
            toInsert.prev = node;
            toInsert.next = node.next;
            node.next.prev = toInsert;
            node.next = toInsert;
        }

        private void removeBucket(Bucket node) {
            node.prev.next = node.next;
            node.next.prev = node.prev;
            node.prev = null; // help GC and make any stale use fail loudly
            node.next = null;
        }
    }

    // =====================================================================
    // Driver: the same script against both approaches
    // =====================================================================

    /** Ties are legitimately ambiguous, so a step may list several acceptable answers. */
    private static void check(String label, String actual, String... allowed) {
        boolean ok = false;
        StringBuilder expected = new StringBuilder();
        for (int i = 0; i < allowed.length; i++) {
            if (i > 0) {
                expected.append(" or ");
            }
            expected.append("'").append(allowed[i]).append("'");
            if (allowed[i].equals(actual)) {
                ok = true;
            }
        }
        System.out.println("  " + label + " -> actual '" + actual + "'   expected "
                + expected + (ok ? "   OK" : "   FAIL"));
    }

    private static void run(String label, AllOneApi ds) {
        System.out.println("== " + label + " ==");

        check("empty            max", ds.getMaxKey(), "");
        check("empty            min", ds.getMinKey(), "");

        ds.inc("hello");
        ds.inc("hello");
        check("hello=2          max", ds.getMaxKey(), "hello");
        check("hello=2          min", ds.getMinKey(), "hello");

        ds.inc("leet");
        check("hello=2 leet=1   max", ds.getMaxKey(), "hello");
        check("hello=2 leet=1   min", ds.getMinKey(), "leet");

        ds.inc("leet");
        ds.inc("leet");
        check("hello=2 leet=3   max", ds.getMaxKey(), "leet");
        check("hello=2 leet=3   min", ds.getMinKey(), "hello");

        ds.dec("leet");
        check("both=2 tie       max", ds.getMaxKey(), "hello", "leet");
        check("both=2 tie       min", ds.getMinKey(), "hello", "leet");

        // Sparse counts: hello=2, leet=2, world goes 1 -> 2 -> 3, so bucket 1 empties.
        ds.inc("world");
        check("world=1          max", ds.getMaxKey(), "hello", "leet");
        check("world=1          min", ds.getMinKey(), "world");

        ds.inc("world");
        ds.inc("world");
        check("world=3          max", ds.getMaxKey(), "world");
        check("world=3          min", ds.getMinKey(), "hello", "leet");

        ds.dec("nosuchkey"); // decrementing an absent key must be a harmless no-op
        check("dec missing key  max", ds.getMaxKey(), "world");

        // Drain both count-2 keys to 0 so the minimum has to jump from 1 up to 3.
        ds.dec("hello");
        ds.dec("hello");
        ds.dec("leet");
        ds.dec("leet");
        check("only world=3     max", ds.getMaxKey(), "world");
        check("only world=3     min", ds.getMinKey(), "world");

        ds.dec("world");
        ds.dec("world");
        ds.dec("world");
        check("drained          max", ds.getMaxKey(), "");
        check("drained          min", ds.getMinKey(), "");
        System.out.println();
    }

    public static void main(String[] args) {
        run("Approach 1: two maps + tracked min/max", new TwoMaps());
        run("Approach 2: doubly linked bucket list (true O(1))", new BucketList());
    }
}

/*
 * =====================================================================
 *  Design In-Memory File System                       LeetCode 588 | Hard
 * =====================================================================
 *
 * PROBLEM
 *   Build a file system in memory with four shell-like operations. Paths are absolute,
 *   use "/" as the separator, and never have a trailing slash; "/" itself is the root.
 *     ls(path)                        if path is a directory, the sorted names directly
 *                                     inside it; if path is a file, a list with just that
 *                                     file's name.
 *     mkdir(path)                     create the directory and every missing directory
 *                                     along the way (like mkdir -p).
 *     addContentToFile(path, content) append to the file, creating it (and any missing
 *                                     parent directory) if it does not exist yet.
 *     readContentFromFile(path)       the file's full accumulated content.
 *
 * EXAMPLE
 *   mkdir("/a/b/c"); addContentToFile("/a/b/c/d.txt", "hello")
 *   ls("/")          -> [a] ls("/a/b/c")     -> [d.txt]
 *   ls("/a/b/c/d.txt") -> [d.txt]          a file path lists only itself
 *   addContentToFile("/a/b/c/d.txt", " world"); readContentFromFile(...) -> "hello world"
 *   ls("/") on a brand-new file system -> []   (the empty-root edge case)
 *
 * DESIGN  (trie of path segments)
 *   Dir   one node of the tree. Two maps, which is what keeps every case simple:
 *           dirs  : child directory name -> Dir
 *           files : file name            -> its content so far
 *         Keeping files separate from dirs means "is this path a file or a directory?"
 *         is two O(1) lookups, never a type check on a shared node.
 *   DesignInMemoryFileSystem holds only the root Dir. Every operation is the same walk
 *         down the segment list; the operations differ only in what they do at the end
 *         and whether the walk is allowed to create missing nodes.
 *
 * KEY DECISIONS
 *   1. Split once into segments and drop empty ones, so "/" and "/a/b" go through the
 *      same code. path.split("/") on "/a/b" yields ["", "a", "b"] -- the leading empty
 *      string is the classic off-by-one in this problem, so it is filtered out here.
 *   2. Two walk helpers instead of one flag: walkCreating for mkdir and writes,
 *      walkExisting (returns null on a missing segment) for ls and reads. Reads then
 *      degrade to [] or "" instead of throwing NullPointerException.
 *   3. ls sorts on demand. Sorting on write would cost more overall, because a directory
 *      is usually written many times and listed rarely.
 *   4. addContentToFile appends with getOrDefault(name, "") + content, so "create" and
 *      "append" are one line rather than two branches.
 *
 * COMPLEXITY
 *   Let L be the number of path segments and K the number of entries in a directory.
 *   Time  ls O(L + K log K) for the sort; mkdir, addContentToFile, readContentFromFile O(L)
 *         plus the cost of copying the content on append.
 *   Space O(N) for N directories and files, plus the stored content of every file.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Add rm / rmdir: delete the entry from the parent's map, and decide recursive or not.
 *   - Make appends cheap: store List<String> or StringBuilder per file instead of String,
 *     so appending is O(added) rather than O(total).
 *   - Support relative paths and "." / "..": resolve against a current-directory pointer.
 *   - Make it concurrent: lock per directory node, or use ConcurrentHashMap children.
 *   - Persist it: what changes if the tree must survive a restart? (a write-ahead log)
 *
 * RUN
 *   main() runs 3 cases (the LeetCode walkthrough, empty root and a file at root,
 *   auto-created parents plus missing paths) and prints actual vs expected per line.
 */

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** One node of the path trie: child directories by name, and files by name. */
class Dir {
    Map<String, Dir> dirs = new HashMap<>();
    Map<String, String> files = new HashMap<>();
}

class DesignInMemoryFileSystem {

    private final Dir root = new Dir();

    /** Directory listing, or the single file name when path points at a file. */
    public List<String> ls(String path) {
        String[] parts = segments(path);
        Dir cur = walkExisting(parts, parts.length - 1); // stop at the parent of the last segment
        if (cur == null) {
            return new ArrayList<>(); // some directory on the way does not exist
        }

        if (parts.length > 0) {
            String last = parts[parts.length - 1];
            if (cur.files.containsKey(last)) {
                return new ArrayList<>(Collections.singletonList(last)); // a file lists only itself
            }
            cur = cur.dirs.get(last);
            if (cur == null) {
                return new ArrayList<>(); // neither a file nor a directory
            }
        }

        List<String> result = new ArrayList<>(cur.dirs.keySet());
        result.addAll(cur.files.keySet());
        Collections.sort(result); // directories and files are listed together, sorted by name
        return result;
    }

    /** Create the directory and every missing directory above it (mkdir -p). */
    public void mkdir(String path) {
        String[] parts = segments(path);
        walkCreating(parts, parts.length);
    }

    /** Append to the file, creating the file and any missing parent directory. */
    public void addContentToFile(String filePath, String content) {
        String[] parts = segments(filePath);
        if (parts.length == 0) {
            return; // "/" is the root directory, not a file
        }
        Dir parent = walkCreating(parts, parts.length - 1);
        String name = parts[parts.length - 1];
        // getOrDefault turns "create" and "append" into the same single statement.
        parent.files.put(name, parent.files.getOrDefault(name, "") + content);
    }

    /** Full content of the file, or "" if no such file exists. */
    public String readContentFromFile(String filePath) {
        String[] parts = segments(filePath);
        if (parts.length == 0) {
            return "";
        }
        Dir parent = walkExisting(parts, parts.length - 1);
        if (parent == null) {
            return "";
        }
        return parent.files.getOrDefault(parts[parts.length - 1], "");
    }

    // ------------------------------------------------------------------
    // Path helpers
    // ------------------------------------------------------------------

    /**
     * "/" -> [], "/a/b/c" -> [a, b, c].
     * split("/") leaves a leading empty string, which is the usual off-by-one here,
     * so empty segments are dropped rather than skipped with an index trick.
     */
    private static String[] segments(String path) {
        List<String> parts = new ArrayList<>();
        for (String part : path.split("/")) {
            if (!part.isEmpty()) {
                parts.add(part);
            }
        }
        return parts.toArray(new String[0]);
    }

    /** Walk the first {@code depth} segments, creating any directory that is missing. */
    private Dir walkCreating(String[] parts, int depth) {
        Dir cur = root;
        for (int i = 0; i < depth; i++) {
            cur = cur.dirs.computeIfAbsent(parts[i], name -> new Dir());
        }
        return cur;
    }

    /** Walk the first {@code depth} segments, returning null if any is missing. */
    private Dir walkExisting(String[] parts, int depth) {
        Dir cur = root;
        for (int i = 0; i < depth; i++) {
            cur = cur.dirs.get(parts[i]);
            if (cur == null) {
                return null;
            }
        }
        return cur;
    }

    // ------------------------------------------------------------------
    // Demo
    // ------------------------------------------------------------------

    private static void check(String label, Object actual, Object expected) {
        boolean ok = String.valueOf(actual).equals(String.valueOf(expected));
        System.out.println("  " + label + " -> actual " + actual + "   expected " + expected
                + (ok ? "   OK" : "   FAIL"));
    }

    public static void main(String[] args) {
        System.out.println("case 1: the LeetCode walkthrough");
        DesignInMemoryFileSystem fs = new DesignInMemoryFileSystem();
        fs.mkdir("/a/b/c");
        check("ls(\"/\")", fs.ls("/"), Arrays.asList("a"));
        check("ls(\"/a/b/c\") empty dir", fs.ls("/a/b/c"), Collections.emptyList());
        fs.addContentToFile("/a/b/c/d.txt", "hello");
        check("ls(\"/a/b/c\")", fs.ls("/a/b/c"), Arrays.asList("d.txt"));
        check("ls file path", fs.ls("/a/b/c/d.txt"), Arrays.asList("d.txt"));
        check("read d.txt", fs.readContentFromFile("/a/b/c/d.txt"), "hello");
        fs.addContentToFile("/a/b/c/d.txt", " world"); // append, do not overwrite
        check("read after append", fs.readContentFromFile("/a/b/c/d.txt"), "hello world");

        System.out.println("case 2: empty root, a file directly at root, mkdir(\"/\")");
        DesignInMemoryFileSystem fs2 = new DesignInMemoryFileSystem();
        check("ls(\"/\") on new fs", fs2.ls("/"), Collections.emptyList());
        fs2.mkdir("/"); // no segments to create, must be a harmless no-op
        check("ls(\"/\") after mkdir(/)", fs2.ls("/"), Collections.emptyList());
        fs2.addContentToFile("/top.txt", "T");
        fs2.mkdir("/zdir");
        check("ls(\"/\") dirs and files", fs2.ls("/"), Arrays.asList("top.txt", "zdir"));
        check("ls(\"/top.txt\")", fs2.ls("/top.txt"), Arrays.asList("top.txt"));
        check("read /top.txt", fs2.readContentFromFile("/top.txt"), "T");

        System.out.println("case 3: parents created on write, and missing paths");
        DesignInMemoryFileSystem fs3 = new DesignInMemoryFileSystem();
        fs3.addContentToFile("/x/y/z.txt", "deep"); // /x and /x/y never had mkdir called
        check("ls(\"/\")", fs3.ls("/"), Arrays.asList("x"));
        check("ls(\"/x/y\")", fs3.ls("/x/y"), Arrays.asList("z.txt"));
        check("read z.txt", fs3.readContentFromFile("/x/y/z.txt"), "deep");
        fs3.mkdir("/x/y/sub");
        fs3.addContentToFile("/x/y/a.txt", "A");
        check("ls(\"/x/y\") sorted", fs3.ls("/x/y"), Arrays.asList("a.txt", "sub", "z.txt"));
        check("ls missing dir", fs3.ls("/nope/nope"), Collections.emptyList());
        check("read missing file", fs3.readContentFromFile("/x/y/missing.txt"), "");
    }
}

