/*
 * =====================================================================
 *  Student Grade From Marks                                Easy
 * =====================================================================
 *
 * PROBLEM
 *   Given a student's marks out of 100, return the letter grade using fixed
 *   cut-offs: A >= 90, B >= 70, C >= 50, D >= 35, otherwise "Fail".
 *   Marks are assumed to be in 0..100; anything below 35 fails.
 *
 * EXAMPLE
 *   marks = 85   ->  "Grade B"    85 is below 90 but at or above 70
 *   marks = 90   ->  "Grade A"    boundary value belongs to the higher band
 *   marks = 34   ->  "Fail"       falls through every threshold
 *   marks = 0    ->  "Fail"       lowest legal input, the edge case main() runs
 *
 * APPROACH  (ordered threshold ladder)
 *   1. Order the thresholds from highest to lowest: 90, 70, 50, 35.
 *   2. Walk down the ladder with else-if. The first test that succeeds wins,
 *      so each branch only has to state its own lower bound.
 *   3. The trailing else is the catch-all for everything under the last bound.
 *   4. Return the label instead of printing it, so main() can assert on it.
 *
 * KEY INSIGHT
 *   Because the ladder is ordered top-down and uses else-if, a branch never has
 *   to write "marks >= 70 && marks < 90" - the earlier branch already excluded
 *   the upper part of the range. Descending order plus else-if removes every
 *   upper bound. Reverse the order and the ladder silently collapses to one
 *   branch, which is the classic bug an interviewer plants here.
 *
 * COMPLEXITY
 *   Time  O(1)  at most four comparisons, independent of input size
 *   Space O(1)  no allocation beyond the returned label
 *
 * INTERVIEW FOLLOW-UPS
 *   - Make the bands data-driven: an array of {cutoff, label} scanned in order.
 *   - Many bands, many lookups - use a TreeMap and floorEntry(marks) for O(log n).
 *   - Validate input: what should marks = -5 or marks = 120 do, throw or clamp?
 *   - Change to grade-on-a-curve: cut-offs become percentiles of the cohort.
 *
 * RUN
 *   main() runs 6 cases (typical, the 90 / 70 / 50 boundaries, one mark below the
 *   35 pass mark, and the low edge) and prints actual vs expected on one line each.
 *   The 35 boundary itself is the one cut-off no case exercises - add it if you
 *   want the D band covered.
 */
class StudentGrade {

    /** Returns the letter grade for a mark out of 100 using descending cut-offs. */
    public String studentGrade(int marks) {
        // Ordered high to low: the first match wins, so no upper bounds are needed.
        if (marks >= 90) {
            return "Grade A";
        } else if (marks >= 70) {
            return "Grade B";
        } else if (marks >= 50) {
            return "Grade C";
        } else if (marks >= 35) {
            return "Grade D";
        } else {
            return "Fail";
        }
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        StudentGrade obj = new StudentGrade();

        print("case 1 marks=85 (typical)", obj.studentGrade(85), "Grade B");
        print("case 2 marks=90 (boundary)", obj.studentGrade(90), "Grade A");
        print("case 3 marks=70 (boundary)", obj.studentGrade(70), "Grade B");
        print("case 4 marks=50 (boundary)", obj.studentGrade(50), "Grade C");
        print("case 5 marks=34 (just below pass)", obj.studentGrade(34), "Fail");
        print("case 6 marks=0  (edge)", obj.studentGrade(0), "Fail");
    }
}

/*
 * =====================================================================
 *  Most Frequent IP In A Log File                  Easy    MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Given server log lines where each line starts with an IP address followed
 *   by a space and arbitrary text, return the IP that appears most often.
 *   Lines are well formed; the log may be empty, in which case return "".
 *   Ties are not defined by the problem - see KEY INSIGHT.
 *
 * EXAMPLE
 *   ["10.0.0.1 - GET /a", "10.0.0.1 - GET /b", "10.0.0.2 - GET /c"]  ->  "10.0.0.1"
 *   ["10.0.0.7 - only line"]  ->  "10.0.0.7"    single entry
 *   []                        ->  ""            empty log, the edge case main() runs
 *
 * APPROACH  (frequency map plus argmax scan)
 *   1. Walk the log once. For each line take the first whitespace-separated
 *      token - that is the IP.
 *   2. Count it into a HashMap<String, Integer> with getOrDefault(ip, 0) + 1.
 *   3. Walk the map's entrySet once, keeping the entry with the largest count
 *      seen so far (argmax). Return its key.
 *   4. findTopIpLexicographic() is the same scan with a deterministic tie-break,
 *      so a tied log always yields the same answer.
 *
 * KEY INSIGHT
 *   Count-then-argmax is two independent linear passes, not one clever pass -
 *   you cannot know the winner until every line is counted. The trap is the
 *   argmax comparison: a strict ">" keeps the FIRST maximum in HashMap iteration
 *   order, and that order is not the insertion order and not stable across JVM
 *   runs. If ties are possible, state a tie-break rule out loud (smallest IP,
 *   earliest seen) instead of shipping an order-dependent answer.
 *
 * COMPLEXITY
 *   Time  O(n * L)  n lines, L the cost of splitting one line to its first token
 *   Space O(k)      k distinct IP addresses held in the map
 *
 * INTERVIEW FOLLOW-UPS
 *   - Return the top k IPs, not just one - heap of size k, or a full sort.
 *   - The log does not fit in memory: stream it, or shard by hash of the IP.
 *   - Count only the last 5 minutes - sliding window over timestamped entries.
 *   - Approximate heavy hitters with Count-Min Sketch or Misra-Gries.
 *
 * RUN
 *   main() runs 4 cases (typical, single line, empty log, tie) and prints
 *   actual vs expected on one line each.
 */
import java.util.HashMap;
import java.util.Map;

class FindTopIpaddress {

    /** Most frequent leading IP. On a tie the winner depends on map iteration order. */
    public static String findTopIpaddress(String[] inputs) {
        Map<String, Integer> ipCountMap = new HashMap<>();

        for (String logEntry : inputs) {
            String ip = logEntry.split(" ")[0]; // the IP is the first token of the line
            ipCountMap.put(ip, ipCountMap.getOrDefault(ip, 0) + 1);
        }

        String topIp = "";
        int maxCount = 0;
        for (Map.Entry<String, Integer> entry : ipCountMap.entrySet()) {
            if (entry.getValue() > maxCount) {
                topIp = entry.getKey();
                maxCount = entry.getValue();
            }
        }
        return topIp;
    }

    /**
     * Same count-and-argmax, but ties break on the lexicographically smallest IP,
     * so the result no longer depends on HashMap iteration order.
     */
    public static String findTopIpLexicographic(String[] inputs) {
        Map<String, Integer> ipCountMap = new HashMap<>();
        for (String logEntry : inputs) {
            String ip = logEntry.split(" ")[0];
            ipCountMap.put(ip, ipCountMap.getOrDefault(ip, 0) + 1);
        }

        String topIp = "";
        int maxCount = 0;
        for (Map.Entry<String, Integer> entry : ipCountMap.entrySet()) {
            int count = entry.getValue();
            String ip = entry.getKey();
            boolean better = count > maxCount
                    || (count == maxCount && !topIp.isEmpty() && ip.compareTo(topIp) < 0);
            if (better) {
                topIp = ip;
                maxCount = count;
            }
        }
        return topIp;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": \"" + actual + "\"   expected \"" + expected + "\"");
    }

    public static void main(String[] args) {
        String[] typical = {
                "10.0.0.1 - log entry 1 11",
                "10.0.0.1 - log entry 2 213",
                "10.0.0.2 - log entry 133132"
        };
        String[] single = {"10.0.0.7 - the only line"};
        String[] empty = {};
        String[] tied = {"10.0.0.9 - a", "10.0.0.3 - b"}; // one vote each

        print("case 1 typical", findTopIpaddress(typical), "10.0.0.1");
        print("case 2 single line", findTopIpaddress(single), "10.0.0.7");
        print("case 3 empty log (edge)", findTopIpaddress(empty), "");
        // The plain version is order-dependent on a tie, so the tie case uses the
        // deterministic variant: both IPs have one hit, smaller string wins.
        print("case 4 tie, lexicographic", findTopIpLexicographic(tied), "10.0.0.3");
    }
}

/*
 * =====================================================================
 *  Election Winner With Lexicographic Tie-Break            Easy
 * =====================================================================
 *
 * PROBLEM
 *   Given an array of ballots, each a candidate's name, return the candidate
 *   with the most votes. If several candidates tie on votes, the winner is the
 *   lexicographically smallest name. An empty ballot box returns "".
 *
 * EXAMPLE
 *   ["John","Jane","John","Jane","John","Doe","Doe","Jane","Doe","John"] -> "John"
 *       John 4, Jane 3, Doe 3 - clear majority, no tie-break needed
 *   ["Bob","Alice"]  ->  "Alice"   one vote each, smaller name wins
 *   []               ->  ""        edge case main() runs
 *
 * APPROACH  (count votes, then argmax with a tie-break)
 *   1. Tally every ballot into a HashMap<String, Integer>.
 *   2. Scan the entry set keeping the best candidate seen so far.
 *   3. A candidate replaces the current best when it has strictly more votes,
 *      OR it has exactly the same votes and a lexicographically smaller name.
 *   4. Return the surviving best. "" falls out naturally for an empty input.
 *
 * KEY INSIGHT
 *   The tie-break turns an order-dependent scan into a deterministic one. With
 *   only "votes > max" the answer is whichever tied candidate HashMap iteration
 *   happens to reach first, which is not insertion order and can change between
 *   runs. Adding "|| (votes == max && name.compareTo(best) < 0)" makes the scan
 *   a true argmin/argmax over the pair (-votes, name), so the result is the same
 *   no matter what order the entries arrive in. Recognise this shape: any
 *   "pick the best, ties broken by X" is one comparison over a compound key.
 *
 * COMPLEXITY
 *   Time  O(n + k)  n ballots to count, k distinct candidates to scan
 *   Space O(k)      the tally map
 *
 * INTERVIEW FOLLOW-UPS
 *   - Tie-break on earliest first vote instead of name - keep a first-seen index.
 *   - Return the full ranking, not just the winner - sort entries by the same key.
 *   - Streaming ballots with a running winner at any moment - keep max as you count.
 *   - Ranked-choice voting: eliminate the last-placed candidate and redistribute.
 *
 * RUN
 *   main() runs 4 cases (typical, two-way tie, all votes equal, empty) and
 *   prints actual vs expected on one line each.
 */
import java.util.HashMap;
import java.util.Map;

class ElectionWinner {

    public static String findWinner(String[] votes) {
        // Step 1: tally the ballots.
        HashMap<String, Integer> voteCount = new HashMap<>();
        for (String vote : votes) {
            voteCount.put(vote, voteCount.getOrDefault(vote, 0) + 1);
        }

        // Step 2: argmax over (votes desc, name asc). The compound comparison is
        // what makes the result independent of HashMap iteration order.
        String winner = "";
        int maxVotes = 0;

        for (Map.Entry<String, Integer> entry : voteCount.entrySet()) {
            String candidate = entry.getKey();
            int votesReceived = entry.getValue();

            boolean beatsCurrent = votesReceived > maxVotes
                    || (votesReceived == maxVotes && candidate.compareTo(winner) < 0);
            if (beatsCurrent) {
                winner = candidate;
                maxVotes = votesReceived;
            }
        }

        return winner;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": \"" + actual + "\"   expected \"" + expected + "\"");
    }

    public static void main(String[] args) {
        String[] clearWinner = {"John", "Jane", "John", "Jane", "John",
                "Doe", "Doe", "Jane", "Doe", "John"};
        String[] twoWayTie = {"Bob", "Alice", "Bob", "Alice"};     // 2 each -> smaller name
        String[] allDistinct = {"Zoe", "Adam", "Mia"};             // 1 each -> smaller name
        String[] noBallots = {};

        print("case 1 clear winner", findWinner(clearWinner), "John");
        print("case 2 two-way tie", findWinner(twoWayTie), "Alice");
        print("case 3 every vote unique", findWinner(allDistinct), "Adam");
        print("case 4 empty ballot box (edge)", findWinner(noBallots), "");
    }
}

/*
 * =====================================================================
 *  Best Average Grade                                      Easy
 * =====================================================================
 *
 * PROBLEM
 *   Given a list of [studentName, score] string pairs, find the highest average
 *   score any single student achieved and return its floor as an int.
 *   An empty list returns 0. A malformed row (not exactly two fields) also
 *   returns 0, matching the original contract.
 *
 * EXAMPLE
 *   [["Bobby","87"],["Charles","100"],["Eric","64"],["Charles","22"]]  ->  87
 *       Bobby 87, Charles (100+22)/2 = 61, Eric 64  ->  best is 87
 *   [["Ann","-10"],["Ann","-11"]]  ->  -11   average -10.5, floor is -11
 *   []                             ->  0     edge case main() runs
 *
 * APPROACH  (group by key, then aggregate)
 *   1. Build Map<String, List<Integer>> from student name to all their scores,
 *      using putIfAbsent to create the list on first sight.
 *   2. For each student, sum the list and divide by its size as a double.
 *   3. Track the running maximum average, seeded with NEGATIVE_INFINITY so a
 *      negative average can still win.
 *   4. Return Math.floor of the winner, cast to int.
 *
 * KEY INSIGHT
 *   Group-then-aggregate is the workhorse shape behind most log and record
 *   problems: one pass to bucket rows under a key, a second pass to reduce each
 *   bucket. Upgrading a plain counter map to a map of lists is the only change.
 *   Fixed: the maximum was seeded with Double.MIN_VALUE, which is the smallest
 *   POSITIVE double (about 4.9e-324), not the most negative one. Any input whose
 *   best average was negative returned 0. Seed running maxima with
 *   Double.NEGATIVE_INFINITY (or Integer.MIN_VALUE for ints) instead.
 *
 * COMPLEXITY
 *   Time  O(n)      n rows: one pass to group, one pass over the same n scores
 *   Space O(m + n)  m distinct students plus every score held in the lists
 *
 * INTERVIEW FOLLOW-UPS
 *   - Drop the lists: keep running sum and count per student, O(m) space.
 *   - Return the student's name too, not just the value - track the argmax key.
 *   - Break ties between equal averages by name, or by number of scores.
 *   - Should the answer round, truncate toward zero, or floor? Ask before coding.
 *
 * RUN
 *   main() runs 5 cases (typical, single student, negative scores, empty,
 *   malformed row) and prints actual vs expected on one line each.
 */
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class BestAverageGrade {

    public static Integer bestAverageGrade(String[][] inputScores) {
        if (inputScores.length == 0) return 0;

        // Step 1: group every score under its student.
        Map<String, List<Integer>> studentScoresMap = new HashMap<>();
        for (String[] scoreRow : inputScores) {
            if (scoreRow.length != 2) {
                return 0; // malformed row: the original contract returns 0 rather than throwing
            }
            String student = scoreRow[0];
            int score = Integer.parseInt(scoreRow[1]);

            studentScoresMap.putIfAbsent(student, new ArrayList<>());
            studentScoresMap.get(student).add(score);
        }

        // Step 2: reduce each bucket to its average and keep the largest.
        // NEGATIVE_INFINITY, not Double.MIN_VALUE - MIN_VALUE is a tiny POSITIVE
        // number, so it would beat every negative average.
        double maxAverage = Double.NEGATIVE_INFINITY;

        for (List<Integer> scores : studentScoresMap.values()) {
            int sum = 0;
            for (int score : scores) {
                sum += score;
            }
            double average = sum / (double) scores.size(); // cast first, else integer division
            maxAverage = Math.max(maxAverage, average);
        }
        return (int) Math.floor(maxAverage);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        String[][] typical = {{"Bobby", "87"}, {"Charles", "100"},
                              {"Eric", "64"}, {"Charles", "22"}};
        String[][] singleStudent = {{"Solo", "42"}};
        String[][] allNegative = {{"Ann", "-10"}, {"Ann", "-11"}};
        String[][] empty = {};
        String[][] malformed = {{"Bobby"}};

        print("case 1 typical", bestAverageGrade(typical), 87);
        print("case 2 single student", bestAverageGrade(singleStudent), 42);
        print("case 3 negative averages", bestAverageGrade(allNegative), -11);
        print("case 4 empty input (edge)", bestAverageGrade(empty), 0);
        print("case 5 malformed row", bestAverageGrade(malformed), 0);
    }
}

/*
 * =====================================================================
 *  Shortest Distance Between Two Words      LeetCode 243 | Easy  MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Given a document (or a word array) and two distinct words, return the
 *   shortest distance between an occurrence of the first and an occurrence of
 *   the second. Matching is case-insensitive on raw text; return -1 when either
 *   word never appears.
 *
 *   "Distance" means two different things in interviews - ALWAYS ask which:
 *     1. Word-index distance : how many words apart (LeetCode 243).
 *     2. Character distance  : characters between the MIDPOINTS of the two
 *                              words (the Karat variant; its published answers
 *                              6 / 14 / 25 only come out with this meaning).
 *
 * EXAMPLE
 *   ["the","quick","brown","fox","quick","jumps","over","the","lazy","dog"]
 *       word1 = "quick", word2 = "the"      ->  1    indices 1 and 0 are adjacent
 *       word1 = "quick", word2 = "missing"  -> -1    edge case main() runs
 *   DOCUMENT, "and", "graphic"  ->  wordIndex 1,  midpoint distance 6
 *
 * APPROACH  (last-seen index, single pass)
 *   1. Walk the tokens left to right once, remembering only the most recent
 *      position of word1 and the most recent position of word2.
 *   2. Whenever either is updated and both have been seen, the gap between the
 *      two remembered positions is a candidate answer - keep the minimum.
 *   3. For the character variant the "position" is the word's midpoint:
 *      real start offset in the document + length / 2.
 *   4. midpointDistancePairwise() is the naive O(p*q) all-pairs version, kept
 *      as a second named method so main() can cross-check the one-pass answer.
 *
 * KEY INSIGHT
 *   You never need the full list of occurrences. Positions arrive in increasing
 *   order, so when you meet an occurrence of word1 the only occurrence of word2
 *   that can possibly be closer than anything already scored is the LAST one you
 *   saw. That single observation turns an O(p*q) all-pairs comparison into O(n)
 *   time and O(1) space. Recognise the shape: "closest pair of two tagged items
 *   in a sequence" is always last-seen bookkeeping, never a nested loop.
 *
 *   Gotcha the earlier drafts got wrong: if you tokenize with split() and
 *   advance a running offset by "length + 1", the offset drifts by one for every
 *   multi-character separator such as ", " or ". ". Use a regex Matcher and read
 *   the real m.start() offset instead.
 *
 * COMPLEXITY
 *   Time  O(n)  one pass over n tokens (pairwise variant is O(n + p*q))
 *   Space O(1)  two remembered positions (pairwise variant stores O(p + q));
 *               the text wrapper wordIndexDistanceInText adds O(n) for the
 *               lowercased copy and the token array split() builds, while the
 *               Matcher-based midpoint one-pass avoids both
 *
 * INTERVIEW FOLLOW-UPS
 *   - Many queries on one fixed document (LC 244): pre-index word -> sorted
 *     positions, then merge the two lists with two pointers per query.
 *   - word1 equals word2 (LC 245): the else-if collapses, so track the previous
 *     occurrence of the same word instead of two separate slots.
 *   - Return the actual pair of offsets, not just the gap.
 *   - Make it phrase-aware, or ignore stop words - changes only the tokenizer.
 *
 * RUN
 *   main() runs 2 array cases (typical, missing word) and 3 document cases,
 *   each printing actual vs expected for all three distance methods.
 */
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

class MinimumDistanceBetweenWordsV2 {

    // -------- Approach 1: word-index distance on an array (LeetCode 243 shape) --------

    public static int wordIndexDistance(String[] words, String word1, String word2) {
        int minDistance = Integer.MAX_VALUE;
        int lastPositionWord1 = -1;
        int lastPositionWord2 = -1;

        for (int i = 0; i < words.length; i++) {
            if (words[i].equals(word1)) {
                lastPositionWord1 = i;
            } else if (words[i].equals(word2)) {
                lastPositionWord2 = i;
            } else {
                continue; // not one of ours, nothing to update
            }
            // Only the most recent occurrence of the other word can improve the answer.
            if (lastPositionWord1 != -1 && lastPositionWord2 != -1) {
                minDistance = Math.min(minDistance,
                        Math.abs(lastPositionWord1 - lastPositionWord2));
            }
        }
        return (minDistance == Integer.MAX_VALUE) ? -1 : minDistance;
    }

    // -------- Approach 2: word-index distance on raw text --------

    public static int wordIndexDistanceInText(String paragraph, String word1, String word2) {
        // \W+ splits on any run of non-word characters, so punctuation is dropped for free.
        String[] words = paragraph.toLowerCase().split("\\W+");
        return wordIndexDistance(words, word1.toLowerCase(), word2.toLowerCase());
    }

    // -------- Shared helper for the midpoint approaches --------

    private static final Pattern WORD = Pattern.compile("[A-Za-z0-9']+");

    /** Midpoint = real start offset in the document + length / 2 ("bad" at offset 0 -> 1). */
    private static List<Integer>[] collectMidpoints(String document, String word1, String word2) {
        @SuppressWarnings("unchecked")
        List<Integer>[] midpoints = new List[]{new ArrayList<>(), new ArrayList<>()};
        Matcher m = WORD.matcher(document);
        while (m.find()) {
            String word = m.group().toLowerCase();
            int midpoint = m.start() + word.length() / 2;
            if (word.equals(word1)) midpoints[0].add(midpoint);
            else if (word.equals(word2)) midpoints[1].add(midpoint);
        }
        return midpoints;
    }

    // -------- Approach 3: character distance between midpoints, all pairs --------

    public static int midpointDistancePairwise(String document, String word1, String word2) {
        List<Integer>[] mids =
                collectMidpoints(document, word1.toLowerCase(), word2.toLowerCase());
        int shortest = Integer.MAX_VALUE;
        for (int pos1 : mids[0]) {
            for (int pos2 : mids[1]) {
                shortest = Math.min(shortest, Math.abs(pos1 - pos2));
            }
        }
        return shortest == Integer.MAX_VALUE ? -1 : shortest;
    }

    // -------- Approach 4: character distance between midpoints, one pass --------

    public static int midpointDistanceOnePass(String document, String word1, String word2) {
        word1 = word1.toLowerCase();
        word2 = word2.toLowerCase();
        int last1 = -1, last2 = -1, shortest = Integer.MAX_VALUE;
        Matcher m = WORD.matcher(document);
        while (m.find()) {
            String word = m.group().toLowerCase();
            int midpoint = m.start() + word.length() / 2;
            if (word.equals(word1)) last1 = midpoint;
            else if (word.equals(word2)) last2 = midpoint;
            else continue;
            // Midpoints arrive in increasing order, so the nearest partner is
            // always the last one seen.
            if (last1 != -1 && last2 != -1) shortest = Math.min(shortest, Math.abs(last1 - last2));
        }
        return shortest == Integer.MAX_VALUE ? -1 : shortest;
    }

    // -------- Demo --------

    private static final String DOCUMENT =
            "In publishing and graphic design, lorem ipsum is a filler text"
          + " commonly used to demonstrate the graphic elements"
          + " lorem ipsum text has been used in typesetting since the 1960s or"
          + " earlier, when it was popularized by advertisements"
          + " for Letraset transfer sheets. It was introduced to the Information"
          + " Age in the mid-1980s by Aldus Corporation, which";

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        String[] words = {"the", "quick", "brown", "fox", "quick",
                          "jumps", "over", "the", "lazy", "dog"};

        print("case 1 array, quick vs the", wordIndexDistance(words, "quick", "the"), 1);
        print("case 2 array, quick vs missing word (edge)",
                wordIndexDistance(words, "quick", "missing"), -1);
        System.out.println();

        // Karat sample: the published answers 6 / 14 / 25 are CHARACTER distances
        // between midpoints. The word-index answer for the same pair is different,
        // which is exactly why you must pin down the definition before coding.
        String[][] cases = {
                // word1, word2, expected word-index distance, expected midpoint distance
                {"and", "graphic", "1", "6"},
                {"transfer", "it", "2", "14"},
                {"Design", "filler", "5", "25"},
        };
        int caseNumber = 3;
        for (String[] c : cases) {
            String pair = c[0] + " vs " + c[1];
            print("case " + caseNumber + " doc, " + pair + " wordIndex",
                    wordIndexDistanceInText(DOCUMENT, c[0], c[1]), c[2]);
            print("case " + caseNumber + " doc, " + pair + " midpoint pairwise",
                    midpointDistancePairwise(DOCUMENT, c[0], c[1]), c[3]);
            print("case " + caseNumber + " doc, " + pair + " midpoint one-pass",
                    midpointDistanceOnePass(DOCUMENT, c[0], c[1]), c[3]);
            caseNumber++;
        }
    }
}

/*
 * =====================================================================
 *  Top K Videos by Total Watch Time            Karat / phone screen | Easy
 * =====================================================================
 *
 * PROBLEM
 *   You are given a stream of watch events, each a (videoName, watchTime) pair.
 *   The same video appears many times. Return the names of the 10 videos with the
 *   highest TOTAL watch time, best first. Ties are broken by name ascending so the
 *   answer is deterministic. Fewer than 10 distinct videos -> return all of them.
 *
 * EXAMPLE
 *   [(abc,10) (def,15) (ghi,10) (abc,12) (xyz,100) (abc,5) (def,20)]
 *     totals: xyz=100, def=35, abc=27, ghi=10  ->  [xyz, def, abc, ghi]
 *   [(b,10) (a,10) (c,3)]  ->  [a, b, c]        a and b tie at 10, name breaks it
 *   []                     ->  []               empty stream, empty answer
 *
 * APPROACH  (group-by-key, then top-k)
 *   1. Fold the events into Map<videoName, totalWatchTime>. One pass, O(n).
 *   2. topVideosBySort: copy the entry set to a list, sort by total descending
 *      (name ascending on a tie), take the first k. O(m log m) for m distinct videos.
 *   3. topVideosByHeap: keep a size-k MIN-heap ordered by the SAME rule. Push every
 *      entry; when the heap exceeds k, evict its head (the current worst). At the end
 *      the heap holds the best k; drain it and reverse. O(m log k).
 *   4. main() runs both and asserts they agree - identical comparator, identical answer.
 *
 * KEY INSIGHT
 *   Top-k is two independent decisions: the aggregation (a HashMap fold) and the
 *   selection (sort vs heap). Sorting is O(m log m) and gives you the full ranking;
 *   a size-k min-heap is O(m log k) and gives you only the k winners. Because k = 10
 *   here, the heap is the answer an interviewer wants once m gets large or the input
 *   is a stream that does not fit in memory. The min-heap is counter-intuitive on
 *   purpose: to keep the LARGEST k you must be able to cheaply discard the smallest
 *   one you are holding, so the heap head is the weakest survivor.
 *   Fixed: the original comparator sorted on total only, so videos with equal totals
 *   came out in HashMap iteration order - a different answer on a different JVM run.
 *
 * COMPLEXITY
 *   Time  O(n + m log m) sort form, O(n + m log k) heap form; n events, m distinct
 *   Space O(m)  the totals map dominates; the heap itself is only O(k)
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why a min-heap and not a max-heap for top-k? (evict the worst in O(log k))
 *   - The events arrive as an unbounded stream - what changes? (heap, or count-min
 *     sketch plus heap when even the distinct-video map will not fit)
 *   - Top 10 per hour with old events expiring - how? (bucket by time window)
 *   - If m is huge but k is tiny, is Quickselect better? (O(m) average, but it
 *     destroys the order and needs the whole array in memory)
 *
 * RUN
 *   main() runs 3 cases (typical, tie-break, empty) through both implementations
 *   and prints actual vs expected.
 */

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;

class TopVideos {

    private static final int DEFAULT_K = 10;

    /**
     * Best total watch time first; ties broken by name ascending.
     * Used by BOTH implementations so their answers are directly comparable.
     */
    private static final Comparator<Map.Entry<String, Integer>> BEST_FIRST =
            Comparator.<Map.Entry<String, Integer>>comparingInt(Map.Entry::getValue).reversed()
                      .thenComparing(Map.Entry::getKey);

    // ---------- Step 1: aggregation, shared by both approaches ----------

    /** Fold the raw events into video -> total watch time. O(n). */
    private static Map<String, Integer> totalWatchTimePerVideo(List<Pair<String, Integer>> events) {
        Map<String, Integer> totals = new HashMap<>();
        for (Pair<String, Integer> event : events) {
            totals.merge(event.getKey(), event.getValue(), Integer::sum);
        }
        return totals;
    }

    // ---------- Approach 1: sort the whole thing ----------

    /** The problem as asked: top 10. */
    public static List<String> topVideos(List<Pair<String, Integer>> events) {
        return topVideosBySort(events, DEFAULT_K);
    }

    /** O(m log m). Simple, and it hands you the full ranking if you ever need it. */
    public static List<String> topVideosBySort(List<Pair<String, Integer>> events, int k) {
        List<Map.Entry<String, Integer>> ranked =
                new ArrayList<>(totalWatchTimePerVideo(events).entrySet());
        ranked.sort(BEST_FIRST);

        List<String> top = new ArrayList<>();
        for (int i = 0; i < Math.min(k, ranked.size()); i++) {
            top.add(ranked.get(i).getKey());
        }
        return top;
    }

    // ---------- Approach 2: bounded min-heap ----------

    /**
     * O(m log k). The heap is ordered WORST-first (BEST_FIRST reversed), so its head is
     * always the weakest video currently held and can be evicted in O(log k).
     */
    public static List<String> topVideosByHeap(List<Pair<String, Integer>> events, int k) {
        if (k <= 0) return new ArrayList<>();

        PriorityQueue<Map.Entry<String, Integer>> worstFirst =
                new PriorityQueue<>(BEST_FIRST.reversed());

        for (Map.Entry<String, Integer> entry : totalWatchTimePerVideo(events).entrySet()) {
            worstFirst.offer(entry);
            if (worstFirst.size() > k) {
                worstFirst.poll(); // drop the weakest survivor, never the strongest
            }
        }

        // Draining a worst-first heap yields ascending order, so reverse it.
        List<String> top = new ArrayList<>();
        while (!worstFirst.isEmpty()) {
            top.add(worstFirst.poll().getKey());
        }
        Collections.reverse(top);
        return top;
    }

    // ---------- Test harness ----------

    private static List<Pair<String, Integer>> events(Object... nameThenTime) {
        List<Pair<String, Integer>> list = new ArrayList<>();
        for (int i = 0; i < nameThenTime.length; i += 2) {
            list.add(new Pair<>((String) nameThenTime[i], (Integer) nameThenTime[i + 1]));
        }
        return list;
    }

    private static void check(String label, List<Pair<String, Integer>> input,
                              int k, String expected) {
        List<String> bySort = topVideosBySort(input, k);
        List<String> byHeap = topVideosByHeap(input, k);
        System.out.println(label + " sort: " + bySort + "   expected " + expected);
        System.out.println(label + " heap: " + byHeap + "   expected " + expected
                + "   (agrees with sort: " + bySort.equals(byHeap) + ", expected true)");
    }

    public static void main(String[] args) {
        // case 1 - typical: repeated videos, k larger than the number of distinct videos
        check("case 1", events(
                "abc", 10, "def", 15, "ghi", 10, "abc", 12,
                "xyz", 100, "abc", 5, "def", 20), 10, "[xyz, def, abc, ghi]");

        // case 2 - tricky: a and b tie at 10, so the name tie-break decides
        check("case 2", events("b", 10, "a", 10, "c", 3), 10, "[a, b, c]");

        // case 3 - edge: no events at all
        check("case 3", events(), 10, "[]");

        // case 4 - edge: k smaller than the number of distinct videos
        check("case 4", events("p", 1, "q", 9, "r", 5), 2, "[q, r]");

        // the method as the interviewer asked for it (top 10, no k argument)
        System.out.println("case 5: " + topVideos(events("solo", 7)) + "   expected [solo]");
    }
}

/** Minimal pair holder so the file stays dependency-free
 *  (javafx.util.Pair is not on the JDK path). */
class Pair<K, V> {
    private final K key;
    private final V value;

    public Pair(K key, V value) {
        this.key = key;
        this.value = value;
    }

    public K getKey() {
        return key;
    }

    public V getValue() {
        return value;
    }
}

/*
 * =====================================================================
 *  Scrambled Word Hidden in a Note              Karat round 1 | Easy
 * =====================================================================
 *
 * PROBLEM
 *   You suspect students are passing the answer to a quiz around, hidden inside a
 *   note that looks like gibberish. Given a list of lowercase words and one note,
 *   return the word whose letters can all be found inside the note. The letters need
 *   not be in order or adjacent, but each letter of the note can be used only ONCE.
 *   At most one word matches; return "-" when none does.
 *
 * EXAMPLE
 *   words = [baby, referee, cat, dada, dog, bird, ax, baz]
 *   note = "ctay"             ->  "cat"    letters need not be in order
 *   note = "bcanihjsrrrferet" ->  "cat"    letters need not be adjacent
 *   note = "tbaykkjlga"       ->  "-"      only one 'a', so "baby" cannot reuse it
 *   note = "bbbblkkjbaby"     ->  "baby"   b,a,b,y all present
 *   note = "dad"              ->  "-"      "dada" needs two 'a', the note has one
 *   note = "dadaa"            ->  "dada"   two 'd' and two 'a' available
 *   note = ""                 ->  "-"      edge case main() runs
 *
 * APPROACH  (letter multiset containment)
 *   1. Count the note's letters once into an int[26] - this is the budget of letters
 *      available, and it never changes while we test candidates.
 *   2. Count each word's letters into its own int[26].
 *   3. A word fits iff for EVERY letter, wordCount[c] <= noteCount[c]. One counter
 *      exceeding its budget is enough to reject, so bail out on the first failure.
 *   4. Return the first word that fits, otherwise "-".
 *
 * KEY INSIGHT
 *   "Letters cannot be reused" is the whole problem, and it is exactly the definition
 *   of multiset (bag) containment: word is a sub-multiset of note. The moment you see
 *   that, the "not in order, not adjacent" wording becomes irrelevant noise - position
 *   never enters the computation, only counts do. Recognise the shape: the same
 *   int[26] <= int[26] test drives Ransom Note, Valid Anagram (there with equality
 *   instead of <=) and Minimum Window Substring's "have we covered the need" check.
 *
 * COMPLEXITY
 *   With W = number of words and S = max length of a word or the note:
 *   Time  O(S + W * (S + 26)) = O(W * S)  count the note once, then each word once
 *   Space O(W * 26) = O(W)  one fixed 26-slot tally per word; O(26) if built lazily
 *
 * INTERVIEW FOLLOW-UPS
 *   - Many notes against the same word list: precompute the word tallies once, then
 *     each note costs O(S + W * 26). That is why the tallies live in a list here.
 *   - Unicode or mixed case instead of a-z: swap int[26] for a HashMap<Character,
 *     Integer>, or normalise case first. The int[26] indexing silently corrupts
 *     memory-adjacent counts on any character outside a-z.
 *   - Return ALL matching words rather than the first one.
 *   - Rank the matches by length, or find the longest word hidden in the note.
 *
 * RUN
 *   main() runs the 7 official Karat notes plus 2 edge cases (empty note, a word that
 *   uses the note exactly) and prints actual vs expected on each line.
 */

import java.util.ArrayList;
import java.util.List;

class Solution {

    private static final int ALPHABET = 26;
    private static final String NOT_FOUND = "-";

    /** Returns the first word whose letters all fit inside the note, or "-". */
    private String find(String[] words, String note) {
        // Precompute one tally per word so repeated notes cost nothing extra.
        List<int[]> wordTallies = new ArrayList<>();
        for (String word : words) {
            wordTallies.add(letterCounts(word));
        }

        int[] noteTally = letterCounts(note);
        for (int i = 0; i < words.length; i++) {
            if (fitsInside(wordTallies.get(i), noteTally)) {
                return words[i];
            }
        }
        return NOT_FOUND;
    }

    /** How many of each letter a-z the text contains. */
    private int[] letterCounts(String text) {
        int[] counts = new int[ALPHABET];
        for (int i = 0; i < text.length(); i++) {
            counts[text.charAt(i) - 'a']++;
        }
        return counts;
    }

    /** True iff the word never needs more of a letter than the note can supply. */
    private boolean fitsInside(int[] wordCounts, int[] noteCounts) {
        for (int c = 0; c < ALPHABET; c++) {
            if (wordCounts[c] > noteCounts[c]) {
                return false; // one over-budget letter is enough to reject
            }
        }
        return true;
    }

    // ---------- Test harness ----------

    private static void check(Solution sol, String[] words, String note, String expected) {
        String actual = sol.find(words, note);
        System.out.println("note \"" + note + "\" -> " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        Solution sol = new Solution();
        String[] words = {"baby", "referee", "cat", "dada", "dog", "bird", "ax", "baz"};

        // The 7 cases from the original Karat prompt.
        check(sol, words, "ctay", "cat");             // out of order
        check(sol, words, "bcanihjsrrrferet", "cat"); // not adjacent
        check(sol, words, "tbaykkjlga", "-");         // letters cannot be reused
        check(sol, words, "bbbblkkjbaby", "baby");    // plenty of spare letters
        check(sol, words, "dad", "-");                // "dada" needs a second 'a'
        check(sol, words, "breadmaking", "bird");
        check(sol, words, "dadaa", "dada");           // exactly enough letters

        // Edge cases.
        check(sol, words, "", "-");                   // empty note matches nothing
        check(sol, words, "xa", "ax");                // note consumed exactly
    }
}

/*
 * =====================================================================
 *  High-Access Employees / Badge Access      LeetCode 2933 | Medium  MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Badge records arrive as [name, "HHMM"] pairs in arbitrary order. An employee is
 *   "high-access" if they badged in 3 or more times inside a single one-hour window.
 *   Return those employees. Times are within one day, so no midnight wrap-around.
 *   Two forms of the same question ship together here:
 *     LeetCode 2933 - return just the names, window is OPEN   (strictly under 60 min)
 *     Karat "badge access" - return the offending times too, window is CLOSED (<= 60)
 *
 * EXAMPLE
 *   [[a,0549] [b,0457] [a,0532] [a,0621] [b,0540]]  ->  [a]
 *     a's sorted scans are 0532 0549 0621; 0621 - 0532 = 49 min, three in one hour
 *   [[d,0002] [c,0808] [c,0829] [e,0215] [d,1508] [d,1444] [d,1410] [c,0809]] -> [c, d]
 *   Zhang badges at 0001 0010 0109 0110: 0110 - 0010 is exactly 60 minutes, so Zhang
 *     is EXCLUDED by the strict LeetCode rule and INCLUDED by the inclusive Karat rule
 *
 * APPROACH  (group by employee, sort times, check the i and i-2 pair)
 *   1. Parse each "HHMM" into minutes since midnight: (hhmm / 100) * 60 + hhmm % 100.
 *      Integer parsing rather than substrings, because Karat's input is not
 *      zero-padded - "835", "5" and "0" are all legal there.
 *   2. Group the minute values per employee in a HashMap<String, List<Integer>>.
 *   3. Sort each employee's list.
 *   4. leetcodeNamesOnly: slide a fixed window of THREE consecutive scans. For each
 *      i >= 2, test times[i] - times[i-2] < 60. One hit means high-access; stop.
 *   5. karatFirstWindow: the report form. Anchor at each scan i and grow forward while
 *      times[j] - times[i] <= 60. The first anchor collecting 3+ scans is reported,
 *      with its times formatted back to "HHMM".
 *
 * KEY INSIGHT
 *   Once the times are sorted, "three scans inside one hour" collapses to a single
 *   subtraction. The three tightest consecutive scans ending at index i are exactly
 *   times[i-2], times[i-1], times[i], and since they are sorted, the outer pair is the
 *   widest of the three gaps. So if times[i] - times[i-2] fits in an hour, everything
 *   between it does too - no inner loop, no sliding two-pointer, no bookkeeping.
 *   Recognise the pattern: a "k events within a window" question over sortable keys is
 *   always a one-line check on times[i] - times[i-k+1], which generalises for free.
 *   The second insight is a spec one: ALWAYS ask whether the hour is open or closed.
 *   Zhang above is the employee whose answer flips on that single word.
 *
 * COMPLEXITY
 *   Time  O(n log n)  sorting each employee's list; the scan afterwards is O(n)
 *   Space O(n)        the grouping map holds every record once
 *   Karat form adds O(n * k) in the worst case, k = scans inside one window.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Generalise to k scans in m minutes: the check becomes times[i] - times[i-k+1] < m.
 *   - Records stream in already sorted by time - can you avoid the sort? (yes: keep a
 *     per-employee deque, evict from the front while it is older than 60 min, and flag
 *     when the deque reaches size 3 - O(n) total)
 *   - Times cross midnight, or carry dates - what breaks? (parse to epoch minutes)
 *   - Report EVERY offending window instead of only the first per employee.
 *
 * RUN
 *   main() runs 4 datasets (two LeetCode examples, a nobody-qualifies edge case, the
 *   full Karat example) through both implementations, printing actual vs expected.
 */

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

class HighAccessEmployees {

    private static final int WINDOW_MINUTES = 60;
    private static final int SCANS_NEEDED = 3;

    // ---------- Approach 1: LeetCode 2933 (names only, strict < 60) ----------

    public List<String> leetcodeNamesOnly(List<List<String>> accessTimes) {
        Map<String, List<Integer>> byEmployee = groupByEmployee(accessTimes);

        List<String> result = new ArrayList<>();
        for (Map.Entry<String, List<Integer>> entry : byEmployee.entrySet()) {
            List<Integer> times = entry.getValue();
            if (times.size() < SCANS_NEEDED) continue;
            Collections.sort(times);
            // Sorted, so times[i-2] <= times[i-1] <= times[i]: if the OUTER pair is
            // under an hour apart, all three scans share the same open hour.
            for (int i = SCANS_NEEDED - 1; i < times.size(); i++) {
                if (times.get(i) - times.get(i - (SCANS_NEEDED - 1)) < WINDOW_MINUTES) {
                    result.add(entry.getKey());
                    break; // one offending window is all it takes
                }
            }
        }
        return result;
    }

    // ---------- Approach 2: Karat form (first window plus its times, inclusive <= 60) ----------

    public Map<String, List<String>> karatFirstWindow(List<List<String>> accessTimes) {
        Map<String, List<Integer>> byEmployee = groupByEmployee(accessTimes);

        Map<String, List<String>> result = new TreeMap<>(); // sorted keys = stable output
        for (Map.Entry<String, List<Integer>> entry : byEmployee.entrySet()) {
            List<Integer> times = entry.getValue();
            Collections.sort(times);

            for (int i = 0; i < times.size(); i++) {
                // Grow the window anchored at scan i: keep adding later scans while
                // they are still within 60 minutes of the anchor.
                List<Integer> window = new ArrayList<>();
                window.add(times.get(i));
                for (int j = i + 1; j < times.size(); j++) {
                    if (times.get(j) - times.get(i) > WINDOW_MINUTES) {
                        break; // sorted, so nothing later can fit either
                    }
                    window.add(times.get(j));
                }

                if (window.size() >= SCANS_NEEDED) {
                    List<String> formatted = new ArrayList<>();
                    for (int minutes : window) formatted.add(formatTime(minutes));
                    result.put(entry.getKey(), formatted);
                    break; // only the first offending window per employee
                }
            }
        }
        return result;
    }

    // ---------- Shared helpers ----------

    /** Group the scan times per employee, each converted to minutes since midnight. */
    private static Map<String, List<Integer>> groupByEmployee(List<List<String>> accessTimes) {
        Map<String, List<Integer>> byEmployee = new HashMap<>();
        for (List<String> record : accessTimes) {
            byEmployee.computeIfAbsent(record.get(0), name -> new ArrayList<>())
                      .add(toMinutes(record.get(1)));
        }
        return byEmployee;
    }

    /** "HHMM" -> minutes. Integer parse, not substring, so "835", "5" and "0" also work. */
    private static int toMinutes(String timeStr) {
        int hhmm = Integer.parseInt(timeStr);
        return (hhmm / 100) * 60 + (hhmm % 100);
    }

    /** minutes since midnight -> zero-padded "HHMM" for the report. */
    private static String formatTime(int totalMinutes) {
        return String.format("%02d%02d", totalMinutes / 60, totalMinutes % 60);
    }

    // ---------- Test harness ----------

    private static List<List<String>> toList(String[][] rows) {
        List<List<String>> out = new ArrayList<>();
        for (String[] row : rows) out.add(Arrays.asList(row));
        return out;
    }

    private void check(String label, List<List<String>> input,
                       String expectedNames, String expectedWindows) {
        List<String> names = leetcodeNamesOnly(input);
        Collections.sort(names); // HashMap order is not guaranteed; sort to compare
        System.out.println(label + " names  (<60) : " + names + "   expected " + expectedNames);
        System.out.println(label + " window (<=60): " + karatFirstWindow(input)
                + "   expected " + expectedWindows);
    }

    public static void main(String[] args) {
        HighAccessEmployees sol = new HighAccessEmployees();

        // case 1 - LeetCode example 1
        sol.check("case 1", toList(new String[][]{
                        {"a", "0549"}, {"b", "0457"}, {"a", "0532"},
                        {"a", "0621"}, {"b", "0540"}}),
                "[a]",
                "{a=[0532, 0549, 0621]}");

        // case 2 - LeetCode example 2: two offenders, one of them near the end of the day
        sol.check("case 2", toList(new String[][]{
                        {"d", "0002"}, {"c", "0808"}, {"c", "0829"}, {"e", "0215"},
                        {"d", "1508"}, {"d", "1444"}, {"d", "1410"}, {"c", "0809"}}),
                "[c, d]",
                "{c=[0808, 0809, 0829], d=[1410, 1444, 1508]}");

        // case 3 - edge: nobody reaches three scans at all
        sol.check("case 3", toList(new String[][]{
                        {"solo", "0900"}, {"solo", "0910"}, {"other", "0905"}}),
                "[]",
                "{}");

        // case 4 - the full Karat example. Zhang (0010, 0109, 0110) is exactly 60 minutes
        // wide, so Zhang appears ONLY in the inclusive <=60 report - the spec gap made
        // visible. Note the non-zero-padded inputs "835", "5", "0", "1".
        sol.check("case 4", toList(new String[][]{
                        {"Paul", "1355"}, {"Jennifer", "1910"}, {"Jose", "835"},
                        {"Jose", "830"}, {"Paul", "1315"}, {"Chloe", "0"},
                        {"Chloe", "1910"}, {"Jose", "1615"}, {"Jose", "1640"},
                        {"Paul", "1405"}, {"Jose", "855"}, {"Jose", "930"},
                        {"Jose", "915"}, {"Jose", "730"}, {"Jose", "940"},
                        {"Jennifer", "1335"}, {"Jennifer", "730"}, {"Jose", "1630"},
                        {"Jennifer", "5"}, {"Chloe", "1909"}, {"Zhang", "1"},
                        {"Zhang", "10"}, {"Zhang", "109"}, {"Zhang", "110"},
                        {"Amos", "1"}, {"Amos", "2"}, {"Amos", "400"},
                        {"Amos", "500"}, {"Amos", "503"}, {"Amos", "504"},
                        {"Amos", "601"}, {"Amos", "602"}, {"Paul", "1416"}}),
                "[Amos, Jose, Paul]",
                "{Amos=[0500, 0503, 0504], Jose=[0830, 0835, 0855, 0915, 0930], "
                        + "Paul=[1315, 1355, 1405], Zhang=[0010, 0109, 0110]}");
    }
}

/*
 * =====================================================================
 *  K Nearest Places to a Coordinate        Scenario / "find me nearby" | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Given a user's latitude/longitude, a list of places (name, lat, lon) and an
 *   integer k, return the k places closest to the user, nearest first. Distance is
 *   great-circle distance on the Earth's surface, not straight-line on a flat map.
 *   k may exceed the number of places (return all) or be zero (return nothing), and
 *   the input list must not be reordered as a side effect.
 *
 * EXAMPLE
 *   user = Connaught Place, Delhi (28.6139, 77.2090), k = 3
 *   places = Taj Mahal, India Gate, Red Fort, Qutub Minar, Lotus Temple
 *     -> [India Gate (2.0 km), Red Fort (5.7 km), Lotus Temple (8.3 km)]
 *   k = 0   -> []                                    edge case main() runs
 *   k = 99  -> all 5, ordered India Gate .. Taj Mahal (Agra, ~180 km away)
 *
 * APPROACH  (Haversine distance, then top-k by sort or by bounded heap)
 *   1. Haversine: convert the latitude and longitude deltas to radians, apply
 *      a = sin^2(dLat/2) + cos(lat1) * cos(lat2) * sin^2(dLon/2),
 *      c = 2 * atan2(sqrt(a), sqrt(1-a)), distance = R * c with R = 6371 km.
 *   2. nearestBySort: compute each place's distance ONCE into a (place, distance)
 *      record, sort those records ascending, take the first k. O(n log n).
 *   3. nearestByHeap: keep a size-k MAX-heap keyed on distance. Offer every place and,
 *      whenever the heap exceeds k, evict its head - the farthest place held. At the
 *      end the heap holds the k nearest; drain and reverse. O(n log k).
 *   4. Both use the same tie-break (equal distance -> name ascending) so their answers
 *      are identical and main() can assert that.
 *
 * KEY INSIGHT
 *   The distance key is EXPENSIVE - Haversine costs several trig calls - and a
 *   comparator is invoked O(n log n) times, so computing the distance inside the
 *   comparator evaluates it roughly n log n times instead of n. Compute the key once
 *   per element, sort the decorated records, then strip the decoration. That is the
 *   decorate-sort-undecorate (Schwartzian transform) pattern, and it is the answer
 *   interviewers are fishing for here. The second half is the same top-k lesson as any
 *   heap problem, with the polarity flipped: to keep the k SMALLEST distances you hold
 *   a MAX-heap, because the thing you must cheaply discard is the current worst.
 *   Fixed: the original sorted the caller's list in place (a visible side effect, and
 *   an exception on an immutable list), recomputed Haversine inside the comparator,
 *   returned a subList view aliased to that list, and had no tie-break, so places at
 *   equal distance could come back in either order.
 *
 * COMPLEXITY
 *   Time  O(n log n) sort form, O(n log k) heap form; n Haversine calls either way
 *   Space O(n) for the decorated copy in the sort form, O(k) for the heap form
 *
 * INTERVIEW FOLLOW-UPS
 *   - k much smaller than n: why the bounded heap wins, and when Quickselect (O(n)
 *     average) beats both.
 *   - Millions of places and many queries: precompute a spatial index - geohash,
 *     quadtree, k-d tree or PostGIS/S2 cells - so you never scan every place.
 *   - Can you skip Haversine? For ranking only, squared equirectangular distance
 *     (dLat, dLon * cos(lat)) preserves order locally and costs one cosine.
 *   - Filter by a radius as well as k, or weight the ranking by rating or open hours.
 *
 * RUN
 *   main() runs 4 cases (typical k=3, k larger than the list, k=0, a deliberate
 *   distance tie) through both implementations and prints actual vs expected.
 */

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;

class Place {
    final String name;
    final double latitude;
    final double longitude;

    public Place(String name, double latitude, double longitude) {
        this.name = name;
        this.latitude = latitude;
        this.longitude = longitude;
    }

    @Override
    public String toString() {
        return name;
    }
}

class NearestPlacesFinder {

    private static final double EARTH_RADIUS_KM = 6371;

    /** A place with its distance already computed - the "decorate" half of the pattern. */
    private static final class Scored {
        final Place place;
        final double distanceKm;

        Scored(Place place, double distanceKm) {
            this.place = place;
            this.distanceKm = distanceKm;
        }
    }

    /** Nearest first; equal distances broken by name so the answer is deterministic. */
    private static final Comparator<Scored> NEAREST_FIRST =
            Comparator.<Scored>comparingDouble(s -> s.distanceKm)
                      .thenComparing(s -> s.place.name);

    // ---------- The distance kernel ----------

    /** Great-circle distance in kilometres between two lat/lon points (Haversine). */
    public static double distance(double lat1, double lon1, double lat2, double lon2) {
        double dLat = Math.toRadians(lat2 - lat1);
        double dLon = Math.toRadians(lon2 - lon1);

        double a = Math.sin(dLat / 2) * Math.sin(dLat / 2)
                 + Math.cos(Math.toRadians(lat1)) * Math.cos(Math.toRadians(lat2))
                 * Math.sin(dLon / 2) * Math.sin(dLon / 2);

        double c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        return EARTH_RADIUS_KM * c;
    }

    /** Decorate: one Haversine call per place, never one per comparison. */
    private static List<Scored> score(double userLat, double userLon, List<Place> places) {
        List<Scored> scored = new ArrayList<>(places.size());
        for (Place p : places) {
            scored.add(new Scored(p, distance(userLat, userLon, p.latitude, p.longitude)));
        }
        return scored;
    }

    private static List<Place> undecorate(List<Scored> scored) {
        List<Place> out = new ArrayList<>(scored.size());
        for (Scored s : scored) out.add(s.place);
        return out;
    }

    // ---------- Approach 1: decorate, sort, undecorate ----------

    public static List<Place> nearestBySort(double userLat, double userLon,
                                            List<Place> places, int k) {
        if (k <= 0) return new ArrayList<>();

        List<Scored> scored = score(userLat, userLon, places); // a COPY: caller's list untouched
        scored.sort(NEAREST_FIRST);
        return undecorate(scored.subList(0, Math.min(k, scored.size())));
    }

    // ---------- Approach 2: bounded max-heap, O(n log k) ----------

    public static List<Place> nearestByHeap(double userLat, double userLon,
                                            List<Place> places, int k) {
        if (k <= 0) return new ArrayList<>();

        // Farthest-first heap: its head is the worst candidate currently held.
        PriorityQueue<Scored> farthestFirst = new PriorityQueue<>(NEAREST_FIRST.reversed());
        for (Place p : places) {
            farthestFirst.offer(new Scored(p, distance(userLat, userLon, p.latitude, p.longitude)));
            if (farthestFirst.size() > k) {
                farthestFirst.poll(); // drop the farthest, never the nearest
            }
        }

        // Draining a farthest-first heap gives descending order, so reverse it.
        List<Place> out = new ArrayList<>();
        while (!farthestFirst.isEmpty()) out.add(farthestFirst.poll().place);
        Collections.reverse(out);
        return out;
    }

    // ---------- Test harness ----------

    private static void check(String label, double lat, double lon,
                              List<Place> places, int k, String expected) {
        List<Place> bySort = nearestBySort(lat, lon, places, k);
        List<Place> byHeap = nearestByHeap(lat, lon, places, k);
        System.out.println(label + " sort: " + bySort + "   expected " + expected);
        System.out.println(label + " heap: " + byHeap + "   expected " + expected
                + "   (agrees with sort: " + bySort.equals(byHeap) + ", expected true)");
    }

    public static void main(String[] args) {
        List<Place> places = Arrays.asList(
                new Place("Taj Mahal", 27.1751, 78.0421),
                new Place("India Gate", 28.6129, 77.2295),
                new Place("Red Fort", 28.6562, 77.2410),
                new Place("Qutub Minar", 28.5244, 77.1855),
                new Place("Lotus Temple", 28.5535, 77.2588));

        double userLat = 28.6139; // Connaught Place, Delhi
        double userLon = 77.2090;

        // case 1 - typical: the 3 nearest landmarks
        check("case 1", userLat, userLon, places, 3,
                "[India Gate, Red Fort, Lotus Temple]");

        // case 2 - edge: k larger than the list, so the full ranking comes back
        check("case 2", userLat, userLon, places, 99,
                "[India Gate, Red Fort, Lotus Temple, Qutub Minar, Taj Mahal]");

        // case 3 - edge: k = 0 asks for nothing
        check("case 3", userLat, userLon, places, 0, "[]");

        // case 4 - tricky: two places at an identical distance (same point, mirrored
        // offsets), so only the name tie-break makes the answer reproducible.
        List<Place> tied = Arrays.asList(
                new Place("West", 28.6139, 77.1090),
                new Place("East", 28.6139, 77.3090),
                new Place("Far", 28.6139, 78.2090));
        check("case 4", userLat, userLon, tied, 2, "[East, West]");

        // The input list must survive the calls unreordered.
        System.out.println("case 5: input order " + places
                + "   expected [Taj Mahal, India Gate, Red Fort, Qutub Minar, Lotus Temple]");

        // The distances behind case 1, for a reader who wants the numbers.
        for (Place p : nearestBySort(userLat, userLon, places, 3)) {
            System.out.printf("  %-14s %.2f km%n", p.name,
                    distance(userLat, userLon, p.latitude, p.longitude));
        }
    }
}

/*
 * =====================================================================
 *  Rank Teams by Votes                          LeetCode 1366 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   Every voter submits a full ranking of the same teams as a string, e.g. "ACB"
 *   means A first, C second, B third. Produce the overall ranking: a team ranks above
 *   another if it received more FIRST-place votes; if those tie, compare second-place
 *   votes, then third, and so on. If a team ties on every position, order the two by
 *   team letter ascending. Teams are uppercase letters, at most 26 of them, and every
 *   vote lists exactly the same teams.
 *
 * EXAMPLE
 *   ["ABC","ACB","ABC","ACB","ACB"]  ->  "ACB"
 *     A: 5 firsts. B and C both have 0 firsts, so compare seconds: C has 3, B has 2.
 *   ["WXYZ","XYZW"]                  ->  "XWYZ"
 *     W and X each have 1 first-place vote; at the second position X has 1 and W
 *     has 0, so X ranks above W - the cascade decides one position down.
 *   ["BCA","CAB","CBA","ABC","ACB","BAC"] -> "ABC"   every team ties everywhere
 *   ["A"]                            ->  "A"         edge case main() runs
 *
 * APPROACH  (positional tally matrix, then a cascading comparator)
 *   1. Build tally[26][n]: tally[team][position] = how many voters put that team in
 *      that position. One pass over all votes, O(votes * n).
 *   2. Collect the participating teams - votes[0] already lists each exactly once.
 *   3. Sort them with a comparator that walks positions 0..n-1 and returns on the
 *      first position where the two teams differ, higher count first.
 *   4. If the loop finishes without a difference the teams are identical on every
 *      position, so fall back to letter ascending.
 *
 * KEY INSIGHT
 *   The counting is trivial; the COMPARATOR is the interview signal. A cascading
 *   tie-break is a loop over keys that returns on the first difference and only falls
 *   through to the final rule when every key matched. Write it that way and the number
 *   of tie-break levels stops mattering - 2 or 26, the code is identical. The second
 *   thing to say out loud: the comparator must be a total order (transitive, and
 *   antisymmetric), which is exactly why the letter fallback is mandatory rather than
 *   cosmetic - without it Arrays.sort can throw "Comparison method violates its
 *   general contract" and the output becomes input-order dependent.
 *   Recognise the shape next time: A03_ElectionWinner is this problem with n = 1.
 *
 * COMPLEXITY
 *   With v = number of votes and n = number of teams (n <= 26):
 *   Time  O(v * n + n^2 log n)   tally pass, then a sort whose comparator costs O(n)
 *   Space O(26 * n) = O(n)       the tally matrix; bounded by 26 * 26 = 676 ints
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why not return teams[b][i] - teams[a][i] as an int subtraction in general?
 *     (safe here because counts are at most 1000, but it overflows for arbitrary ints)
 *   - Why is the letter fallback required, not just nice? (total-order contract)
 *   - Votes stream in one at a time and you must answer at any moment - what changes?
 *     (keep the tally live; the sort is O(n^2 log n) per query, or maintain a TreeSet)
 *   - Weighted positions (3/2/1 points) instead of lexicographic cascade - how does
 *     the comparator collapse? (to a single summed score, and ties become common)
 *
 * RUN
 *   main() runs 6 cases (two LeetCode examples, an all-tie case, a single vote, a
 *   single team, and an empty vote list) and prints actual vs expected.
 */

import java.util.Arrays;
import java.util.Comparator;

class RankTeamsByVotes {

    private static final int ALPHABET = 26;

    public static String rankTeams(String[] votes) {
        if (votes == null || votes.length == 0) return "";
        if (votes.length == 1) return votes[0]; // one voter: their ranking IS the answer

        final int teamCount = votes[0].length();

        // tally[team letter][position] = number of voters placing that team there.
        final int[][] tally = new int[ALPHABET][teamCount];
        for (String vote : votes) {
            for (int position = 0; position < teamCount; position++) {
                tally[vote.charAt(position) - 'A'][position]++;
            }
        }

        // votes[0] lists every participating team exactly once.
        Character[] teams = new Character[teamCount];
        for (int i = 0; i < teamCount; i++) {
            teams[i] = votes[0].charAt(i);
        }

        Arrays.sort(teams, cascadingComparator(tally, teamCount));

        StringBuilder ranking = new StringBuilder(teamCount);
        for (char team : teams) ranking.append(team);
        return ranking.toString();
    }

    /**
     * Walk the positions in order and return on the FIRST position where the two teams
     * differ, more votes first. Identical on every position -> letter ascending, which
     * is what makes this a total order and keeps Arrays.sort legal.
     */
    private static Comparator<Character> cascadingComparator(int[][] tally, int teamCount) {
        return (a, b) -> {
            int teamA = a - 'A';
            int teamB = b - 'A';
            for (int position = 0; position < teamCount; position++) {
                if (tally[teamA][position] != tally[teamB][position]) {
                    // Descending on count: the team with MORE votes at this position wins.
                    return Integer.compare(tally[teamB][position], tally[teamA][position]);
                }
            }
            return Character.compare(a, b); // mandatory fallback, not cosmetic
        };
    }

    // ---------- Test harness ----------

    private static void check(String label, String[] votes, String expected) {
        System.out.println(label + ": " + rankTeams(votes) + "   expected " + expected);
    }

    public static void main(String[] args) {
        // case 1 - typical: A sweeps the firsts, C beats B on second-place votes
        check("case 1", new String[]{"ABC", "ACB", "ABC", "ACB", "ACB"}, "ACB");

        // case 2 - tricky: W and X tie on first-place votes, decided at position 2
        check("case 2", new String[]{"WXYZ", "XYZW"}, "XWYZ");

        // case 3 - tricky: every team ties on every position, so letters decide
        check("case 3", new String[]{"BCA", "CAB", "CBA", "ABC", "ACB", "BAC"}, "ABC");

        // case 4 - edge: a single voter, so their ranking is the result verbatim
        check("case 4", new String[]{"ZMNAGUEDSJYLBOPHRQICWFXTVK"}, "ZMNAGUEDSJYLBOPHRQICWFXTVK");

        // case 5 - edge: one team only
        check("case 5", new String[]{"A", "A", "A"}, "A");

        // case 6 - edge: no votes at all
        check("case 6", new String[]{}, "");
    }
}

/*
 * =====================================================================
 *  Movie Recommender (collaborative filtering)          Karat | Medium
 * =====================================================================
 *
 * PROBLEM
 *   You are given a rating log: each entry is [user, movie, rating] with rating 1..5.
 *   For a target user, recommend movies that "similar" users liked but the target has
 *   not rated at all. You must define "similar" and "liked" yourself and defend them.
 *
 *   Rules chosen here (state these out loud in the interview):
 *     - "liked"   = rating >= 4.
 *     - "similar" = any OTHER user who also liked at least one movie the target liked.
 *     - a movie is recommendable only if the target has no rating for it (not even a 1).
 *     - the result is returned sorted alphabetically so the output is deterministic.
 *
 * EXAMPLE
 *   Charlie liked Lost In Translation and Inception.
 *   Bob and Franz also liked Lost In Translation, so they are Charlie's similar users.
 *   Both of them liked Mad Max, which Charlie never rated.
 *   recommendations("Charlie", log)  ->  [Mad Max]
 *
 *   recommendations("Alice", log)    ->  []
 *     Alice only liked Frozen, which nobody else rated, so she has no similar users.
 *
 * APPROACH  (two inverted indexes, then a two-hop traversal)
 *   1. Pass over the log once and build two maps:
 *        userToRatings : user  -> (movie -> rating)     "what did this user rate?"
 *        movieToLikers : movie -> set of users who rated it >= 4
 *   2. Hop 1: for every movie the TARGET liked, read movieToLikers to collect the
 *      similar users. Drop the target itself.
 *   3. Hop 2: for every similar user, walk their ratings and keep every movie they
 *      liked that the target has not rated.
 *   4. Sort the collected set and return it.
 *
 * KEY INSIGHT
 *   Recommendation here is just a two-hop walk on a bipartite graph of users and movies:
 *     target -> movies they liked -> other users who liked them -> movies THOSE users liked.
 *   The inverted index movie -> likers is what makes the middle hop O(1) instead of a
 *   rescan of the whole log. Whenever a problem says "people like you also liked X",
 *   reach for the inverted index and the two-hop pattern.
 *
 * COMPLEXITY
 *   Let R = number of log entries, and let the target have L liked movies.
 *   Time  O(R + sum of ratings of the similar users + M log M)
 *         building the indexes is one pass over R; the two hops only touch entries that
 *         are reachable from the target; M is the number of recommended movies we sort.
 *         Worst case (everyone likes everything) this degrades to O(R + M log M).
 *   Space O(R)  both indexes together store every log entry once.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Rank the results instead of returning a set: score each movie by how many similar
 *     users liked it, or by average rating, then sort by score descending.
 *   - Weight similarity: a user who overlaps on 5 liked movies should count more than
 *     one who overlaps on 1. That is cosine similarity / Jaccard on the liked sets.
 *   - Exclude a movie the target rated 1-3, which we already do, versus re-recommending
 *     it later. Which is right depends on whether a low rating means "seen and disliked".
 *   - Scale: millions of users means you cannot expand every similar user online. Use
 *     min-hash / LSH to shortlist neighbours, or precompute item-item similarity offline.
 *
 * RUN
 *   main() runs 7 cases: four ordinary users (Charlie, Bob, Dennis, Franz), a user
 *   with no similar users (Alice), an unknown user, and an empty log. Each prints
 *   actual vs expected on one line.
 */

import java.util.*;

class MovieRecommender {

    private static final int LIKE_THRESHOLD = 4;

    /**
     * Returns the alphabetically sorted movies that users similar to {@code user} liked
     * and that {@code user} has not rated.
     */
    public static List<String> recommendations(String user, List<List<String>> ratings) {
        Map<String, Map<String, Integer>> userToRatings = new HashMap<>();
        Map<String, Set<String>> movieToLikers = new HashMap<>();
        buildIndexes(ratings, userToRatings, movieToLikers);

        // Everything the target has already rated, at any score. Used twice below.
        Map<String, Integer> targetRatings = userToRatings.getOrDefault(user, Map.of());

        Set<String> similarUsers = findSimilarUsers(user, targetRatings, movieToLikers);

        Set<String> recommended = new HashSet<>();
        for (String similarUser : similarUsers) {
            for (Map.Entry<String, Integer> rated : userToRatings.get(similarUser).entrySet()) {
                boolean theyLikedIt = rated.getValue() >= LIKE_THRESHOLD;
                boolean targetHasNotSeenIt = !targetRatings.containsKey(rated.getKey());
                if (theyLikedIt && targetHasNotSeenIt) {
                    recommended.add(rated.getKey());
                }
            }
        }

        // Fixed: the original returned new ArrayList<>(hashSet), so the order changed
        // between runs and the printed answer could not be compared to an expected value.
        List<String> result = new ArrayList<>(recommended);
        Collections.sort(result);
        return result;
    }

    /** One pass over the log fills both inverted indexes. */
    private static void buildIndexes(List<List<String>> ratings,
                                     Map<String, Map<String, Integer>> userToRatings,
                                     Map<String, Set<String>> movieToLikers) {
        for (List<String> entry : ratings) {
            String user = entry.get(0);
            String movie = entry.get(1);
            int score = Integer.parseInt(entry.get(2));

            userToRatings.computeIfAbsent(user, k -> new HashMap<>()).put(movie, score);

            if (score >= LIKE_THRESHOLD) {
                movieToLikers.computeIfAbsent(movie, k -> new HashSet<>()).add(user);
            }
        }
    }

    /** Hop 1: anyone who liked a movie the target liked, excluding the target. */
    private static Set<String> findSimilarUsers(String user,
                                                Map<String, Integer> targetRatings,
                                                Map<String, Set<String>> movieToLikers) {
        Set<String> similarUsers = new HashSet<>();
        for (Map.Entry<String, Integer> rated : targetRatings.entrySet()) {
            if (rated.getValue() < LIKE_THRESHOLD) continue;          // target did not like it
            for (String liker : movieToLikers.getOrDefault(rated.getKey(), Set.of())) {
                if (!liker.equals(user)) {
                    similarUsers.add(liker);
                }
            }
        }
        return similarUsers;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        List<List<String>> ratings = Arrays.asList(
                Arrays.asList("Alice", "Frozen", "5"),
                Arrays.asList("Bob", "Mad Max", "5"),
                Arrays.asList("Charlie", "Lost In Translation", "4"),
                Arrays.asList("Charlie", "Inception", "4"),
                Arrays.asList("Bob", "All About Eve", "3"),
                Arrays.asList("Bob", "Lost In Translation", "5"),
                Arrays.asList("Dennis", "All About Eve", "5"),
                Arrays.asList("Dennis", "Mad Max", "4"),
                Arrays.asList("Charlie", "Topsy-Turvy", "2"),
                Arrays.asList("Dennis", "Topsy-Turvy", "4"),
                Arrays.asList("Alice", "Lost In Translation", "1"),
                Arrays.asList("Franz", "Lost In Translation", "5"),
                Arrays.asList("Franz", "Mad Max", "5")
        );

        // typical: one similar-user hop lands on exactly one unseen movie
        print("case 1 Charlie", recommendations("Charlie", ratings), "[Mad Max]");

        // Bob rated All About Eve a 3, so Dennis liking it does NOT make it a recommendation
        print("case 2 Bob", recommendations("Bob", ratings), "[Inception, Topsy-Turvy]");

        print("case 3 Dennis", recommendations("Dennis", ratings), "[Lost In Translation]");

        // edge: Alice's only liked movie was rated by nobody else -> no similar users
        print("case 4 Alice", recommendations("Alice", ratings), "[]");

        print("case 5 Franz", recommendations("Franz", ratings),
                "[All About Eve, Inception, Topsy-Turvy]");

        // edge: a user who is not in the log at all must not blow up
        print("case 6 unknown user", recommendations("Zoe", ratings), "[]");

        // edge: empty log
        print("case 7 empty log", recommendations("Alice", List.of()), "[]");
    }
}

/*
 * =====================================================================
 *  Popularity Tracker (running max under an interface)   Design | Hard  MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Implement the MostPopular interface for a content service. Content IDs can be
 *   promoted (increasePopularity) or demoted (decreasePopularity) in any order, and at
 *   any moment mostPopular() must return an ID with the highest count, or -1 when no
 *   content has a positive count. A count that falls to 0 means the ID is gone.
 *   Ties may be broken arbitrarily: any ID holding the maximum is a valid answer.
 *
 * EXAMPLE
 *   increase(7), increase(7), increase(8)   ->  mostPopular() = 7   (7 has 2, 8 has 1)
 *   increase(8), increase(8)                ->  mostPopular() = 8   (8 has 3, 7 has 2)
 *   decrease(8), decrease(8)                ->  mostPopular() = 7   (8 back to 1)
 *   decrease everything to zero             ->  mostPopular() = -1
 *
 * DESIGN  (count map + count-to-IDs bucket TreeMap)
 *   popularityMap : HashMap<Integer, Integer>
 *       contentId -> its current count. The forward lookup, O(1).
 *   countMap      : TreeMap<Integer, Set<Integer>>
 *       count -> the set of IDs currently sitting at that count. This is the inverted
 *       index, and because it is a TreeMap its last key is the running maximum.
 *
 *   Every update is the same three-step move:
 *       1. read the old count from popularityMap
 *       2. pull the ID out of its old bucket, deleting the bucket if it becomes empty
 *       3. write the new count and drop the ID into the new bucket
 *   Deleting empty buckets is what keeps lastKey() honest - a leftover empty set at a
 *   high count would make mostPopular() report a maximum nobody holds any more.
 *
 * KEY DECISIONS
 *   - Why two maps and not one? A single ID->count map forces an O(n) scan on every
 *     mostPopular() call. The inverted index turns the running maximum into a lookup.
 *   - Why TreeMap and not a PriorityQueue? A heap cannot cheaply remove an arbitrary
 *     element when a count changes, so it accumulates stale entries. A TreeMap keyed by
 *     count supports exact removal and still exposes the maximum.
 *   - Why a Set per count and not a List? Removal must be O(1); a List removal is O(size).
 *   - Count 0 deletes the ID entirely, so "not tracked" and "count zero" are one state.
 *     decreasePopularity on an unknown ID is a silent no-op rather than a negative count.
 *
 * COMPLEXITY
 *   increasePopularity / decreasePopularity : O(log d), d = number of DISTINCT counts,
 *       from the TreeMap insert/remove. The HashMap and HashSet work is O(1).
 *   mostPopular : O(log d) for TreeMap.lastKey(), then O(1) to take an element from the
 *       bucket. (The original header claimed O(1) here; lastKey() is a tree descent.
 *       A LinkedHashMap-of-buckets doubly-linked-list design is the true O(1) variant.)
 *   Space : O(n) for n tracked IDs - each ID appears once in each map.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Make every operation O(1): replace the TreeMap with a doubly linked list of count
 *     buckets in ascending order. Counts only ever move by one, so the next bucket is
 *     always the neighbour. This is exactly LeetCode 432 "All O(1) Data Structure".
 *   - Return ALL IDs at the maximum, or the k most popular, instead of one.
 *   - Break ties deterministically (smallest ID, or most recently promoted): swap the
 *     HashSet bucket for a TreeSet, or for a LinkedHashSet to get insertion order.
 *   - This is the skeleton of an LFU cache: LFU evicts from the LOWEST bucket
 *     (firstKey) instead of reading the highest.
 *   - Thread safety: the two maps must move together, so guard both with one lock or
 *     make the whole move a single atomic section. Two concurrent maps are not enough.
 *   - Gotcha: mostPopular() returns Integer, so == between TWO boxed Integers compares
 *     references and fails outside the -128..127 cache - use .equals() or .intValue().
 *     Against an int literal it is safe: "result == -1" unboxes the Integer and compares
 *     numerically, which is exactly what case 7 below relies on.
 *
 * RUN
 *   main() runs 7 cases: the empty tracker, the typical promote/demote sequence, a
 *   no-op decrease on an unknown ID, everything back at zero, and a tie on a second
 *   tracker. Each prints actual vs expected.
 */

import java.util.*;

interface MostPopular {
    void increasePopularity(Integer contentId);

    Integer mostPopular();

    void decreasePopularity(Integer contentId);
}

class PopularityTracker implements MostPopular {

    /** contentId -> its current popularity count. Only positive counts are stored. */
    private final Map<Integer, Integer> popularityMap = new HashMap<>();

    /** popularity count -> the IDs currently at that count. Sorted, so lastKey() is the max. */
    private final TreeMap<Integer, Set<Integer>> countMap = new TreeMap<>();

    @Override
    public void increasePopularity(Integer contentId) {
        int oldCount = popularityMap.getOrDefault(contentId, 0);
        int newCount = oldCount + 1;

        if (oldCount > 0) {
            removeFromBucket(oldCount, contentId);   // oldCount == 0 means no bucket exists yet
        }
        popularityMap.put(contentId, newCount);
        addToBucket(newCount, contentId);
    }

    @Override
    public void decreasePopularity(Integer contentId) {
        Integer oldCount = popularityMap.get(contentId);
        if (oldCount == null) return;                // untracked ID: nothing to demote

        removeFromBucket(oldCount, contentId);
        int newCount = oldCount - 1;

        if (newCount > 0) {
            popularityMap.put(contentId, newCount);
            addToBucket(newCount, contentId);
        } else {
            popularityMap.remove(contentId);         // count 0 means the ID stops existing
        }
    }

    @Override
    public Integer mostPopular() {
        if (countMap.isEmpty()) return -1;
        int highestCount = countMap.lastKey();
        return countMap.get(highestCount).iterator().next();   // any ID at the max is valid
    }

    private void addToBucket(int count, Integer contentId) {
        countMap.computeIfAbsent(count, k -> new HashSet<>()).add(contentId);
    }

    /** Removes the ID from its bucket and deletes the bucket when it empties. */
    private void removeFromBucket(int count, Integer contentId) {
        Set<Integer> bucket = countMap.get(count);
        if (bucket == null) return;
        bucket.remove(contentId);
        // An empty bucket left behind would make lastKey() report a phantom maximum.
        if (bucket.isEmpty()) countMap.remove(count);
    }

    /** Handy while debugging a failing sequence: shows both maps at once. */
    public String state() {
        return "counts=" + popularityMap + " buckets=" + countMap;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        PopularityTracker tracker = new PopularityTracker();

        // edge: nothing tracked yet
        print("case 1 empty tracker", tracker.mostPopular(), "-1");

        tracker.increasePopularity(7);
        tracker.increasePopularity(7);
        tracker.increasePopularity(8);
        print("case 2 after 7,7,8", tracker.mostPopular(), "7");

        tracker.increasePopularity(8);
        tracker.increasePopularity(8);
        print("case 3 8 overtakes 7", tracker.mostPopular(), "8");

        tracker.decreasePopularity(8);
        tracker.decreasePopularity(8);
        print("case 4 8 demoted twice", tracker.mostPopular(), "7");

        // edge: demoting an ID that was never tracked must be a silent no-op
        tracker.decreasePopularity(999);
        print("case 5 unknown ID ignored", tracker.state(),
                "counts={7=2, 8=1} buckets={1=[8], 2=[7]}");

        tracker.decreasePopularity(7);
        tracker.decreasePopularity(7);
        tracker.decreasePopularity(8);
        print("case 6 everything at zero", tracker.mostPopular(), "-1");

        // tricky: a genuine tie - either ID is a correct answer, so check membership
        PopularityTracker tied = new PopularityTracker();
        tied.increasePopularity(4);
        tied.increasePopularity(9);
        Integer winner = tied.mostPopular();
        boolean valid = winner == 4 || winner == 9;
        print("case 7 tie is valid", valid + " (returned " + winner + ")", "true");
    }
}

/*
 * =====================================================================
 *  Election / Josephus Problem                          LC 1823 | Medium
 * =====================================================================
 *
 * PROBLEM
 *   n students numbered 1..n sit in a circle. The teacher starts at student 1 and sings
 *   a song of length k, walking past k students; the student she stops on is removed.
 *   She resumes from the student after the removed one and repeats until one is left.
 *   Return the number of the surviving student. n >= 1, k >= 1.
 *
 * EXAMPLE
 *   n = 4, k = 2  ->  1
 *     circle 1,2,3,4. She walks past 1 and 2, so 2 goes. Then 3 and 4, so 4 goes.
 *     Then 1 and 3, so 3 goes. Student 1 survives.
 *   n = 1, k = 1  ->  1     (edge: the only student wins by default)
 *   n = 5, k = 3  ->  4
 *
 * APPROACH  (Josephus recurrence, in 1-based numbering)
 *   1. Solve the 0-indexed problem first. Let g(n) be the survivor's SEAT INDEX
 *      (0..n-1) when the count always restarts from seat 0. Then g(1) = 0 and
 *      g(n) = (g(n-1) + k) % n.
 *   2. Why: after the first removal, n-1 students remain and the counting restarts from
 *      the seat just after the one removed. That smaller circle is the same problem,
 *      only rotated by k seats. So take the answer for n-1 and rotate it back by k.
 *   3. Convert to 1-based numbering. Substituting f(n) = g(n) + 1 gives the form used
 *      in the code:  f(1) = 1,  f(n) = (f(n-1) + k - 1) % n + 1.
 *      The "- 1" undoes the 1-based offset before the modulo; the "+ 1" restores it.
 *   4. whoIsElected uses that recurrence directly. whoIsElectedIterative runs the same
 *      recurrence bottom-up from n = 1 upward, which removes the call stack.
 *
 * KEY INSIGHT
 *   Do not simulate the circle - collapse it. Removing one student turns the problem of
 *   size n into the SAME problem of size n-1 whose seats have been rotated by k, so the
 *   whole thing is one line of arithmetic. The only place people lose this in an
 *   interview is the 1-based indexing: derive it 0-based, then add 1 at the very end.
 *   Pattern to recognise: "people in a circle, every k-th one is eliminated" is Josephus.
 *
 * COMPLEXITY
 *   whoIsElected (recursive)   Time O(n)   one call per size.  Space O(n) call stack -
 *                              this is the version that dies with StackOverflowError
 *                              around n in the tens of thousands.
 *   whoIsElectedIterative      Time O(n)   one loop pass.      Space O(1).
 *   whoIsElectedBySimulation   Time O(n^2) ArrayList.remove shifts elements each time.
 *                              Space O(n). Only here to prove the formula is right.
 *
 * INTERVIEW FOLLOW-UPS
 *   - n up to 10^9 with small k: the O(n) loop is too slow. There is an O(k log n)
 *     trick that skips whole blocks of eliminations at a time.
 *   - k = 2 has a closed form: write n = 2^m + L, the survivor is 2L + 1.
 *   - Return the elimination ORDER, not just the survivor: that needs a simulation,
 *     and an order-statistic BIT or a balanced BST gets it to O(n log n).
 *   - Variant: the teacher alternates direction, or k changes each round. The recurrence
 *     still works as long as each round removes exactly one and restarts after it.
 *
 * RUN
 *   main() runs 8 cases through all three implementations: the doc example, the n = 1
 *   edge case, k = 1 (plain round robin), and larger n up to 1000. Each prints actual
 *   vs expected; the simulation is skipped above n = 2000 because it is quadratic.
 */

import java.util.*;

class Election {

    /** Josephus recurrence, top-down. O(n) stack depth. */
    public static int whoIsElected(int n, int k) {
        if (n == 1) return 1;
        return (whoIsElected(n - 1, k) + k - 1) % n + 1;
    }

    /** Same recurrence built bottom-up, so there is no call stack to overflow. */
    public static int whoIsElectedIterative(int n, int k) {
        int survivor = 1;                       // f(1) = 1
        for (int size = 2; size <= n; size++) {
            survivor = (survivor + k - 1) % size + 1;
        }
        return survivor;
    }

    /**
     * Brute-force simulation of the actual circle. Not the interview answer - it exists
     * so you can verify the recurrence and, if asked, read off the elimination order.
     */
    public static int whoIsElectedBySimulation(int n, int k) {
        List<Integer> circle = new ArrayList<>(n);
        for (int student = 1; student <= n; student++) {
            circle.add(student);
        }

        int seat = 0;                           // the teacher starts standing at student 1
        while (circle.size() > 1) {
            seat = (seat + k - 1) % circle.size();   // walk past k students, wrapping round
            circle.remove(seat);
            // After the removal this index already points at the next student; wrap if
            // we just removed the last seat in the list.
            if (seat == circle.size()) seat = 0;
        }
        return circle.get(0);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // { n, k, expected survivor }
        int[][] cases = {
                {1, 1, 1},          // edge: a single student
                {2, 2, 1},
                {4, 2, 1},          // the worked example in the header
                {5, 3, 4},
                {6, 4, 5},
                {7, 1, 7},          // k = 1: everyone is removed in order, the last seat wins
                {100, 2, 73},
                {1000, 5, 763}      // still inside the n <= 2000 simulation guard
        };

        for (int[] c : cases) {
            int n = c[0], k = c[1], expected = c[2];
            String label = "n=" + n + " k=" + k;

            print(label + " recursive", whoIsElected(n, k), expected);
            print(label + " iterative", whoIsElectedIterative(n, k), expected);
            if (n <= 2000) {
                print(label + " simulated", whoIsElectedBySimulation(n, k), expected);
            }
            System.out.println();
        }
    }
}

