/*
 * =====================================================================
 *  Static method call on a null reference          Java language | Easy
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   Calling a static method through a reference variable that holds null does
 *   NOT throw NullPointerException. The compiler resolves static members from
 *   the DECLARED TYPE of the expression, not from the object it points at, so
 *   the reference is never dereferenced at run time.
 *
 * WHAT YOU WILL SEE
 *   case 1: static method through a null ref   -> runs normally, no NPE
 *   case 2: instance method through a null ref -> NullPointerException
 *   case 3: static field through a null ref    -> reads the field, no NPE
 *   case 4: the receiver expression still runs -> its side effect happens
 *
 * HOW IT WORKS
 *   1. javac sees ref.staticMethod() where ref is declared as StaticNullRef.
 *   2. Static members bind at compile time to the declared type, so the call
 *      is effectively rewritten to StaticNullRef.staticMethod().
 *   3. That compiles to the invokestatic bytecode, which never looks at the
 *      reference value. An instance call compiles to invokevirtual, which must
 *      dereference the receiver to find the method - that is where NPE lives.
 *   4. The expression before the dot is still EVALUATED; only its value is
 *      discarded. So makeNull().staticMethod() still runs makeNull().
 *
 * KEY INSIGHT
 *   Static = bound at compile time to the declared type. Instance = dispatched
 *   at run time on the actual object. Only the second kind can throw NPE.
 *
 * GOTCHAS
 *   - The same rule covers static fields, so ref.CONSTANT reads fine on null.
 *   - Static methods are hidden, not overridden: a subclass reference still
 *     picks the declared type's version, which surprises people in tests.
 *   - IDEs warn "static member accessed via instance reference" for a reason;
 *     always write ClassName.staticMethod() in real code.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why does a static method have no `this`?
 *   - Can a static method be overridden? What is method hiding?
 *   - Which bytecode does each call site compile to, and why does it matter?
 *   - Does Objects.requireNonNull help here, and where would you put it?
 *
 * RUN
 *   main() runs 4 cases (static call, instance call, static field, receiver
 *   side effect) and prints actual vs expected.
 */
class StaticNullRefWithStaticMethhodCall {

    /** Set by makeNullWithSideEffect() so case 4 can observe that it ran. */
    private static String sideEffectMarker = "not run";

    public static void main(String[] args) {
        print("case 1: static method via null ref", staticCallThroughNull(), "staticMethod ran");
        print("case 2: instance method via null ref", instanceCallThroughNull(),
                "NullPointerException");
        print("case 3: static field via null ref", staticFieldThroughNull(), "42");
        print("case 4: receiver expression evaluated", receiverStillEvaluated(),
                "side effect ran");
    }

    /** invokestatic: the null value is never dereferenced, so no NPE. */
    private static String staticCallThroughNull() {
        StaticNullRef ref = null;
        return ref.staticMethod();  // javac turns this into StaticNullRef.staticMethod()
    }

    /** invokevirtual: the receiver IS dereferenced, so this throws. */
    private static String instanceCallThroughNull() {
        StaticNullRef ref = null;
        try {
            ref.instanceMethod();
            return "no exception (unexpected)";
        } catch (NullPointerException e) {
            return "NullPointerException";
        }
    }

    /** Static fields bind to the declared type too, so a null ref reads fine. */
    private static String staticFieldThroughNull() {
        StaticNullRef ref = null;
        return String.valueOf(ref.STATIC_VALUE);
    }

    /** The value of the receiver is discarded, but the expression still runs. */
    private static String receiverStillEvaluated() {
        sideEffectMarker = "not run";
        makeNullWithSideEffect().staticMethod();
        return sideEffectMarker;
    }

    private static StaticNullRef makeNullWithSideEffect() {
        sideEffectMarker = "side effect ran";
        return null;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

class StaticNullRef {

    static final int STATIC_VALUE = 42;

    static String staticMethod() {
        return "staticMethod ran";
    }

    String instanceMethod() {
        return "instanceMethod ran";
    }
}

/*
 * =====================================================================
 *  Varargs and overload resolution              Java language | Easy
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   A varargs parameter (T... args) is just an array parameter (T[] args) with
 *   compiler sugar at the call site, and varargs is the LAST resort when the
 *   compiler picks between overloads.
 *
 * WHAT YOU WILL SEE
 *   varArgDemo(1, 2, 3)                -> Integer... with 3 args
 *   varArgDemo(new Integer[]{1,2,3})   -> Integer... with 3 args (array passed as-is)
 *   varArgDemo(new String[]{"a","b"})  -> String... with 2 args
 *   varArgDemo("")                     -> String... with 1 arg
 *   varArgDemo(list.toArray(new Integer[0])) -> Integer... with 2 args
 *   pick(7)                            -> fixed-arity Integer, not the varargs one
 *
 *   Fixed: the original file called varArgDemo(someList). A List<Integer> is
 *   not an Integer[], so that did not compile. The fix is to hand over an
 *   array: list.toArray(new Integer[0]).
 *
 * HOW IT WORKS
 *   1. At a call site javac wraps the loose arguments into a new array, so
 *      varArgDemo(1, 2, 3) becomes varArgDemo(new Integer[]{1, 2, 3}).
 *   2. If you already pass an array of the right type, no wrapping happens and
 *      that exact array instance is used.
 *   3. Overloads are chosen in three phases:
 *        phase 1 - exact match / widening, no boxing, no varargs
 *        phase 2 - boxing and unboxing allowed, still no varargs
 *        phase 3 - varargs considered
 *      The first phase that finds a match wins, which is why pick(7) picks the
 *      fixed-arity Integer overload.
 *
 * KEY INSIGHT
 *   Varargs is array sugar resolved at compile time. Two rules cover almost
 *   every trick question: a varargs method is never chosen while any
 *   fixed-arity method applies, and passing an array skips the wrapping.
 *
 * GOTCHAS
 *   - varArgDemo() with no arguments would not compile here: both Integer...
 *     and String... match an empty call and neither is more specific.
 *   - Passing a single null to T... is ambiguous between "the whole array is
 *     null" and "one null element"; cast it, e.g. (String) null.
 *   - A collection is not an array, so a List never satisfies T... directly.
 *
 * INTERVIEW FOLLOW-UPS
 *   - What does varargs compile down to in the bytecode?
 *   - Why can varargs only be the last parameter?
 *   - Why does the compiler warn about generic varargs, and what is @SafeVarargs?
 *   - What does f(null) resolve to when overloads take String... and Object...?
 *
 * RUN
 *   main() runs 6 cases (loose args, an Integer[] passed directly, a String[]
 *   passed directly, a single literal, a list converted to an array, and
 *   fixed-arity vs varargs) and prints actual vs expected.
 */
import java.util.ArrayList;
import java.util.List;

class VarArgDemo {

    public static void main(String[] args) {
        List<Integer> numbers = new ArrayList<>();
        numbers.add(10);
        numbers.add(20);

        Integer[] boxed = {1, 2, 3};
        String[] words = {"a", "b"};

        print("case 1: three loose ints", varArgDemo(1, 2, 3), "Integer... with 3 args");
        print("case 2: Integer[] passed directly", varArgDemo(boxed), "Integer... with 3 args");
        print("case 3: String[] passed directly", varArgDemo(words), "String... with 2 args");
        print("case 4: single empty string", varArgDemo(""), "String... with 1 args");
        // A List is not an array, so it must be converted first - this was the original bug.
        print("case 5: list converted to array", varArgDemo(numbers.toArray(new Integer[0])),
                "Integer... with 2 args");
        print("case 6: fixed-arity beats varargs", pick(7), "fixed-arity Integer");
    }

    private static String varArgDemo(Integer... list) {
        return "Integer... with " + list.length + " args";
    }

    private static String varArgDemo(String... list) {
        return "String... with " + list.length + " args";
    }

    /** Phase 2 (boxing) finds this, so phase 3 (varargs) is never reached. */
    private static String pick(Integer value) {
        return "fixed-arity Integer";
    }

    private static String pick(Integer... values) {
        return "varargs Integer...";
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Array clone() is a shallow copy            Java language | Easy
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   arr.clone() on a two-dimensional array copies only the OUTER array of
 *   references. The inner rows are shared between the original and the copy,
 *   so writing through one is visible through the other.
 *
 * WHAT YOU WILL SEE
 *   arr    = [[8, 9], [7, 8, 6]]
 *   cloned = arr.clone()          -> prints the same contents
 *   cloned != arr                 -> true  (a new outer array)
 *   cloned[0] == arr[0]           -> true  (the SAME row object)
 *   cloned[0][0] = 99             -> arr[0][0] is now 99 as well
 *   deepCopy(arr) breaks that link, so the original stays untouched.
 *
 * HOW IT WORKS
 *   1. int[][] is an array whose elements are int[] REFERENCES.
 *   2. clone() allocates a new outer array and copies those references, one
 *      slot at a time - it never looks inside a row.
 *   3. So cloned[0] and arr[0] point at one and the same int[] on the heap.
 *   4. deepCopy() fixes it by cloning each row as well; for a 1-D int[] a
 *      clone IS a full copy, because the elements are primitives, not refs.
 *
 * KEY INSIGHT
 *   clone(), Arrays.copyOf() and System.arraycopy() all copy one level. Copy
 *   depth must match reference depth: every level that holds references needs
 *   its own copy, which is exactly the defensive-copy rule for mutable fields.
 *
 * GOTCHAS
 *   - The same trap hits arrays of objects, List.copyOf() and new
 *     ArrayList<>(other): the elements themselves are still shared.
 *   - Arrays.equals() compares rows by reference; use Arrays.deepEquals().
 *   - Arrays.toString() on int[][] prints hashes; use Arrays.deepToString().
 *
 * INTERVIEW FOLLOW-UPS
 *   - How would you deep-copy an arbitrary object graph, and what about cycles?
 *   - Why is Cloneable considered a broken interface?
 *   - Where does a shallow copy actually bite you in production code?
 *   - Is a copy constructor or a static factory better than clone()? Why?
 *
 * RUN
 *   main() runs 3 cases (identity checks, shared-row mutation, deep copy) and
 *   prints actual vs expected.
 */
import java.util.Arrays;

class ArrayCloneExample {

    public static void main(String[] args) {
        int[][] arr = {{8, 9}, {7, 8, 6}};
        int[][] cloned = arr.clone();

        print("case 1: contents after clone", Arrays.deepToString(cloned),
                "[[8, 9], [7, 8, 6]]");
        print("case 1: new outer array?", cloned != arr, true);
        print("case 1: row 0 shared?", cloned[0] == arr[0], true);

        // Writing through the copy is visible through the original: same row object.
        cloned[0][0] = 99;
        print("case 2: original after cloned[0][0] = 99", Arrays.deepToString(arr),
                "[[99, 9], [7, 8, 6]]");

        // Edge case: a deep copy gives rows of its own, so the original is safe.
        int[][] deep = deepCopy(arr);
        deep[0][0] = -1;
        print("case 3: original after deep copy write", Arrays.deepToString(arr),
                "[[99, 9], [7, 8, 6]]");
        print("case 3: deep copy itself", Arrays.deepToString(deep), "[[-1, 9], [7, 8, 6]]");
        print("case 3: row 0 shared?", deep[0] == arr[0], false);
    }

    /** Clones the outer array AND every row, so nothing is shared. */
    private static int[][] deepCopy(int[][] source) {
        int[][] copy = new int[source.length][];
        for (int i = 0; i < source.length; i++) {
            copy[i] = source[i].clone();  // rows hold primitives, so this is a full copy
        }
        return copy;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Static generic methods and type inference    Java language | Easy
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   A generic method declares its own type parameter before the return type,
 *   as in "static <T> T echo(T value)". The class itself does not have to be
 *   generic, and the caller never has to spell T out - javac infers it from
 *   the arguments.
 *
 * WHAT YOU WILL SEE
 *   echo(123)            -> 123          T inferred as Integer (autoboxed)
 *   echo("I am string")  -> I am string  T inferred as String
 *   echo(25.89)          -> 25.89        T inferred as Double
 *   larger("apple", "pear")  -> pear     bounded T extends Comparable<T>
 *   Runtime class of T inside the method: Integer, String, Double - the VALUE
 *   still knows its class, even though T itself is erased.
 *
 *   Fixed: the original used new Integer(123) and new Double(25.89). Those
 *   constructors are deprecated for removal since Java 9; autoboxing or
 *   valueOf() is the modern form and it caches small values.
 *
 * HOW IT WORKS
 *   1. <T> before the return type introduces the type parameter.
 *   2. javac infers T at the call site from the static type of the argument.
 *   3. After compilation T is ERASED to its bound (Object here), so there is
 *      one method in the bytecode, not one per type.
 *   4. Erasure removes the type ARGUMENT, not the object: value.getClass()
 *      still reports Integer, because the object carries its own class.
 *   5. larger() shows a bound: <T extends Comparable<T>> is what lets the body
 *      call compareTo at all.
 *
 * KEY INSIGHT
 *   Generics are a compile-time contract. They buy type safety and remove
 *   casts at the call site; at run time the type argument is gone. Any time
 *   you need T at run time you must pass a Class<T> token or capture it in a
 *   subclass - which is exactly the super-type-token trick.
 *
 * GOTCHAS
 *   - You cannot write new T(), new T[10], or T.class inside the method.
 *   - instanceof List<String> does not compile; only List<?> does.
 *   - A generic method can be called explicitly: NonGenericClass.<String>echo("x").
 *
 * INTERVIEW FOLLOW-UPS
 *   - What is type erasure, and why did Java choose it over reified generics?
 *   - When do you need <T extends Comparable<? super T>> instead of Comparable<T>?
 *   - Explain PECS: when is List<? extends T> right, and when List<? super T>?
 *   - How do you get the real type argument back at run time?
 *
 * RUN
 *   main() runs 4 cases (Integer, String, Double, bounded comparison) and
 *   prints actual vs expected.
 */
class NonGenericClass {

    /** <T> is declared by the METHOD, so the enclosing class need not be generic. */
    static <T> T echo(T value) {
        T copy = value;   // T behaves like Object at run time, but is type-checked here
        return copy;
    }

    /** The runtime class of the value survives erasure; the type argument does not. */
    static <T> String runtimeClassOf(T value) {
        return value.getClass().getSimpleName();
    }

    /** A bound is what makes a method call on T legal inside the body. */
    static <T extends Comparable<T>> T larger(T a, T b) {
        return a.compareTo(b) >= 0 ? a : b;
    }
}

class GenericsInJava {

    public static void main(String[] args) {
        print("case 1: Integer argument", NonGenericClass.echo(123), 123);
        print("case 1: runtime class", NonGenericClass.runtimeClassOf(123), "Integer");

        print("case 2: String argument", NonGenericClass.echo("I am string"), "I am string");
        print("case 2: runtime class", NonGenericClass.runtimeClassOf("I am string"), "String");

        print("case 3: Double argument", NonGenericClass.echo(25.89), 25.89);
        print("case 3: runtime class", NonGenericClass.runtimeClassOf(25.89), "Double");

        // Edge case: a bounded type parameter, and an explicit type argument at the call site.
        print("case 4: larger of two strings", NonGenericClass.larger("apple", "pear"), "pear");
        print("case 4: explicit type argument", NonGenericClass.<String>echo("explicit"),
                "explicit");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Enums with constant-specific bodies        Java language | Easy
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   An enum can declare an abstract method and let every constant supply its
 *   own implementation in a class body. That turns the enum into a small,
 *   exhaustive strategy table: the behaviour lives next to the constant
 *   instead of inside a switch somewhere else.
 *
 * WHAT YOU WILL SEE
 *   SUNDAY.describe()          -> "SUNDAY is a weekend day (value 0)"
 *   MONDAY.describe()          -> "MONDAY starts the work week (value 1)"
 *   MyEnum.valueOf("MONDAY")   -> MONDAY, and .value is 1
 *   MyEnum.valueOf("FUNDAY")   -> IllegalArgumentException
 *   SUNDAY.getClass() == MyEnum.class          -> false (anonymous subclass)
 *   SUNDAY.getDeclaringClass() == MyEnum.class -> true
 *
 * HOW IT WORKS
 *   1. MyEnum declares a final int field, a private constructor and an
 *      abstract method describe().
 *   2. Each constant is followed by { ... }, which compiles to an ANONYMOUS
 *      SUBCLASS of MyEnum overriding describe(). That is why the enum can be
 *      abstract yet still have instances.
 *   3. values() returns a fresh array of the constants in declaration order;
 *      valueOf(String) does an exact-name lookup and throws if it misses.
 *   4. Calling describe() on a constant is ordinary virtual dispatch into that
 *      constant's own subclass body.
 *
 * KEY INSIGHT
 *   A constant-specific body is an anonymous subclass. Because of that,
 *   getClass() is NOT MyEnum - use getDeclaringClass() (or name() and
 *   ordinal()) whenever you need the enum type itself, for example as a map
 *   key or in reflection.
 *
 * GOTCHAS
 *   - values() copies the array on every call; cache it in a hot loop.
 *   - ordinal() shifts the moment someone reorders the constants, so never
 *     persist it; store name() instead.
 *   - Enum constructors are implicitly private and run before any static
 *     field of the enum is initialised.
 *   - Use EnumMap and EnumSet, not HashMap and HashSet, for enum keys.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why is a single-constant enum the best singleton in Java?
 *   - Constant-specific bodies versus a switch on the enum: which and why?
 *   - Can an enum implement an interface? Can it extend a class?
 *   - How do enums behave across serialization, and why is that safe?
 *
 * RUN
 *   main() runs 3 cases (every constant, lookup by name including the bad
 *   name, and the anonymous-subclass check) and prints actual vs expected.
 */
class EnumDemo {

    public static void main(String[] args) {
        // Case 1: iterate the constants in declaration order.
        StringBuilder all = new StringBuilder();
        for (MyEnum constant : MyEnum.values()) {
            all.append("[").append(constant.describe()).append("]");
        }
        print("case 1: every constant", all,
                "[SUNDAY is a weekend day (value 0)][MONDAY starts the work week (value 1)]");
        print("case 1: how many constants", MyEnum.values().length, 2);

        // Case 2: lookup by name, including the failing edge case.
        print("case 2: valueOf(\"MONDAY\").value", MyEnum.valueOf("MONDAY").value, 1);
        print("case 2: valueOf(\"FUNDAY\")", lookupOrError("FUNDAY"), "IllegalArgumentException");

        // Case 3: a constant-specific body means the constant is an anonymous subclass.
        print("case 3: getClass() == MyEnum.class", MyEnum.SUNDAY.getClass() == MyEnum.class,
                false);
        print("case 3: getDeclaringClass() == MyEnum.class",
                MyEnum.SUNDAY.getDeclaringClass() == MyEnum.class, true);
        print("case 3: name and ordinal", MyEnum.MONDAY.name() + "/" + MyEnum.MONDAY.ordinal(),
                "MONDAY/1");
    }

    /** valueOf() is an exact-name lookup; anything else is an IllegalArgumentException. */
    private static String lookupOrError(String name) {
        try {
            return MyEnum.valueOf(name).name();
        } catch (IllegalArgumentException e) {
            return "IllegalArgumentException";
        }
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

enum MyEnum {

    // Each { ... } body compiles to an anonymous subclass of MyEnum.
    SUNDAY(0) {
        @Override
        String describe() {
            return name() + " is a weekend day (value " + value + ")";
        }
    },
    MONDAY(1) {
        @Override
        String describe() {
            return name() + " starts the work week (value " + value + ")";
        }
    };

    final int value;

    MyEnum(int value) {
        this.value = value;
    }

    /** Abstract, so every constant is forced to supply its own behaviour. */
    abstract String describe();
}

/*
 * =====================================================================
 *  TreeMap floorKey and friends                       Java Core | Easy
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   TreeMap is a sorted map (red-black tree), so on top of get/put it can answer
 *   "which key is nearest to this probe?" in O(log n). floorKey(k) returns the
 *   greatest key that is <= k, or null when every key in the map is bigger.
 *
 * WHAT YOU WILL SEE
 *   map = {5=A, 10=B, 15=C} floorKey(3)  -> null   no key is <= 3
 *   floorKey(12) -> 10     10 is the greatest key <= 12
 *   floorKey(10) -> 10     floor INCLUDES an exact match
 *   floorEntry(12) -> 10=B same lookup, but you also get the value
 *
 * HOW IT WORKS
 *   1. Walk down from the root comparing the probe with the current key.
 *   2. Going right (probe is bigger) records the current key as the best
 *      candidate so far; going left discards it.
 *   3. The last recorded candidate when the walk falls off the tree is the floor.
 *   4. Same walk, four answers: lower/higher EXCLUDE the probe,
 *      floor/ceiling INCLUDE it; floor/lower look down, ceiling/higher look up.
 *
 * KEY INSIGHT
 *   Reach for TreeMap the moment a problem says "nearest", "previous", "next",
 *   "last value before time T" or "which bucket does this fall into". A HashMap
 *   cannot answer those at all; scanning a sorted array is O(n) per query.
 *
 * GOTCHAS
 *   - The return type is Integer, not int: a miss returns null, so unboxing a
 *     floorKey result straight into an int can throw NullPointerException.
 *   - floorKey needs only a key to compare, so it works even when the key is absent.
 *   - Ordering comes from compareTo (or the supplied Comparator), never equals.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Difference between floorKey and lowerKey? (<= versus strictly <)
 *   - How would you find the value in force at a timestamp? (floorEntry on a
 *     TreeMap<timestamp, value> - the standard "time-based key-value store")
 *   - When is a sorted array plus binary search better? (static data, no inserts)
 *   - What does subMap/headMap give you that floorKey does not? (a live range view)
 *
 * RUN
 *   main() runs 3 groups of cases (typical, miss, exact match) and prints
 *   actual vs expected.
 */
import java.util.Map;
import java.util.TreeMap;

class FloorKeyExample {

    private static TreeMap<Integer, String> sampleMap() {
        TreeMap<Integer, String> map = new TreeMap<>();
        map.put(5, "A");
        map.put(10, "B");
        map.put(15, "C");
        return map;
    }

    /** Greatest key <= probe, or null when every key in the map is bigger. */
    static Integer floorKey(TreeMap<Integer, String> map, int probe) {
        return map.floorKey(probe);
    }

    /** Same walk as floorKey, but hands back the value too - the useful form in real code. */
    static Map.Entry<Integer, String> floorEntry(TreeMap<Integer, String> map, int probe) {
        return map.floorEntry(probe);
    }

    /** All four navigation keys side by side; this is the table people mix up. */
    static String neighbours(TreeMap<Integer, String> map, int probe) {
        return "lower=" + map.lowerKey(probe)      // strictly <  probe
                + " floor=" + map.floorKey(probe)     // <=            probe
                + " ceiling=" + map.ceilingKey(probe) // >=            probe
                + " higher=" + map.higherKey(probe);  // strictly >  probe
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        TreeMap<Integer, String> map = sampleMap();
        System.out.println("map                     : " + map);

        // Typical: probe sits between two keys.
        print("floorKey(12)            : ", floorKey(map, 12), 10);
        print("floorEntry(12)          : ", floorEntry(map, 12), "10=B");

        // Edge: probe below every key -> null, not an exception and not 0.
        print("floorKey(3)             : ", floorKey(map, 3), "null");
        print("floorEntry(3)           : ", floorEntry(map, 3), "null");

        // Tricky: exact match. floor includes it, lower does not.
        print("floorKey(10)            : ", floorKey(map, 10), 10);
        print("lowerKey(10)            : ", map.lowerKey(10), 5);
        print("neighbours(10)          : ", neighbours(map, 10),
                "lower=5 floor=10 ceiling=10 higher=15");

        // Probe above every key: floor is the last key, ceiling/higher are null.
        print("neighbours(99)          : ", neighbours(map, 99),
                "lower=15 floor=15 ceiling=null higher=null");
    }
}

/*
 * =====================================================================
 *  Default method diamond: A.super.m1()          Java Core | Easy
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   Since Java 8 an interface may ship a default method body. If a class
 *   implements two interfaces that BOTH provide a default m1(), the compiler
 *   refuses to guess which one you meant - the class must override m1() and,
 *   if it wants one of the inherited bodies, call it as A.super.m1().
 *
 * WHAT YOU WILL SEE
 *   DefaultM1InABInterfaces implements A, B, C
 *     m1()  -> "A m1"   the override delegates with A.super.m1()
 *     m2()  -> "C m2"   only C declares it, so no conflict, no override needed
 *   PicksB implements A, B
 *     m1()  -> "B m1"   same conflict, resolved the other way
 *   MostSpecificWins implements A, D   (D extends A and redeclares m1)
 *     m1()  -> "D m1"   NOT a conflict: D is more specific than A, so D wins
 *
 * HOW IT WORKS
 *   1. The compiler collects every default m1() reachable from the class.
 *   2. It drops any interface that a more specific interface already overrides
 *      (that is the MostSpecificWins case: D extends A, so A's body is out).
 *   3. If two unrelated candidates survive, that is an error the class must
 *      resolve by overriding m1() itself.
 *   4. Inside that override, <Interface>.super.<method>() names exactly one body.
 *      The named interface must be a DIRECT superinterface of this class.
 *
 * KEY INSIGHT
 *   Java has no multiple inheritance of state, but default methods give it
 *   multiple inheritance of behaviour - so it needs one tie-break rule.
 *   The rule, in order: a class body beats any interface; a more specific
 *   interface beats a less specific one; anything still tied is a compile error
 *   you settle with A.super.m1(). Recite it in that order.
 *
 * GOTCHAS
 *   - Delete the override below and the file stops compiling:
 *     "class DefaultM1InABInterfaces inherits unrelated defaults for m1()".
 *   - A.super.m1() is legal only inside the class that directly implements A,
 *     and only for a default method - not for an abstract or static one.
 *   - Interface static methods are never inherited, so they never collide.
 *
 * INTERVIEW FOLLOW-UPS
 *   - What if a superclass also declares m1()? (class always wins over interface)
 *   - Can a default method be made abstract again by a subinterface? (yes:
 *     redeclare it with no body, and implementers must supply one)
 *   - Why were default methods added at all? (to add stream() to Collection
 *     without breaking every existing implementation)
 *   - Difference between a default method and an abstract class? (no fields,
 *     no constructor, no state - and a class can have many interfaces)
 *
 * RUN
 *   main() runs 3 cases (the conflict resolved to A, resolved to B, and the
 *   more-specific-interface case) and prints actual vs expected.
 */

class DefaultM1InABInterfaces implements A, B, C {

    // Without this override the class does not compile: A and B both offer m1().
    @Override
    public String m1() {
        return A.super.m1();   // name exactly one inherited body
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        DefaultM1InABInterfaces picksA = new DefaultM1InABInterfaces();

        // Typical: conflict resolved in favour of A.
        print("A.super.m1()            : ", picksA.m1(), "A m1");

        // No conflict at all - only C declares m2(), so it is inherited as is.
        print("inherited m2()          : ", picksA.m2(), "C m2");

        // Same diamond, opposite choice: nothing about A makes it the default.
        print("B.super.m1()            : ", new PicksB().m1(), "B m1");

        // Edge: D extends A and redeclares m1, so D is more specific and wins
        // automatically - this class needs no override.
        print("most specific wins      : ", new MostSpecificWins().m1(), "D m1");
    }
}

/** Same A+B diamond, resolved the other way, to show the choice is arbitrary. */
class PicksB implements A, B {
    @Override
    public String m1() {
        return B.super.m1();
    }
}

/** D redeclares m1, so A's body is pruned before any conflict can arise. */
class MostSpecificWins implements A, D {
    // Deliberately empty: D's m1 overrides A's, so there is nothing to resolve.
}

interface A {
    default String m1() {
        return "A m1";
    }
}

interface B {
    default String m1() {
        return "B m1";
    }
}

interface C {
    default String m2() {
        return "C m2";
    }
}

interface D extends A {
    @Override
    default String m1() {
        return "D m1";
    }
}

/*
 * =====================================================================
 *  Parsing an offset date-time string into an Instant   Java Core | Easy
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   Turning text like "2025-11-12 23:31:00.000 +0530" into a java.time.Instant.
 *   The string carries a UTC offset, so it names a real point on the timeline;
 *   the job is to parse it with a DateTimeFormatter into an OffsetDateTime and
 *   then drop the offset with toInstant().
 *
 * WHAT YOU WILL SEE
 *   "2025-11-12 23:31:00.000 +0530" -> 2025-11-12T18:01:00Z   (23:31 minus 5h30)
 *   "2025-11-12 23:31:00.000 -0800" -> 2025-11-13T07:31:00Z   (23:31 plus 8h)
 *   "2025-11-12 18:01:00.000 +0000" -> 2025-11-12T18:01:00Z   same instant as case 1
 *   "2025-11-12 23:31:00.000"       -> DateTimeParseException  no offset in the text
 *
 * HOW IT WORKS
 *   1. Build a DateTimeFormatter whose pattern mirrors the text exactly:
 *      "yyyy-MM-dd HH:mm:ss.SSS Z".  Z means an RFC-822 offset such as +0530.
 *   2. OffsetDateTime.parse(text, formatter) gives local fields PLUS the offset.
 *   3. toInstant() subtracts the offset, leaving a UTC point in time.
 *   4. Instant.toString() always prints in UTC and ends in Z.
 *
 * KEY INSIGHT
 *   Pick the java.time type by how much the text actually tells you.
 *   LocalDateTime = wall clock with no offset, so it is NOT a point in time.
 *   OffsetDateTime = wall clock plus a fixed offset, so it is.
 *   ZonedDateTime = wall clock plus a zone id, so it also knows DST rules.
 *   Instant = the point in time alone. Store Instant, display ZonedDateTime.
 *
 * GOTCHAS
 *   - Pattern letters are case sensitive: "mm" is minutes, "MM" is months, and
 *     "hh" is a 12-hour clock that needs an am/pm field.
 *   - "Z" in the pattern parses +0530; "XXX" parses +05:30; "VV" parses
 *     Asia/Kolkata. Use the one that matches your input.
 *   - Two different offset strings can denote the SAME instant, so compare
 *     Instants (or use isEqual), never the formatted text.
 *   - Parsing text with no offset into OffsetDateTime throws - it would have to
 *     invent a zone. Parse it as LocalDateTime and attach a zone on purpose.
 *
 * INTERVIEW FOLLOW-UPS
 *   - How do you go from Instant back to a user's local time? (atZone(zoneId))
 *   - Why is Instant preferred over java.util.Date in an entity? (immutable,
 *     thread-safe, nanosecond precision, no hidden default time zone)
 *   - What breaks if you store LocalDateTime for an event that spans zones?
 *   - How do you handle a DST gap, e.g. 02:30 on a spring-forward day?
 *
 * RUN
 *   main() runs 4 cases (typical +0530, negative offset, equal-instant check,
 *   and the missing-offset failure) and prints actual vs expected.
 */
import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;

class StringZonedDateTimeToInstant {

    /** Mirrors "2025-11-12 23:31:00.000 +0530"; Z is the RFC-822 style offset. */
    private static final DateTimeFormatter FORMAT =
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.SSS Z");

    /** Text with an offset -> the UTC point in time it names. */
    static Instant toInstant(String text) {
        OffsetDateTime offsetDateTime = OffsetDateTime.parse(text, FORMAT);
        return offsetDateTime.toInstant();   // subtracts the offset, result is UTC
    }

    /** Returns the exception type name instead of blowing up, so main can assert on it. */
    static String toInstantOrError(String text) {
        try {
            return toInstant(text).toString();
        } catch (DateTimeParseException e) {
            return "DateTimeParseException";
        }
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // Typical: India offset, so UTC is 5h30m earlier.
        print("+0530                   : ", toInstant("2025-11-12 23:31:00.000 +0530"),
                "2025-11-12T18:01:00Z");

        // Edge: negative offset pushes UTC past midnight into the next day.
        print("-0800 (rolls the date)  : ", toInstant("2025-11-12 23:31:00.000 -0800"),
                "2025-11-13T07:31:00Z");

        // Tricky: different text, different offset, same point in time.
        Instant india = toInstant("2025-11-12 23:31:00.000 +0530");
        Instant utc = toInstant("2025-11-12 18:01:00.000 +0000");
        print("same instant?           : ", india.equals(utc), true);

        // Edge: no offset in the text, so OffsetDateTime has nothing to anchor to.
        print("no offset in text       : ", toInstantOrError("2025-11-12 23:31:00.000"),
                "DateTimeParseException");
    }
}

/*
 * =====================================================================
 *  Logging an exception so the stack trace survives   Java Core | Easy
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   The single most common logging bug in Java services: log.error("boom: " + e)
 *   prints only the exception's toString (class name and message) and throws the
 *   stack trace away. Passing the exception as an extra TRAILING argument -
 *   log.error("boom {}", id, e) - prints the full trace with every frame.
 *
 *   The original file used Lombok's @Slf4j and a real SLF4J binding. Those are
 *   external jars, so this scratch file ships MiniLogger: about 30 lines that
 *   implement SLF4J's own MessageFormatter rule, letting the demo run with
 *   nothing on the classpath. The call sites are exactly what you would write
 *   against a real logger.
 *
 * WHAT YOU WILL SEE
 *   log.error("error : " + e)          -> one line, no frames          (BAD)
 *   log.error("error {}", "123", e)    -> "error 123" plus full trace  (GOOD)
 *   log.error("error {} {}", "123", e) -> "error 123 java.lang..."     (TRAP)
 *                                         two placeholders swallow the throwable
 *
 * HOW IT WORKS
 *   1. SLF4J never formats with String.format; it scans the message for "{}"
 *      and substitutes the arguments in order. That is why it is cheap: nothing
 *      is built when the level is disabled.
 *   2. After substitution, if the LAST argument is a Throwable and there were
 *      more arguments than placeholders, it is not a placeholder value - it is
 *      the exception, and the appender prints its stack trace.
 *   3. So the throwable must be left over. Add a placeholder for it and it gets
 *      formatted as text instead, and the trace is lost.
 *   4. Concatenation never leaves anything over, so it never prints a trace.
 *
 * KEY INSIGHT
 *   The exception argument is positional, not typed magic: it must be the last
 *   argument AND unmatched by any "{}". Remember it as "one more argument than
 *   you have braces". Same rule in Logback and Log4j2.
 *
 * GOTCHAS
 *   - log.error("failed", e.getMessage()) loses the trace too - a String is not
 *     a Throwable, so nothing triggers the trace printing.
 *   - Do not log and rethrow the same exception; the caller logs it again and
 *     you get the trace twice under two different timestamps.
 *   - e.printStackTrace() bypasses the logging framework entirely: no level,
 *     no appender, no correlation id.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why parameterized logging instead of concatenation, even without an
 *     exception? (no string is built when the level is off)
 *   - What does getCause()/initCause() give you here? (the "Caused by" chain)
 *   - How do you keep the trace when wrapping? (new ServiceException(msg, e))
 *   - Where does the MDC fit in? (per-thread context such as a request id)
 *
 * RUN
 *   main() runs 3 cases (concatenation, correct trailing throwable, and the
 *   too-many-placeholders trap) and prints actual vs expected.
 */
import java.io.PrintWriter;
import java.io.StringWriter;
import java.util.Arrays;

class ExceptionLoggingDemo {

    private static final MiniLogger log = new MiniLogger(ExceptionLoggingDemo.class.getName());

    public static void main(String[] args) {
        m1();
    }

    private static void m1() {
        m2();
    }

    private static void m2() {
        longName();
    }

    /** Deliberately several frames deep so a real stack trace has something to show. */
    private static void longName() {
        try {
            throw new RuntimeException("some exception");
        } catch (RuntimeException e) {

            // BAD: the exception is flattened into the message, so only its
            // toString survives and every frame is lost.
            banner("1 concatenation      ", "log.error(\"error : \" + e)");
            report("1 concatenation      ", log.error("error : " + e), false);

            // GOOD: one "{}" consumes "123", the trailing throwable is left over
            // and is therefore logged as the exception, trace and all.
            banner("2 trailing throwable ", "log.error(\"error {}\", \"123\", e)");
            report("2 trailing throwable ", log.error("error {}", "123", e), true);

            // TRAP: two "{}" for two arguments, so the throwable fills the second
            // placeholder as text and nothing is left over to print a trace.
            banner("3 swallowed by {}    ", "log.error(\"error {} {}\", \"123\", e)");
            report("3 swallowed by {}    ", log.error("error {} {}", "123", e), false);
        }
    }

    private static void banner(String label, String callSite) {
        System.out.println("---- case " + label + ": " + callSite + " ----");
    }

    /** The record was already printed by the logger; this line is the assertion. */
    private static void report(String label, String record, boolean expectTrace) {
        System.out.println("case " + label + ": stackFrames=" + countFrames(record)
                + " hasTrace=" + (countFrames(record) > 0)
                + "   expected hasTrace=" + expectTrace);
        System.out.println();
    }

    /** A stack frame line is "\tat some.Class.method(File.java:NN)". */
    private static int countFrames(String record) {
        int frames = 0;
        for (String line : record.split("\\R")) {
            if (line.strip().startsWith("at ")) {
                frames++;
            }
        }
        return frames;
    }
}

/**
 * The smallest logger that reproduces SLF4J's argument rule. Real code uses
 * Lombok's @Slf4j to generate the field and a binding such as Logback behind it.
 */
class MiniLogger {

    private final String name;

    MiniLogger(String name) {
        this.name = name;
    }

    /** Prints the record and also returns it so tests can assert on what was logged. */
    String error(String format, Object... args) {
        String record = "ERROR " + name + " -- " + render(format, args);
        System.out.println(record);
        return record;
    }

    /**
     * SLF4J's rule: substitute "{}" left to right; if the last argument is a
     * Throwable AND there are more arguments than placeholders, it is the
     * exception rather than a placeholder value, so print its stack trace.
     */
    private String render(String format, Object... args) {
        int placeholders = countPlaceholders(format);
        Object[] messageArgs = args;
        Throwable thrown = null;

        if (args.length > placeholders && args.length > 0
                && args[args.length - 1] instanceof Throwable last) {
            thrown = last;
            messageArgs = Arrays.copyOf(args, args.length - 1);
        }

        StringBuilder out = new StringBuilder(substitute(format, messageArgs));
        if (thrown != null) {
            out.append(System.lineSeparator()).append(stackTraceOf(thrown));
        }
        return out.toString();
    }

    private static int countPlaceholders(String format) {
        int count = 0;
        for (int i = format.indexOf("{}"); i >= 0; i = format.indexOf("{}", i + 2)) {
            count++;
        }
        return count;
    }

    private static String substitute(String format, Object[] args) {
        StringBuilder out = new StringBuilder();
        int from = 0;
        for (Object arg : args) {
            int at = format.indexOf("{}", from);
            if (at < 0) {
                break;          // more arguments than placeholders: the rest are dropped
            }
            out.append(format, from, at).append(arg);
            from = at + 2;
        }
        return out.append(format.substring(from)).toString();
    }

    private static String stackTraceOf(Throwable t) {
        StringWriter buffer = new StringWriter();
        t.printStackTrace(new PrintWriter(buffer));
        return buffer.toString().stripTrailing();
    }
}

/*
 * =====================================================================
 *  Stream and Collector recipes          Java Core | Medium   MUST-KNOW
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   The six stream pipelines that come up again and again in interviews and in
 *   real service code: frequency counting, filtering into an array or a list,
 *   flattening nested lists, "max per group" done two ways, and the difference
 *   between filtering inside a group and filtering before grouping.
 *
 * WHAT YOU WILL SEE
 *   countOccurrences([1,2,3,3,3,4,5])       -> {1=1, 2=1, 3=3, 4=1, 5=1}
 *   filter "A" from [Abc, Bac, Axy]         -> [Abc, Axy]
 *   flatten [[Alice,Bob],[Charlie,David],[Eve,Frank]]
 *                                           -> [Alice, Bob, Charlie, David, Eve, Frank]
 *   max salary per dept (Optional form)     -> {Finance=6500.0, HR=4500.0, IT=8000.0}
 *   max salary per dept (unwrapped form)    -> same numbers, no Optional to peel
 *   high earners > 7000, Collectors.filtering -> {Finance=[], HR=[], IT=[David]}
 *   high earners > 7000, filter first        -> {IT=[David]}   empty groups vanish
 *
 * HOW IT WORKS
 *   1. int[] has no stream of objects, so Arrays.stream(...).boxed() turns an
 *      IntStream into Stream<Integer> before any Collector can be used.
 *   2. groupingBy(classifier, downstream) buckets elements by the classifier and
 *      feeds each bucket to the downstream collector - counting(), toList(),
 *      maxBy(), filtering(), whatever reduces a group to one value.
 *   3. maxBy returns Optional because a reduction over a group has no identity
 *      value; collectingAndThen(maxBy(...), finisher) runs the finisher on each
 *      group's result, so the Optional is unwrapped inside the collector.
 *   4. flatMap replaces each element with the contents of a stream, so a
 *      Stream<List<String>> becomes a Stream<String>.
 *   5. Collectors.filtering (Java 9+) filters AFTER bucketing, so a group with
 *      no survivors still exists with an empty list. stream.filter before
 *      groupingBy removes the elements first, so that key never appears.
 *
 * KEY INSIGHT
 *   A stream pipeline is source -> intermediate ops -> one terminal op, and the
 *   whole shape of the result is decided by the terminal collector. So think
 *   in terms of the downstream collector: "what do I want each group reduced
 *   to?" - a count, a list, a max, a filtered list. And remember where the
 *   filter sits, because that alone decides whether empty groups survive.
 *
 * GOTCHAS
 *   - groupingBy returns a HashMap, so iteration order is unspecified. Wrap in
 *     a TreeMap (as main does) or pass a map factory when order matters.
 *   - groupingBy throws NullPointerException if the classifier returns null.
 *   - Collectors.toList() gives no guarantee of mutability; use toCollection or
 *     Stream.toList() (Java 16+, unmodifiable) when you care.
 *
 * INTERVIEW FOLLOW-UPS
 *   - groupingBy vs partitioningBy? (arbitrary keys vs exactly true/false)
 *   - How do you get a sorted or insertion-ordered result map? (three-arg
 *     groupingBy with TreeMap::new or LinkedHashMap::new)
 *   - Why does maxBy return Optional but counting() does not? (no identity)
 *   - When is parallelStream a win? (big CPU-bound work, splittable source,
 *     stateless associative reduction)
 *
 * RUN
 *   main() runs the six pipelines on a typical dataset plus an empty-input edge
 *   case, and prints actual vs expected.
 */

import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;
import java.util.stream.Stream;

class Streams {

    // int[] cannot be collected directly - boxed() turns IntStream into Stream<Integer>.
    static Map<Integer, Long> countOccurrences(int[] arr) {
        return Arrays.stream(arr)
                .boxed()
                .collect(Collectors.groupingBy(Function.identity(), Collectors.counting()));
    }

    // Two ways to end up with a String[]: toArray(generator) straight from the stream,
    // or collect to a List and then list.toArray(new String[0]).
    static String[] filterToArrayAndList(String[] words, String prefix) {
        String[] direct = Arrays.stream(words)
                .filter(s -> s.startsWith(prefix))
                .toArray(String[]::new);

        List<String> viaList = Stream.of(words)
                .filter(s -> s.startsWith(prefix))
                .collect(Collectors.toList());
        // new String[0] is the idiomatic size hint
        String[] fromList = viaList.toArray(new String[0]);

        if (!Arrays.equals(direct, fromList)) {
            throw new AssertionError("both routes must agree");
        }
        return direct;
    }

    // flatMap: each inner list becomes a stream, and the streams are concatenated.
    static List<String> flattenListOfLists(List<List<String>> listOfLists) {
        return listOfLists.stream()
                .flatMap(List::stream)
                .collect(Collectors.toList());
    }

    // Approach 1: maxBy returns Optional<Employee> (a reduction has no identity value),
    // so the map value is Optional and the caller has to unwrap it.
    static Map<String, Employee> maxSalaryByDepartment(List<Employee> employees) {
        return employees.stream()
                .collect(Collectors.groupingBy(
                        Employee::getDepartment,
                        Collectors.collectingAndThen(
                                Collectors.maxBy(Comparator.comparingDouble(Employee::getSalary)),
                                Optional::get
                        )
                ));
    }

    // Approach 2: collectingAndThen(downstream, finisher) runs the finisher on each group's
    // result, so the Optional is unwrapped inside the collector and the map is
    // Map<String, Double>.
    static Map<String, Double> maxSalaryUnwrapped(List<Employee> employees) {
        return employees.stream()
                .collect(Collectors.groupingBy(
                        Employee::getDepartment,
                        Collectors.collectingAndThen(
                                Collectors.maxBy(Comparator.comparingDouble(Employee::getSalary)),
                                opt -> opt.map(Employee::getSalary).orElse(0.0)
                        )
                ));
    }

    // Collectors.filtering (Java 9+) filters INSIDE each group -> departments with no match
    // still appear with an empty list.
    static Map<String, List<Employee>> highEarnersByDeptKeepEmptyGroups(List<Employee> employees,
                                                                        double threshold) {
        return employees.stream()
                .collect(Collectors.groupingBy(
                        Employee::getDepartment,
                        Collectors.filtering(e -> e.getSalary() > threshold, Collectors.toList())
                ));
    }

    // Stream.filter BEFORE groupingBy -> departments with no match are absent from the map.
    static Map<String, List<Employee>> highEarnersByDeptDropEmptyGroups(List<Employee> employees,
                                                                        double threshold) {
        return employees.stream()
                .filter(e -> e.getSalary() > threshold)
                .collect(Collectors.groupingBy(Employee::getDepartment));
    }

    /**
     * groupingBy hands back a HashMap; sort it so the printed output is deterministic.
     */
    private static <K, V> Map<K, V> sorted(Map<K, V> map) {
        return new TreeMap<>(map);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // ---- typical cases -------------------------------------------------
        print("countOccurrences        : ",
                sorted(countOccurrences(new int[]{1, 2, 3, 3, 3, 4, 5})),
                "{1=1, 2=1, 3=3, 4=1, 5=1}");

        print("filterToArrayAndList    : ",
                Arrays.toString(filterToArrayAndList(new String[]{"Abc", "Bac", "Axy"}, "A")),
                "[Abc, Axy]");

        print("flattenListOfLists      : ", flattenListOfLists(Arrays.asList(
                        Arrays.asList("Alice", "Bob"),
                        Arrays.asList("Charlie", "David"),
                        Arrays.asList("Eve", "Frank"))),
                "[Alice, Bob, Charlie, David, Eve, Frank]");

        List<Employee> employees = Employee.sample();
        System.out.println("employees               : " + employees);

        // Approach 1: the caller peels the Optional off every value.
        Map<String, Double> peeledByCaller = new TreeMap<>();
        maxSalaryByDepartment(employees).forEach((dept, best) ->
                peeledByCaller.put(dept, best.getSalary()));
        print("maxSalaryWithOptional   : ", peeledByCaller,
                "{Finance=6500.0, HR=4500.0, IT=8000.0}");

        // Approach 2: same numbers, but the collector already unwrapped them.
        print("maxSalaryUnwrapped      : ", sorted(maxSalaryUnwrapped(employees)),
                "{Finance=6500.0, HR=4500.0, IT=8000.0}");

        // The two filtering positions, side by side. Bob is exactly 7000, so he fails "> 7000".
        print("highEarners keepEmpty   : ",
                sorted(highEarnersByDeptKeepEmptyGroups(employees, 7000)),
                "{Finance=[], HR=[], IT=[David(IT,8000.0)]}");
        print("highEarners dropEmpty   : ",
                sorted(highEarnersByDeptDropEmptyGroups(employees, 7000)),
                "{IT=[David(IT,8000.0)]}");

        // ---- edge case: empty input ---------------------------------------
        // Every collector still returns an empty container, never null.
        print("empty countOccurrences  : ", countOccurrences(new int[]{}), "{}");
        print("empty flatten           : ", flattenListOfLists(new ArrayList<>()), "[]");
        print("empty maxSalary         : ", maxSalaryUnwrapped(new ArrayList<>()), "{}");
    }
}

class Employee {
    private final String name;
    private final String department;
    private final double salary;

    Employee(String name, String department, double salary) {
        this.name = name;
        this.department = department;
        this.salary = salary;
    }

    String getDepartment() {
        return department;
    }

    double getSalary() {
        return salary;
    }

    @Override
    public String toString() {
        return name + "(" + department + "," + salary + ")";
    }

    // Salaries chosen so the 7000 threshold splits them: only David passes,
    // Bob is exactly 7000 (not >).
    static List<Employee> sample() {
        return Arrays.asList(
                new Employee("Alice", "HR", 4000),
                new Employee("Bob", "IT", 7000),
                new Employee("Charlie", "HR", 4500),
                new Employee("David", "IT", 8000),
                new Employee("Eve", "Finance", 6500)
        );
    }
}

/*
 * =====================================================================
 *  JDK Dynamic Proxy (InvocationHandler)          Java core | Medium   MUST-KNOW
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   How to create, at runtime, an object that implements one or more interfaces without
 *   writing a class for it. Every call on that object is funnelled into a single method,
 *   InvocationHandler.invoke, where you can log, time, retry, or delegate. This is the
 *   machinery behind Spring AOP, @Transactional, Mockito mocks and MyBatis mappers.
 *
 * WHAT YOU WILL SEE
 *   case 1: a call to performAction() is wrapped with "before" and "after" work and then
 *           forwarded to the real OriginalClass instance.
 *   case 2: a call to additionalAction() - a method the real object does NOT implement -
 *           is served entirely by the handler, because the proxy implements that interface
 *           too. Blindly forwarding it would blow up (see GOTCHAS).
 *   case 3: identity checks - the proxy is an instance of both interfaces and its class
 *           was generated at runtime, so it is not OriginalClass.
 *
 * HOW IT WORKS
 *   1. Proxy.newProxyInstance(loader, interfaces, handler) generates a class such as
 *      $Proxy0 that implements every interface in the array.
 *   2. Each generated method body is the same: package the arguments and call
 *      handler.invoke(proxyItself, theMethodObject, args).
 *   3. The handler decides what to do. Here it appends to a call log, then either
 *      reflects the call onto the wrapped target or answers it itself.
 *   4. Whatever invoke returns is returned to the caller, so the return type must match.
 *
 * KEY INSIGHT
 *   The proxy is typed by INTERFACES, not by the target object. The interface list and
 *   the target are independent: the proxy can expose methods the target never had, and it
 *   can hide that a target exists at all. That decoupling is why one handler (a
 *   transaction interceptor, say) can wrap any bean in the container.
 *
 * GOTCHAS
 *   - The target class is irrelevant to the type of the proxy. Forwarding additionalAction
 *     with method.invoke(target, args) throws IllegalArgumentException ("object is not an
 *     instance of declaring class"), which is why the handler checks first.
 *   - JDK proxies need an interface. To proxy a concrete class you need CGLIB or
 *     ByteBuddy, which subclass it - that is why Spring switches proxy modes.
 *   - equals, hashCode and toString also reach invoke; forgetting them gives a proxy whose
 *     toString recurses or whose equals is broken.
 *   - A self-call inside the target (this.other()) does NOT go through the proxy. That is
 *     the classic "my @Transactional method is ignored" bug.
 *
 * INTERVIEW FOLLOW-UPS
 *   - JDK proxy vs CGLIB: interfaces vs subclassing, final methods, no-arg constructors.
 *   - How would you add retry-with-backoff to every method of a service using this?
 *   - Why does calling a @Transactional method from another method of the same bean fail?
 *   - What is the cost of reflection here, and how does Spring reduce it?
 *
 * RUN
 *   main() runs 3 cases (forwarded call, handler-only call, identity checks) and prints
 *   actual vs expected.
 */

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;

// Step 1: the interfaces the proxy will implement.
interface OriginalInterface {
    void performAction();
}

interface AdditionalInterface {
    void additionalAction();
}

// Step 2: the real object. Note it implements ONLY OriginalInterface.
class OriginalClass implements OriginalInterface {
    public void performAction() {
        System.out.println("  target: performing the original action...");
    }
}

// Step 3: the one method every proxy call is funnelled into.
class ProxyHandler implements InvocationHandler {
    private final Object originalObject;
    private final List<String> callLog = new ArrayList<>();

    public ProxyHandler(Object originalObject) {
        this.originalObject = originalObject;
    }

    public List<String> getCallLog() {
        return List.copyOf(callLog);
    }

    @Override
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        // Object's own methods must never be forwarded blindly or toString can recurse.
        if (method.getDeclaringClass() == Object.class) {
            return method.invoke(this, args);
        }

        callLog.add("before:" + method.getName());
        System.out.println("  handler: before " + method.getName());

        Object result;
        // The proxy may expose interfaces the target does not implement, so check first.
        if (method.getDeclaringClass().isInstance(originalObject)) {
            result = method.invoke(originalObject, args);       // forward to the real object
        } else {
            System.out.println("  handler: target has no " + method.getName()
                    + "(), serving it here");
            callLog.add("handled-by-proxy:" + method.getName());
            result = null;                                      // void method, so null is fine
        }

        System.out.println("  handler: after " + method.getName());
        callLog.add("after:" + method.getName());
        return result;
    }
}

// Step 4: build the proxy and exercise it.
class DynamicProxyDemo {

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        OriginalInterface originalObject = new OriginalClass();
        ProxyHandler handler = new ProxyHandler(originalObject);

        Object proxy = Proxy.newProxyInstance(
                OriginalInterface.class.getClassLoader(),
                new Class<?>[]{OriginalInterface.class, AdditionalInterface.class},
                handler);

        // case 1: a method the target really implements - forwarded.
        System.out.println("case 1: performAction() on the proxy");
        ((OriginalInterface) proxy).performAction();
        print("case 1 log", handler.getCallLog(),
                "[before:performAction, after:performAction]");

        // case 2: a method only the PROXY implements - answered by the handler.
        System.out.println("case 2: additionalAction() on the proxy");
        ((AdditionalInterface) proxy).additionalAction();
        print("case 2 log", handler.getCallLog(),
                "[before:performAction, after:performAction, before:additionalAction, "
                        + "handled-by-proxy:additionalAction, after:additionalAction]");

        // case 3: what the proxy actually is.
        print("case 3 isProxyClass", Proxy.isProxyClass(proxy.getClass()), true);
        print("case 3 is OriginalInterface", proxy instanceof OriginalInterface, true);
        print("case 3 is AdditionalInterface", proxy instanceof AdditionalInterface, true);
        print("case 3 is OriginalClass", proxy instanceof OriginalClass, false);
        print("case 3 handler round-trip", Proxy.getInvocationHandler(proxy) == handler, true);
    }
}

/*
 * =====================================================================
 *  TreeSet uses compareTo, never equals          Java core | Hard
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   A Node has a vertex id and a distance. equals/hashCode compare the VERTEX (two nodes
 *   are the same graph node), but compareTo compares the DISTANCE (so the set is ordered
 *   by distance, which is what Dijkstra wants). Those two answers disagree, and a sorted
 *   collection believes only compareTo. This is the classic decrease-key bug.
 *
 * WHAT YOU WILL SEE
 *   case 1  adding vertex 4 at distance 10 to a set that already holds vertex 0 at
 *           distance 10 is REJECTED as a duplicate - the set silently loses a node.
 *   case 2  remove(new Node(2, 99)) returns false even though equals() says that object
 *           is vertex 2, because no element compares equal to distance 99.
 *   case 3  the correct decrease-key: remove with the OLD distance, then add the new one.
 *   case 4  the fix - a comparator that breaks ties on vertex, so ordering agrees
 *           with equals and both traps disappear.
 *
 * HOW IT WORKS
 *   TreeSet is a TreeMap of red-black nodes. Every add, remove and contains walks the
 *   tree using compareTo (or the supplied Comparator) and stops when it reads 0. It never
 *   calls equals or hashCode. So "this element is already here" and "this is the element
 *   you asked me to delete" both mean "compareTo returned 0", nothing else.
 *
 * KEY INSIGHT
 *   A sorted collection's notion of identity IS its comparator. If compareTo can return 0
 *   for two objects that are not equals(), a TreeSet will drop one of them; if it can
 *   return non-zero for two objects that ARE equals(), you cannot remove by identity. Make
 *   the comparator a total order that ends in a unique tie-breaker (here, the vertex id).
 *   Same reasoning applies to PriorityQueue.remove, which instead uses equals and is O(n).
 *
 * GOTCHAS
 *   - The Comparable javadoc calls "consistent with equals" strongly recommended, not
 *     required - so the compiler will never warn you about this.
 *   - contains() has the same blind spot: a List would find vertex 2 by equals, the
 *     TreeSet will not.
 *   - Mutating an element's distance while it sits in the set corrupts the tree: the
 *     element is now in the wrong place and may be unreachable. Always remove, mutate,
 *     re-add.
 *
 * INTERVIEW FOLLOW-UPS
 *   - How do you implement decrease-key with a PriorityQueue instead? (lazy deletion:
 *     push the new pair and skip stale pops with a seen[] or a best-distance check)
 *   - Why is PriorityQueue.remove(Object) O(n) while TreeSet.remove is O(log n)?
 *   - When is a comparator inconsistent with equals actually fine? (BigDecimal in a
 *     TreeSet: 1.0 and 1.00 collapse, which may be exactly what you want)
 *   - What breaks if compareTo is not a total order, e.g. it is not transitive?
 *
 * RUN
 *   main() runs 4 cases (silent duplicate, failed remove, correct decrease-key, fixed
 *   comparator) and prints actual vs expected.
 */

import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.TreeSet;

class TreeSetRemoveExample {

    /** A graph node: ordered by distance, but identified by vertex. */
    static class Node implements Comparable<Node> {
        final int vertex;
        final int distance;

        public Node(int vertex, int distance) {
            this.vertex = vertex;
            this.distance = distance;
        }

        @Override
        public int compareTo(Node other) {
            // Ordering is by distance only - this is the line that causes every trap below.
            return Integer.compare(this.distance, other.distance);
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            Node node = (Node) obj;
            return vertex == node.vertex;     // identity is the vertex, not the distance
        }

        @Override
        public int hashCode() {
            return Objects.hash(vertex);
        }

        @Override
        public String toString() {
            return "v" + vertex + ":d" + distance;
        }
    }

    /** Consistent with equals: order by distance, then break ties on the vertex id. */
    static final Comparator<Node> BY_DISTANCE_THEN_VERTEX =
            Comparator.comparingInt((Node n) -> n.distance).thenComparingInt(n -> n.vertex);

    private static TreeSet<Node> freshSet() {
        TreeSet<Node> set = new TreeSet<>();
        set.add(new Node(0, 10));
        set.add(new Node(1, 20));
        set.add(new Node(2, 15));
        set.add(new Node(3, 5));
        return set;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        TreeSet<Node> set = freshSet();
        print("initial set", set, "[v3:d5, v0:d10, v2:d15, v1:d20]");

        // ---- case 1: a distinct vertex that ties on distance is swallowed -------------
        boolean added = set.add(new Node(4, 10));   // same distance as vertex 0
        print("case 1 add(v4:d10)", added, false);
        print("case 1 size after add", set.size(), 4);
        print("case 1 set", set, "[v3:d5, v0:d10, v2:d15, v1:d20]");

        // ---- case 2: equals() says yes, the tree search says no ----------------------
        Node lookalike = new Node(2, 99);           // equals() vertex 2, wrong distance
        print("case 2 equals(v2:d15)", lookalike.equals(new Node(2, 15)), true);
        print("case 2 list contains", List.copyOf(set).contains(lookalike), true);
        print("case 2 treeSet contains", set.contains(lookalike), false);
        print("case 2 remove", set.remove(lookalike), false);
        print("case 2 size", set.size(), 4);

        // ---- case 3: decrease-key done right - remove with the OLD key, then add ------
        boolean removed = set.remove(new Node(2, 15));   // exact old distance
        set.add(new Node(2, 7));                         // reinsert at the new distance
        print("case 3 remove(v2:d15)", removed, true);
        print("case 3 set", set, "[v3:d5, v2:d7, v0:d10, v1:d20]");

        // ---- case 4: the fix - ordering consistent with equals -----------------------
        TreeSet<Node> fixed = new TreeSet<>(BY_DISTANCE_THEN_VERTEX);
        fixed.add(new Node(0, 10));
        fixed.add(new Node(1, 20));
        fixed.add(new Node(2, 15));
        fixed.add(new Node(3, 5));
        print("case 4 add(v4:d10)", fixed.add(new Node(4, 10)), true);
        print("case 4 set", fixed, "[v3:d5, v0:d10, v4:d10, v2:d15, v1:d20]");
        print("case 4 remove(v2:d99)", fixed.remove(new Node(2, 99)), false);
        print("case 4 remove(v2:d15)", fixed.remove(new Node(2, 15)), true);
        print("case 4 final", fixed, "[v3:d5, v0:d10, v4:d10, v1:d20]");
    }
}

/*
 * =====================================================================
 *  Super type token: picking Response<T> at runtime      Java core | Hard
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   Every API here answers with the same envelope, Response<T>, where T depends on a
 *   "payloadType" string known only at runtime. Erasure means Response<Customer> and
 *   Response<Address> are the same class at run time, so you cannot say
 *   fromJson(json, Response<Customer>.class) - that is not even legal Java. The super
 *   type token trick recovers the full generic type and lets a binder use it.
 *
 * WHAT YOU WILL SEE
 *   case 1  a customer envelope binds to Response<Customer> and prints the name.
 *   case 2  an address envelope binds to Response<Address> and prints the street.
 *   case 3  an order envelope binds to Response<Order> and prints the amount (a double).
 *   case 4  a customer literally named "order" still routes to Customer - the old
 *           json.contains("order") dispatch got this wrong.
 *   case 5  erasure proof: the two envelopes share one Class object, yet the two type
 *           tokens report different types.
 *
 * HOW IT WORKS
 *   1. new TypeToken<Response<Customer>>() {} creates an ANONYMOUS SUBCLASS. Its
 *      superclass is recorded in the class file as TypeToken<Response<Customer>> - a
 *      generic supertype is metadata, so it survives erasure.
 *   2. The TypeToken constructor reads getClass().getGenericSuperclass(), casts it to
 *      ParameterizedType and takes getActualTypeArguments()[0]. That java.lang.reflect.Type
 *      is the whole Response<Customer>, raw class plus argument.
 *   3. MiniJson parses the text once into maps, lists, Strings and Doubles.
 *   4. MiniJson.bind walks the Type: for Response<Customer> it instantiates Response and,
 *      when it meets the field declared as T, resolves T to Customer by position and
 *      recurses. That is a 40-line version of what Gson and Jackson do.
 *
 * KEY INSIGHT
 *   Erasure removes the type argument from OBJECTS, not from CLASS DECLARATIONS. Anything
 *   written into a class file - a superclass, an implemented interface, a field or method
 *   signature - keeps its type arguments. Subclassing is therefore the standard smuggling
 *   route: that is why the token is always "new TypeToken<...>() {}" with braces, and why
 *   Gson's TypeToken, Jackson's TypeReference and Spring's ParameterizedTypeReference are
 *   all abstract classes you must subclass.
 *
 * GOTCHAS
 *   - Drop the {} and you get a raw TypeToken whose generic superclass is a plain Class;
 *     the constructor here fails fast with IllegalStateException (case 5 proves it).
 *   - The token must be built at a site where T is a real type. new TypeToken<T>() {}
 *     inside a generic method captures the type VARIABLE T, not the caller's argument.
 *   - Dispatching on json.contains("customer") reads the whole document, so any field
 *     value containing that word hijacks the route. Parse first, then switch on the
 *     discriminator field.
 *   - Fixed: dispatch now uses the parsed payloadType field, not substring matching.
 *   - Fixed: removed the external Gson dependency and the "package casting" line so the
 *     file compiles and runs standalone.
 *
 * INTERVIEW FOLLOW-UPS
 *   - How does Jackson do the same thing? (TypeReference, or
 *     mapper.getTypeFactory().constructParametricType(Response.class, Customer.class))
 *   - What is the RestTemplate/WebClient equivalent? (ParameterizedTypeReference)
 *   - Which generic information does erasure actually keep, and where is it stored?
 *   - How would you make the payloadType to type mapping open for extension?
 *
 * RUN
 *   main() runs 5 cases (three payload types, the misleading value, erasure proof) and
 *   prints actual vs expected.
 */

import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

class GenericTypeDynamically {

    // The braces at the end are the whole trick: they create an anonymous subclass whose
    // generic superclass records Response<Customer> in the class file.
    private static final Type CUSTOMER_RESPONSE_TYPE = new TypeToken<Response<Customer>>() {
    }.getType();
    private static final Type ADDRESS_RESPONSE_TYPE = new TypeToken<Response<Address>>() {
    }.getType();
    private static final Type ORDER_RESPONSE_TYPE = new TypeToken<Response<Order>>() {
    }.getType();

    /** payloadType value -> the fully generic envelope type to bind it to. */
    private static final Map<String, Type> TYPE_BY_PAYLOAD = Map.of(
            "customer", CUSTOMER_RESPONSE_TYPE,
            "address", ADDRESS_RESPONSE_TYPE,
            "order", ORDER_RESPONSE_TYPE);

    /**
     * Parses once, reads the discriminator, binds with the matching super type token, and
     * returns the one interesting field so main() can compare it against an expected value.
     */
    public static String processJson(String json) {
        Object tree = MiniJson.parse(json);                  // maps / lists / String / Double
        String payloadType = String.valueOf(((Map<?, ?>) tree).get("payloadType"));

        Type responseType = TYPE_BY_PAYLOAD.get(payloadType);
        if (responseType == null) {
            throw new IllegalArgumentException("unknown payloadType: " + payloadType);
        }

        switch (payloadType) {
            case "customer" -> {
                Response<Customer> response = MiniJson.bind(tree, responseType);
                return response.payload.name;
            }
            case "address" -> {
                Response<Address> response = MiniJson.bind(tree, responseType);
                return response.payload.street;
            }
            default -> {
                Response<Order> response = MiniJson.bind(tree, responseType);
                return String.valueOf(response.payload.amount);
            }
        }
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        String customerJson = """
                {
                  "status": "OK",
                  "message": "fetched",
                  "payloadType": "customer",
                  "payload": {
                               "name": "John Doe",
                               "age": 30
                             }
                }""";

        String addressJson = """
                {
                  "status": "OK",
                  "message": "fetched",
                  "payloadType": "address",
                  "payload": {
                               "street": "123 Main St",
                               "city": "Anytown"
                             }
                }""";

        String orderJson = """
                {
                  "status": "OK",
                  "message": "fetched",
                  "payloadType": "order",
                  "payload": {
                               "orderId": "ORD-8019",
                               "amount": 42.50
                             }
                }""";

        // A customer whose name would fool a substring-based dispatch.
        String trickyJson = """
                {
                  "status": "OK",
                  "message": "fetched",
                  "payloadType": "customer",
                  "payload": {
                               "name": "order",
                               "age": 7
                             }
                }""";

        print("case 1 customer name", processJson(customerJson), "John Doe");
        print("case 2 address street", processJson(addressJson), "123 Main St");
        print("case 3 order amount", processJson(orderJson), "42.5");
        print("case 4 tricky name", processJson(trickyJson), "order");

        // case 5: erasure loses the argument on objects, the token keeps it on the class.
        Response<Customer> c = new Response<>();
        Response<Address> a = new Response<>();
        print("case 5 same runtime class", c.getClass() == a.getClass(), true);
        print("case 5 customer token", CUSTOMER_RESPONSE_TYPE.getTypeName(),
                "Response<Customer>");
        print("case 5 tokens differ",
                !CUSTOMER_RESPONSE_TYPE.equals(ADDRESS_RESPONSE_TYPE), true);
        print("case 5 raw token (no braces)", rawTokenMessage(),
                "IllegalStateException: TypeToken must be subclassed with a type argument");
    }

    /** Building a token without the trailing {} is the classic mistake; prove it fails. */
    private static String rawTokenMessage() {
        try {
            Type bare = new RawToken().getType();
            return "no exception, got " + bare;
        } catch (IllegalStateException e) {
            return "IllegalStateException: " + e.getMessage();
        }
    }

    /** A direct subclass that forgets to supply a type argument - same failure as no {}. */
    @SuppressWarnings("rawtypes")
    private static class RawToken extends TypeToken {
    }
}

/**
 * Hand-rolled equivalent of Gson's TypeToken. Abstract on purpose: you MUST subclass it,
 * because the type argument is only recorded on a subclass's generic superclass.
 */
abstract class TypeToken<T> {
    private final Type type;

    protected TypeToken() {
        Type superclass = getClass().getGenericSuperclass();
        if (!(superclass instanceof ParameterizedType parameterized)) {
            throw new IllegalStateException(
                    "TypeToken must be subclassed with a type argument");
        }
        this.type = parameterized.getActualTypeArguments()[0];
    }

    public Type getType() {
        return type;
    }
}

/** A 60-line stand-in for Gson: parse JSON text, then bind a tree onto a generic Type. */
final class MiniJson {

    private final String src;
    private int pos;

    private MiniJson(String src) {
        this.src = src;
    }

    // ---- parsing: text -> Map / List / String / Double / Boolean / null ---------------

    static Object parse(String json) {
        MiniJson p = new MiniJson(json);
        Object value = p.readValue();
        p.skipWhitespace();
        if (p.pos != json.length()) {
            throw new IllegalArgumentException("trailing junk at index " + p.pos);
        }
        return value;
    }

    private Object readValue() {
        skipWhitespace();
        char c = src.charAt(pos);
        return switch (c) {
            case '{' -> readObject();
            case '[' -> readArray();
            case '"' -> readString();
            case 't' -> readLiteral("true", Boolean.TRUE);
            case 'f' -> readLiteral("false", Boolean.FALSE);
            case 'n' -> readLiteral("null", null);
            default -> readNumber();
        };
    }

    private Map<String, Object> readObject() {
        Map<String, Object> map = new LinkedHashMap<>();
        pos++;                                   // consume '{'
        skipWhitespace();
        if (src.charAt(pos) == '}') {
            pos++;
            return map;
        }
        while (true) {
            skipWhitespace();
            String key = readString();
            skipWhitespace();
            expect(':');
            map.put(key, readValue());
            skipWhitespace();
            char c = src.charAt(pos++);
            if (c == '}') return map;
            if (c != ',') throw new IllegalArgumentException("expected , or } at " + pos);
        }
    }

    private List<Object> readArray() {
        List<Object> list = new ArrayList<>();
        pos++;                                   // consume '['
        skipWhitespace();
        if (src.charAt(pos) == ']') {
            pos++;
            return list;
        }
        while (true) {
            list.add(readValue());
            skipWhitespace();
            char c = src.charAt(pos++);
            if (c == ']') return list;
            if (c != ',') throw new IllegalArgumentException("expected , or ] at " + pos);
        }
    }

    private String readString() {
        expect('"');
        StringBuilder sb = new StringBuilder();
        while (true) {
            char c = src.charAt(pos++);
            if (c == '"') return sb.toString();
            if (c == '\\') {                     // only the escapes these payloads need
                char esc = src.charAt(pos++);
                sb.append(switch (esc) {
                    case 'n' -> '\n';
                    case 't' -> '\t';
                    default -> esc;              // covers \" and \\
                });
            } else {
                sb.append(c);
            }
        }
    }

    private Double readNumber() {
        int start = pos;
        while (pos < src.length() && "+-.eE0123456789".indexOf(src.charAt(pos)) >= 0) {
            pos++;
        }
        return Double.valueOf(src.substring(start, pos));
    }

    private Object readLiteral(String word, Object value) {
        if (!src.startsWith(word, pos)) {
            throw new IllegalArgumentException("bad literal at " + pos);
        }
        pos += word.length();
        return value;
    }

    private void expect(char c) {
        if (src.charAt(pos) != c) {
            throw new IllegalArgumentException("expected " + c + " at index " + pos);
        }
        pos++;
    }

    private void skipWhitespace() {
        while (pos < src.length() && Character.isWhitespace(src.charAt(pos))) {
            pos++;
        }
    }

    // ---- binding: tree + Type -> object ----------------------------------------------

    /** The only method that needs the super type token: it reads the type ARGUMENTS. */
    @SuppressWarnings("unchecked")
    static <T> T bind(Object tree, Type type) {
        Class<?> raw;
        Type[] typeArguments = {};
        if (type instanceof ParameterizedType parameterized) {
            raw = (Class<?>) parameterized.getRawType();
            typeArguments = parameterized.getActualTypeArguments();   // e.g. {Customer}
        } else {
            raw = (Class<?>) type;
        }

        if (raw == String.class) return (T) String.valueOf(tree);
        if (raw == int.class || raw == Integer.class) {
            return (T) Integer.valueOf(((Number) tree).intValue());
        }
        if (raw == double.class || raw == Double.class) {
            return (T) Double.valueOf(((Number) tree).doubleValue());
        }

        Map<?, ?> map = (Map<?, ?>) tree;
        try {
            Object target = raw.getDeclaredConstructor().newInstance();
            for (var field : raw.getFields()) {
                Object value = map.get(field.getName());
                if (value == null) continue;
                field.set(target, bind(value, resolve(field.getGenericType(),
                        raw, typeArguments)));
            }
            return (T) target;
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("cannot bind " + raw.getSimpleName(), e);
        }
    }

    /** Turn a field declared as T into the concrete type the token supplied. */
    private static Type resolve(Type fieldType, Class<?> owner, Type[] typeArguments) {
        if (!(fieldType instanceof TypeVariable<?> variable)) return fieldType;
        TypeVariable<?>[] declared = owner.getTypeParameters();
        for (int i = 0; i < declared.length && i < typeArguments.length; i++) {
            if (declared[i].getName().equals(variable.getName())) return typeArguments[i];
        }
        throw new IllegalStateException("unresolved type variable " + variable);
    }
}

