/*
 * =====================================================================
 *  Caesar Cipher - encrypt and decrypt                    Easy
 * =====================================================================
 *
 * PROBLEM
 *   Given a text and an integer shift key, replace every letter by the letter
 *   'shift' positions later in the alphabet, wrapping Z back to A. Case is
 *   preserved and non-letters (spaces, punctuation, digits) pass through
 *   untouched. Decryption is the same walk with the shift reversed.
 *
 * EXAMPLE
 *   encrypt("Hello, World!", 3)  ->  "Khoor, Zruog!"   H+3=K, comma untouched
 *   encrypt("xyz XYZ", 3)        ->  "abc ABC"         wraps past z and Z
 *   decrypt("Khoor, Zruog!", 3)  ->  "Hello, World!"   shift back by 3
 *   encrypt("Hello", 29)         ->  "Khoor"           29 mod 26 == 3
 *
 * APPROACH  (modular arithmetic on a 0..25 alphabet index)
 *   1. Normalise the key once: ((shift % 26) + 26) % 26, so any int - negative,
 *      zero, or huge - becomes a forward shift in 0..25.
 *   2. Walk the string one char at a time.
 *   3. For a letter, pick its base ('A' or 'a'), convert to an index with
 *      ch - base, add the shift, take % 26, then add the base back.
 *   4. Append anything that is not a letter unchanged.
 *   5. decrypt(text, shift) is just encrypt(text, -shift) - step 1 makes the
 *      negative key safe.
 *
 * KEY INSIGHT
 *   Mapping a letter to 0..25 turns the alphabet into a ring, and a shift
 *   cipher is addition on that ring. Because addition on a ring is invertible,
 *   encryption and decryption are the same code with opposite signs - that is
 *   the whole idea of a symmetric key. Recognise the pattern any time a problem
 *   says "wrap around": subtract the base, do the maths mod n, add the base.
 *   Fixed: the original used (ch - base + shift) % 26 directly, which returns a
 *   negative index for a negative shift and produced garbage control characters;
 *   normalising the key first removes that whole class of bug.
 *
 * COMPLEXITY
 *   Time  O(n)  one pass, constant work per character
 *   Space O(n)  the StringBuilder holding the result; O(1) besides the output
 *
 * INTERVIEW FOLLOW-UPS
 *   - Break it without the key: 26 brute-force shifts, or letter-frequency analysis.
 *   - Generalise to a Vigenere cipher, where the shift cycles through a keyword.
 *   - Why is this not encryption in any real sense? (tiny key space, no diffusion)
 *   - Shift over the full byte range instead of A-Z: what breaks for Unicode text?
 *
 * RUN
 *   main() runs 7 cases (typical, round trip, wrap-around, empty, zero key,
 *   key > 26, negative key) and prints actual vs expected.
 */

class CaesarCipher {

    private static final int ALPHABET_SIZE = 26;

    /** Shifts every letter forward by 'shift'; leaves everything else alone. */
    public static String encrypt(String plaintext, int shift) {
        // Fold any int into 0..25 so a negative or oversized key still works.
        int key = ((shift % ALPHABET_SIZE) + ALPHABET_SIZE) % ALPHABET_SIZE;

        StringBuilder out = new StringBuilder(plaintext.length());
        for (char ch : plaintext.toCharArray()) {
            if (Character.isUpperCase(ch)) {
                out.append(shiftLetter(ch, 'A', key));
            } else if (Character.isLowerCase(ch)) {
                out.append(shiftLetter(ch, 'a', key));
            } else {
                out.append(ch); // digits, spaces, punctuation ride through
            }
        }
        return out.toString();
    }

    /** Decryption is encryption with the opposite shift - the symmetric part. */
    public static String decrypt(String cipherText, int shift) {
        return encrypt(cipherText, -shift);
    }

    /** ch -> index 0..25 -> add key -> wrap -> back to a char of the same case. */
    private static char shiftLetter(char ch, char base, int key) {
        return (char) (((ch - base + key) % ALPHABET_SIZE) + base);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // case 1: typical - letters shift, punctuation does not
        print("case 1 encrypt", encrypt("Hello, World!", 3), "Khoor, Zruog!");

        // case 2: the same text decrypts back - symmetry check
        print("case 2 decrypt", decrypt("Khoor, Zruog!", 3), "Hello, World!");

        // case 3: wrap-around at both ends of the alphabet
        print("case 3 wrap   ", encrypt("xyz XYZ", 3), "abc ABC");

        // case 4: edge - empty text and a zero key are both identity
        print("case 4 empty  ", "[" + encrypt("", 5) + "]", "[]");
        print("case 5 key 0  ", encrypt("Hello", 0), "Hello");

        // case 6: tricky - keys outside 0..25 must behave like their mod-26 value
        print("case 6 key 29 ", encrypt("Hello", 29), "Khoor");
        print("case 7 key -3 ", encrypt("Khoor", -3), "Hello");
    }
}

/*
 * =====================================================================
 *  AES symmetric encryption with the JCE                 Medium   MUST-KNOW
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   The four-object pipeline every Java encryption task uses: SecretKey ->
 *   Cipher -> doFinal -> Base64. It shows it twice: once the textbook way with
 *   Cipher.getInstance("AES"), which silently means ECB mode, and once the way
 *   you would actually ship, AES/GCM with a random IV and an auth tag. The same
 *   key encrypts and decrypts - that is what "symmetric" means.
 *
 * WHAT YOU WILL SEE
 *   ECB round trip  : "Hello AES!" -> Base64 ciphertext -> "Hello AES!"
 *   ECB determinism : encrypting the same text twice gives the SAME bytes (bad)
 *   GCM round trip  : "Hello AES!" -> Base64 ciphertext -> "Hello AES!"
 *   GCM randomness  : encrypting the same text twice gives DIFFERENT bytes (good)
 *   GCM tamper test : flipping one ciphertext byte makes decryption throw
 *
 * HOW IT WORKS
 *   1. SecretKeySpec wraps raw bytes as an AES key. AES accepts exactly 16, 24
 *      or 32 bytes (AES-128 / 192 / 256); 16 chars of ASCII is 16 bytes.
 *   2. Cipher.getInstance(transformation) picks algorithm/mode/padding. "AES"
 *      alone resolves to "AES/ECB/PKCS5Padding" - the mode is implied, not absent.
 *   3. init(ENCRYPT_MODE, key) then doFinal(bytes) produces the ciphertext.
 *   4. Ciphertext is raw bytes, not text, so Base64 encodes it for printing or
 *      for storing in a String column. Base64 is encoding, never encryption.
 *   5. init(DECRYPT_MODE, key) with the same key reverses it. For GCM the IV
 *      must be supplied again, so it is prepended to the ciphertext and split
 *      off before decrypting.
 *
 * KEY INSIGHT
 *   The mode of operation, not AES itself, decides whether the output leaks
 *   anything. ECB encrypts each 16-byte block independently, so equal plaintext
 *   blocks give equal ciphertext blocks and the structure of the data shows
 *   through. GCM mixes in a per-message IV and appends an authentication tag,
 *   so the same plaintext looks different every time and any tampering is
 *   detected on decrypt. "AES/GCM/NoPadding with a fresh random IV" is the
 *   answer to give; "Cipher.getInstance(\"AES\")" is the answer to recognise
 *   as a finding in a code review.
 *
 * GOTCHAS
 *   - Cipher.getInstance("AES") == ECB. Never ship it; it is the demo default.
 *   - A hardcoded key string in source is a leaked key. Real keys come from a
 *     KMS, a keystore, or KeyGenerator, and are rotated.
 *   - Never reuse an IV with the same GCM key; that breaks the mode outright.
 *   - plainText.getBytes() uses the platform charset. Always name UTF-8.
 *   - Cipher objects are stateful and NOT thread safe - do not share one.
 *   - GCM decrypt failure throws AEADBadTagException; catch it, do not ignore it.
 *
 * INTERVIEW FOLLOW-UPS
 *   - AES-GCM vs AES-CBC + HMAC: what does GCM give you for free?
 *   - Where does the key live in production, and how do you rotate it?
 *   - Encrypting a column so you can still search it - why is that hard?
 *   - Symmetric vs asymmetric: when do you need RSA instead? (see C01_RSA)
 *
 * RUN
 *   main() runs 5 cases (ECB round trip, ECB determinism, GCM round trip,
 *   GCM randomness, GCM tamper detection) and prints actual vs expected.
 */

import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.Arrays;
import java.util.Base64;

class AESExample {

    // Demo only. A real key is generated by KeyGenerator and kept in a KMS.
    private static final byte[] KEY_BYTES = "1234567890123456".getBytes(StandardCharsets.UTF_8);
    private static final SecretKeySpec KEY = new SecretKeySpec(KEY_BYTES, "AES");

    private static final int GCM_IV_BYTES = 12;   // 96-bit IV is the GCM standard
    private static final int GCM_TAG_BITS = 128;  // full-length auth tag
    private static final SecureRandom RANDOM = new SecureRandom();

    // ---------------------------------------------------------------- ECB ---
    // The author's original pipeline, kept as-is so the flaw stays visible.

    static String encryptEcb(String plainText) throws Exception {
        Cipher cipher = Cipher.getInstance("AES"); // == AES/ECB/PKCS5Padding
        cipher.init(Cipher.ENCRYPT_MODE, KEY);
        byte[] encrypted = cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8));
        return Base64.getEncoder().encodeToString(encrypted);
    }

    static String decryptEcb(String base64CipherText) throws Exception {
        Cipher cipher = Cipher.getInstance("AES");
        cipher.init(Cipher.DECRYPT_MODE, KEY);
        byte[] decrypted = cipher.doFinal(Base64.getDecoder().decode(base64CipherText));
        return new String(decrypted, StandardCharsets.UTF_8);
    }

    // ---------------------------------------------------------------- GCM ---
    // What you would actually ship: random IV per message + authentication tag.

    static String encryptGcm(String plainText) throws Exception {
        byte[] iv = new byte[GCM_IV_BYTES];
        RANDOM.nextBytes(iv); // a fresh IV per message is mandatory for GCM

        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.ENCRYPT_MODE, KEY, new GCMParameterSpec(GCM_TAG_BITS, iv));
        byte[] cipherText = cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8));

        // The IV is not secret, but the receiver needs it: ship it in front.
        byte[] ivAndCipherText = new byte[iv.length + cipherText.length];
        System.arraycopy(iv, 0, ivAndCipherText, 0, iv.length);
        System.arraycopy(cipherText, 0, ivAndCipherText, iv.length, cipherText.length);
        return Base64.getEncoder().encodeToString(ivAndCipherText);
    }

    static String decryptGcm(String base64IvAndCipherText) throws Exception {
        byte[] all = Base64.getDecoder().decode(base64IvAndCipherText);
        byte[] iv = Arrays.copyOfRange(all, 0, GCM_IV_BYTES);
        byte[] cipherText = Arrays.copyOfRange(all, GCM_IV_BYTES, all.length);

        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.DECRYPT_MODE, KEY, new GCMParameterSpec(GCM_TAG_BITS, iv));
        // Throws AEADBadTagException if a single bit of iv or cipherText changed.
        return new String(cipher.doFinal(cipherText), StandardCharsets.UTF_8);
    }

    /** Flips one bit in the last byte so the GCM tag check must fail. */
    static String tamperWith(String base64Text) {
        byte[] all = Base64.getDecoder().decode(base64Text);
        all[all.length - 1] ^= 0x01;
        return Base64.getEncoder().encodeToString(all);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) throws Exception {
        String plainText = "Hello AES!";

        // case 1: the classic round trip - same key both ways
        String ecb = encryptEcb(plainText);
        System.out.println("ECB ciphertext (Base64): " + ecb);
        print("case 1 ECB round trip ", decryptEcb(ecb), plainText);

        // case 2: ECB is deterministic - identical input, identical output.
        // That is the flaw: an observer can spot repeated values without the key.
        print("case 2 ECB repeats?   ", encryptEcb(plainText).equals(ecb), true);

        // case 3: GCM round trip, IV carried alongside the ciphertext
        String gcm = encryptGcm(plainText);
        System.out.println("GCM iv+ciphertext+tag (Base64): " + gcm);
        print("case 3 GCM round trip ", decryptGcm(gcm), plainText);

        // case 4: GCM is randomised - same plaintext, different ciphertext
        print("case 4 GCM repeats?   ", encryptGcm(plainText).equals(gcm), false);

        // case 5: edge - one flipped bit is caught by the auth tag, not ignored
        String verdict;
        try {
            decryptGcm(tamperWith(gcm));
            verdict = "no exception";
        } catch (javax.crypto.AEADBadTagException e) {
            verdict = "AEADBadTagException";
        }
        print("case 5 GCM tampered   ", verdict, "AEADBadTagException");
    }
}

/*
 * =====================================================================
 *  RSA asymmetric encryption, and why it needs AES            Medium
 * =====================================================================
 *
 * WHAT THIS DEMONSTRATES
 *   The same Cipher pipeline as A02_AES, but with two different keys:
 *   anyone holding the public key can encrypt, only the private key can
 *   decrypt. It then shows the constraint nobody expects - RSA can only
 *   encrypt a few hundred bytes - and the standard way around it: hybrid
 *   encryption, where RSA carries a one-off AES key and AES carries the data.
 *
 * WHAT YOU WILL SEE
 *   round trip   : "Hello Asymmetric RSA!" -> Base64 -> back again
 *   block size   : a 2048-bit key always emits exactly 256 ciphertext bytes
 *   size ceiling : encrypting 300 bytes throws IllegalBlockSizeException
 *   OAEP         : the padding you should actually ask for, round-tripping
 *   hybrid       : a long message encrypted by AES, its key wrapped by RSA
 *
 * HOW IT WORKS
 *   1. KeyPairGenerator.getInstance("RSA").initialize(2048) produces a matched
 *      PublicKey and PrivateKey. This step is the slow one - hundreds of
 *      milliseconds - because it hunts for large primes.
 *   2. Encrypt: Cipher.getInstance("RSA"), init(ENCRYPT_MODE, publicKey),
 *      doFinal(bytes). Base64 turns the raw bytes into something printable.
 *   3. Decrypt: the same transformation, init(DECRYPT_MODE, privateKey).
 *   4. The ceiling: RSA encrypts one number smaller than the modulus, so the
 *      payload limit is keySize/8 minus padding overhead. 2048-bit key with
 *      PKCS#1 v1.5 padding = 256 - 11 = 245 bytes. Over that, doFinal throws.
 *   5. Hybrid: KeyGenerator makes a random AES-256 key, AES/GCM encrypts the
 *      real payload, RSA encrypts just the 32-byte AES key. The receiver
 *      unwraps the key with its private key, then decrypts the payload.
 *
 * KEY INSIGHT
 *   RSA is a key-transport mechanism, not a data-encryption mechanism. It is
 *   roughly a thousand times slower than AES and bounded by the modulus size,
 *   so every real protocol - TLS, PGP, JWE - uses it to move a symmetric key
 *   and lets AES do the bulk work. The other half of the insight is direction:
 *   encrypt with the PUBLIC key so only the private key can read it; sign with
 *   the PRIVATE key so any public key holder can verify it. Swapping those two
 *   is the classic interview trap.
 *
 * GOTCHAS
 *   - Cipher.getInstance("RSA") means RSA/ECB/PKCS1Padding. Prefer
 *     "RSA/ECB/OAEPWithSHA-256AndMGF1Padding"; PKCS#1 v1.5 has known attacks.
 *   - "ECB" in an RSA transformation is a naming artefact - there is one block.
 *   - Never loop RSA over chunks of a large message. Use hybrid encryption.
 *   - Encryption is not signing. Signature uses java.security.Signature, and a
 *     signature proves origin, not secrecy.
 *   - Key generation is expensive: generate once and reuse, never per request.
 *   - Below 2048 bits is considered broken; 3072+ for long-lived data.
 *
 * INTERVIEW FOLLOW-UPS
 *   - Walk through a TLS handshake: where exactly does the asymmetric part stop?
 *   - RSA vs ECDSA/ECDH: why do modern systems prefer elliptic curves?
 *   - How do you distribute and trust a public key? (certificates, CAs, pinning)
 *   - Sign-then-encrypt or encrypt-then-sign, and what goes wrong either way?
 *
 * RUN
 *   main() runs 5 cases (round trip, ciphertext length, oversized payload,
 *   OAEP round trip, hybrid round trip) and prints actual vs expected.
 */

import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.PrivateKey;
import java.security.PublicKey;
import java.security.SecureRandom;
import java.util.Arrays;
import java.util.Base64;

class RSAExample {

    private static final String PKCS1 = "RSA";  // == RSA/ECB/PKCS1Padding
    private static final String OAEP = "RSA/ECB/OAEPWithSHA-256AndMGF1Padding";

    private static final int GCM_IV_BYTES = 12;
    private static final int GCM_TAG_BITS = 128;
    private static final SecureRandom RANDOM = new SecureRandom();

    static KeyPair newKeyPair() throws Exception {
        KeyPairGenerator generator = KeyPairGenerator.getInstance("RSA");
        generator.initialize(2048); // 256-byte modulus -> 256-byte ciphertext
        return generator.generateKeyPair();
    }

    static byte[] encrypt(String transformation, PublicKey publicKey, byte[] data)
            throws Exception {
        Cipher cipher = Cipher.getInstance(transformation);
        cipher.init(Cipher.ENCRYPT_MODE, publicKey); // public key locks it
        return cipher.doFinal(data);
    }

    static byte[] decrypt(String transformation, PrivateKey privateKey, byte[] data)
            throws Exception {
        Cipher cipher = Cipher.getInstance(transformation);
        cipher.init(Cipher.DECRYPT_MODE, privateKey); // only the private key opens it
        return cipher.doFinal(data);
    }

    // ------------------------------------------------------------- hybrid ---
    // RSA moves the key, AES moves the data. This is what TLS and JWE do.

    /** Returns [rsa-wrapped AES key | iv | AES-GCM ciphertext], Base64 encoded. */
    static String hybridEncrypt(PublicKey publicKey, String plainText) throws Exception {
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(256);
        SecretKey sessionKey = keyGen.generateKey(); // one-off, never stored

        byte[] iv = new byte[GCM_IV_BYTES];
        RANDOM.nextBytes(iv);
        Cipher aes = Cipher.getInstance("AES/GCM/NoPadding");
        aes.init(Cipher.ENCRYPT_MODE, sessionKey, new GCMParameterSpec(GCM_TAG_BITS, iv));
        byte[] payload = aes.doFinal(plainText.getBytes(StandardCharsets.UTF_8));

        // Only the 32-byte AES key goes through RSA - well under the ceiling.
        byte[] wrappedKey = encrypt(OAEP, publicKey, sessionKey.getEncoded());

        byte[] out = new byte[wrappedKey.length + iv.length + payload.length];
        System.arraycopy(wrappedKey, 0, out, 0, wrappedKey.length);
        System.arraycopy(iv, 0, out, wrappedKey.length, iv.length);
        System.arraycopy(payload, 0, out, wrappedKey.length + iv.length, payload.length);
        return Base64.getEncoder().encodeToString(out);
    }

    static String hybridDecrypt(PrivateKey privateKey, String base64) throws Exception {
        byte[] all = Base64.getDecoder().decode(base64);
        int wrappedLen = 256; // fixed by the 2048-bit key size

        byte[] wrappedKey = Arrays.copyOfRange(all, 0, wrappedLen);
        byte[] iv = Arrays.copyOfRange(all, wrappedLen, wrappedLen + GCM_IV_BYTES);
        byte[] payload = Arrays.copyOfRange(all, wrappedLen + GCM_IV_BYTES, all.length);

        byte[] keyBytes = decrypt(OAEP, privateKey, wrappedKey);
        SecretKeySpec sessionKey = new SecretKeySpec(keyBytes, "AES");

        Cipher aes = Cipher.getInstance("AES/GCM/NoPadding");
        aes.init(Cipher.DECRYPT_MODE, sessionKey, new GCMParameterSpec(GCM_TAG_BITS, iv));
        return new String(aes.doFinal(payload), StandardCharsets.UTF_8);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) throws Exception {
        KeyPair pair = newKeyPair(); // generate once, reuse for every case
        PublicKey publicKey = pair.getPublic();
        PrivateKey privateKey = pair.getPrivate();

        String plainText = "Hello Asymmetric RSA!";
        byte[] cipherBytes = encrypt(PKCS1, publicKey, plainText.getBytes(StandardCharsets.UTF_8));
        System.out.println("Ciphertext (Base64): "
                + Base64.getEncoder().encodeToString(cipherBytes));

        // case 1: typical - public key encrypts, private key decrypts
        String recovered =
                new String(decrypt(PKCS1, privateKey, cipherBytes), StandardCharsets.UTF_8);
        print("case 1 round trip     ", recovered, plainText);

        // case 2: output size is the key size, not the message size
        print("case 2 cipher bytes   ", cipherBytes.length, 256);

        // case 3: edge - 300 bytes exceeds the 245-byte PKCS#1 ceiling
        byte[] tooBig = new byte[300];
        Arrays.fill(tooBig, (byte) 'x');
        String verdict;
        try {
            encrypt(PKCS1, publicKey, tooBig);
            verdict = "no exception";
        } catch (javax.crypto.IllegalBlockSizeException e) {
            verdict = "IllegalBlockSizeException";
        }
        print("case 3 300-byte input ", verdict, "IllegalBlockSizeException");

        // case 4: OAEP padding - the transformation to prefer in real code
        byte[] oaep = encrypt(OAEP, publicKey, plainText.getBytes(StandardCharsets.UTF_8));
        print("case 4 OAEP round trip",
                new String(decrypt(OAEP, privateKey, oaep), StandardCharsets.UTF_8), plainText);

        // case 5: tricky - the same 300-byte payload that RSA refused now
        // succeeds, because AES carries it and RSA only carries the AES key
        String longText = "x".repeat(300);
        String hybrid = hybridEncrypt(publicKey, longText);
        print("case 5 hybrid 300 chars", hybridDecrypt(privateKey, hybrid).equals(longText), true);
    }
}

