/*
 * =====================================================================
 *  Factory - payment processor per checkout request   Creational | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Checkout receives {"method": "UPI", "amount": 1200}. The method code
 *   decides which processor runs: UPI, card (adds a 2% fee) or cash on
 *   delivery (refused above Rs 50,000). Checkout must not `new` any of them,
 *   and launching BNPL next quarter must not mean editing a switch.
 *
 * KEY INSIGHT
 *   The factory owns the "code -> class" decision, and a registry of
 *   Suppliers replaces the if/else chain: a new method is one register()
 *   call. The return type is the interface, so checkout never names a
 *   concrete processor.
 *
 * ROLES IN THIS CODE
 *   PaymentProcessor                  Product
 *   UpiProcessor, Card.., Cod..       ConcreteProduct
 *   PaymentProcessorFactory           Factory (registry of Suppliers)
 *   main()                            Client (the checkout)
 *
 * INTERVIEW FOLLOW-UPS
 *   - Unknown code: throw in the factory; returning null moves the crash.
 *   - Spring does this for you: inject Map<String, PaymentProcessor> and
 *     the bean names become the keys.
 *   - Factory vs Abstract Factory: one product here, a matched family of
 *     products in C01_AbstractFactoryPattern.
 *
 * RUN
 *   5 cases: UPI, card fee, COD over limit, unknown code, BNPL registered.
 */

import java.util.HashMap;
import java.util.Map;
import java.util.function.Supplier;

/** Product: the only type checkout knows. */
interface PaymentProcessor {
    /** Returns a receipt line, or throws if this method cannot take the amount. */
    String pay(int amountRs);
}

class UpiProcessor implements PaymentProcessor {
    public String pay(int amountRs) {
        return "UPI collect request for Rs " + amountRs;
    }
}

class CardProcessor implements PaymentProcessor {
    public String pay(int amountRs) {
        int fee = amountRs * 2 / 100; // gateway fee passed on to the customer
        return "Card charged Rs " + (amountRs + fee) + " (fee Rs " + fee + ")";
    }
}

class CodProcessor implements PaymentProcessor {
    static final int LIMIT_RS = 50_000;

    public String pay(int amountRs) {
        if (amountRs > LIMIT_RS) {
            throw new IllegalStateException("COD not allowed above Rs " + LIMIT_RS);
        }
        return "COD booked, collect Rs " + amountRs + " at the door";
    }
}

/** Factory: the only place a method code turns into a class. */
class PaymentProcessorFactory {
    private final Map<String, Supplier<PaymentProcessor>> registry = new HashMap<>();

    PaymentProcessorFactory() {
        register("UPI", UpiProcessor::new);
        register("CARD", CardProcessor::new);
        register("COD", CodProcessor::new);
    }

    /** Open for extension: a new method is a register() call, not an edited switch. */
    void register(String code, Supplier<PaymentProcessor> supplier) {
        registry.put(code, supplier);
    }

    PaymentProcessor forMethod(String code) {
        Supplier<PaymentProcessor> supplier = registry.get(code);
        if (supplier == null) {
            throw new IllegalArgumentException("Unsupported payment method " + code);
        }
        return supplier.get();
    }
}

class FactoryDesignPattern {

    public static void main(String[] args) {
        PaymentProcessorFactory factory = new PaymentProcessorFactory();

        // Case 1-2: typical. The client holds a PaymentProcessor, never a UpiProcessor.
        print("case 1 UPI      ", factory.forMethod("UPI").pay(1200),
                "UPI collect request for Rs 1200");
        print("case 2 card fee ", factory.forMethod("CARD").pay(1000),
                "Card charged Rs 1020 (fee Rs 20)");

        // Case 3: the product enforces its own business rule.
        print("case 3 COD limit", attempt(() -> factory.forMethod("COD").pay(60_000)),
                "IllegalStateException COD not allowed above Rs 50000");

        // Case 4: edge. An unknown code fails here, at the real fault line.
        print("case 4 unknown  ", attempt(() -> factory.forMethod("BNPL").pay(500)),
                "IllegalArgumentException Unsupported payment method BNPL");

        // Case 5: BNPL launches. One register() call; factory and checkout untouched.
        factory.register("BNPL", () -> amount -> "BNPL 3 EMIs of Rs " + amount / 3);
        print("case 5 BNPL     ", factory.forMethod("BNPL").pay(3000), "BNPL 3 EMIs of Rs 1000");
    }

    private static String attempt(Supplier<String> call) {
        try {
            return call.get();
        } catch (RuntimeException e) {
            return e.getClass().getSimpleName() + " " + e.getMessage();
        }
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Builder - product search request                Creational | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   The search page sends a keyword ("running shoes") plus any of: category,
 *   price range, brands, sort order, page number. A 7-argument constructor
 *   is unreadable, and nothing stops a caller passing minPrice and maxPrice
 *   the wrong way round.
 *
 * KEY INSIGHT
 *   Required values go in the builder's constructor, optional ones are named
 *   methods, and build() is the single gate that validates. An invalid
 *   SearchRequest can never exist, and once built it is immutable.
 *
 * ROLES IN THIS CODE
 *   SearchRequest           Product (immutable, private constructor)
 *   SearchRequest.Builder   Builder (static nested, fluent)
 *   toBuilder()             copy-and-modify, e.g. "same search, next page"
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why not setters? The object would be mutable and could be half-built.
 *   - Why Set.copyOf in the constructor? Case 5: the builder's own set keeps
 *     changing after build().
 *   - Seen in: HttpRequest.newBuilder(), StringBuilder, Lombok @Builder.
 *
 * RUN
 *   6 cases: full build, defaults, bad price range, missing keyword, next
 *   page via toBuilder, builder reused after build.
 */

import java.util.HashSet;
import java.util.Set;
import java.util.TreeSet;
import java.util.function.Supplier;

class SearchRequest {
    enum Sort { RELEVANCE, PRICE_LOW_TO_HIGH, NEWEST }

    private final String keyword;
    private final String category; // null = all categories
    private final int minPrice;
    private final int maxPrice;
    private final Set<String> brands;
    private final Sort sort;
    private final int page;

    private SearchRequest(Builder b) {
        keyword = b.keyword;
        category = b.category;
        minPrice = b.minPrice;
        maxPrice = b.maxPrice;
        brands = Set.copyOf(b.brands); // snapshot: later builder changes cannot leak in
        sort = b.sort;
        page = b.page;
    }

    static Builder builder(String keyword) {
        return new Builder(keyword);
    }

    /** Copy-and-modify. The original request is untouched. */
    Builder toBuilder() {
        Builder b = new Builder(keyword).category(category).price(minPrice, maxPrice)
                .sortBy(sort).page(page);
        b.brands.addAll(brands);
        return b;
    }

    @Override
    public String toString() {
        return "q=" + keyword + (category == null ? "" : " cat=" + category)
                + " price=" + minPrice + "-" + (maxPrice == Integer.MAX_VALUE ? "any" : maxPrice)
                + " brands=" + new TreeSet<>(brands) + " sort=" + sort + " page=" + page;
    }

    static class Builder {
        private final String keyword;
        private String category;
        private int minPrice = 0;
        private int maxPrice = Integer.MAX_VALUE;
        private final Set<String> brands = new HashSet<>();
        private Sort sort = Sort.RELEVANCE;
        private int page = 1;

        private Builder(String keyword) {
            this.keyword = keyword;
        }

        Builder category(String category) {
            this.category = category;
            return this;
        }

        Builder price(int min, int max) {
            this.minPrice = min;
            this.maxPrice = max;
            return this;
        }

        Builder brand(String brand) {
            brands.add(brand);
            return this;
        }

        Builder sortBy(Sort sort) {
            this.sort = sort;
            return this;
        }

        Builder page(int page) {
            this.page = page;
            return this;
        }

        /** The one gate: every invariant is checked before the object exists. */
        SearchRequest build() {
            if (keyword == null || keyword.isBlank()) {
                throw new IllegalStateException("keyword is required");
            }
            if (minPrice > maxPrice) {
                throw new IllegalStateException("minPrice " + minPrice + " > maxPrice " + maxPrice);
            }
            return new SearchRequest(this);
        }
    }
}

class BuilderExample {

    public static void main(String[] args) {
        // Case 1: typical. Every value is labelled by its method name.
        SearchRequest shoes = SearchRequest.builder("running shoes")
                .category("footwear")
                .price(2000, 5000)
                .brand("Nike").brand("Asics")
                .sortBy(SearchRequest.Sort.PRICE_LOW_TO_HIGH)
                .build();
        print("case 1 full    ", shoes, "q=running shoes cat=footwear price=2000-5000"
                + " brands=[Asics, Nike] sort=PRICE_LOW_TO_HIGH page=1");

        // Case 2: edge. Only the required keyword; defaults fill the rest.
        print("case 2 defaults", SearchRequest.builder("tv").build(),
                "q=tv price=0-any brands=[] sort=RELEVANCE page=1");

        // Case 3-4: build() refuses an invalid request, so none ever exists.
        print("case 3 bad range",
                attempt(() -> SearchRequest.builder("tv").price(5000, 2000).build()),
                "IllegalStateException minPrice 5000 > maxPrice 2000");
        print("case 4 no keyword", attempt(() -> SearchRequest.builder(" ").build()),
                "IllegalStateException keyword is required");

        // Case 5: "load more" - same search, next page. Page 1 is not touched.
        SearchRequest page2 = shoes.toBuilder().page(2).build();
        print("case 5a page 2  ", page2.toString().endsWith("page=2"), true);
        print("case 5b page 1  ", shoes.toString().endsWith("page=1"), true);

        // Case 6: tricky. Reuse a builder after build(); the first request keeps
        // its own brand set because the constructor copied it.
        SearchRequest.Builder reused = SearchRequest.builder("phone").brand("Sony");
        SearchRequest first = reused.build();
        reused.brand("LG").build();
        print("case 6 reuse    ", first, "q=phone price=0-any brands=[Sony] sort=RELEVANCE page=1");
    }

    private static String attempt(Supplier<Object> call) {
        try {
            return String.valueOf(call.get());
        } catch (RuntimeException e) {
            return e.getClass().getSimpleName() + " " + e.getMessage();
        }
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Prototype - product variants from a base listing      Creational | Easy
 * =====================================================================
 *
 * PROBLEM
 *   A seller lists "Classic Tee" once, with fabric, fit, wash care, images
 *   and so on, then needs Red/S, Red/M, Red/L... variants. Re-entering every
 *   field per variant is slow and error-prone. Copy the base listing and
 *   change only colour and size.
 *
 * KEY INSIGHT
 *   The copy must be DEEP for every mutable field. A shallow copy shares the
 *   attribute map, so setting the variant's colour silently repaints the
 *   base listing too (case 2). A copy constructor makes the deep copy
 *   explicit; a registry of templates makes "clone, then tweak" the normal
 *   way a new listing is born.
 *
 * ROLES IN THIS CODE
 *   ProductListing      Prototype (copy() = deep copy via copy constructor)
 *   TemplateRegistry    Prototype registry: template name -> listing to clone
 *
 * INTERVIEW FOLLOW-UPS
 *   - Copy constructor vs Cloneable: clone() skips the constructor, is
 *     shallow by default and throws a checked exception.
 *   - Strings are immutable, so sharing them is safe; only the Map and List
 *     need fresh copies.
 *   - Seen in: new ArrayList<>(other), Spring's prototype bean scope.
 *
 * RUN
 *   5 cases: deep copy isolated, shallow-copy bug, registry spawns three
 *   sizes, image lists independent, unknown template.
 */

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

class ProductListing {
    final String title;
    final Map<String, String> attributes;
    final List<String> images;

    ProductListing(String title, Map<String, String> attributes, List<String> images) {
        this.title = title;
        this.attributes = attributes;
        this.images = images;
    }

    /** Copy constructor: fresh containers, the same immutable Strings inside. */
    ProductListing(ProductListing other) {
        this(other.title, new LinkedHashMap<>(other.attributes), new ArrayList<>(other.images));
    }

    /** The Prototype operation: a deep copy. */
    ProductListing copy() {
        return new ProductListing(this);
    }

    /** The bug code review catches: a new object holding the SAME map and list. */
    ProductListing shallowCopy() {
        return new ProductListing(title, attributes, images);
    }

    ProductListing with(String key, String value) {
        attributes.put(key, value);
        return this;
    }

    String sku() {
        return title.replace(" ", "") + "-" + attributes.get("colour")
                + "-" + attributes.get("size");
    }
}

class TemplateRegistry {
    private final Map<String, ProductListing> templates = new HashMap<>();

    void register(String name, ProductListing template) {
        templates.put(name, template);
    }

    ProductListing newFrom(String name) {
        ProductListing template = templates.get(name);
        if (template == null) {
            throw new IllegalArgumentException("no template " + name);
        }
        return template.copy(); // callers never get the template itself
    }
}

class PrototypeExample {

    public static void main(String[] args) {
        // Case 1: typical. Deep copy, then change colour - the base is untouched.
        ProductListing base = classicTee();
        ProductListing red = base.copy().with("colour", "red");
        print("case 1a variant", red.sku(), "ClassicTee-red-M");
        print("case 1b base   ", base.sku(), "ClassicTee-white-M");

        // Case 2: the bug. Shallow copy shares the map, so the base turns black too.
        ProductListing base2 = classicTee();
        base2.shallowCopy().with("colour", "black");
        print("case 2 shallow ", base2.sku(), "ClassicTee-black-M");

        // Case 3: the registry spawns one listing per size from one template.
        TemplateRegistry registry = new TemplateRegistry();
        registry.register("tee", classicTee());
        List<String> skus = new ArrayList<>();
        for (String size : List.of("S", "M", "L")) {
            skus.add(registry.newFrom("tee").with("colour", "red").with("size", size).sku());
        }
        print("case 3a sizes  ", skus, "[ClassicTee-red-S, ClassicTee-red-M, ClassicTee-red-L]");
        print("case 3b template", registry.newFrom("tee").sku(), "ClassicTee-white-M");

        // Case 4: the image list is copied too, not just the attribute map.
        red.images.add("red-closeup.jpg");
        print("case 4 images  ", base.images.size() + " vs " + red.images.size(), "2 vs 3");

        // Case 5: edge. Asking for a template nobody registered.
        String outcome;
        try {
            registry.newFrom("hoodie");
            outcome = "no exception";
        } catch (IllegalArgumentException e) {
            outcome = e.getMessage();
        }
        print("case 5 unknown ", outcome, "no template hoodie");
    }

    private static ProductListing classicTee() {
        Map<String, String> attributes = new LinkedHashMap<>();
        attributes.put("fabric", "cotton");
        attributes.put("fit", "regular");
        attributes.put("colour", "white");
        attributes.put("size", "M");
        return new ProductListing("Classic Tee", attributes,
                new ArrayList<>(List.of("front.jpg", "back.jpg")));
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Abstract Factory - regional checkout kit            Creational | Medium
 * =====================================================================
 *
 * PROBLEM
 *   The store sells in India and the US. Each region needs its own payment
 *   gateway, tax rule and invoice currency, and the three must match: a GST
 *   invoice charged through Stripe in dollars is a compliance bug. Checkout
 *   must work for any region without naming one.
 *
 * KEY INSIGHT
 *   One factory makes the whole family, so choosing the region once (from
 *   config, at startup) guarantees every part matches. Checkout depends only
 *   on the interfaces. The cost: adding a new product to the family, say
 *   ShippingRates, means editing every kit.
 *
 * ROLES IN THIS CODE
 *   RegionKit                         AbstractFactory
 *   IndiaKit, UsKit                   ConcreteFactory (one per region)
 *   PaymentGateway, TaxCalculator,
 *   InvoiceFormatter                  AbstractProduct
 *   RazorpayGateway, GstCalculator..  ConcreteProduct
 *   Checkout                          Client
 *
 * INTERVIEW FOLLOW-UPS
 *   - Factory vs Abstract Factory: A01_FactoryDesignPattern makes one
 *     product from a key; this makes a family that must not be mixed.
 *   - Spring: one @Configuration per region, picked by @Profile("in").
 *   - Seen in: JDBC (a Driver gives you a matching Connection, Statement,
 *     ResultSet), javax.xml DocumentBuilderFactory.
 *
 * RUN
 *   4 cases: India order, US order, unknown region, kit parts all match.
 */

import java.util.Locale;

// ---------- the products every region must supply ----------

interface PaymentGateway {
    /** Gateways take the amount in the smallest unit (paise, cents). */
    String charge(long minorUnits);
}

interface TaxCalculator {
    long taxOn(long netMinor);

    String label();
}

interface InvoiceFormatter {
    String money(long minorUnits);
}

// ---------- India family ----------

class RazorpayGateway implements PaymentGateway {
    public String charge(long paise) {
        return "Razorpay charged " + paise + " paise";
    }
}

class GstCalculator implements TaxCalculator {
    public long taxOn(long netPaise) {
        return netPaise * 18 / 100;
    }

    public String label() {
        return "GST 18%";
    }
}

class RupeeFormatter implements InvoiceFormatter {
    public String money(long paise) {
        return String.format(Locale.US, "Rs %,d.%02d", paise / 100, paise % 100);
    }
}

// ---------- US family ----------

class StripeGateway implements PaymentGateway {
    public String charge(long cents) {
        return "Stripe charged " + cents + " cents";
    }
}

class UsSalesTax implements TaxCalculator {
    public long taxOn(long netCents) {
        return netCents * 825 / 10_000; // 8.25%
    }

    public String label() {
        return "Sales tax 8.25%";
    }
}

class DollarFormatter implements InvoiceFormatter {
    public String money(long cents) {
        return String.format(Locale.US, "$%,d.%02d", cents / 100, cents % 100);
    }
}

// ---------- the abstract factory and its two regions ----------

interface RegionKit {
    PaymentGateway gateway();

    TaxCalculator tax();

    InvoiceFormatter invoice();

    static RegionKit forRegion(String code) {
        return switch (code) {
            case "IN" -> new IndiaKit();
            case "US" -> new UsKit();
            default -> throw new IllegalArgumentException("No region kit for " + code);
        };
    }
}

class IndiaKit implements RegionKit {
    public PaymentGateway gateway() { return new RazorpayGateway(); }
    public TaxCalculator tax() { return new GstCalculator(); }
    public InvoiceFormatter invoice() { return new RupeeFormatter(); }
}

class UsKit implements RegionKit {
    public PaymentGateway gateway() { return new StripeGateway(); }
    public TaxCalculator tax() { return new UsSalesTax(); }
    public InvoiceFormatter invoice() { return new DollarFormatter(); }
}

/** Client: never mentions India, the US, Razorpay or Stripe. */
class Checkout {
    private final RegionKit kit;

    Checkout(RegionKit kit) {
        this.kit = kit;
    }

    String placeOrder(long netMinor) {
        TaxCalculator tax = kit.tax();
        InvoiceFormatter fmt = kit.invoice();
        long taxAmount = tax.taxOn(netMinor);
        long total = netMinor + taxAmount;
        return fmt.money(netMinor) + " + " + tax.label() + " " + fmt.money(taxAmount)
                + " = " + fmt.money(total) + " | " + kit.gateway().charge(total);
    }
}

class AbstractFactoryPattern {

    public static void main(String[] args) {
        // Case 1-2: same Checkout code, same net amount (1000.00), two regions.
        print("case 1 India ", new Checkout(RegionKit.forRegion("IN")).placeOrder(100_000),
                "Rs 1,000.00 + GST 18% Rs 180.00 = Rs 1,180.00 | Razorpay charged 118000 paise");
        print("case 2 US    ", new Checkout(RegionKit.forRegion("US")).placeOrder(100_000),
                "$1,000.00 + Sales tax 8.25% $82.50 = $1,082.50 | Stripe charged 108250 cents");

        // Case 3: edge. A region we do not sell in fails loudly, never defaults.
        String outcome;
        try {
            RegionKit.forRegion("BR");
            outcome = "no exception";
        } catch (IllegalArgumentException e) {
            outcome = e.getMessage();
        }
        print("case 3 BR    ", outcome, "No region kit for BR");

        // Case 4: the point of the pattern - one choice, a matching set of parts.
        RegionKit kit = RegionKit.forRegion("IN");
        print("case 4 family", kit.gateway().getClass().getSimpleName() + " + "
                        + kit.tax().getClass().getSimpleName() + " + "
                        + kit.invoice().getClass().getSimpleName(),
                "RazorpayGateway + GstCalculator + RupeeFormatter");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Singleton - sealing every back door       Creational | Hard   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Some objects must exist once per JVM: the connection pool, the metrics
 *   registry, the app config. Two pools double the DB connections; two
 *   configs drift apart. Build it three ways (double-checked locking, holder
 *   idiom, enum) and attack each through its back doors.
 *
 * KEY INSIGHT
 *   `instance = new Singleton()` is allocate, construct, assign. Without
 *   `volatile` another thread may see the reference before the constructor
 *   finishes. Then three back doors still make a second instance:
 *   reflection, clone() and deserialization (readResolve must return
 *   Object). An enum closes all three for free - the recommended form.
 *
 * ROLES IN THIS CODE
 *   Singleton         double-checked locking + the three hand-written guards
 *   RobustSingleton   holder idiom: lazy and lock-free, JVM class init is once
 *   EnumSingleton     enum: the JVM blocks reflection and deserialization
 *   Main              client, and the attacker
 *
 * INTERVIEW FOLLOW-UPS
 *   - Holder vs DCL: same laziness, no lock, no volatile, less to get wrong.
 *   - Spring beans are already singleton-scoped; hand-rolling one there is
 *     usually a mistake, and getInstance() calls cannot be faked in tests.
 *   - "One instance" means one per classloader, so one per JVM, not per
 *     cluster.
 *
 * RUN
 *   8 cases: identity for each variant, then reflection, clone and
 *   serialization attacks against each guard.
 */

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serial;
import java.io.Serializable;
import java.lang.reflect.Constructor;

/** `final` prevents a subclass from handing out extra instances. */
final class Singleton implements Cloneable, Serializable {

    @Serial
    private static final long serialVersionUID = 1L;

    // volatile: stops the JVM publishing a half-constructed object to a
    // second thread, and makes the write visible without a lock on reads.
    // Cannot be final - it is assigned lazily.
    private static volatile Singleton singleton;

    private Singleton() {
        // Guard 1 of 3: reflection. Once an instance exists, a reflective
        // call to this constructor blows up.
        // Still bypassable if reflection runs BEFORE the first getInstance().
        if (singleton != null) {
            throw new IllegalStateException("Instance already created");
        }
    }

    public static Singleton getInstance() {
        // First read is unsynchronized - the common, fast path.
        if (singleton == null) {
            synchronized (Singleton.class) {
                // Second read inside the lock: two threads can both pass the
                // first check, only one may construct.
                if (singleton == null) {
                    singleton = new Singleton();
                }
            }
        }
        return singleton;
    }

    @Override
    protected Object clone() throws CloneNotSupportedException {
        // Guard 2 of 3: clone(). Object.clone() would allocate a copy
        // without running any constructor, so refuse outright.
        throw new CloneNotSupportedException("Cannot clone a singleton");
    }

    /**
     * Guard 3 of 3: deserialization. readStream builds a fresh object and
     * then calls this hook; returning the live instance discards it.
     * The return type MUST be Object - serialization matches the method by
     * exact signature, so a covariant return silently disables the hook.
     */
    @Serial
    protected Object readResolve() {
        return getInstance();
    }
}

/**
 * Initialization-on-demand holder idiom: lazy, thread-safe, lock-free.
 * Holder is not loaded until getInstance() touches it, and the JVM
 * guarantees class initialization runs once.
 */
class RobustSingleton implements Serializable, Cloneable {

    @Serial
    private static final long serialVersionUID = 1L;

    private RobustSingleton() {
        // During Holder's own class init this read returns null (the JVM
        // allows re-entrant access from the initializing thread), so the
        // legitimate creation passes. A later reflective call does not.
        if (Holder.INSTANCE != null) {
            throw new IllegalStateException("Instance already created");
        }
    }

    private static class Holder {
        private static final RobustSingleton INSTANCE = new RobustSingleton();
    }

    public static RobustSingleton getInstance() {
        return Holder.INSTANCE;
    }

    @Override
    protected Object clone() throws CloneNotSupportedException {
        throw new CloneNotSupportedException("Cannot clone a singleton");
    }

    @Serial
    protected Object readResolve() {
        return getInstance();
    }
}

/**
 * The recommended form. No guards written by hand: the JVM refuses
 * reflective construction of enums and deserializes constants by name.
 */
enum EnumSingleton {
    INSTANCE;

    public String greet() {
        return "hello from enum singleton";
    }
}

class Main {

    public static void main(String[] args) throws Exception {
        // Case 1: every getInstance() call returns the same reference.
        Singleton a = Singleton.getInstance();
        Singleton b = Singleton.getInstance();
        Singleton c = Singleton.getInstance();
        print("case 1 DCL identity    ", a == b && b == c, true);

        // Case 2: back door 1 - reflection on the private constructor.
        print("case 2 DCL reflection  ", reflectionAttack(Singleton.class),
                "IllegalStateException: Instance already created");

        // Case 3: back door 2 - clone().
        String cloneResult;
        try {
            invokeClone(a);
            cloneResult = "cloned";
        } catch (CloneNotSupportedException e) {
            cloneResult = "CloneNotSupportedException: " + e.getMessage();
        }
        print("case 3 DCL clone       ", cloneResult,
                "CloneNotSupportedException: Cannot clone a singleton");

        // Case 4: back door 3 - serialize, then read back. readResolve()
        // must swap the fresh object for the live one.
        print("case 4 DCL serialize   ", roundTrip(a) == a, true);

        // Case 5-6: the holder idiom gives the same guarantees with no lock.
        RobustSingleton r1 = RobustSingleton.getInstance();
        print("case 5 holder identity ", r1 == RobustSingleton.getInstance(), true);
        print("case 6 holder reflection", reflectionAttack(RobustSingleton.class),
                "IllegalStateException: Instance already created");

        // Case 7-8: enum. Identity is free, and the JVM itself refuses the
        // reflective attack - no hand-written guard anywhere.
        print("case 7 enum identity   ",
                EnumSingleton.INSTANCE == EnumSingleton.valueOf("INSTANCE"), true);
        print("case 8 enum reflection ", enumReflectionAttack(),
                "IllegalArgumentException: Cannot reflectively create enum objects");

        System.out.println(EnumSingleton.INSTANCE.greet());
    }

    /** Tries to build a second instance through the private constructor. */
    private static String reflectionAttack(Class<?> type) throws Exception {
        Constructor<?> constructor = type.getDeclaredConstructor();
        constructor.setAccessible(true);
        try {
            constructor.newInstance();
            return "attack succeeded - a second instance exists";
        } catch (java.lang.reflect.InvocationTargetException e) {
            Throwable cause = e.getCause();
            return cause.getClass().getSimpleName() + ": " + cause.getMessage();
        }
    }

    /** Enums are rejected by Constructor.newInstance() itself. */
    private static String enumReflectionAttack() throws Exception {
        Constructor<?> constructor = EnumSingleton.class.getDeclaredConstructors()[0];
        constructor.setAccessible(true);
        try {
            constructor.newInstance("EVIL", 1);
            return "attack succeeded - a second constant exists";
        } catch (IllegalArgumentException e) {
            return "IllegalArgumentException: " + e.getMessage();
        }
    }

    /** clone() is protected, so reach it reflectively from the client. */
    private static Object invokeClone(Object target) throws Exception {
        java.lang.reflect.Method clone = target.getClass().getDeclaredMethod("clone");
        clone.setAccessible(true);
        try {
            return clone.invoke(target);
        } catch (java.lang.reflect.InvocationTargetException e) {
            if (e.getCause() instanceof CloneNotSupportedException cnse) {
                throw cnse;
            }
            throw e;
        }
    }

    /** Writes the object to bytes and reads it straight back. */
    private static Object roundTrip(Object target) throws IOException, ClassNotFoundException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(target);
        }
        ByteArrayInputStream source = new ByteArrayInputStream(bytes.toByteArray());
        try (ObjectInputStream in = new ObjectInputStream(source)) {
            return in.readObject();
        }
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

