/*
 * =====================================================================
 *  Adapter - courier partner APIs                    Structural | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Checkout asks every courier partner for a shipping quote and shows the
 *   cheapest. Our code speaks ShippingProvider: kg in, whole rupees out.
 *   FedEx's SDK wants pounds and returns "USD 10.61"; Delhivery's wants grams
 *   and an int pincode, returns paise, and throws for places it cannot
 *   reach. We cannot change either SDK.
 *
 * KEY INSIGHT
 *   An adapter implements the interface we want, holds the SDK we have, and
 *   translates in between: units, currency, parameter types, error style.
 *   Every vendor quirk lives in one class per vendor; checkout stays clean
 *   and a new courier is one new adapter.
 *
 * ROLES IN THIS CODE
 *   ShippingProvider                  Target (our interface)
 *   FedExSdk, DelhiveryClient         Adaptee (third-party, cannot change)
 *   FedExAdapter, DelhiveryAdapter    Adapter
 *   cheapest()                        Client
 *
 * INTERVIEW FOLLOW-UPS
 *   - Adapter vs Facade: convert ONE interface vs simplify MANY.
 *   - Object adapter (holds the SDK, as here) vs class adapter (extends it):
 *     holding it also works when the SDK class is final.
 *   - Seen in: InputStreamReader (bytes -> chars), Arrays.asList, Spring
 *     MVC's HandlerAdapter.
 *
 * RUN
 *   4 cases: Delhivery quote, FedEx quote, cheapest courier, a pincode
 *   Delhivery cannot serve.
 */

import java.util.List;
import java.util.Locale;

record Parcel(double weightKg, String pincode) {
}

/** Target: what checkout wants from every courier. */
interface ShippingProvider {
    String name();

    /** Quote in whole rupees, or -1 when this courier cannot deliver there. */
    int quoteRs(Parcel parcel);
}

/** Adaptee from a vendor jar: pounds in, a USD string out. */
class FedExSdk {
    String getRate(double weightLbs, String destinationZip) {
        return String.format(Locale.US, "USD %.2f", 4.0 + 1.5 * weightLbs);
    }
}

/** Adaptee from another vendor: grams and an int pincode in, paise out. */
class DelhiveryClient {
    long priceInPaise(int grams, int pincode) {
        if (pincode >= 900_000) {
            throw new IllegalArgumentException("pincode " + pincode + " not serviceable");
        }
        return 4_000 + 6L * grams; // Rs 40 base + Rs 6 per 100 g
    }
}

class FedExAdapter implements ShippingProvider {
    private static final double LBS_PER_KG = 2.20462;
    private static final double RS_PER_USD = 83.0;
    private final FedExSdk sdk = new FedExSdk();

    public String name() {
        return "FedEx";
    }

    public int quoteRs(Parcel parcel) {
        String usd = sdk.getRate(parcel.weightKg() * LBS_PER_KG, parcel.pincode()); // kg -> lbs
        double dollars = Double.parseDouble(usd.substring("USD ".length()));    // "USD 10.61"
        return (int) Math.round(dollars * RS_PER_USD);                          // USD -> Rs
    }
}

class DelhiveryAdapter implements ShippingProvider {
    private final DelhiveryClient client = new DelhiveryClient();

    public String name() {
        return "Delhivery";
    }

    public int quoteRs(Parcel parcel) {
        try {
            int grams = (int) Math.round(parcel.weightKg() * 1000);
            return (int) (client.priceInPaise(grams, Integer.parseInt(parcel.pincode())) / 100);
        } catch (IllegalArgumentException e) {
            return -1; // vendor's exception -> our "cannot deliver" contract
        }
    }
}

class AdapterPatternDemo {

    /** Client: only ever sees ShippingProvider. */
    static String cheapest(List<ShippingProvider> couriers, Parcel parcel) {
        ShippingProvider best = null;
        int bestQuote = Integer.MAX_VALUE;
        for (ShippingProvider courier : couriers) {
            int quote = courier.quoteRs(parcel);
            if (quote >= 0 && quote < bestQuote) {
                best = courier;
                bestQuote = quote;
            }
        }
        return best == null ? "no courier" : best.name() + " Rs " + bestQuote;
    }

    public static void main(String[] args) {
        List<ShippingProvider> couriers = List.of(new FedExAdapter(), new DelhiveryAdapter());
        Parcel shoes = new Parcel(2.0, "560001");

        // Case 1-2: each adapter turns its vendor's units into whole rupees.
        print("case 1 Delhivery", new DelhiveryAdapter().quoteRs(shoes), 160);
        print("case 2 FedEx    ", new FedExAdapter().quoteRs(shoes), 881);

        // Case 3: typical. Checkout compares couriers without knowing either SDK.
        print("case 3 cheapest ", cheapest(couriers, shoes), "Delhivery Rs 160");

        // Case 4: edge. Delhivery's exception became -1, so FedEx wins here.
        print("case 4 remote   ", cheapest(couriers, new Parcel(2.0, "999001")), "FedEx Rs 881");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Facade - one placeOrder() over four services        Structural | Easy
 * =====================================================================
 *
 * PROBLEM
 *   Placing an order touches four services in a fixed order: validate the
 *   user, check stock, take payment, notify. Every caller (web, mobile app,
 *   admin tool) repeating that sequence and its early exits is a bug factory.
 *
 * KEY INSIGHT
 *   The facade owns the workflow: one call in, many subsystem calls out. It
 *   does NOT share an interface with what it wraps - that is what separates
 *   it from Adapter, Decorator and Proxy. The services do not know it exists.
 *
 * ROLES IN THIS CODE
 *   PaymentServiceFacade            Facade - processOrder() entry point
 *   UserService, InventoryService,
 *   PaymentGateway, Notification..  Subsystem
 *   FacadePatternExample            Client - knows only the facade
 *
 * INTERVIEW FOLLOW-UPS
 *   - Facade vs Adapter: simplify many vs convert one interface.
 *   - What if payment fails after stock was reserved? The facade is where
 *     the compensating step (release stock) belongs.
 *   - A Spring @Service over several clients/repositories is a facade; the
 *     second constructor here is how you inject fakes in a test.
 *
 * RUN
 *   4 cases: success, out of stock, unknown user, gateway rejects Rs 0.
 */

class UserService {
    /**
     * Demo rule: any id starting with "user" is a known customer.
     */
    public boolean validateUser(String userId) {
        System.out.println("  validating user : " + userId);
        return userId != null && userId.startsWith("user");
    }
}

class InventoryService {
    /**
     * Demo rule: the product id "OUT" is the one we never have in stock.
     */
    public boolean checkStock(String productId) {
        System.out.println("  checking inventory for productId : " + productId);
        return !"OUT".equals(productId);
    }
}

class PaymentGateway {
    /**
     * Demo rule: a non-positive amount is rejected by the gateway.
     */
    public boolean makePayment(String userId, double amount) {
        System.out.println("  processing payment of Rs " + amount + " for userId " + userId);
        return amount > 0;
    }
}

class NotificationService {
    public void sendNotification(String userId, String message) {
        System.out.println("  notifying user " + userId + " : " + message);
    }
}

/**
 * The Facade. Clients call processOrder(); they never touch the four services,
 * do not know the required order of the steps, and do not repeat the checks.
 */
class PaymentServiceFacade {

    private final UserService userService;
    private final InventoryService inventoryService;
    private final PaymentGateway paymentGateway;
    private final NotificationService notificationService;

    public PaymentServiceFacade() {
        this(
                new UserService(),
                new InventoryService(),
                new PaymentGateway(),
                new NotificationService()
        );
    }

    /**
     * Injected form: same facade, but the subsystem can be stubbed in a test.
     */
    public PaymentServiceFacade(UserService userService,
                                InventoryService inventoryService,
                                PaymentGateway paymentGateway,
                                NotificationService notificationService) {
        this.userService = userService;
        this.inventoryService = inventoryService;
        this.paymentGateway = paymentGateway;
        this.notificationService = notificationService;
    }

    /**
     * One call the client cares about. Returns a status string instead of void
     * so the demo (and a test) can assert the outcome, not just read the log.
     */
    public String processOrder(String userId, double amount, String productId) {
        System.out.println("  starting payment process");

        if (!userService.validateUser(userId)) {
            return "INVALID_USER";
        }
        if (!inventoryService.checkStock(productId)) {
            return "OUT_OF_STOCK";
        }
        if (!paymentGateway.makePayment(userId, amount)) {
            return "PAYMENT_FAILED";
        }
        notificationService.sendNotification(userId, "Order processed successfully");
        return "SUCCESS";
    }
}

class FacadePatternExample {

    public static void main(String[] args) {
        PaymentServiceFacade facade = new PaymentServiceFacade();

        // Case 1: typical - everything succeeds, all four services are used.
        print("case 1 happy path  ", facade.processOrder("user123", 123.0, "P675"), "SUCCESS");

        // Case 2: edge - stock check fails, so payment is never attempted.
        print("case 2 out of stock", facade.processOrder("user123", 123.0, "OUT"), "OUT_OF_STOCK");

        // Case 3: edge - unknown user, the facade exits on the very first step.
        print("case 3 bad user    ", facade.processOrder("ghost9", 123.0, "P675"), "INVALID_USER");

        // Case 4: tricky - valid user and stock, but the gateway rejects Rs 0.
        print("case 4 zero amount ", facade.processOrder("user123", 0.0, "P675"), "PAYMENT_FAILED");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + " : " + actual + "   expected " + expected);
        System.out.println();
    }
}

/*
 * =====================================================================
 *  Decorator - retry, fallback, logging on an API call  Structural | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   The product page calls inventory-service for stock. During a deploy it
 *   returns 503 for a few calls. We want retries, a safe fallback (show
 *   "out of stock" instead of an error page) and a log of each attempt -
 *   switchable per call site, without touching the HTTP client class and
 *   without a RetryingLoggingFallbackClient subclass for every combination.
 *
 * KEY INSIGHT
 *   Each wrapper implements the SAME interface it wraps, so wrappers stack:
 *   new Fallback(new Retry(new Logging(remote))). Each adds one behaviour
 *   and delegates the rest. ORDER MATTERS: a fallback inside a retry
 *   swallows the error, so the retry never fires (case 4 vs case 3).
 *
 * ROLES IN THIS CODE
 *   InventoryClient           Component
 *   RemoteInventory           ConcreteComponent (the real, flaky call)
 *   InventoryDecorator        Decorator base: IS-A and HAS-A InventoryClient
 *   Retry, Fallback, Logging  ConcreteDecorator
 *
 * INTERVIEW FOLLOW-UPS
 *   - Decorator vs Proxy: same shape; a decorator ADDS behaviour and is
 *     handed its wrappee, a proxy CONTROLS access and usually owns it.
 *   - Seen in: Resilience4j Decorators.ofSupplier(..).withRetry(..),
 *     java.io (new BufferedReader(new FileReader(..))),
 *     Collections.unmodifiableList.
 *
 * RUN
 *   5 cases: bare call fails, retry recovers, fallback after retries run
 *   out, the wrong wrap order, logging every attempt.
 */

import java.util.ArrayList;
import java.util.List;

interface InventoryClient {
    int stock(String sku);
}

/** The real remote call. Fails the first N calls, like a service mid-deploy. */
class RemoteInventory implements InventoryClient {
    private int failuresLeft;
    int calls;

    RemoteInventory(int failures) {
        this.failuresLeft = failures;
    }

    public int stock(String sku) {
        calls++;
        if (failuresLeft-- > 0) {
            throw new IllegalStateException("503 from inventory-service");
        }
        return 42;
    }
}

/** IS an InventoryClient and HAS one - that double identity is the pattern. */
abstract class InventoryDecorator implements InventoryClient {
    protected final InventoryClient inner;

    InventoryDecorator(InventoryClient inner) {
        this.inner = inner;
    }
}

class Retry extends InventoryDecorator {
    private final int maxAttempts;

    Retry(int maxAttempts, InventoryClient inner) {
        super(inner);
        this.maxAttempts = maxAttempts;
    }

    public int stock(String sku) {
        RuntimeException last = null;
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                return inner.stock(sku);
            } catch (RuntimeException e) {
                last = e;
            }
        }
        throw last;
    }
}

class Fallback extends InventoryDecorator {
    private final int fallbackStock;

    Fallback(int fallbackStock, InventoryClient inner) {
        super(inner);
        this.fallbackStock = fallbackStock;
    }

    public int stock(String sku) {
        try {
            return inner.stock(sku);
        } catch (RuntimeException e) {
            return fallbackStock; // degrade, do not fail the page
        }
    }
}

class Logging extends InventoryDecorator {
    final List<String> log = new ArrayList<>();

    Logging(InventoryClient inner) {
        super(inner);
    }

    public int stock(String sku) {
        try {
            int stock = inner.stock(sku);
            log.add("ok " + stock);
            return stock;
        } catch (RuntimeException e) {
            log.add("fail");
            throw e;
        }
    }
}

class DecoratorDesignPattern {

    public static void main(String[] args) {
        // Case 1: no decorators. The 503 reaches the product page.
        String outcome;
        try {
            outcome = "stock " + new RemoteInventory(2).stock("SKU-1");
        } catch (IllegalStateException e) {
            outcome = e.getMessage();
        }
        print("case 1 bare      ", outcome, "503 from inventory-service");

        // Case 2: typical. Two failures, then success on the 3rd attempt.
        RemoteInventory flaky = new RemoteInventory(2);
        print("case 2a retry    ", new Retry(3, flaky).stock("SKU-1"), 42);
        print("case 2b calls    ", flaky.calls, 3);

        // Case 3: still down after 3 attempts -> the fallback answers 0.
        RemoteInventory down = new RemoteInventory(5);
        print("case 3a fallback ", new Fallback(0, new Retry(3, down)).stock("SKU-1"), 0);
        print("case 3b calls    ", down.calls, 3);

        // Case 4: tricky. Same two wrappers, other order: the fallback swallows the
        // first error, so Retry sees a success and never tries again.
        RemoteInventory blip = new RemoteInventory(2);
        print("case 4a wrong way", new Retry(3, new Fallback(0, blip)).stock("SKU-1"), 0);
        print("case 4b calls    ", blip.calls, 1);

        // Case 5: logging INSIDE retry sees every attempt.
        Logging logged = new Logging(new RemoteInventory(2));
        new Retry(3, logged).stock("SKU-1");
        print("case 5 log       ", logged.log, "[fail, fail, ok 42]");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Proxy - cached, admin-only product catalog          Structural | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Every product page reads a price from the catalog DB, so a sale spike
 *   floods the DB with the same few reads. Price changes must be limited to
 *   admins and must never leave an old price in a cache. Callers should
 *   not change: they still just call ProductCatalog.
 *
 * KEY INSIGHT
 *   The proxy implements the same interface as the real catalog and stands
 *   in front of it, deciding whether and when the real one is touched:
 *   serve reads from a cache, refuse non-admin writes, evict on write.
 *   Spring builds exactly this at runtime for @Cacheable, @Transactional
 *   and @PreAuthorize, using a JDK dynamic proxy (case 4).
 *
 * ROLES IN THIS CODE
 *   ProductCatalog    Subject
 *   DbCatalog         RealSubject (counts DB reads)
 *   CatalogProxy      Proxy: caching + protection + invalidation
 *   loggingProxy()    the same idea built at runtime by java.lang.reflect.Proxy
 *
 * INTERVIEW FOLLOW-UPS
 *   - Proxy vs Decorator: same shape; a proxy CONTROLS access to one object
 *     (often creating it), a decorator ADDS behaviour and is handed it.
 *   - Self-invocation: this.price() inside the real bean skips the Spring
 *     proxy, so @Cacheable on it silently does nothing.
 *   - Other kinds: lazy (Hibernate entities), remote (gRPC stubs).
 *
 * RUN
 *   4 cases: second read cached, non-admin write refused, admin write
 *   evicts the cache, dynamic proxy records every call.
 */

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

interface ProductCatalog {
    int price(String sku);

    void updatePrice(String user, String sku, int priceRs);
}

class DbCatalog implements ProductCatalog {
    private final Map<String, Integer> table = new HashMap<>(Map.of("PHONE-15", 79_900));
    int dbReads;

    public int price(String sku) {
        dbReads++;
        return table.get(sku);
    }

    public void updatePrice(String user, String sku, int priceRs) {
        table.put(sku, priceRs);
    }
}

class CatalogProxy implements ProductCatalog {
    private final ProductCatalog real;
    private final Set<String> admins;
    private final Map<String, Integer> cache = new HashMap<>();

    CatalogProxy(ProductCatalog real, Set<String> admins) {
        this.real = real;
        this.admins = admins;
    }

    public int price(String sku) {
        return cache.computeIfAbsent(sku, real::price); // DB only on a cache miss
    }

    public void updatePrice(String user, String sku, int priceRs) {
        if (!admins.contains(user)) {
            throw new SecurityException(user + " may not change prices");
        }
        real.updatePrice(user, sku, priceRs);
        cache.remove(sku); // never serve the old price after a write
    }
}

class ProxyDesignPattern {

    /** What Spring AOP does: a proxy class generated at runtime for an interface. */
    static ProductCatalog loggingProxy(ProductCatalog target, List<String> calls) {
        return (ProductCatalog) Proxy.newProxyInstance(
                ProductCatalog.class.getClassLoader(),
                new Class<?>[]{ProductCatalog.class},
                (proxy, method, args) -> {
                    calls.add(method.getName()); // "before advice"
                    return method.invoke(target, args);
                });
    }

    public static void main(String[] args) {
        DbCatalog db = new DbCatalog();
        ProductCatalog catalog = new CatalogProxy(db, Set.of("admin"));

        // Case 1: typical. Two reads, one DB hit.
        catalog.price("PHONE-15");
        print("case 1a price   ", catalog.price("PHONE-15"), 79900);
        print("case 1b db reads", db.dbReads, 1);

        // Case 2: protection. A non-admin write never reaches the DB.
        String outcome;
        try {
            catalog.updatePrice("guest", "PHONE-15", 1);
            outcome = "updated";
        } catch (SecurityException e) {
            outcome = e.getMessage();
        }
        print("case 2a guest   ", outcome, "guest may not change prices");
        print("case 2b price   ", catalog.price("PHONE-15"), 79900);

        // Case 3: tricky. The write evicts the cache, so the next read is fresh.
        catalog.updatePrice("admin", "PHONE-15", 74_900);
        print("case 3a new     ", catalog.price("PHONE-15"), 74900);
        print("case 3b db reads", db.dbReads, 2);

        // Case 4: a runtime-generated proxy in front of the hand-written one.
        List<String> calls = new ArrayList<>();
        ProductCatalog logged = loggingProxy(catalog, calls);
        logged.price("PHONE-15");
        logged.updatePrice("admin", "PHONE-15", 69_900);
        print("case 4a calls   ", calls, "[price, updatePrice]");
        print("case 4b class   ", logged.getClass().getSimpleName().startsWith("$Proxy"), true);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Composite - product bundles inside an order          Structural | Medium
 * =====================================================================
 *
 * PROBLEM
 *   An order holds single products and bundles ("Work Combo" = laptop +
 *   headset + mouse), and a bundle can contain another bundle. Totals,
 *   invoices and display must work at any depth without "if (isBundle)".
 *
 * KEY INSIGHT
 *   Product (leaf) and ProductBundle (composite) implement the same
 *   OrderItem, so a bundle can hold bundles. getPrice() on a bundle sums its
 *   children and the recursion stops at the leaves - no depth parameter, no
 *   casts. Summing with identity 0.0 keeps an empty bundle from crashing.
 *
 * ROLES IN THIS CODE
 *   OrderItem         Component - getPrice() + showDetails()
 *   Product           Leaf
 *   ProductBundle     Composite - holds List<OrderItem>
 *   CompositePattern  Client - calls only OrderItem
 *
 * INTERVIEW FOLLOW-UPS
 *   - Safe vs transparent: add()/remove() only on the composite (this file)
 *     or on OrderItem so leaves must throw?
 *   - Add a bundle discount: one field on ProductBundle, nothing else moves.
 *   - Seen in: category trees, file systems, UI component trees, Swing
 *     Container.
 *
 * RUN
 *   4 cases: nested order total, single leaf, empty bundle, total after a
 *   remove; then prints the whole tree.
 */

import java.util.ArrayList;
import java.util.List;

/** Component: the single type the client codes against, leaf or group. */
interface OrderItem {

    double getPrice();

    /** Print this node (and any children) with the given left indent. */
    void showDetails(String indent);

    /** Convenience entry point for the client. */
    default void showDetails() {
        showDetails("");
    }
}

/** Leaf: an individual product. It has no children, so the recursion stops here. */
class Product implements OrderItem {

    private final double price;
    private final String name;

    public Product(double price, String name) {
        this.price = price;
        this.name = name;
    }

    @Override
    public double getPrice() {
        return price;
    }

    @Override
    public void showDetails(String indent) {
        System.out.println(indent + "- " + name + ": Rs " + price);
    }
}

/**
 * Composite: a bundle of OrderItems. Because a bundle IS an OrderItem, a
 * bundle can contain bundles, which is what makes the structure a tree.
 */
class ProductBundle implements OrderItem {

    private final String name;
    private final List<OrderItem> items = new ArrayList<>();

    public ProductBundle(String name) {
        this.name = name;
    }

    // add/remove live only on the composite: the "safe" variant of the pattern.
    public void addItem(OrderItem orderItem) {
        items.add(orderItem);
    }

    public void removeItem(OrderItem orderItem) {
        items.remove(orderItem);
    }

    @Override
    public double getPrice() {
        // Identity 0.0 matters: an empty bundle must cost 0, not blow up.
        return items.stream().mapToDouble(OrderItem::getPrice).sum();
    }

    @Override
    public void showDetails(String indent) {
        System.out.println(indent + "Bundle: " + name);
        for (OrderItem item : items) {
            item.showDetails(indent + "  "); // same call on leaves and bundles
        }
        System.out.println(indent + "= Total for " + name + ": Rs " + getPrice());
    }
}

class CompositePattern {

    public static void main(String[] args) {
        Product laptop = new Product(250_000.0, "MacBook Pro");
        Product headset = new Product(25_000.0, "Airpods Pro");
        Product mouse = new Product(10_000.0, "Magic Mouse");
        Product keyboard = new Product(10_000.0, "Magic Keyboard");

        ProductBundle workCombo = new ProductBundle("Work Combo");
        workCombo.addItem(laptop);
        workCombo.addItem(headset);
        workCombo.addItem(mouse);
        workCombo.addItem(keyboard);

        Product phone = new Product(240_000.0, "17 Pro Max");
        Product pouch = new Product(4_500.0, "Silicon Pouch");
        ProductBundle phoneCombo = new ProductBundle("Phone Combo");
        phoneCombo.addItem(phone);
        phoneCombo.addItem(pouch);

        // A bundle of bundles: two levels deep, and the client never notices.
        ProductBundle completeOrder = new ProductBundle("Complete Order");
        completeOrder.addItem(workCombo);
        completeOrder.addItem(phoneCombo);

        // Case 1: typical - the whole nested tree.
        print("case 1 nested order ", completeOrder.getPrice(), 539500.0);

        // Case 2: edge - a leaf answers the same call with no recursion.
        print("case 2 single leaf  ", laptop.getPrice(), 250000.0);

        // Case 3: edge - an empty bundle. This used to throw NoSuchElementException.
        ProductBundle emptyGiftBox = new ProductBundle("Empty Gift Box");
        print("case 3 empty bundle ", emptyGiftBox.getPrice(), 0.0);

        // Case 4: tricky - remove a child; the parent total updates by recursion.
        workCombo.removeItem(mouse);
        print("case 4 after remove ", completeOrder.getPrice(), 529500.0);

        System.out.println();
        completeOrder.showDetails(); // one call renders the entire tree
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + " : " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Flyweight - forest of trees in a game map               Structural | Medium
 * =====================================================================
 *
 * PROBLEM
 *   A game map draws a million trees. Each Oak repeats the same name,
 *   colour and texture (the heavy part); only its x, y differ. One full
 *   object per tree runs out of memory.
 *
 * KEY INSIGHT
 *   What repeats (species, colour, texture) is stored once in a shared,
 *   immutable TreeType; what varies (x, y) stays in a tiny Tree. The
 *   factory enforces the sharing: a million trees cost a million small
 *   Trees plus one TreeType per species.
 *
 * ROLES IN THIS CODE
 *   TreeType          Flyweight - intrinsic state only, immutable
 *   TreeFactory       FlyweightFactory - one instance per distinct key
 *   Tree              Context - x, y plus a pointer to its TreeType
 *   FlyweightExample  Client - never calls new TreeType
 *
 * INTERVIEW FOLLOW-UPS
 *   - Flyweight vs Singleton: one instance per distinct value, not one total.
 *   - Why immutable? One writer would change every tree sharing it.
 *   - Seen in: Integer.valueOf cache (-128..127), the String pool, text
 *     editor glyphs, map markers in delivery apps.
 *
 * RUN
 *   3 cases: plant and draw, re-plant the same species 100 times, identity
 *   checks on the factory.
 */

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Flyweight: intrinsic (shared, immutable) state only. Never stores x/y. */
class TreeType {
    private final String name;
    private final String color;
    private final String texture;

    public TreeType(String name, String color, String texture) {
        this.name = name;
        this.color = color;
        this.texture = texture;
    }

    /** x and y arrive as arguments - they are extrinsic, so not fields here. */
    public void draw(int x, int y) {
        System.out.println("  drawing " + name + " (" + color + ", " + texture
                + ") at (" + x + ", " + y + ")");
    }

    @Override
    public String toString() {
        return name + "/" + color + "/" + texture;
    }
}

/** FlyweightFactory: the only place a TreeType is ever constructed. */
class TreeFactory {
    private static final Map<String, TreeType> CACHE = new HashMap<>();

    public static TreeType getTreeType(String name, String color, String texture) {
        // The key must cover every intrinsic field, otherwise two different
        // species could collide onto one shared instance.
        String key = name + "-" + color + "-" + texture;
        return CACHE.computeIfAbsent(key, k -> new TreeType(name, color, texture));
    }

    /** How many distinct flyweights exist - the number the pattern minimises. */
    public static int distinctTypes() {
        return CACHE.size();
    }

    public static void clear() {
        CACHE.clear();
    }
}

/** Context: one per tree. Cheap, because it only holds x, y and a pointer. */
class Tree {
    private final TreeType type;
    private final int x;
    private final int y;

    public Tree(TreeType type, int x, int y) {
        this.type = type;
        this.x = x;
        this.y = y;
    }

    /** Extrinsic state is handed to the flyweight at call time. */
    public void plant() {
        type.draw(x, y);
    }

    public TreeType getType() {
        return type;
    }
}

/** Client. */
class FlyweightExample {
    private final List<Tree> forest = new ArrayList<>();

    public void plantTree(String name, String color, String texture, int x, int y) {
        TreeType treeType = TreeFactory.getTreeType(name, color, texture);
        forest.add(new Tree(treeType, x, y));
    }

    public void draw() {
        for (Tree tree : forest) {
            tree.plant();
        }
    }

    public int treeCount() {
        return forest.size();
    }

    public List<Tree> trees() {
        return forest;
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }

    public static void main(String[] args) {
        // ---- case 1: typical - 3 trees, only 2 distinct species -------------
        TreeFactory.clear();
        FlyweightExample forest = new FlyweightExample();
        forest.plantTree("Oak", "Green", "Rough", 10, 20);
        forest.plantTree("Pine", "DarkGreen", "Smooth", 15, 25);
        forest.plantTree("Oak", "Green", "Rough", 30, 35); // reuses the Oak flyweight
        forest.draw();
        print("case 1 trees planted", forest.treeCount(), 3);
        print("case 1 distinct flyweights", TreeFactory.distinctTypes(), 2);

        // ---- case 2: edge - planting the same species 100 more times ---------
        for (int i = 0; i < 100; i++) {
            forest.plantTree("Oak", "Green", "Rough", i, i);
        }
        print("case 2 trees planted", forest.treeCount(), 103);
        print("case 2 distinct flyweights", TreeFactory.distinctTypes(), 2);

        // ---- case 3: tricky - identity, not equality, is what is shared ------
        TreeType a = TreeFactory.getTreeType("Oak", "Green", "Rough");
        TreeType b = TreeFactory.getTreeType("Oak", "Green", "Rough");
        TreeType c = TreeFactory.getTreeType("Oak", "Brown", "Rough"); // color differs
        print("case 3 same description -> same object", a == b, true);
        print("case 3 different color -> new object", a == c, false);
        print("case 3 distinct flyweights now", TreeFactory.distinctTypes(), 3);
        print("case 3 first tree shares the Oak flyweight",
                forest.trees().get(0).getType() == a, true);
    }
}

/*
 * =====================================================================
 *  Bridge - notification type x delivery channel           Structural | Hard
 * =====================================================================
 *
 * PROBLEM
 *   The store sends OTPs, "order shipped" updates and promo offers, over
 *   SMS (160 chars, no subject), email and app push (short body). With one
 *   class per pair that is OtpSms, OtpEmail, ShippedPush... 9 classes, and
 *   adding WhatsApp means 3 more.
 *
 * KEY INSIGHT
 *   Two independent dimensions -> two hierarchies joined by a field.
 *   Notification decides WHAT is said; Channel decides HOW it travels. The
 *   `channel` field is the bridge: 3 + 3 classes cover all 9 pairs, and a
 *   new channel is written once (case 4). If you catch yourself naming a
 *   class OtpSmsNotification, you have two dimensions.
 *
 * ROLES IN THIS CODE
 *   Notification                     Abstraction (holds a Channel)
 *   OtpNotification, Shipped.., Promo..  RefinedAbstraction
 *   Channel                          Implementor
 *   SmsChannel, EmailChannel, Push.. ConcreteImplementor
 *
 * INTERVIEW FOLLOW-UPS
 *   - Bridge vs Strategy: same shape. Bridge is designed up front to let two
 *     hierarchies grow apart; Strategy swaps one algorithm in one class.
 *   - Seen in: JDBC (DriverManager API vs vendor Driver), SLF4J API vs
 *     Logback/Log4j binding.
 *
 * RUN
 *   4 cases: OTP by SMS, shipped by email, promo by push (cut short), a
 *   WhatsApp channel added as a lambda with no other changes.
 */

/** Implementor: HOW a message travels, with that channel's limits. */
interface Channel {
    String send(String to, String subject, String body);
}

class SmsChannel implements Channel {
    public String send(String to, String subject, String body) {
        return "SMS to " + to + ": " + cut(body, 160); // SMS has no subject line
    }

    static String cut(String text, int max) {
        return text.length() <= max ? text : text.substring(0, max - 3) + "...";
    }
}

class EmailChannel implements Channel {
    public String send(String to, String subject, String body) {
        return "EMAIL to " + to + " [" + subject + "] " + body;
    }
}

class PushChannel implements Channel {
    public String send(String to, String subject, String body) {
        return "PUSH to " + to + " [" + subject + "] " + SmsChannel.cut(body, 40);
    }
}

/** Abstraction: WHAT is said. The channel field is the bridge. */
abstract class Notification {
    protected final Channel channel;

    Notification(Channel channel) {
        this.channel = channel;
    }

    abstract String sendTo(String recipient);
}

class OtpNotification extends Notification {
    private final String otp;

    OtpNotification(Channel channel, String otp) {
        super(channel);
        this.otp = otp;
    }

    String sendTo(String recipient) {
        return channel.send(recipient, "Your OTP", otp + " is your login OTP, valid 5 minutes.");
    }
}

class ShippedNotification extends Notification {
    private final String orderId;
    private final String courier;

    ShippedNotification(Channel channel, String orderId, String courier) {
        super(channel);
        this.orderId = orderId;
        this.courier = courier;
    }

    String sendTo(String recipient) {
        return channel.send(recipient, "Order shipped",
                "Order " + orderId + " shipped via " + courier + ".");
    }
}

class PromoNotification extends Notification {
    private final String offer;

    PromoNotification(Channel channel, String offer) {
        super(channel);
        this.offer = offer;
    }

    String sendTo(String recipient) {
        return channel.send(recipient, "Sale is live", offer);
    }
}

class BridgePatternExample {

    public static void main(String[] args) {
        // Case 1-3: three message types over three channels, no OtpSms-style class.
        print("case 1 OTP sms     ",
                new OtpNotification(new SmsChannel(), "482913").sendTo("+910000000001"),
                "SMS to +910000000001: 482913 is your login OTP, valid 5 minutes.");
        print("case 2 shipped mail",
                new ShippedNotification(new EmailChannel(), "OD-1001", "Delhivery")
                        .sendTo("a@example.com"),
                "EMAIL to a@example.com [Order shipped] Order OD-1001 shipped via Delhivery.");

        // Case 3: edge. The push channel's length limit applies to ANY message type.
        print("case 3 promo push  ",
                new PromoNotification(new PushChannel(),
                        "Flat 50% off on sneakers. Ends Sunday midnight.").sendTo("device-7"),
                "PUSH to device-7 [Sale is live] Flat 50% off on sneakers. Ends Sunday...");

        // Case 4: a new channel, written once, works with every notification type.
        Channel whatsApp = (to, subject, body) -> "WHATSAPP to " + to + ": *" + subject + "* "
                + body;
        print("case 4 shipped wa  ",
                new ShippedNotification(whatsApp, "OD-1001", "BlueDart").sendTo("+910000000001"),
                "WHATSAPP to +910000000001: *Order shipped* Order OD-1001 shipped via BlueDart.");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

AAScratches/03-LLD/Design-Patterns/3. Be.text:
/*
 * =====================================================================
 *  Strategy - checkout promotions                   Behavioral | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Every sale runs a different promotion: Rs 200 off above Rs 999, 10% off
 *   capped at Rs 500, buy 2 get the cheapest free. Marketing adds a new one
 *   each month, and checkout should apply the best offer for the cart.
 *   An if/else per promo inside checkout grows forever.
 *
 * KEY INSIGHT
 *   The promotion is a field holding an object, not a branch. Each promo is
 *   one class (or one lambda) behind the same interface; checkout only calls
 *   discount(cart). Picking the best offer is just "try every strategy,
 *   keep the biggest".
 *
 * ROLES IN THIS CODE
 *   Promotion                          Strategy
 *   FlatOff, PercentOff, BuyTwoGetOne  ConcreteStrategy
 *   Checkout                           Context
 *
 * INTERVIEW FOLLOW-UPS
 *   - Strategy vs State: the client chooses a strategy; a state chooses
 *     its own successor (C01_StateDesignPattern).
 *   - A one-method strategy is a functional interface, so a lambda is a
 *     strategy (case 6).
 *   - Seen in: Comparator for sort, Spring's PasswordEncoder.
 *
 * RUN
 *   6 cases: flat, percent with cap, buy-2-get-1, minimum not met, best
 *   offer, a lambda promo.
 */

import java.util.ArrayList;
import java.util.List;

record CartItem(String name, int priceRs, int qty) {
}

interface Promotion {
    /** Discount in whole rupees; 0 when the promo does not apply. */
    int discount(List<CartItem> cart);

    static int subtotal(List<CartItem> cart) {
        return cart.stream().mapToInt(i -> i.priceRs() * i.qty()).sum();
    }
}

class FlatOff implements Promotion {
    private final int amount;
    private final int minCart;

    FlatOff(int amount, int minCart) {
        this.amount = amount;
        this.minCart = minCart;
    }

    public int discount(List<CartItem> cart) {
        return Promotion.subtotal(cart) >= minCart ? amount : 0;
    }
}

class PercentOff implements Promotion {
    private final int percent;
    private final int cap;

    PercentOff(int percent, int cap) {
        this.percent = percent;
        this.cap = cap;
    }

    public int discount(List<CartItem> cart) {
        return Math.min(Promotion.subtotal(cart) * percent / 100, cap);
    }
}

/** For every 3 units in the cart, the cheapest unit is free. */
class BuyTwoGetOne implements Promotion {
    public int discount(List<CartItem> cart) {
        List<Integer> unitPrices = new ArrayList<>();
        cart.forEach(i -> {
            for (int q = 0; q < i.qty(); q++) {
                unitPrices.add(i.priceRs());
            }
        });
        unitPrices.sort(null);
        return unitPrices.subList(0, unitPrices.size() / 3).stream().mapToInt(p -> p).sum();
    }
}

/** Context: never names a concrete promotion. */
class Checkout {
    static int total(List<CartItem> cart, Promotion promo) {
        return Promotion.subtotal(cart) - promo.discount(cart);
    }

    static Promotion bestOffer(List<CartItem> cart, List<Promotion> live) {
        Promotion best = c -> 0; // "no promo" is a strategy too
        for (Promotion promo : live) {
            if (promo.discount(cart) > best.discount(cart)) {
                best = promo;
            }
        }
        return best;
    }
}

class StrategyDesignPattern {

    public static void main(String[] args) {
        // Subtotal: 3000 + 2 x 300 + 800 = 4400.
        List<CartItem> cart = List.of(new CartItem("Shoes", 3000, 1),
                new CartItem("Socks", 300, 2), new CartItem("Tee", 800, 1));
        Promotion flat = new FlatOff(200, 999);
        Promotion percent = new PercentOff(10, 500);
        Promotion b2g1 = new BuyTwoGetOne();

        // Case 1-3: same checkout call, three algorithms.
        print("case 1 flat 200    ", Checkout.total(cart, flat), 4200);
        print("case 2 10% (440)   ", Checkout.total(cart, percent), 3960);
        print("case 3 buy 2 get 1 ", Checkout.total(cart, b2g1), 4100);

        // Case 4: edge. Rs 600 cart is under the Rs 999 minimum.
        List<CartItem> small = List.of(new CartItem("Socks", 300, 2));
        print("case 4 min not met ", Checkout.total(small, flat), 600);

        // Case 5: the best of the live offers, chosen at runtime.
        Promotion best = Checkout.bestOffer(cart, List.of(flat, percent, b2g1));
        print("case 5 best offer  ", best.getClass().getSimpleName(), "PercentOff");

        // Case 6: a first-order 15% promo, added as a lambda - no new class.
        print("case 6 lambda 15%  ", Checkout.total(cart, c -> Promotion.subtotal(c) * 15 / 100),
                3740);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Template Method - order fulfilment                Behavioral | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   Every order goes validate -> reserve stock -> charge -> deliver ->
 *   notify. But a physical order ships by courier, an e-book has no stock
 *   and is emailed, and a pre-order only authorises the card until release.
 *   Copying the whole flow per order type lets the copies drift apart.
 *
 * KEY INSIGHT
 *   The base class owns the order of steps in one final method; subclasses
 *   fill in only the steps that differ. A boolean hook (needsStock) lets a
 *   subclass skip a step without touching the skeleton. Control is
 *   inverted: the base class calls the subclass, not the other way round.
 *
 * ROLES IN THIS CODE
 *   Fulfilment                 AbstractClass - fulfil() is the template method
 *   deliver()                  primitive operation (every subclass must write)
 *   charge(), needsStock()     default step and hook (override if needed)
 *   Physical.., Digital.., PreOrder..  ConcreteClass
 *
 * INTERVIEW FOLLOW-UPS
 *   - Template vs Strategy: inheritance fixes the skeleton at compile time;
 *     Strategy swaps a whole algorithm by composition at runtime.
 *   - Why final? So no subclass can reorder or skip the mandatory steps.
 *   - Seen in: Spring's JdbcTemplate and AbstractController, JUnit's
 *     setUp/test/tearDown, java.io.InputStream.read(byte[]).
 *
 * RUN
 *   4 cases: physical, digital (no stock step), pre-order (authorise only),
 *   quantity 0 rejected at validation.
 */

import java.util.ArrayList;
import java.util.List;

record Order(String id, int qty) {
}

abstract class Fulfilment {

    /** The template method. final: the step order is not negotiable. */
    final List<String> fulfil(Order order) {
        List<String> steps = new ArrayList<>();
        if (order.qty() <= 0) {
            steps.add("rejected qty " + order.qty());
            return steps;
        }
        steps.add("validated " + order.id());
        if (needsStock()) {
            steps.add("reserved stock x" + order.qty());
        }
        steps.add(charge());
        steps.add(deliver(order));
        steps.add("notified customer"); // invariant: every type ends here
        return steps;
    }

    /** Hook: subclasses may switch the stock step off. */
    protected boolean needsStock() {
        return true;
    }

    /** Default step: subclasses may override. */
    protected String charge() {
        return "charged card";
    }

    /** Primitive operation: every subclass must say how it delivers. */
    protected abstract String deliver(Order order);
}

class PhysicalFulfilment extends Fulfilment {
    protected String deliver(Order order) {
        return "shipped by courier";
    }
}

class DigitalFulfilment extends Fulfilment {
    protected boolean needsStock() {
        return false; // an e-book never runs out
    }

    protected String deliver(Order order) {
        return "emailed download link";
    }
}

class PreOrderFulfilment extends Fulfilment {
    protected String charge() {
        return "authorised card, charge on release";
    }

    protected String deliver(Order order) {
        return "queued for release day";
    }
}

class TemplateDesignPattern {

    public static void main(String[] args) {
        print("case 1 physical", new PhysicalFulfilment().fulfil(new Order("OD-1", 2)),
                "[validated OD-1, reserved stock x2, charged card, shipped by courier,"
                        + " notified customer]");
        print("case 2 digital ", new DigitalFulfilment().fulfil(new Order("OD-2", 1)),
                "[validated OD-2, charged card, emailed download link, notified customer]");
        print("case 3 preorder", new PreOrderFulfilment().fulfil(new Order("OD-3", 1)),
                "[validated OD-3, reserved stock x1, authorised card, charge on release,"
                        + " queued for release day, notified customer]");

        // Case 4: edge. The skeleton stops at validation for every type.
        print("case 4 qty 0   ", new DigitalFulfilment().fulfil(new Order("OD-4", 0)),
                "[rejected qty 0]");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Observer - back-in-stock alerts                   Behavioral | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   A product page offers "Notify me when available". When stock goes from
 *   0 to anything, everyone who asked gets one alert and is then removed;
 *   the wishlist badge updates every time. The product must not know about
 *   email, push or badges, and one broken listener must not stop the rest.
 *
 * KEY INSIGHT
 *   The subject keeps a list of listeners behind one interface and calls
 *   them on the event it owns - here the 0 -> positive transition, not
 *   every restock. Two production details: catch per listener so one
 *   failure is isolated, and use CopyOnWriteArrayList so a listener can
 *   unsubscribe itself while the list is being walked.
 *
 * ROLES IN THIS CODE
 *   StockListener    Observer
 *   ProductPage      Subject - subscribe, unsubscribe, notify on 0 -> n
 *   NotifyMeOnce     ConcreteObserver - one alert, then unsubscribes
 *   lambdas in main  ConcreteObserver - wishlist badge, a broken listener
 *
 * INTERVIEW FOLLOW-UPS
 *   - Push (send qty) vs pull (listener asks the subject): push here.
 *   - Slow listeners: hand delivery to an executor or a queue (Kafka) so
 *     restock() does not wait on email.
 *   - Seen in: Spring ApplicationEventPublisher + @EventListener, UI event
 *     listeners, PropertyChangeListener.
 *
 * RUN
 *   4 cases: first restock alerts all, second restock alerts none, one-shot
 *   listeners removed, a throwing listener does not block the badge.
 */

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

interface StockListener {
    void backInStock(String product, int qty);
}

class ProductPage {
    private final String name;
    private int stock;
    private final List<StockListener> listeners = new CopyOnWriteArrayList<>();
    int failedListeners;

    ProductPage(String name) {
        this.name = name;
    }

    void subscribe(StockListener listener) {
        listeners.add(listener);
    }

    void unsubscribe(StockListener listener) {
        listeners.remove(listener);
    }

    int listenerCount() {
        return listeners.size();
    }

    void sell(int qty) {
        stock -= qty;
    }

    void restock(int qty) {
        boolean wasEmpty = stock == 0;
        stock += qty;
        if (wasEmpty && stock > 0) { // the event is the transition, not every restock
            for (StockListener listener : listeners) {
                try {
                    listener.backInStock(name, stock);
                } catch (RuntimeException e) {
                    failedListeners++; // one broken listener must not starve the others
                }
            }
        }
    }
}

/** "Notify me" button: alert once, then leave. */
class NotifyMeOnce implements StockListener {
    private final ProductPage page;
    private final String email;
    private final List<String> outbox;

    NotifyMeOnce(ProductPage page, String email, List<String> outbox) {
        this.page = page;
        this.email = email;
        this.outbox = outbox;
    }

    public void backInStock(String product, int qty) {
        outbox.add("mail " + email);
        page.unsubscribe(this); // safe mid-notify thanks to CopyOnWriteArrayList
    }
}

class ObserverDesignPattern {

    public static void main(String[] args) {
        List<String> outbox = new ArrayList<>();
        ProductPage sneakers = new ProductPage("Sneakers");
        sneakers.subscribe(new NotifyMeOnce(sneakers, "a@example.com", outbox));
        sneakers.subscribe(new NotifyMeOnce(sneakers, "b@example.com", outbox));
        sneakers.subscribe((product, qty) -> outbox.add("badge " + product + " " + qty));

        // Case 1: typical. 0 -> 5 alerts everyone.
        sneakers.restock(5);
        print("case 1 first restock", outbox,
                "[mail a@example.com, mail b@example.com, badge Sneakers 5]");

        // Case 2: 5 -> 10 is not "back in stock", so nobody hears about it.
        sneakers.restock(5);
        print("case 2 second restock", outbox.size(), 3);

        // Case 3: the two one-shot listeners removed themselves; the badge stays.
        print("case 3 listeners left", sneakers.listenerCount(), 1);

        // Case 4: tricky. Sell out, add a broken listener, restock: the badge
        // (subscribed earlier) still gets its update.
        sneakers.sell(10);
        sneakers.subscribe((product, qty) -> {
            throw new IllegalStateException("SMS provider down");
        });
        sneakers.restock(2);
        print("case 4a badge again ", outbox.get(outbox.size() - 1), "badge Sneakers 2");
        print("case 4b failures    ", sneakers.failedListeners, 1);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Iterator - paged orders API export                Behavioral | Easy
 * =====================================================================
 *
 * PROBLEM
 *   A nightly job exports every order to the data warehouse. The orders
 *   service only returns pages (GET /orders?cursor=0&limit=3), and loading
 *   all 2 million orders into one list would exhaust memory. The export
 *   code should still read like a plain for-each loop.
 *
 * KEY INSIGHT
 *   The iterator hides HOW elements are fetched. hasNext() calls the API
 *   only when the current page is used up, so memory holds one page and a
 *   caller that stops early never pays for the pages it did not read.
 *   Implementing java.util.Iterator and returning it from an Iterable is
 *   what makes for-each work.
 *
 * ROLES IN THIS CODE
 *   Iterator<T> (java.util)    Iterator interface
 *   PagedIterator              ConcreteIterator - cursor + current page
 *   PageSource / OrdersApi     the aggregate, reachable only page by page
 *   allOrders()                Iterable, so for-each works
 *
 * INTERVIEW FOLLOW-UPS
 *   - Why `while`, not `if`, in hasNext()? An API may return an empty page
 *     that still has a next cursor.
 *   - Seen in: AWS SDK paginators, Spring Data Slice, JDBC ResultSet,
 *     Kafka consumer poll loops.
 *
 * RUN
 *   5 cases: 7 orders in 3 calls, stop early after 1 call, exactly 2 full
 *   pages, empty API, next() past the end.
 */

import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;

/** One page of results; nextCursor is null on the last page. */
record Page<T>(List<T> items, Integer nextCursor) {
}

interface PageSource<T> {
    Page<T> fetch(int cursor, int limit);
}

/** Stand-in for the remote orders service; counts how often it is called. */
class OrdersApi implements PageSource<String> {
    private final List<String> rows = new ArrayList<>();
    int calls;

    OrdersApi(int orderCount) {
        for (int i = 1; i <= orderCount; i++) {
            rows.add("OD-" + i);
        }
    }

    public Page<String> fetch(int cursor, int limit) {
        calls++;
        int end = Math.min(cursor + limit, rows.size());
        return new Page<>(rows.subList(cursor, end), end < rows.size() ? end : null);
    }
}

class PagedIterator<T> implements Iterator<T> {
    private final PageSource<T> source;
    private final int pageSize;
    private Iterator<T> current = Collections.emptyIterator();
    private Integer nextCursor = 0; // null = no more pages

    PagedIterator(PageSource<T> source, int pageSize) {
        this.source = source;
        this.pageSize = pageSize;
    }

    @Override
    public boolean hasNext() {
        while (!current.hasNext() && nextCursor != null) { // fetch lazily, one page at a time
            Page<T> page = source.fetch(nextCursor, pageSize);
            current = page.items().iterator();
            nextCursor = page.nextCursor();
        }
        return current.hasNext();
    }

    @Override
    public T next() {
        if (!hasNext()) {
            throw new NoSuchElementException("no more orders");
        }
        return current.next();
    }
}

class IteratorPatternExample {

    static Iterable<String> allOrders(PageSource<String> api, int pageSize) {
        return () -> new PagedIterator<>(api, pageSize);
    }

    public static void main(String[] args) {
        // Case 1: typical. 7 orders, pages of 3 -> 3 API calls, plain for-each.
        OrdersApi api = new OrdersApi(7);
        List<String> exported = new ArrayList<>();
        for (String order : allOrders(api, 3)) {
            exported.add(order);
        }
        print("case 1a exported", exported, "[OD-1, OD-2, OD-3, OD-4, OD-5, OD-6, OD-7]");
        print("case 1b calls   ", api.calls, 3);

        // Case 2: lazy. Stop after 2 orders -> only the first page was fetched.
        OrdersApi preview = new OrdersApi(7);
        Iterator<String> it = allOrders(preview, 3).iterator();
        print("case 2a first 2 ", it.next() + " " + it.next(), "OD-1 OD-2");
        print("case 2b calls   ", preview.calls, 1);

        // Case 3: edge. 6 orders = 2 full pages; the null cursor avoids a 3rd call.
        OrdersApi six = new OrdersApi(6);
        allOrders(six, 3).forEach(order -> { });
        print("case 3 calls    ", six.calls, 2);

        // Case 4-5: edge. No orders at all, then reading past the end.
        Iterator<String> none = allOrders(new OrdersApi(0), 3).iterator();
        print("case 4 empty    ", none.hasNext(), false);
        String outcome;
        try {
            outcome = none.next();
        } catch (NoSuchElementException e) {
            outcome = e.getMessage();
        }
        print("case 5 past end ", outcome, "no more orders");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Command - shopping cart undo / redo               Behavioral | Easy   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   The cart page has "Undo" after every action: add item, remove item,
 *   apply coupon. Users undo several steps and redo them; a fresh action
 *   after an undo must wipe the redo list. The undo button cannot contain
 *   a switch over every possible action.
 *
 * KEY INSIGHT
 *   Each action becomes an object that knows how to execute() AND undo()
 *   itself, remembering whatever it needs to reverse (the removed price,
 *   the old coupon). The history only pushes and pops commands; it never
 *   knows what they do. A new action is a new class, not a new branch.
 *
 * ROLES IN THIS CODE
 *   CartCommand                       Command
 *   AddItem, RemoveItem, ApplyCoupon  ConcreteCommand
 *   Cart                              Receiver
 *   CartHistory                       Invoker - undo and redo stacks
 *
 * INTERVIEW FOLLOW-UPS
 *   - Command vs Memento for undo: Command stores HOW to reverse a change,
 *     Memento stores a snapshot (B03_MementoDesignPattern).
 *   - Group several commands into one undo step with a MacroCommand.
 *   - Seen in: Runnable/Callable queued on an executor, job queues, Redux
 *     actions, database redo logs.
 *
 * RUN
 *   6 cases: three actions, undo twice, redo, new action clears redo,
 *   undo a remove, undo past the start.
 */

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.Map;

/** Receiver: the cart itself knows nothing about undo. */
class Cart {
    private final Map<String, Integer> lines = new LinkedHashMap<>(); // product -> price
    private int couponOff;

    void add(String product, int priceRs) {
        lines.put(product, priceRs);
    }

    Integer remove(String product) {
        return lines.remove(product);
    }

    int couponOff() {
        return couponOff;
    }

    void setCouponOff(int rs) {
        couponOff = rs;
    }

    @Override
    public String toString() {
        int total = lines.values().stream().mapToInt(Integer::intValue).sum() - couponOff;
        return lines.keySet() + " Rs " + total;
    }
}

interface CartCommand {
    void execute();

    void undo();
}

class AddItem implements CartCommand {
    private final Cart cart;
    private final String product;
    private final int priceRs;

    AddItem(Cart cart, String product, int priceRs) {
        this.cart = cart;
        this.product = product;
        this.priceRs = priceRs;
    }

    public void execute() {
        cart.add(product, priceRs);
    }

    public void undo() {
        cart.remove(product);
    }
}

class RemoveItem implements CartCommand {
    private final Cart cart;
    private final String product;
    private Integer removedPrice; // remembered so undo can put it back

    RemoveItem(Cart cart, String product) {
        this.cart = cart;
        this.product = product;
    }

    public void execute() {
        removedPrice = cart.remove(product);
    }

    public void undo() {
        if (removedPrice != null) {
            cart.add(product, removedPrice);
        }
    }
}

class ApplyCoupon implements CartCommand {
    private final Cart cart;
    private final int offRs;
    private int previousOff;

    ApplyCoupon(Cart cart, int offRs) {
        this.cart = cart;
        this.offRs = offRs;
    }

    public void execute() {
        previousOff = cart.couponOff();
        cart.setCouponOff(offRs);
    }

    public void undo() {
        cart.setCouponOff(previousOff);
    }
}

/** Invoker: pushes and pops commands, never looks inside them. */
class CartHistory {
    private final Deque<CartCommand> undoStack = new ArrayDeque<>();
    private final Deque<CartCommand> redoStack = new ArrayDeque<>();

    void run(CartCommand command) {
        command.execute();
        undoStack.push(command);
        redoStack.clear(); // a new action invalidates the redo path
    }

    boolean undo() {
        if (undoStack.isEmpty()) {
            return false;
        }
        CartCommand command = undoStack.pop();
        command.undo();
        redoStack.push(command);
        return true;
    }

    boolean redo() {
        if (redoStack.isEmpty()) {
            return false;
        }
        CartCommand command = redoStack.pop();
        command.execute();
        undoStack.push(command);
        return true;
    }
}

class CommandDesignPattern {

    public static void main(String[] args) {
        Cart cart = new Cart();
        CartHistory history = new CartHistory();

        // Case 1: typical. Three actions.
        history.run(new AddItem(cart, "Shoes", 3000));
        history.run(new AddItem(cart, "Socks", 300));
        history.run(new ApplyCoupon(cart, 500));
        print("case 1 three actions", cart, "[Shoes, Socks] Rs 2800");

        // Case 2: undo twice - the coupon goes, then the socks.
        history.undo();
        history.undo();
        print("case 2 undo twice   ", cart, "[Shoes] Rs 3000");

        // Case 3: redo brings the socks back.
        history.redo();
        print("case 3 redo         ", cart, "[Shoes, Socks] Rs 3300");

        // Case 4: tricky. A new action after an undo clears the redo stack,
        // so the undone coupon can no longer be redone.
        history.run(new RemoveItem(cart, "Shoes"));
        print("case 4a remove shoes", cart, "[Socks] Rs 300");
        print("case 4b redo coupon ", history.redo(), false);

        // Case 5: undoing a remove restores the item with its price.
        history.undo();
        print("case 5 undo remove  ", cart, "[Socks, Shoes] Rs 3300");

        // Case 6: edge. Undo back to an empty cart, then one undo too many.
        print("case 6a undo x3     ", history.undo() + " " + history.undo() + " "
                + history.undo(), "true true false");
        print("case 6b empty cart  ", cart, "[] Rs 0");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Memento - text editor undo                        Behavioral | Easy
 * =====================================================================
 *
 * PROBLEM
 *   An editor (or a form, or a game) must go back to an earlier saved
 *   state on Ctrl+Z. The undo history has to keep those states without
 *   reaching into the editor's private fields.
 *
 * KEY INSIGHT
 *   The editor (Originator) makes a sealed snapshot of itself; the history
 *   (Caretaker) stores snapshots but never reads them. Only the editor can
 *   restore from one. A stack gives last-in-first-out undo for free.
 *
 * ROLES IN THIS CODE
 *   EditorMemento   Memento - immutable snapshot
 *   Editor          Originator - save() and restore()
 *   History         Caretaker - a Stack of mementos, never inspected
 *
 * INTERVIEW FOLLOW-UPS
 *   - Memento vs Command for undo: Memento stores WHAT the state was,
 *     Command stores HOW to reverse a change (B02_CommandDesignPattern).
 *   - Redo: push undone snapshots onto a second stack; clear it on a new
 *     edit. Bound memory by capping the stack.
 *
 * RUN
 *   3 cases: undo twice, undo on an empty history, restore one snapshot.
 */

import java.util.Stack;

/** Memento: an immutable snapshot of the Editor's content. The getter is
 *  public only to keep this demo short; see KEY INSIGHT for the real fix. */
class EditorMemento {
    private final String content;

    public EditorMemento(String content) {
        this.content = content;
    }

    public String getContent() {
        return content;
    }
}

/** Originator: the object whose state we snapshot and restore. */
class Editor {
    private String content = "";

    public void type(String newText) {
        this.content = newText;
    }

    public String getContent() {
        return content;
    }

    /** Wraps the current state in a memento the caretaker can park. */
    public EditorMemento save() {
        return new EditorMemento(content);
    }

    /** Only the originator understands how to read a memento back. */
    public void restore(EditorMemento editorMemento) {
        this.content = editorMemento.getContent();
    }
}

/** Caretaker: stores mementos and, by convention, never looks inside them. */
class History {
    private final Stack<EditorMemento> history = new Stack<>();

    public void save(Editor editor) {
        history.push(editor.save());
    }

    /** Returns false when there is nothing left to undo, so main can assert. */
    public boolean undo(Editor editor) {
        if (history.isEmpty()) {
            return false;
        }
        editor.restore(history.pop());
        return true;
    }

    public int size() {
        return history.size();
    }
}

class MementoDesignPattern {

    public static void main(String[] args) {
        // Case 1: typical undo chain - save after each committed edit.
        Editor editor = new Editor();
        History history = new History();

        editor.type("Version 1");
        history.save(editor);
        editor.type("Version 2");
        history.save(editor);
        editor.type("Version 3"); // not saved: this is the "unsaved" edit

        print("case 1a current  ", editor.getContent(), "Version 3");
        history.undo(editor);
        print("case 1b undo once", editor.getContent(), "Version 2");
        history.undo(editor);
        print("case 1c undo twice", editor.getContent(), "Version 1");

        // Case 2: edge - undo with an empty history must be a safe no-op.
        print("case 2a stack size", history.size(), 0);
        print("case 2b undo empty", history.undo(editor), false);
        print("case 2c unchanged ", editor.getContent(), "Version 1");

        // Case 3: tricky - a memento is a value, later typing cannot mutate it.
        Editor draft = new Editor();
        draft.type("snapshot me");
        EditorMemento snapshot = draft.save();
        draft.type("overwritten");
        print("case 3a after edit", draft.getContent(), "overwritten");
        draft.restore(snapshot);
        print("case 3b restored  ", draft.getContent(), "snapshot me");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  State - e-commerce order lifecycle        Behavioral | Medium   MUST-KNOW
 * =====================================================================
 *
 * PROBLEM
 *   An order moves NEW -> PAID -> SHIPPED -> DELIVERED and can be cancelled
 *   only before shipping (with a refund once paid). Written as
 *   "if (status == ...)" in every method, each new state means editing
 *   every branch.
 *
 * KEY INSIGHT
 *   Each state is a class that knows its own rules AND names its successor
 *   via order.setState(). The Order just forwards next()/cancel() to its
 *   current state. A RETURNED state is one new class; an illegal move is a
 *   state that simply does not transition.
 *
 * ROLES IN THIS CODE
 *   OrderState                      State
 *   NewState, PaidState, Shipped..  ConcreteState (Delivered and Cancelled
 *                                   are terminal)
 *   Order                           Context
 *
 * INTERVIEW FOLLOW-UPS
 *   - State vs Strategy: same shape; the client picks a strategy, a state
 *     picks its own successor.
 *   - Persist the state NAME in the DB and rebuild the object on load.
 *   - States hold no data here, so enum constants would avoid allocating
 *     one per transition.
 *
 * RUN
 *   3 cases: full happy path, cancel from NEW, cancel from PAID vs SHIPPED.
 */

/** State: every lifecycle step implements this. */
interface OrderState {
    /** Advance to the next legal state, or refuse if terminal. */
    void next(Order order);

    /** Cancel if this state allows it, or refuse. */
    void cancel(Order order);

    /** Short stable name, used for asserting and for persistence. */
    String name();

    default void printState() {
        System.out.println("  [status] order is " + name());
    }
}

class NewState implements OrderState {

    @Override
    public void next(Order order) {
        System.out.println("  Payment received. Moving to PAID.");
        order.setState(new PaidState());
    }

    @Override
    public void cancel(Order order) {
        System.out.println("  Order cancelled before payment.");
        order.setState(new CancelledState());
    }

    @Override
    public String name() {
        return "NEW";
    }
}

class PaidState implements OrderState {

    @Override
    public void next(Order order) {
        System.out.println("  Order shipped. Moving to SHIPPED.");
        order.setState(new ShippedState());
    }

    @Override
    public void cancel(Order order) {
        // Money already taken, so cancelling here has a side effect.
        System.out.println("  Refund initiated. Order cancelled.");
        order.setState(new CancelledState());
    }

    @Override
    public String name() {
        return "PAID";
    }
}

class ShippedState implements OrderState {

    @Override
    public void next(Order order) {
        System.out.println("  Delivered to customer. Moving to DELIVERED.");
        order.setState(new DeliveredState());
    }

    @Override
    public void cancel(Order order) {
        // Refusing = doing nothing. No setState call, so the state stands.
        System.out.println("  Cannot cancel: parcel is already in transit.");
    }

    @Override
    public String name() {
        return "SHIPPED";
    }
}

/** Terminal state: refuses every transition. */
class DeliveredState implements OrderState {

    @Override
    public void next(Order order) {
        System.out.println("  Already delivered. No next state.");
    }

    @Override
    public void cancel(Order order) {
        System.out.println("  Cannot cancel: order already delivered.");
    }

    @Override
    public String name() {
        return "DELIVERED";
    }
}

/** Terminal state: refuses every transition. */
class CancelledState implements OrderState {

    @Override
    public void next(Order order) {
        System.out.println("  Order is cancelled. No further transitions.");
    }

    @Override
    public void cancel(Order order) {
        System.out.println("  Order is already cancelled.");
    }

    @Override
    public String name() {
        return "CANCELLED";
    }
}

/** Context: owns the current state and delegates every request to it. */
class Order {
    private OrderState orderState = new NewState();

    /** Called by the states themselves - this is where transitions land. */
    public void setState(OrderState state) {
        orderState = state;
    }

    public void next() {
        orderState.next(this);
    }

    public void cancel() {
        orderState.cancel(this);
    }

    public void printStatus() {
        orderState.printState();
    }

    public String currentState() {
        return orderState.name();
    }
}

class StateDesignPatternExample {

    public static void main(String[] args) {
        // Case 1: typical - walk the whole happy path, then try to cancel.
        System.out.println("case 1: happy path");
        Order order = new Order();
        print("  1a start      ", order.currentState(), "NEW");
        order.next();
        print("  1b after pay  ", order.currentState(), "PAID");
        order.next();
        print("  1c after ship ", order.currentState(), "SHIPPED");
        order.next();
        print("  1d delivered  ", order.currentState(), "DELIVERED");
        order.cancel(); // refused
        print("  1e cancel late", order.currentState(), "DELIVERED");

        // Case 2: edge - cancel straight from NEW, then a terminal state
        // must ignore both next() and a second cancel().
        System.out.println("case 2: cancel before payment");
        Order early = new Order();
        early.cancel();
        print("  2a cancelled  ", early.currentState(), "CANCELLED");
        early.next();
        print("  2b next after ", early.currentState(), "CANCELLED");
        early.cancel();
        print("  2c cancel twice", early.currentState(), "CANCELLED");

        // Case 3: tricky - cancel IS allowed from PAID (refund) but not
        // from SHIPPED, so the same call has two different outcomes.
        System.out.println("case 3: cancel from PAID vs from SHIPPED");
        Order paid = new Order();
        paid.next();
        paid.cancel();
        print("  3a paid-cancel", paid.currentState(), "CANCELLED");

        Order shipped = new Order();
        shipped.next();
        shipped.next();
        shipped.cancel();
        shipped.printStatus();
        print("  3b ship-cancel", shipped.currentState(), "SHIPPED");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Chain of Responsibility - ATM cash dispenser      Behavioral | Medium
 * =====================================================================
 *
 * PROBLEM
 *   An ATM must pay Rs 8,700 with the fewest notes from 2000, 500, 200 and
 *   100 cassettes, and refuse amounts it cannot pay. Adding a Rs 50
 *   cassette should not mean rewriting one big if/else.
 *
 * KEY INSIGHT
 *   Each handler pays as many of its own notes as fit and forwards the
 *   remainder to the next (2000 -> 500 -> 200 -> 100) - partial handling,
 *   not all-or-nothing. Ordered high to low, that greedy step gives the
 *   fewest notes: the ordering IS the algorithm.
 *
 * ROLES IN THIS CODE
 *   DispenseChain                Handler - holds nextChain, shared forward()
 *   Rupee2000/500/200/100..      ConcreteHandler - one denomination each
 *   ChainOfResponsibilityExample Client - wires the chain, calls its head
 *
 * INTERVIEW FOLLOW-UPS
 *   - A cassette runs out: dispense min(needed, stock) and forward the rest;
 *     greedy then stops being optimal.
 *   - CoR vs Decorator: same linked shape; a decorator always calls the
 *     next link, a chain link may stop the request.
 *   - Seen in: servlet filters, Spring Security's filter chain, support
 *     ticket escalation, approval workflows by amount.
 *
 * RUN
 *   4 cases: 8700, 2500, 100, and 50 / 0 rejected.
 */

import java.util.ArrayList;
import java.util.List;

/** Handler: knows only its successor, never the whole chain. */
abstract class DispenseChain {
    protected DispenseChain nextChain;

    public void setDispenseChain(DispenseChain nextChain) {
        this.nextChain = nextChain;
    }

    /** Handle what this link can and forward the rest; record the plan in notes. */
    public abstract void dispense(int amount, List<String> notes);

    /**
     * Shared tail step. Without the else-branch a leftover amount at the end
     * of the chain would disappear silently, which is the classic CoR trap.
     */
    protected void forward(int amount, List<String> notes) {
        if (amount == 0) {
            return;
        }
        if (nextChain != null) {
            nextChain.dispense(amount, notes);
        } else {
            System.out.println("  WARNING: cannot dispense remaining " + amount);
            notes.add("unserved " + amount);
        }
    }
}

class Rupee2000Dispenser extends DispenseChain {

    @Override
    public void dispense(int amount, List<String> notes) {
        if (amount >= 2000) {
            int num = amount / 2000;
            System.out.println("  Dispensing " + num + " x 2000 notes");
            notes.add(num + " x 2000");
            forward(amount % 2000, notes);
        } else {
            forward(amount, notes); // nothing for this link, push it down
        }
    }
}

class Rupee500Dispenser extends DispenseChain {

    @Override
    public void dispense(int amount, List<String> notes) {
        if (amount >= 500) {
            int num = amount / 500;
            System.out.println("  Dispensing " + num + " x 500 notes");
            notes.add(num + " x 500");
            forward(amount % 500, notes);
        } else {
            forward(amount, notes);
        }
    }
}

class Rupee200Dispenser extends DispenseChain {

    @Override
    public void dispense(int amount, List<String> notes) {
        if (amount >= 200) {
            int num = amount / 200;
            System.out.println("  Dispensing " + num + " x 200 notes");
            notes.add(num + " x 200");
            forward(amount % 200, notes);
        } else {
            forward(amount, notes);
        }
    }
}

class Rupee100Dispenser extends DispenseChain {

    @Override
    public void dispense(int amount, List<String> notes) {
        if (amount >= 100) {
            int num = amount / 100;
            System.out.println("  Dispensing " + num + " x 100 notes");
            notes.add(num + " x 100");
            forward(amount % 100, notes);
        } else {
            forward(amount, notes);
        }
    }
}

/** Client: builds the chain once, then talks only to its head. */
class ChainOfResponsibilityExample {

    private final DispenseChain dispenseChain;

    public ChainOfResponsibilityExample() {
        Rupee2000Dispenser rupee2000Dispenser = new Rupee2000Dispenser();
        Rupee500Dispenser rupee500Dispenser = new Rupee500Dispenser();
        Rupee200Dispenser rupee200Dispenser = new Rupee200Dispenser();
        Rupee100Dispenser rupee100Dispenser = new Rupee100Dispenser();

        // Descending order is what makes the greedy split use fewest notes.
        rupee2000Dispenser.setDispenseChain(rupee500Dispenser);
        rupee500Dispenser.setDispenseChain(rupee200Dispenser);
        rupee200Dispenser.setDispenseChain(rupee100Dispenser);

        this.dispenseChain = rupee2000Dispenser;
    }

    /** Returns the note plan, or an empty list when the request is rejected. */
    public List<String> dispenseCash(int amount) {
        List<String> notes = new ArrayList<>();
        if (amount <= 0) {
            System.out.println("  Amount must be positive.");
            return notes;
        }
        if (amount % 100 != 0) {
            System.out.println("  Amount should be a multiple of 100.");
            return notes;
        }
        dispenseChain.dispense(amount, notes);
        return notes;
    }

    public static void main(String[] args) {
        ChainOfResponsibilityExample atm = new ChainOfResponsibilityExample();

        // Case 1: typical - three of the four links contribute, and the chain stops
        // early once the remainder hits 0, so the 100 link is never reached.
        System.out.println("case 1: 8700");
        print("  actual", atm.dispenseCash(8700), "[4 x 2000, 1 x 500, 1 x 200]");

        // Case 2: the 200 and 100 links forward without handling.
        System.out.println("case 2: 2500");
        print("  actual", atm.dispenseCash(2500), "[1 x 2000, 1 x 500]");

        // Case 3: edge - the smallest servable amount reaches the last link.
        System.out.println("case 3: 100");
        print("  actual", atm.dispenseCash(100), "[1 x 100]");

        // Case 4: edge - rejected before the chain is ever entered.
        System.out.println("case 4: 50 and 0 are rejected");
        print("  actual 50", atm.dispenseCash(50), "[]");
        print("  actual 0 ", atm.dispenseCash(0), "[]");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Mediator - chat room                              Behavioral | Medium
 * =====================================================================
 *
 * PROBLEM
 *   In a group chat every member's message must reach everyone else. If
 *   each user held references to all other users, n users would need
 *   n*(n-1) links, and "mute" or "direct message" would touch every user.
 *
 * KEY INSIGHT
 *   No user references another user. Everyone talks only to the room
 *   (mediator), which owns the routing rule - here, everyone except the
 *   sender. Links drop from O(n^2) to O(n), and new rules change one class.
 *
 * ROLES IN THIS CODE
 *   ChatMediator        Mediator - addUser, removeUser, sendMessage
 *   ChatMediatorImpl    ConcreteMediator - the roster and the routing rule
 *   User, UserImpl      Colleague - knows the room, not the other users
 *
 * INTERVIEW FOLLOW-UPS
 *   - Mediator vs Observer: Observer is one-way broadcast from a subject;
 *     a mediator routes many-to-many and holds the rules.
 *   - Avoid a god object: one mediator per room or per concern.
 *   - At scale the room becomes a broker topic (Kafka, Redis pub/sub).
 *
 * RUN
 *   3 cases: broadcast in a 3-person room, single member, a member leaves.
 */

import java.util.ArrayList;
import java.util.List;

/** Mediator: the only thing colleagues are allowed to know. */
interface ChatMediator {
    void sendMessage(String message, User sender);

    void addUser(User user);

    void removeUser(User user);
}

/** ConcreteMediator: owns the roster and the routing rule. */
class ChatMediatorImpl implements ChatMediator {

    private final List<User> userList = new ArrayList<>();

    @Override
    public void sendMessage(String message, User sender) {
        for (User user : userList) {
            // The routing rule lives here and nowhere else: do not echo
            // the message back to whoever sent it.
            if (user != sender) {
                user.receiveMessage(sender.getName() + ": " + message);
            }
        }
    }

    @Override
    public void addUser(User user) {
        userList.add(user);
    }

    @Override
    public void removeUser(User user) {
        userList.remove(user);
    }
}

/** Colleague: holds the mediator, never another colleague. */
abstract class User {
    protected final ChatMediator chatMediator;
    protected final String name;

    public User(ChatMediator chatMediator, String name) {
        this.chatMediator = chatMediator;
        this.name = name;
    }

    public String getName() {
        return name;
    }

    abstract void sendMessage(String message);

    abstract void receiveMessage(String message);
}

class UserImpl extends User {

    /** Kept so main can assert what actually arrived. */
    private final List<String> inbox = new ArrayList<>();

    public UserImpl(ChatMediator chatMediator, String name) {
        super(chatMediator, name);
    }

    @Override
    void sendMessage(String message) {
        System.out.println("  " + name + " sends: " + message);
        chatMediator.sendMessage(message, this); // hand off, do not fan out
    }

    @Override
    void receiveMessage(String message) {
        System.out.println("    " + name + " received -> " + message);
        inbox.add(message);
    }

    public List<String> getInbox() {
        return inbox;
    }
}

class MediatorDesignPatternExample {

    public static void main(String[] args) {
        // Case 1: typical - one sender, two receivers, no self-echo.
        System.out.println("case 1: broadcast in a 3-person room");
        ChatMediator room = new ChatMediatorImpl();
        UserImpl ravi = new UserImpl(room, "Ravi");
        UserImpl varma = new UserImpl(room, "Varma");
        UserImpl kiran = new UserImpl(room, "Kiran");
        room.addUser(ravi);
        room.addUser(varma);
        room.addUser(kiran);

        ravi.sendMessage("Hi all");
        print("  1a varma inbox", varma.getInbox(), "[Ravi: Hi all]");
        print("  1b kiran inbox", kiran.getInbox(), "[Ravi: Hi all]");
        print("  1c ravi  inbox", ravi.getInbox(), "[]");

        // Case 2: edge - the only member of a room talks to nobody, and
        // nothing blows up because the sender knows no receivers.
        System.out.println("case 2: single-member room");
        ChatMediator empty = new ChatMediatorImpl();
        UserImpl solo = new UserImpl(empty, "Solo");
        empty.addUser(solo);
        solo.sendMessage("anyone here?");
        print("  2a solo inbox ", solo.getInbox(), "[]");

        // Case 3: tricky - Kiran leaves. Only the mediator's roster changes;
        // Ravi's code is identical, which is the whole point of the pattern.
        System.out.println("case 3: a member leaves");
        room.removeUser(kiran);
        ravi.sendMessage("second message");
        print("  3a varma inbox", varma.getInbox(),
                "[Ravi: Hi all, Ravi: second message]");
        print("  3b kiran inbox", kiran.getInbox(), "[Ravi: Hi all]");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Visitor - tax, shipping, points over cart lines   Behavioral | Hard
 * =====================================================================
 *
 * PROBLEM
 *   A cart holds physical goods, e-books and gift cards. Tax, shipping and
 *   loyalty points each work differently per line type, and finance keeps
 *   asking for new calculations. Adding taxFor(), shippingFor(),
 *   pointsFor()... to every line class mixes unrelated rules into data.
 *
 * KEY INSIGHT
 *   Each calculation becomes one visitor class with a visit() per line
 *   type. A line's accept(v) calls v.visit(this), and because `this` has
 *   the line's real type, Java picks the right overload: double dispatch.
 *   New calculation = new visitor, line classes untouched. The price: a new
 *   LINE TYPE means editing every visitor.
 *
 * ROLES IN THIS CODE
 *   CartLine                              Element - accept(visitor)
 *   PhysicalItem, DigitalItem, GiftCard   ConcreteElement (records)
 *   LineVisitor                           Visitor
 *   TaxVisitor, ShippingVisitor, Points.. ConcreteVisitor
 *
 * INTERVIEW FOLLOW-UPS
 *   - Java 21: a sealed interface + switch with record patterns does the
 *     same job without accept() (case 4), and the compiler flags a missed
 *     type.
 *   - Seen in: javax.lang.model ElementVisitor, java.nio.file.FileVisitor,
 *     compiler ASTs.
 *
 * RUN
 *   5 cases: tax, shipping, a new points visitor, same tax via switch,
 *   empty cart. Tax rates here are illustrative, not legal advice.
 */

import java.util.List;

sealed interface CartLine permits PhysicalItem, DigitalItem, GiftCard {
    int accept(LineVisitor visitor);
}

record PhysicalItem(String name, int priceRs, double weightKg) implements CartLine {
    public int accept(LineVisitor visitor) {
        return visitor.visit(this);
    }
}

record DigitalItem(String name, int priceRs) implements CartLine {
    public int accept(LineVisitor visitor) {
        return visitor.visit(this);
    }
}

record GiftCard(int valueRs) implements CartLine {
    public int accept(LineVisitor visitor) {
        return visitor.visit(this);
    }
}

interface LineVisitor {
    int visit(PhysicalItem item);

    int visit(DigitalItem item);

    int visit(GiftCard card);
}

class TaxVisitor implements LineVisitor {
    public int visit(PhysicalItem item) {
        return item.priceRs() * 12 / 100;
    }

    public int visit(DigitalItem item) {
        return item.priceRs() * 18 / 100;
    }

    public int visit(GiftCard card) {
        return 0; // taxed when it is spent, not when it is bought
    }
}

class ShippingVisitor implements LineVisitor {
    public int visit(PhysicalItem item) {
        return 40 * (int) Math.ceil(item.weightKg()); // Rs 40 per started kg
    }

    public int visit(DigitalItem item) {
        return 0;
    }

    public int visit(GiftCard card) {
        return 0; // emailed
    }
}

/** Added later by marketing - not one line of the cart classes changed. */
class PointsVisitor implements LineVisitor {
    public int visit(PhysicalItem item) {
        return item.priceRs() / 100;
    }

    public int visit(DigitalItem item) {
        return item.priceRs() / 100;
    }

    public int visit(GiftCard card) {
        return 0;
    }
}

class VisitorDesignPatternDemo {

    static int total(List<CartLine> cart, LineVisitor visitor) {
        return cart.stream().mapToInt(line -> line.accept(visitor)).sum();
    }

    /** The Java 21 alternative: no accept(), the switch must cover every type. */
    static int taxBySwitch(CartLine line) {
        return switch (line) {
            case PhysicalItem p -> p.priceRs() * 12 / 100;
            case DigitalItem d -> d.priceRs() * 18 / 100;
            case GiftCard g -> 0;
        };
    }

    public static void main(String[] args) {
        List<CartLine> cart = List.of(
                new PhysicalItem("Shoes", 3000, 1.2),
                new PhysicalItem("Novel", 400, 0.3),
                new DigitalItem("E-book", 200),
                new GiftCard(1000));

        // 360 + 48 + 36 + 0
        print("case 1 tax       ", total(cart, new TaxVisitor()), 444);
        // 2 kg x 40 + 1 kg x 40
        print("case 2 shipping  ", total(cart, new ShippingVisitor()), 120);
        // 30 + 4 + 2 + 0
        print("case 3 points    ", total(cart, new PointsVisitor()), 36);
        print("case 4 tax switch", cart.stream().mapToInt(VisitorDesignPatternDemo::taxBySwitch)
                .sum(), 444);
        print("case 5 empty cart", total(List.of(), new TaxVisitor()), 0);
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

/*
 * =====================================================================
 *  Interpreter - coupon eligibility rules            Behavioral | Hard
 * =====================================================================
 *
 * PROBLEM
 *   Marketing writes coupon rules in an admin panel, for example
 *     cartTotal >= 1000 AND category = ELECTRONICS OR tier = GOLD
 *   and expects them live without a code deploy. Checkout must decide, per
 *   cart, whether the rule matches.
 *
 * KEY INSIGHT
 *   Turn the rule text into a tree of small objects, one class per grammar
 *   element: Compare is a leaf, And / Or hold two sub-rules. matches() on a
 *   node asks its children and combines the answers, so evaluation is plain
 *   recursion. Splitting on OR first and AND second makes AND bind tighter,
 *   as in SQL.
 *
 * ROLES IN THIS CODE
 *   Rule                  AbstractExpression
 *   Compare               TerminalExpression (field op value)
 *   And, Or               NonterminalExpression
 *   Map<String, String>   Context (the cart's facts)
 *   RuleParser            builds the tree (not part of the GoF roles)
 *
 * INTERVIEW FOLLOW-UPS
 *   - When it stops scaling: parentheses, NOT, precedence levels -> use a
 *     real parser (ANTLR) or an engine (Drools, Spring SpEL).
 *   - Seen in: Spring SpEL, regex engines, SQL WHERE clauses, feature-flag
 *     targeting rules.
 *
 * RUN
 *   6 cases: the parsed tree, eligible by total + category, eligible by
 *   GOLD only, not eligible, missing field, malformed rule.
 */

import java.util.Map;

interface Rule {
    boolean matches(Map<String, String> cart);
}

record Compare(String field, String op, String value) implements Rule {
    public boolean matches(Map<String, String> cart) {
        String actual = cart.get(field);
        if (actual == null) {
            return false; // unknown fact never matches
        }
        if (op.equals("=")) {
            return actual.equals(value);
        }
        int left = Integer.parseInt(actual);
        int right = Integer.parseInt(value);
        return switch (op) {
            case ">=" -> left >= right;
            case "<=" -> left <= right;
            case ">" -> left > right;
            case "<" -> left < right;
            default -> throw new IllegalArgumentException("unknown operator " + op);
        };
    }

    @Override
    public String toString() {
        return field + " " + op + " " + value;
    }
}

record And(Rule left, Rule right) implements Rule {
    public boolean matches(Map<String, String> cart) {
        return left.matches(cart) && right.matches(cart);
    }

    @Override
    public String toString() {
        return "(" + left + " AND " + right + ")";
    }
}

record Or(Rule left, Rule right) implements Rule {
    public boolean matches(Map<String, String> cart) {
        return left.matches(cart) || right.matches(cart);
    }

    @Override
    public String toString() {
        return "(" + left + " OR " + right + ")";
    }
}

class RuleParser {
    /** OR is split first, so AND groups bind tighter. */
    static Rule parse(String text) {
        Rule rule = null;
        for (String orPart : text.split(" OR ")) {
            Rule andRule = null;
            for (String condition : orPart.split(" AND ")) {
                String[] t = condition.trim().split("\\s+");
                if (t.length != 3) {
                    throw new IllegalArgumentException("bad condition '" + condition.trim() + "'");
                }
                Rule compare = new Compare(t[0], t[1], t[2]);
                andRule = andRule == null ? compare : new And(andRule, compare);
            }
            rule = rule == null ? andRule : new Or(rule, andRule);
        }
        return rule;
    }
}

class InterpreterPatternExample {

    public static void main(String[] args) {
        Rule rule = RuleParser.parse("cartTotal >= 1000 AND category = ELECTRONICS OR tier = GOLD");
        print("case 1 tree        ", rule,
                "((cartTotal >= 1000 AND category = ELECTRONICS) OR tier = GOLD)");

        // Case 2-4: one parsed rule, evaluated against three different carts.
        print("case 2 big gadget  ", rule.matches(Map.of(
                "cartTotal", "1500", "category", "ELECTRONICS", "tier", "SILVER")), true);
        print("case 3 gold member ", rule.matches(Map.of(
                "cartTotal", "400", "category", "BOOKS", "tier", "GOLD")), true);
        print("case 4 big books   ", rule.matches(Map.of(
                "cartTotal", "1500", "category", "BOOKS", "tier", "SILVER")), false);

        // Case 5: edge. A guest has no tier at all; the missing fact is just false.
        print("case 5 guest       ", rule.matches(Map.of(
                "cartTotal", "900", "category", "ELECTRONICS")), false);

        // Case 6: a typo in the admin panel is caught when the rule is saved.
        String outcome;
        try {
            RuleParser.parse("cartTotal >= AND tier = GOLD");
            outcome = "parsed";
        } catch (IllegalArgumentException e) {
            outcome = e.getMessage();
        }
        print("case 6 bad rule    ", outcome, "bad condition 'cartTotal >='");
    }

    private static void print(String label, Object actual, Object expected) {
        System.out.println(label + ": " + actual + "   expected " + expected);
    }
}

