/*
 * =====================================================================
 *  ErrorResponse -- the error payload DTO          Spring Boot: orders service
 * =====================================================================
 *
 * ROLE IN THE PROJECT
 *   Every failure this service returns is serialised from this one class, so a client
 *   parses the same four fields whether the cause was a validation failure, a missing
 *   order, or an unexpected crash. It is the "error contract" of the API.
 *
 *   Who builds it: GlobalExceptionHandler, and only GlobalExceptionHandler. Controllers
 *   never construct it; they throw, and the advice turns the throw into this object.
 *
 *   The four fields and why each earns its place:
 *     status   - the numeric HTTP status, duplicated in the body so clients that only
 *                log the body still know what happened.
 *     message  - one human sentence ("Validation failed", "order not found with id 2").
 *     errors   - the per-field detail list; empty for failures with no field breakdown.
 *     path     - the request URI, so a log line identifies the call without correlation.
 *
 * WHAT TO NOTICE
 *   - Lombok @Getter/@Setter generate the accessors. Jackson needs the getters to
 *     serialise; the setters exist only so tests can deserialise the JSON back.
 *   - There is no no-arg constructor. Jackson can still write this object out, but it
 *     cannot read one back in without @JsonCreator or a default constructor. A test that
 *     does mapper.readValue(body, ErrorResponse.class) will fail for exactly that reason.
 *   - The class advertises itself as immutable in the original comment yet ships setters
 *     and stores the caller's List by reference. Real immutability would mean final
 *     fields, no setters, and List.copyOf(errors) in the constructor.
 *   - The imported java.time.LocalDateTime is unused. A production error contract almost
 *     always carries a timestamp; this one declares the import and then forgets the field.
 *   - Interview angle: this is a hand-rolled version of RFC 7807 / Spring's ProblemDetail.
 *     Knowing that Spring 6 ships ProblemDetail out of the box is the expected follow-up.
 */
package com.target.orders.exception.exceptions;

import lombok.Getter;
import lombok.Setter;

import java.time.LocalDateTime;
import java.util.List;

@Getter
@Setter
public class ErrorResponse {
    private int status;
    private String message;
    private List<String> errors;
    private String path;

    public ErrorResponse(int status, String message, List<String> errors, String path) {
        this.status = status;
        this.message = message;
        this.errors = errors;
        this.path = path;
    }

    public static void main(String[] args) {
        // Build a concrete example input
        int status = 404;
        String message = "Resource not found";
        java.util.List<String> errors = java.util.List.of("Missing ID", "Invalid format");
        String path = "/api/orders/123";

        // Create the ErrorResponse instance using the exposed constructor
        com.target.orders.exception.exceptions.ErrorResponse errorResponse =
                new com.target.orders.exception.exceptions.ErrorResponse(
                        status, message, errors, path);

        // Print both input and output with labels
        System.out.println("Input:");
        System.out.println("  status: " + status);
        System.out.println("  message: " + message);
        System.out.println("  errors: " + errors);
        System.out.println("  path: " + path);

        System.out.println("\nOutput (ErrorResponse):");
        System.out.println("  status: " + errorResponse.getStatus());
        System.out.println("  message: " + errorResponse.getMessage());
        System.out.println("  errors: " + errorResponse.getErrors());
        System.out.println("  path: " + errorResponse.getPath());
    }
}

/*
 * =====================================================================
 *  GlobalExceptionHandler -- one place for every failure   Spring Boot: orders service
 * =====================================================================
 *
 * ROLE IN THE PROJECT
 *   This is the single translation layer between "something went wrong somewhere in the
 *   app" and "an HTTP response the client can read". Controllers stay free of try/catch:
 *   they throw, and @ControllerAdvice catches the throw anywhere in the dispatch chain
 *   and converts it into an ErrorResponse body plus the right status code.
 *
 *   Three failures are mapped, from most specific to least:
 *     MethodArgumentNotValidException -> 400, with one "field : message" line per
 *        violation. Raised by Spring when @Valid rejects an incoming @RequestBody.
 *     OrderNotFoundException          -> 404, thrown by OrderController.getOrder.
 *     Exception                       -> 500, the catch-all so nothing escapes as a
 *        raw Spring whitelabel page.
 *
 *   Extending ResponseEntityExceptionHandler is what gives the class the ready-made
 *   hooks for Spring MVC's own exceptions; the class only overrides the one it cares
 *   about and inherits sensible defaults for the rest.
 *
 * WHAT TO NOTICE
 *   - handleMethodArgumentNotValid has no @Override annotation. It does still override
 *     the parent method, but only because the four-parameter signature happens to match
 *     Spring 6's exactly (note HttpStatusCode, not HttpStatus -- that type changed in
 *     Spring 6 and is a classic upgrade break). Drop the annotation and a one-character
 *     signature drift silently turns an override into a dead private-looking method.
 *   - Two ways of getting the path appear in the same class: WebRequest.getDescription
 *     (false) with "uri=" stripped off by hand for the inherited hook, and
 *     HttpServletRequest.getRequestURI() for the @ExceptionHandler methods. The string
 *     surgery is the ugly one, and it exists only because the parent hook hands you a
 *     WebRequest rather than the servlet request.
 *   - The 500 branch puts exception.getMessage() straight into the response body and,
 *     unlike the other two, logs nothing. That is backwards on both counts: internal
 *     messages leak to the caller and the operator gets no trace.
 *   - Specificity wins, not declaration order. @ExceptionHandler(Exception.class) does
 *     not swallow OrderNotFoundException; Spring picks the closest supertype match.
 *   - Return types are ResponseEntity<?>, which tells a reader nothing. ResponseEntity
 *     <ErrorResponse> documents the contract and is what a reviewer will ask for.
 *   - @Slf4j is Lombok generating the private static final Logger field named "log".
 */
package com.target.orders.exception.handler;

import com.target.orders.exception.exceptions.ErrorResponse;
import com.target.orders.exception.exceptions.OrderNotFoundException;
import jakarta.servlet.http.HttpServletRequest;
import lombok.extern.slf4j.Slf4j;

import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

import java.util.List;

@ControllerAdvice
@Slf4j
public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {


    protected ResponseEntity<Object> handleMethodArgumentNotValid(
            MethodArgumentNotValidException exception,
            HttpHeaders headers,
            HttpStatusCode statusCode,
            WebRequest request) {

        List<String> validationErrors = exception.getBindingResult()
                .getFieldErrors()
                .stream()
                .map(fieldError -> fieldError.getField() + " : " + fieldError.getDefaultMessage())
                .toList();
        String path = request.getDescription(false).replace("uri=", "");

        ErrorResponse errorResponse = new ErrorResponse(HttpStatus.BAD_REQUEST.value(),
                "Validation failed",
                validationErrors,
                path);
        log.error("Validation failed at {} -> {}", path, validationErrors);
        return new ResponseEntity<>(errorResponse, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(OrderNotFoundException.class)
    public ResponseEntity<?> handleOrderNotFoundException(OrderNotFoundException ex,
                                                          HttpServletRequest request) {
        String path = request.getRequestURI();

        ErrorResponse errorResponse = new ErrorResponse(HttpStatus.NOT_FOUND.value(),
                ex.getMessage(),
                List.of(),
                path);

        log.error("Resource not found at {} -> {}", path, ex.getMessage());

        return new ResponseEntity<>(errorResponse, HttpStatus.NOT_FOUND);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<?> handleServerError(Exception exception, HttpServletRequest request) {
        String path = request.getRequestURI();
        ErrorResponse errorResponse = new ErrorResponse(HttpStatus.INTERNAL_SERVER_ERROR.value(),
                exception.getMessage(), List.of(), path);

        return new ResponseEntity<>(errorResponse, HttpStatus.INTERNAL_SERVER_ERROR);
    }
}

/*
 * =====================================================================
 *  OrderController -- the REST entry point         Spring Boot: orders service
 * =====================================================================
 *
 * ROLE IN THE PROJECT
 *   The only class in this project a client ever talks to. It exposes two endpoints
 *   under /v1/api/orders and owns the (in-memory) store that backs them:
 *
 *     POST /v1/api/orders        body = OrderDTO   -> 200 with the saved order
 *     GET  /v1/api/orders/{id}                     -> 200 with the order, or 404
 *
 *   It is deliberately thin. There is no service layer and no repository: the map is
 *   the database. That keeps the file about the web layer -- routing, binding,
 *   validation, status codes -- which is what the rest of the project demonstrates.
 *
 *   How the three annotations split the work:
 *     @RestController  = @Controller + @ResponseBody, so returns are serialised to JSON.
 *     @RequestMapping  puts the shared /v1/api/orders prefix on every method.
 *     @Valid on the body triggers Bean Validation against OrderDTO's constraints; a
 *        violation becomes MethodArgumentNotValidException, which GlobalExceptionHandler
 *        turns into a 400. The controller never checks a field itself.
 *
 *   The 404 path is the same idea: getOrder throws OrderNotFoundException and lets the
 *   advice decide the status. No error handling lives here.
 *
 * WHAT TO NOTICE
 *   - The store is a static HashMap. Static means it is shared by every request and
 *     survives between tests; HashMap means it is not thread-safe, so two concurrent
 *     POSTs can corrupt it. ConcurrentHashMap (non-static, injected) is the fix, and
 *     "why is that map static" is a near-certain interview question.
 *   - @Validated on the class and @Valid on the parameter are different things. @Valid
 *     (Jakarta) cascades validation into the request body; @Validated (Spring) enables
 *     validation groups and method-level constraints on @PathVariable/@RequestParam.
 *     Here @Validated does nothing useful, because no parameter carries a constraint.
 *   - The optional @RequestParam "val" is declared and never read. Dead surface area on
 *     a public API is worse than dead code -- callers may start sending it.
 *   - Optional.ofNullable(map.get(id)).orElseThrow(...) is the idiomatic shape, but the
 *     intermediate orderDTO variable makes it read twice. One chained call is clearer.
 *   - saveOrder overwrites silently on a duplicate id and returns 200. A create should
 *     return 201 with a Location header, or 409 when the id already exists.
 *   - ResponseEntity<?> hides the payload type; ResponseEntity<OrderDTO> documents it.
 */
package com.target.orders.controller;

import com.target.orders.dto.OrderDTO;
import com.target.orders.exception.exceptions.OrderNotFoundException;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

@RestController
@Validated
@RequestMapping("/v1/api/orders")
public class OrderController {

    private static final Map<Integer, OrderDTO> map = new HashMap<>();

    @PostMapping
    public ResponseEntity<?> saveOrder(@Valid @RequestBody OrderDTO order) {
        map.put(order.getId(), order);
        return ResponseEntity.ok(order);
    }

    @GetMapping(value = "/{id}")
    public ResponseEntity<?> getOrder(@PathVariable Integer id,
                                      @RequestParam(required = false) String val) {
        OrderDTO orderDTO = map.get(id);

        OrderDTO dto = Optional.ofNullable(orderDTO).orElseThrow(() ->
                new OrderNotFoundException("order not found with id " + id));

        return ResponseEntity.ok(dto);
    }

    public static void main(String[] args) {
        // Create controller instance
        OrderController controller = new OrderController();

        // Build a simple OrderDTO (assuming it has a no-arg constructor and setId)
        com.target.orders.dto.OrderDTO order = new com.target.orders.dto.OrderDTO();
        order.setId(1);
        order.setCustomerName("Sample order");

        // Call the primary method to save the order
        ResponseEntity<?> saveResponse = controller.saveOrder(order);

        // Retrieve the same order by id
        ResponseEntity<?> getResponse = controller.getOrder(1, null);

        // Print input and outputs
        System.out.println("Input OrderDTO: " + order);
        System.out.println("Save response body: " + saveResponse.getBody());
        System.out.println("Get response body: " + getResponse.getBody());
    }
}

/*
 * =====================================================================
 *  OrderControllerTest -- MockMvc slice of the API   Spring Boot: orders service
 * =====================================================================
 *
 * ROLE IN THE PROJECT
 *   The only test in the project. It proves the two endpoints behave as advertised
 *   without ever opening a real socket: MockMvc drives Spring's DispatcherServlet
 *   directly, so routing, JSON binding, validation and @ControllerAdvice all run,
 *   but no Tomcat connector is started and no port is bound.
 *
 *   Two cases:
 *     saveOrder() -- POST a full OrderDTO, read the response body back into an
 *        OrderDTO, and assert all four fields survived the round trip. This is really
 *        a serialisation test: it catches a renamed JSON property or a missing getter.
 *     getOrder()  -- GET an id that was never stored and assert a 4xx. That is the
 *        OrderNotFoundException -> GlobalExceptionHandler -> 404 path, end to end.
 *
 *   @SpringBootTest boots the whole application context; @AutoConfigureMockMvc adds the
 *   configured MockMvc bean to it. Together they give a full-context test with a fake
 *   transport, which is the middle ground between a plain unit test and a live server.
 *
 * WHAT TO NOTICE
 *   - The two tests share OrderController's static map, so they are coupled through
 *     global state. getOrder() passes only because nothing ever stores id 2. Change
 *     saveOrder() to use id 2 and the other test fails for reasons unrelated to itself.
 *     JUnit 5 gives no order guarantee, so this is a latent flake, not a safe shortcut.
 *   - getOrder() captures contentAsString and never asserts on it. Either assert the
 *     ErrorResponse body (status, message, path) or drop the variable -- an unused
 *     capture reads like a forgotten assertion.
 *   - is4xxClientError() is weaker than the code deserves. The handler promises exactly
 *     404; isNotFound() would catch a regression that turned it into a 400.
 *   - ObjectMapper is built by hand instead of being @Autowired. The injected one is the
 *     Boot-configured instance (modules, naming strategy, date format), so a hand-rolled
 *     mapper can serialise differently from the server it is testing.
 *   - There is no test for the 400 validation path, which is the most interesting branch
 *     in the whole project: POST a body with a blank customerName or a negative amount
 *     and assert the per-field "customerName : ..." line comes back.
 *   - @SpringBootTest is heavy. @WebMvcTest(OrderController.class) loads only the web
 *     layer and is the right slice when there is nothing below the controller to wire.
 *   - The ErrorResponse import is unused; nothing here deserialises the error body.
 */
package com.target.orders.controller;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.target.orders.dto.OrderDTO;
import com.target.orders.exception.exceptions.ErrorResponse;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;
import org.springframework.test.web.servlet.result.MockMvcResultMatchers;

import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
@AutoConfigureMockMvc
class OrderControllerTest {

    @Autowired
    MockMvc mockMvc;

    ObjectMapper mapper = new ObjectMapper();

    @Test
    void saveOrder() throws Exception {
        OrderDTO dto = new OrderDTO();
        dto.setId(1);
        dto.setAmount(250.5);
        dto.setCustomerName("Ravi");
        dto.setDiscount(0.1);

        String content = mockMvc.perform(
                        MockMvcRequestBuilders
                                .post("/v1/api/orders")
                                .content(mapper.writeValueAsString(dto))
                                .accept(MediaType.APPLICATION_JSON)
                                .contentType(MediaType.APPLICATION_JSON)
                )
                .andReturn()
                .getResponse()
                .getContentAsString();

        OrderDTO orderDTO = mapper.readValue(content, OrderDTO.class);

        assertEquals(1, orderDTO.getId());
        assertEquals(250.5, orderDTO.getAmount());
        assertEquals(0.1, orderDTO.getDiscount());
        assertEquals("Ravi", orderDTO.getCustomerName());
    }

    @Test
    void getOrder() throws Exception {

        String contentAsString = mockMvc.perform(
                        MockMvcRequestBuilders
                                .get("/v1/api/orders/2")
                                .accept(MediaType.APPLICATION_JSON)
                                .contentType(MediaType.APPLICATION_JSON)
                )
                .andExpect(MockMvcResultMatchers.status().is4xxClientError())
                .andReturn()
                .getResponse()
                .getContentAsString();

    }

    public static void main(String[] args) throws Exception {
        // Build a small concrete example input
        com.target.orders.dto.OrderDTO dto = new com.target.orders.dto.OrderDTO();
        dto.setId(1);
        dto.setAmount(250.5);
        dto.setCustomerName("Ravi");
        dto.setDiscount(0.1);

        // Convert to JSON string using ObjectMapper
        com.fasterxml.jackson.databind.ObjectMapper mapper =
                new com.fasterxml.jackson.databind.ObjectMapper();
        String jsonInput = mapper.writeValueAsString(dto);

        // Print the input with a label
        System.out.println("Input OrderDTO as JSON:");
        System.out.println(jsonInput);
        System.out.println();

        // Simulate the controller's saveOrder behavior by converting back to DTO
        com.target.orders.dto.OrderDTO outputDto =
                mapper.readValue(jsonInput, com.target.orders.dto.OrderDTO.class);

        // Print the output with a label
